-- ============================================================================
-- StayQR v1.0 — Day 18 Canonical Schema Baseline REV1
-- Version: 202608060060
-- Purpose: bootstrap a completely empty development/staging database from the
--          accepted Day 18 production schema snapshot.
-- Source schema SHA-256: 553a964549977d07915044852b718d4caa2251cf9c6a8267e712457dc1f7044e
-- Source public tables: 134
-- Source private tables: 11
--
-- SAFETY CONTRACT
-- - This migration intentionally refuses to run when public tables or views
--   already exist. It must never execute against the existing StayQR production
--   database. Production adoption is history-only after fingerprint validation.
-- - No production row data, auth users, database password, API key, or storage
--   object byte is included.
-- - Historical Day 1–18 migration files remain preserved under
--   docs/database/legacy-migrations/pre-day18-canonical-baseline/.
-- ============================================================================

BEGIN;

DO $stayqr_day18_empty_target_guard$
DECLARE
  v_public_tables bigint;
  v_public_views bigint;
BEGIN
  SELECT count(*)
  INTO v_public_tables
  FROM pg_catalog.pg_tables
  WHERE schemaname = 'public';

  SELECT count(*)
  INTO v_public_views
  FROM pg_catalog.pg_views
  WHERE schemaname = 'public';

  IF v_public_tables <> 0 OR v_public_views <> 0 THEN
    RAISE EXCEPTION
      'StayQR canonical baseline refused: target is not empty (public tables %, public views %).',
      v_public_tables,
      v_public_views;
  END IF;
END
$stayqr_day18_empty_target_guard$;




SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "private";


ALTER SCHEMA "private" OWNER TO "postgres";


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "btree_gist" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






CREATE OR REPLACE FUNCTION "private"."assert_reservation_write_access"("target_hotel_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_hotel_role(
    target_hotel_id,
    array[
      'owner',
      'manager',
      'reception',
      'front_desk',
      'frontdesk'
    ]
  ) then
    raise exception 'Reservation write access denied.';
  end if;
end;
$$;


ALTER FUNCTION "private"."assert_reservation_write_access"("target_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_subscription_capacity_internal_20260728"("target_hotel_id" "uuid", "target_plan_id" "uuid" DEFAULT NULL::"uuid", "additional_rooms" integer DEFAULT 0, "additional_staff" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  plan_row public.subscription_plans%rowtype;
  subscription_row public.hotel_subscriptions%rowtype;
  room_count_value bigint := 0;
  staff_count_value bigint := 0;
begin
  if target_hotel_id is null then
    raise exception 'Hotel is required.';
  end if;

  if coalesce(additional_rooms, 0) < 0
     or coalesce(additional_staff, 0) < 0
  then
    raise exception
      'Additional capacity values cannot be negative.';
  end if;

  if target_plan_id is null then
    select hs.*
    into subscription_row
    from public.hotel_subscriptions hs
    where hs.hotel_id = target_hotel_id
      and hs.status in (
        'trial',
        'trialing',
        'active',
        'past_due',
        'suspended'
      )
    order by
      coalesce(hs.updated_at, hs.created_at) desc,
      hs.created_at desc,
      hs.id desc
    limit 1;

    if not found then
      raise exception
        'This hotel has no current subscription.';
    end if;

    if subscription_row.status = 'suspended' then
      raise exception
        'The hotel subscription is suspended.';
    end if;

    target_plan_id := subscription_row.plan_id;
  end if;

  select sp.*
  into plan_row
  from public.subscription_plans sp
  where sp.id = target_plan_id
    and sp.status = 'active';

  if not found then
    raise exception
      'The selected subscription plan is not active.';
  end if;

  select count(*)
  into room_count_value
  from public.rooms r
  where r.hotel_id = target_hotel_id;

  select count(*)
  into staff_count_value
  from public.staff s
  where s.hotel_id = target_hotel_id
    and s.status = 'active';

  if plan_row.max_rooms is not null
     and room_count_value + coalesce(additional_rooms, 0)
       > plan_row.max_rooms
  then
    raise exception
      'Room limit exceeded: current %, additional %, limit %.',
      room_count_value,
      coalesce(additional_rooms, 0),
      plan_row.max_rooms;
  end if;

  if plan_row.max_staff is not null
     and staff_count_value + coalesce(additional_staff, 0)
       > plan_row.max_staff
  then
    raise exception
      'Staff limit exceeded: current %, additional %, limit %.',
      staff_count_value,
      coalesce(additional_staff, 0),
      plan_row.max_staff;
  end if;

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'plan_id', plan_row.id,
    'plan_code', plan_row.plan_code,
    'rooms', room_count_value,
    'room_limit', plan_row.max_rooms,
    'additional_rooms', coalesce(additional_rooms, 0),
    'active_staff', staff_count_value,
    'staff_limit', plan_row.max_staff,
    'additional_staff', coalesce(additional_staff, 0),
    'allowed', true
  );
end;
$$;


ALTER FUNCTION "private"."assert_subscription_capacity_internal_20260728"("target_hotel_id" "uuid", "target_plan_id" "uuid", "additional_rooms" integer, "additional_staff" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."build_reservation_json"("target_hotel_id" "uuid", "target_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', r.id,
    'hotel_id', r.hotel_id,
    'reservation_number', r.reservation_number,
    'status', r.status,
    'booking_source', r.booking_source,
    'source_reference', r.source_reference,
    'arrival_date', r.arrival_date,
    'departure_date', r.departure_date,
    'expected_checkin_time', r.expected_checkin_time,
    'expected_checkout_time', r.expected_checkout_time,
    'adults', r.adults,
    'children', r.children,
    'currency_code', r.currency_code,
    'room_subtotal', r.room_subtotal,
    'tax_amount', r.tax_amount,
    'discount_amount', r.discount_amount,
    'total_amount', r.total_amount,
    'deposit_required', r.deposit_required,
    'deposit_collected', r.deposit_collected,
    'deposit_balance',
      greatest(r.deposit_required - r.deposit_collected, 0),
    'special_requests', r.special_requests,
    'internal_notes', r.internal_notes,
    'cancellation_reason', r.cancellation_reason,
    'cancelled_at', r.cancelled_at,
    'no_show_at', r.no_show_at,
    'created_by', r.created_by,
    'updated_by', r.updated_by,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'guest', (
      select jsonb_build_object(
        'id', g.id,
        'full_name', g.full_name,
        'phone', g.phone,
        'email', g.email,
        'id_type', g.id_type,
        'id_number', g.id_number,
        'preferred_language', g.preferred_language,
        'created_at', g.created_at
      )
      from public.guests g
      where g.id = r.primary_guest_id
        and g.hotel_id = r.hotel_id
    ),
    'rooms', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', rr.id,
            'room_type_id', rr.room_type_id,
            'room_type_name', rt.name,
            'room_id', rr.room_id,
            'room_number', room.room_number,
            'rate_plan_id', rr.rate_plan_id,
            'rate_plan_name', rp.name,
            'status', rr.status,
            'adults', rr.adults,
            'children', rr.children,
            'nightly_rate', rr.nightly_rate,
            'room_subtotal', rr.room_subtotal,
            'tax_amount', rr.tax_amount,
            'discount_amount', rr.discount_amount,
            'total_amount', rr.total_amount,
            'notes', rr.notes
          )
          order by rr.created_at
        ),
        '[]'::jsonb
      )
      from public.reservation_rooms rr
      join public.room_types rt
        on rt.id = rr.room_type_id
       and rt.hotel_id = rr.hotel_id
      left join public.rooms room
        on room.id = rr.room_id
       and room.hotel_id = rr.hotel_id
      left join public.rate_plans rp
        on rp.id = rr.rate_plan_id
       and rp.hotel_id = rr.hotel_id
      where rr.hotel_id = r.hotel_id
        and rr.reservation_id = r.id
    ),
    'payments', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', payment.id,
            'amount', payment.amount,
            'payment_method', payment.payment_method,
            'payment_status', payment.payment_status,
            'transaction_reference',
              payment.transaction_reference,
            'notes', payment.notes,
            'collected_by', payment.collected_by,
            'collected_at', payment.collected_at
          )
          order by payment.collected_at desc
        ),
        '[]'::jsonb
      )
      from public.reservation_payments payment
      where payment.hotel_id = r.hotel_id
        and payment.reservation_id = r.id
    ),
    'status_history', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', history.id,
            'old_status', history.old_status,
            'new_status', history.new_status,
            'reason', history.reason,
            'changed_by', history.changed_by,
            'metadata', history.metadata,
            'created_at', history.created_at
          )
          order by history.created_at desc
        ),
        '[]'::jsonb
      )
      from public.reservation_status_history history
      where history.hotel_id = r.hotel_id
        and history.reservation_id = r.id
    )
  )
  from public.reservations r
  where r.hotel_id = target_hotel_id
    and r.id = target_reservation_id;
$$;


ALTER FUNCTION "private"."build_reservation_json"("target_hotel_id" "uuid", "target_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."build_room_block_json"("target_hotel_id" "uuid", "target_room_block_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', block.id,
    'hotel_id', block.hotel_id,
    'room_id', block.room_id,
    'room_number', room.room_number,
    'room_type_id', room.room_type_id,
    'room_type_name', room_type.name,
    'block_type', block.block_type,
    'status', block.status,
    'start_date', block.start_date,
    'end_date', block.end_date,
    'reason', block.reason,
    'notes', block.notes,
    'release_reason', block.release_reason,
    'created_by', block.created_by,
    'created_by_name', private.resolve_calendar_actor_name(
      block.created_by,
      block.hotel_id
    ),
    'updated_by', block.updated_by,
    'updated_by_name', private.resolve_calendar_actor_name(
      block.updated_by,
      block.hotel_id
    ),
    'released_at', block.released_at,
    'released_by', block.released_by,
    'released_by_name', private.resolve_calendar_actor_name(
      block.released_by,
      block.hotel_id
    ),
    'created_at', block.created_at,
    'updated_at', block.updated_at
  )
  from public.room_blocks block
  join public.rooms room
    on room.id = block.room_id
   and room.hotel_id = block.hotel_id
  join public.room_types room_type
    on room_type.id = room.room_type_id
   and room_type.hotel_id = room.hotel_id
  where block.hotel_id = target_hotel_id
    and block.id = target_room_block_id;
$$;


ALTER FUNCTION "private"."build_room_block_json"("target_hotel_id" "uuid", "target_room_block_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."calendar_room_is_available"("target_hotel_id" "uuid", "target_room_id" "uuid", "target_start_date" "date", "target_end_date" "date", "exclude_reservation_room_id" "uuid" DEFAULT NULL::"uuid", "exclude_room_block_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select target_hotel_id is not null and target_room_id is not null
    and target_start_date is not null and target_end_date is not null and target_end_date>target_start_date
    and exists(
      select 1 from public.rooms r
      join public.floors f on f.hotel_id=r.hotel_id and f.id=r.floor_id and f.is_active
      join public.room_types t on t.hotel_id=r.hotel_id and t.id=r.room_type_id and t.is_active
      where r.hotel_id=target_hotel_id and r.id=target_room_id and r.is_active
        and r.status not in ('maintenance','out_of_order')
    )
    and not exists(
      select 1 from public.room_inventory_allocations a
      where a.hotel_id=target_hotel_id and a.room_id=target_room_id and a.status='active'
        and a.stay_dates&&daterange(target_start_date,target_end_date,'[)')
        and (exclude_reservation_room_id is null or a.reservation_room_id is distinct from exclude_reservation_room_id)
        and (exclude_room_block_id is null or a.room_block_id is distinct from exclude_room_block_id)
    );
$$;


ALTER FUNCTION "private"."calendar_room_is_available"("target_hotel_id" "uuid", "target_room_id" "uuid", "target_start_date" "date", "target_end_date" "date", "exclude_reservation_room_id" "uuid", "exclude_room_block_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."cleanup_day5_checkout_smoke_20260724"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_state jsonb;
  v_target_hotel uuid;
  v_reservation_id uuid;
  v_reservation_room_id uuid;
  v_room_id uuid;
  v_guest_id uuid;
  v_rate_plan_id uuid;
  v_temporary_rate_plan_created boolean;
  v_target_sequence_year integer;
  v_sequence_existed boolean;
  v_sequence_before bigint;
  deleted_checkout_events integer := 0;
  deleted_invoice_items integer := 0;
  deleted_collections integer := 0;
  deleted_transfers integer := 0;
  deleted_checkin_events integer := 0;
  deleted_invoices integer := 0;
  deleted_payments integer := 0;
  deleted_tasks integer := 0;
  deleted_sessions integer := 0;
  deleted_allocations integer := 0;
  deleted_reservations integer := 0;
  deleted_guests integer := 0;
  deleted_rooms integer := 0;
  deleted_rate_plans integer := 0;
begin
  select s.payload into v_state
  from private.day5_checkout_smoke_state_20260724 s
  where s.singleton
  for update;

  if v_state is null then
    raise exception 'Day 5 checkout smoke state is missing or already cleaned.';
  end if;

  v_target_hotel := (v_state->>'hotel_id')::uuid;
  v_reservation_id := (v_state->>'reservation_id')::uuid;
  v_reservation_room_id := (v_state->>'reservation_room_id')::uuid;
  v_room_id := (v_state->>'room_id')::uuid;
  v_guest_id := (v_state->>'guest_id')::uuid;
  v_rate_plan_id := (v_state->>'rate_plan_id')::uuid;
  v_temporary_rate_plan_created := coalesce((v_state->>'temporary_rate_plan_created')::boolean, false);
  v_target_sequence_year := (v_state->>'sequence_year')::integer;
  v_sequence_existed := coalesce((v_state->>'sequence_existed')::boolean, false);
  v_sequence_before := nullif(v_state->>'sequence_before', '')::bigint;

  delete from public.reservation_checkout_events event
  where event.hotel_id = v_target_hotel
    and event.reservation_id = v_reservation_id;
  get diagnostics deleted_checkout_events = row_count;

  delete from public.invoice_items item
  using public.invoices inv
  where item.invoice_id = inv.id
    and inv.hotel_id = v_target_hotel
    and inv.guest_id = v_guest_id
    and inv.room_id = v_room_id;
  get diagnostics deleted_invoice_items = row_count;

  delete from public.reservation_payment_transfers transfer
  where transfer.hotel_id = v_target_hotel
    and transfer.reservation_id = v_reservation_id;
  get diagnostics deleted_transfers = row_count;

  delete from public.payment_collections collection
  where collection.hotel_id = v_target_hotel
    and collection.reservation_id = v_reservation_id;
  get diagnostics deleted_collections = row_count;

  delete from public.reservation_checkin_events event
  where event.hotel_id = v_target_hotel
    and event.reservation_id = v_reservation_id;
  get diagnostics deleted_checkin_events = row_count;

  delete from public.invoices inv
  where inv.hotel_id = v_target_hotel
    and inv.guest_id = v_guest_id
    and inv.room_id = v_room_id;
  get diagnostics deleted_invoices = row_count;

  delete from public.payments payment
  where payment.hotel_id = v_target_hotel
    and payment.reservation_id = v_reservation_id;
  get diagnostics deleted_payments = row_count;

  delete from public.housekeeping_tasks task
  where task.hotel_id = v_target_hotel
    and task.room_id = v_room_id;
  get diagnostics deleted_tasks = row_count;

  delete from public.guest_sessions session
  where session.hotel_id = v_target_hotel
    and session.reservation_id = v_reservation_id;
  get diagnostics deleted_sessions = row_count;

  delete from public.room_inventory_allocations allocation
  where allocation.hotel_id = v_target_hotel
    and allocation.reservation_room_id = v_reservation_room_id;
  get diagnostics deleted_allocations = row_count;

  delete from public.activity_logs log
  where log.hotel_id = v_target_hotel
    and log.entity_type = 'reservation'
    and log.entity_id = v_reservation_id;

  delete from public.reservations reservation
  where reservation.hotel_id = v_target_hotel
    and reservation.id = v_reservation_id;
  get diagnostics deleted_reservations = row_count;

  delete from public.guests guest
  where guest.hotel_id = v_target_hotel
    and guest.id = v_guest_id;
  get diagnostics deleted_guests = row_count;

  delete from public.rooms room
  where room.hotel_id = v_target_hotel
    and room.id = v_room_id;
  get diagnostics deleted_rooms = row_count;

  if v_temporary_rate_plan_created then
    delete from public.rate_plans rate_plan
    where rate_plan.hotel_id = v_target_hotel
      and rate_plan.id = v_rate_plan_id;
    get diagnostics deleted_rate_plans = row_count;
  end if;

  if v_sequence_existed then
    update public.reservation_number_sequences sequence
    set last_number = v_sequence_before
    where sequence.hotel_id = v_target_hotel
      and sequence.sequence_year = v_target_sequence_year;
  else
    delete from public.reservation_number_sequences sequence
    where sequence.hotel_id = v_target_hotel
      and sequence.sequence_year = v_target_sequence_year;
  end if;

  delete from private.day5_checkout_smoke_state_20260724;

  return jsonb_build_object(
    'result', 'DAY 5 BOOKING-TO-CHECKOUT SMOKE DATA CLEANED',
    'deleted_checkout_events', deleted_checkout_events,
    'deleted_invoice_items', deleted_invoice_items,
    'deleted_collections', deleted_collections,
    'deleted_transfers', deleted_transfers,
    'deleted_checkin_events', deleted_checkin_events,
    'deleted_invoices', deleted_invoices,
    'deleted_payments', deleted_payments,
    'deleted_housekeeping_tasks', deleted_tasks,
    'deleted_sessions', deleted_sessions,
    'deleted_allocations', deleted_allocations,
    'deleted_reservations', deleted_reservations,
    'deleted_guests', deleted_guests,
    'deleted_rooms', deleted_rooms,
    'deleted_temporary_rate_plans', deleted_rate_plans
  );
end;
$$;


ALTER FUNCTION "private"."cleanup_day5_checkout_smoke_20260724"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."compute_hotel_onboarding_readiness"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  hotel_details_ready boolean := false;
  owner_ready boolean := false;
  settings_ready boolean := false;
  room_types_ready boolean := false;
  floors_ready boolean := false;
  rooms_ready boolean := false;
  rates_ready boolean := false;
  amenities_ready boolean := false;
  request_categories_ready boolean := false;
  menu_ready boolean := false;
  invoice_ready boolean := false;
  subscription_ready boolean := false;
  qr_ready boolean := false;
  all_ready boolean := false;
  missing_items text[];
begin
  if target_hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = target_hotel_id
     )
  then
    raise exception 'Unknown hotel.';
  end if;

  select
    nullif(trim(h.hotel_name), '') is not null
    and nullif(trim(h.slug), '') is not null
    and nullif(trim(h.timezone), '') is not null
    and h.currency_code ~ '^[A-Z]{3}$'
    and exists (
      select 1
      from public.hotel_info hi
      where hi.hotel_id = h.id
    )
  into hotel_details_ready
  from public.hotels h
  where h.id = target_hotel_id;

  select exists (
    select 1
    from public.staff s
    where s.hotel_id = target_hotel_id
      and s.status = 'active'
      and s.auth_user_id is not null
      and lower(replace(trim(s.role::text), ' ', '_')) = 'owner'
  )
  into owner_ready;

  select exists (
    select 1
    from public.hotel_settings hs
    where hs.hotel_id = target_hotel_id
  )
  into settings_ready;

  select exists (
    select 1
    from public.room_types rt
    where rt.hotel_id = target_hotel_id
      and rt.is_active
  )
  into room_types_ready;

  select exists (
    select 1
    from public.floors f
    where f.hotel_id = target_hotel_id
      and f.is_active
  )
  into floors_ready;

  select
    exists (
      select 1
      from public.rooms r
      where r.hotel_id = target_hotel_id
    )
    and not exists (
      select 1
      from public.rooms r
      where r.hotel_id = target_hotel_id
        and (r.room_type_id is null or r.floor_id is null)
    )
  into rooms_ready;

  select
    room_types_ready
    and not exists (
      select 1
      from public.room_types rt
      where rt.hotel_id = target_hotel_id
        and rt.is_active
        and not exists (
          select 1
          from public.rate_plans rp
          where rp.hotel_id = rt.hotel_id
            and rp.room_type_id = rt.id
            and rp.is_active
        )
    )
  into rates_ready;

  if to_regclass('public.amenities') is not null then
    execute
      'select exists (
         select 1
         from public.amenities a
         where a.hotel_id = $1
           and a.is_active
       )'
    into amenities_ready
    using target_hotel_id;
  end if;

  if to_regclass('public.service_request_types') is not null then
    execute
      'select exists (
         select 1
         from public.service_request_types srt
         where srt.hotel_id = $1
           and srt.is_active
       )'
    into request_categories_ready
    using target_hotel_id;
  end if;

  select
    exists (
      select 1
      from public.menu_categories mc
      where mc.hotel_id = target_hotel_id
    )
    and exists (
      select 1
      from public.menu_items mi
      where mi.hotel_id = target_hotel_id
    )
  into menu_ready;

  select exists (
    select 1
    from public.invoice_number_sequences ins
    where ins.hotel_id = target_hotel_id
      and ins.sequence_year = extract(year from now())::integer
  )
  into invoice_ready;

  select exists (
    select 1
    from public.hotel_subscriptions hsub
    where hsub.hotel_id = target_hotel_id
      and hsub.status in ('trial', 'trialing', 'active', 'past_due')
      and (
        hsub.end_date is null
        or hsub.end_date > now()
        or hsub.status = 'past_due'
      )
  )
  into subscription_ready;

  qr_ready :=
    rooms_ready
    and to_regclass('public.guest_access_tokens') is not null
    and to_regprocedure('public.get_guest_access_links(uuid)') is not null
    and to_regprocedure('public.resolve_guest_portal(text,text)') is not null;

  missing_items := array_remove(array[
    case when not hotel_details_ready then 'hotel_details' end,
    case when not owner_ready then 'owner_identity' end,
    case when not settings_ready then 'hotel_settings' end,
    case when not room_types_ready then 'room_types' end,
    case when not floors_ready then 'floors' end,
    case when not rooms_ready then 'rooms' end,
    case when not rates_ready then 'rates' end,
    case when not amenities_ready then 'amenities' end,
    case when not request_categories_ready then 'request_categories' end,
    case when not menu_ready then 'menu' end,
    case when not invoice_ready then 'invoice_numbering' end,
    case when not subscription_ready then 'subscription' end,
    case when not qr_ready then 'qr_readiness' end
  ], null);

  all_ready := coalesce(cardinality(missing_items), 0) = 0;

  return jsonb_build_object(
    'ready', all_ready,
    'checklist', jsonb_build_object(
      'hotel_details', hotel_details_ready,
      'owner_identity', owner_ready,
      'settings', settings_ready,
      'room_types', room_types_ready,
      'floors', floors_ready,
      'rooms', rooms_ready,
      'rates', rates_ready,
      'amenities', amenities_ready,
      'request_categories', request_categories_ready,
      'menu', menu_ready,
      'invoice', invoice_ready,
      'subscription', subscription_ready,
      'qr_ready', qr_ready
    ),
    'missing', to_jsonb(coalesce(missing_items, '{}'::text[])),
    'generated_at', now()
  );
end;
$_$;


