SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."folios" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "hotel_id" "uuid" NOT NULL,
    "folio_number" "text" NOT NULL,
    "guest_session_id" "uuid" NOT NULL,
    "reservation_id" "uuid",
    "reservation_room_id" "uuid",
    "guest_id" "uuid" NOT NULL,
    "room_id" "uuid",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "currency_code" "text" DEFAULT 'INR'::"text" NOT NULL,
    "charges_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "discount_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "tax_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "collection_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "refund_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "credit_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "balance_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "opened_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "opened_by" "uuid",
    "settled_at" timestamp with time zone,
    "settled_by" "uuid",
    "voided_at" timestamp with time zone,
    "voided_by" "uuid",
    "void_reason" "text",
    "lock_version" bigint DEFAULT 0 NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "folios_amounts_nonnegative" CHECK ((("charges_amount" >= (0)::numeric) AND ("discount_amount" >= (0)::numeric) AND ("tax_amount" >= (0)::numeric) AND ("collection_amount" >= (0)::numeric) AND ("refund_amount" >= (0)::numeric) AND ("credit_amount" >= (0)::numeric))),
    CONSTRAINT "folios_balance_equation_check" CHECK (("balance_amount" = ((((("charges_amount" - "discount_amount") + "tax_amount") - "collection_amount") + "refund_amount") - "credit_amount"))),
    CONSTRAINT "folios_balance_nonnegative_check" CHECK (("balance_amount" >= (0)::numeric)),
    CONSTRAINT "folios_currency_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "folios_settled_check" CHECK ((("status" <> 'settled'::"text") OR (("settled_at" IS NOT NULL) AND ("balance_amount" = (0)::numeric)))),
    CONSTRAINT "folios_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'settled'::"text", 'voided'::"text"]))),
    CONSTRAINT "folios_voided_check" CHECK ((("status" <> 'voided'::"text") OR (("voided_at" IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM "void_reason"), ''::"text") IS NOT NULL))))
);


