COMMENT ON TABLE "public"."folios" IS 'Day 11 authoritative stay folio header. Summary columns are maintained from posted folio items, collections and signed adjustments.';



CREATE OR REPLACE FUNCTION "private"."day11_ensure_folio_for_source"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "source_value" "text") RETURNS "public"."folios"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  folio_row public.folios%rowtype;
  stay_row public.guest_sessions%rowtype;
  hotel_row public.hotels%rowtype;
  generated_id uuid := gen_random_uuid();
begin
  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:day11-source-folio:'
      || target_hotel_id::text
      || ':'
      || target_guest_session_id::text,
      0
    )
  );

  select folio.*
  into folio_row
  from public.folios folio
  where folio.hotel_id = target_hotel_id
    and folio.guest_session_id = target_guest_session_id
  limit 1;

  if folio_row.id is not null then
    return folio_row;
  end if;

  select stay.*
  into stay_row
  from public.guest_sessions stay
  where stay.hotel_id = target_hotel_id
    and stay.id = target_guest_session_id
  for share;

  if not found then
    raise exception
      'Guest session % was not found for hotel %.',
      target_guest_session_id,
      target_hotel_id;
  end if;

  if stay_row.guest_id is null then
    raise exception
      'Guest session % has no guest.',
      target_guest_session_id;
  end if;

  select hotel.*
  into strict hotel_row
  from public.hotels hotel
  where hotel.id = target_hotel_id;

  insert into public.folios (
    id,
    hotel_id,
    folio_number,
    guest_session_id,
    reservation_id,
    reservation_room_id,
    guest_id,
    room_id,
    status,
    currency_code,
    opened_by,
    opened_at,
    metadata
  )
  values (
    generated_id,
    target_hotel_id,
    'FOL-'
      || to_char(
        coalesce(stay_row.checkin_time, now())
          at time zone coalesce(hotel_row.timezone, 'Asia/Kolkata'),
        'YYYYMMDD'
      )
      || '-'
      || upper(substr(replace(generated_id::text, '-', ''), 1, 8)),
    target_guest_session_id,
    stay_row.reservation_id,
    stay_row.reservation_room_id,
    stay_row.guest_id,
    stay_row.room_id,
    'open',
    coalesce(hotel_row.currency_code, 'INR'),
    auth.uid(),
    coalesce(stay_row.checkin_time, now()),
    jsonb_build_object(
      'source', coalesce(source_value, 'legacy_financial_sync'),
      'day', 11,
      'migration', '033',
      'legacy_backfill', true
    )
  )
  returning *
  into folio_row;

  perform private.write_folio_event(
    target_hotel_id,
    folio_row.id,
    'folio.opened',
    'guest_session',
    target_guest_session_id,
    to_jsonb(folio_row),
    jsonb_build_object(
      'source', coalesce(source_value, 'legacy_financial_sync'),
      'migration', '033'
    )
  );

  return folio_row;
end;
$$;


