CREATE OR REPLACE FUNCTION "private"."day11_normalize_payment_method"("payment_method_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when normalized in ('cash') then 'cash'
    when normalized in (
      'card',
      'credit_card',
      'debit_card',
      'creditcard',
      'debitcard'
    ) then 'card'
    when normalized in ('upi', 'gpay', 'google_pay', 'phonepe', 'paytm')
      then 'upi'
    when normalized in (
      'bank',
      'bank_transfer',
      'banktransfer',
      'net_banking',
      'netbanking',
      'neft',
      'rtgs',
      'imps'
    ) then 'bank_transfer'
    when normalized in (
      'payment_link',
      'paymentlink',
      'cashfree',
      'razorpay',
      'gateway',
      'online'
    ) then 'payment_link'
    else 'other'
  end
  from (
    select lower(
      regexp_replace(
        coalesce(trim(payment_method_value), ''),
        '[^a-zA-Z0-9]+',
        '_',
        'g'
      )
    ) as normalized
  ) source;
$$;


ALTER FUNCTION "private"."day11_normalize_payment_method"("payment_method_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day11_payment_charge_category"("payment_type_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when lower(coalesce(payment_type_value, '')) in (
      'room',
      'room_charge',
      'roomcharge'
    ) then 'room'
    when lower(coalesce(payment_type_value, '')) in (
      'food',
      'food_charge',
      'foodcharge'
    ) then 'food'
    when lower(coalesce(payment_type_value, '')) in (
      'service',
      'service_charge',
      'servicecharge'
    ) then 'service'
    when lower(coalesce(payment_type_value, '')) in (
      'manual',
      'manual_charge',
      'manualcharge'
    ) then 'manual'
    else 'other'
  end;
$$;


