CREATE OR REPLACE FUNCTION "private"."day11_post_service_request_charge"("target_request_id" "uuid", "force_manual" boolean DEFAULT false, "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_row public.service_requests%rowtype;
  type_row public.service_request_types%rowtype;
  mapping_value jsonb;
  candidate_count_value integer;
  mapped_session_id uuid;
  mapped_room_id uuid;
  folio_row public.folios%rowtype;
  existing_item public.folio_items%rowtype;
  item_id_value uuid;
  inserted_value boolean := false;
  amount_value numeric(14,2);
  description_value text;
begin
  select request.*
  into source_row
  from public.service_requests request
  where request.id = target_request_id;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'reason', 'source_not_found',
      'source_id', target_request_id
    );
  end if;

  if source_row.request_type_id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'service_type_missing',
      'source_id', source_row.id
    );
  end if;

  select request_type.*
  into type_row
  from public.service_request_types request_type
  where request_type.hotel_id = source_row.hotel_id
    and request_type.id = source_row.request_type_id;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'reason', 'service_type_not_found',
      'source_id', source_row.id
    );
  end if;

  if source_row.status <> 'completed' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'service_not_completed',
      'source_id', source_row.id
    );
  end if;

  if not type_row.charge_enabled then
    return jsonb_build_object(
      'ok', false,
      'reason', 'service_pricing_disabled',
      'source_id', source_row.id
    );
  end if;

  if type_row.default_charge_amount is null
     or type_row.default_charge_amount <= 0
  then
    return jsonb_build_object(
      'ok', false,
      'reason', 'service_amount_invalid',
      'source_id', source_row.id
    );
  end if;

  if
    type_row.charge_posting_policy = 'manual'
    and not force_manual
  then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'manual_post_required',
      'source_id', source_row.id
    );
  end if;

  mapping_value :=
    private.day11_resolve_financial_source_session(
      source_row.hotel_id,
      source_row.guest_id,
      source_row.room_id,
      source_row.created_at,
      false
    );

  candidate_count_value :=
    coalesce(
      (mapping_value ->> 'candidate_count')::integer,
      0
    );

  if candidate_count_value <> 1 then
    perform private.day11_record_source_exception(
      source_row.hotel_id,
      'service_requests',
      source_row.id,
      case
        when candidate_count_value > 1
          then 'source_ambiguous'
        else 'source_unmatched'
      end,
      candidate_count_value,
      source_row.guest_id,
      source_row.room_id,
      source_row.created_at,
      to_jsonb(source_row),
      mapping_value,
      jsonb_build_object(
        'service_charge_attempted', true,
        'request_id', request_id_value,
        'source_sync', 'migration_034'
      )
    );

    return jsonb_build_object(
      'ok', false,
      'reason', case
        when candidate_count_value > 1
          then 'source_ambiguous'
        else 'source_unmatched'
      end,
      'source_id', source_row.id,
      'mapping', mapping_value
    );
  end if;

  mapped_session_id :=
    (mapping_value ->> 'guest_session_id')::uuid;

  mapped_room_id :=
    (mapping_value ->> 'mapped_room_id')::uuid;

  amount_value := type_row.default_charge_amount;

  description_value := coalesce(
    nullif(trim(type_row.charge_description), ''),
    nullif(trim(type_row.name), ''),
    'Service charge'
  );

  folio_row := private.day11_ensure_folio_for_source(
    source_row.hotel_id,
    mapped_session_id,
    'service_request_charge'
  );

  select item.*
  into existing_item
  from public.folio_items item
  where item.hotel_id = source_row.hotel_id
    and item.source_table = 'service_requests'
    and item.source_id = source_row.id
  limit 1;

  if existing_item.id is null then
    insert into public.folio_items (
      hotel_id,
      folio_id,
      item_kind,
      charge_category,
      description,
      quantity,
      unit_amount,
      amount,
      source_table,
      source_id,
      service_at,
      posting_status,
      posted_at,
      posted_by,
      metadata
    )
    values (
      source_row.hotel_id,
      folio_row.id,
      'charge',
      'service',
      description_value,
      1,
      amount_value,
      amount_value,
      'service_requests',
      source_row.id,
      coalesce(
        source_row.completed_at,
        source_row.created_at
      ),
      'posted',
      now(),
      private.day11_valid_auth_actor(auth.uid()),
      jsonb_build_object(
        'request_type_id',
          source_row.request_type_id,
        'request_type_code',
          type_row.code,
        'request_type_name',
          type_row.name,
        'charge_posting_policy',
          type_row.charge_posting_policy,
        'charge_taxable',
          type_row.charge_taxable,
        'mapped_guest_session_id',
          mapped_session_id,
        'mapped_room_id',
          mapped_room_id,
        'request_id',
          request_id_value,
        'source_sync', 'migration_034'
      )
    )
    returning id
    into item_id_value;

    inserted_value := true;
  else
    update public.folio_items
    set
      folio_id = folio_row.id,
      item_kind = 'charge',
      charge_category = 'service',
      description = description_value,
      quantity = 1,
      unit_amount = amount_value,
      amount = amount_value,
      service_at = coalesce(
        source_row.completed_at,
        source_row.created_at
      ),
      posting_status = 'posted',
      voided_at = null,
      voided_by = null,
      void_reason = null,
      metadata = metadata || jsonb_build_object(
        'request_type_id',
          source_row.request_type_id,
        'request_type_code',
          type_row.code,
        'request_type_name',
          type_row.name,
        'charge_posting_policy',
          type_row.charge_posting_policy,
        'charge_taxable',
          type_row.charge_taxable,
        'mapped_guest_session_id',
          mapped_session_id,
        'mapped_room_id',
          mapped_room_id,
        'request_id',
          request_id_value,
        'source_sync', 'migration_034'
      )
    where hotel_id = source_row.hotel_id
      and id = existing_item.id
    returning id
    into item_id_value;

    if existing_item.folio_id <> folio_row.id then
      perform private.recalculate_folio(
        source_row.hotel_id,
        existing_item.folio_id
      );
    end if;
  end if;

  perform private.day11_resolve_source_exception(
    source_row.hotel_id,
    'service_requests',
    source_row.id,
    jsonb_build_object(
      'service_charge_posted', true,
      'request_id', request_id_value
    )
  );

  if inserted_value then
    perform private.write_folio_event(
      source_row.hotel_id,
      folio_row.id,
      'folio.item.posted',
      'service_request',
      source_row.id,
      jsonb_build_object(
        'folio_item_id', item_id_value,
        'amount', amount_value,
        'charge_category', 'service'
      ),
      jsonb_build_object(
        'request_id', request_id_value,
        'source_sync', 'migration_034'
      )
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'skipped', false,
    'idempotent', not inserted_value,
    'source_id', source_row.id,
    'folio_id', folio_row.id,
    'folio_item_id', item_id_value,
    'amount', amount_value,
    'request_id', request_id_value
  );
end;
$$;


ALTER FUNCTION "private"."day11_post_service_request_charge"("target_request_id" "uuid", "force_manual" boolean, "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day11_process_refund"("target_refund_id" "uuid", "provider_refund_id_value" "text", "transaction_reference_value" "text", "actor_id_value" "uuid", "system_processing" boolean, "metadata_value" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  refund_row public.refunds%rowtype;
begin
  select refund.* into refund_row
  from public.refunds refund where refund.id = target_refund_id for update;
  if not found then raise exception 'Refund was not found.'; end if;
  if refund_row.status = 'processed' then return jsonb_build_object('ok',true,'idempotent',true,'refund',to_jsonb(refund_row)); end if;
  if refund_row.status <> 'pending' then raise exception 'Only pending refund can be processed; current status %.',refund_row.status; end if;
  if not system_processing and private.day11_valid_auth_actor(actor_id_value) is null then
    raise exception 'Manual refund processing requires a valid actor.';
  end if;

  update public.refunds
  set status = 'processed',
      transaction_reference = coalesce(nullif(trim(transaction_reference_value),''),transaction_reference),
      provider_refund_id = coalesce(nullif(trim(provider_refund_id_value),''),provider_refund_id),
      processed_at = now(),
      processed_by = case when system_processing then null else private.day11_valid_auth_actor(actor_id_value) end,
      provider = coalesce(nullif(trim(metadata_value ->> 'provider'),''),provider),
      failure_reason = null,
      metadata = metadata || coalesce(metadata_value,'{}'::jsonb) || jsonb_build_object('processed_by_system',system_processing,'day',11)
  where id = target_refund_id
  returning * into refund_row;

  perform private.write_folio_event(refund_row.hotel_id,refund_row.folio_id,'folio.refund.processed','refund',refund_row.id,to_jsonb(refund_row),coalesce(metadata_value,'{}'::jsonb) || jsonb_build_object('system_processing',system_processing,'day',11));
  return jsonb_build_object('ok',true,'idempotent',false,'refund',to_jsonb(refund_row));
end;
$$;


ALTER FUNCTION "private"."day11_process_refund"("target_refund_id" "uuid", "provider_refund_id_value" "text", "transaction_reference_value" "text", "actor_id_value" "uuid", "system_processing" boolean, "metadata_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day11_record_source_exception"("target_hotel_id" "uuid", "source_table_value" "text", "source_id_value" "uuid", "exception_code_value" "text", "candidate_count_value" integer, "guest_id_value" "uuid", "room_id_value" "uuid", "source_at_value" timestamp with time zone, "source_snapshot_value" "jsonb", "mapping_snapshot_value" "jsonb", "metadata_value" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  exception_id_value uuid;
begin
  insert into public.folio_source_exceptions (
    hotel_id,
    source_table,
    source_id,
    exception_code,
    status,
    candidate_count,
    guest_id,
    room_id,
    source_at,
    source_snapshot,
    mapping_snapshot,
    metadata
  )
  values (
    target_hotel_id,
    source_table_value,
    source_id_value,
    exception_code_value,
    'open',
    greatest(coalesce(candidate_count_value, 0), 0),
    guest_id_value,
    room_id_value,
    source_at_value,
    coalesce(source_snapshot_value, '{}'::jsonb),
    coalesce(mapping_snapshot_value, '{}'::jsonb),
    coalesce(metadata_value, '{}'::jsonb)
  )
  on conflict (
    hotel_id,
    source_table,
    source_id
  )
  do update
  set
    exception_code = excluded.exception_code,
    status = 'open',
    candidate_count = excluded.candidate_count,
    guest_id = excluded.guest_id,
    room_id = excluded.room_id,
    source_at = excluded.source_at,
    source_snapshot = excluded.source_snapshot,
    mapping_snapshot = excluded.mapping_snapshot,
    metadata =
      public.folio_source_exceptions.metadata
      || excluded.metadata,
    last_seen_at = now(),
    resolved_at = null,
    resolved_by = null
  returning id
  into exception_id_value;

  return exception_id_value;
end;
$$;


ALTER FUNCTION "private"."day11_record_source_exception"("target_hotel_id" "uuid", "source_table_value" "text", "source_id_value" "uuid", "exception_code_value" "text", "candidate_count_value" integer, "guest_id_value" "uuid", "room_id_value" "uuid", "source_at_value" timestamp with time zone, "source_snapshot_value" "jsonb", "mapping_snapshot_value" "jsonb", "metadata_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day11_refresh_service_request_mapping"("target_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_row public.service_requests%rowtype;
  mapping_value jsonb;
  candidate_count_value integer;
begin
  select request.*
  into source_row
  from public.service_requests request
  where request.id = target_request_id;

  if not found then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'source_not_found',
      'source_id', target_request_id
    );
  end if;

  mapping_value :=
    private.day11_resolve_financial_source_session(
      source_row.hotel_id,
      source_row.guest_id,
      source_row.room_id,
      source_row.created_at,
      false
    );

  candidate_count_value :=
    coalesce(
      (mapping_value ->> 'candidate_count')::integer,
      0
    );

  if candidate_count_value = 1 then
    perform private.day11_resolve_source_exception(
      source_row.hotel_id,
      'service_requests',
      source_row.id,
      jsonb_build_object(
        'mapping_ready', true,
        'resolved_by_sync', 'migration_034'
      )
    );
  else
    perform private.day11_record_source_exception(
      source_row.hotel_id,
      'service_requests',
      source_row.id,
      case
        when candidate_count_value > 1
          then 'source_ambiguous'
        else 'source_unmatched'
      end,
      candidate_count_value,
      source_row.guest_id,
      source_row.room_id,
      source_row.created_at,
      to_jsonb(source_row),
      mapping_value,
      jsonb_build_object(
        'source_sync', 'migration_034',
        'charge_not_posted', true
      )
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'source_id', source_row.id,
    'mapping', mapping_value
  );
end;
$$;


ALTER FUNCTION "private"."day11_refresh_service_request_mapping"("target_request_id" "uuid") OWNER TO "postgres";


