CREATE OR REPLACE FUNCTION "private"."day11_sync_food_order"("target_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_row public.food_orders%rowtype;
  mapping_value jsonb;
  mapped_session_id uuid;
  mapped_room_id uuid;
  candidate_count_value integer;
  item_rows_value integer;
  calculated_amount_value numeric(14,2);
  item_snapshot_value jsonb;
  folio_row public.folios%rowtype;
  existing_item public.folio_items%rowtype;
  item_id_value uuid;
  inserted_value boolean := false;
  exception_code_value text;
begin
  select food_order.*
  into source_row
  from public.food_orders food_order
  where food_order.id = target_order_id;

  if not found then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'source_not_found',
      'source_id', target_order_id
    );
  end if;

  select
    count(*),
    coalesce(
      sum(
        coalesce(item.quantity, 0)
        * coalesce(item.price, 0)
      ),
      0
    ),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'food_order_item_id', item.id,
          'menu_item_id', item.menu_item_id,
          'quantity', item.quantity,
          'price', item.price,
          'line_amount',
            coalesce(item.quantity, 0)
            * coalesce(item.price, 0)
        )
        order by item.id
      ),
      '[]'::jsonb
    )
  into
    item_rows_value,
    calculated_amount_value,
    item_snapshot_value
  from public.food_order_items item
  where item.hotel_id = source_row.hotel_id
    and item.order_id = source_row.id;

  mapping_value :=
    private.day11_resolve_financial_source_session(
      source_row.hotel_id,
      source_row.guest_id,
      source_row.room_id,
      source_row.created_at,
      false
    );

  candidate_count_value :=
    coalesce(
      (mapping_value ->> 'candidate_count')::integer,
      0
    );

  mapped_session_id :=
    nullif(
      mapping_value ->> 'guest_session_id',
      ''
    )::uuid;

  mapped_room_id :=
    nullif(
      mapping_value ->> 'mapped_room_id',
      ''
    )::uuid;

  exception_code_value := case
    when lower(coalesce(source_row.order_status, '')) <> 'delivered'
      then 'source_not_final'
    when source_row.total_amount <= 0
      then 'source_amount_invalid'
    when item_rows_value = 0
      then 'food_items_missing'
    when source_row.total_amount <> calculated_amount_value
      then 'food_item_total_mismatch'
    when candidate_count_value > 1
      then 'source_ambiguous'
    when candidate_count_value = 0
      then 'source_unmatched'
    else null
  end;

  if exception_code_value is not null then
    perform private.day11_void_source_item(
      source_row.hotel_id,
      'food_orders',
      source_row.id,
      'Food order failed authoritative posting eligibility.'
    );

    perform private.day11_record_source_exception(
      source_row.hotel_id,
      'food_orders',
      source_row.id,
      exception_code_value,
      candidate_count_value,
      source_row.guest_id,
      source_row.room_id,
      source_row.created_at,
      to_jsonb(source_row)
        || jsonb_build_object(
          'item_rows', item_rows_value,
          'calculated_item_amount',
            calculated_amount_value,
          'items', item_snapshot_value
        ),
      mapping_value,
      jsonb_build_object(
        'source_sync', 'migration_034'
      )
    );

    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', exception_code_value,
      'source_id', source_row.id,
      'mapping', mapping_value
    );
  end if;

  folio_row := private.day11_ensure_folio_for_source(
    source_row.hotel_id,
    mapped_session_id,
    'legacy_food_order'
  );

  select item.*
  into existing_item
  from public.folio_items item
  where item.hotel_id = source_row.hotel_id
    and item.source_table = 'food_orders'
    and item.source_id = source_row.id
  limit 1;

  if existing_item.id is null then
    insert into public.folio_items (
      hotel_id,
      folio_id,
      item_kind,
      charge_category,
      description,
      quantity,
      unit_amount,
      amount,
      source_table,
      source_id,
      service_at,
      posting_status,
      posted_at,
      posted_by,
      metadata
    )
    values (
      source_row.hotel_id,
      folio_row.id,
      'charge',
      'food',
      'Food order '
        || upper(
          substr(
            replace(source_row.id::text, '-', ''),
            1,
            8
          )
        ),
      1,
      source_row.total_amount,
      source_row.total_amount,
      'food_orders',
      source_row.id,
      coalesce(
        source_row.delivered_at,
        source_row.created_at
      ),
      'posted',
      coalesce(
        source_row.delivered_at,
        source_row.created_at
      ),
      null,
      jsonb_build_object(
        'legacy_order_status',
          source_row.order_status,
        'legacy_payment_status',
          source_row.payment_status,
        'legacy_room_id',
          source_row.room_id,
        'mapped_guest_session_id',
          mapped_session_id,
        'mapped_room_id',
          mapped_room_id,
        'item_rows', item_rows_value,
        'calculated_item_amount',
          calculated_amount_value,
        'items', item_snapshot_value,
        'source_sync', 'migration_034'
      )
    )
    returning id
    into item_id_value;

    inserted_value := true;
  else
    update public.folio_items
    set
      folio_id = folio_row.id,
      item_kind = 'charge',
      charge_category = 'food',
      description =
        'Food order '
        || upper(
          substr(
            replace(source_row.id::text, '-', ''),
            1,
            8
          )
        ),
      quantity = 1,
      unit_amount = source_row.total_amount,
      amount = source_row.total_amount,
      service_at = coalesce(
        source_row.delivered_at,
        source_row.created_at
      ),
      posting_status = 'posted',
      voided_at = null,
      voided_by = null,
      void_reason = null,
      metadata = metadata || jsonb_build_object(
        'legacy_order_status',
          source_row.order_status,
        'legacy_payment_status',
          source_row.payment_status,
        'legacy_room_id',
          source_row.room_id,
        'mapped_guest_session_id',
          mapped_session_id,
        'mapped_room_id',
          mapped_room_id,
        'item_rows', item_rows_value,
        'calculated_item_amount',
          calculated_amount_value,
        'items', item_snapshot_value,
        'source_sync', 'migration_034'
      )
    where hotel_id = source_row.hotel_id
      and id = existing_item.id
    returning id
    into item_id_value;

    if existing_item.folio_id <> folio_row.id then
      perform private.recalculate_folio(
        source_row.hotel_id,
        existing_item.folio_id
      );
    end if;
  end if;

  perform private.day11_resolve_source_exception(
    source_row.hotel_id,
    'food_orders',
    source_row.id,
    jsonb_build_object(
      'resolved_by_sync', 'migration_034'
    )
  );

  if inserted_value then
    perform private.write_folio_event(
      source_row.hotel_id,
      folio_row.id,
      'folio.item.posted',
      'food_order',
      source_row.id,
      jsonb_build_object(
        'folio_item_id', item_id_value,
        'amount', source_row.total_amount,
        'charge_category', 'food'
      ),
      jsonb_build_object(
        'source_sync', 'migration_034'
      )
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'skipped', false,
    'idempotent', not inserted_value,
    'source_id', source_row.id,
    'folio_id', folio_row.id,
    'folio_item_id', item_id_value,
    'amount', source_row.total_amount
  );
end;
$$;


ALTER FUNCTION "private"."day11_sync_food_order"("target_order_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."day11_sync_food_order"("target_order_id" "uuid") IS 'Posts one delivered, item-reconciled and uniquely mapped food order as one authoritative folio food charge.';



CREATE OR REPLACE FUNCTION "private"."day11_sync_manual_charge"("target_charge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_row public.manual_charges%rowtype;
  mapping_value jsonb;
  mapped_session_id uuid;
  mapped_room_id uuid;
  candidate_count_value integer;
  folio_row public.folios%rowtype;
  existing_item public.folio_items%rowtype;
  item_id_value uuid;
  inserted_value boolean := false;
  exception_code_value text;
begin
  select charge.*
  into source_row
  from public.manual_charges charge
  where charge.id = target_charge_id;

  if not found then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'source_not_found',
      'source_id', target_charge_id
    );
  end if;

  mapping_value :=
    private.day11_resolve_financial_source_session(
      source_row.hotel_id,
      source_row.guest_id,
      source_row.room_id,
      source_row.created_at,
      true
    );

  candidate_count_value :=
    coalesce(
      (mapping_value ->> 'candidate_count')::integer,
      0
    );

  mapped_session_id :=
    nullif(
      mapping_value ->> 'guest_session_id',
      ''
    )::uuid;

  mapped_room_id :=
    nullif(
      mapping_value ->> 'mapped_room_id',
      ''
    )::uuid;

  exception_code_value := case
    when source_row.charge_amount <= 0
      then 'source_amount_invalid'
    when candidate_count_value > 1
      then 'source_ambiguous'
    when candidate_count_value = 0
      then 'source_unmatched'
    else null
  end;

  if exception_code_value is not null then
    perform private.day11_void_source_item(
      source_row.hotel_id,
      'manual_charges',
      source_row.id,
      'Manual charge failed authoritative stay mapping.'
    );

    perform private.day11_record_source_exception(
      source_row.hotel_id,
      'manual_charges',
      source_row.id,
      exception_code_value,
      candidate_count_value,
      source_row.guest_id,
      source_row.room_id,
      source_row.created_at,
      to_jsonb(source_row),
      mapping_value,
      jsonb_build_object(
        'source_sync', 'migration_034'
      )
    );

    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', exception_code_value,
      'source_id', source_row.id,
      'mapping', mapping_value
    );
  end if;

  folio_row := private.day11_ensure_folio_for_source(
    source_row.hotel_id,
    mapped_session_id,
    'legacy_manual_charge'
  );

  select item.*
  into existing_item
  from public.folio_items item
  where item.hotel_id = source_row.hotel_id
    and item.source_table = 'manual_charges'
    and item.source_id = source_row.id
  limit 1;

  if existing_item.id is null then
    insert into public.folio_items (
      hotel_id,
      folio_id,
      item_kind,
      charge_category,
      description,
      quantity,
      unit_amount,
      amount,
      source_table,
      source_id,
      service_at,
      posting_status,
      posted_at,
      posted_by,
      metadata
    )
    values (
      source_row.hotel_id,
      folio_row.id,
      'charge',
      'manual',
      coalesce(
        nullif(trim(source_row.charge_name), ''),
        'Manual charge'
      ),
      1,
      source_row.charge_amount,
      source_row.charge_amount,
      'manual_charges',
      source_row.id,
      source_row.created_at,
      'posted',
      source_row.created_at,
      null,
      jsonb_build_object(
        'legacy_payment_status',
          source_row.payment_status,
        'legacy_notes',
          source_row.notes,
        'legacy_room_id',
          source_row.room_id,
        'source_room_missing',
          source_row.room_id is null,
        'mapped_guest_session_id',
          mapped_session_id,
        'mapped_room_id',
          mapped_room_id,
        'source_sync', 'migration_034'
      )
    )
    returning id
    into item_id_value;

    inserted_value := true;
  else
    update public.folio_items
    set
      folio_id = folio_row.id,
      item_kind = 'charge',
      charge_category = 'manual',
      description = coalesce(
        nullif(trim(source_row.charge_name), ''),
        'Manual charge'
      ),
      quantity = 1,
      unit_amount = source_row.charge_amount,
      amount = source_row.charge_amount,
      service_at = source_row.created_at,
      posting_status = 'posted',
      voided_at = null,
      voided_by = null,
      void_reason = null,
      metadata = metadata || jsonb_build_object(
        'legacy_payment_status',
          source_row.payment_status,
        'legacy_notes',
          source_row.notes,
        'legacy_room_id',
          source_row.room_id,
        'source_room_missing',
          source_row.room_id is null,
        'mapped_guest_session_id',
          mapped_session_id,
        'mapped_room_id',
          mapped_room_id,
        'source_sync', 'migration_034'
      )
    where hotel_id = source_row.hotel_id
      and id = existing_item.id
    returning id
    into item_id_value;

    if existing_item.folio_id <> folio_row.id then
      perform private.recalculate_folio(
        source_row.hotel_id,
        existing_item.folio_id
      );
    end if;
  end if;

  perform private.day11_resolve_source_exception(
    source_row.hotel_id,
    'manual_charges',
    source_row.id,
    jsonb_build_object(
      'resolved_by_sync', 'migration_034'
    )
  );

  if inserted_value then
    perform private.write_folio_event(
      source_row.hotel_id,
      folio_row.id,
      'folio.item.posted',
      'manual_charge',
      source_row.id,
      jsonb_build_object(
        'folio_item_id', item_id_value,
        'amount', source_row.charge_amount,
        'charge_category', 'manual'
      ),
      jsonb_build_object(
        'source_sync', 'migration_034'
      )
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'skipped', false,
    'idempotent', not inserted_value,
    'source_id', source_row.id,
    'folio_id', folio_row.id,
    'folio_item_id', item_id_value,
    'amount', source_row.charge_amount
  );
end;
$$;


ALTER FUNCTION "private"."day11_sync_manual_charge"("target_charge_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."day11_sync_manual_charge"("target_charge_id" "uuid") IS 'Posts one positive and uniquely mapped legacy manual charge while preserving missing source room evidence in metadata.';



CREATE OR REPLACE FUNCTION "private"."day11_sync_payment"("target_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  payment_row public.payments%rowtype;
  folio_row public.folios%rowtype;
  existing_item_id uuid;
  existing_fallback_id uuid;
  actual_collection_count integer;
  category_value text;
  normalized_method text;
  collection_record record;
begin
  select payment.*
  into payment_row
  from public.payments payment
  where payment.id = target_payment_id;

  if not found then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'payment_not_found',
      'payment_id', target_payment_id
    );
  end if;

  if payment_row.guest_session_id is null then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'guest_session_missing',
      'payment_id', target_payment_id
    );
  end if;

  folio_row := private.day11_ensure_folio_for_source(
    payment_row.hotel_id,
    payment_row.guest_session_id,
    'legacy_payment'
  );

  category_value :=
    private.day11_payment_charge_category(payment_row.payment_type);

  normalized_method :=
    private.day11_normalize_payment_method(
      payment_row.payment_method
    );

  select item.id
  into existing_item_id
  from public.folio_items item
  where item.hotel_id = payment_row.hotel_id
    and item.source_table = 'payments'
    and item.source_id = payment_row.id
  limit 1;

  if existing_item_id is null then
    insert into public.folio_items (
      hotel_id,
      folio_id,
      item_kind,
      charge_category,
      description,
      quantity,
      unit_amount,
      amount,
      source_table,
      source_id,
      service_at,
      posting_status,
      posted_at,
      posted_by,
      metadata
    )
    values (
      payment_row.hotel_id,
      folio_row.id,
      'charge',
      category_value,
      coalesce(
        nullif(trim(payment_row.notes), ''),
        nullif(trim(payment_row.payment_notes), ''),
        case
          when category_value = 'room'
          then 'Room charge'
          else initcap(category_value) || ' charge'
        end
      ),
      1,
      payment_row.amount,
      payment_row.amount,
      'payments',
      payment_row.id,
      coalesce(payment_row.created_at, now()),
      'posted',
      coalesce(payment_row.created_at, now()),
      private.day11_valid_auth_actor(
        payment_row.collected_by
      ),
      jsonb_build_object(
        'legacy_collected_by', payment_row.collected_by,
        'legacy_payment_type', payment_row.payment_type,
        'legacy_payment_status', payment_row.payment_status,
        'legacy_payment_method', payment_row.payment_method,
        'legacy_invoice_id', payment_row.invoice_id,
        'legacy_reservation_id', payment_row.reservation_id,
        'legacy_reservation_room_id',
          payment_row.reservation_room_id,
        'source_sync', 'migration_033'
      )
    )
    returning id
    into existing_item_id;
  else
    update public.folio_items
    set
      folio_id = folio_row.id,
      charge_category = category_value,
      description = coalesce(
        nullif(trim(payment_row.notes), ''),
        nullif(trim(payment_row.payment_notes), ''),
        case
          when category_value = 'room'
          then 'Room charge'
          else initcap(category_value) || ' charge'
        end
      ),
      quantity = 1,
      unit_amount = payment_row.amount,
      amount = payment_row.amount,
      service_at = coalesce(payment_row.created_at, service_at),
      posting_status = 'posted',
      voided_at = null,
      voided_by = null,
      void_reason = null,
      metadata = metadata || jsonb_build_object(
        'legacy_collected_by', payment_row.collected_by,
        'legacy_payment_type', payment_row.payment_type,
        'legacy_payment_status', payment_row.payment_status,
        'legacy_payment_method', payment_row.payment_method,
        'legacy_invoice_id', payment_row.invoice_id,
        'legacy_reservation_id', payment_row.reservation_id,
        'legacy_reservation_room_id',
          payment_row.reservation_room_id,
        'source_sync', 'migration_033'
      )
    where hotel_id = payment_row.hotel_id
      and id = existing_item_id;
  end if;

  actual_collection_count := 0;

  for collection_record in
    select collection.id
    from public.payment_collections collection
    where collection.hotel_id = payment_row.hotel_id
      and collection.payment_id = payment_row.id
    order by collection.collected_at, collection.created_at, collection.id
  loop
    actual_collection_count := actual_collection_count + 1;
    perform private.day11_sync_payment_collection(
      collection_record.id
    );
  end loop;

  select collection.id
  into existing_fallback_id
  from public.folio_collections collection
  where collection.hotel_id = payment_row.hotel_id
    and collection.source_table = 'payments'
    and collection.source_id = payment_row.id
  limit 1;

  if
    lower(coalesce(payment_row.payment_status, 'pending')) = 'paid'
    and actual_collection_count = 0
  then
    if existing_fallback_id is null then
      insert into public.folio_collections (
        hotel_id,
        folio_id,
        collection_group_id,
        amount,
        payment_method,
        status,
        transaction_reference,
        provider,
        provider_payment_id,
        source_table,
        source_id,
        idempotency_key,
        collected_at,
        collected_by,
        metadata
      )
      values (
        payment_row.hotel_id,
        folio_row.id,
        payment_row.id,
        payment_row.amount,
        normalized_method,
        'posted',
        payment_row.transaction_reference,
        case
          when payment_row.razorpay_payment_id is not null
          then 'razorpay'
          else null
        end,
        payment_row.razorpay_payment_id,
        'payments',
        payment_row.id,
        'legacy-paid-payment:' || payment_row.id::text,
        coalesce(
          payment_row.paid_at,
          payment_row.created_at,
          now()
        ),
        private.day11_valid_auth_actor(
          payment_row.collected_by
        ),
        jsonb_build_object(
          'legacy_collected_by', payment_row.collected_by,
          'legacy_paid_fallback', true,
          'compatibility_reason',
            'Legacy payment is marked paid without payment_collection history.',
          'legacy_payment_status', payment_row.payment_status,
          'legacy_invoice_id', payment_row.invoice_id,
          'source_sync', 'migration_033'
        )
      )
      returning id
      into existing_fallback_id;
    else
      update public.folio_collections
      set
        folio_id = folio_row.id,
        collection_group_id = payment_row.id,
        amount = payment_row.amount,
        payment_method = normalized_method,
        status = 'posted',
        transaction_reference = payment_row.transaction_reference,
        provider = case
          when payment_row.razorpay_payment_id is not null
          then 'razorpay'
          else provider
        end,
        provider_payment_id = coalesce(
          payment_row.razorpay_payment_id,
          provider_payment_id
        ),
        collected_at = coalesce(
          payment_row.paid_at,
          payment_row.created_at,
          collected_at
        ),
        collected_by = private.day11_valid_auth_actor(
          payment_row.collected_by
        ),
        voided_at = null,
        voided_by = null,
        void_reason = null,
        metadata = metadata || jsonb_build_object(
          'legacy_collected_by', payment_row.collected_by,
          'legacy_paid_fallback', true,
          'compatibility_reason',
            'Legacy payment is marked paid without payment_collection history.',
          'legacy_payment_status', payment_row.payment_status,
          'legacy_invoice_id', payment_row.invoice_id,
          'source_sync', 'migration_033'
        )
      where hotel_id = payment_row.hotel_id
        and id = existing_fallback_id;
    end if;
  elsif existing_fallback_id is not null then
    update public.folio_collections
    set
      status = 'reversed',
      voided_at = coalesce(voided_at, now()),
      voided_by = coalesce(voided_by, auth.uid()),
      void_reason = coalesce(
        void_reason,
        case
          when actual_collection_count > 0
          then 'Replaced by authoritative payment_collection history.'
          else 'Legacy payment is no longer marked paid.'
        end
      ),
      metadata = metadata || jsonb_build_object(
        'reversed_by_sync', 'migration_033',
        'actual_collection_count', actual_collection_count,
        'legacy_payment_status', payment_row.payment_status
      )
    where hotel_id = payment_row.hotel_id
      and id = existing_fallback_id
      and status = 'posted';
  end if;

  return jsonb_build_object(
    'ok', true,
    'skipped', false,
    'payment_id', payment_row.id,
    'folio_id', folio_row.id,
    'folio_item_id', existing_item_id,
    'actual_collection_count', actual_collection_count,
    'fallback_collection_id', existing_fallback_id
  );
end;
$$;


ALTER FUNCTION "private"."day11_sync_payment"("target_payment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."day11_sync_payment"("target_payment_id" "uuid") IS 'Synchronizes one legacy payments charge into an authoritative folio and preserves legacy paid state with compatibility collection evidence when collection history is absent.';



CREATE OR REPLACE FUNCTION "private"."day11_sync_payment_collection"("target_collection_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  collection_row public.payment_collections%rowtype;
  payment_row public.payments%rowtype;
  folio_row public.folios%rowtype;
  guest_session_id_value uuid;
  existing_collection_id uuid;
  normalized_method text;
begin
  select collection.*
  into collection_row
  from public.payment_collections collection
  where collection.id = target_collection_id;

  if not found then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'collection_not_found',
      'collection_id', target_collection_id
    );
  end if;

  select payment.*
  into strict payment_row
  from public.payments payment
  where payment.hotel_id = collection_row.hotel_id
    and payment.id = collection_row.payment_id;

  guest_session_id_value :=
    coalesce(
      collection_row.guest_session_id,
      payment_row.guest_session_id
    );

  if guest_session_id_value is null then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'guest_session_missing',
      'collection_id', target_collection_id
    );
  end if;

  folio_row := private.day11_ensure_folio_for_source(
    collection_row.hotel_id,
    guest_session_id_value,
    'legacy_payment_collection'
  );

  normalized_method :=
    private.day11_normalize_payment_method(
      collection_row.payment_method
    );

  select folio_collection.id
  into existing_collection_id
  from public.folio_collections folio_collection
  where folio_collection.hotel_id = collection_row.hotel_id
    and folio_collection.source_table = 'payment_collections'
    and folio_collection.source_id = collection_row.id
  limit 1;

  if existing_collection_id is null then
    insert into public.folio_collections (
      hotel_id,
      folio_id,
      collection_group_id,
      amount,
      payment_method,
      status,
      transaction_reference,
      source_table,
      source_id,
      idempotency_key,
      collected_at,
      collected_by,
      metadata
    )
    values (
      collection_row.hotel_id,
      folio_row.id,
      collection_row.payment_id,
      collection_row.amount,
      normalized_method,
      'posted',
      collection_row.transaction_reference,
      'payment_collections',
      collection_row.id,
      'legacy-payment-collection:' || collection_row.id::text,
      coalesce(
        collection_row.collected_at,
        collection_row.created_at,
        now()
      ),
      private.day11_valid_auth_actor(
        collection_row.collected_by
      ),
      jsonb_build_object(
        'legacy_collected_by', collection_row.collected_by,
        'legacy_payment_id', collection_row.payment_id,
        'legacy_guest_id', collection_row.guest_id,
        'legacy_room_id', collection_row.room_id,
        'legacy_invoice_id', collection_row.invoice_id,
        'legacy_reservation_id', collection_row.reservation_id,
        'legacy_reservation_payment_id',
          collection_row.reservation_payment_id,
        'source_sync', 'migration_033',
        'legacy_paid_fallback', false
      )
    )
    returning id
    into existing_collection_id;
  else
    update public.folio_collections
    set
      folio_id = folio_row.id,
      collection_group_id = collection_row.payment_id,
      amount = collection_row.amount,
      payment_method = normalized_method,
      status = 'posted',
      transaction_reference = collection_row.transaction_reference,
      collected_at = coalesce(
        collection_row.collected_at,
        collection_row.created_at,
        collected_at
      ),
      collected_by = private.day11_valid_auth_actor(
        collection_row.collected_by
      ),
      voided_at = null,
      voided_by = null,
      void_reason = null,
      metadata = metadata || jsonb_build_object(
        'legacy_collected_by', collection_row.collected_by,
        'legacy_payment_id', collection_row.payment_id,
        'legacy_guest_id', collection_row.guest_id,
        'legacy_room_id', collection_row.room_id,
        'legacy_invoice_id', collection_row.invoice_id,
        'legacy_reservation_id', collection_row.reservation_id,
        'legacy_reservation_payment_id',
          collection_row.reservation_payment_id,
        'source_sync', 'migration_033',
        'legacy_paid_fallback', false
      )
    where hotel_id = collection_row.hotel_id
      and id = existing_collection_id;
  end if;

  -- Real collection history replaces any synthesized paid-payment fallback.
  update public.folio_collections fallback
  set
    status = 'reversed',
    voided_at = coalesce(fallback.voided_at, now()),
    voided_by = coalesce(fallback.voided_by, auth.uid()),
    void_reason = coalesce(
      fallback.void_reason,
      'Replaced by authoritative legacy payment_collection rows.'
    ),
    metadata = fallback.metadata || jsonb_build_object(
      'reversed_by_collection_id', collection_row.id,
      'reversed_by_sync', 'migration_033'
    )
  where fallback.hotel_id = collection_row.hotel_id
    and fallback.source_table = 'payments'
    and fallback.source_id = collection_row.payment_id
    and fallback.status = 'posted'
    and coalesce(
      (fallback.metadata ->> 'legacy_paid_fallback')::boolean,
      false
    );

  return jsonb_build_object(
    'ok', true,
    'skipped', false,
    'collection_id', collection_row.id,
    'folio_collection_id', existing_collection_id,
    'folio_id', folio_row.id,
    'guest_session_id', guest_session_id_value
  );
end;
$$;


ALTER FUNCTION "private"."day11_sync_payment_collection"("target_collection_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."day11_sync_payment_collection"("target_collection_id" "uuid") IS 'Synchronizes one payment_collections row one-to-one and reverses any synthesized paid-payment fallback for the same payment.';



CREATE OR REPLACE FUNCTION "private"."day11_valid_auth_actor"("candidate_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when candidate_actor_id is null then null::uuid
    when exists (
      select 1
      from auth.users auth_user
      where auth_user.id = candidate_actor_id
    ) then candidate_actor_id
    else null::uuid
  end;
$$;


ALTER FUNCTION "private"."day11_valid_auth_actor"("candidate_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."day11_valid_auth_actor"("candidate_actor_id" "uuid") IS 'Returns a candidate legacy actor only when it still exists in auth.users; stale UUIDs become NULL in constrained actor columns and remain preserved in source metadata.';



CREATE OR REPLACE FUNCTION "private"."day11_validate_adjustment_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  folio_row public.folios%rowtype;
  old_effect numeric(14,2) := 0;
  new_effect numeric(14,2) := 0;
  delta_value numeric(14,2);
  linked_status text;
  linked_hotel_id uuid;
  linked_folio_id uuid;
begin
  if tg_op = 'UPDATE' then
    if old.hotel_id is distinct from new.hotel_id
       or old.folio_id is distinct from new.folio_id
       or old.adjustment_type is distinct from new.adjustment_type
       or old.amount is distinct from new.amount
       or old.balance_effect is distinct from new.balance_effect
       or old.approval_id is distinct from new.approval_id
       or old.refund_id is distinct from new.refund_id
       or old.credit_note_id is distinct from new.credit_note_id
       or old.idempotency_key is distinct from new.idempotency_key
    then
      raise exception 'Posted adjustment identity and amount are immutable.';
    end if;
    old_effect := case when old.status = 'posted' then old.balance_effect else 0 end;
  end if;

  if new.adjustment_type = 'discount' then
    if new.approval_id is null or new.refund_id is not null or new.credit_note_id is not null then
      raise exception 'Discount adjustment requires only approval_id.';
    end if;
    select approval.status, approval.hotel_id, approval.folio_id
    into linked_status, linked_hotel_id, linked_folio_id
    from public.discount_approvals approval where approval.id = new.approval_id;
    if linked_status <> 'approved' or linked_hotel_id <> new.hotel_id or linked_folio_id <> new.folio_id then
      raise exception 'Discount adjustment must reference the approved same-folio request.';
    end if;
  elsif new.adjustment_type = 'refund' then
    if new.refund_id is null or new.approval_id is not null or new.credit_note_id is not null then
      raise exception 'Refund adjustment requires only refund_id.';
    end if;
    select refund.status, refund.hotel_id, refund.folio_id
    into linked_status, linked_hotel_id, linked_folio_id
    from public.refunds refund where refund.id = new.refund_id;
    if linked_status <> 'processed' or linked_hotel_id <> new.hotel_id or linked_folio_id <> new.folio_id then
      raise exception 'Refund adjustment must reference the processed same-folio refund.';
    end if;
  elsif new.adjustment_type = 'credit_note' then
    if new.credit_note_id is null or new.approval_id is not null or new.refund_id is not null then
      raise exception 'Credit adjustment requires only credit_note_id.';
    end if;
    select credit.status, credit.hotel_id, credit.folio_id
    into linked_status, linked_hotel_id, linked_folio_id
    from public.credit_notes credit where credit.id = new.credit_note_id;
    if linked_hotel_id <> new.hotel_id or linked_folio_id <> new.folio_id
       or (new.status = 'posted' and linked_status <> 'issued')
       or (new.status = 'voided' and linked_status <> 'voided')
    then
      raise exception 'Credit adjustment must match the same-folio credit-note state.';
    end if;
  elsif new.adjustment_type = 'writeoff' then
    if new.approval_id is not null or new.refund_id is not null or new.credit_note_id is not null then
      raise exception 'Writeoff cannot reference discount/refund/credit records.';
    end if;
  end if;

  new_effect := case when new.status = 'posted' then new.balance_effect else 0 end;
  delta_value := new_effect - old_effect;

  select folio.* into folio_row
  from public.folios folio
  where folio.hotel_id = new.hotel_id and folio.id = new.folio_id
  for update;

  if not found then raise exception 'Adjustment folio was not found.'; end if;
  if folio_row.status = 'voided' then raise exception 'A voided folio cannot accept adjustments.'; end if;
  if folio_row.balance_amount + delta_value < 0 then
    raise exception 'Adjustment exceeds open balance %. Effect %.', folio_row.balance_amount, delta_value;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."day11_validate_adjustment_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day11_validate_collection_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  folio_row public.folios%rowtype;
  old_effect numeric(14,2) := 0;
  new_effect numeric(14,2) := 0;
  delta_value numeric(14,2);
begin
  if tg_op = 'UPDATE' then
    if old.hotel_id is distinct from new.hotel_id
       or old.folio_id is distinct from new.folio_id
       or old.amount is distinct from new.amount
       or old.payment_method is distinct from new.payment_method
       or old.collection_group_id is distinct from new.collection_group_id
       or old.source_table is distinct from new.source_table
       or old.source_id is distinct from new.source_id
       or old.idempotency_key is distinct from new.idempotency_key
    then
      raise exception 'Posted collection identity and amount are immutable.';
    end if;
    old_effect := case when old.status = 'posted' then old.amount else 0 end;
  end if;

  new_effect := case when new.status = 'posted' then new.amount else 0 end;
  delta_value := new_effect - old_effect;

  select folio.* into folio_row
  from public.folios folio
  where folio.hotel_id = new.hotel_id and folio.id = new.folio_id
  for update;

  if not found then raise exception 'Collection folio was not found.'; end if;
  if folio_row.status = 'voided' then raise exception 'A voided folio cannot accept collections.'; end if;
  if delta_value > 0 and folio_row.balance_amount - delta_value < 0 then
    raise exception 'Collection exceeds open balance %. Additional collection %.', folio_row.balance_amount, delta_value;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."day11_validate_collection_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day11_validate_refund_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  collection_row public.folio_collections%rowtype;
  reserved_amount numeric(14,2);
begin
  if tg_op = 'UPDATE' then
    if old.hotel_id is distinct from new.hotel_id
       or old.folio_id is distinct from new.folio_id
       or old.folio_collection_id is distinct from new.folio_collection_id
       or old.amount is distinct from new.amount
       or old.payment_method is distinct from new.payment_method
       or old.idempotency_key is distinct from new.idempotency_key
    then
      raise exception 'Refund identity, source collection and amount are immutable.';
    end if;
    if old.status = 'processed' and new.status <> 'processed' then
      raise exception 'A processed refund cannot be reversed in place.';
    end if;
    if old.status in ('failed','cancelled') and new.status <> old.status then
      raise exception 'A failed or cancelled refund requires a new request.';
    end if;
  end if;

  select collection.* into collection_row
  from public.folio_collections collection
  where collection.hotel_id = new.hotel_id and collection.id = new.folio_collection_id
  for share;

  if not found then raise exception 'Refund source collection was not found.'; end if;
  if collection_row.folio_id <> new.folio_id or collection_row.status <> 'posted' then
    raise exception 'Refund must reference a posted collection from the same folio.';
  end if;
  if new.payment_method <> collection_row.payment_method then
    raise exception 'Refund method must match source collection.';
  end if;

  select coalesce(sum(refund.amount),0) into reserved_amount
  from public.refunds refund
  where refund.hotel_id = new.hotel_id
    and refund.folio_collection_id = new.folio_collection_id
    and refund.status in ('pending','processed')
    and refund.id is distinct from new.id;

  if new.status in ('pending','processed') and reserved_amount + new.amount > collection_row.amount then
    raise exception 'Refund exceeds collection %. Reserved %, attempted %.', collection_row.amount, reserved_amount, new.amount;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."day11_validate_refund_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day11_void_source_item"("target_hotel_id" "uuid", "source_table_value" "text", "source_id_value" "uuid", "reason_value" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_item public.folio_items%rowtype;
begin
  select item.*
  into source_item
  from public.folio_items item
  where item.hotel_id = target_hotel_id
    and item.source_table = source_table_value
    and item.source_id = source_id_value
  limit 1;

  if source_item.id is null then
    return false;
  end if;

  if source_item.posting_status = 'posted' then
    update public.folio_items
    set
      posting_status = 'voided',
      voided_at = now(),
      voided_by =
        private.day11_valid_auth_actor(auth.uid()),
      void_reason = coalesce(
        nullif(trim(reason_value), ''),
        'Source is no longer eligible for posting.'
      ),
      metadata = metadata || jsonb_build_object(
        'voided_by_source_sync', true,
        'voided_source_table', source_table_value,
        'voided_source_id', source_id_value
      )
    where hotel_id = target_hotel_id
      and id = source_item.id;

    perform private.write_folio_event(
      target_hotel_id,
      source_item.folio_id,
      'folio.item.voided',
      source_table_value,
      source_id_value,
      to_jsonb(source_item),
      jsonb_build_object(
        'reason', reason_value,
        'source_sync', 'migration_034'
      )
    );
  end if;

  return true;
end;
$$;


ALTER FUNCTION "private"."day11_void_source_item"("target_hotel_id" "uuid", "source_table_value" "text", "source_id_value" "uuid", "reason_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_build_accounting_csv"("h" "uuid", "d1" "date", "d2" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  tz text;
  start_at timestamptz;
  end_at timestamptz;
  header text:='business_date,entry_type,document_number,folio_number,invoice_number,payment_method,amount,tax_amount,reference,event_at';
  body text;
  csv text;
  rows_count integer;
begin
  if d1 is null or d2 is null or d2<d1 then raise exception 'Accounting export date range invalid.'; end if;
  select timezone into tz from public.hotels where id=h;
  if tz is null then raise exception 'Hotel not found.'; end if;
  start_at:=d1::timestamp at time zone tz;
  end_at:=(d2+1)::timestamp at time zone tz;

  select count(*),string_agg(row_text,E'\n' order by event_at,sort_order,document_number)
  into rows_count,body
  from (
    select c.collected_at event_at,1 sort_order,r.receipt_number document_number,
      private.day12_csv_escape((c.collected_at at time zone tz)::date::text)||','||
      private.day12_csv_escape('collection')||','||private.day12_csv_escape(r.receipt_number)||','||
      private.day12_csv_escape(f.folio_number)||','||private.day12_csv_escape(coalesce(i.invoice_number,''))||','||
      private.day12_csv_escape(c.payment_method)||','||private.day12_csv_escape(c.amount::text)||','||
      private.day12_csv_escape('0')||','||
      private.day12_csv_escape(coalesce(c.transaction_reference,c.provider_payment_id,''))||','||
      private.day12_csv_escape(c.collected_at::text) row_text
    from public.folio_collections c
    join public.folios f on f.hotel_id=c.hotel_id and f.id=c.folio_id
    join public.receipts r on r.hotel_id=c.hotel_id and r.folio_collection_id=c.id
    left join public.invoices i on i.hotel_id=c.hotel_id and i.folio_id=c.folio_id
      and i.invoice_origin='authoritative' and i.finalized_at is not null
    where c.hotel_id=h and c.status='posted' and c.collected_at>=start_at and c.collected_at<end_at

    union all

    select r.processed_at,2,'REFUND/'||r.id::text,
      private.day12_csv_escape((r.processed_at at time zone tz)::date::text)||','||
      private.day12_csv_escape('refund')||','||private.day12_csv_escape('REFUND/'||r.id::text)||','||
      private.day12_csv_escape(f.folio_number)||','||private.day12_csv_escape(coalesce(i.invoice_number,''))||','||
      private.day12_csv_escape(r.payment_method)||','||private.day12_csv_escape((-r.amount)::text)||','||
      private.day12_csv_escape('0')||','||
      private.day12_csv_escape(coalesce(r.transaction_reference,r.provider_refund_id,''))||','||
      private.day12_csv_escape(r.processed_at::text)
    from public.refunds r
    join public.folios f on f.hotel_id=r.hotel_id and f.id=r.folio_id
    left join public.invoices i on i.hotel_id=r.hotel_id and i.folio_id=r.folio_id
      and i.invoice_origin='authoritative' and i.finalized_at is not null
    where r.hotel_id=h and r.status='processed' and r.processed_at>=start_at and r.processed_at<end_at

    union all

    select i.finalized_at,3,i.invoice_number,
      private.day12_csv_escape(i.invoice_date::text)||','||private.day12_csv_escape('invoice')||','||
      private.day12_csv_escape(i.invoice_number)||','||private.day12_csv_escape(f.folio_number)||','||
      private.day12_csv_escape(i.invoice_number)||','||private.day12_csv_escape('')||','||
      private.day12_csv_escape(i.total_amount::text)||','||private.day12_csv_escape(i.tax_amount::text)||','||
      private.day12_csv_escape(i.snapshot_hash)||','||private.day12_csv_escape(i.finalized_at::text)
    from public.invoices i
    join public.folios f on f.hotel_id=i.hotel_id and f.id=i.folio_id
    where i.hotel_id=h and i.invoice_origin='authoritative' and i.finalized_at>=start_at and i.finalized_at<end_at

    union all

    select c.issued_at,4,c.credit_note_number,
      private.day12_csv_escape((c.issued_at at time zone tz)::date::text)||','||private.day12_csv_escape('credit_note')||','||
      private.day12_csv_escape(c.credit_note_number)||','||private.day12_csv_escape(f.folio_number)||','||
      private.day12_csv_escape(coalesce(i.invoice_number,''))||','||private.day12_csv_escape('')||','||
      private.day12_csv_escape((-c.amount)::text)||','||private.day12_csv_escape('0')||','||
      private.day12_csv_escape(c.reason)||','||private.day12_csv_escape(c.issued_at::text)
    from public.credit_notes c
    join public.folios f on f.hotel_id=c.hotel_id and f.id=c.folio_id
    left join public.invoices i on i.hotel_id=c.hotel_id and i.folio_id=c.folio_id
      and i.invoice_origin='authoritative' and i.finalized_at is not null
    where c.hotel_id=h and c.status='issued' and c.issued_at>=start_at and c.issued_at<end_at
  ) q;

  csv:=header||case when coalesce(body,'')='' then '' else E'\n'||body end;
  return jsonb_build_object('date_from',d1,'date_to',d2,'row_count',rows_count,'csv_content',csv,'content_hash',private.day12_hash_text(csv));
end;
$$;


ALTER FUNCTION "private"."day12_build_accounting_csv"("h" "uuid", "d1" "date", "d2" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_build_cashier_shift_snapshot"("h" "uuid", "shift_id_value" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  s public.cashier_shifts%rowtype;
  entry_count_value integer;
  inflow_value numeric;
  outflow_value numeric;
  cash_net_value numeric;
  methods jsonb;
begin
  select * into s from public.cashier_shifts where hotel_id=h and id=shift_id_value;
  if not found then raise exception 'Cashier shift not found.'; end if;
  select count(*),
         coalesce(sum(amount) filter(where direction='inflow'),0),
         coalesce(sum(amount) filter(where direction='outflow'),0),
         coalesce(sum(net_effect) filter(where payment_method='cash'),0)
  into entry_count_value,inflow_value,outflow_value,cash_net_value
  from public.cashier_shift_entries where hotel_id=h and cashier_shift_id=shift_id_value;
  select coalesce(jsonb_object_agg(method_value,payload),'{}'::jsonb)
  into methods
  from (
    select coalesce(payment_method,'unclassified') method_value,
           jsonb_build_object(
             'entries',count(*),
             'inflow',coalesce(sum(amount) filter(where direction='inflow'),0),
             'outflow',coalesce(sum(amount) filter(where direction='outflow'),0),
             'net',coalesce(sum(net_effect),0)
           ) payload
    from public.cashier_shift_entries
    where hotel_id=h and cashier_shift_id=shift_id_value
    group by coalesce(payment_method,'unclassified')
  ) q;
  return jsonb_build_object(
    'shift',to_jsonb(s),'entry_count',entry_count_value,'inflow_amount',inflow_value,
    'outflow_amount',outflow_value,'net_amount',inflow_value-outflow_value,
    'cash_net',cash_net_value,'expected_cash',s.opening_cash+cash_net_value,
    'method_breakdown',methods,
    'entries',coalesce((select jsonb_agg(to_jsonb(e) order by e.occurred_at,e.id)
                        from public.cashier_shift_entries e
                        where e.hotel_id=h and e.cashier_shift_id=shift_id_value),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "private"."day12_build_cashier_shift_snapshot"("h" "uuid", "shift_id_value" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_build_day_close_preview"("h" "uuid", "business_date_value" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  hotel_row public.hotels%rowtype;
  period_end timestamptz;
  x jsonb:='[]'::jsonb;
  blockers integer;
  warnings integer;
  financial jsonb;
begin
  select * into hotel_row from public.hotels where id=h;
  if not found then raise exception 'Hotel not found.'; end if;
  if business_date_value is null then raise exception 'Business date required.'; end if;
  period_end:=(business_date_value+1)::timestamp at time zone hotel_row.timezone;

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','open_folio','severity','blocker','entity_type','folio','entity_id',id,
    'amount',balance_amount,'message','Open folio '||folio_number||' has balance '||balance_amount::text,
    'source_snapshot',to_jsonb(f)
  ) order by balance_amount desc,id)
  from public.folios f where hotel_id=h and status='open' and balance_amount>0),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','active_stay','severity','blocker','entity_type','guest_session','entity_id',id,
    'amount',null,'message','Guest session remains active.','source_snapshot',to_jsonb(s)
  ) order by checkin_time,id)
  from public.guest_sessions s where hotel_id=h and status='active'),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','overdue_stay','severity','blocker','entity_type','guest_session','entity_id',id,
    'amount',null,'message','Active stay is past effective checkout.','source_snapshot',to_jsonb(s)
  ) order by coalesce(extended_until,checkout_time),id)
  from public.guest_sessions s
  where hotel_id=h and status='active' and coalesce(extended_until,checkout_time)<period_end),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','financial_source_exception','severity','warning','entity_type',source_table,
    'entity_id',source_id,'amount',null,'message','Financial source remains unmapped: '||source_table,
    'source_snapshot',to_jsonb(e)
  ) order by last_seen_at,id)
  from public.folio_source_exceptions e where hotel_id=h and status='open'),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','pending_refund','severity','blocker','entity_type','refund','entity_id',id,
    'amount',amount,'message','Refund remains pending.','source_snapshot',to_jsonb(r)
  ) order by requested_at,id)
  from public.refunds r where hotel_id=h and status='pending'),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','unresolved_gateway_event','severity','blocker','entity_type','payment_webhook_event',
    'entity_id',id,'amount',null,'message','Gateway event remains '||event_status||'.',
    'source_snapshot',to_jsonb(e)
  ) order by received_at,id)
  from public.payment_webhook_events e where hotel_id=h and event_status in ('received','failed')),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','open_cashier_shift','severity','blocker','entity_type','cashier_shift','entity_id',id,
    'amount',opening_cash,'message','Cashier shift '||shift_number||' remains open.',
    'source_snapshot',to_jsonb(s)
  ) order by opened_at,id)
  from public.cashier_shifts s where hotel_id=h and status='open'),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','unreceipted_collection','severity','blocker','entity_type','folio_collection',
    'entity_id',c.id,'amount',c.amount,'message','Posted collection has no receipt.',
    'source_snapshot',to_jsonb(c)
  ) order by c.collected_at,c.id)
  from public.folio_collections c left join public.receipts r
    on r.hotel_id=c.hotel_id and r.folio_collection_id=c.id
  where c.hotel_id=h and c.status='posted' and r.id is null),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','draft_invoice','severity','warning','entity_type','invoice','entity_id',id,
    'amount',total_amount,'message','Invoice remains draft.','source_snapshot',to_jsonb(i)
  ) order by created_at,id)
  from public.invoices i where hotel_id=h and invoice_status='draft' and finalized_at is null),'[]'::jsonb);

  x:=x||coalesce((select jsonb_agg(jsonb_build_object(
    'exception_type','unfinished_housekeeping','severity','warning','entity_type','housekeeping_task',
    'entity_id',id,'amount',null,'message','Housekeeping task remains '||coalesce(status,'unknown')||'.',
    'source_snapshot',to_jsonb(t)
  ) order by created_at,id)
  from public.housekeeping_tasks t
  where hotel_id=h and coalesce(status,'pending') not in ('completed','cancelled','inspected','ready')),'[]'::jsonb);

  select count(*) filter(where value->>'severity'='blocker'),
         count(*) filter(where value->>'severity'='warning')
  into blockers,warnings from jsonb_array_elements(x);

  select jsonb_build_object(
    'folios',count(*),'open_folios',count(*) filter(where status='open'),
    'settled_folios',count(*) filter(where status='settled'),
    'charges_amount',coalesce(sum(charges_amount),0),
    'discounts_amount',coalesce(sum(discount_amount),0),
    'taxes_amount',coalesce(sum(tax_amount),0),
    'collections_amount',coalesce(sum(collection_amount),0),
    'refunds_amount',coalesce(sum(refund_amount),0),
    'credits_amount',coalesce(sum(credit_amount),0),
    'open_balance_amount',coalesce(sum(balance_amount),0),
    'equation_failures',count(*) filter(where balance_amount<>charges_amount-discount_amount+tax_amount-collection_amount+refund_amount-credit_amount)
  ) into financial from public.folios where hotel_id=h;

  return jsonb_build_object(
    'schema','stayqr.day_close.preview','version',1,'hotel_id',h,'business_date',business_date_value,
    'timezone',hotel_row.timezone,'generated_at',now(),'blocker_count',blockers,'warning_count',warnings,
    'exception_count',blockers+warnings,'financial_summary',financial,'exceptions',x
  );
end;
$$;


ALTER FUNCTION "private"."day12_build_day_close_preview"("h" "uuid", "business_date_value" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_build_invoice_snapshot"("target_hotel_id" "uuid", "target_invoice_id" "uuid", "finalized_at_override" timestamp with time zone DEFAULT NULL::timestamp with time zone, "verification_token_override" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invoice_row public.invoices%rowtype;
  hotel_snapshot_value jsonb;
  guest_snapshot_value jsonb;
  folio_snapshot_value jsonb;
  item_snapshot_value jsonb;
  finalized_value timestamptz;
  token_value uuid;
begin
  select invoice.*
  into invoice_row
  from public.invoices invoice
  where invoice.hotel_id = target_hotel_id
    and invoice.id = target_invoice_id;

  if not found then
    raise exception 'Invoice was not found.';
  end if;

  finalized_value :=
    coalesce(finalized_at_override, invoice_row.finalized_at);

  token_value :=
    coalesce(
      verification_token_override,
      invoice_row.verification_token
    );

  select
    to_jsonb(hotel)
    || jsonb_build_object(
      'settings',
      coalesce(
        (
          select to_jsonb(setting)
          from public.hotel_settings setting
          where setting.hotel_id = hotel.id
        ),
        '{}'::jsonb
      )
    )
  into hotel_snapshot_value
  from public.hotels hotel
  where hotel.id = target_hotel_id;

  select coalesce(
    (
      select to_jsonb(guest)
      from public.guests guest
      where guest.id = invoice_row.guest_id
    ),
    '{}'::jsonb
  )
  into guest_snapshot_value;

  select coalesce(
    (
      select to_jsonb(folio)
      from public.folios folio
      where folio.hotel_id = target_hotel_id
        and folio.id = invoice_row.folio_id
    ),
    '{}'::jsonb
  )
  into folio_snapshot_value;

  select coalesce(
    jsonb_agg(
      to_jsonb(item)
      order by
        item.line_number nulls last,
        item.created_at,
        item.id
    ),
    '[]'::jsonb
  )
  into item_snapshot_value
  from public.invoice_items item
  where item.hotel_id = target_hotel_id
    and item.invoice_id = target_invoice_id;

  return jsonb_build_object(
    'schema', 'stayqr.invoice.snapshot',
    'version', invoice_row.snapshot_version,
    'invoice',
      (
        to_jsonb(invoice_row)
        - 'snapshot_json'
        - 'snapshot_hash'
      )
      || jsonb_build_object(
        'finalized_at', finalized_value,
        'verification_token', token_value
      ),
    'items', item_snapshot_value,
    'seller', coalesce(
      invoice_row.seller_snapshot,
      hotel_snapshot_value
    ),
    'buyer', coalesce(
      invoice_row.buyer_snapshot,
      guest_snapshot_value
    ),
    'folio', folio_snapshot_value,
    'captured_at', finalized_value
  );
end;
$$;


ALTER FUNCTION "private"."day12_build_invoice_snapshot"("target_hotel_id" "uuid", "target_invoice_id" "uuid", "finalized_at_override" timestamp with time zone, "verification_token_override" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."accounting_exports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "hotel_id" "uuid" NOT NULL,
    "night_audit_id" "uuid",
    "export_type" "text" DEFAULT 'accounting_csv'::"text" NOT NULL,
    "date_from" "date" NOT NULL,
    "date_to" "date" NOT NULL,
    "file_name" "text" NOT NULL,
    "content_type" "text" DEFAULT 'text/csv'::"text" NOT NULL,
    "row_count" integer NOT NULL,
    "csv_content" "text" NOT NULL,
    "content_hash" "text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "generated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "generated_by" "uuid" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "accounting_exports_check" CHECK (("date_to" >= "date_from")),
    CONSTRAINT "accounting_exports_content_hash_check" CHECK (("length"(TRIM(BOTH FROM "content_hash")) = 64)),
    CONSTRAINT "accounting_exports_csv_content_check" CHECK (("length"("csv_content") > 0)),
    CONSTRAINT "accounting_exports_export_type_check" CHECK (("export_type" = ANY (ARRAY['accounting_csv'::"text", 'collections_csv'::"text", 'invoice_csv'::"text", 'gst_csv'::"text"]))),
    CONSTRAINT "accounting_exports_row_count_check" CHECK (("row_count" >= 0))
);


ALTER TABLE "public"."accounting_exports" OWNER TO "postgres";


COMMENT ON TABLE "public"."accounting_exports" IS 'Checksum-protected accounting CSV.';



CREATE OR REPLACE FUNCTION "private"."day12_create_accounting_export"("h" "uuid", "audit_id_value" "uuid", "d1" "date", "d2" "date", "request_key" "text", "actor" "uuid") RETURNS "public"."accounting_exports"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.accounting_exports%rowtype;
  payload jsonb;
begin
  select * into e from public.accounting_exports where hotel_id=h and idempotency_key=request_key;
  if e.id is not null then return e; end if;
  payload:=private.day12_build_accounting_csv(h,d1,d2);
  insert into public.accounting_exports(
    hotel_id,night_audit_id,export_type,date_from,date_to,file_name,content_type,row_count,
    csv_content,content_hash,idempotency_key,generated_by,metadata
  ) values (
    h,audit_id_value,'accounting_csv',d1,d2,
    'stayqr-accounting-'||d1::text||case when d2=d1 then '' else '-to-'||d2::text end||'.csv',
    'text/csv',(payload->>'row_count')::integer,payload->>'csv_content',payload->>'content_hash',
    request_key,actor,jsonb_build_object('generated_from',case when audit_id_value is null then 'manual_export' else 'night_audit' end)
  ) returning * into e;
  return e;
end;
$$;


ALTER FUNCTION "private"."day12_create_accounting_export"("h" "uuid", "audit_id_value" "uuid", "d1" "date", "d2" "date", "request_key" "text", "actor" "uuid") OWNER TO "postgres";


