CREATE OR REPLACE FUNCTION "private"."day12_financial_year_start"("occurred_at_value" timestamp with time zone, "timezone_value" "text") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when extract(
      month from (
        coalesce(occurred_at_value, now())
        at time zone coalesce(
          nullif(trim(timezone_value), ''),
          'Asia/Kolkata'
        )
      )
    ) >= 4
    then extract(
      year from (
        coalesce(occurred_at_value, now())
        at time zone coalesce(
          nullif(trim(timezone_value), ''),
          'Asia/Kolkata'
        )
      )
    )::integer
    else extract(
      year from (
        coalesce(occurred_at_value, now())
        at time zone coalesce(
          nullif(trim(timezone_value), ''),
          'Asia/Kolkata'
        )
      )
    )::integer - 1
  end;
$$;


