$$;


ALTER FUNCTION "private"."day12_hash_text"("v" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_issue_receipt_for_collection"("collection_id_value" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.folio_collections%rowtype;
  fol public.folios%rowtype;
  r public.receipts%rowtype;
  num jsonb;
  shift_id uuid;
  snap jsonb;
  hash_value text;
begin
  select * into c from public.folio_collections where id=collection_id_value;
  if not found then return jsonb_build_object('ok',true,'skipped',true,'reason','collection_not_found'); end if;
  select * into r from public.receipts where hotel_id=c.hotel_id and folio_collection_id=c.id;
  if r.id is not null then return jsonb_build_object('ok',true,'idempotent',true,'receipt',to_jsonb(r)); end if;
  if c.status<>'posted' then return jsonb_build_object('ok',true,'skipped',true,'reason','collection_not_posted'); end if;
  select * into fol from public.folios where hotel_id=c.hotel_id and id=c.folio_id;
  if not found then raise exception 'Collection folio not found.'; end if;
  shift_id:=private.day12_current_open_cashier_shift(c.hotel_id,c.collected_by);
  num:=private.day12_next_receipt_number(c.hotel_id,c.collected_at);
  snap:=jsonb_build_object(
    'schema','stayqr.receipt.snapshot','version',1,
    'receipt_number',num->>'receipt_number',
    'hotel',(select to_jsonb(h) from public.hotels h where h.id=c.hotel_id),
    'folio',to_jsonb(fol),'collection',to_jsonb(c),'cashier_shift_id',shift_id,'issued_at',c.collected_at
  );
  hash_value:=private.day12_hash_snapshot(snap);
  insert into public.receipts(
    hotel_id,folio_id,folio_collection_id,cashier_shift_id,receipt_number,receipt_status,currency_code,
    amount,payment_method,transaction_reference,provider,provider_payment_id,issued_at,issued_by,
    idempotency_key,snapshot_json,snapshot_hash,metadata
  ) values (
    c.hotel_id,c.folio_id,c.id,shift_id,num->>'receipt_number','issued',fol.currency_code,
    c.amount,c.payment_method,c.transaction_reference,c.provider,c.provider_payment_id,c.collected_at,
    private.day11_valid_auth_actor(c.collected_by),'collection:'||c.id::text,snap,hash_value,
    jsonb_build_object('financial_year_start',(num->>'financial_year_start')::integer,'source','folio_collection')
  ) returning * into r;
  return jsonb_build_object('ok',true,'idempotent',false,'receipt',to_jsonb(r));
end;
$$;


ALTER FUNCTION "private"."day12_issue_receipt_for_collection"("collection_id_value" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_lock_finalized_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.finalized_at is not null then
      raise exception
        'Finalized invoices are immutable and cannot be deleted.';
    end if;

    return old;
  end if;

  if old.finalized_at is not null then
    if to_jsonb(new) is distinct from to_jsonb(old) then
      raise exception
        'Finalized invoices are immutable. Use a credit note or cancellation workflow.';
    end if;

    return new;
  end if;

  if new.finalized_at is not null then
    if new.snapshot_json is null
       or nullif(trim(new.snapshot_hash), '') is null
       or new.verification_token is null
    then
      raise exception
        'Invoice finalization requires snapshot, hash and verification token.';
    end if;

    if new.snapshot_hash <>
      private.day12_hash_snapshot(new.snapshot_json)
    then
      raise exception
        'Invoice snapshot hash does not match the immutable snapshot.';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "private"."day12_lock_finalized_invoice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_lock_finalized_invoice_items"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_invoice_id uuid;
  finalized_value timestamptz;
begin
  target_invoice_id :=
    coalesce(new.invoice_id, old.invoice_id);

  select invoice.finalized_at
  into finalized_value
  from public.invoices invoice
  where invoice.id = target_invoice_id;

  if finalized_value is not null then
    raise exception
      'Finalized invoice lines are immutable.';
  end if;

  if tg_op <> 'DELETE' then
    new.updated_at := now();
    return new;
  end if;

  return old;
end;
$$;


ALTER FUNCTION "private"."day12_lock_finalized_invoice_items"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_next_invoice_number"("target_hotel_id" "uuid", "occurred_at_value" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  hotel_row public.hotels%rowtype;
  sequence_row public.invoice_number_sequences%rowtype;
  financial_year_start_value integer;
  financial_year_label_value text;
  next_number_value bigint;
  generated_number text;
begin
  select hotel.*
  into hotel_row
  from public.hotels hotel
  where hotel.id = target_hotel_id;

  if not found then
    raise exception 'Hotel was not found.';
  end if;

  financial_year_start_value :=
    private.day12_financial_year_start(
      occurred_at_value,
      hotel_row.timezone
    );

  financial_year_label_value :=
    private.day12_financial_year_label(
      financial_year_start_value
    );

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:invoice-sequence:'
      || target_hotel_id::text
      || ':'
      || financial_year_start_value::text,
      0
    )
  );

  insert into public.invoice_number_sequences (
    hotel_id,
    sequence_year,
    prefix,
    last_number,
    padding,
    reset_annually,
    updated_by
  )
  values (
    target_hotel_id,
    financial_year_start_value,
    'INV',
    0,
    6,
    true,
    private.day11_valid_auth_actor(auth.uid())
  )
  on conflict (hotel_id, sequence_year)
  do nothing;

  update public.invoice_number_sequences
  set
    last_number = last_number + 1,
    updated_at = now(),
    updated_by =
      private.day11_valid_auth_actor(auth.uid())
  where hotel_id = target_hotel_id
    and sequence_year = financial_year_start_value
  returning *
  into sequence_row;

  next_number_value := sequence_row.last_number;

  generated_number :=
    trim(sequence_row.prefix)
    || '/'
    || financial_year_label_value
    || '/'
    || lpad(
      next_number_value::text,
      sequence_row.padding,
      '0'
    );

  return jsonb_build_object(
    'invoice_number', generated_number,
    'financial_year_start',
      financial_year_start_value,
    'financial_year_label',
      financial_year_label_value,
    'sequence_number', next_number_value,
    'prefix', sequence_row.prefix,
    'padding', sequence_row.padding
  );
end;
$$;


ALTER FUNCTION "private"."day12_next_invoice_number"("target_hotel_id" "uuid", "occurred_at_value" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "private"."day12_next_invoice_number"("target_hotel_id" "uuid", "occurred_at_value" timestamp with time zone) IS 'Concurrency-safe Indian financial-year invoice number allocator using the existing invoice_number_sequences table.';



CREATE OR REPLACE FUNCTION "private"."day12_next_receipt_number"("h" "uuid", "occurred" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  tz text;
  fy integer;
  label text;
  seq public.receipt_number_sequences%rowtype;
begin
  select timezone into tz from public.hotels where id=h;
  if tz is null then raise exception 'Hotel not found.'; end if;
  fy:=private.day12_financial_year_start(coalesce(occurred,now()),tz);
  label:=private.day12_financial_year_label(fy);
  perform pg_advisory_xact_lock(hashtextextended('stayqr:receipt-seq:'||h::text||':'||fy::text,0));
  insert into public.receipt_number_sequences(hotel_id,financial_year_start,prefix,last_number,padding,updated_by)
  values(h,fy,'RCPT',0,6,private.day11_valid_auth_actor(auth.uid()))
  on conflict(hotel_id,financial_year_start) do nothing;
  update public.receipt_number_sequences
  set last_number=last_number+1,updated_by=private.day11_valid_auth_actor(auth.uid()),updated_at=now()
  where hotel_id=h and financial_year_start=fy
  returning * into seq;
  return jsonb_build_object(
    'receipt_number',trim(seq.prefix)||'/'||label||'/'||lpad(seq.last_number::text,seq.padding,'0'),
    'financial_year_start',fy,'financial_year_label',label,'sequence_number',seq.last_number
  );
end;
$$;


ALTER FUNCTION "private"."day12_next_receipt_number"("h" "uuid", "occurred" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day12_preview_folio_invoice"("target_hotel_id" "uuid", "target_folio_id" "uuid", "supply_mode_value" "text", "invoice_date_value" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  folio_row public.folios%rowtype;
  hotel_row public.hotels%rowtype;
  stay_row public.guest_sessions%rowtype;
  guest_snapshot_value jsonb;
  settings_snapshot_value jsonb;

  source_record record;

  charge_count integer;
  current_line integer := 0;

  gross_charges_value numeric(14,2);
  discount_value numeric(14,2);
  allocated_discount_value numeric(14,2) := 0;
  line_discount_value numeric(14,2);
  line_taxable_value numeric(14,2);

  base_tax_value numeric(14,2);
  cgst_value numeric(14,2);
  sgst_value numeric(14,2);
  igst_value numeric(14,2);
  cess_value numeric(14,2);
  line_total_value numeric(14,2);

  room_amount_value numeric(14,2) := 0;
  food_amount_value numeric(14,2) := 0;
  service_amount_value numeric(14,2) := 0;
  manual_amount_value numeric(14,2) := 0;
  other_amount_value numeric(14,2) := 0;

  taxable_total_value numeric(14,2) := 0;
  cgst_total_value numeric(14,2) := 0;
  sgst_total_value numeric(14,2) := 0;
  igst_total_value numeric(14,2) := 0;
  cess_total_value numeric(14,2) := 0;
  tax_total_value numeric(14,2) := 0;
  invoice_total_value numeric(14,2) := 0;

  net_collection_value numeric(14,2);
  paid_value numeric(14,2);
  pending_value numeric(14,2);

  selected_rate_count integer;
  selected_rate_id uuid;
  selected_rate_percent numeric(7,4);
  selected_cess_percent numeric(7,4);
  selected_hsn_sac_code text;

  lines_value jsonb := '[]'::jsonb;
  tax_breakup_value jsonb := '{}'::jsonb;

  seller_gstin_value text;
  buyer_gstin_value text;
  seller_state_value text;
  buyer_state_value text;
  seller_state_code_value text;
  buyer_state_code_value text;
begin
  if supply_mode_value not in (
    'exempt',
    'intra_state',
    'inter_state'
  ) then
    raise exception
      'Supply mode must be exempt, intra_state or inter_state.';
  end if;

  if invoice_date_value is null then
    raise exception 'Invoice date is required.';
  end if;

  select folio.*
  into folio_row
  from public.folios folio
  where folio.hotel_id = target_hotel_id
    and folio.id = target_folio_id;

  if not found then
    raise exception 'Folio was not found.';
  end if;

  if folio_row.status = 'voided' then
    raise exception 'A voided folio cannot be invoiced.';
  end if;

  if folio_row.charges_amount <= 0 then
    raise exception 'Folio has no posted charge.';
  end if;

  if folio_row.credit_amount > 0
     or folio_row.refund_amount > 0
  then
    raise exception
      'Final invoice must precede credit-note or refund activity.';
  end if;

  if exists (
    select 1
    from public.invoices invoice
    where invoice.hotel_id = target_hotel_id
      and invoice.folio_id = target_folio_id
      and invoice.invoice_origin =
        'authoritative'
      and invoice.finalized_at is not null
  ) then
    raise exception
      'A final authoritative invoice already exists for this folio.';
  end if;

  select hotel.*
  into hotel_row
  from public.hotels hotel
  where hotel.id = target_hotel_id;

  if not found then
    raise exception 'Hotel was not found.';
  end if;

  select stay.*
  into stay_row
  from public.guest_sessions stay
  where stay.hotel_id = target_hotel_id
    and stay.id = folio_row.guest_session_id;

  if not found then
    raise exception 'Guest session was not found.';
  end if;

  select coalesce(
    (
      select to_jsonb(setting)
      from public.hotel_settings setting
      where setting.hotel_id = target_hotel_id
    ),
    '{}'::jsonb
  )
  into settings_snapshot_value;

  select coalesce(
    (
      select to_jsonb(guest)
      from public.guests guest
      where guest.hotel_id = target_hotel_id
        and guest.id = folio_row.guest_id
    ),
    '{}'::jsonb
  )
  into guest_snapshot_value;

  seller_gstin_value :=
    upper(
      nullif(
        regexp_replace(
          coalesce(
            hotel_row.gst_number,
            settings_snapshot_value
              ->> 'tax_registration_number',
            ''
          ),
          '\s+',
          '',
          'g'
        ),
        ''
      )
    );

  buyer_gstin_value :=
    upper(
      nullif(
        regexp_replace(
          coalesce(
            guest_snapshot_value ->> 'gst_number',
            guest_snapshot_value ->> 'gstin',
            ''
          ),
          '\s+',
          '',
          'g'
        ),
        ''
      )
    );

  seller_state_value :=
    nullif(trim(hotel_row.state), '');

  seller_state_code_value :=
    case
      when seller_gstin_value is not null
        then left(seller_gstin_value, 2)
      else null
    end;

  buyer_state_value :=
    coalesce(
      nullif(
        trim(
          guest_snapshot_value ->> 'state'
        ),
        ''
      ),
      seller_state_value
    );

  buyer_state_code_value :=
    case
      when buyer_gstin_value is not null
        then left(buyer_gstin_value, 2)
      when supply_mode_value = 'intra_state'
        then seller_state_code_value
      else null
    end;

  if seller_gstin_value is not null
     and seller_gstin_value !~
       '^[0-9]{2}[A-Z0-9]{13}$'
  then
    raise exception 'Hotel GSTIN format is invalid.';
  end if;

  if buyer_gstin_value is not null
     and buyer_gstin_value !~
       '^[0-9]{2}[A-Z0-9]{13}$'
  then
    raise exception 'Buyer GSTIN format is invalid.';
  end if;

  select
    count(*),
    coalesce(sum(item.amount), 0)
  into
    charge_count,
    gross_charges_value
  from public.folio_items item
  where item.hotel_id = target_hotel_id
    and item.folio_id = target_folio_id
    and item.posting_status = 'posted'
    and item.item_kind = 'charge';

  if charge_count = 0
     or gross_charges_value <= 0
  then
    raise exception
      'No posted charge items are available.';
  end if;

  discount_value := folio_row.discount_amount;

  if discount_value > gross_charges_value then
    raise exception
      'Folio discount exceeds posted charges.';
  end if;

  for source_record in
    select
      item.id,
      item.charge_category,
      item.description,
      item.quantity,
      item.unit_amount,
      item.amount,
      item.service_at,
      item.metadata,
      row_number() over (
        order by item.service_at,
                 item.created_at,
                 item.id
      )::integer as line_number
    from public.folio_items item
    where item.hotel_id = target_hotel_id
      and item.folio_id = target_folio_id
      and item.posting_status = 'posted'
      and item.item_kind = 'charge'
    order by item.service_at,
             item.created_at,
             item.id
  loop
    current_line := current_line + 1;

    if current_line = charge_count then
      line_discount_value :=
        discount_value
        - allocated_discount_value;
    else
      line_discount_value :=
        round(
          discount_value
          * source_record.amount
          / gross_charges_value,
          2
        );

      allocated_discount_value :=
        allocated_discount_value
        + line_discount_value;
    end if;

    line_taxable_value :=
      greatest(
        source_record.amount
        - line_discount_value,
        0
      );

    selected_rate_id := null;
    selected_rate_count := 0;
    selected_rate_percent := 0;
    selected_cess_percent := 0;
    selected_hsn_sac_code := null;
    base_tax_value := 0;
    cgst_value := 0;
    sgst_value := 0;
    igst_value := 0;
    cess_value := 0;

    if supply_mode_value <> 'exempt' then
      select
        count(*),
        (
          min(tax_rate.id::text)
        )::uuid
      into
        selected_rate_count,
        selected_rate_id
      from public.tax_rates tax_rate
      where tax_rate.hotel_id =
            target_hotel_id
        and tax_rate.charge_category =
            coalesce(
              source_record.charge_category,
              'other'
            )
        and tax_rate.is_active
        and invoice_date_value >=
            tax_rate.valid_from
        and (
          tax_rate.valid_to is null
          or invoice_date_value <=
             tax_rate.valid_to
        );

      if selected_rate_count <> 1 then
        raise exception
          'Exactly one active tax rate is required for category %. Found %.',
          coalesce(
            source_record.charge_category,
            'other'
          ),
          selected_rate_count;
      end if;

      select
        tax_rate.rate_percent,
        tax_rate.cess_percent,
        tax_rate.hsn_sac_code
      into
        selected_rate_percent,
        selected_cess_percent,
        selected_hsn_sac_code
      from public.tax_rates tax_rate
      where tax_rate.hotel_id =
            target_hotel_id
        and tax_rate.id =
            selected_rate_id;

      base_tax_value :=
        round(
          line_taxable_value
          * selected_rate_percent
          / 100,
          2
        );

      cess_value :=
        round(
          line_taxable_value
          * selected_cess_percent
          / 100,
          2
        );

      if supply_mode_value = 'intra_state' then
        cgst_value :=
          round(base_tax_value / 2, 2);

        sgst_value :=
          base_tax_value - cgst_value;
      else
        igst_value := base_tax_value;
      end if;
    end if;

    line_total_value :=
      line_taxable_value
      + cgst_value
      + sgst_value
      + igst_value
      + cess_value;

    taxable_total_value :=
      taxable_total_value
      + line_taxable_value;

    cgst_total_value :=
      cgst_total_value + cgst_value;

    sgst_total_value :=
      sgst_total_value + sgst_value;

    igst_total_value :=
      igst_total_value + igst_value;

    cess_total_value :=
      cess_total_value + cess_value;

    case coalesce(
      source_record.charge_category,
      'other'
    )
      when 'room' then
        room_amount_value :=
          room_amount_value
          + source_record.amount;
      when 'food' then
        food_amount_value :=
          food_amount_value
          + source_record.amount;
      when 'service' then
        service_amount_value :=
          service_amount_value
          + source_record.amount;
      when 'manual' then
        manual_amount_value :=
          manual_amount_value
          + source_record.amount;
      else
        other_amount_value :=
          other_amount_value
          + source_record.amount;
    end case;

    lines_value :=
      lines_value
      || jsonb_build_array(
        jsonb_build_object(
          'line_number',
            source_record.line_number,
          'folio_item_id',
            source_record.id,
          'item_type',
            case
              when source_record.charge_category =
                   'manual'
                then 'manual_charge'
              when source_record.charge_category in (
                'room',
                'food',
                'service'
              )
                then source_record.charge_category
              else 'other'
            end,
          'charge_category',
            coalesce(
              source_record.charge_category,
              'other'
            ),
          'description',
            source_record.description,
          'quantity',
            source_record.quantity,
          'unit_price',
            source_record.unit_amount,
          'gross_amount',
            source_record.amount,
          'discount_amount',
            line_discount_value,
          'taxable_amount',
            line_taxable_value,
          'tax_rate_id',
            selected_rate_id,
          'tax_rate_percent',
            coalesce(
              selected_rate_percent,
              0
            ),
          'cess_rate_percent',
            coalesce(
              selected_cess_percent,
              0
            ),
          'hsn_sac_code',
            selected_hsn_sac_code,
          'cgst_amount',
            cgst_value,
          'sgst_amount',
            sgst_value,
          'igst_amount',
            igst_value,
          'cess_amount',
            cess_value,
          'line_total',
            line_total_value,
          'service_at',
            source_record.service_at,
          'source_metadata',
            source_record.metadata
        )
      );
  end loop;

  tax_total_value :=
    cgst_total_value
    + sgst_total_value
    + igst_total_value
    + cess_total_value;

  invoice_total_value :=
    taxable_total_value
    + tax_total_value;

  net_collection_value :=
    greatest(
      folio_row.collection_amount
      - folio_row.refund_amount,
      0
    );

  paid_value :=
    least(
      net_collection_value,
      invoice_total_value
    );

  pending_value :=
    greatest(
      invoice_total_value
      - paid_value,
      0
    );

  tax_breakup_value :=
    jsonb_build_object(
      'taxable_amount',
        taxable_total_value,
      'cgst_amount',
        cgst_total_value,
      'sgst_amount',
        sgst_total_value,
      'igst_amount',
        igst_total_value,
      'cess_amount',
        cess_total_value,
      'tax_amount',
        tax_total_value
    );

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'folio_id', target_folio_id,
    'guest_session_id',
      folio_row.guest_session_id,
    'guest_id', folio_row.guest_id,
    'room_id', folio_row.room_id,
    'invoice_date', invoice_date_value,
    'supply_mode', supply_mode_value,
    'currency_code', folio_row.currency_code,
    'seller_gstin', seller_gstin_value,
    'buyer_gstin', buyer_gstin_value,
    'place_of_supply', buyer_state_value,
    'place_of_supply_code',
      buyer_state_code_value,
    'seller_state', seller_state_value,
    'seller_state_code',
      seller_state_code_value,
    'gross_charges', gross_charges_value,
    'discount_amount', discount_value,
    'room_amount', room_amount_value,
    'food_amount', food_amount_value,
    'service_amount', service_amount_value,
    'manual_amount', manual_amount_value,
    'other_amount', other_amount_value,
    'taxable_amount', taxable_total_value,
    'tax_breakup', tax_breakup_value,
    'invoice_total', invoice_total_value,
    'net_collection', net_collection_value,
    'paid_amount', paid_value,
    'pending_amount', pending_value,
    'payment_status',
      case
        when pending_value = 0
          then 'paid'
        when paid_value > 0
          then 'partially_paid'
        else 'pending'
      end,
    'invoice_status',
      case
        when pending_value = 0
          then 'paid'
        when paid_value > 0
          then 'partially_paid'
        else 'issued'
      end,
    'checkin_time', stay_row.checkin_time,
    'checkout_time',
      coalesce(
        stay_row.extended_until,
        stay_row.checkout_time
      ),
    'stay_hours',
      greatest(
        ceil(
          extract(
            epoch from (
              coalesce(
                stay_row.extended_until,
                stay_row.checkout_time
              )
              - stay_row.checkin_time
            )
          ) / 3600
        )::integer,
        0
      ),
    'stay_nights',
      greatest(
        ceil(
          extract(
            epoch from (
              coalesce(
                stay_row.extended_until,
                stay_row.checkout_time
              )
              - stay_row.checkin_time
            )
          ) / 86400
        )::integer,
        0
      ),
    'seller_snapshot',
      to_jsonb(hotel_row)
      || jsonb_build_object(
        'settings',
          settings_snapshot_value
      ),
    'buyer_snapshot',
      guest_snapshot_value,
    'lines', lines_value
  );
end;
$_$;


