CREATE OR REPLACE FUNCTION "private"."day13_hash_json"("payload" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select encode(
    extensions.digest(
      convert_to(payload::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
$$;


