CREATE OR REPLACE FUNCTION "private"."day13_insert_housekeeping_event"("target_hotel_id" "uuid", "target_task_id" "uuid", "event_type_value" "text", "previous_status_value" "text", "new_status_value" "text", "actor_id_value" "uuid", "request_id_value" "text", "metadata_value" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  event_id_value uuid;
begin
  insert into public.housekeeping_task_events (
    hotel_id,
    task_id,
    event_type,
    previous_status,
    new_status,
    actor_id,
    request_id,
    metadata
  )
  values (
    target_hotel_id,
    target_task_id,
    event_type_value,
    previous_status_value,
    new_status_value,
    actor_id_value,
    nullif(trim(request_id_value), ''),
    coalesce(metadata_value, '{}'::jsonb)
  )
  on conflict (
    hotel_id,
    request_id,
    event_type
  )
  where request_id is not null
  do update
  set request_id =
    excluded.request_id
  returning id
  into event_id_value;

  return event_id_value;
end;
$$;


