CREATE OR REPLACE FUNCTION "private"."day13_maintenance_task_number"("target_hotel_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  hotel_timezone text;
  business_day date;
  next_sequence integer;
begin
  select hotel.timezone
  into hotel_timezone
  from public.hotels hotel
  where hotel.id = target_hotel_id;

  business_day :=
    (
      now()
      at time zone coalesce(
        hotel_timezone,
        'Asia/Kolkata'
      )
    )::date;

  perform pg_advisory_xact_lock(
    hashtextextended(
      target_hotel_id::text
      || ':maintenance:'
      || business_day::text,
      0
    )
  );

  select count(*) + 1
  into next_sequence
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.created_at >= business_day::timestamptz
    and task.created_at <
        (business_day + 1)::timestamptz;

  return
    'MNT-'
    || to_char(business_day, 'YYYYMMDD')
    || '-'
    || lpad(next_sequence::text, 4, '0');
end;
$$;


ALTER FUNCTION "private"."day13_maintenance_task_number"("target_hotel_id" "uuid") OWNER TO "postgres";


