CREATE OR REPLACE FUNCTION "private"."day13_prepare_atomic_checkout_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  hotel_row public.hotels%rowtype;
  folio_row public.folios%rowtype;
  number_value jsonb;
  settings_snapshot_value jsonb := '{}'::jsonb;
  seller_snapshot_value jsonb := '{}'::jsonb;
  buyer_snapshot_value jsonb := '{}'::jsonb;
  issue_at_value timestamptz;
begin
  -- Day 12-native issuance is already complete and must remain untouched.
  if new.financial_year_start is not null
     and nullif(trim(new.financial_year_label), '') is not null
     and new.invoice_date is not null
     and nullif(trim(new.currency_code), '') is not null
  then
    return new;
  end if;

  -- Limit compatibility handling to the old paid atomic checkout shape.
  if new.guest_session_id is null
     or new.folio_id is not null
     or lower(coalesce(new.invoice_status, '')) <> 'paid'
     or lower(coalesce(new.payment_status, '')) <> 'paid'
     or new.finalized_at is not null
  then
    return new;
  end if;

  select hotel.*
  into strict hotel_row
  from public.hotels hotel
  where hotel.id = new.hotel_id;

  folio_row := private.day11_ensure_folio_for_source(
    new.hotel_id,
    new.guest_session_id,
    'checkout_guest_session_day13_compatibility'
  );

  issue_at_value := coalesce(
    new.settled_at,
    new.checkout_time,
    new.created_at,
    now()
  );

  number_value := private.day12_next_invoice_number(
    new.hotel_id,
    issue_at_value
  );

  select coalesce(
    (
      select to_jsonb(setting)
      from public.hotel_settings setting
      where setting.hotel_id = new.hotel_id
    ),
    '{}'::jsonb
  )
  into settings_snapshot_value;

  seller_snapshot_value :=
    to_jsonb(hotel_row)
    || jsonb_build_object(
      'settings', settings_snapshot_value
    );

  select coalesce(
    (
      select to_jsonb(guest)
      from public.guests guest
      where guest.hotel_id = new.hotel_id
        and guest.id = new.guest_id
    ),
    '{}'::jsonb
  )
  into buyer_snapshot_value;

  new.folio_id := folio_row.id;
  new.invoice_number := number_value ->> 'invoice_number';
  new.invoice_origin := 'authoritative';
  new.idempotency_key := coalesce(
    nullif(trim(new.idempotency_key), ''),
    'stayqr:checkout:' || new.guest_session_id::text
  );

  new.financial_year_start :=
    (number_value ->> 'financial_year_start')::integer;
  new.financial_year_label :=
    number_value ->> 'financial_year_label';
  new.invoice_date :=
    (issue_at_value at time zone coalesce(hotel_row.timezone, 'Asia/Kolkata'))::date;
  new.currency_code :=
    coalesce(nullif(trim(hotel_row.currency_code), ''), 'INR');

  if coalesce(new.seller_snapshot, '{}'::jsonb) = '{}'::jsonb then
    new.seller_snapshot := seller_snapshot_value;
  end if;

  if coalesce(new.buyer_snapshot, '{}'::jsonb) = '{}'::jsonb then
    new.buyer_snapshot := buyer_snapshot_value;
  end if;

  new.tax_mode := case
    when coalesce(new.tax_amount, 0) > 0
      then 'legacy_unclassified'
    else 'exempt'
  end;

  new.taxable_amount := greatest(
    round(
      coalesce(new.subtotal_amount, 0)
      - coalesce(new.discount_amount, 0),
      2
    ),
    0
  );

  new.metadata :=
    coalesce(new.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'source', 'checkout_guest_session',
      'compatibility_migration', '044',
      'day13_checkout_compatibility', true,
      'original_invoice_number', new.invoice_number,
      'folio_id', folio_row.id
    );

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "private"."day13_prepare_atomic_checkout_invoice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day13_prepare_housekeeping_task"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  room_row public.rooms%rowtype;
  staff_row public.staff%rowtype;
  latest_session public.guest_sessions%rowtype;
  actor_id_value uuid;
begin
  select room.*
  into room_row
  from public.rooms room
  where room.hotel_id = new.hotel_id
    and room.id = new.room_id;

  if not found then
    raise exception
      'Housekeeping task requires a room in the same hotel.';
  end if;

  if not room_row.is_active then
    raise exception
      'Archived room cannot receive a housekeeping task.';
  end if;

  new.room_number := room_row.room_number;
  new.status :=
    coalesce(
      nullif(trim(new.status), ''),
      'pending'
    );
  new.task_type :=
    coalesce(
      nullif(trim(new.task_type), ''),
      'room_cleaning'
    );
  new.priority :=
    coalesce(
      nullif(trim(new.priority), ''),
      'normal'
    );
  new.updated_at := now();

  actor_id_value :=
    private.day11_valid_auth_actor(auth.uid());

  new.updated_by :=
    coalesce(
      actor_id_value,
      new.updated_by
    );

  if new.source_type = 'manual'
     and new.notes ilike
         'Checkout cleaning task%'
  then
    new.source_type := 'checkout';
  elsif new.source_type = 'manual'
        and new.notes ilike
            'Room cleaning after active stay moved%'
  then
    new.source_type := 'room_move';
  end if;

  if new.source_type in (
    'checkout',
    'room_move'
  )
  and new.source_guest_session_id is null
  then
    select session_record.*
    into latest_session
    from public.guest_sessions session_record
    where session_record.hotel_id =
          new.hotel_id
      and session_record.room_id =
          new.room_id
      and session_record.status =
          'completed'
    order by
      coalesce(
        session_record.checked_out_at,
        session_record.expired_at,
        session_record.created_at
      ) desc
    limit 1;

    if latest_session.id is not null then
      new.source_guest_session_id :=
        latest_session.id;
      new.source_reservation_id :=
        latest_session.reservation_id;
    end if;
  end if;

  if new.assigned_staff_id is not null then
    select staff.*
    into staff_row
    from public.staff staff
    where staff.hotel_id = new.hotel_id
      and staff.id = new.assigned_staff_id
      and staff.status = 'active'
      and staff.disabled_at is null;

    if staff_row.id is null then
      raise exception
        'Assigned housekeeping staff is not active in this hotel.';
    end if;

    new.assigned_to := staff_row.full_name;
    new.assigned_at :=
      coalesce(new.assigned_at, now());
    new.assigned_by :=
      coalesce(new.assigned_by, actor_id_value);

    if new.status = 'pending' then
      new.status := 'assigned';
    end if;
  else
    new.assigned_to := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."day13_prepare_housekeeping_task"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day13_record_room_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare req text; src text; rsn text;
begin
  if tg_op='UPDATE' and new.status is not distinct from old.status
     and new.is_active is not distinct from old.is_active then return new; end if;
  req:=nullif(current_setting('stayqr.day13_request_id',true),'');
  src:=coalesce(nullif(current_setting('stayqr.day13_event_source',true),''),'database');
  if src not in ('database','room_rpc','archive_rpc','import','checkin','checkout','housekeeping','maintenance') then src:='database'; end if;
  rsn:=coalesce(nullif(current_setting('stayqr.day13_status_reason',true),''),nullif(new.metadata->>'last_status_reason',''));
  insert into public.room_status_events(
    hotel_id,room_id,previous_status,new_status,previous_is_active,new_is_active,
    reason,source,request_id,actor_id,metadata
  ) values (
    new.hotel_id,new.id,case when tg_op='INSERT' then null else old.status end,new.status,
    case when tg_op='INSERT' then null else old.is_active end,new.is_active,
    rsn,src,req,private.day11_valid_auth_actor(auth.uid()),
    jsonb_build_object('room_number',new.room_number,'floor_id',new.floor_id,'room_type_id',new.room_type_id)
  )
  on conflict (hotel_id,request_id) where request_id is not null do nothing;
  return new;
end;
$$;


ALTER FUNCTION "private"."day13_record_room_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day13_require_housekeeping_manager"("target_hotel_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
begin
  if target_hotel_id is null then
    raise exception 'Hotel ID is required.';
  end if;

  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'housekeeping.manage',
      'rooms.manage',
      'hotel.manage',
      'superadmin.manage'
    ]::text[]
  ) then
    raise exception
      'Housekeeping management access denied.';
  end if;

  actor_id_value :=
    private.day11_require_current_actor();

  return actor_id_value;
end;
$$;


