CREATE OR REPLACE FUNCTION "private"."day13_seed_housekeeping_items"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  template_row
    public.housekeeping_checklist_templates%rowtype;
begin
  select template.*
  into template_row
  from public.housekeeping_checklist_templates template
  where template.hotel_id = new.hotel_id
    and template.task_type = new.task_type
    and template.is_active
  order by template.version desc
  limit 1;

  if template_row.id is null then
    raise exception
      'No active housekeeping checklist template exists for task type %.',
      new.task_type;
  end if;

  update public.housekeeping_tasks
  set checklist_version =
    template_row.version
  where hotel_id = new.hotel_id
    and id = new.id;

  insert into public.housekeeping_task_items (
    hotel_id,
    task_id,
    template_id,
    item_code,
    label,
    sort_order,
    is_required,
    metadata
  )
  select
    new.hotel_id,
    new.id,
    template_row.id,
    item.value ->> 'code',
    item.value ->> 'label',
    coalesce(
      (item.value ->> 'sort_order')::integer,
      item.ordinality::integer * 10
    ),
    coalesce(
      (item.value ->> 'required')::boolean,
      true
    ),
    jsonb_build_object(
      'template_version',
      template_row.version
    )
  from jsonb_array_elements(
    template_row.items
  ) with ordinality item(value, ordinality);

  return new;
end;
$$;


ALTER FUNCTION "private"."day13_seed_housekeeping_items"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day13_sync_checkout_request_on_stay_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status::text = 'completed'
     and old.status::text is distinct from new.status::text
  then
    update public.service_requests request
    set
      status = 'completed',
      accepted_at = coalesce(request.accepted_at, now()),
      started_at = coalesce(request.started_at, now()),
      completed_at = coalesce(request.completed_at, now())
    where request.hotel_id = new.hotel_id
      and request.room_id = new.room_id
      and request.guest_id = new.guest_id
      and request.request_type = 'Checkout Request'
      and request.status not in ('completed', 'cancelled');
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."day13_sync_checkout_request_on_stay_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day13_sync_room_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare fa boolean; ta boolean; tn text;
begin
  new.room_number:=private.day13_normalize_room_number(new.room_number);
  if new.room_number is null then raise exception 'Room number is required.'; end if;
  select f.is_active into fa from public.floors f where f.hotel_id=new.hotel_id and f.id=new.floor_id;
  if fa is distinct from true then raise exception 'Room requires an active floor.'; end if;
  select t.is_active,t.name into ta,tn from public.room_types t where t.hotel_id=new.hotel_id and t.id=new.room_type_id;
  if ta is distinct from true then raise exception 'Room requires an active room type.'; end if;
  new.room_type:=tn;
  return new;
end;
$$;


