CREATE OR REPLACE FUNCTION "private"."day14_build_guide_snapshot"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_snapshot jsonb;
begin
  select jsonb_build_object(
    'schema_version', 1,
    'generated_at', now(),
    'hotel_id', p_hotel_id,
    'settings', jsonb_build_object(
      'template_key', s.template_key,
      'default_locale', s.default_locale,
      'enabled_locales', to_jsonb(s.enabled_locales),
      'theme', s.theme,
      'branding', s.branding,
      'navigation', s.navigation
    ),
    'legacy_content', coalesce(
      (
        select jsonb_object_agg(c.locale, c.content)
        from public.hotel_guest_content c
        where c.hotel_id = p_hotel_id
          and c.is_active
      ),
      '{}'::jsonb
    ),
    'sections', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', sec.id,
            'section_key', sec.section_key,
            'section_type', sec.section_type,
            'sort_order', sec.sort_order,
            'is_enabled', sec.is_enabled,
            'settings', sec.settings,
            'translations', coalesce(
              (
                select jsonb_object_agg(
                  tr.locale,
                  jsonb_strip_nulls(
                    jsonb_build_object(
                      'label', tr.label,
                      'title', tr.title,
                      'subtitle', tr.subtitle,
                      'body', tr.body,
                      'button_label', tr.button_label,
                      'metadata', tr.metadata
                    )
                  )
                )
                from public.guest_guide_section_translations tr
                where tr.section_id = sec.id
              ),
              '{}'::jsonb
            )
          )
          order by sec.sort_order, sec.section_key
        )
        from public.guest_guide_sections sec
        where sec.hotel_id = p_hotel_id
      ),
      '[]'::jsonb
    ),
    'items', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'section_id', i.section_id,
            'scope_type', i.scope_type,
            'room_type_id', i.room_type_id,
            'room_id', i.room_id,
            'item_key', i.item_key,
            'item_type', i.item_type,
            'icon', i.icon,
            'action_type', i.action_type,
            'action_value', i.action_value,
            'sort_order', i.sort_order,
            'is_enabled', i.is_enabled,
            'metadata', i.metadata,
            'translations', coalesce(
              (
                select jsonb_object_agg(
                  tr.locale,
                  jsonb_strip_nulls(
                    jsonb_build_object(
                      'title', tr.title,
                      'subtitle', tr.subtitle,
                      'description', tr.description,
                      'instructions', tr.instructions,
                      'disclaimer', tr.disclaimer,
                      'button_label', tr.button_label,
                      'metadata', tr.metadata
                    )
                  )
                )
                from public.guest_guide_item_translations tr
                where tr.item_id = i.id
              ),
              '{}'::jsonb
            )
          )
          order by i.section_id, i.sort_order, i.item_key
        )
        from public.guest_guide_items i
        where i.hotel_id = p_hotel_id
      ),
      '[]'::jsonb
    ),
    'media', coalesce(
      (
        select jsonb_agg(
          jsonb_strip_nulls(
            jsonb_build_object(
              'id', m.id,
              'section_id', m.section_id,
              'item_id', m.item_id,
              'scope_type', m.scope_type,
              'room_type_id', m.room_type_id,
              'room_id', m.room_id,
              'media_key', m.media_key,
              'category', m.category,
              'bucket_id', m.bucket_id,
              'object_path', m.object_path,
              'mime_type', m.mime_type,
              'title', m.title,
              'caption', m.caption,
              'alt_text', m.alt_text,
              'locale', m.locale,
              'sort_order', m.sort_order,
              'is_active', m.is_active,
              'metadata', m.metadata
            )
          )
          order by m.sort_order, m.media_key
        )
        from public.guest_guide_media m
        where m.hotel_id = p_hotel_id
      ),
      '[]'::jsonb
    ),
    'payment_profile', coalesce(
      (
        select jsonb_strip_nulls(
          jsonb_build_object(
            'is_enabled', p.is_enabled,
            'payee_name', p.payee_name,
            'upi_id', p.upi_id,
            'qr_media_id', p.qr_media_id,
            'instructions', p.instructions,
            'show_outstanding_balance', p.show_outstanding_balance,
            'require_reception_confirmation',
              p.require_reception_confirmation,
            'metadata', p.metadata
          )
        )
        from public.guest_guide_payment_profiles p
        where p.hotel_id = p_hotel_id
      ),
      '{}'::jsonb
    ),
    'greetings', coalesce(
      (
        select jsonb_object_agg(
          g.locale,
          jsonb_build_object(
            'language_name', g.language_name,
            'native_name', g.native_name,
            'neutral', g.neutral_greeting,
            'morning', g.morning_greeting,
            'afternoon', g.afternoon_greeting,
            'evening', g.evening_greeting,
            'night', g.night_greeting,
            'is_enabled', g.is_enabled,
            'sort_order', g.sort_order
          )
        )
        from public.guest_guide_greetings g
        where g.hotel_id = p_hotel_id
      ),
      '{}'::jsonb
    )
  )
  into v_snapshot
  from public.guest_guide_settings s
  where s.hotel_id = p_hotel_id;

  if v_snapshot is null then
    raise exception 'Guest guide settings were not found.';
  end if;

  return v_snapshot;
end;
$$;


ALTER FUNCTION "private"."day14_build_guide_snapshot"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day14_builder_preflight_rev2"() RETURNS TABLE("area" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_count bigint;
  v_text text;
begin
  -- ========================================================================
  -- A. ACCEPTED DAY 14 BASELINE
  -- ========================================================================

  return query
  select 'BASELINE', '01_hotel_guest_content',
    to_regclass('public.hotel_guest_content') is not null,
    'Migration 045 multilingual content table exists.';

  return query
  select 'BASELINE', '02_guest_feedback',
    to_regclass('public.guest_feedback') is not null,
    'Migration 045 private feedback table exists.';

  return query
  select 'BASELINE', '03_guest_review_rewards',
    to_regclass('public.guest_review_rewards') is not null,
    'Migration 045 review/reward audit table exists.';

  return query
  select 'BASELINE', '04_resolve_guest_portal',
    to_regprocedure('public.resolve_guest_portal(text,text)') is not null,
    'Signed guest portal resolver exists.';

  return query
  select 'BASELINE', '05_submit_guest_feedback',
    to_regprocedure(
      'public.submit_guest_feedback(text,text,integer,text,boolean)'
    ) is not null,
    'Signed feedback RPC exists.';

  return query
  select 'BASELINE', '06_review_reward_action',
    to_regprocedure(
      'public.record_guest_review_reward_action(text,text,text)'
    ) is not null,
    'Signed review/reward RPC exists.';

  return query
  select 'BASELINE', '07_content_read_rpc',
    to_regprocedure(
      'public.get_hotel_guest_content(uuid,text)'
    ) is not null,
    'Hotel content read RPC exists.';

  return query
  select 'BASELINE', '08_content_write_rpc',
    to_regprocedure(
      'public.upsert_hotel_guest_content(uuid,text,jsonb)'
    ) is not null,
    'Hotel content write RPC exists.';

  return query
  select 'BASELINE', '09_anon_portal_execute',
    coalesce(
      has_function_privilege(
        'anon',
        'public.resolve_guest_portal(text,text)',
        'EXECUTE'
      ),
      false
    ),
    'Anonymous signed links can resolve.';

  return query
  select 'BASELINE', '10_authenticated_portal_execute',
    coalesce(
      has_function_privilege(
        'authenticated',
        'public.resolve_guest_portal(text,text)',
        'EXECUTE'
      ),
      false
    ),
    'Authenticated browser profiles can resolve signed links.';

  return query
  select 'BASELINE', '11_no_duplicate_active_tokens',
    not exists (
      select 1
      from public.guest_access_tokens
      where status = 'active'
      group by guest_session_id
      having count(*) > 1
    ),
    'At most one active token exists per guest stay.';

  return query
  select 'BASELINE', '12_no_expired_active_tokens',
    not exists (
      select 1
      from public.guest_access_tokens
      where status = 'active'
        and expires_at <= now()
    ),
    'No expired token remains active.';

  -- ========================================================================
  -- B. TENANT / ROOM INHERITANCE CONTRACTS
  -- ========================================================================

  return query
  select 'INHERITANCE', '01_hotels_table',
    to_regclass('public.hotels') is not null,
    'Hotels relation exists.';

  return query
  select 'INHERITANCE', '02_room_types_table',
    to_regclass('public.room_types') is not null,
    'Room types relation exists.';

  return query
  select 'INHERITANCE', '03_rooms_table',
    to_regclass('public.rooms') is not null,
    'Rooms relation exists.';

  return query
  select 'INHERITANCE', '04_rooms_room_type_id',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'rooms'
        and column_name = 'room_type_id'
        and udt_name = 'uuid'
    ),
    'Rooms can inherit content from a room type.';

  return query
  select 'INHERITANCE', '05_rooms_metadata',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'rooms'
        and column_name = 'metadata'
        and udt_name = 'jsonb'
    ),
    'Room metadata column exists.';

  return query
  select 'INHERITANCE', '06_room_types_metadata',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'room_types'
        and column_name = 'metadata'
        and udt_name = 'jsonb'
    ),
    'Room-type metadata column exists.';

  return query
  select 'INHERITANCE', '07_room_hotel_composite',
    exists (
      select 1
      from pg_indexes
      where schemaname = 'public'
        and tablename = 'rooms'
        and indexdef ilike '%hotel_id%'
        and indexdef ilike '%id%'
    ),
    'Rooms have tenant-aware indexing.';

  return query
  select 'INHERITANCE', '08_room_type_hotel_composite',
    exists (
      select 1
      from pg_indexes
      where schemaname = 'public'
        and tablename = 'room_types'
        and indexdef ilike '%hotel_id%'
        and indexdef ilike '%id%'
    ),
    'Room types have tenant-aware indexing.';

  v_count := private.day14_builder_safe_count_rev2(
    'public.hotels',
    null
  );
  return query
  select 'INHERITANCE', '09_hotel_count',
    v_count > 0,
    format('%s hotel row(s) are present.', v_count);

  v_count := private.day14_builder_safe_count_rev2(
    'public.room_types',
    'is_active'
  );
  return query
  select 'INHERITANCE', '10_active_room_type_count',
    v_count >= 0,
    format('%s active room-type row(s) are present.', v_count);

  v_count := private.day14_builder_safe_count_rev2(
    'public.rooms',
    'is_active'
  );
  return query
  select 'INHERITANCE', '11_active_room_count',
    v_count >= 0,
    format('%s active room row(s) are present.', v_count);

  return query
  select 'INHERITANCE', '12_room_type_fk_present',
    exists (
      select 1
      from pg_constraint c
      join pg_class t on t.oid = c.conrelid
      join pg_namespace n on n.oid = t.relnamespace
      where n.nspname = 'public'
        and t.relname = 'rooms'
        and c.contype = 'f'
        and pg_get_constraintdef(c.oid) ilike '%room_type%'
    ),
    'Rooms enforce a room-type relationship.';

  -- ========================================================================
  -- C. HOTEL PROFILE / PAYMENT / CONTACT INPUTS
  -- ========================================================================

  return query
  select 'PROFILE', '01_hotel_info_table',
    to_regclass('public.hotel_info') is not null,
    'Existing hotel profile relation exists.';

  foreach v_text in array array[
    'hotel_name',
    'address',
    'reception_phone',
    'emergency_phone',
    'checkin_time',
    'checkout_time',
    'breakfast_time',
    'wifi_name',
    'wifi_password',
    'hotel_rules',
    'about',
    'google_review_url',
    'reward_title',
    'reward_description',
    'reward_enabled'
  ]
  loop
    return query
    select
      'PROFILE',
      '02_hotel_info_column_' || v_text,
      exists (
        select 1
        from information_schema.columns
        where table_schema = 'public'
          and table_name = 'hotel_info'
          and column_name = v_text
      ),
      format('hotel_info.%s inventory.', v_text);
  end loop;

  return query
  select 'PROFILE', '03_existing_social_profile_columns',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name in ('hotels', 'hotel_info')
        and column_name in (
          'instagram_url',
          'facebook_url',
          'youtube_url',
          'website_url',
          'whatsapp_number',
          'email'
        )
    ),
    'At least one existing social/contact profile column is present.';

  return query
  select 'PROFILE', '04_existing_upi_column',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and column_name in ('upi_id', 'payment_upi_id')
        and table_name in ('hotels', 'hotel_info', 'hotel_settings')
    ),
    'An existing hotel UPI profile column is present.';

  return query
  select 'PROFILE', '05_existing_payment_qr_column',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and column_name in (
          'payment_qr_url',
          'payment_qr_path',
          'upi_qr_url'
        )
        and table_name in ('hotels', 'hotel_info', 'hotel_settings')
    ),
    'An existing hotel payment-QR field is present.';

  -- ========================================================================
  -- D. STORAGE
  -- ========================================================================

  return query
  select 'STORAGE', '01_storage_objects',
    to_regclass('storage.objects') is not null,
    'Supabase Storage objects relation exists.';

  return query
  select 'STORAGE', '02_storage_buckets',
    to_regclass('storage.buckets') is not null,
    'Supabase Storage buckets relation exists.';

  return query
  select 'STORAGE', '03_hotel_assets_bucket',
    exists (
      select 1
      from storage.buckets
      where id = 'hotel-assets'
    ),
    'Existing private hotel-assets bucket exists.';

  return query
  select 'STORAGE', '04_hotel_assets_private',
    coalesce((
      select not b.public
      from storage.buckets b
      where b.id = 'hotel-assets'
    ), false),
    'Existing hotel-assets bucket remains private.';

  return query
  select 'STORAGE', '05_guest_guide_media_bucket',
    exists (
      select 1
      from storage.buckets
      where id = 'guest-guide-media'
    ),
    'Dedicated guest-guide media bucket already exists.';

  return query
  select 'STORAGE', '06_storage_hotel_path_helper',
    to_regprocedure(
      'private.storage_object_hotel_id(text)'
    ) is not null,
    'Hotel-folder storage helper exists.';

  return query
  select 'STORAGE', '07_hotel_asset_select_policy',
    exists (
      select 1
      from pg_policies
      where schemaname = 'storage'
        and tablename = 'objects'
        and policyname = 'stayqr_hotel_assets_select'
    ),
    'Authenticated hotel-assets select policy exists.';

  return query
  select 'STORAGE', '08_hotel_asset_insert_policy',
    exists (
      select 1
      from pg_policies
      where schemaname = 'storage'
        and tablename = 'objects'
        and policyname = 'stayqr_hotel_assets_insert'
    ),
    'Hotel-managed upload policy exists.';

  return query
  select 'STORAGE', '09_image_mime_support',
    coalesce((
      select
        'image/jpeg' = any(allowed_mime_types)
        and 'image/png' = any(allowed_mime_types)
        and 'image/webp' = any(allowed_mime_types)
      from storage.buckets
      where id = 'hotel-assets'
    ), false),
    'Existing hotel-assets bucket supports JPG, PNG and WebP.';

  return query
  select 'STORAGE', '10_guest_media_public_read_policy',
    exists (
      select 1
      from pg_policies
      where schemaname = 'storage'
        and tablename = 'objects'
        and policyname ilike '%guest%guide%media%select%'
    ),
    'A guest-guide public-media read policy already exists.';

  -- ========================================================================
  -- E. LANGUAGE / GREETING READINESS
  -- ========================================================================

  return query
  select 'LANGUAGE', '01_locale_constraint_allows_indian_codes',
    exists (
      select 1
      from pg_constraint c
      join pg_class t on t.oid = c.conrelid
      join pg_namespace n on n.oid = t.relnamespace
      where n.nspname = 'public'
        and t.relname = 'hotel_guest_content'
        and c.contype = 'c'
        and pg_get_constraintdef(c.oid) ilike '%locale%'
    ),
    'Current locale constraint can be reviewed for Indian language codes.';

  foreach v_text in array array[
    'en','hi','mr','ta','te','bn','gu','kn','ml','pa','or','as'
  ]
  loop
    return query
    select
      'LANGUAGE',
      '02_existing_locale_' || v_text,
      exists (
        select 1
        from public.hotel_guest_content
        where locale = v_text
          and is_active
      ),
      format('Active %s guest-content row inventory.', v_text);
  end loop;

  return query
  select 'LANGUAGE', '03_multiple_locales_present',
    exists (
      select 1
      from public.hotel_guest_content
      where is_active
      group by hotel_id
      having count(distinct locale) >= 2
    ),
    'At least one hotel currently has multilingual content.';

  return query
  select 'LANGUAGE', '04_greetings_table',
    to_regclass('public.guest_guide_greetings') is not null,
    'Editable language-specific greetings table exists.';

  -- ========================================================================
  -- F. BUILDER / VERSIONING GAPS
  -- ========================================================================

  foreach v_text in array array[
    'guest_guide_settings',
    'guest_guide_sections',
    'guest_guide_section_translations',
    'guest_guide_items',
    'guest_guide_item_translations',
    'guest_guide_media',
    'guest_guide_payment_profiles',
    'guest_guide_greetings',
    'guest_guide_versions',
    'guest_guide_events'
  ]
  loop
    return query
    select
      'BUILDER',
      '01_table_' || v_text,
      to_regclass('public.' || v_text) is not null,
      format('Builder relation public.%s inventory.', v_text);
  end loop;

  foreach v_text in array array[
    'get_guest_guide_builder',
    'upsert_guest_guide_settings',
    'upsert_guest_guide_section',
    'upsert_guest_guide_item',
    'upsert_guest_guide_media',
    'upsert_guest_guide_greeting',
    'upsert_guest_guide_payment_profile',
    'publish_guest_guide',
    'record_guest_guide_event'
  ]
  loop
    return query
    select
      'BUILDER',
      '02_rpc_' || v_text,
      exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = v_text
      ),
      format('Builder RPC public.%s inventory.', v_text);
  end loop;

  return query
  select 'BUILDER', '03_template_setting',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'guest_guide_settings'
        and column_name = 'template_key'
    ),
    'Template selection storage exists.';

  return query
  select 'BUILDER', '04_enabled_locales_setting',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'guest_guide_settings'
        and column_name = 'enabled_locales'
    ),
    'Hotel-enabled locale storage exists.';

  return query
  select 'BUILDER', '05_draft_publish_status',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'guest_guide_settings'
        and column_name in ('status', 'publish_status')
    ),
    'Draft/published state storage exists.';

  return query
  select 'BUILDER', '06_section_ordering',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'guest_guide_sections'
        and column_name = 'sort_order'
    ),
    'Guide section ordering exists.';

  return query
  select 'BUILDER', '07_section_visibility',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'guest_guide_sections'
        and column_name in ('is_enabled', 'is_visible')
    ),
    'Guide section visibility exists.';

  return query
  select 'BUILDER', '08_item_scope',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'guest_guide_items'
        and column_name = 'scope_type'
    ),
    'Hotel/room-type/room item scope exists.';

  return query
  select 'BUILDER', '09_media_scope',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'guest_guide_media'
        and column_name = 'scope_type'
    ),
    'Hotel/room-type/room media scope exists.';

  return query
  select 'BUILDER', '10_version_snapshot',
    exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'guest_guide_versions'
        and column_name in ('snapshot', 'snapshot_json')
    ),
    'Published guide snapshot/version storage exists.';

  -- ========================================================================
  -- G. SECURITY PRIMITIVES
  -- ========================================================================

  return query
  select 'SECURITY', '01_user_has_permission',
    to_regprocedure(
      'private.user_has_permission(uuid,text)'
    ) is not null,
    'Canonical permission helper exists.';

  return query
  select 'SECURITY', '02_user_has_hotel_access',
    to_regprocedure(
      'private.user_has_hotel_access(uuid)'
    ) is not null,
    'Canonical hotel-access helper exists.';

  return query
  select 'SECURITY', '03_token_resolver',
    to_regprocedure(
      'private.resolve_guest_access_token(text,text,boolean)'
    ) is not null,
    'Signed guest-token resolver exists.';

  return query
  select 'SECURITY', '04_pgcrypto_uuid',
    to_regprocedure('gen_random_uuid()') is not null,
    'UUID generation function exists.';

  return query
  select 'SECURITY', '05_rooms_rls',
    coalesce((
      select c.relrowsecurity
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname = 'rooms'
    ), false),
    'Rooms RLS is enabled.';

  return query
  select 'SECURITY', '06_room_types_rls',
    coalesce((
      select c.relrowsecurity
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname = 'room_types'
    ), false),
    'Room types RLS is enabled.';

  return query
  select 'SECURITY', '07_hotel_guest_content_rls',
    coalesce((
      select c.relrowsecurity
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname = 'hotel_guest_content'
    ), false),
    'Current guest content RLS is enabled.';

  return query
  select 'SECURITY', '08_anon_no_rooms_read',
    not has_table_privilege(
      'anon',
      'public.rooms',
      'SELECT'
    ),
    'Anonymous guests cannot directly enumerate rooms.';

  return query
  select 'SECURITY', '09_anon_no_guest_content_write',
    not (
      has_table_privilege(
        'anon',
        'public.hotel_guest_content',
        'INSERT'
      )
      or has_table_privilege(
        'anon',
        'public.hotel_guest_content',
        'UPDATE'
      )
      or has_table_privilege(
        'anon',
        'public.hotel_guest_content',
        'DELETE'
      )
    ),
    'Anonymous guests cannot directly edit current guest content.';

  return query
  select 'SECURITY', '10_service_role_not_public_setting',
    not exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and column_name ilike '%service_role%'
    ),
    'No public builder column is intended to contain a service-role key.';

  -- ========================================================================
  -- H. CURRENT RUNTIME CONTENT
  -- ========================================================================

  v_count := private.day14_builder_safe_count_rev2(
    'public.hotel_guest_content',
    'is_active'
  );
  return query
  select 'RUNTIME', '01_active_localized_content_rows',
    v_count >= 0,
    format('%s active localized content row(s) exist.', v_count);

  v_count := private.day14_builder_safe_count_rev2(
    'public.amenities',
    'is_active and guest_visible'
  );
  return query
  select 'RUNTIME', '02_guest_visible_amenities',
    v_count >= 0,
    format('%s active guest-visible amenity row(s) exist.', v_count);

  v_count := private.day14_builder_safe_count_rev2(
    'public.guest_feedback',
    null
  );
  return query
  select 'RUNTIME', '03_feedback_rows',
    v_count >= 0,
    format('%s private feedback row(s) exist.', v_count);

  v_count := private.day14_builder_safe_count_rev2(
    'public.guest_access_tokens',
    $$status = 'active' and expires_at > now()$$
  );
  return query
  select 'RUNTIME', '04_active_signed_tokens',
    v_count >= 0,
    format('%s currently active signed guest token(s) exist.', v_count);

  v_count := private.day14_builder_safe_count_rev2(
    'public.guest_access_tokens',
    $$status = 'revoked'$$
  );
  return query
  select 'RUNTIME', '05_revoked_token_evidence',
    v_count >= 0,
    format('%s revoked token row(s) exist.', v_count);

  v_count := private.day14_builder_safe_count_rev2(
    'public.guest_review_rewards',
    null
  );
  return query
  select 'RUNTIME', '06_review_reward_events',
    v_count >= 0,
    format('%s review/reward audit row(s) exist.', v_count);

end;
$_$;


ALTER FUNCTION "private"."day14_builder_preflight_rev2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day14_builder_safe_count_rev2"("p_relation" "text", "p_where" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_relation regclass;
  v_sql text;
  v_count bigint := 0;
begin
  v_relation := to_regclass(p_relation);

  if v_relation is null then
    return 0;
  end if;

  v_sql := format('select count(*) from %s', v_relation);

  if nullif(trim(coalesce(p_where, '')), '') is not null then
    v_sql := v_sql || ' where ' || p_where;
  end if;

  execute v_sql into v_count;
  return coalesce(v_count, 0);
exception
  when others then
    return -1;
end;
$$;


ALTER FUNCTION "private"."day14_builder_safe_count_rev2"("p_relation" "text", "p_where" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day14_builder_touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "private"."day14_builder_touch_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day14_day15_preflight_inventory_rev2"() RETURNS TABLE("area" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  r record;
  v_exists boolean;
  v_count bigint;
  v_aux bigint;
  v_text text;
begin
  -- -----------------------------------------------------------------------
  -- Core table inventory
  -- -----------------------------------------------------------------------
  for r in
    select * from (values
      ('DAY14', 'hotels', 'Hotel profile and guest-facing content source'),
      ('DAY14', 'rooms', 'Room binding for signed guest access'),
      ('DAY14', 'guest_sessions', 'Active-stay binding for signed guest access'),
      ('DAY14', 'guest_access_tokens', 'Signed, rotating and revocable access token lifecycle'),
      ('DAY14', 'amenities', 'Hotel-configurable guest-visible amenities'),
      ('DAY14', 'guest_feedback', 'Private guest feedback and consent workflow'),
      ('DAY14', 'hotel_guest_content', 'Multilingual-ready guest guide content'),
      ('DAY14', 'guest_review_rewards', 'Review/reward audit and redemption workflow'),
      ('DAY15', 'menu_categories', 'Hotel-configurable menu categories'),
      ('DAY15', 'menu_items', 'Hotel-configurable menu items'),
      ('DAY15', 'menu_item_modifier_groups', 'Modifier groups'),
      ('DAY15', 'menu_item_modifiers', 'Modifier choices and price deltas'),
      ('DAY15', 'food_orders', 'Guest food-order header'),
      ('DAY15', 'food_order_items', 'Guest food-order line items'),
      ('DAY15', 'food_order_item_modifiers', 'Immutable selected modifier snapshots'),
      ('DAY15', 'service_request_types', 'Dynamic service categories and routing'),
      ('DAY15', 'service_requests', 'Service request operational workflow'),
      ('DAY15', 'guest_notifications', 'Guest-visible status notification history'),
      ('DAY15', 'service_request_events', 'Immutable service workflow event history')
    ) as t(area_name, relation_name, purpose)
  loop
    v_exists := to_regclass('public.' || r.relation_name) is not null;
    area := r.area_name;
    test_name := 'table_' || r.relation_name;
    passed := v_exists;
    details := case when v_exists
      then r.purpose || ' table exists.'
      else r.purpose || ' table is absent.'
    end;
    return next;
  end loop;

  -- -----------------------------------------------------------------------
  -- Required/expected columns used by the current frontend and roadmap
  -- -----------------------------------------------------------------------
  for r in
    select * from (values
      ('DAY14','hotels','slug'),
      ('DAY14','hotels','status'),
      ('DAY14','hotels','hotel_name'),
      ('DAY14','hotels','address'),
      ('DAY14','hotels','about'),
      ('DAY14','hotels','wifi_name'),
      ('DAY14','hotels','wifi_password'),
      ('DAY14','hotels','checkin_time'),
      ('DAY14','hotels','checkout_time'),
      ('DAY14','hotels','breakfast_time'),
      ('DAY14','hotels','reception_phone'),
      ('DAY14','hotels','emergency_phone'),
      ('DAY14','hotels','hotel_rules'),
      ('DAY14','hotels','google_review_url'),
      ('DAY14','hotels','reward_enabled'),
      ('DAY14','hotels','reward_title'),
      ('DAY14','hotels','reward_description'),
      ('DAY14','amenities','hotel_id'),
      ('DAY14','amenities','name'),
      ('DAY14','amenities','description'),
      ('DAY14','amenities','instructions'),
      ('DAY14','amenities','icon'),
      ('DAY14','amenities','guest_visible'),
      ('DAY14','amenities','is_active'),
      ('DAY14','amenities','sort_order'),
      ('DAY14','guest_access_tokens','token_nonce'),
      ('DAY14','guest_access_tokens','hotel_id'),
      ('DAY14','guest_access_tokens','room_id'),
      ('DAY14','guest_access_tokens','guest_session_id'),
      ('DAY14','guest_access_tokens','status'),
      ('DAY14','guest_access_tokens','expires_at'),
      ('DAY14','guest_access_tokens','revoked_at'),
      ('DAY14','guest_access_tokens','revocation_reason'),
      ('DAY15','menu_categories','hotel_id'),
      ('DAY15','menu_categories','name'),
      ('DAY15','menu_categories','code'),
      ('DAY15','menu_categories','is_active'),
      ('DAY15','menu_categories','sort_order'),
      ('DAY15','menu_items','hotel_id'),
      ('DAY15','menu_items','category_id'),
      ('DAY15','menu_items','item_name'),
      ('DAY15','menu_items','description'),
      ('DAY15','menu_items','price'),
      ('DAY15','menu_items','is_available'),
      ('DAY15','food_orders','hotel_id'),
      ('DAY15','food_orders','guest_session_id'),
      ('DAY15','food_orders','order_status'),
      ('DAY15','food_orders','total_amount'),
      ('DAY15','food_order_items','hotel_id'),
      ('DAY15','food_order_items','order_id'),
      ('DAY15','food_order_items','menu_item_id'),
      ('DAY15','food_order_items','quantity'),
      ('DAY15','food_order_items','price'),
      ('DAY15','service_request_types','hotel_id'),
      ('DAY15','service_request_types','name'),
      ('DAY15','service_request_types','code'),
      ('DAY15','service_request_types','department'),
      ('DAY15','service_request_types','default_priority'),
      ('DAY15','service_request_types','guest_visible'),
      ('DAY15','service_request_types','is_active'),
      ('DAY15','service_requests','hotel_id'),
      ('DAY15','service_requests','guest_session_id'),
      ('DAY15','service_requests','request_type_id'),
      ('DAY15','service_requests','status'),
      ('DAY15','service_requests','priority'),
      ('DAY15','service_requests','assigned_staff_id'),
      ('DAY15','service_requests','estimated_minutes'),
      ('DAY15','service_requests','estimated_arrival_time'),
      ('DAY15','service_requests','created_at'),
      ('DAY15','service_requests','accepted_at'),
      ('DAY15','service_requests','started_at'),
      ('DAY15','service_requests','completed_at')
    ) as c(area_name, table_name, column_name)
  loop
    select exists (
      select 1
      from information_schema.columns ic
      where ic.table_schema = 'public'
        and ic.table_name = r.table_name
        and ic.column_name = r.column_name
    ) into v_exists;

    area := r.area_name;
    test_name := 'column_' || r.table_name || '_' || r.column_name;
    passed := v_exists;
    details := format('public.%s.%s %s.', r.table_name, r.column_name,
      case when v_exists then 'exists' else 'is absent' end);
    return next;
  end loop;

  -- -----------------------------------------------------------------------
  -- Existing guest/public and hotel-admin RPC contracts
  -- -----------------------------------------------------------------------
  for r in
    select * from (values
      ('DAY14','resolve_guest_portal(text,text)','Guest portal resolver'),
      ('DAY14','get_guest_access_links(uuid)','Hotel QR/link inventory'),
      ('DAY14','rotate_guest_access_token(uuid,uuid,text)','Manual access rotation'),
      ('DAY14','revoke_guest_access_token(uuid,uuid,text)','Manual access revocation'),
      ('DAY14','submit_guest_feedback(text,text,integer,text,boolean)','Private guest feedback'),
      ('DAY14','record_guest_review_reward_action(text,text,text)','Review/reward audit action'),
      ('DAY14','get_hotel_guest_content(uuid,text)','Hotel content editor read contract'),
      ('DAY14','upsert_hotel_guest_content(uuid,text,jsonb)','Hotel content editor write contract'),
      ('DAY15','get_guest_food_menu(text,text)','Signed guest menu'),
      ('DAY15','place_guest_food_order(text,text,jsonb)','Signed idempotent food ordering'),
      ('DAY15','get_guest_food_orders(text,text)','Signed guest order tracking'),
      ('DAY15','cancel_guest_food_order(text,text,uuid,text)','Signed order cancellation'),
      ('DAY15','update_food_order_status(uuid,uuid,text,integer,text)','Trusted kitchen status transition'),
      ('DAY15','post_food_order_to_folio(uuid,uuid)','Exactly-once food folio posting'),
      ('DAY15','create_guest_service_request(text,text,text)','Signed guest request creation'),
      ('DAY15','get_guest_service_requests(text,text)','Signed guest request tracking'),
      ('DAY15','update_service_request_status(uuid,uuid,text,integer,text)','Trusted service transition'),
      ('DAY15','escalate_overdue_service_requests(uuid)','SLA escalation reconciliation'),
      ('DAY15','get_service_operations_analytics(uuid,timestamptz,timestamptz)','Service analytics')
    ) as f(area_name, signature, purpose)
  loop
    v_exists := to_regprocedure('public.' || r.signature) is not null;
    area := r.area_name;
    test_name := 'function_' || regexp_replace(split_part(r.signature, '(', 1), '[^a-z0-9_]+', '_', 'g');
    passed := v_exists;
    details := case when v_exists
      then r.purpose || ' function exists with expected signature.'
      else r.purpose || ' function/signature is absent.'
    end;
    return next;
  end loop;

  -- -----------------------------------------------------------------------
  -- RLS inventory for all existing Day 14/15 business tables
  -- -----------------------------------------------------------------------
  for r in
    select unnest(array[
      'hotels','guest_access_tokens','amenities','guest_feedback','hotel_guest_content',
      'guest_review_rewards','menu_categories','menu_items','menu_item_modifier_groups',
      'menu_item_modifiers','food_orders','food_order_items','food_order_item_modifiers',
      'service_request_types','service_requests','guest_notifications','service_request_events'
    ]) as relation_name
  loop
    if to_regclass('public.' || r.relation_name) is null then
      area := case when r.relation_name in ('hotels','guest_access_tokens','amenities','guest_feedback','hotel_guest_content','guest_review_rewards') then 'DAY14' else 'DAY15' end;
      test_name := 'rls_' || r.relation_name;
      passed := false;
      details := 'Table is absent, so RLS cannot be verified.';
      return next;
    else
      select c.relrowsecurity
      into v_exists
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname = r.relation_name;

      area := case when r.relation_name in ('hotels','guest_access_tokens','amenities','guest_feedback','hotel_guest_content','guest_review_rewards') then 'DAY14' else 'DAY15' end;
      test_name := 'rls_' || r.relation_name;
      passed := coalesce(v_exists, false);
      details := format('RLS on public.%s is %s.', r.relation_name,
        case when v_exists then 'enabled' else 'not enabled' end);
      return next;
    end if;
  end loop;

  -- -----------------------------------------------------------------------
  -- Browser direct-write exposure checks for existing operational tables
  -- -----------------------------------------------------------------------
  for r in
    select * from (values
      ('DAY14','guest_access_tokens'),
      ('DAY14','amenities'),
      ('DAY14','guest_feedback'),
      ('DAY14','hotel_guest_content'),
      ('DAY14','guest_review_rewards'),
      ('DAY15','menu_categories'),
      ('DAY15','menu_items'),
      ('DAY15','menu_item_modifier_groups'),
      ('DAY15','menu_item_modifiers'),
      ('DAY15','food_orders'),
      ('DAY15','food_order_items'),
      ('DAY15','food_order_item_modifiers'),
      ('DAY15','service_request_types'),
      ('DAY15','service_requests'),
      ('DAY15','guest_notifications'),
      ('DAY15','service_request_events')
    ) as t(area_name, relation_name)
  loop
    area := r.area_name;
    test_name := 'anon_no_direct_write_' || r.relation_name;

    if to_regclass('public.' || r.relation_name) is null then
      passed := false;
      details := 'Table is absent.';
    else
      passed := not (
        has_table_privilege('anon', 'public.' || r.relation_name, 'INSERT')
        or has_table_privilege('anon', 'public.' || r.relation_name, 'UPDATE')
        or has_table_privilege('anon', 'public.' || r.relation_name, 'DELETE')
      );
      details := case when passed
        then 'anon has no direct INSERT/UPDATE/DELETE privilege.'
        else 'anon retains at least one direct write privilege.'
      end;
    end if;
    return next;
  end loop;

  -- -----------------------------------------------------------------------
  -- Current runtime baseline counts (safe dynamic reads)
  -- -----------------------------------------------------------------------
  if to_regclass('public.guest_access_tokens') is not null then
    execute 'select count(*) from public.guest_access_tokens' into v_count;
    execute $q$select count(*) from public.guest_access_tokens where status = 'active' and expires_at > now()$q$ into v_aux;
    area := 'DAY14'; test_name := 'baseline_guest_access_tokens'; passed := true;
    details := format('%s total tokens; %s currently active and unexpired.', v_count, v_aux); return next;

    execute $q$select count(*) from public.guest_access_tokens where status = 'active' and expires_at <= now()$q$ into v_count;
    area := 'DAY14'; test_name := 'active_tokens_not_expired'; passed := v_count = 0;
    details := format('%s active token(s) are already past expires_at.', v_count); return next;

    execute $q$
      select count(*) from (
        select guest_session_id
        from public.guest_access_tokens
        where status = 'active'
        group by guest_session_id
        having count(*) > 1
      ) d
    $q$ into v_count;
    area := 'DAY14'; test_name := 'one_active_token_per_stay'; passed := v_count = 0;
    details := format('%s stay(s) have duplicate active access tokens.', v_count); return next;
  end if;

  if to_regclass('public.amenities') is not null then
    execute 'select count(*) from public.amenities' into v_count;
    execute 'select count(*) from public.amenities where is_active and guest_visible' into v_aux;
    area := 'DAY14'; test_name := 'baseline_amenities'; passed := true;
    details := format('%s total amenities; %s active and guest-visible.', v_count, v_aux); return next;
  end if;

  if to_regclass('public.menu_items') is not null then
    execute 'select count(*) from public.menu_items' into v_count;
    execute 'select count(*) from public.menu_items where is_available' into v_aux;
    area := 'DAY15'; test_name := 'baseline_menu_items'; passed := true;
    details := format('%s total menu items; %s currently available.', v_count, v_aux); return next;
  end if;

  if to_regclass('public.food_orders') is not null then
    execute 'select count(*) from public.food_orders' into v_count;
    execute $q$select count(*) from public.food_orders where order_status not in ('delivered','cancelled')$q$ into v_aux;
    area := 'DAY15'; test_name := 'baseline_food_orders'; passed := true;
    details := format('%s total food orders; %s currently open.', v_count, v_aux); return next;
  end if;

  if to_regclass('public.service_request_types') is not null then
    execute 'select count(*) from public.service_request_types' into v_count;
    execute 'select count(*) from public.service_request_types where is_active and guest_visible' into v_aux;
    area := 'DAY15'; test_name := 'baseline_service_request_types'; passed := true;
    details := format('%s total service categories; %s active and guest-visible.', v_count, v_aux); return next;
  end if;

  if to_regclass('public.service_requests') is not null then
    execute 'select count(*) from public.service_requests' into v_count;
    execute $q$select count(*) from public.service_requests where status not in ('completed','cancelled')$q$ into v_aux;
    area := 'DAY15'; test_name := 'baseline_service_requests'; passed := true;
    details := format('%s total service requests; %s currently open.', v_count, v_aux); return next;
  end if;

  -- -----------------------------------------------------------------------
  -- Existing policy/function exposure summary
  -- -----------------------------------------------------------------------
  select count(*)::bigint
  into v_count
  from pg_policies p
  where p.schemaname = 'public'
    and p.tablename = any(array[
      'guest_access_tokens','amenities','guest_feedback','hotel_guest_content',
      'guest_review_rewards','menu_categories','menu_items','menu_item_modifier_groups',
      'menu_item_modifiers','food_orders','food_order_items','food_order_item_modifiers',
      'service_request_types','service_requests','guest_notifications','service_request_events'
    ]);
  area := 'CROSS'; test_name := 'relevant_policy_count'; passed := true;
  details := format('%s RLS policies currently exist across Day 14/15 relevant tables.', v_count); return next;

  select string_agg(p.proname, ', ' order by p.proname)
  into v_text
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname like '%guest%'
    and has_function_privilege('anon', p.oid, 'EXECUTE');
  area := 'CROSS'; test_name := 'anon_guest_rpc_inventory'; passed := true;
  details := 'anon executable guest RPCs: ' || coalesce(v_text, '(none)'); return next;
end;
$_$;


