CREATE OR REPLACE FUNCTION "private"."day14_mark_guide_draft"("p_hotel_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.guest_guide_settings
  set
    publish_status = 'draft',
    draft_revision = draft_revision + 1,
    updated_by = auth.uid(),
    updated_at = now()
  where hotel_id = p_hotel_id;
end;
$$;


