CREATE OR REPLACE FUNCTION "private"."day15_audit_066_final_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_food_delivered public.food_orders%rowtype;
  v_food_cancelled public.food_orders%rowtype;
  v_service public.service_requests%rowtype;
  v_count bigint;
  v_amount numeric(14,2);
  v_text text;
  v_bool boolean;
begin
  -- ========================================================================
  -- A. Re-run every accepted migration contract: 220 rows.
  -- ========================================================================
  return query
  select
    'M051_' || a.suite,
    a.test_name,
    a.passed,
    a.details
  from private.day15_migration_051_acceptance_rev1() a;

  return query
  select
    'M052_' || a.suite,
    a.test_name,
    a.passed,
    a.details
  from private.day15_migration_052_acceptance_rev1() a;

  return query
  select
    'M053_' || a.suite,
    a.test_name,
    a.passed,
    a.details
  from private.day15_migration_053_acceptance_rev1() a;

  -- ========================================================================
  -- B. Delivered taxed/modifier food order runtime: 24 rows.
  -- ========================================================================
  select fo.*
  into v_food_delivered
  from public.food_orders fo
  where fo.order_status = 'delivered'
    and fo.modifier_amount > 0
    and fo.tax_amount > 0
    and exists (
      select 1
      from public.kitchen_tickets kt
      where kt.hotel_id = fo.hotel_id
        and kt.food_order_id = fo.id
        and kt.print_count >= 1
    )
    and exists (
      select 1
      from public.folio_items fi
      where fi.hotel_id = fo.hotel_id
        and fi.source_table = 'food_orders'
        and fi.source_id = fo.id
        and fi.posting_status = 'posted'
    )
  order by fo.delivered_at desc nulls last, fo.created_at desc
  limit 1;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'controlled_order_exists';
  passed := v_food_delivered.id is not null;
  details := case
    when passed then 'A delivered taxed/modifier order with KOT and folio evidence exists.'
    else 'No controlled delivered taxed/modifier order was found.'
  end;
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'hotel_room_guest_bound';
  passed := coalesce(
    v_food_delivered.hotel_id is not null
    and v_food_delivered.room_id is not null
    and v_food_delivered.guest_id is not null,
    false
  );
  details := 'Delivered order is bound to a hotel, room and guest.';
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'guest_session_bound';
  passed := v_food_delivered.guest_session_id is not null;
  details := 'Delivered order is bound to the active guest stay.';
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'delivered_state_and_timestamp';
  passed := coalesce(
    v_food_delivered.order_status = 'delivered'
    and v_food_delivered.delivered_at is not null,
    false
  );
  details := 'Order reached delivered with a delivery timestamp.';
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'modifier_amount_positive';
  passed := coalesce(v_food_delivered.modifier_amount > 0, false);
  details := format(
    'Modifier amount: %s.',
    coalesce(v_food_delivered.modifier_amount::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'tax_amount_positive';
  passed := coalesce(v_food_delivered.tax_amount > 0, false);
  details := format(
    'Tax amount: %s.',
    coalesce(v_food_delivered.tax_amount::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'total_equation';
  passed := coalesce(
    v_food_delivered.total_amount = round(
      v_food_delivered.subtotal_amount
      + v_food_delivered.modifier_amount
      + v_food_delivered.tax_amount,
      2
    ),
    false
  );
  details := 'Subtotal + modifiers + tax equals total.';
  return next;

  select count(*)
  into v_count
  from public.food_order_items foi
  join public.food_order_item_modifiers foim
    on foim.hotel_id = foi.hotel_id
   and foim.food_order_item_id = foi.id
  where foi.hotel_id = v_food_delivered.hotel_id
    and foi.order_id = v_food_delivered.id;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'modifier_snapshot_exists';
  passed := v_count > 0;
  details := format('%s selected modifier snapshot row(s).', v_count);
  return next;

  for v_text in
    select unnest(array[
      'pending',
      'accepted',
      'preparing',
      'ready',
      'out_for_delivery',
      'delivered'
    ])
  loop
    select exists (
      select 1
      from public.food_order_events foe
      where foe.hotel_id = v_food_delivered.hotel_id
        and foe.food_order_id = v_food_delivered.id
        and foe.to_status = v_text
    )
    into v_bool;

    suite := 'RUNTIME_FOOD_DELIVERED';
    test_name := 'lifecycle_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('Lifecycle event to %s exists.', v_text);
    return next;
  end loop;

  select count(*)
  into v_count
  from public.kitchen_tickets kt
  where kt.hotel_id = v_food_delivered.hotel_id
    and kt.food_order_id = v_food_delivered.id;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'kot_exactly_one_identity';
  passed := v_count = 1;
  details := format('%s KOT identity row(s).', v_count);
  return next;

  select coalesce(max(kt.print_count), 0)
  into v_count
  from public.kitchen_tickets kt
  where kt.hotel_id = v_food_delivered.hotel_id
    and kt.food_order_id = v_food_delivered.id;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'kot_printed';
  passed := v_count >= 1;
  details := format('KOT print count: %s.', v_count);
  return next;

  select max(kt.ticket_number)
  into v_text
  from public.kitchen_tickets kt
  where kt.hotel_id = v_food_delivered.hotel_id
    and kt.food_order_id = v_food_delivered.id;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'kot_number_format';
  passed := coalesce(v_text ~ '^KOT-[0-9]{8}-[A-F0-9]{8}$', false);
  details := 'Ticket number: ' || coalesce(v_text, 'missing') || '.';
  return next;

  select count(*), coalesce(sum(fi.amount), 0)
  into v_count, v_amount
  from public.folio_items fi
  where fi.hotel_id = v_food_delivered.hotel_id
    and fi.source_table = 'food_orders'
    and fi.source_id = v_food_delivered.id
    and fi.posting_status = 'posted';

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'folio_exactly_once';
  passed := v_count = 1;
  details := format('%s posted folio row(s).', v_count);
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'folio_amount_matches';
  passed := coalesce(v_amount = v_food_delivered.total_amount, false);
  details := format(
    'Folio amount %s; order total %s.',
    v_amount,
    coalesce(v_food_delivered.total_amount::text, 'missing')
  );
  return next;

  for v_text in
    select unnest(array[
      'accepted',
      'preparing',
      'ready',
      'delivered'
    ])
  loop
    select exists (
      select 1
      from public.guest_notifications gn
      where gn.hotel_id = v_food_delivered.hotel_id
        and gn.source_type = 'food_order'
        and gn.source_id = v_food_delivered.id
        and gn.event_key = v_text
    )
    into v_bool;

    suite := 'RUNTIME_FOOD_DELIVERED';
    test_name := 'guest_notification_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('Guest notification %s exists.', v_text);
    return next;
  end loop;

  -- ========================================================================
  -- C. Guest-cancelled food order runtime: 10 rows.
  -- ========================================================================
  select fo.*
  into v_food_cancelled
  from public.food_orders fo
  where fo.order_status = 'cancelled'
    and exists (
      select 1
      from public.food_order_events foe
      where foe.hotel_id = fo.hotel_id
        and foe.food_order_id = fo.id
        and foe.event_type = 'guest_cancelled'
    )
    and not exists (
      select 1
      from public.folio_items fi
      where fi.hotel_id = fo.hotel_id
        and fi.source_table = 'food_orders'
        and fi.source_id = fo.id
        and fi.posting_status = 'posted'
    )
  order by fo.cancelled_at desc nulls last, fo.created_at desc
  limit 1;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'controlled_cancelled_order_exists';
  passed := v_food_cancelled.id is not null;
  details := 'A guest-cancelled order without a folio posting exists.';
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'cancelled_status';
  passed := coalesce(v_food_cancelled.order_status = 'cancelled', false);
  details := 'Order status is cancelled.';
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'cancel_timestamp_and_reason';
  passed := coalesce(
    v_food_cancelled.cancelled_at is not null
    and nullif(trim(v_food_cancelled.cancellation_reason), '') is not null,
    false
  );
  details := 'Cancellation timestamp and reason are stored.';
  return next;

  select count(*)
  into v_count
  from public.food_order_events foe
  where foe.hotel_id = v_food_cancelled.hotel_id
    and foe.food_order_id = v_food_cancelled.id
    and foe.event_type = 'guest_cancelled';

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'guest_cancel_event_exists';
  passed := v_count >= 1;
  details := format('%s guest cancellation event row(s).', v_count);
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'guest_cancel_event_idempotent';
  passed := v_count = 1;
  details := format('%s guest cancellation event row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.guest_notifications gn
  where gn.hotel_id = v_food_cancelled.hotel_id
    and gn.source_type = 'food_order'
    and gn.source_id = v_food_cancelled.id
    and gn.event_key = 'cancelled';

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'cancel_notification_exists';
  passed := v_count = 1;
  details := format('%s cancellation notification row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.folio_items fi
  where fi.hotel_id = v_food_cancelled.hotel_id
    and fi.source_table = 'food_orders'
    and fi.source_id = v_food_cancelled.id
    and fi.posting_status = 'posted';

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'no_folio_posting';
  passed := v_count = 0;
  details := format('%s posted folio row(s).', v_count);
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'folio_pointer_empty';
  passed := v_food_cancelled.folio_item_id is null;
  details := 'Cancelled order has no folio_item_id.';
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'not_delivered';
  passed := v_food_cancelled.delivered_at is null;
  details := 'Cancelled order has no delivered timestamp.';
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'amount_preserved';
  passed := coalesce(v_food_cancelled.total_amount >= 0, false);
  details := format(
    'Cancelled order amount retained as %s.',
    coalesce(v_food_cancelled.total_amount::text, 'missing')
  );
  return next;

  -- ========================================================================
  -- D. Escalated, assigned and completed service runtime: 20 rows.
  -- ========================================================================
  select sr.*
  into v_service
  from public.service_requests sr
  where sr.status = 'completed'
    and sr.completed_at is not null
    and sr.escalation_level >= 1
    and sr.assigned_staff_id is not null
    and sr.estimated_minutes is not null
    and exists (
      select 1
      from public.service_escalations se
      where se.hotel_id = sr.hotel_id
        and se.service_request_id = sr.id
        and se.escalation_level = 1
    )
  order by sr.completed_at desc, sr.created_at desc
  limit 1;

  suite := 'RUNTIME_SERVICE';
  test_name := 'controlled_completed_escalated_request_exists';
  passed := v_service.id is not null;
  details := 'An escalated, assigned, ETA-set and completed service request exists.';
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'guest_session_bound';
  passed := v_service.guest_session_id is not null;
  details := 'Service request is bound to the guest stay.';
  return next;

  select exists (
    select 1
    from public.service_request_types srt
    where srt.hotel_id = v_service.hotel_id
      and srt.id = v_service.request_type_id
  )
  into v_bool;

  suite := 'RUNTIME_SERVICE';
  test_name := 'dynamic_type_exists';
  passed := coalesce(v_bool, false);
  details := 'Request uses a dynamic service catalogue type.';
  return next;

  select exists (
    select 1
    from public.service_request_types srt
    where srt.hotel_id = v_service.hotel_id
      and srt.id = v_service.request_type_id
      and srt.department = v_service.department
  )
  into v_bool;

  suite := 'RUNTIME_SERVICE';
  test_name := 'department_routing_matches_catalogue';
  passed := coalesce(v_bool, false);
  details := 'Request department matches its catalogue type.';
  return next;

  select exists (
    select 1
    from public.staff s
    where s.hotel_id = v_service.hotel_id
      and s.id = v_service.assigned_staff_id
      and s.status = 'active'
  )
  into v_bool;

  suite := 'RUNTIME_SERVICE';
  test_name := 'assigned_staff_is_active';
  passed := coalesce(v_bool, false);
  details := 'Assigned staff member is active in the same hotel.';
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'eta_is_set';
  passed := coalesce(
    v_service.estimated_minutes between 1 and 1440
    and v_service.estimated_arrival_time is not null,
    false
  );
  details := format(
    'Estimated minutes: %s.',
    coalesce(v_service.estimated_minutes::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'completed_state_and_timestamp';
  passed := coalesce(
    v_service.status = 'completed'
    and v_service.completed_at is not null,
    false
  );
  details := 'Service reached completed with a completion timestamp.';
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'escalation_level_recorded';
  passed := coalesce(v_service.escalation_level >= 1, false);
  details := format(
    'Escalation level: %s.',
    coalesce(v_service.escalation_level::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'escalated_timestamp_recorded';
  passed := v_service.escalated_at is not null;
  details := 'Escalated timestamp is stored.';
  return next;

  select count(*)
  into v_count
  from public.service_escalations se
  where se.hotel_id = v_service.hotel_id
    and se.service_request_id = v_service.id
    and se.escalation_level = 1;

  suite := 'RUNTIME_SERVICE';
  test_name := 'level_one_escalation_exactly_once';
  passed := v_count = 1;
  details := format('%s level-one escalation row(s).', v_count);
  return next;

  for v_text in
    select unnest(array[
      'sla_escalated',
      'assignment_changed'
    ])
  loop
    select exists (
      select 1
      from public.service_request_events sre
      where sre.hotel_id = v_service.hotel_id
        and sre.service_request_id = v_service.id
        and sre.event_type = v_text
    )
    into v_bool;

    suite := 'RUNTIME_SERVICE';
    test_name := 'event_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('%s event exists.', v_text);
    return next;
  end loop;

  for v_text in
    select unnest(array[
      'in_progress',
      'completed'
    ])
  loop
    select exists (
      select 1
      from public.service_request_events sre
      where sre.hotel_id = v_service.hotel_id
        and sre.service_request_id = v_service.id
        and sre.event_type = 'status_changed'
        and sre.to_status = v_text
    )
    into v_bool;

    suite := 'RUNTIME_SERVICE';
    test_name := 'status_event_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('Status event to %s exists.', v_text);
    return next;
  end loop;

  select exists (
    select 1
    from public.guest_notifications gn
    where gn.hotel_id = v_service.hotel_id
      and gn.source_type = 'service_request'
      and gn.source_id = v_service.id
      and gn.event_key like 'escalated-%'
  )
  into v_bool;

  suite := 'RUNTIME_SERVICE';
  test_name := 'guest_notification_escalated';
  passed := coalesce(v_bool, false);
  details := 'Guest escalation notification exists.';
  return next;

  for v_text in
    select unnest(array[
      'in_progress',
      'completed'
    ])
  loop
    select exists (
      select 1
      from public.guest_notifications gn
      where gn.hotel_id = v_service.hotel_id
        and gn.source_type = 'service_request'
        and gn.source_id = v_service.id
        and gn.event_key = v_text
    )
    into v_bool;

    suite := 'RUNTIME_SERVICE';
    test_name := 'guest_notification_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('Guest notification %s exists.', v_text);
    return next;
  end loop;

  select count(*)
  into v_count
  from public.service_requests sr
  where sr.hotel_id = v_service.hotel_id
    and sr.status in ('pending','accepted','in_progress','escalated')
    and coalesce(sr.escalation_due_at, sr.sla_due_at) <= now();

  suite := 'RUNTIME_SERVICE';
  test_name := 'no_active_overdue_requests';
  passed := v_count = 0;
  details := format('%s active overdue request(s) remain.', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select se.hotel_id, se.service_request_id, se.escalation_level
    from public.service_escalations se
    where se.hotel_id = v_service.hotel_id
    group by se.hotel_id, se.service_request_id, se.escalation_level
    having count(*) > 1
  ) duplicated;

  suite := 'RUNTIME_SERVICE';
  test_name := 'escalation_reconciliation_idempotent';
  passed := v_count = 0;
  details := format('%s duplicate escalation level group(s).', v_count);
  return next;

  select
    case
      when srt.charge_enabled then (
        select count(*) = 1
        from public.folio_items fi
        where fi.hotel_id = v_service.hotel_id
          and fi.source_table = 'service_requests'
          and fi.source_id = v_service.id
          and fi.posting_status = 'posted'
      )
      else (
        select count(*) = 0
        from public.folio_items fi
        where fi.hotel_id = v_service.hotel_id
          and fi.source_table = 'service_requests'
          and fi.source_id = v_service.id
          and fi.posting_status = 'posted'
      )
    end
  into v_bool
  from public.service_request_types srt
  where srt.hotel_id = v_service.hotel_id
    and srt.id = v_service.request_type_id;

  suite := 'RUNTIME_SERVICE';
  test_name := 'service_folio_policy_exactly_once';
  passed := coalesce(v_bool, false);
  details := 'Completed service follows its charge/no-charge folio policy exactly once.';
  return next;

  -- ========================================================================
  -- E. Final global health and closure: 6 rows.
  -- ========================================================================
  select count(*)
  into v_count
  from (
    select fi.hotel_id, fi.folio_id, fi.source_table, fi.source_id
    from public.folio_items fi
    where fi.posting_status = 'posted'
      and fi.source_table in ('food_orders','service_requests')
      and fi.source_id is not null
    group by fi.hotel_id, fi.folio_id, fi.source_table, fi.source_id
    having count(*) > 1
  ) duplicated;

  suite := 'FINAL_HEALTH';
  test_name := 'no_duplicate_posted_sources';
  passed := v_count = 0;
  details := format('%s duplicate posted source group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select foe.hotel_id, foe.food_order_id, foe.idempotency_key
    from public.food_order_events foe
    group by foe.hotel_id, foe.food_order_id, foe.idempotency_key
    having count(*) > 1
  ) duplicated;

  suite := 'FINAL_HEALTH';
  test_name := 'food_event_idempotency';
  passed := v_count = 0;
  details := format('%s duplicate food event key group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select sre.hotel_id, sre.service_request_id, sre.idempotency_key
    from public.service_request_events sre
    group by sre.hotel_id, sre.service_request_id, sre.idempotency_key
    having count(*) > 1
  ) duplicated;

  suite := 'FINAL_HEALTH';
  test_name := 'service_event_idempotency';
  passed := v_count = 0;
  details := format('%s duplicate service event key group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select fo.hotel_id, fo.idempotency_key
    from public.food_orders fo
    where fo.idempotency_key is not null
    group by fo.hotel_id, fo.idempotency_key
    having count(*) > 1
  ) duplicated;

  suite := 'FINAL_HEALTH';
  test_name := 'food_request_idempotency';
  passed := v_count = 0;
  details := format('%s duplicate food request key group(s).', v_count);
  return next;

  select (
    select count(*)
    from public.food_orders fo
    where fo.order_status not in (
      'pending','accepted','preparing','ready',
      'out_for_delivery','delivered','cancelled'
    )
  ) + (
    select count(*)
    from public.service_requests sr
    where sr.status not in (
      'pending','accepted','in_progress',
      'completed','cancelled','escalated'
    )
  )
  into v_count;

  suite := 'FINAL_HEALTH';
  test_name := 'all_status_values_supported';
  passed := v_count = 0;
  details := format('%s unsupported food/service status row(s).', v_count);
  return next;

  suite := 'FINAL_HEALTH';
  test_name := 'day15_final_acceptance_complete';
  passed := true;
  details :=
    'Day 15 roadmap scope and controlled runtime acceptance are complete.';
  return next;
end;
$_$;


ALTER FUNCTION "private"."day15_audit_066_final_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_audit_066_final_rev2"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_food_delivered public.food_orders%rowtype;
  v_food_cancelled public.food_orders%rowtype;
  v_service public.service_requests%rowtype;
  v_count bigint;
  v_amount numeric(14,2);
  v_text text;
  v_bool boolean;
begin
  -- ========================================================================
  -- A. Re-run every accepted migration contract: 220 rows.
  -- ========================================================================
  return query
  select
    'M051_' || a.suite,
    a.test_name,
    a.passed,
    a.details
  from private.day15_migration_051_acceptance_rev1() a;

  return query
  select
    'M052_' || a.suite,
    a.test_name,
    a.passed,
    a.details
  from private.day15_migration_052_acceptance_rev1() a;

  return query
  select
    'M053_' || a.suite,
    a.test_name,
    a.passed,
    a.details
  from private.day15_migration_053_acceptance_rev1() a;

  -- ========================================================================
  -- B. Delivered taxed/modifier food order runtime: 24 rows.
  -- ========================================================================
  select fo.*
  into v_food_delivered
  from public.food_orders fo
  where fo.order_status = 'delivered'
    and fo.modifier_amount > 0
    and fo.tax_amount > 0
    and exists (
      select 1
      from public.kitchen_tickets kt
      where kt.hotel_id = fo.hotel_id
        and kt.food_order_id = fo.id
        and kt.print_count >= 1
    )
    and exists (
      select 1
      from public.folio_items fi
      where fi.hotel_id = fo.hotel_id
        and fi.source_table = 'food_orders'
        and fi.source_id = fo.id
        and fi.posting_status = 'posted'
    )
  order by fo.delivered_at desc nulls last, fo.created_at desc
  limit 1;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'controlled_order_exists';
  passed := v_food_delivered.id is not null;
  details := case
    when passed then 'A delivered taxed/modifier order with KOT and folio evidence exists.'
    else 'No controlled delivered taxed/modifier order was found.'
  end;
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'hotel_room_guest_bound';
  passed := coalesce(
    v_food_delivered.hotel_id is not null
    and v_food_delivered.room_id is not null
    and v_food_delivered.guest_id is not null,
    false
  );
  details := 'Delivered order is bound to a hotel, room and guest.';
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'guest_session_bound';
  passed := v_food_delivered.guest_session_id is not null;
  details := 'Delivered order is bound to the active guest stay.';
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'delivered_state_and_timestamp';
  passed := coalesce(
    v_food_delivered.order_status = 'delivered'
    and v_food_delivered.delivered_at is not null,
    false
  );
  details := 'Order reached delivered with a delivery timestamp.';
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'modifier_amount_positive';
  passed := coalesce(v_food_delivered.modifier_amount > 0, false);
  details := format(
    'Modifier amount: %s.',
    coalesce(v_food_delivered.modifier_amount::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'tax_amount_positive';
  passed := coalesce(v_food_delivered.tax_amount > 0, false);
  details := format(
    'Tax amount: %s.',
    coalesce(v_food_delivered.tax_amount::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'total_equation';
  passed := coalesce(
    v_food_delivered.total_amount = round(
      v_food_delivered.subtotal_amount
      + v_food_delivered.modifier_amount
      + v_food_delivered.tax_amount,
      2
    ),
    false
  );
  details := 'Subtotal + modifiers + tax equals total.';
  return next;

  select count(*)
  into v_count
  from public.food_order_items foi
  join public.food_order_item_modifiers foim
    on foim.hotel_id = foi.hotel_id
   and foim.food_order_item_id = foi.id
  where foi.hotel_id = v_food_delivered.hotel_id
    and foi.order_id = v_food_delivered.id;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'modifier_snapshot_exists';
  passed := v_count > 0;
  details := format('%s selected modifier snapshot row(s).', v_count);
  return next;

  for v_text in
    select unnest(array[
      'pending',
      'accepted',
      'preparing',
      'ready',
      'out_for_delivery',
      'delivered'
    ])
  loop
    select exists (
      select 1
      from public.food_order_events foe
      where foe.hotel_id = v_food_delivered.hotel_id
        and foe.food_order_id = v_food_delivered.id
        and foe.to_status = v_text
    )
    into v_bool;

    suite := 'RUNTIME_FOOD_DELIVERED';
    test_name := 'lifecycle_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('Lifecycle event to %s exists.', v_text);
    return next;
  end loop;

  select count(*)
  into v_count
  from public.kitchen_tickets kt
  where kt.hotel_id = v_food_delivered.hotel_id
    and kt.food_order_id = v_food_delivered.id;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'kot_exactly_one_identity';
  passed := v_count = 1;
  details := format('%s KOT identity row(s).', v_count);
  return next;

  select coalesce(max(kt.print_count), 0)
  into v_count
  from public.kitchen_tickets kt
  where kt.hotel_id = v_food_delivered.hotel_id
    and kt.food_order_id = v_food_delivered.id;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'kot_printed';
  passed := v_count >= 1;
  details := format('KOT print count: %s.', v_count);
  return next;

  select max(kt.ticket_number)
  into v_text
  from public.kitchen_tickets kt
  where kt.hotel_id = v_food_delivered.hotel_id
    and kt.food_order_id = v_food_delivered.id;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'kot_number_format';
  passed := coalesce(v_text ~ '^KOT-[0-9]{8}-[A-F0-9]{8}$', false);
  details := 'Ticket number: ' || coalesce(v_text, 'missing') || '.';
  return next;

  select count(*), coalesce(sum(fi.amount), 0)
  into v_count, v_amount
  from public.folio_items fi
  where fi.hotel_id = v_food_delivered.hotel_id
    and fi.source_table = 'food_orders'
    and fi.source_id = v_food_delivered.id
    and fi.posting_status = 'posted';

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'folio_exactly_once';
  passed := v_count = 1;
  details := format('%s posted folio row(s).', v_count);
  return next;

  suite := 'RUNTIME_FOOD_DELIVERED';
  test_name := 'folio_amount_matches';
  passed := coalesce(v_amount = v_food_delivered.total_amount, false);
  details := format(
    'Folio amount %s; order total %s.',
    v_amount,
    coalesce(v_food_delivered.total_amount::text, 'missing')
  );
  return next;

  for v_text in
    select unnest(array[
      'accepted',
      'preparing',
      'ready',
      'delivered'
    ])
  loop
    select exists (
      select 1
      from public.guest_notifications gn
      where gn.hotel_id = v_food_delivered.hotel_id
        and gn.source_type = 'food_order'
        and gn.source_id = v_food_delivered.id
        and gn.event_key = v_text
    )
    into v_bool;

    suite := 'RUNTIME_FOOD_DELIVERED';
    test_name := 'guest_notification_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('Guest notification %s exists.', v_text);
    return next;
  end loop;

  -- ========================================================================
  -- C. Guest-cancelled food order runtime: 13 rows.
  -- ========================================================================

  select count(*)
  into v_count
  from public.food_orders fo
  where fo.order_status = 'cancelled';

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'any_cancelled_order_exists';
  passed := v_count > 0;
  details := format('%s cancelled food order(s) exist.', v_count);
  return next;

  select count(*)
  into v_count
  from public.food_order_events foe
  where foe.event_type = 'guest_cancelled'
     or foe.idempotency_key = 'guest-cancelled';

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'any_guest_cancel_event_exists';
  passed := v_count > 0;
  details := format('%s guest-cancel event row(s) exist.', v_count);
  return next;

  select count(*)
  into v_count
  from public.guest_notifications gn
  where gn.source_type = 'food_order'
    and gn.event_key = 'cancelled';

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'any_cancel_notification_exists';
  passed := v_count > 0;
  details := format('%s food cancellation notification row(s) exist.', v_count);
  return next;

  v_food_cancelled := null;

  select fo.*
  into v_food_cancelled
  from public.food_orders fo
  where fo.order_status = 'cancelled'
    and exists (
      select 1
      from public.food_order_events foe
      where foe.hotel_id = fo.hotel_id
        and foe.food_order_id = fo.id
        and (
          foe.event_type = 'guest_cancelled'
          or foe.idempotency_key = 'guest-cancelled'
        )
    )
    and not exists (
      select 1
      from public.folio_items fi
      where fi.hotel_id = fo.hotel_id
        and fi.source_table = 'food_orders'
        and fi.source_id = fo.id
        and fi.posting_status = 'posted'
    )
  order by fo.cancelled_at desc nulls last, fo.created_at desc
  limit 1;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'controlled_cancelled_order_exists';
  passed := v_food_cancelled.id is not null;
  details := case
    when passed then
      'A guest-cancelled order without a folio posting exists.'
    else
      'No order cancelled through cancel_guest_food_order was found. '
      || 'Place a fresh order and cancel it from the signed guest menu while Pending.'
  end;
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'cancelled_status';
  passed := coalesce(
    v_food_cancelled.id is not null
    and v_food_cancelled.order_status = 'cancelled',
    false
  );
  details := 'Selected controlled order status is cancelled.';
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'cancel_timestamp_and_reason';
  passed := coalesce(
    v_food_cancelled.id is not null
    and v_food_cancelled.cancelled_at is not null
    and nullif(trim(v_food_cancelled.cancellation_reason), '') is not null,
    false
  );
  details := 'Cancellation timestamp and reason are stored.';
  return next;

  select count(*)
  into v_count
  from public.food_order_events foe
  where v_food_cancelled.id is not null
    and foe.hotel_id = v_food_cancelled.hotel_id
    and foe.food_order_id = v_food_cancelled.id
    and (
      foe.event_type = 'guest_cancelled'
      or foe.idempotency_key = 'guest-cancelled'
    );

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'guest_cancel_event_exists';
  passed := v_food_cancelled.id is not null and v_count >= 1;
  details := format('%s guest cancellation event row(s).', v_count);
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'guest_cancel_event_idempotent';
  passed := v_food_cancelled.id is not null and v_count = 1;
  details := format('%s guest cancellation event row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.guest_notifications gn
  where v_food_cancelled.id is not null
    and gn.hotel_id = v_food_cancelled.hotel_id
    and gn.source_type = 'food_order'
    and gn.source_id = v_food_cancelled.id
    and gn.event_key = 'cancelled';

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'cancel_notification_exists';
  passed := v_food_cancelled.id is not null and v_count = 1;
  details := format('%s cancellation notification row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.folio_items fi
  where v_food_cancelled.id is not null
    and fi.hotel_id = v_food_cancelled.hotel_id
    and fi.source_table = 'food_orders'
    and fi.source_id = v_food_cancelled.id
    and fi.posting_status = 'posted';

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'no_folio_posting';
  passed := v_food_cancelled.id is not null and v_count = 0;
  details := format('%s posted folio row(s).', v_count);
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'folio_pointer_empty';
  passed := coalesce(
    v_food_cancelled.id is not null
    and v_food_cancelled.folio_item_id is null,
    false
  );
  details := 'Guest-cancelled order has no folio_item_id.';
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'not_delivered';
  passed := coalesce(
    v_food_cancelled.id is not null
    and v_food_cancelled.delivered_at is null,
    false
  );
  details := 'Guest-cancelled order has no delivered timestamp.';
  return next;

  suite := 'RUNTIME_FOOD_CANCELLED';
  test_name := 'amount_preserved';
  passed := coalesce(
    v_food_cancelled.id is not null
    and v_food_cancelled.total_amount >= 0,
    false
  );
  details := format(
    'Cancelled order amount retained as %s.',
    coalesce(v_food_cancelled.total_amount::text, 'missing')
  );
  return next;

  -- ========================================================================
  -- D. Escalated, assigned and completed service runtime: 20 rows.
  -- ========================================================================
  select sr.*
  into v_service
  from public.service_requests sr
  where sr.status = 'completed'
    and sr.completed_at is not null
    and sr.escalation_level >= 1
    and sr.assigned_staff_id is not null
    and sr.estimated_minutes is not null
    and exists (
      select 1
      from public.service_escalations se
      where se.hotel_id = sr.hotel_id
        and se.service_request_id = sr.id
        and se.escalation_level = 1
    )
  order by sr.completed_at desc, sr.created_at desc
  limit 1;

  suite := 'RUNTIME_SERVICE';
  test_name := 'controlled_completed_escalated_request_exists';
  passed := v_service.id is not null;
  details := 'An escalated, assigned, ETA-set and completed service request exists.';
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'guest_session_bound';
  passed := v_service.guest_session_id is not null;
  details := 'Service request is bound to the guest stay.';
  return next;

  select exists (
    select 1
    from public.service_request_types srt
    where srt.hotel_id = v_service.hotel_id
      and srt.id = v_service.request_type_id
  )
  into v_bool;

  suite := 'RUNTIME_SERVICE';
  test_name := 'dynamic_type_exists';
  passed := coalesce(v_bool, false);
  details := 'Request uses a dynamic service catalogue type.';
  return next;

  select exists (
    select 1
    from public.service_request_types srt
    where srt.hotel_id = v_service.hotel_id
      and srt.id = v_service.request_type_id
      and srt.department = v_service.department
  )
  into v_bool;

  suite := 'RUNTIME_SERVICE';
  test_name := 'department_routing_matches_catalogue';
  passed := coalesce(v_bool, false);
  details := 'Request department matches its catalogue type.';
  return next;

  select exists (
    select 1
    from public.staff s
    where s.hotel_id = v_service.hotel_id
      and s.id = v_service.assigned_staff_id
      and s.status = 'active'
  )
  into v_bool;

  suite := 'RUNTIME_SERVICE';
  test_name := 'assigned_staff_is_active';
  passed := coalesce(v_bool, false);
  details := 'Assigned staff member is active in the same hotel.';
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'eta_is_set';
  passed := coalesce(
    v_service.estimated_minutes between 1 and 1440
    and v_service.estimated_arrival_time is not null,
    false
  );
  details := format(
    'Estimated minutes: %s.',
    coalesce(v_service.estimated_minutes::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'completed_state_and_timestamp';
  passed := coalesce(
    v_service.status = 'completed'
    and v_service.completed_at is not null,
    false
  );
  details := 'Service reached completed with a completion timestamp.';
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'escalation_level_recorded';
  passed := coalesce(v_service.escalation_level >= 1, false);
  details := format(
    'Escalation level: %s.',
    coalesce(v_service.escalation_level::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_SERVICE';
  test_name := 'escalated_timestamp_recorded';
  passed := v_service.escalated_at is not null;
  details := 'Escalated timestamp is stored.';
  return next;

  select count(*)
  into v_count
  from public.service_escalations se
  where se.hotel_id = v_service.hotel_id
    and se.service_request_id = v_service.id
    and se.escalation_level = 1;

  suite := 'RUNTIME_SERVICE';
  test_name := 'level_one_escalation_exactly_once';
  passed := v_count = 1;
  details := format('%s level-one escalation row(s).', v_count);
  return next;

  for v_text in
    select unnest(array[
      'sla_escalated',
      'assignment_changed'
    ])
  loop
    select exists (
      select 1
      from public.service_request_events sre
      where sre.hotel_id = v_service.hotel_id
        and sre.service_request_id = v_service.id
        and sre.event_type = v_text
    )
    into v_bool;

    suite := 'RUNTIME_SERVICE';
    test_name := 'event_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('%s event exists.', v_text);
    return next;
  end loop;

  for v_text in
    select unnest(array[
      'in_progress',
      'completed'
    ])
  loop
    select exists (
      select 1
      from public.service_request_events sre
      where sre.hotel_id = v_service.hotel_id
        and sre.service_request_id = v_service.id
        and sre.event_type = 'status_changed'
        and sre.to_status = v_text
    )
    into v_bool;

    suite := 'RUNTIME_SERVICE';
    test_name := 'status_event_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('Status event to %s exists.', v_text);
    return next;
  end loop;

  select exists (
    select 1
    from public.guest_notifications gn
    where gn.hotel_id = v_service.hotel_id
      and gn.source_type = 'service_request'
      and gn.source_id = v_service.id
      and gn.event_key like 'escalated-%'
  )
  into v_bool;

  suite := 'RUNTIME_SERVICE';
  test_name := 'guest_notification_escalated';
  passed := coalesce(v_bool, false);
  details := 'Guest escalation notification exists.';
  return next;

  for v_text in
    select unnest(array[
      'in_progress',
      'completed'
    ])
  loop
    select exists (
      select 1
      from public.guest_notifications gn
      where gn.hotel_id = v_service.hotel_id
        and gn.source_type = 'service_request'
        and gn.source_id = v_service.id
        and gn.event_key = v_text
    )
    into v_bool;

    suite := 'RUNTIME_SERVICE';
    test_name := 'guest_notification_' || v_text;
    passed := coalesce(v_bool, false);
    details := format('Guest notification %s exists.', v_text);
    return next;
  end loop;

  select count(*)
  into v_count
  from public.service_requests sr
  where sr.hotel_id = v_service.hotel_id
    and sr.status in ('pending','accepted','in_progress','escalated')
    and coalesce(sr.escalation_due_at, sr.sla_due_at) <= now();

  suite := 'RUNTIME_SERVICE';
  test_name := 'no_active_overdue_requests';
  passed := v_count = 0;
  details := format('%s active overdue request(s) remain.', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select se.hotel_id, se.service_request_id, se.escalation_level
    from public.service_escalations se
    where se.hotel_id = v_service.hotel_id
    group by se.hotel_id, se.service_request_id, se.escalation_level
    having count(*) > 1
  ) duplicated;

  suite := 'RUNTIME_SERVICE';
  test_name := 'escalation_reconciliation_idempotent';
  passed := v_count = 0;
  details := format('%s duplicate escalation level group(s).', v_count);
  return next;

  select
    case
      when srt.charge_enabled then (
        select count(*) = 1
        from public.folio_items fi
        where fi.hotel_id = v_service.hotel_id
          and fi.source_table = 'service_requests'
          and fi.source_id = v_service.id
          and fi.posting_status = 'posted'
      )
      else (
        select count(*) = 0
        from public.folio_items fi
        where fi.hotel_id = v_service.hotel_id
          and fi.source_table = 'service_requests'
          and fi.source_id = v_service.id
          and fi.posting_status = 'posted'
      )
    end
  into v_bool
  from public.service_request_types srt
  where srt.hotel_id = v_service.hotel_id
    and srt.id = v_service.request_type_id;

  suite := 'RUNTIME_SERVICE';
  test_name := 'service_folio_policy_exactly_once';
  passed := coalesce(v_bool, false);
  details := 'Completed service follows its charge/no-charge folio policy exactly once.';
  return next;

  -- ========================================================================
  -- E. Final global health and closure: 6 rows.
  -- ========================================================================
  select count(*)
  into v_count
  from (
    select fi.hotel_id, fi.folio_id, fi.source_table, fi.source_id
    from public.folio_items fi
    where fi.posting_status = 'posted'
      and fi.source_table in ('food_orders','service_requests')
      and fi.source_id is not null
    group by fi.hotel_id, fi.folio_id, fi.source_table, fi.source_id
    having count(*) > 1
  ) duplicated;

  suite := 'FINAL_HEALTH';
  test_name := 'no_duplicate_posted_sources';
  passed := v_count = 0;
  details := format('%s duplicate posted source group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select foe.hotel_id, foe.food_order_id, foe.idempotency_key
    from public.food_order_events foe
    group by foe.hotel_id, foe.food_order_id, foe.idempotency_key
    having count(*) > 1
  ) duplicated;

  suite := 'FINAL_HEALTH';
  test_name := 'food_event_idempotency';
  passed := v_count = 0;
  details := format('%s duplicate food event key group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select sre.hotel_id, sre.service_request_id, sre.idempotency_key
    from public.service_request_events sre
    group by sre.hotel_id, sre.service_request_id, sre.idempotency_key
    having count(*) > 1
  ) duplicated;

  suite := 'FINAL_HEALTH';
  test_name := 'service_event_idempotency';
  passed := v_count = 0;
  details := format('%s duplicate service event key group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select fo.hotel_id, fo.idempotency_key
    from public.food_orders fo
    where fo.idempotency_key is not null
    group by fo.hotel_id, fo.idempotency_key
    having count(*) > 1
  ) duplicated;

  suite := 'FINAL_HEALTH';
  test_name := 'food_request_idempotency';
  passed := v_count = 0;
  details := format('%s duplicate food request key group(s).', v_count);
  return next;

  select (
    select count(*)
    from public.food_orders fo
    where fo.order_status not in (
      'pending','accepted','preparing','ready',
      'out_for_delivery','delivered','cancelled'
    )
  ) + (
    select count(*)
    from public.service_requests sr
    where sr.status not in (
      'pending','accepted','in_progress',
      'completed','cancelled','escalated'
    )
  )
  into v_count;

  suite := 'FINAL_HEALTH';
  test_name := 'all_status_values_supported';
  passed := v_count = 0;
  details := format('%s unsupported food/service status row(s).', v_count);
  return next;

  suite := 'FINAL_HEALTH';
  test_name := 'day15_final_acceptance_complete';
  passed := true;
  details :=
    'Day 15 roadmap scope and controlled runtime acceptance are complete.';
  return next;
end;
$_$;


ALTER FUNCTION "private"."day15_audit_066_final_rev2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_column_exists"("p_table_name" "text", "p_column_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = p_table_name
      and c.column_name = p_column_name
  );
$$;


ALTER FUNCTION "private"."day15_column_exists"("p_table_name" "text", "p_column_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_guest_context"("p_hotel_slug" "text", "p_access_token" "text", "p_mark_used" boolean DEFAULT true) RETURNS TABLE("token_id" "uuid", "hotel_id" "uuid", "room_id" "uuid", "guest_session_id" "uuid", "guest_id" "uuid", "room_number" "text", "hotel_timezone" "text", "currency_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_token_id uuid;
begin
  v_token_id := private.resolve_guest_access_token(
    p_hotel_slug,
    p_access_token,
    p_mark_used
  );

  if v_token_id is null then
    raise exception 'This guest access link is invalid or expired.';
  end if;

  return query
  select
    t.id,
    t.hotel_id,
    t.room_id,
    t.guest_session_id,
    gs.guest_id,
    r.room_number,
    coalesce(nullif(trim(h.timezone), ''), 'Asia/Kolkata'),
    upper(coalesce(nullif(trim(h.currency_code), ''), 'INR'))
  from public.guest_access_tokens t
  join public.hotels h
    on h.id = t.hotel_id
  join public.guest_sessions gs
    on gs.id = t.guest_session_id
   and gs.hotel_id = t.hotel_id
   and gs.room_id = t.room_id
   and gs.status = 'active'
  join public.rooms r
    on r.id = t.room_id
   and r.hotel_id = t.hotel_id
  where t.id = v_token_id;

  if not found then
    raise exception 'The guest stay linked to this access token is unavailable.';
  end if;
end;
$$;


ALTER FUNCTION "private"."day15_guest_context"("p_hotel_slug" "text", "p_access_token" "text", "p_mark_used" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."menu_categories" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "hotel_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "code" "text" NOT NULL,
    "description" "text",
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "service_start_time" time without time zone,
    "service_end_time" time without time zone,
    "translations" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "menu_categories_code_not_blank" CHECK (("length"(TRIM(BOTH FROM "code")) > 0)),
    CONSTRAINT "menu_categories_translations_object_check" CHECK (("jsonb_typeof"("translations") = 'object'::"text"))
);


ALTER TABLE "public"."menu_categories" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_menu_item_available_now"("p_category" "public"."menu_categories", "p_hotel_timezone" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_local_time time;
begin
  if not coalesce(p_category.is_active, false) then
    return false;
  end if;

  if p_category.service_start_time is null
     or p_category.service_end_time is null
  then
    return true;
  end if;

  v_local_time := timezone(p_hotel_timezone, now())::time;

  if p_category.service_start_time <= p_category.service_end_time then
    return v_local_time between p_category.service_start_time
      and p_category.service_end_time;
  end if;

  return v_local_time >= p_category.service_start_time
    or v_local_time <= p_category.service_end_time;
end;
$$;


ALTER FUNCTION "private"."day15_menu_item_available_now"("p_category" "public"."menu_categories", "p_hotel_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_migration_051_acceptance_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r record;
  v_exists boolean;
  v_count bigint;
begin
  -- Required tables.
  for r in
    select unnest(array[
      'menu_item_modifier_groups',
      'menu_item_modifiers',
      'food_order_item_modifiers',
      'food_order_events',
      'kitchen_tickets',
      'service_request_events',
      'guest_notifications',
      'service_escalations'
    ]) as relation_name
  loop
    v_exists := to_regclass('public.' || r.relation_name) is not null;
    suite := 'A_TABLES';
    test_name := 'table_' || r.relation_name;
    passed := v_exists;
    details := case when v_exists then 'Exists.' else 'Missing.' end;
    return next;
  end loop;

  -- Required columns.
  for r in
    select * from (values
      ('menu_categories','service_start_time'),
      ('menu_categories','service_end_time'),
      ('menu_items','tax_rate'),
      ('menu_items','tax_inclusive'),
      ('menu_items','preparation_minutes'),
      ('menu_items','sort_order'),
      ('menu_items','archived_at'),

      ('food_orders','guest_session_id'),
      ('food_orders','subtotal_amount'),
      ('food_orders','modifier_amount'),
      ('food_orders','tax_amount'),
      ('food_orders','currency_code'),
      ('food_orders','idempotency_key'),
      ('food_orders','accepted_at'),
      ('food_orders','preparing_at'),
      ('food_orders','ready_at'),
      ('food_orders','out_for_delivery_at'),
      ('food_orders','cancelled_at'),
      ('food_orders','cancelled_by'),
      ('food_orders','cancellation_reason'),
      ('food_orders','folio_item_id'),
      ('food_orders','folio_posted_at'),
      ('food_orders','updated_at'),

      ('food_order_items','item_name_snapshot'),
      ('food_order_items','unit_price'),
      ('food_order_items','modifier_amount'),
      ('food_order_items','tax_rate'),
      ('food_order_items','tax_amount'),
      ('food_order_items','line_total'),

      ('service_request_types','department'),
      ('service_request_types','sla_minutes'),
      ('service_request_types','escalation_minutes'),
      ('service_request_types','notification_template'),

      ('service_requests','guest_session_id'),
      ('service_requests','department'),
      ('service_requests','assigned_staff_id'),
      ('service_requests','sla_due_at'),
      ('service_requests','escalation_due_at'),
      ('service_requests','escalated_at'),
      ('service_requests','escalation_level'),
      ('service_requests','cancelled_at'),
      ('service_requests','cancellation_reason'),
      ('service_requests','folio_item_id'),
      ('service_requests','folio_posted_at'),
      ('service_requests','updated_at')
    ) as c(table_name, column_name)
  loop
    select exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = r.table_name
        and c.column_name = r.column_name
    )
    into v_exists;

    suite := 'B_COLUMNS';
    test_name := r.table_name || '_' || r.column_name;
    passed := v_exists;
    details := case when v_exists then 'Exists.' else 'Missing.' end;
    return next;
  end loop;

  -- Indexes.
  for r in
    select unnest(array[
      'uq_menu_items_hotel_id_id',
      'uq_food_orders_hotel_id_id',
      'uq_food_order_items_hotel_id_id',
      'uq_service_requests_hotel_id_id',
      'uq_staff_hotel_id_id',
      'uq_menu_item_modifier_groups_hotel_id_id',
      'uq_menu_item_modifiers_hotel_id_id',
      'uq_food_orders_hotel_idempotency',
      'idx_food_orders_hotel_status_created',
      'idx_food_orders_hotel_session_created',
      'uq_food_order_item_modifiers_item_modifier',
      'uq_food_order_events_idempotency',
      'uq_kitchen_tickets_hotel_order',
      'uq_kitchen_tickets_hotel_number',
      'idx_service_request_types_hotel_department_active',
      'idx_service_requests_hotel_department_status',
      'idx_service_requests_hotel_sla_due',
      'idx_service_requests_hotel_assigned_status',
      'idx_service_requests_hotel_session_created',
      'uq_service_request_events_idempotency',
      'uq_guest_notifications_source_event',
      'uq_service_escalations_request_level'
    ]) as index_name
  loop
    v_exists := to_regclass('public.' || r.index_name) is not null;
    suite := 'C_INDEXES';
    test_name := 'index_' || r.index_name;
    passed := v_exists;
    details := case when v_exists then 'Exists.' else 'Missing.' end;
    return next;
  end loop;

  -- Named constraints.
  for r in
    select unnest(array[
      'menu_items_day15_tax_rate_check',
      'menu_items_day15_preparation_minutes_check',
      'menu_item_modifier_groups_selection_check',
      'menu_item_modifiers_price_delta_check',
      'food_orders_hotel_guest_session_fkey',
      'food_orders_order_status_check',
      'food_orders_amounts_check',
      'food_orders_currency_code_check',
      'food_order_items_amounts_check',
      'food_order_item_modifiers_hotel_item_fkey',
      'food_order_events_hotel_order_fkey',
      'kitchen_tickets_hotel_order_fkey',
      'service_request_types_department_check',
      'service_request_types_sla_check',
      'service_requests_hotel_guest_session_fkey',
      'service_requests_hotel_assigned_staff_fkey',
      'service_requests_department_check',
      'service_request_events_hotel_request_fkey',
      'guest_notifications_hotel_session_fkey',
      'service_escalations_hotel_request_fkey'
    ]) as constraint_name
  loop
    select exists (
      select 1
      from pg_constraint pc
      where pc.conname = r.constraint_name
        and pc.convalidated
    )
    into v_exists;

    suite := 'D_CONSTRAINTS';
    test_name := 'constraint_' || r.constraint_name;
    passed := v_exists;
    details := case when v_exists
      then 'Exists and is validated.'
      else 'Missing or not validated.'
    end;
    return next;
  end loop;

  -- RLS.
  for r in
    select unnest(array[
      'menu_item_modifier_groups',
      'menu_item_modifiers',
      'food_order_item_modifiers',
      'food_order_events',
      'kitchen_tickets',
      'service_request_events',
      'guest_notifications',
      'service_escalations'
    ]) as relation_name
  loop
    select c.relrowsecurity
    into v_exists
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = r.relation_name;

    suite := 'E_RLS';
    test_name := 'rls_' || r.relation_name;
    passed := coalesce(v_exists, false);
    details := case when v_exists then 'Enabled.' else 'Not enabled.' end;
    return next;
  end loop;

  -- Anonymous direct writes blocked.
  for r in
    select unnest(array[
      'menu_item_modifier_groups',
      'menu_item_modifiers',
      'food_order_item_modifiers',
      'food_order_events',
      'kitchen_tickets',
      'service_request_events',
      'guest_notifications',
      'service_escalations'
    ]) as relation_name
  loop
    suite := 'F_PRIVILEGES';
    test_name := 'anon_no_write_' || r.relation_name;
    passed := not (
      has_table_privilege('anon', 'public.' || r.relation_name, 'INSERT')
      or has_table_privilege('anon', 'public.' || r.relation_name, 'UPDATE')
      or has_table_privilege('anon', 'public.' || r.relation_name, 'DELETE')
    );
    details := case when passed
      then 'anon has no direct write privilege.'
      else 'anon retains a direct write privilege.'
    end;
    return next;
  end loop;

  -- Operational ledgers are RPC/service-role write only.
  for r in
    select unnest(array[
      'food_order_item_modifiers',
      'food_order_events',
      'kitchen_tickets',
      'service_request_events',
      'guest_notifications',
      'service_escalations'
    ]) as relation_name
  loop
    suite := 'F_PRIVILEGES';
    test_name := 'authenticated_no_write_' || r.relation_name;
    passed := not (
      has_table_privilege(
        'authenticated',
        'public.' || r.relation_name,
        'INSERT'
      )
      or has_table_privilege(
        'authenticated',
        'public.' || r.relation_name,
        'UPDATE'
      )
      or has_table_privilege(
        'authenticated',
        'public.' || r.relation_name,
        'DELETE'
      )
    );
    details := case when passed
      then 'authenticated has no direct write privilege.'
      else 'authenticated retains a direct write privilege.'
    end;
    return next;
  end loop;

  -- Backfill/data integrity.
  select count(*)
  into v_count
  from public.food_orders
  where subtotal_amount is null
     or modifier_amount is null
     or tax_amount is null
     or currency_code is null
     or updated_at is null;

  suite := 'G_BACKFILL';
  test_name := 'food_order_required_backfill';
  passed := v_count = 0;
  details := format('%s incomplete food order backfill row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.food_orders
  where total_amount <> round(
    subtotal_amount + modifier_amount + tax_amount,
    2
  );

  suite := 'G_BACKFILL';
  test_name := 'food_order_total_equation';
  passed := v_count = 0;
  details := format('%s food order total equation mismatch(es).', v_count);
  return next;

  select count(*)
  into v_count
  from public.food_order_items
  where item_name_snapshot is null
     or unit_price is null
     or modifier_amount is null
     or tax_rate is null
     or tax_amount is null
     or line_total is null
     or line_total <> round(quantity * price, 2);

  suite := 'G_BACKFILL';
  test_name := 'food_order_item_snapshot_backfill';
  passed := v_count = 0;
  details := format('%s incomplete food order item snapshot row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.service_request_types
  where department is null
     or sla_minutes is null
     or escalation_minutes is null
     or notification_template is null;

  suite := 'G_BACKFILL';
  test_name := 'service_type_operational_defaults';
  passed := v_count = 0;
  details := format('%s incomplete service type default row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.service_requests
  where department is null
     or sla_due_at is null
     or escalation_due_at is null
     or updated_at is null;

  suite := 'G_BACKFILL';
  test_name := 'service_request_operational_backfill';
  passed := v_count = 0;
  details := format('%s incomplete service request backfill row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select hotel_id, food_order_id, idempotency_key
    from public.food_order_events
    group by hotel_id, food_order_id, idempotency_key
    having count(*) > 1
  ) d;

  suite := 'G_BACKFILL';
  test_name := 'food_event_idempotency';
  passed := v_count = 0;
  details := format('%s duplicated food event key group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select hotel_id, service_request_id, idempotency_key
    from public.service_request_events
    group by hotel_id, service_request_id, idempotency_key
    having count(*) > 1
  ) d;

  suite := 'G_BACKFILL';
  test_name := 'service_event_idempotency';
  passed := v_count = 0;
  details := format('%s duplicated service event key group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from (
    select hotel_id, folio_id, source_table, source_id
    from public.folio_items
    where posting_status = 'posted'
      and source_table in ('food_orders', 'service_requests')
      and source_id is not null
    group by hotel_id, folio_id, source_table, source_id
    having count(*) > 1
  ) d;

  suite := 'H_LOCKED_NON_REGRESSION';
  test_name := 'folio_source_exactly_once';
  passed := v_count = 0;
  details := format('%s duplicate posted folio source group(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.food_orders
  where order_status not in (
    'pending',
    'accepted',
    'preparing',
    'ready',
    'out_for_delivery',
    'delivered',
    'cancelled'
  );

  suite := 'H_LOCKED_NON_REGRESSION';
  test_name := 'food_status_values';
  passed := v_count = 0;
  details := format('%s unsupported food status row(s).', v_count);
  return next;

  select count(*)
  into v_count
  from public.service_requests
  where status not in (
    'pending',
    'accepted',
    'in_progress',
    'completed',
    'cancelled',
    'escalated'
  );

  suite := 'H_LOCKED_NON_REGRESSION';
  test_name := 'service_status_values';
  passed := v_count = 0;
  details := format('%s unsupported service status row(s).', v_count);
  return next;

  suite := 'H_LOCKED_NON_REGRESSION';
  test_name := 'legacy_food_status_column_retained';
  passed := exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'food_orders'
      and column_name = 'order_status'
  );
  details := 'food_orders.order_status remains available.';
  return next;

  suite := 'H_LOCKED_NON_REGRESSION';
  test_name := 'legacy_service_assignment_retained';
  passed := exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'service_requests'
      and column_name = 'assigned_to'
  );
  details := 'service_requests.assigned_to remains available.';
  return next;

  suite := 'H_LOCKED_NON_REGRESSION';
  test_name := 'migration_051_complete';
  passed := true;
  details :=
    'Day 15 operational schema foundation installed without deleting legacy contracts.';
  return next;
end;
$$;


ALTER FUNCTION "private"."day15_migration_051_acceptance_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_migration_052_acceptance_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r record;
  v_definition text;
  v_count bigint;
begin
  for r in
    select * from (values
      ('public.get_guest_food_menu(text,text)', 'guest'),
      ('public.place_guest_food_order(text,text,jsonb)', 'guest'),
      ('public.get_guest_food_orders(text,text)', 'guest'),
      ('public.cancel_guest_food_order(text,text,uuid,text)', 'guest'),
      ('public.update_food_order_status(uuid,uuid,text,integer,text)', 'staff'),
      ('public.post_food_order_to_folio(uuid,uuid)', 'staff'),
      ('public.get_food_order_kot(uuid,uuid)', 'staff'),
      ('public.get_food_operations_analytics(uuid,timestamptz,timestamptz)', 'staff'),
      ('public.get_guest_service_catalog(text,text)', 'guest'),
      ('public.create_guest_service_request(text,text,text)', 'guest'),
      ('public.get_guest_service_requests(text,text)', 'guest'),
      ('public.cancel_guest_service_request(text,text,uuid,text)', 'guest'),
      ('public.assign_service_request(uuid,uuid,uuid)', 'staff'),
      ('public.update_service_request_priority(uuid,uuid,text)', 'staff'),
      ('public.update_service_request_status(uuid,uuid,text,integer,text)', 'staff'),
      ('public.escalate_overdue_service_requests(uuid)', 'staff'),
      ('public.get_guest_notifications(text,text)', 'guest'),
      ('public.get_service_operations_analytics(uuid,timestamptz,timestamptz)', 'staff')
    ) f(signature, access_type)
  loop
    suite := 'A_FUNCTIONS';
    test_name := 'function_' || regexp_replace(split_part(r.signature, '(', 1), '[^a-zA-Z0-9_]+', '_', 'g');
    passed := to_regprocedure(r.signature) is not null;
    details := r.signature || case when passed then ' exists.' else ' is missing.' end;
    return next;

    suite := 'B_EXECUTE_GRANTS';
    test_name := r.access_type || '_grant_' || regexp_replace(split_part(r.signature, '(', 1), '[^a-zA-Z0-9_]+', '_', 'g');
    if r.access_type = 'guest' then
      passed := has_function_privilege('anon', r.signature, 'EXECUTE');
      details := case when passed then 'anon can execute signed guest RPC.' else 'anon guest execution is missing.' end;
    else
      passed := has_function_privilege('authenticated', r.signature, 'EXECUTE')
        and not has_function_privilege('anon', r.signature, 'EXECUTE');
      details := case when passed then 'Authenticated-only staff execution is correct.' else 'Staff RPC execution boundary is incorrect.' end;
    end if;
    return next;
  end loop;

  for r in
    select unnest(array[
      'food_orders','food_order_items','food_order_item_modifiers',
      'food_order_events','kitchen_tickets','service_requests',
      'service_request_events','guest_notifications','service_escalations'
    ]) relation_name
  loop
    suite := 'C_RPC_ONLY_WRITES';
    test_name := 'authenticated_no_write_' || r.relation_name;
    passed := not (
      has_table_privilege('authenticated', 'public.' || r.relation_name, 'INSERT')
      or has_table_privilege('authenticated', 'public.' || r.relation_name, 'UPDATE')
      or has_table_privilege('authenticated', 'public.' || r.relation_name, 'DELETE')
    );
    details := case when passed then 'Authenticated browser role has no direct write privilege.' else 'Direct authenticated write remains.' end;
    return next;
  end loop;

  select pg_get_functiondef('public.place_guest_food_order(text,text,jsonb)'::regprocedure)
  into v_definition;
  return query select 'D_SOURCE_CONTRACTS','food_idempotency',position('idempotency_key' in lower(v_definition)) > 0,'Order placement uses a server-enforced idempotency key.';
  return query select 'D_SOURCE_CONTRACTS','food_modifiers',position('food_order_item_modifiers' in lower(v_definition)) > 0,'Order placement validates and snapshots modifiers.';
  return query select 'D_SOURCE_CONTRACTS','food_tax',position('tax_inclusive' in lower(v_definition)) > 0,'Order placement calculates tax snapshots.';
  return query select 'D_SOURCE_CONTRACTS','food_service_window',position('day15_menu_item_available_now' in lower(v_definition)) > 0,'Order placement enforces service windows.';

  select pg_get_functiondef('public.update_food_order_status(uuid,uuid,text,integer,text)'::regprocedure)
  into v_definition;
  return query select 'D_SOURCE_CONTRACTS','food_exactly_once_folio',position('day11_sync_food_order' in lower(v_definition)) > 0,'Delivered status invokes the locked exactly-once folio synchronizer.';
  return query select 'D_SOURCE_CONTRACTS','food_ready_stage',position('''ready''' in lower(v_definition)) > 0,'Kitchen workflow contains the ready stage.';

  select pg_get_functiondef('public.create_guest_service_request(text,text,text)'::regprocedure)
  into v_definition;
  return query select 'D_SOURCE_CONTRACTS','dynamic_service_catalog',position('service_request_types' in lower(v_definition)) > 0,'Guest service creation uses the dynamic catalogue.';
  return query select 'D_SOURCE_CONTRACTS','service_department',position('department' in lower(v_definition)) > 0,'Guest service creation routes to a department.';
  return query select 'D_SOURCE_CONTRACTS','service_sla',position('sla_due_at' in lower(v_definition)) > 0,'Guest service creation assigns SLA deadlines.';

  select pg_get_functiondef('public.update_service_request_status(uuid,uuid,text,integer,text)'::regprocedure)
  into v_definition;
  return query select 'D_SOURCE_CONTRACTS','service_guest_notification',position('day15_notify_guest' in lower(v_definition)) > 0,'Service transitions create guest notifications.';
  return query select 'D_SOURCE_CONTRACTS','service_charge_sync',position('day11_post_service_request_charge' in lower(v_definition)) > 0,'Completed chargeable services use locked exactly-once folio posting.';

  select count(*) into v_count
  from (
    select hotel_id, folio_id, source_table, source_id
    from public.folio_items
    where posting_status = 'posted'
      and source_table in ('food_orders','service_requests')
      and source_id is not null
    group by hotel_id, folio_id, source_table, source_id
    having count(*) > 1
  ) d;
  return query select 'E_DATA_HEALTH','folio_exactly_once',v_count = 0,format('%s duplicate posted source group(s).',v_count);

  select count(*) into v_count
  from public.food_orders
  where order_status not in ('pending','accepted','preparing','ready','out_for_delivery','delivered','cancelled');
  return query select 'E_DATA_HEALTH','food_status_values',v_count = 0,format('%s unsupported food status row(s).',v_count);

  select count(*) into v_count
  from public.service_requests
  where status not in ('pending','accepted','in_progress','completed','cancelled','escalated');
  return query select 'E_DATA_HEALTH','service_status_values',v_count = 0,format('%s unsupported service status row(s).',v_count);

  select count(*) into v_count
  from public.food_orders
  where total_amount <> round(subtotal_amount + modifier_amount + tax_amount,2);
  return query select 'E_DATA_HEALTH','food_total_equation',v_count = 0,format('%s food total mismatch(es).',v_count);

  select count(*) into v_count
  from public.service_requests sr
  left join public.service_request_types srt
    on srt.id = sr.request_type_id and srt.hotel_id = sr.hotel_id
  where sr.request_type_id is not null and srt.id is null;
  return query select 'E_DATA_HEALTH','service_type_tenant_integrity',v_count = 0,format('%s missing/cross-hotel service type reference(s).',v_count);

  return query select 'F_LOCKED_NON_REGRESSION','signed_token_helper',to_regprocedure('private.resolve_guest_access_token(text,text,boolean)') is not null,'Day 7 signed token resolver remains installed.';
  return query select 'F_LOCKED_NON_REGRESSION','day11_food_sync',to_regprocedure('private.day11_sync_food_order(uuid)') is not null,'Day 11 food folio synchronizer remains installed.';
  return query select 'F_LOCKED_NON_REGRESSION','day11_service_sync',to_regprocedure('private.day11_post_service_request_charge(uuid,boolean,text)') is not null,'Day 11 service folio synchronizer remains installed.';
  return query select 'F_LOCKED_NON_REGRESSION','day14_guest_guide',to_regprocedure('public.resolve_premium_guest_guide(text,text)') is not null,'Day 14 premium guide remains installed.';
  return query select 'F_LOCKED_NON_REGRESSION','migration_052_complete',true,'Trusted Day 15 food/service workflow foundation is installed.';
end;
$$;


ALTER FUNCTION "private"."day15_migration_052_acceptance_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_migration_053_acceptance_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_definition text;
  v_exists boolean;
  v_count bigint;
begin
  -- A. Preconditions and retained Day 15 objects: 6 checks.
  suite := 'A_PRECONDITIONS';
  test_name := 'table_service_requests';
  passed := to_regclass('public.service_requests') is not null;
  details := 'Service request operational table exists.';
  return next;

  suite := 'A_PRECONDITIONS';
  test_name := 'function_update_service_request_status';
  passed := to_regprocedure(
    'public.update_service_request_status(uuid,uuid,text,integer,text)'
  ) is not null;
  details := 'Trusted service status RPC exists.';
  return next;

  suite := 'A_PRECONDITIONS';
  test_name := 'function_escalate_overdue_service_requests';
  passed := to_regprocedure(
    'public.escalate_overdue_service_requests(uuid)'
  ) is not null;
  details := 'Trusted SLA escalation RPC exists.';
  return next;

  suite := 'A_PRECONDITIONS';
  test_name := 'table_service_escalations';
  passed := to_regclass('public.service_escalations') is not null;
  details := 'Escalation ledger exists.';
  return next;

  suite := 'A_PRECONDITIONS';
  test_name := 'table_service_request_events';
  passed := to_regclass('public.service_request_events') is not null;
  details := 'Service event ledger exists.';
  return next;

  suite := 'A_PRECONDITIONS';
  test_name := 'table_guest_notifications';
  passed := to_regclass('public.guest_notifications') is not null;
  details := 'Guest notification ledger exists.';
  return next;

  -- B. Constraint definition and live rows: 9 checks.
  select pg_get_constraintdef(pc.oid)
  into v_definition
  from pg_constraint pc
  where pc.conrelid = 'public.service_requests'::regclass
    and pc.conname = 'service_requests_status_check';

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'constraint_exists';
  passed := v_definition is not null;
  details := coalesce(v_definition, 'Constraint is missing.');
  return next;

  select exists (
    select 1
    from pg_constraint pc
    where pc.conrelid = 'public.service_requests'::regclass
      and pc.conname = 'service_requests_status_check'
      and pc.convalidated
  )
  into v_exists;

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'constraint_validated';
  passed := v_exists;
  details := case
    when v_exists then 'Constraint is validated.'
    else 'Constraint is missing or not validated.'
  end;
  return next;

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'allows_pending';
  passed := position('pending' in lower(coalesce(v_definition, ''))) > 0;
  details := 'pending is included.';
  return next;

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'allows_accepted';
  passed := position('accepted' in lower(coalesce(v_definition, ''))) > 0;
  details := 'accepted is included.';
  return next;

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'allows_in_progress';
  passed := position('in_progress' in lower(coalesce(v_definition, ''))) > 0;
  details := 'in_progress is included.';
  return next;

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'allows_completed';
  passed := position('completed' in lower(coalesce(v_definition, ''))) > 0;
  details := 'completed is included.';
  return next;

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'allows_cancelled';
  passed := position('cancelled' in lower(coalesce(v_definition, ''))) > 0;
  details := 'cancelled is included.';
  return next;

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'allows_escalated';
  passed := position('escalated' in lower(coalesce(v_definition, ''))) > 0;
  details := 'escalated is included.';
  return next;

  select count(*)
  into v_count
  from public.service_requests sr
  where sr.status not in (
    'pending',
    'accepted',
    'in_progress',
    'completed',
    'cancelled',
    'escalated'
  );

  suite := 'B_STATUS_CONSTRAINT';
  test_name := 'current_rows_use_supported_statuses';
  passed := v_count = 0;
  details := format('%s unsupported live status row(s).', v_count);
  return next;

  -- C. Security and execution boundary: 8 checks.
  select c.relrowsecurity
  into v_exists
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relname = 'service_requests';

  suite := 'C_SECURITY';
  test_name := 'rls_service_requests';
  passed := coalesce(v_exists, false);
  details := 'RLS remains enabled on service_requests.';
  return next;

  select c.relrowsecurity
  into v_exists
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relname = 'service_escalations';

  suite := 'C_SECURITY';
  test_name := 'rls_service_escalations';
  passed := coalesce(v_exists, false);
  details := 'RLS remains enabled on service_escalations.';
  return next;

  suite := 'C_SECURITY';
  test_name := 'anon_no_write_service_requests';
  passed := not (
    has_table_privilege(
      'anon', 'public.service_requests', 'INSERT'
    )
    or has_table_privilege(
      'anon', 'public.service_requests', 'UPDATE'
    )
    or has_table_privilege(
      'anon', 'public.service_requests', 'DELETE'
    )
  );
  details := 'anon has no direct service-request write access.';
  return next;

  suite := 'C_SECURITY';
  test_name := 'anon_no_write_service_escalations';
  passed := not (
    has_table_privilege(
      'anon', 'public.service_escalations', 'INSERT'
    )
    or has_table_privilege(
      'anon', 'public.service_escalations', 'UPDATE'
    )
    or has_table_privilege(
      'anon', 'public.service_escalations', 'DELETE'
    )
  );
  details := 'anon has no direct escalation-ledger write access.';
  return next;

  suite := 'C_SECURITY';
  test_name := 'authenticated_no_write_service_requests';
  passed := not (
    has_table_privilege(
      'authenticated', 'public.service_requests', 'INSERT'
    )
    or has_table_privilege(
      'authenticated', 'public.service_requests', 'UPDATE'
    )
    or has_table_privilege(
      'authenticated', 'public.service_requests', 'DELETE'
    )
  );
  details := 'Authenticated browser users cannot directly mutate requests.';
  return next;

  suite := 'C_SECURITY';
  test_name := 'authenticated_no_write_service_escalations';
  passed := not (
    has_table_privilege(
      'authenticated', 'public.service_escalations', 'INSERT'
    )
    or has_table_privilege(
      'authenticated', 'public.service_escalations', 'UPDATE'
    )
    or has_table_privilege(
      'authenticated', 'public.service_escalations', 'DELETE'
    )
  );
  details := 'Authenticated browser users cannot directly mutate escalations.';
  return next;

  suite := 'C_SECURITY';
  test_name := 'authenticated_execute_escalation_rpc';
  passed := has_function_privilege(
    'authenticated',
    'public.escalate_overdue_service_requests(uuid)',
    'EXECUTE'
  );
  details := 'Authenticated staff can call the trusted escalation RPC.';
  return next;

  suite := 'C_SECURITY';
  test_name := 'authenticated_execute_status_rpc';
  passed := has_function_privilege(
    'authenticated',
    'public.update_service_request_status(uuid,uuid,text,integer,text)',
    'EXECUTE'
  );
  details := 'Authenticated staff can call the trusted status RPC.';
  return next;

  -- D. Final completion marker: 1 check. Total = 24.
  suite := 'D_FINAL';
  test_name := 'migration_053_complete';
  passed := true;
  details :=
    'Service escalation status is compatible with the trusted Day 15 workflow.';
  return next;
end;
$$;


ALTER FUNCTION "private"."day15_migration_053_acceptance_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_notify_guest"("p_hotel_id" "uuid", "p_guest_session_id" "uuid", "p_room_id" "uuid", "p_guest_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_event_key" "text", "p_title" "text", "p_message" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_event_key text := coalesce(nullif(trim(p_event_key), ''), 'update');
  v_title text := coalesce(nullif(trim(p_title), ''), 'Order update');
  v_message text := coalesce(nullif(trim(p_message), ''), 'Your order has been updated.');
begin
  insert into public.guest_notifications (
    hotel_id,
    guest_session_id,
    room_id,
    guest_id,
    source_type,
    source_id,
    event_key,
    title,
    message,
    metadata
  ) values (
    p_hotel_id,
    p_guest_session_id,
    p_room_id,
    p_guest_id,
    p_source_type,
    p_source_id,
    v_event_key,
    v_title,
    v_message,
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (hotel_id, source_type, source_id, event_key)
  do update set
    title = excluded.title,
    message = excluded.message,
    metadata = public.guest_notifications.metadata || excluded.metadata
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "private"."day15_notify_guest"("p_hotel_id" "uuid", "p_guest_session_id" "uuid", "p_room_id" "uuid", "p_guest_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_event_key" "text", "p_title" "text", "p_message" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_preflight_inventory_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  r record;
  v_exists boolean;
  v_count bigint;
  v_aux bigint;
  v_text text;
  v_definition text;
begin
  -- ========================================================================
  -- A. Locked dependencies that Day 15 must preserve
  -- ========================================================================
  for r in
    select * from (values
      ('public.hotels', 'Tenant/hotel identity'),
      ('public.rooms', 'Room binding'),
      ('public.guests', 'Guest identity'),
      ('public.guest_sessions', 'Active stay'),
      ('public.guest_access_tokens', 'Signed guest token'),
      ('public.folios', 'Authoritative folio'),
      ('public.folio_items', 'Authoritative folio charge ledger'),
      ('public.staff', 'Department/staff assignment'),
      ('public.notifications', 'Existing notification ledger')
    ) as t(relation_name, purpose)
  loop
    v_exists := to_regclass(r.relation_name) is not null;
    suite := 'A_LOCKED_BASELINE';
    test_name := 'table_' || replace(r.relation_name, 'public.', '');
    passed := v_exists;
    details := r.purpose || case when v_exists then ' exists.' else ' is missing.' end;
    return next;
  end loop;

  for r in
    select * from (values
      ('private.resolve_guest_access_token(text,text,boolean)', 'Signed-token resolver'),
      ('private.day11_sync_food_order(uuid)', 'Existing exactly-once folio food synchronizer'),
      ('private.day11_sync_service_request(uuid)', 'Existing service folio synchronizer'),
      ('public.resolve_premium_guest_guide(text,text)', 'Locked Day 14 guest guide'),
      ('public.create_guest_service_request(text,text,text)', 'Current signed guest service creation'),
      ('public.get_guest_service_requests(text,text)', 'Current guest service tracking'),
      ('public.get_guest_food_menu(text,text)', 'Current signed menu resolver'),
      ('public.place_guest_food_order(text,text,jsonb)', 'Current signed order placement'),
      ('public.get_guest_food_orders(text,text)', 'Current guest order tracking')
    ) as t(signature, purpose)
  loop
    v_exists := to_regprocedure(r.signature) is not null;
    suite := 'A_LOCKED_BASELINE';
    test_name := 'function_' ||
      regexp_replace(split_part(r.signature, '(', 1), '[^a-zA-Z0-9_]+', '_', 'g');
    passed := v_exists;
    details := r.purpose || case when v_exists then ' exists.' else ' is missing.' end;
    return next;
  end loop;

  -- ========================================================================
  -- B. Food and kitchen relation inventory
  -- ========================================================================
  for r in
    select * from (values
      ('menu_categories', 'Menu category configuration'),
      ('menu_items', 'Menu item configuration'),
      ('menu_item_modifier_groups', 'Modifier groups'),
      ('menu_item_modifiers', 'Modifier choices'),
      ('food_orders', 'Food order header'),
      ('food_order_items', 'Food order lines'),
      ('food_order_item_modifiers', 'Selected modifier snapshots'),
      ('food_order_events', 'Immutable food status/event history'),
      ('kitchen_tickets', 'KOT/ticket identity and print history')
    ) as t(relation_name, purpose)
  loop
    v_exists := to_regclass('public.' || r.relation_name) is not null;
    suite := 'B_FOOD_TABLES';
    test_name := 'table_' || r.relation_name;
    passed := v_exists;
    details := r.purpose || case when v_exists then ' table exists.' else ' table is absent.' end;
    return next;
  end loop;

  -- Current and target food columns.
  for r in
    select * from (values
      ('menu_categories','hotel_id','current'),
      ('menu_categories','name','current'),
      ('menu_categories','code','current'),
      ('menu_categories','description','current'),
      ('menu_categories','is_active','current'),
      ('menu_categories','sort_order','current'),
      ('menu_categories','service_start_time','target'),
      ('menu_categories','service_end_time','target'),

      ('menu_items','hotel_id','current'),
      ('menu_items','category_id','current'),
      ('menu_items','item_name','current'),
      ('menu_items','description','current'),
      ('menu_items','price','current'),
      ('menu_items','image_url','current'),
      ('menu_items','is_available','current'),
      ('menu_items','tax_rate','target'),
      ('menu_items','tax_inclusive','target'),
      ('menu_items','preparation_minutes','target'),
      ('menu_items','sort_order','target'),
      ('menu_items','archived_at','target'),

      ('food_orders','hotel_id','current'),
      ('food_orders','room_id','current'),
      ('food_orders','guest_id','current'),
      ('food_orders','guest_session_id','target'),
      ('food_orders','order_status','current'),
      ('food_orders','payment_status','current'),
      ('food_orders','subtotal_amount','target'),
      ('food_orders','modifier_amount','target'),
      ('food_orders','tax_amount','target'),
      ('food_orders','total_amount','current'),
      ('food_orders','currency_code','target'),
      ('food_orders','idempotency_key','target'),
      ('food_orders','estimated_minutes','current'),
      ('food_orders','estimated_delivery_time','current'),
      ('food_orders','accepted_at','target'),
      ('food_orders','preparing_at','target'),
      ('food_orders','ready_at','target'),
      ('food_orders','out_for_delivery_at','target'),
      ('food_orders','delivered_at','current'),
      ('food_orders','cancelled_at','target'),
      ('food_orders','cancelled_by','target'),
      ('food_orders','cancellation_reason','target'),
      ('food_orders','folio_item_id','target'),
      ('food_orders','folio_posted_at','target'),

      ('food_order_items','hotel_id','current'),
      ('food_order_items','order_id','current'),
      ('food_order_items','menu_item_id','current'),
      ('food_order_items','quantity','current'),
      ('food_order_items','price','current'),
      ('food_order_items','item_name_snapshot','target'),
      ('food_order_items','unit_price','target'),
      ('food_order_items','modifier_amount','target'),
      ('food_order_items','tax_rate','target'),
      ('food_order_items','tax_amount','target'),
      ('food_order_items','line_total','target'),

      ('menu_item_modifier_groups','hotel_id','target'),
      ('menu_item_modifier_groups','menu_item_id','target'),
      ('menu_item_modifier_groups','name','target'),
      ('menu_item_modifier_groups','min_selections','target'),
      ('menu_item_modifier_groups','max_selections','target'),
      ('menu_item_modifier_groups','is_required','target'),
      ('menu_item_modifier_groups','is_active','target'),

      ('menu_item_modifiers','hotel_id','target'),
      ('menu_item_modifiers','modifier_group_id','target'),
      ('menu_item_modifiers','name','target'),
      ('menu_item_modifiers','price_delta','target'),
      ('menu_item_modifiers','is_available','target'),

      ('food_order_item_modifiers','hotel_id','target'),
      ('food_order_item_modifiers','food_order_item_id','target'),
      ('food_order_item_modifiers','modifier_id','target'),
      ('food_order_item_modifiers','modifier_name_snapshot','target'),
      ('food_order_item_modifiers','price_delta','target')
    ) as c(table_name, column_name, contract_level)
  loop
    v_exists := private.day15_column_exists(r.table_name, r.column_name);
    suite := 'C_FOOD_COLUMNS';
    test_name := r.contract_level || '_' || r.table_name || '_' || r.column_name;
    passed := v_exists;
    details := format(
      'public.%s.%s %s (%s contract).',
      r.table_name,
      r.column_name,
      case when v_exists then 'exists' else 'is absent' end,
      r.contract_level
    );
    return next;
  end loop;

  -- ========================================================================
  -- D. Service operations relation and column inventory
  -- ========================================================================
  for r in
    select * from (values
      ('service_request_types', 'Dynamic guest-visible service categories'),
      ('service_requests', 'Operational service queue'),
      ('service_request_events', 'Immutable service workflow history'),
      ('guest_notifications', 'Guest-visible notification history'),
      ('service_escalations', 'Escalation evidence and acknowledgement')
    ) as t(relation_name, purpose)
  loop
    v_exists := to_regclass('public.' || r.relation_name) is not null;
    suite := 'D_SERVICE_TABLES';
    test_name := 'table_' || r.relation_name;
    passed := v_exists;
    details := r.purpose || case when v_exists then ' table exists.' else ' table is absent.' end;
    return next;
  end loop;

  for r in
    select * from (values
      ('service_request_types','hotel_id','current'),
      ('service_request_types','name','current'),
      ('service_request_types','code','current'),
      ('service_request_types','description','current'),
      ('service_request_types','default_priority','current'),
      ('service_request_types','default_estimated_minutes','current'),
      ('service_request_types','guest_visible','current'),
      ('service_request_types','is_active','current'),
      ('service_request_types','sort_order','current'),
      ('service_request_types','department','target'),
      ('service_request_types','sla_minutes','target'),
      ('service_request_types','escalation_minutes','target'),
      ('service_request_types','notification_template','target'),
      ('service_request_types','charge_enabled','current'),
      ('service_request_types','default_charge_amount','current'),
      ('service_request_types','charge_posting_policy','current'),

      ('service_requests','hotel_id','current'),
      ('service_requests','room_id','current'),
      ('service_requests','guest_id','current'),
      ('service_requests','guest_session_id','target'),
      ('service_requests','request_type_id','current'),
      ('service_requests','request_type','current'),
      ('service_requests','request_details','current'),
      ('service_requests','department','target'),
      ('service_requests','status','current'),
      ('service_requests','priority','current'),
      ('service_requests','assigned_to','legacy'),
      ('service_requests','assigned_staff_id','target'),
      ('service_requests','estimated_minutes','current'),
      ('service_requests','estimated_arrival_time','current'),
      ('service_requests','sla_due_at','target'),
      ('service_requests','escalation_due_at','target'),
      ('service_requests','escalated_at','target'),
      ('service_requests','escalation_level','target'),
      ('service_requests','accepted_at','current'),
      ('service_requests','started_at','current'),
      ('service_requests','completed_at','current'),
      ('service_requests','cancelled_at','target'),
      ('service_requests','cancellation_reason','target'),
      ('service_requests','folio_item_id','target'),
      ('service_requests','folio_posted_at','target')
    ) as c(table_name, column_name, contract_level)
  loop
    v_exists := private.day15_column_exists(r.table_name, r.column_name);
    suite := 'E_SERVICE_COLUMNS';
    test_name := r.contract_level || '_' || r.table_name || '_' || r.column_name;
    passed := v_exists;
    details := format(
      'public.%s.%s %s (%s contract).',
      r.table_name,
      r.column_name,
      case when v_exists then 'exists' else 'is absent' end,
      r.contract_level
    );
    return next;
  end loop;

  -- ========================================================================
  -- F. Required Day 15 server-action contracts
  -- ========================================================================
  for r in
    select * from (values
      ('public.get_guest_food_menu(text,text)', 'Signed menu with availability/tax/modifier payload'),
      ('public.place_guest_food_order(text,text,jsonb)', 'Signed idempotent order placement'),
      ('public.get_guest_food_orders(text,text)', 'Guest order tracking'),
      ('public.cancel_guest_food_order(text,text,uuid,text)', 'Guest cancellation with status/time rules'),
      ('public.update_food_order_status(uuid,uuid,text,integer,text)', 'Trusted kitchen transition and ETA'),
      ('public.post_food_order_to_folio(uuid,uuid)', 'Explicit exactly-once folio posting'),
      ('public.get_food_order_kot(uuid,uuid)', 'Print-ready KOT payload'),
      ('public.get_food_operations_analytics(uuid,timestamptz,timestamptz)', 'Food operational analytics'),

      ('public.get_guest_service_catalog(text,text)', 'Signed dynamic service catalogue'),
      ('public.create_guest_service_request(text,text,text)', 'Signed service creation'),
      ('public.get_guest_service_requests(text,text)', 'Guest service tracking'),
      ('public.assign_service_request(uuid,uuid,uuid)', 'Trusted department/staff assignment'),
      ('public.update_service_request_status(uuid,uuid,text,integer,text)', 'Trusted status and ETA transition'),
      ('public.cancel_guest_service_request(text,text,uuid,text)', 'Guest cancellation where allowed'),
      ('public.escalate_overdue_service_requests(uuid)', 'Repeatable SLA escalation reconciliation'),
      ('public.get_guest_notifications(text,text)', 'Guest-visible notification history'),
      ('public.get_service_operations_analytics(uuid,timestamptz,timestamptz)', 'Service SLA analytics')
    ) as f(signature, purpose)
  loop
    v_exists := to_regprocedure(r.signature) is not null;
    suite := 'F_RPC_CONTRACTS';
    test_name := 'function_' ||
      regexp_replace(split_part(r.signature, '(', 1), '[^a-zA-Z0-9_]+', '_', 'g');
    passed := v_exists;
    details := r.purpose || case when v_exists
      then ' function exists with the expected signature.'
      else ' function/signature is absent.'
    end;
    return next;
  end loop;

  -- Existing function definitions: detect known hard-coded/direct legacy behavior.
  if to_regprocedure('public.create_guest_service_request(text,text,text)') is not null then
    select pg_get_functiondef('public.create_guest_service_request(text,text,text)'::regprocedure)
    into v_definition;

    suite := 'F_RPC_CONTRACTS';
    test_name := 'service_creation_uses_dynamic_type_table';
    passed := position('service_request_types' in lower(v_definition)) > 0;
    details := case when passed
      then 'Guest service creation resolves dynamic service_request_types.'
      else 'Guest service creation still uses a hard-coded allowlist or legacy text path.'
    end;
    return next;
  end if;

  if to_regprocedure('public.place_guest_food_order(text,text,jsonb)') is not null then
    select pg_get_functiondef('public.place_guest_food_order(text,text,jsonb)'::regprocedure)
    into v_definition;

    suite := 'F_RPC_CONTRACTS';
    test_name := 'food_order_idempotency_contract';
    passed :=
      position('idempotency' in lower(v_definition)) > 0
      or position('request_key' in lower(v_definition)) > 0;
    details := case when passed
      then 'Order placement contains an explicit idempotency contract.'
      else 'Order placement has no explicit request/idempotency key contract.'
    end;
    return next;

    suite := 'F_RPC_CONTRACTS';
    test_name := 'food_order_modifier_validation_contract';
    passed := position('modifier' in lower(v_definition)) > 0;
    details := case when passed
      then 'Order placement validates/snapshots modifiers.'
      else 'Order placement does not yet validate or snapshot modifiers.'
    end;
    return next;
  end if;

  -- ========================================================================
  -- G. RLS and browser write exposure
  -- ========================================================================
  for r in
    select unnest(array[
      'menu_categories',
      'menu_items',
      'menu_item_modifier_groups',
      'menu_item_modifiers',
      'food_orders',
      'food_order_items',
      'food_order_item_modifiers',
      'food_order_events',
      'kitchen_tickets',
      'service_request_types',
      'service_requests',
      'service_request_events',
      'guest_notifications',
      'service_escalations'
    ]) as relation_name
  loop
    suite := 'G_SECURITY';
    test_name := 'rls_' || r.relation_name;

    if to_regclass('public.' || r.relation_name) is null then
      passed := false;
      details := 'Table is absent, so RLS cannot be verified.';
    else
      select c.relrowsecurity
      into v_exists
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname = r.relation_name;

      passed := coalesce(v_exists, false);
      details := format(
        'RLS on public.%s is %s.',
        r.relation_name,
        case when v_exists then 'enabled' else 'not enabled' end
      );
    end if;
    return next;
  end loop;

  for r in
    select unnest(array[
      'menu_categories',
      'menu_items',
      'menu_item_modifier_groups',
      'menu_item_modifiers',
      'food_orders',
      'food_order_items',
      'food_order_item_modifiers',
      'food_order_events',
      'kitchen_tickets',
      'service_request_types',
      'service_requests',
      'service_request_events',
      'guest_notifications',
      'service_escalations'
    ]) as relation_name
  loop
    suite := 'G_SECURITY';
    test_name := 'anon_no_direct_write_' || r.relation_name;

    if to_regclass('public.' || r.relation_name) is null then
      passed := false;
      details := 'Table is absent.';
    else
      passed := not (
        has_table_privilege('anon', 'public.' || r.relation_name, 'INSERT')
        or has_table_privilege('anon', 'public.' || r.relation_name, 'UPDATE')
        or has_table_privilege('anon', 'public.' || r.relation_name, 'DELETE')
      );
      details := case when passed
        then 'anon has no direct INSERT/UPDATE/DELETE privilege.'
        else 'anon retains at least one direct write privilege.'
      end;
    end if;
    return next;
  end loop;

  -- Day 15 operational state must move behind trusted RPCs.
  for r in
    select unnest(array[
      'food_orders',
      'food_order_items',
      'food_order_item_modifiers',
      'food_order_events',
      'kitchen_tickets',
      'service_requests',
      'service_request_events',
      'guest_notifications',
      'service_escalations'
    ]) as relation_name
  loop
    suite := 'G_SECURITY';
    test_name := 'authenticated_no_operational_direct_write_' || r.relation_name;

    if to_regclass('public.' || r.relation_name) is null then
      passed := false;
      details := 'Table is absent.';
    else
      passed := not (
        has_table_privilege('authenticated', 'public.' || r.relation_name, 'INSERT')
        or has_table_privilege('authenticated', 'public.' || r.relation_name, 'UPDATE')
        or has_table_privilege('authenticated', 'public.' || r.relation_name, 'DELETE')
      );
      details := case when passed
        then 'authenticated has no direct operational write privilege.'
        else 'authenticated still has direct operational write privilege; Day 15 RPC closure is required.'
      end;
    end if;
    return next;
  end loop;

  -- ========================================================================
  -- H. Constraint/index and trigger inventory
  -- ========================================================================
  for r in
    select * from (values
      ('uq_folio_items_source', 'Exactly-once source-linked folio item uniqueness'),
      ('uq_menu_categories_hotel_code', 'Unique menu category code per hotel'),
      ('uq_service_request_types_hotel_code', 'Unique service type code per hotel'),
      ('uq_food_orders_hotel_idempotency', 'One order per hotel/idempotency key'),
      ('uq_food_order_events_idempotency', 'Event replay protection'),
      ('uq_service_request_events_idempotency', 'Service event replay protection'),
      ('idx_food_orders_hotel_status_created', 'Kitchen queue lookup'),
      ('idx_service_requests_hotel_department_status', 'Department queue lookup'),
      ('idx_service_requests_hotel_sla_due', 'SLA reconciliation lookup')
    ) as i(index_name, purpose)
  loop
    v_exists := to_regclass('public.' || r.index_name) is not null;
    suite := 'H_INDEXES';
    test_name := 'index_' || r.index_name;
    passed := v_exists;
    details := r.purpose || case when v_exists then ' index exists.' else ' index is absent.' end;
    return next;
  end loop;

  for r in
    select * from (values
      ('food_orders_order_status_check', 'Food status constraint'),
      ('service_requests_status_check', 'Service status constraint'),
      ('service_requests_priority_check', 'Service priority constraint'),
      ('service_request_types_department_check', 'Department constraint'),
      ('food_orders_amounts_check', 'Non-negative food totals'),
      ('food_order_items_amounts_check', 'Non-negative item totals')
    ) as c(constraint_name, purpose)
  loop
    select exists (
      select 1
      from pg_constraint pc
      where pc.conname = r.constraint_name
        and pc.convalidated
    )
    into v_exists;

    suite := 'H_CONSTRAINTS';
    test_name := 'constraint_' || r.constraint_name;
    passed := v_exists;
    details := r.purpose || case when v_exists
      then ' exists and is validated.'
      else ' is absent or not validated.'
    end;
    return next;
  end loop;

  -- ========================================================================
  -- I. Current runtime/data-health baseline
  -- ========================================================================
  if to_regclass('public.menu_categories') is not null then
    execute 'select count(*) from public.menu_categories' into v_count;
    execute 'select count(*) from public.menu_categories where is_active' into v_aux;
    suite := 'I_RUNTIME_BASELINE';
    test_name := 'menu_categories_count';
    passed := true;
    details := format('%s total categories; %s active.', v_count, v_aux);
    return next;
  end if;

  if to_regclass('public.menu_items') is not null then
    execute 'select count(*) from public.menu_items' into v_count;
    execute 'select count(*) from public.menu_items where is_available' into v_aux;
    suite := 'I_RUNTIME_BASELINE';
    test_name := 'menu_items_count';
    passed := true;
    details := format('%s total items; %s available.', v_count, v_aux);
    return next;

    if private.day15_column_exists('menu_items','category_id') then
      execute $sql$
        select count(*)
        from public.menu_items mi
        left join public.menu_categories mc
          on mc.id = mi.category_id
         and mc.hotel_id = mi.hotel_id
        where mi.category_id is not null
          and mc.id is null
      $sql$ into v_count;

      suite := 'I_DATA_HEALTH';
      test_name := 'menu_item_category_tenant_integrity';
      passed := v_count = 0;
      details := format('%s menu item(s) reference a missing/cross-hotel category.', v_count);
      return next;
    end if;
  end if;

  if to_regclass('public.food_orders') is not null then
    execute 'select count(*) from public.food_orders' into v_count;

    if private.day15_column_exists('food_orders','order_status') then
      execute $sql$
        select count(*)
        from public.food_orders
        where order_status not in (
          'pending','accepted','preparing','ready',
          'out_for_delivery','delivered','cancelled'
        )
      $sql$ into v_aux;

      suite := 'I_DATA_HEALTH';
      test_name := 'food_order_status_values';
      passed := v_aux = 0;
      details := format('%s total food orders; %s use an unsupported status.', v_count, v_aux);
      return next;

      execute $sql$
        select coalesce(
          string_agg(order_status || ':' || status_count::text, ', ' order by order_status),
          'none'
        )
        from (
          select order_status, count(*) status_count
          from public.food_orders
          group by order_status
        ) s
      $sql$ into v_text;

      suite := 'I_RUNTIME_BASELINE';
      test_name := 'food_order_status_distribution';
      passed := true;
      details := 'Current statuses: ' || coalesce(v_text, 'none') || '.';
      return next;
    end if;
  end if;

  if to_regclass('public.food_order_items') is not null then
    execute 'select count(*) from public.food_order_items' into v_count;
    suite := 'I_RUNTIME_BASELINE';
    test_name := 'food_order_items_count';
    passed := true;
    details := format('%s food order item rows exist.', v_count);
    return next;

    if private.day15_column_exists('food_order_items','order_id') then
      execute $sql$
        select count(*)
        from public.food_order_items foi
        left join public.food_orders fo
          on fo.id = foi.order_id
         and fo.hotel_id = foi.hotel_id
        where fo.id is null
      $sql$ into v_aux;

      suite := 'I_DATA_HEALTH';
      test_name := 'food_order_item_parent_integrity';
      passed := v_aux = 0;
      details := format('%s food order item(s) have a missing/cross-hotel parent.', v_aux);
      return next;
    end if;
  end if;

  if to_regclass('public.folio_items') is not null then
    execute $sql$
      select count(*)
      from (
        select hotel_id, folio_id, source_table, source_id
        from public.folio_items
        where posting_status = 'posted'
          and source_table in ('food_orders','service_requests')
          and source_id is not null
        group by hotel_id, folio_id, source_table, source_id
        having count(*) > 1
      ) d
    $sql$ into v_count;

    suite := 'I_DATA_HEALTH';
    test_name := 'folio_source_exactly_once';
    passed := v_count = 0;
    details := format('%s duplicated posted food/service folio source group(s).', v_count);
    return next;
  end if;

  if to_regclass('public.service_request_types') is not null then
    execute 'select count(*) from public.service_request_types' into v_count;
    execute 'select count(*) from public.service_request_types where is_active and guest_visible' into v_aux;

    suite := 'I_RUNTIME_BASELINE';
    test_name := 'service_request_types_count';
    passed := true;
    details := format('%s total types; %s active and guest-visible.', v_count, v_aux);
    return next;

    execute $sql$
      select count(*)
      from (
        select hotel_id, upper(trim(code))
        from public.service_request_types
        group by hotel_id, upper(trim(code))
        having count(*) > 1
      ) d
    $sql$ into v_count;

    suite := 'I_DATA_HEALTH';
    test_name := 'service_type_code_uniqueness';
    passed := v_count = 0;
    details := format('%s duplicate hotel/service-code group(s).', v_count);
    return next;
  end if;

  if to_regclass('public.service_requests') is not null then
    execute 'select count(*) from public.service_requests' into v_count;

    if private.day15_column_exists('service_requests','status') then
      execute $sql$
        select count(*)
        from public.service_requests
        where status not in (
          'pending','accepted','in_progress',
          'completed','cancelled','escalated'
        )
      $sql$ into v_aux;

      suite := 'I_DATA_HEALTH';
      test_name := 'service_request_status_values';
      passed := v_aux = 0;
      details := format('%s total service requests; %s use an unsupported status.', v_count, v_aux);
      return next;

      execute $sql$
        select coalesce(
          string_agg(status || ':' || status_count::text, ', ' order by status),
          'none'
        )
        from (
          select status, count(*) status_count
          from public.service_requests
          group by status
        ) s
      $sql$ into v_text;

      suite := 'I_RUNTIME_BASELINE';
      test_name := 'service_request_status_distribution';
      passed := true;
      details := 'Current statuses: ' || coalesce(v_text, 'none') || '.';
      return next;
    end if;

    if private.day15_column_exists('service_requests','request_type_id') then
      execute $sql$
        select count(*)
        from public.service_requests sr
        left join public.service_request_types srt
          on srt.id = sr.request_type_id
         and srt.hotel_id = sr.hotel_id
        where sr.request_type_id is not null
          and srt.id is null
      $sql$ into v_aux;

      suite := 'I_DATA_HEALTH';
      test_name := 'service_request_type_tenant_integrity';
      passed := v_aux = 0;
      details := format('%s service request(s) reference a missing/cross-hotel type.', v_aux);
      return next;
    end if;
  end if;

  -- ========================================================================
  -- J. Frontend compatibility markers inferred from the locked Day 14 source
  -- ========================================================================
  suite := 'J_SOURCE_EXPECTATIONS';
  test_name := 'legacy_food_status_column';
  passed := private.day15_column_exists('food_orders','order_status');
  details := 'Current frontend reads/writes food_orders.order_status.';
  return next;

  suite := 'J_SOURCE_EXPECTATIONS';
  test_name := 'legacy_service_assignment_column';
  passed := private.day15_column_exists('service_requests','assigned_to');
  details := 'Current frontend reads/writes service_requests.assigned_to.';
  return next;

  suite := 'J_SOURCE_EXPECTATIONS';
  test_name := 'target_service_assignment_column';
  passed := private.day15_column_exists('service_requests','assigned_staff_id');
  details := 'Day 15 target contract uses assigned_staff_id or a compatibility layer.';
  return next;

  suite := 'J_SOURCE_EXPECTATIONS';
  test_name := 'day15_preflight_complete';
  passed := true;
  details := 'Inventory completed without changing hotel business data.';
  return next;
end;
$_$;


ALTER FUNCTION "private"."day15_preflight_inventory_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day15_sync_service_assignment_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.assigned_staff_id is distinct from old.assigned_staff_id then
    new.assigned_to := new.assigned_staff_id;
  elsif new.assigned_to is distinct from old.assigned_to then
    new.assigned_staff_id := new.assigned_to;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."day15_sync_service_assignment_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day16_assert_filter_access"("p_hotel_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
begin
  if p_hotel_id is null then
    raise exception 'Hotel is required.';
  end if;

  select coalesce(nullif(trim(h.timezone), ''), 'Asia/Kolkata')
  into v_timezone
  from public.hotels h
  where h.id = p_hotel_id
    and h.status = 'active';

  if v_timezone is null then
    raise exception 'Active hotel was not found.';
  end if;

  perform now() at time zone v_timezone;

  if not private.user_has_permission(p_hotel_id, 'reports.view') then
    raise exception 'You do not have reports.view permission for this hotel.';
  end if;

  return v_timezone;
end;
$$;


ALTER FUNCTION "private"."day16_assert_filter_access"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day16_assert_report_access"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
begin
  if p_hotel_id is null then
    raise exception 'Hotel is required.';
  end if;

  if p_date_from is null or p_date_to is null then
    raise exception 'Report start and end dates are required.';
  end if;

  if p_date_to < p_date_from then
    raise exception 'Report end date cannot be before start date.';
  end if;

  if (p_date_to - p_date_from) > 366 then
    raise exception 'Report date range cannot exceed 367 inclusive days.';
  end if;

  select coalesce(nullif(trim(h.timezone), ''), 'Asia/Kolkata')
  into v_timezone
  from public.hotels h
  where h.id = p_hotel_id
    and h.status = 'active';

  if v_timezone is null then
    raise exception 'Active hotel was not found.';
  end if;

  perform now() at time zone v_timezone;

  if not private.user_has_permission(p_hotel_id, 'reports.view') then
    raise exception 'You do not have reports.view permission for this hotel.';
  end if;

  return v_timezone;
end;
$$;


ALTER FUNCTION "private"."day16_assert_report_access"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day16_audit_067_preflight_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "state" "text", "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r record;
  v_exists boolean;
  v_count bigint;
begin
  -- A. Required source tables.
  for r in
    select *
    from (values
      ('hotels', 'Hotel identity, status, timezone and tax context.'),
      ('rooms', 'Physical room inventory.'),
      ('room_types', 'Room classification and capacity.'),
      ('reservations', 'Reservation header, dates, source and revenue.'),
      ('reservation_rooms', 'Sold-room and rate allocation lines.'),
      ('reservation_guests', 'Reservation-to-guest identity.'),
      ('guest_sessions', 'Actual stay/check-in/check-out source.'),
      ('guests', 'Guest identity source.'),
      ('folios', 'Authoritative guest financial account.'),
      ('folio_items', 'Posted room, food, service and tax charges.'),
      ('folio_collections', 'Authoritative collections by payment method.'),
      ('invoices', 'Issued invoice and GST summary source.'),
      ('invoice_lines', 'Issued invoice line and tax breakdown.'),
      ('payments', 'Legacy/current payment records.'),
      ('food_orders', 'Food order lifecycle and delivered revenue.'),
      ('food_order_items', 'Food order item detail.'),
      ('service_requests', 'Guest service lifecycle and SLA source.'),
      ('service_request_types', 'Dynamic service catalogue and department routing.'),
      ('housekeeping_tasks', 'Housekeeping workload and completion source.'),
      ('maintenance_tasks', 'Maintenance workload and closure source.'),
      ('staff', 'Staff and department workload source.'),
      ('role_permissions', 'Role/permission reporting boundary.'),
      ('room_blocks', 'Out-of-order and blocked room-night source.'),
      ('room_inventory_allocations', 'Authoritative room inventory ledger.')
    ) as source_table(object_name, purpose)
  loop
    suite := 'A_SOURCE_TABLES';
    test_name := r.object_name;
    passed := to_regclass(format('public.%I', r.object_name)) is not null;
    state := 'baseline';
    details := r.purpose;
    return next;
  end loop;

  -- B. Required source columns.
  for r in
    select *
    from (values
      ('hotels', 'id', 'Tenant key.'),
      ('hotels', 'timezone', 'Hotel-local date boundary.'),
      ('hotels', 'status', 'Active hotel scope.'),
      ('rooms', 'hotel_id', 'Tenant scope.'),
      ('rooms', 'status', 'Current room state.'),
      ('rooms', 'room_type_id', 'Room-type drill-down.'),
      ('reservations', 'hotel_id', 'Tenant scope.'),
      ('reservations', 'booking_source', 'Reservation/source report.'),
      ('reservations', 'arrival_date', 'Arrival filtering.'),
      ('reservations', 'departure_date', 'Departure filtering.'),
      ('reservations', 'status', 'Reservation lifecycle.'),
      ('reservations', 'room_subtotal', 'Room revenue source.'),
      ('reservations', 'tax_amount', 'Reservation tax source.'),
      ('reservations', 'discount_amount', 'Reservation discount source.'),
      ('reservations', 'total_amount', 'Reservation total source.'),
      ('reservation_rooms', 'reservation_id', 'Reservation line identity.'),
      ('reservation_rooms', 'room_id', 'Physical room drill-down.'),
      ('reservation_rooms', 'room_type_id', 'Room-type drill-down.'),
      ('reservation_rooms', 'nightly_rate', 'ADR/ARR input.'),
      ('reservation_rooms', 'total_amount', 'Reservation-room total.'),
      ('guest_sessions', 'hotel_id', 'Tenant scope.'),
      ('guest_sessions', 'room_id', 'Actual occupied room.'),
      ('guest_sessions', 'reservation_id', 'Reservation/stay reconciliation.'),
      ('guest_sessions', 'checkin_time', 'Actual arrival.'),
      ('guest_sessions', 'checkout_time', 'Actual departure.'),
      ('guest_sessions', 'status', 'Stay lifecycle.'),
      ('folios', 'hotel_id', 'Tenant scope.'),
      ('folios', 'guest_session_id', 'Stay/folio reconciliation.'),
      ('folios', 'status', 'Open/settled account state.'),
      ('folio_items', 'charge_category', 'Room/food/service/manual revenue split.'),
      ('folio_items', 'amount', 'Posted charge amount.'),
      ('folio_items', 'posting_status', 'Posted-versus-voided filter.'),
      ('folio_items', 'service_at', 'Hotel-local revenue date.'),
      ('folio_collections', 'amount', 'Collection value.'),
      ('folio_collections', 'payment_method', 'Payment method drill-down.'),
      ('folio_collections', 'status', 'Posted/voided/reversed filter.'),
      ('folio_collections', 'collected_at', 'Collection date.'),
      ('invoices', 'total_amount', 'Issued invoice total.'),
      ('invoices', 'cgst_amount', 'CGST report.'),
      ('invoices', 'sgst_amount', 'SGST report.'),
      ('invoices', 'igst_amount', 'IGST report.'),
      ('food_orders', 'order_status', 'Food lifecycle filter.'),
      ('food_orders', 'total_amount', 'Delivered food revenue.'),
      ('food_orders', 'created_at', 'Order date filter.'),
      ('service_requests', 'department', 'Department report.'),
      ('service_requests', 'sla_due_at', 'SLA report.'),
      ('service_requests', 'accepted_at', 'Acceptance-time metric.'),
      ('service_requests', 'completed_at', 'Completion-time metric.'),
      ('housekeeping_tasks', 'assigned_staff_id', 'Staff workload.'),
      ('housekeeping_tasks', 'status', 'Housekeeping status.'),
      ('maintenance_tasks', 'assigned_staff_id', 'Maintenance workload.'),
      ('maintenance_tasks', 'status', 'Maintenance status.'),
      ('staff', 'role', 'Role drill-down.'),
      ('staff', 'department', 'Department drill-down.')
    ) as source_column(table_name, column_name, purpose)
  loop
    select exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = r.table_name
        and c.column_name = r.column_name
    )
    into v_exists;

    suite := 'B_SOURCE_COLUMNS';
    test_name := r.table_name || '.' || r.column_name;
    passed := v_exists;
    state := 'baseline';
    details := r.purpose;
    return next;
  end loop;

  -- C. Existing permission and analytics helpers.
  for r in
    select *
    from (values
      ('private.user_has_permission(uuid,text)', 'Tenant permission enforcement.'),
      ('private.user_has_any_permission(uuid,text[])', 'Multi-permission enforcement.'),
      ('private.is_platform_admin()', 'Platform-admin override.'),
      ('public.get_my_hotel_permissions(uuid)', 'Frontend permission resolution.'),
      ('public.get_cashier_shift_report(uuid,uuid)', 'Existing standard cashier report.'),
      ('public.get_food_operations_analytics(uuid,timestamptz,timestamptz)', 'Existing Day 15 food analytics.'),
      ('public.get_service_operations_analytics(uuid,timestamptz,timestamptz)', 'Existing Day 15 service analytics.')
    ) as baseline_function(signature, purpose)
  loop
    suite := 'C_EXISTING_FUNCTIONS';
    test_name := r.signature;
    passed := to_regprocedure(r.signature) is not null;
    state := 'baseline';
    details := r.purpose;
    return next;
  end loop;

  -- D. Existing performance indexes.
  for r in
    select *
    from (values
      ('idx_reservations_hotel_dates_status', 'Reservation date/status filtering.'),
      ('idx_reservation_rooms_room_status', 'Room allocation filtering.'),
      ('idx_folios_hotel_status_updated', 'Folio status/date filtering.'),
      ('idx_folio_items_folio_posted', 'Posted folio lines.'),
      ('idx_food_orders_hotel_status_created', 'Food date/status filtering.'),
      ('idx_service_requests_hotel_department_status', 'Service department/status filtering.'),
      ('idx_service_requests_hotel_sla_due', 'Service SLA filtering.'),
      ('idx_housekeeping_tasks_hotel_status_created', 'Housekeeping date/status filtering.'),
      ('idx_housekeeping_tasks_workload', 'Housekeeping staff workload.'),
      ('idx_maintenance_tasks_workload', 'Maintenance staff workload.'),
      ('idx_invoices_hotel_created', 'Invoice date filtering.'),
      ('idx_payments_hotel_created', 'Payment date filtering.')
    ) as source_index(index_name, purpose)
  loop
    suite := 'D_INDEXES';
    test_name := r.index_name;
    passed := to_regclass(format('public.%I', r.index_name)) is not null;
    state := 'baseline';
    details := r.purpose;
    return next;
  end loop;

  -- E. Permission matrix and security boundary.
  suite := 'E_SECURITY';
  test_name := 'reports_view_owner';
  select exists (
    select 1 from public.role_permissions
    where role_name = 'owner' and permission_key = 'reports.view'
  ) into passed;
  state := 'baseline';
  details := 'Owner has reports.view.';
  return next;

  suite := 'E_SECURITY';
  test_name := 'reports_view_manager';
  select exists (
    select 1 from public.role_permissions
    where role_name = 'manager' and permission_key = 'reports.view'
  ) into passed;
  state := 'baseline';
  details := 'Manager has reports.view.';
  return next;

  suite := 'E_SECURITY';
  test_name := 'reports_view_accounts';
  select exists (
    select 1 from public.role_permissions
    where role_name = 'accounts' and permission_key = 'reports.view'
  ) into passed;
  state := 'baseline';
  details := 'Accounts has reports.view.';
  return next;

  suite := 'E_SECURITY';
  test_name := 'anon_no_permission_helper';
  passed := not has_function_privilege(
    'anon',
    'public.get_my_hotel_permissions(uuid)',
    'EXECUTE'
  );
  state := 'baseline';
  details := 'Anonymous role cannot enumerate hotel permissions.';
  return next;

  suite := 'E_SECURITY';
  test_name := 'authenticated_permission_helper';
  passed := has_function_privilege(
    'authenticated',
    'public.get_my_hotel_permissions(uuid)',
    'EXECUTE'
  );
  state := 'baseline';
  details := 'Authenticated staff can resolve their own permissions.';
  return next;

  suite := 'E_SECURITY';
  test_name := 'reports_page_permission_key_exists';
  select exists (
    select 1 from public.role_permissions
    where permission_key = 'reports.view'
  ) into passed;
  state := 'baseline';
  details := 'Canonical reports.view permission exists.';
  return next;

  suite := 'E_SECURITY';
  test_name := 'hotels_rls_enabled';
  select c.relrowsecurity
  into passed
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname = 'hotels';
  state := 'baseline';
  details := 'Tenant root remains protected by RLS.';
  return next;

  suite := 'E_SECURITY';
  test_name := 'folios_rls_enabled';
  select c.relrowsecurity
  into passed
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname = 'folios';
  state := 'baseline';
  details := 'Authoritative folios remain protected by RLS.';
  return next;

  -- F. Planned Day 16 RPCs. False is expected before implementation.
  for r in
    select *
    from (values
      ('public.get_report_kpi_summary(uuid,date,date)', 'Occupancy, room nights, ADR/ARR, RevPAR and revenue summary.'),
      ('public.get_report_occupancy_daily(uuid,date,date)', 'Daily available/sold/occupied/blocked room nights.'),
      ('public.get_report_revenue_daily(uuid,date,date)', 'Daily posted revenue and collections.'),
      ('public.get_report_revenue_by_category(uuid,date,date)', 'Room/food/service/manual/tax revenue drill-down.'),
      ('public.get_report_reservations_by_source(uuid,date,date)', 'Reservation source and conversion report.'),
      ('public.get_report_arrivals_departures(uuid,date,date)', 'Arrival/departure operational report.'),
      ('public.get_report_payments_by_method(uuid,date,date)', 'Cash/card/UPI/payment-link collections.'),
      ('public.get_report_tax_gst_summary(uuid,date,date)', 'CGST/SGST/IGST and taxable totals.'),
      ('public.get_report_guest_food_service(uuid,date,date)', 'Guest, food and service performance.'),
      ('public.get_report_service_sla(uuid,date,date)', 'Department SLA, overdue and completion metrics.'),
      ('public.get_report_housekeeping(uuid,date,date)', 'Housekeeping status and turnaround.'),
      ('public.get_report_staff_department(uuid,date,date)', 'Staff/department workload and completion.'),
      ('public.get_report_export_rows(uuid,date,date,text,jsonb)', 'Role/date-filtered export dataset.'),
      ('public.get_report_filter_options(uuid)', 'Safe source/department/room/staff filter options.')
    ) as planned_function(signature, purpose)
  loop
    suite := 'F_DAY16_PLANNED_GAPS';
    test_name := r.signature;
    passed := to_regprocedure(r.signature) is not null;
    state := case when passed then 'implemented' else 'planned_gap' end;
    details := r.purpose;
    return next;
  end loop;

  -- G. Informational source-row counts.
  for r in
    select *
    from (values
      ('hotels', 'Current source-row count.'),
      ('rooms', 'Current source-row count.'),
      ('reservations', 'Current source-row count.'),
      ('reservation_rooms', 'Current source-row count.'),
      ('guest_sessions', 'Current source-row count.'),
      ('folios', 'Current source-row count.'),
      ('folio_items', 'Current source-row count.'),
      ('folio_collections', 'Current source-row count.'),
      ('invoices', 'Current source-row count.'),
      ('food_orders', 'Current source-row count.'),
      ('service_requests', 'Current source-row count.'),
      ('housekeeping_tasks', 'Current source-row count.')
    ) as data_source(table_name, purpose)
  loop
    if to_regclass(format('public.%I', r.table_name)) is null then
      v_count := 0;
    else
      execute format('select count(*) from public.%I', r.table_name)
      into v_count;
    end if;

    suite := 'G_DATA_COUNTS';
    test_name := r.table_name;
    passed := true;
    state := 'informational';
    details := format('%s row(s).', v_count);
    return next;
  end loop;

  suite := 'H_FINAL';
  test_name := 'day16_preflight_complete';
  passed := true;
  state := 'informational';
  details :=
    'Preflight complete. Migration 055 may now build the trusted report kernel.';
  return next;
end;
$$;


ALTER FUNCTION "private"."day16_audit_067_preflight_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day16_audit_068_final_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_hotel_id uuid;
  v_hotel_name text;
  v_auth_user_id uuid;
  v_other_hotel_id uuid;
  v_timezone text;
  v_is_platform_admin boolean := false;
  v_date_from date;
  v_date_to date;

  v_kpi jsonb;
  v_occupancy jsonb;
  v_revenue_daily jsonb;
  v_revenue_category jsonb;
  v_sources jsonb;
  v_arrivals jsonb;
  v_payments jsonb;
  v_tax jsonb;
  v_guest_food_service jsonb;
  v_service_sla jsonb;
  v_housekeeping jsonb;
  v_staff jsonb;
  v_filters jsonb;
  v_export jsonb;

  v_available numeric := 0;
  v_sold numeric := 0;
  v_occupied numeric := 0;
  v_blocked numeric := 0;

  v_room_revenue numeric := 0;
  v_food_revenue numeric := 0;
  v_service_revenue numeric := 0;
  v_other_revenue numeric := 0;
  v_tax_revenue numeric := 0;
  v_gross_revenue numeric := 0;
  v_collections numeric := 0;

  v_reservation_count bigint := 0;
  v_arrival_count bigint := 0;
  v_departure_count bigint := 0;
  v_food_order_count bigint := 0;
  v_service_request_count bigint := 0;

  v_count bigint := 0;
  v_count_2 bigint := 0;
  v_count_3 bigint := 0;
  v_count_4 bigint := 0;
  v_amount numeric := 0;
  v_amount_2 numeric := 0;
  v_amount_3 numeric := 0;
  v_amount_4 numeric := 0;
  v_bool boolean := false;
  v_text text;
begin
  -- ========================================================================
  -- A. Re-run the complete accepted Migration 055 contract: 118 rows.
  -- ========================================================================
  return query
  select
    'M055_' || accepted.suite,
    accepted.test_name,
    accepted.passed,
    accepted.details
  from private.day16_migration_055_acceptance_rev1() accepted;

  -- ========================================================================
  -- B. Resolve a real authorized hotel/user and runtime window: 10 rows.
  -- ========================================================================
  with candidates as (
    select distinct
      h.id as hotel_id,
      h.hotel_name,
      coalesce(nullif(trim(h.timezone), ''), 'Asia/Kolkata') as timezone,
      s.auth_user_id,
      exists (
        select 1
        from public.platform_admins pa
        where pa.user_id = s.auth_user_id
          and pa.status = 'active'
      ) as is_platform_admin,
      (
        select count(*) from public.folio_items fi
        where fi.hotel_id = h.id
      )
      + (
        select count(*) from public.guest_sessions gs
        where gs.hotel_id = h.id
      )
      + (
        select count(*) from public.food_orders fo
        where fo.hotel_id = h.id
      )
      + (
        select count(*) from public.service_requests sr
        where sr.hotel_id = h.id
      ) as activity_score
    from public.staff s
    join public.hotels h
      on h.id = s.hotel_id
    join auth.users au
      on au.id = s.auth_user_id
    join public.role_permissions rp
      on lower(replace(trim(rp.role_name), ' ', '_'))
       = lower(replace(trim(s.role), ' ', '_'))
     and rp.permission_key = 'reports.view'
    where s.status = 'active'
      and h.status = 'active'
      and s.auth_user_id is not null
      and coalesce(au.banned_until, '-infinity'::timestamptz) <= now()
  )
  select
    c.hotel_id,
    c.hotel_name,
    c.auth_user_id,
    c.timezone,
    c.is_platform_admin
  into
    v_hotel_id,
    v_hotel_name,
    v_auth_user_id,
    v_timezone,
    v_is_platform_admin
  from candidates c
  order by
    case when c.is_platform_admin then 1 else 0 end,
    c.activity_score desc,
    c.hotel_name
  limit 1;

  select h.id
  into v_other_hotel_id
  from public.hotels h
  where h.status = 'active'
    and h.id <> v_hotel_id
  order by h.created_at, h.id
  limit 1;

  if v_hotel_id is not null then
    select greatest(
      (now() at time zone v_timezone)::date,
      coalesce(
        (
          select max((fi.service_at at time zone v_timezone)::date)
          from public.folio_items fi
          where fi.hotel_id = v_hotel_id
        ),
        date '1900-01-01'
      ),
      coalesce(
        (
          select max((gs.checkin_time at time zone v_timezone)::date)
          from public.guest_sessions gs
          where gs.hotel_id = v_hotel_id
        ),
        date '1900-01-01'
      ),
      coalesce(
        (
          select max((fo.created_at at time zone v_timezone)::date)
          from public.food_orders fo
          where fo.hotel_id = v_hotel_id
        ),
        date '1900-01-01'
      ),
      coalesce(
        (
          select max((sr.created_at at time zone v_timezone)::date)
          from public.service_requests sr
          where sr.hotel_id = v_hotel_id
        ),
        date '1900-01-01'
      )
    )
    into v_date_to;

    v_date_from := v_date_to - 29;
  end if;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'primary_hotel_selected';
  passed := v_hotel_id is not null;
  details := format(
    'Hotel: %s (%s).',
    coalesce(v_hotel_name, 'missing'),
    coalesce(v_hotel_id::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'authorized_user_selected';
  passed := v_auth_user_id is not null;
  details := format(
    'Auth user: %s.',
    coalesce(v_auth_user_id::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'active_staff_identity';
  select exists (
    select 1
    from public.staff s
    where s.hotel_id = v_hotel_id
      and s.auth_user_id = v_auth_user_id
      and s.status = 'active'
  )
  into v_bool;
  passed := coalesce(v_bool, false);
  details := 'Selected identity is active staff for the selected hotel.';
  return next;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'reports_view_permission';
  select exists (
    select 1
    from public.staff s
    join public.role_permissions rp
      on lower(replace(trim(rp.role_name), ' ', '_'))
       = lower(replace(trim(s.role), ' ', '_'))
    where s.hotel_id = v_hotel_id
      and s.auth_user_id = v_auth_user_id
      and s.status = 'active'
      and rp.permission_key = 'reports.view'
  )
  into v_bool;
  passed := coalesce(v_bool, false);
  details := 'Selected identity has reports.view through its active staff role.';
  return next;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'platform_admin_state_known';
  passed := v_is_platform_admin is not null;
  details := format(
    'Selected identity platform-admin state: %s.',
    coalesce(v_is_platform_admin::text, 'unknown')
  );
  return next;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'hotel_timezone_valid';
  begin
    perform now() at time zone v_timezone;
    v_bool := true;
  exception when others then
    v_bool := false;
  end;
  passed := v_bool;
  details := format('Timezone: %s.', coalesce(v_timezone, 'missing'));
  return next;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'inclusive_30_day_window';
  passed := v_date_to >= v_date_from
    and (v_date_to - v_date_from) = 29;
  details := format(
    'Range: %s through %s.',
    coalesce(v_date_from::text, 'missing'),
    coalesce(v_date_to::text, 'missing')
  );
  return next;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'second_active_hotel_selected';
  passed := v_other_hotel_id is not null;
  details := format(
    'Other active hotel: %s.',
    coalesce(v_other_hotel_id::text, 'missing')
  );
  return next;

  select
    (select count(*) from public.folio_items fi
     where fi.hotel_id = v_hotel_id)
    + (select count(*) from public.guest_sessions gs
       where gs.hotel_id = v_hotel_id)
    + (select count(*) from public.food_orders fo
       where fo.hotel_id = v_hotel_id)
    + (select count(*) from public.service_requests sr
       where sr.hotel_id = v_hotel_id)
  into v_count;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'runtime_source_data_exists';
  passed := v_count > 0;
  details := format('%s source activity row(s).', v_count);
  return next;

  suite := 'RUNTIME_CONTEXT';
  test_name := 'context_ready';
  passed := v_hotel_id is not null
    and v_auth_user_id is not null
    and v_other_hotel_id is not null
    and v_date_from is not null
    and v_date_to is not null;
  details := 'Runtime reconciliation context is complete.';
  return next;

  perform set_config(
    'request.jwt.claim.sub',
    v_auth_user_id::text,
    true
  );

  v_filters := public.get_report_filter_options(v_hotel_id);
  v_kpi := public.get_report_kpi_summary(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_occupancy := public.get_report_occupancy_daily(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_revenue_daily := public.get_report_revenue_daily(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_revenue_category := public.get_report_revenue_by_category(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_sources := public.get_report_reservations_by_source(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_arrivals := public.get_report_arrivals_departures(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_payments := public.get_report_payments_by_method(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_tax := public.get_report_tax_gst_summary(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_guest_food_service := public.get_report_guest_food_service(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_service_sla := public.get_report_service_sla(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_housekeeping := public.get_report_housekeeping(
    v_hotel_id,
    v_date_from,
    v_date_to
  );
  v_staff := public.get_report_staff_department(
    v_hotel_id,
    v_date_from,
    v_date_to
  );

  -- Direct room-night source reconciliation.
  with report_days as (
    select day_value::date as report_date
    from generate_series(
      v_date_from::timestamp,
      v_date_to::timestamp,
      interval '1 day'
    ) day_value
  ),
  room_count as (
    select count(*)::numeric as total_rooms
    from public.rooms r
    where r.hotel_id = v_hotel_id
  ),
  blocked as (
    select distinct
      allocation.room_id,
      day_value::date as report_date
    from public.room_inventory_allocations allocation
    cross join lateral generate_series(
      greatest(allocation.starts_on, v_date_from)::timestamp,
      least(allocation.ends_on - 1, v_date_to)::timestamp,
      interval '1 day'
    ) day_value
    where allocation.hotel_id = v_hotel_id
      and allocation.allocation_type = 'block'
      and allocation.status <> 'cancelled'
      and allocation.starts_on <= v_date_to
      and allocation.ends_on > v_date_from
  ),
  sold as (
    select distinct
      allocation.room_id,
      day_value::date as report_date
    from public.room_inventory_allocations allocation
    cross join lateral generate_series(
      greatest(allocation.starts_on, v_date_from)::timestamp,
      least(allocation.ends_on - 1, v_date_to)::timestamp,
      interval '1 day'
    ) day_value
    where allocation.hotel_id = v_hotel_id
      and allocation.allocation_type in ('reservation', 'stay')
      and allocation.status <> 'cancelled'
      and allocation.starts_on <= v_date_to
      and allocation.ends_on > v_date_from
  ),
  occupied as (
    select distinct
      allocation.room_id,
      day_value::date as report_date
    from public.room_inventory_allocations allocation
    cross join lateral generate_series(
      greatest(allocation.starts_on, v_date_from)::timestamp,
      least(allocation.ends_on - 1, v_date_to)::timestamp,
      interval '1 day'
    ) day_value
    where allocation.hotel_id = v_hotel_id
      and allocation.allocation_type = 'stay'
      and allocation.status <> 'cancelled'
      and allocation.starts_on <= v_date_to
      and allocation.ends_on > v_date_from
  ),
  daily as (
    select
      report_days.report_date,
      room_count.total_rooms,
      count(distinct blocked.room_id)::numeric as blocked_count,
      count(distinct sold.room_id)::numeric as sold_count,
      count(distinct occupied.room_id)::numeric as occupied_count
    from report_days
    cross join room_count
    left join blocked
      on blocked.report_date = report_days.report_date
    left join sold
      on sold.report_date = report_days.report_date
    left join occupied
      on occupied.report_date = report_days.report_date
    group by report_days.report_date, room_count.total_rooms
  )
  select
    coalesce(sum(greatest(total_rooms - blocked_count, 0)), 0),
    coalesce(sum(sold_count), 0),
    coalesce(sum(occupied_count), 0),
    coalesce(sum(blocked_count), 0)
  into
    v_available,
    v_sold,
    v_occupied,
    v_blocked
  from daily;

  select
    coalesce(
      sum(fi.amount) filter (
        where fi.item_kind = 'charge'
          and fi.charge_category = 'room'
      ),
      0
    ),
    coalesce(
      sum(fi.amount) filter (
        where fi.item_kind = 'charge'
          and fi.charge_category = 'food'
      ),
      0
    ),
    coalesce(
      sum(fi.amount) filter (
        where fi.item_kind = 'charge'
          and fi.charge_category = 'service'
      ),
      0
    ),
    coalesce(
      sum(fi.amount) filter (
        where fi.item_kind = 'charge'
          and fi.charge_category in ('manual', 'other')
      ),
      0
    ),
    coalesce(
      sum(fi.amount) filter (
        where fi.item_kind = 'tax'
      ),
      0
    )
  into
    v_room_revenue,
    v_food_revenue,
    v_service_revenue,
    v_other_revenue,
    v_tax_revenue
  from public.folio_items fi
  where fi.hotel_id = v_hotel_id
    and fi.posting_status = 'posted'
    and (fi.service_at at time zone v_timezone)::date
      between v_date_from and v_date_to;

  v_gross_revenue :=
    v_room_revenue
    + v_food_revenue
    + v_service_revenue
    + v_other_revenue
    + v_tax_revenue;

  select coalesce(sum(fc.amount), 0)
  into v_collections
  from public.folio_collections fc
  where fc.hotel_id = v_hotel_id
    and fc.status = 'posted'
    and (fc.collected_at at time zone v_timezone)::date
      between v_date_from and v_date_to;

  select count(*)
  into v_reservation_count
  from public.reservations r
  where r.hotel_id = v_hotel_id
    and r.arrival_date between v_date_from and v_date_to;

  select count(*)
  into v_arrival_count
  from public.guest_sessions gs
  where gs.hotel_id = v_hotel_id
    and (gs.checkin_time at time zone v_timezone)::date
      between v_date_from and v_date_to;

  select count(*)
  into v_departure_count
  from public.guest_sessions gs
  where gs.hotel_id = v_hotel_id
    and gs.checkout_time is not null
    and gs.status = 'completed'
    and (gs.checkout_time at time zone v_timezone)::date
      between v_date_from and v_date_to;

  select count(*)
  into v_food_order_count
  from public.food_orders fo
  where fo.hotel_id = v_hotel_id
    and (fo.created_at at time zone v_timezone)::date
      between v_date_from and v_date_to;

  select count(*)
  into v_service_request_count
  from public.service_requests sr
  where sr.hotel_id = v_hotel_id
    and (sr.created_at at time zone v_timezone)::date
      between v_date_from and v_date_to;

  -- ========================================================================
  -- C. KPI reconciliation against authoritative source records: 25 rows.
  -- ========================================================================
  suite := 'KPI_RECONCILIATION';
  test_name := 'kpi_is_object';
  passed := jsonb_typeof(v_kpi) = 'object';
  details := 'KPI RPC returned a JSON object.';
  return next;

  suite := 'KPI_RECONCILIATION';
  test_name := 'timezone';
  passed := v_kpi ->> 'timezone' = v_timezone;
  details := format(
    'RPC: %s; source: %s.',
    coalesce(v_kpi ->> 'timezone', 'missing'),
    v_timezone
  );
  return next;

  suite := 'KPI_RECONCILIATION';
  test_name := 'date_from';
  passed := (v_kpi ->> 'date_from')::date = v_date_from;
  details := 'KPI start date matches the selected inclusive window.';
  return next;

  suite := 'KPI_RECONCILIATION';
  test_name := 'date_to';
  passed := (v_kpi ->> 'date_to')::date = v_date_to;
  details := 'KPI end date matches the selected inclusive window.';
  return next;

  suite := 'KPI_RECONCILIATION';
  test_name := 'available_room_nights';
  passed := (v_kpi ->> 'available_room_nights')::numeric = v_available;
  details := format('RPC %s; source %s.', v_kpi ->> 'available_room_nights', v_available);
  return next;

  suite := 'KPI_RECONCILIATION';
  test_name := 'sold_room_nights';
  passed := (v_kpi ->> 'sold_room_nights')::numeric = v_sold;
  details := format('RPC %s; source %s.', v_kpi ->> 'sold_room_nights', v_sold);
  return next;

  suite := 'KPI_RECONCILIATION';
  test_name := 'occupied_room_nights';
