  into
    v_count,
    v_amount,
    v_count_2,
    v_count_3,
    v_count_4,
    v_service_request_count
  from jsonb_array_elements(v_sources) item;

  suite := 'BUSINESS_REPORTS';
  test_name := 'source_reservation_count';
  passed := v_count = v_reservation_count;
