  suite := 'OPERATIONS_RECONCILIATION';
  test_name := 'unique_guests';
  passed := (v_guest_food_service ->> 'unique_guests')::bigint = v_count_2;
  details := format('Report %s; source %s.', v_guest_food_service ->> 'unique_guests', v_count_2);
  return next;

