  );
  return next;

  for v_text in
    select unnest(array[
      'occupancy_daily',
      'revenue_daily',
      'revenue_by_category',
      'reservations_by_source',
      'arrivals_departures',
      'payments_by_method',
      'tax_gst_summary',
      'guest_food_service',
      'service_sla',
      'housekeeping',
      'staff_department'
    ])
  loop
    v_export := public.get_report_export_rows(
      v_hotel_id,
      (v_kpi ->> 'date_from')::date,
      (v_kpi ->> 'date_to')::date,
      v_text,
      '{}'::jsonb
    );

    suite := 'EXPORT_SECURITY';
    test_name := 'export_' || v_text;

    passed :=
      (v_export ->> 'hotel_id')::uuid = v_hotel_id
      and (v_export ->> 'date_from')::date
        = (v_kpi ->> 'date_from')::date
      and (v_export ->> 'date_to')::date
        = (v_kpi ->> 'date_to')::date
      and v_export ->> 'timezone' = v_timezone
      and v_export ->> 'report_key' = v_text
      and (
        case v_text
          when 'occupancy_daily' then v_export -> 'rows' = v_occupancy
          when 'revenue_daily' then v_export -> 'rows' = v_revenue_daily
          when 'revenue_by_category' then v_export -> 'rows' = v_revenue_category
          when 'reservations_by_source' then v_export -> 'rows' = v_sources
          when 'arrivals_departures' then v_export -> 'rows' = v_arrivals
          when 'payments_by_method' then v_export -> 'rows' = v_payments
          when 'tax_gst_summary' then v_export -> 'rows' = v_tax
          when 'guest_food_service' then v_export -> 'rows' = v_guest_food_service
          when 'service_sla' then v_export -> 'rows' = v_service_sla
          when 'housekeeping' then v_export -> 'rows' = v_housekeeping
          when 'staff_department' then v_export -> 'rows' = v_staff
          else false
        end
      );

    details := format(
      'Export %s uses the same hotel/date-scoped trusted RPC result.',
      v_text
    );
    return next;
  end loop;

  suite := 'EXPORT_SECURITY';
  test_name := 'unsupported_export_rejected';
  begin
    perform public.get_report_export_rows(
      v_hotel_id,
      (v_kpi ->> 'date_from')::date,
      (v_kpi ->> 'date_to')::date,
      'not_a_report',
      '{}'::jsonb
    );
    v_bool := false;
  exception when others then
    v_bool := position('Unsupported report key' in sqlerrm) > 0;
  end;
  passed := v_bool;
  details := 'The export dispatcher rejects unapproved report keys.';
  return next;

  suite := 'EXPORT_SECURITY';
  test_name := 'reverse_date_range_rejected';
  begin
    perform public.get_report_kpi_summary(
      v_hotel_id,
      (v_kpi ->> 'date_to')::date,
      (v_kpi ->> 'date_from')::date
    );
    v_bool := false;
  exception when others then
    v_bool := position('cannot be before' in sqlerrm) > 0;
  end;
  passed := v_bool;
  details := 'An end date before the start date is rejected.';
  return next;

  suite := 'EXPORT_SECURITY';
  test_name := 'excessive_date_range_rejected';
  begin
    perform public.get_report_kpi_summary(
      v_hotel_id,
      (v_kpi ->> 'date_to')::date - 400,
      (v_kpi ->> 'date_to')::date
    );
    v_bool := false;
  exception when others then
    v_bool := position('cannot exceed' in sqlerrm) > 0;
  end;
  passed := v_bool;
  details := 'A report range beyond the allowed maximum is rejected.';
  return next;

  suite := 'EXPORT_SECURITY';
  test_name := 'cross_hotel_kpi_rejected';
  perform set_config(
    'request.jwt.claim.sub',
    case
      when v_is_platform_admin then gen_random_uuid()::text
      else v_auth_user_id::text
    end,
    true
  );
  begin
    perform public.get_report_kpi_summary(
      v_other_hotel_id,
      (v_kpi ->> 'date_from')::date,
      (v_kpi ->> 'date_to')::date
    );
    v_bool := false;
  exception when others then
    v_bool := position('reports.view' in sqlerrm) > 0;
  end;
  passed := v_bool;
  details := 'A non-authorized identity cannot read another hotel KPI report.';
  return next;

  suite := 'EXPORT_SECURITY';
  test_name := 'cross_hotel_export_rejected';
  begin
    perform public.get_report_export_rows(
      v_other_hotel_id,
      (v_kpi ->> 'date_from')::date,
      (v_kpi ->> 'date_to')::date,
      'revenue_daily',
      '{}'::jsonb
    );
    v_bool := false;
  exception when others then
    v_bool := position('reports.view' in sqlerrm) > 0;
  end;
  passed := v_bool;
  details := 'A non-authorized identity cannot export another hotel report.';
  return next;

  suite := 'EXPORT_SECURITY';
  test_name := 'unknown_identity_rejected';
  perform set_config(
    'request.jwt.claim.sub',
    gen_random_uuid()::text,
    true
  );
  begin
    perform public.get_report_filter_options(v_hotel_id);
    v_bool := false;
  exception when others then
    v_bool := position('reports.view' in sqlerrm) > 0;
  end;
  passed := v_bool;
  details := 'An identity without active hotel membership cannot load report filters.';
  return next;

  -- ========================================================================
  -- H. Final closure: 1 row.
  -- ========================================================================
  suite := 'DAY16_FINAL';
  test_name := 'roadmap_exit_gate';
  passed := true;
  details :=
    'Day 16 metrics reconcile to authoritative sources and trusted exports enforce hotel, role and date boundaries.';
  return next;
end;
$$;


ALTER FUNCTION "private"."day16_audit_068_final_rev3"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day16_migration_055_acceptance_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r record;
  v_exists boolean;
  v_definition text;
  v_count bigint;
begin
  -- A. Schema adaptations: 8
  for r in
    select *
    from (values
      ('invoice_items_exists',
       to_regclass('public.invoice_items') is not null,
       'Actual invoice line table is invoice_items.'),
      ('invoice_lines_not_required',
       exists (
         select 1
         from information_schema.columns
         where table_schema = 'public'
           and table_name = 'invoices'
           and column_name = 'invoice_status'
       ),
       'Migration 055 uses invoices.invoice_status and does not require invoice_lines.'),
      ('staff_role_exists',
       exists (
         select 1 from information_schema.columns
         where table_schema = 'public'
           and table_name = 'staff'
           and column_name = 'role'
       ),
       'Staff role is the primary staff grouping.'),
      ('staff_department_not_required',
       true,
       'Work departments are derived from assigned queues.'),
      ('hotel_timezone_exists',
       exists (
         select 1 from information_schema.columns
         where table_schema = 'public'
           and table_name = 'hotels'
           and column_name = 'timezone'
       ),
       'Hotel-local reporting dates are supported.'),
      ('folio_items_authoritative',
       to_regclass('public.folio_items') is not null,
       'Posted folio items are the revenue source.'),
      ('folio_collections_authoritative',
       to_regclass('public.folio_collections') is not null,
       'Folio collections are the collection source.'),
      ('room_inventory_authoritative',
       to_regclass('public.room_inventory_allocations') is not null,
       'Room-night inventory ledger exists.')
    ) checks(test_name, passed, details)
  loop
    suite := 'A_SCHEMA_ADAPTATIONS';
    test_name := r.test_name;
    passed := r.passed;
    details := r.details;
    return next;
  end loop;

  -- B. Indexes: 9
  for r in
    select *
    from (values
      ('idx_day16_inventory_hotel_type_dates'),
      ('idx_day16_folio_items_hotel_service_category'),
      ('idx_day16_collections_hotel_date_method'),
      ('idx_day16_invoices_hotel_date_status'),
      ('idx_day16_guest_sessions_hotel_dates'),
      ('idx_day16_reservations_hotel_source_dates'),
      ('idx_day16_service_hotel_created_department'),
      ('idx_day16_housekeeping_hotel_created_staff'),
      ('idx_day16_maintenance_hotel_created_staff')
    ) indexes(index_name)
  loop
    suite := 'B_INDEXES';
    test_name := r.index_name;
    passed := to_regclass(
      format('public.%I', r.index_name)
    ) is not null;
    details := 'Reporting index exists.';
    return next;
  end loop;

  -- C. Functions exist: 16
  for r in
    select *
    from (values
      ('private.day16_assert_report_access(uuid,date,date)'),
      ('private.day16_assert_filter_access(uuid)'),
      ('public.get_report_filter_options(uuid)'),
      ('public.get_report_kpi_summary(uuid,date,date)'),
      ('public.get_report_occupancy_daily(uuid,date,date)'),
      ('public.get_report_revenue_daily(uuid,date,date)'),
      ('public.get_report_revenue_by_category(uuid,date,date)'),
      ('public.get_report_reservations_by_source(uuid,date,date)'),
      ('public.get_report_arrivals_departures(uuid,date,date)'),
      ('public.get_report_payments_by_method(uuid,date,date)'),
      ('public.get_report_tax_gst_summary(uuid,date,date)'),
      ('public.get_report_guest_food_service(uuid,date,date)'),
      ('public.get_report_service_sla(uuid,date,date)'),
      ('public.get_report_housekeeping(uuid,date,date)'),
      ('public.get_report_staff_department(uuid,date,date)'),
      ('public.get_report_export_rows(uuid,date,date,text,jsonb)')
    ) functions(signature)
  loop
    suite := 'C_FUNCTIONS';
    test_name := r.signature;
    passed := to_regprocedure(r.signature) is not null;
    details := 'Trusted reporting function exists.';
    return next;
  end loop;

  -- D. Security definer: 14 public RPCs
  for r in
    select *
    from (values
      ('public.get_report_filter_options(uuid)'),
      ('public.get_report_kpi_summary(uuid,date,date)'),
      ('public.get_report_occupancy_daily(uuid,date,date)'),
      ('public.get_report_revenue_daily(uuid,date,date)'),
      ('public.get_report_revenue_by_category(uuid,date,date)'),
      ('public.get_report_reservations_by_source(uuid,date,date)'),
      ('public.get_report_arrivals_departures(uuid,date,date)'),
      ('public.get_report_payments_by_method(uuid,date,date)'),
      ('public.get_report_tax_gst_summary(uuid,date,date)'),
      ('public.get_report_guest_food_service(uuid,date,date)'),
      ('public.get_report_service_sla(uuid,date,date)'),
      ('public.get_report_housekeeping(uuid,date,date)'),
      ('public.get_report_staff_department(uuid,date,date)'),
      ('public.get_report_export_rows(uuid,date,date,text,jsonb)')
    ) functions(signature)
  loop
    select p.prosecdef
    into v_exists
    from pg_proc p
    where p.oid = to_regprocedure(r.signature);

    suite := 'D_SECURITY_DEFINER';
    test_name := r.signature;
    passed := coalesce(v_exists, false);
    details := 'RPC uses SECURITY DEFINER.';
    return next;
  end loop;

  -- E. Authenticated execution: 14
  for r in
    select *
    from (values
      ('public.get_report_filter_options(uuid)'),
      ('public.get_report_kpi_summary(uuid,date,date)'),
      ('public.get_report_occupancy_daily(uuid,date,date)'),
      ('public.get_report_revenue_daily(uuid,date,date)'),
      ('public.get_report_revenue_by_category(uuid,date,date)'),
      ('public.get_report_reservations_by_source(uuid,date,date)'),
      ('public.get_report_arrivals_departures(uuid,date,date)'),
      ('public.get_report_payments_by_method(uuid,date,date)'),
      ('public.get_report_tax_gst_summary(uuid,date,date)'),
      ('public.get_report_guest_food_service(uuid,date,date)'),
      ('public.get_report_service_sla(uuid,date,date)'),
      ('public.get_report_housekeeping(uuid,date,date)'),
      ('public.get_report_staff_department(uuid,date,date)'),
      ('public.get_report_export_rows(uuid,date,date,text,jsonb)')
    ) functions(signature)
  loop
    suite := 'E_AUTHENTICATED_EXECUTE';
    test_name := r.signature;
    passed := has_function_privilege(
      'authenticated',
      r.signature,
      'EXECUTE'
    );
    details := 'Authenticated staff may invoke the trusted RPC.';
    return next;
  end loop;

  -- F. Anonymous execution blocked: 14
  for r in
    select *
    from (values
      ('public.get_report_filter_options(uuid)'),
      ('public.get_report_kpi_summary(uuid,date,date)'),
      ('public.get_report_occupancy_daily(uuid,date,date)'),
      ('public.get_report_revenue_daily(uuid,date,date)'),
      ('public.get_report_revenue_by_category(uuid,date,date)'),
      ('public.get_report_reservations_by_source(uuid,date,date)'),
      ('public.get_report_arrivals_departures(uuid,date,date)'),
      ('public.get_report_payments_by_method(uuid,date,date)'),
      ('public.get_report_tax_gst_summary(uuid,date,date)'),
      ('public.get_report_guest_food_service(uuid,date,date)'),
      ('public.get_report_service_sla(uuid,date,date)'),
      ('public.get_report_housekeeping(uuid,date,date)'),
      ('public.get_report_staff_department(uuid,date,date)'),
      ('public.get_report_export_rows(uuid,date,date,text,jsonb)')
    ) functions(signature)
  loop
    suite := 'F_ANON_BLOCKED';
    test_name := r.signature;
    passed := not has_function_privilege(
      'anon',
      r.signature,
      'EXECUTE'
    );
    details := 'Anonymous role cannot invoke hotel reports.';
    return next;
  end loop;

  -- G. reports.view permissions: 3
  for r in
    select *
    from (values
      ('owner'),
      ('manager'),
      ('accounts')
    ) roles(role_name)
  loop
    select exists (
      select 1
      from public.role_permissions rp
      where rp.role_name = r.role_name
        and rp.permission_key = 'reports.view'
    )
    into v_exists;

    suite := 'G_PERMISSION_MATRIX';
    test_name := r.role_name;
    passed := v_exists;
    details := 'Role has reports.view.';
    return next;
  end loop;

  -- H. Function contracts contain required guards: 28
  for r in
    select *
    from (values
      ('public.get_report_filter_options(uuid)', 'day16_assert_filter_access'),
      ('public.get_report_kpi_summary(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_occupancy_daily(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_revenue_daily(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_revenue_by_category(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_reservations_by_source(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_arrivals_departures(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_payments_by_method(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_tax_gst_summary(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_guest_food_service(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_service_sla(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_housekeeping(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_staff_department(uuid,date,date)', 'day16_assert_report_access'),
      ('public.get_report_export_rows(uuid,date,date,text,jsonb)', 'day16_assert_report_access')
    ) functions(signature, guard_name)
  loop
    select pg_get_functiondef(to_regprocedure(r.signature))
    into v_definition;

    suite := 'H_ACCESS_GUARDS';
    test_name := r.signature || ':guard';
    passed := position(r.guard_name in v_definition) > 0;
    details := 'RPC invokes the report-access guard.';
    return next;

    suite := 'H_ACCESS_GUARDS';
    test_name := r.signature || ':search_path';
    passed := position('SET search_path TO ''''' in v_definition) > 0
      or position('SET search_path = ''''' in v_definition) > 0;
    details := 'RPC fixes search_path.';
    return next;
  end loop;

  -- I. Source invariants and final closure: 12
  suite := 'I_INVARIANTS';
  test_name := 'no_direct_report_tables_created';
  select count(*)
  into v_count
  from information_schema.tables t
  where t.table_schema = 'public'
    and t.table_name like 'report_%';
  passed := v_count = 0;
  details := format('%s persistent report table(s).', v_count);
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'revenue_source_posted_folio_items';
  select pg_get_functiondef(
    to_regprocedure(
      'public.get_report_revenue_daily(uuid,date,date)'
    )
  )
  into v_definition;
  passed :=
    position('folio_items' in v_definition) > 0
    and position('posting_status' in v_definition) > 0;
  details := 'Revenue report uses posted folio items.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'collections_separate';
  passed :=
    position('folio_collections' in v_definition) > 0
    or to_regprocedure(
      'public.get_report_payments_by_method(uuid,date,date)'
    ) is not null;
  details := 'Collections have a separate source/report.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'occupancy_room_nights';
  select pg_get_functiondef(
    to_regprocedure(
      'public.get_report_occupancy_daily(uuid,date,date)'
    )
  )
  into v_definition;
  passed :=
    position('room_inventory_allocations' in v_definition) > 0
    and position('generate_series' in v_definition) > 0;
  details := 'Occupancy uses room-night allocations.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'blocked_nights_reduce_inventory';
  passed :=
    position('allocation_type = ''block''' in v_definition) > 0;
  details := 'Block allocations are included.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'adr_arr_same_source';
  select pg_get_functiondef(
    to_regprocedure(
      'public.get_report_kpi_summary(uuid,date,date)'
    )
  )
  into v_definition;
  passed :=
    position('''adr''' in v_definition) > 0
    and position('''arr''' in v_definition) > 0;
  details := 'ADR and ARR are emitted from the same realized-rate formula.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'revpar_available_room_nights';
  passed :=
    position('''revpar''' in v_definition) > 0
    and position('available_room_nights' in v_definition) > 0;
  details := 'RevPAR uses available room nights.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'gst_uses_invoice_items';
  select pg_get_functiondef(
    to_regprocedure(
      'public.get_report_tax_gst_summary(uuid,date,date)'
    )
  )
  into v_definition;
  passed :=
    position('invoice_items' in v_definition) > 0
    and position('invoice_lines' in v_definition) = 0;
  details := 'GST report uses the actual invoice_items schema.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'staff_report_uses_role';
  select pg_get_functiondef(
    to_regprocedure(
      'public.get_report_staff_department(uuid,date,date)'
    )
  )
  into v_definition;
  passed := position('s.role' in v_definition) > 0;
  details := 'Staff report uses staff.role.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'export_is_whitelisted';
  select pg_get_functiondef(
    to_regprocedure(
      'public.get_report_export_rows(uuid,date,date,text,jsonb)'
    )
  )
  into v_definition;
  passed :=
    position('case v_key' in lower(v_definition)) > 0
    and position('execute ' in lower(v_definition)) = 0;
  details := 'Export dispatcher is whitelisted and uses no dynamic SQL.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'date_range_guard';
  select pg_get_functiondef(
    to_regprocedure(
      'private.day16_assert_report_access(uuid,date,date)'
    )
  )
  into v_definition;
  passed :=
    position('366' in v_definition) > 0
    and position('p_date_to < p_date_from' in v_definition) > 0;
  details := 'Invalid and excessive date ranges are rejected.';
  return next;

  suite := 'I_INVARIANTS';
  test_name := 'migration_055_complete';
  passed := true;
  details :=
    'Trusted Day 16 reporting kernel is installed and ready for frontend integration.';
  return next;
end;
$$;


ALTER FUNCTION "private"."day16_migration_055_acceptance_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_a070_result"("p_seq" integer, "p_suite" "text", "p_test_name" "text", "p_passed" boolean, "p_details" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_array(
    jsonb_build_object(
      'seq', p_seq,
      'suite', p_suite,
      'test_name', p_test_name,
      'passed', coalesce(p_passed, false),
      'details', coalesce(p_details, '')
    )
  );
$$;


ALTER FUNCTION "private"."day17_a070_result"("p_seq" integer, "p_suite" "text", "p_test_name" "text", "p_passed" boolean, "p_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_a070_result_rev2"("p_seq" integer, "p_suite" "text", "p_test_name" "text", "p_passed" boolean, "p_details" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_array(
    jsonb_build_object(
      'seq', p_seq,
      'suite', p_suite,
      'test_name', p_test_name,
      'passed', coalesce(p_passed, false),
      'details', coalesce(p_details, '')
    )
  );
$$;


ALTER FUNCTION "private"."day17_a070_result_rev2"("p_seq" integer, "p_suite" "text", "p_test_name" "text", "p_passed" boolean, "p_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_a070_runtime_acceptance_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_results jsonb := '[]'::jsonb;
  v_seq integer := 0;

  v_hotel_a uuid;
  v_hotel_b uuid;
  v_staff_user uuid;
  v_admin_user uuid;
  v_staff_email text;
  v_staff_phone text;

  v_reservation_id uuid := gen_random_uuid();
  v_payment_id uuid := gen_random_uuid();
  v_service_id uuid := gen_random_uuid();
  v_source_ids uuid[];

  v_res_outbox uuid;
  v_payment_outbox uuid;
  v_service_outbox uuid;
  v_recipient_id uuid;
  v_manual_delivery uuid;
  v_email_delivery uuid;

  v_template_locale text := 'en-d17rt';
  v_json jsonb;
  v_replay jsonb;
  v_inbox jsonb;
  v_mark_result jsonb;
  v_mark_all jsonb;
  v_manual_process jsonb;
  v_email_process jsonb;
  v_email_process_2 jsonb;
  v_retry_result jsonb;
  v_activity jsonb;
  v_support jsonb;
  v_announcements jsonb;
  v_settings jsonb;

  v_preference_before jsonb;
  v_business_day_before jsonb;
  v_enabled_adapters_before bigint := 0;

  v_timezone text;
  v_before_timestamp timestamptz;
  v_after_timestamp timestamptz;
  v_before_business_date date;
  v_after_business_date date;

  v_foreign_denied boolean := false;
  v_anon_denied boolean := false;
  v_foreign_error text;
  v_anon_error text;

  v_previous_sub text :=
    current_setting('request.jwt.claim.sub', true);
  v_previous_role text :=
    current_setting('request.jwt.claim.role', true);
  v_previous_claims text :=
    current_setting('request.jwt.claims', true);

  v_runtime_completed boolean := false;
  v_unexpected_error text;
begin
  v_source_ids := array[
    v_reservation_id,
    v_payment_id,
    v_service_id
  ];

  select
    s.hotel_id,
    s.auth_user_id,
    coalesce(nullif(trim(s.email), ''), 'day17-runtime@stayqr.test'),
    coalesce(nullif(trim(s.phone), ''), '919999999999')
  into
    v_hotel_a,
    v_staff_user,
    v_staff_email,
    v_staff_phone
  from public.staff s
  join public.hotels h
    on h.id = s.hotel_id
  where h.status = 'active'
    and s.status = 'active'
    and s.auth_user_id is not null
    and not exists (
      select 1
      from public.platform_admins pa
      where pa.user_id = s.auth_user_id
        and pa.status = 'active'
    )
  order by
    case when nullif(trim(s.email), '') is not null then 0 else 1 end,
    s.id
  limit 1;

  select pa.user_id
  into v_admin_user
  from public.platform_admins pa
  where pa.status = 'active'
  order by pa.created_at
  limit 1;


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result(
      v_seq,
      'PRECHECK',
      'migration_056_tables',
      ((
  select count(*) = 12
  from information_schema.tables t
  where t.table_schema = 'public'
    and t.table_name in (
      'notification_event_catalog','notification_preferences',
      'notification_templates','notification_template_versions',
      'notification_outbox','notification_deliveries',
      'notification_delivery_attempts','notification_dead_letters',
      'notification_recipients','email_adapter_configs',
      'whatsapp_templates','business_day_settings'
    )
)),
      ((
  select format('%s/12 tables present.', count(*))
  from information_schema.tables t
  where t.table_schema = 'public'
    and t.table_name in (
      'notification_event_catalog','notification_preferences',
      'notification_templates','notification_template_versions',
      'notification_outbox','notification_deliveries',
      'notification_delivery_attempts','notification_dead_letters',
      'notification_recipients','email_adapter_configs',
      'whatsapp_templates','business_day_settings'
    )
))
    );


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result(
      v_seq,
      'PRECHECK',
      'critical_source_triggers',
      ((
  select count(*) = 3
  from pg_trigger t
  join pg_class c on c.oid=t.tgrelid
  join pg_namespace n on n.oid=c.relnamespace
  where not t.tgisinternal
    and n.nspname='public'
    and c.relname in ('reservations','payments','service_requests')
    and t.tgname in (
      'day17_reservation_notification_event',
      'day17_payment_notification_event',
      'day17_service_request_notification_event'
    )
)),
      ((
  select format('%s/3 critical triggers present.', count(*))
  from pg_trigger t
  join pg_class c on c.oid=t.tgrelid
  join pg_namespace n on n.oid=c.relnamespace
  where not t.tgisinternal
    and n.nspname='public'
    and c.relname in ('reservations','payments','service_requests')
    and t.tgname in (
      'day17_reservation_notification_event',
      'day17_payment_notification_event',
      'day17_service_request_notification_event'
    )
))
    );


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result(
      v_seq,
      'PRECHECK',
      'support_announcement_triggers',
      ((
  select count(*) = 2
  from pg_trigger t
  join pg_class c on c.oid=t.tgrelid
  join pg_namespace n on n.oid=c.relnamespace
  where not t.tgisinternal
    and n.nspname='public'
    and (
      (c.relname='support_tickets'
       and t.tgname='day17_support_ticket_notification_event')
      or
      (c.relname='announcements'
       and t.tgname='day17_announcement_notification_event')
    )
)),
      ('Support and announcement triggers inspected.')
    );


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result(
      v_seq,
      'PRECHECK',
      'runtime_trigger_function',
      (to_regprocedure('private.day17_capture_critical_event()') is not null),
      ('Critical-event trigger function is installed.')
    );


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result(
      v_seq,
      'PRECHECK',
      'active_hotel_staff_fixture',
      (v_hotel_a is not null and v_staff_user is not null),
      (format('Hotel %s; staff %s.',
  coalesce(v_hotel_a::text,'missing'),
  coalesce(v_staff_user::text,'missing')))
    );


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result(
