        'in_app_enabled', true,
        'email_enabled', false,
        'manual_whatsapp_enabled', false,
        'locale', 'en',
        'event_overrides', '{}'::jsonb
      )
    );

    perform set_config(
      'request.jwt.claim.sub',
      v_admin_user::text,
      true
    );
    perform set_config(
      'request.jwt.claims',
      jsonb_build_object(
        'sub', v_admin_user,
        'role', 'authenticated'
      )::text,
