      'pending',
      117.00;

    execute $dml$
      insert into pg_temp.service_requests (
        id,
        hotel_id,
        request_type,
        department,
        status,
        created_at,
        updated_at
      ) values ($1, $2, $3, $4, $5, now(), now())
    $dml$
    using
      v_service_id,
      v_hotel_a,
      'runtime_acceptance',
      'guest_services',
      'pending';

    execute $dml$
      update pg_temp.reservations
      set status = 'checked_in', updated_at = now()
      where id = $1
    $dml$
    using v_reservation_id;

    execute $dml$
      update pg_temp.payments
      set payment_status = 'paid', updated_at = now()
      where id = $1
    $dml$
    using v_payment_id;

    execute $dml$
      update pg_temp.service_requests
      set status = 'accepted', updated_at = now()
      where id = $1
    $dml$
    using v_service_id;

    execute $dml$
      update pg_temp.reservations
      set status = 'checked_in', updated_at = now()
      where id = $1
    $dml$
    using v_reservation_id;

    execute $dml$
      update pg_temp.payments
      set payment_status = 'paid', updated_at = now()
      where id = $1
    $dml$
    using v_payment_id;

    execute $dml$
      update pg_temp.service_requests
      set status = 'accepted', updated_at = now()
      where id = $1
    $dml$
    using v_service_id;

    v_replay := private.day17_enqueue_notification_event_internal(
