      'foreign_hotel_available',
      (v_hotel_b is not null),
      (format('Comparison hotel %s.',coalesce(v_hotel_b::text,'none')))
    );


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result(
