      v_seq,
      'ROLLBACK_CLEANUP',
      'jwt_claims_restored',
      (coalesce(current_setting('request.jwt.claim.sub',true),'')
   =coalesce(v_previous_sub,'')),
      ('SQL Editor JWT claim context was restored.')
    );


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result_rev2(
      v_seq,
      'ROLLBACK_CLEANUP',
      'no_runtime_dead_letters',
      (not exists(
  select 1 from public.notification_dead_letters ndl
  where ndl.delivery_id=v_email_delivery
)),
      ('No runtime dead-letter fixture remains.')
    );


    v_seq := v_seq + 1;
    v_results := v_results || private.day17_a070_result_rev2(
      v_seq,
      'ROLLBACK_CLEANUP',
      'reversible_runtime_complete',
      (v_runtime_completed and v_unexpected_error is null),
      (coalesce(v_unexpected_error,
  'All runtime operations completed and were rolled back.'))
    );


  return query
  select
    result.suite,
    result.test_name,
    result.passed,
    result.details
  from jsonb_to_recordset(v_results) as result(
    seq integer,
    suite text,
    test_name text,
    passed boolean,
    details text
  )
  order by result.seq;
end;
$_$;


ALTER FUNCTION "private"."day17_a070_runtime_acceptance_rev2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_a071_final_consolidated_acceptance_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_admin_user uuid;
  v_hotel_id uuid;
  v_hotel_name text;

  v_previous_sub text :=
    current_setting('request.jwt.claim.sub', true);
  v_previous_role text :=
    current_setting('request.jwt.claim.role', true);
  v_previous_claims text :=
    current_setting('request.jwt.claims', true);

  v_inbox jsonb;
  v_activity jsonb;
  v_settings jsonb;
  v_support jsonb;
  v_announcements jsonb;
  v_runtime_error text;
begin
  -- ========================================================================
  -- A. Replay all accepted Migration 056 contracts: 275 rows.
  -- ========================================================================
  return query
  select
    'M056_' || accepted.suite,
    accepted.test_name,
    accepted.passed,
    accepted.details
  from private.day17_migration_056_acceptance_rev2() accepted;

  -- ========================================================================
  -- B. Replay complete reversible notification runtime: 75 rows.
  -- ========================================================================
  return query
  select
    'A070_' || accepted.suite,
    accepted.test_name,
    accepted.passed,
    accepted.details
  from private.day17_a070_runtime_acceptance_rev2() accepted;

  -- ========================================================================
  -- C. Replay Migration 057 privilege/RPC hotfix: 37 rows.
  -- ========================================================================
  return query
  select
    'M057_' || accepted.suite,
    accepted.test_name,
    accepted.passed,
    accepted.details
  from private.day17_migration_057_acceptance_rev1() accepted;

  -- ========================================================================
  -- D. Final fixed prerequisite, privilege and data-plane checks: 28 rows.
  -- ========================================================================
  return query
  select
    final_checks.suite,
    final_checks.test_name,
    final_checks.passed,
    final_checks.details
  from (
    values
      -- FINAL_CHECK_01
      (
        'DAY17_FINAL_PREREQUISITE'::text,
        'm056_acceptance_helper'::text,
        to_regprocedure(
          'private.day17_migration_056_acceptance_rev2()'
        ) is not null,
        'Migration 056 accepted helper is installed.'::text
      ),
      -- FINAL_CHECK_02
      (
        'DAY17_FINAL_PREREQUISITE',
        'a070_runtime_helper',
        to_regprocedure(
          'private.day17_a070_runtime_acceptance_rev2()'
        ) is not null,
        'Audit 070 REV2 runtime helper is installed.'
      ),
      -- FINAL_CHECK_03
      (
        'DAY17_FINAL_PREREQUISITE',
        'm057_acceptance_helper',
        to_regprocedure(
          'private.day17_migration_057_acceptance_rev1()'
        ) is not null,
        'Migration 057 acceptance helper is installed.'
      ),
      -- FINAL_CHECK_04
      (
        'DAY17_FINAL_PREREQUISITE',
        'notification_inbox_rpc',
        to_regprocedure(
          'public.get_notification_inbox(uuid,integer,timestamp with time zone)'
        ) is not null,
        'Trusted notification inbox RPC is installed.'
      ),
      -- FINAL_CHECK_05
      (
        'DAY17_FINAL_PREREQUISITE',
        'activity_timeline_rpc',
        to_regprocedure(
          'public.get_activity_timeline(uuid,timestamp with time zone,timestamp with time zone,jsonb)'
        ) is not null,
        'Trusted activity timeline RPC is installed.'
      ),
      -- FINAL_CHECK_06
      (
        'DAY17_FINAL_PREREQUISITE',
        'system_settings_rpc',
        to_regprocedure(
          'public.get_hotel_system_settings(uuid)'
        ) is not null,
        'Trusted system-settings reader is installed.'
      ),
      -- FINAL_CHECK_07
      (
        'DAY17_FINAL_PREREQUISITE',
        'support_workspace_rpc',
        to_regprocedure(
          'public.get_support_workspace(uuid)'
        ) is not null,
        'Trusted support workspace RPC is installed.'
      ),
      -- FINAL_CHECK_08
      (
        'DAY17_FINAL_PREREQUISITE',
        'announcements_rpc',
        to_regprocedure(
          'public.get_active_announcements(uuid)'
        ) is not null,
        'Trusted announcements RPC is installed.'
      ),
      -- FINAL_CHECK_09
      (
        'DAY17_FINAL_PREREQUISITE',
        'email_adapter_writer_rpc',
        to_regprocedure(
          'public.upsert_email_adapter_config(uuid,jsonb)'
        ) is not null,
        'Trusted email adapter writer is installed.'
      ),
      -- FINAL_CHECK_10
      (
        'DAY17_FINAL_PREREQUISITE',
        'manual_whatsapp_writer_rpc',
        to_regprocedure(
          'public.upsert_manual_whatsapp_template(uuid,jsonb)'
        ) is not null,
        'Trusted manual WhatsApp writer is installed.'
      ),
      -- FINAL_CHECK_11
      (
        'DAY17_FINAL_PRIVILEGE',
        'management_helper_authenticated_execute',
        has_function_privilege(
          'authenticated',
          'private.day17_can_manage_hotel(uuid)',
          'EXECUTE'
        ),
        'Authenticated users can evaluate management RLS safely.'
      ),
      -- FINAL_CHECK_12
      (
        'DAY17_FINAL_PRIVILEGE',
        'management_helper_anon_blocked',
        not has_function_privilege(
          'anon',
          'private.day17_can_manage_hotel(uuid)',
          'EXECUTE'
        ),
        'Anonymous execution remains blocked.'
      ),
      -- FINAL_CHECK_13
      (
        'DAY17_FINAL_PRIVILEGE',
        'notification_inbox_authenticated_execute',
        has_function_privilege(
          'authenticated',
          'public.get_notification_inbox(uuid,integer,timestamp with time zone)',
          'EXECUTE'
        ),
        'Authenticated inbox execution is granted.'
      ),
      -- FINAL_CHECK_14
      (
        'DAY17_FINAL_PRIVILEGE',
        'notification_inbox_anon_blocked',
        not has_function_privilege(
          'anon',
          'public.get_notification_inbox(uuid,integer,timestamp with time zone)',
          'EXECUTE'
        ),
        'Anonymous inbox execution is blocked.'
      ),
      -- FINAL_CHECK_15
      (
        'DAY17_FINAL_PRIVILEGE',
        'settings_update_authenticated_execute',
        has_function_privilege(
          'authenticated',
          'public.update_hotel_system_settings(uuid,jsonb)',
          'EXECUTE'
        ),
        'Authenticated settings update execution is granted.'
      ),
      -- FINAL_CHECK_16
      (
        'DAY17_FINAL_PRIVILEGE',
        'settings_update_anon_blocked',
        not has_function_privilege(
          'anon',
          'public.update_hotel_system_settings(uuid,jsonb)',
          'EXECUTE'
        ),
        'Anonymous settings updates are blocked.'
      ),
      -- FINAL_CHECK_17
      (
        'DAY17_FINAL_PRIVILEGE',
        'email_adapter_writer_authenticated_execute',
        has_function_privilege(
          'authenticated',
          'public.upsert_email_adapter_config(uuid,jsonb)',
          'EXECUTE'
        ),
        'Authenticated email adapter writes use the trusted RPC.'
      ),
      -- FINAL_CHECK_18
      (
        'DAY17_FINAL_PRIVILEGE',
        'email_adapter_writer_anon_blocked',
        not has_function_privilege(
          'anon',
          'public.upsert_email_adapter_config(uuid,jsonb)',
          'EXECUTE'
        ),
        'Anonymous email adapter writes are blocked.'
      ),
      -- FINAL_CHECK_19
      (
        'DAY17_FINAL_PRIVILEGE',
        'whatsapp_writer_authenticated_execute',
        has_function_privilege(
          'authenticated',
          'public.upsert_manual_whatsapp_template(uuid,jsonb)',
          'EXECUTE'
        ),
        'Authenticated manual WhatsApp writes use the trusted RPC.'
      ),
      -- FINAL_CHECK_20
      (
        'DAY17_FINAL_PRIVILEGE',
        'whatsapp_writer_anon_blocked',
        not has_function_privilege(
          'anon',
          'public.upsert_manual_whatsapp_template(uuid,jsonb)',
          'EXECUTE'
        ),
        'Anonymous manual WhatsApp writes are blocked.'
      ),
      -- FINAL_CHECK_21
      (
        'DAY17_FINAL_DATA_PLANE',
        'notification_recipients_rls',
        coalesce(
          (
            select c.relrowsecurity
            from pg_catalog.pg_class c
            join pg_catalog.pg_namespace n
              on n.oid = c.relnamespace
            where n.nspname = 'public'
              and c.relname = 'notification_recipients'
          ),
          false
        ),
        'notification_recipients has RLS enabled.'
      ),
      -- FINAL_CHECK_22
      (
        'DAY17_FINAL_DATA_PLANE',
        'notification_deliveries_rls',
        coalesce(
          (
            select c.relrowsecurity
            from pg_catalog.pg_class c
            join pg_catalog.pg_namespace n
              on n.oid = c.relnamespace
            where n.nspname = 'public'
              and c.relname = 'notification_deliveries'
          ),
          false
        ),
        'notification_deliveries has RLS enabled.'
      ),
      -- FINAL_CHECK_23
      (
        'DAY17_FINAL_DATA_PLANE',
        'activity_logs_rls',
        coalesce(
          (
            select c.relrowsecurity
            from pg_catalog.pg_class c
            join pg_catalog.pg_namespace n
              on n.oid = c.relnamespace
            where n.nspname = 'public'
              and c.relname = 'activity_logs'
          ),
          false
        ),
        'activity_logs has RLS enabled.'
      ),
      -- FINAL_CHECK_24
      (
        'DAY17_FINAL_DATA_PLANE',
        'email_adapter_configs_rls',
        coalesce(
          (
            select c.relrowsecurity
            from pg_catalog.pg_class c
            join pg_catalog.pg_namespace n
              on n.oid = c.relnamespace
            where n.nspname = 'public'
              and c.relname = 'email_adapter_configs'
          ),
          false
        ),
        'email_adapter_configs has RLS enabled.'
      ),
      -- FINAL_CHECK_25
      (
        'DAY17_FINAL_DATA_PLANE',
        'whatsapp_templates_rls',
        coalesce(
          (
            select c.relrowsecurity
            from pg_catalog.pg_class c
            join pg_catalog.pg_namespace n
              on n.oid = c.relnamespace
            where n.nspname = 'public'
              and c.relname = 'whatsapp_templates'
          ),
          false
        ),
        'whatsapp_templates has RLS enabled.'
      ),
      -- FINAL_CHECK_26
      (
        'DAY17_FINAL_DATA_PLANE',
        'notification_recipients_realtime',
        exists (
          select 1
          from pg_catalog.pg_publication_tables ppt
          where ppt.pubname = 'supabase_realtime'
            and ppt.schemaname = 'public'
            and ppt.tablename = 'notification_recipients'
        ),
        'notification_recipients is in the realtime publication.'
      ),
      -- FINAL_CHECK_27
      (
        'DAY17_FINAL_DATA_PLANE',
        'notification_deliveries_realtime',
        exists (
          select 1
          from pg_catalog.pg_publication_tables ppt
          where ppt.pubname = 'supabase_realtime'
            and ppt.schemaname = 'public'
            and ppt.tablename = 'notification_deliveries'
        ),
        'notification_deliveries is in the realtime publication.'
      ),
      -- FINAL_CHECK_28
      (
        'DAY17_FINAL_DATA_PLANE',
        'email_adapter_select_policy_uses_management_helper',
        exists (
          select 1
          from pg_catalog.pg_policy pol
          join pg_catalog.pg_class c
            on c.oid = pol.polrelid
          join pg_catalog.pg_namespace n
            on n.oid = c.relnamespace
          where n.nspname = 'public'
            and c.relname = 'email_adapter_configs'
            and pol.polname = 'email_adapter_configs_select_day17'
            and pg_catalog.pg_get_expr(
              pol.polqual,
              pol.polrelid
            ) ilike '%day17_can_manage_hotel%'
        ),
        'Email adapter reads remain management-scoped.'
      )
  ) final_checks(suite, test_name, passed, details);

  -- ========================================================================
  -- E. Final real authorized read smoke with restored JWT state: 5 rows.
  -- ========================================================================

  select pa.user_id
  into v_admin_user
  from public.platform_admins pa
  join auth.users au
    on au.id = pa.user_id
  where pa.status = 'active'
    and coalesce(
      au.banned_until,
      '-infinity'::timestamptz
    ) <= now()
  order by pa.created_at, pa.user_id
  limit 1;

  select h.id, h.hotel_name
  into v_hotel_id, v_hotel_name
  from public.hotels h
  where h.status = 'active'
  order by h.created_at, h.id
  limit 1;

  begin
    if v_admin_user is null then
      raise exception 'No active platform admin was available.';
    end if;

    if v_hotel_id is null then
      raise exception 'No active hotel was available.';
    end if;

    perform set_config(
      'request.jwt.claim.sub',
      v_admin_user::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );
    perform set_config(
      'request.jwt.claims',
      jsonb_build_object(
        'sub', v_admin_user,
        'role', 'authenticated'
      )::text,
      true
    );

    v_inbox := public.get_notification_inbox(
      v_hotel_id,
      10,
      null
    );

    v_activity := public.get_activity_timeline(
      v_hotel_id,
      now() - interval '30 days',
      now(),
      jsonb_build_object('limit', 25)
    );

    v_settings := public.get_hotel_system_settings(
      v_hotel_id
    );

    v_support := public.get_support_workspace(
      v_hotel_id
    );

    v_announcements := public.get_active_announcements(
      v_hotel_id
    );
  exception
    when others then
      v_runtime_error := format(
        '%s [%s]',
        sqlerrm,
        sqlstate
      );
  end;

  perform set_config(
    'request.jwt.claim.sub',
    coalesce(v_previous_sub, ''),
    true
  );
  perform set_config(
    'request.jwt.claim.role',
    coalesce(v_previous_role, ''),
    true
  );
  perform set_config(
    'request.jwt.claims',
    coalesce(v_previous_claims, '{}'),
    true
  );

  return query
  select
    smoke.suite,
    smoke.test_name,
    smoke.passed,
    smoke.details
  from (
    values
      -- FINAL_CHECK_29
      (
        'DAY17_FINAL_RUNTIME'::text,
        'notification_inbox_real_authorized_read'::text,
        v_runtime_error is null
          and jsonb_typeof(v_inbox) = 'object',
        coalesce(
          v_runtime_error,
          format(
            '%s / %s',
            coalesce(v_hotel_name, 'Unknown hotel'),
            coalesce(v_inbox::text, 'null')
          )
        )::text
      ),
      -- FINAL_CHECK_30
      (
        'DAY17_FINAL_RUNTIME',
        'activity_timeline_real_authorized_read',
        v_runtime_error is null
          and jsonb_typeof(v_activity) = 'object',
        coalesce(
          v_runtime_error,
          format(
            '%s / %s',
            coalesce(v_hotel_name, 'Unknown hotel'),
            coalesce(v_activity::text, 'null')
          )
        )
      ),
      -- FINAL_CHECK_31
      (
        'DAY17_FINAL_RUNTIME',
        'system_settings_real_authorized_read',
        v_runtime_error is null
          and jsonb_typeof(v_settings) = 'object',
        coalesce(
          v_runtime_error,
          format(
            '%s / settings loaded',
            coalesce(v_hotel_name, 'Unknown hotel')
          )
        )
      ),
      -- FINAL_CHECK_32
      (
        'DAY17_FINAL_RUNTIME',
        'support_workspace_real_authorized_read',
        v_runtime_error is null
          and jsonb_typeof(v_support) = 'object',
        coalesce(
          v_runtime_error,
          format(
            '%s / support workspace loaded',
            coalesce(v_hotel_name, 'Unknown hotel')
          )
        )
      ),
      -- FINAL_CHECK_33
      (
        'DAY17_FINAL_RUNTIME',
        'announcements_real_authorized_read',
        v_runtime_error is null
          and jsonb_typeof(v_announcements) in ('array', 'object'),
        coalesce(
          v_runtime_error,
          format(
            '%s / announcements loaded',
            coalesce(v_hotel_name, 'Unknown hotel')
          )
        )
      )
  ) smoke(suite, test_name, passed, details);
end;
$$;


ALTER FUNCTION "private"."day17_a071_final_consolidated_acceptance_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_audit_069_preflight_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rec record;
  v_exists boolean;
  v_count bigint;
  v_count_2 bigint;
  v_text text;
begin
  -- A. Locked roadmap contract.
  for rec in
    select *
    from (
      values
      ('in_app_realtime', 'In-app realtime notification inbox and live updates.'),
      ('notification_preferences', 'Hotel/user notification channel and event preferences.'),
      ('notification_templates', 'Reusable event templates with safe variables.'),
      ('email_adapters', 'Provider-neutral email adapter and queued delivery boundary.'),
      ('manual_whatsapp_templates', 'Manual WhatsApp templates without automatic message sending.'),
      ('retry_failure_log', 'Delivery attempt, retry and terminal failure audit trail.'),
      ('activity_log_ui', 'Hotel-scoped searchable activity timeline UI.'),
      ('support_tickets', 'Hotel and platform support ticket workflow.'),
      ('announcements', 'Platform and hotel announcement workflow.'),
      ('hotel_settings', 'Operational hotel and system settings.'),
      ('timezone_business_day', 'Timezone and business-day consistency.'),
      ('critical_event_exit_gate', 'Reservation, payment and service events create auditable notifications without cross-hotel leakage.')
    ) roadmap(scope_key, scope_detail)
  loop
    suite := 'ROADMAP_SCOPE';
    test_name := rec.scope_key;
    passed := true;
    details := rec.scope_detail;
    return next;
  end loop;

  -- B. Existing table inventory.
  for rec in
    select *
    from (
      values
      ('notifications', 'Legacy staff-facing notification inbox'),
      ('guest_notifications', 'Day 15 guest-visible status history'),
      ('activity_logs', 'Day 3 tenant activity ledger'),
      ('support_tickets', 'Day 9 support ticket header'),
      ('support_ticket_messages', 'Day 9 support conversation'),
      ('announcements', 'Day 9 platform/hotel announcements'),
      ('hotel_settings', 'Day 8 hotel settings'),
      ('hotels', 'Tenant and timezone authority'),
      ('hotel_info', 'Guest-facing hotel profile'),
      ('staff', 'Hotel staff identity'),
      ('role_permissions', 'Role permission matrix'),
      ('platform_admins', 'Platform administration'),
      ('reservations', 'Critical reservation source'),
      ('reservation_events', 'Reservation lifecycle event source'),
      ('activity_logs', 'Reservation activity source'),
      ('payments', 'Critical payment source'),
      ('payment_collections', 'Cashier collection source'),
      ('payment_events', 'Payment event source when available'),
      ('payment_webhook_events', 'Provider webhook source when available'),
      ('service_requests', 'Critical guest-service source'),
      ('service_request_events', 'Service workflow event source'),
      ('guest_sessions', 'Guest stay scope'),
      ('hotel_subscriptions', 'Commercial lifecycle source'),
      ('subscription_events', 'Commercial event source')
    ) expected(table_name, purpose)
  loop
    select to_regclass('public.' || rec.table_name) is not null
    into v_exists;

    suite := 'LOCKED_TABLE_BASELINE';
    test_name := rec.table_name;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT — ' || rec.purpose
      else 'MISSING LOCKED BASELINE — ' || rec.purpose
    end;
    return next;
  end loop;

  -- C. Existing column inventory.
  for rec in
    select *
    from (
      values
      ('notifications', 'id'),
      ('notifications', 'hotel_id'),
      ('notifications', 'room_id'),
      ('notifications', 'guest_id'),
      ('notifications', 'type'),
      ('notifications', 'title'),
      ('notifications', 'message'),
      ('notifications', 'is_read'),
      ('notifications', 'created_at'),
      ('guest_notifications', 'id'),
      ('guest_notifications', 'hotel_id'),
      ('guest_notifications', 'guest_session_id'),
      ('guest_notifications', 'source_type'),
      ('guest_notifications', 'source_id'),
      ('guest_notifications', 'event_key'),
      ('guest_notifications', 'title'),
      ('guest_notifications', 'message'),
      ('guest_notifications', 'status'),
      ('guest_notifications', 'metadata'),
      ('guest_notifications', 'created_at'),
      ('activity_logs', 'id'),
      ('activity_logs', 'hotel_id'),
      ('activity_logs', 'actor_user_id'),
      ('activity_logs', 'actor_role'),
      ('activity_logs', 'action'),
      ('activity_logs', 'entity_type'),
      ('activity_logs', 'entity_id'),
      ('activity_logs', 'description'),
      ('activity_logs', 'before_data'),
      ('activity_logs', 'after_data'),
      ('activity_logs', 'metadata'),
      ('activity_logs', 'created_at'),
      ('support_tickets', 'id'),
      ('support_tickets', 'hotel_id'),
      ('support_tickets', 'ticket_number'),
      ('support_tickets', 'subject'),
      ('support_tickets', 'description'),
      ('support_tickets', 'category'),
      ('support_tickets', 'priority'),
      ('support_tickets', 'status'),
      ('support_tickets', 'created_by_user_id'),
      ('support_tickets', 'assigned_to_user_id'),
      ('support_tickets', 'created_at'),
      ('support_tickets', 'updated_at'),
      ('support_tickets', 'metadata'),
      ('support_ticket_messages', 'id'),
      ('support_ticket_messages', 'ticket_id'),
      ('support_ticket_messages', 'author_user_id'),
      ('support_ticket_messages', 'message'),
      ('support_ticket_messages', 'created_at'),
      ('announcements', 'id'),
      ('announcements', 'scope'),
      ('announcements', 'hotel_id'),
      ('announcements', 'title'),
      ('announcements', 'body'),
      ('announcements', 'severity'),
      ('announcements', 'status'),
      ('announcements', 'starts_at'),
      ('announcements', 'ends_at'),
      ('announcements', 'created_by_user_id'),
      ('announcements', 'metadata'),
      ('announcements', 'created_at'),
      ('announcements', 'updated_at'),
      ('hotel_settings', 'hotel_id'),
      ('hotel_settings', 'currency_code'),
      ('hotel_settings', 'tax_rate'),
      ('hotel_settings', 'service_charge_rate'),
      ('hotel_settings', 'invoice_prefix'),
      ('hotel_settings', 'reservation_prefix'),
      ('hotel_settings', 'trial_started_at'),
      ('hotel_settings', 'trial_ends_at'),
      ('hotel_settings', 'created_at'),
      ('hotel_settings', 'updated_at'),
      ('hotels', 'id'),
      ('hotels', 'hotel_name'),
      ('hotels', 'status'),
      ('hotels', 'timezone'),
      ('hotels', 'created_at'),
      ('hotels', 'updated_at'),
      ('reservations', 'id'),
      ('reservations', 'hotel_id'),
      ('reservations', 'reservation_number'),
      ('reservations', 'status'),
      ('reservations', 'arrival_date'),
      ('reservations', 'departure_date'),
      ('reservations', 'created_at'),
      ('reservations', 'updated_at'),
      ('payments', 'id'),
      ('payments', 'hotel_id'),
      ('payments', 'payment_status'),
      ('payments', 'amount'),
      ('payments', 'created_at'),
      ('service_requests', 'id'),
      ('service_requests', 'hotel_id'),
      ('service_requests', 'guest_session_id'),
      ('service_requests', 'status'),
      ('service_requests', 'request_type'),
      ('service_requests', 'department'),
      ('service_requests', 'created_at'),
      ('service_requests', 'updated_at')
    ) expected(table_name, column_name)
  loop
    select exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = rec.table_name
        and c.column_name = rec.column_name
    )
    into v_exists;

    suite := 'LOCKED_COLUMN_BASELINE';
    test_name := rec.table_name || '.' || rec.column_name;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT'
      else 'MISSING OR SCHEMA-DIFFERENT — confirm before Migration 056'
    end;
    return next;
  end loop;

  -- D. RLS, policy and authenticated-grant inventory.
  for rec in
    select table_name
    from (
      values
      ('notifications'),
      ('guest_notifications'),
      ('activity_logs'),
      ('support_tickets'),
      ('support_ticket_messages'),
      ('announcements'),
      ('hotel_settings'),
      ('reservations'),
      ('payments'),
      ('service_requests')
    ) expected(table_name)
  loop
    select coalesce(c.relrowsecurity, false)
    into v_exists
    from pg_class c
    join pg_namespace n
      on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = rec.table_name;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.rls_enabled';
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'RLS ENABLED'
      else 'RLS MISSING'
    end;
    return next;

    select count(*)
    into v_count
    from pg_policies p
    where p.schemaname = 'public'
      and p.tablename = rec.table_name;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.policy_count';
    passed := v_count > 0;
    details := format('%s policy/policies.', v_count);
    return next;

    select has_table_privilege(
      'authenticated',
      format('public.%I', rec.table_name),
      'SELECT'
    )
    into v_exists;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.authenticated_select';
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Authenticated SELECT granted; RLS remains authoritative.'
      else 'Authenticated SELECT not granted.'
    end;
    return next;
  end loop;

  -- E. Existing function/RPC inventory.
  for rec in
    select *
    from (
      values
      ('private.user_has_hotel_access(uuid)', 'Tenant membership guard'),
      ('private.user_has_hotel_role(uuid,text[])', 'Role guard'),
      ('private.is_platform_admin()', 'Platform-admin guard'),
      ('public.create_support_ticket(uuid,text,text,text,text)', 'Support ticket creation'),
      ('public.add_support_ticket_message(uuid,text)', 'Support conversation'),
      ('public.update_support_ticket_status(uuid,text,text,uuid)', 'Support status transition'),
      ('public.create_announcement(uuid,text,text,text,text,timestamptz,timestamptz,jsonb)', 'Announcement management'),
      ('public.get_platform_admin_console()', 'Platform support and announcement console'),
      ('public.create_guest_service_request(text,text,text)', 'Guest service request source'),
      ('public.place_guest_food_order(text,jsonb,text)', 'Guest food order source'),
      ('public.get_report_service_sla(uuid,date,date)', 'Service analytics source')
    ) expected(signature, purpose)
  loop
    select to_regprocedure(rec.signature) is not null
    into v_exists;

    suite := 'LOCKED_FUNCTION_BASELINE';
    test_name := rec.signature;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT — ' || rec.purpose
      else 'MISSING OR SIGNATURE-DIFFERENT — ' || rec.purpose
    end;
    return next;
  end loop;

  -- F. Planned Day 17 table collision checks.
  for rec in
    select *
    from (
      values
      ('notification_event_catalog', 'Canonical event definitions'),
      ('notification_preferences', 'Hotel/user channel preferences'),
      ('notification_templates', 'Localized notification templates'),
      ('notification_template_versions', 'Template publication history'),
      ('notification_outbox', 'Transactional delivery queue'),
      ('notification_deliveries', 'Recipient/channel delivery ledger'),
      ('notification_delivery_attempts', 'Retry/failure attempt log'),
      ('notification_dead_letters', 'Terminal delivery failures'),
      ('notification_recipients', 'Recipient-level inbox/read state'),
      ('email_adapter_configs', 'Hotel/platform email adapter configuration'),
      ('whatsapp_templates', 'Manual WhatsApp template library'),
      ('business_day_settings', 'Business-day cutoff and timezone policy')
    ) proposed(table_name, purpose)
  loop
    select to_regclass('public.' || rec.table_name) is null
    into v_exists;

    suite := 'DAY17_TABLE_COLLISION';
    test_name := rec.table_name;
    passed := v_exists;
    details := case
      when v_exists then 'PLANNED GAP / NAME AVAILABLE — ' || rec.purpose
      else 'OBJECT ALREADY EXISTS — inspect before Migration 056'
    end;
    return next;
  end loop;

  -- G. Planned Day 17 RPC collision checks.
  for rec in
    select *
    from (
      values
      ('public.get_notification_inbox(uuid,integer,timestamptz)', 'Trusted hotel-scoped inbox'),
      ('public.mark_notification_read(uuid)', 'Recipient-scoped read transition'),
      ('public.mark_all_notifications_read(uuid)', 'Hotel/user scoped bulk read'),
      ('public.upsert_notification_preferences(uuid,jsonb)', 'Preference mutation'),
      ('public.publish_notification_template(uuid,text,text,jsonb)', 'Template publication'),
      ('public.enqueue_notification_event(uuid,text,uuid,jsonb)', 'Canonical event/outbox creation'),
      ('public.process_notification_outbox(integer)', 'Delivery dispatcher'),
      ('public.retry_notification_delivery(uuid)', 'Controlled retry'),
      ('public.get_activity_timeline(uuid,timestamptz,timestamptz,jsonb)', 'Trusted activity UI feed'),
      ('public.get_hotel_system_settings(uuid)', 'Trusted settings read'),
      ('public.update_hotel_system_settings(uuid,jsonb)', 'Trusted settings update'),
      ('private.resolve_hotel_business_date(uuid,timestamptz)', 'Business-date authority')
    ) proposed(signature, purpose)
  loop
    select to_regprocedure(rec.signature) is null
    into v_exists;

    suite := 'DAY17_FUNCTION_COLLISION';
    test_name := rec.signature;
    passed := v_exists;
    details := case
      when v_exists then 'PLANNED GAP / SIGNATURE AVAILABLE — ' || rec.purpose
      else 'FUNCTION ALREADY EXISTS — inspect before Migration 056'
    end;
    return next;
  end loop;

  -- H. Realtime, security and data-quality boundary checks.
  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notifications_realtime_publication';
  select exists (
    select 1
    from pg_publication_tables pt
    where pt.pubname = 'supabase_realtime'
      and pt.schemaname = 'public'
      and pt.tablename = 'notifications'
  )
  into v_exists;
  passed := v_exists;
  details := case
    when v_exists then 'Legacy notifications is published to Supabase Realtime.'
    else 'GAP — Navbar subscription cannot receive postgres_changes until publication is installed.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'guest_notifications_realtime_publication';
  select exists (
    select 1
    from pg_publication_tables pt
    where pt.pubname = 'supabase_realtime'
      and pt.schemaname = 'public'
      and pt.tablename = 'guest_notifications'
  )
  into v_exists;
  passed := true;
  details := case
    when v_exists then 'PRESENT — guest notifications are realtime enabled.'
    else 'PLANNED GAP — decide whether guest status history requires realtime publication.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notifications_anon_insert_blocked';
  select not has_table_privilege(
    'anon',
    'public.notifications',
    'INSERT'
  )
  into v_exists;
  passed := coalesce(v_exists, false);
  details := case
    when coalesce(v_exists, false) then 'Anonymous direct insert is blocked.'
    else 'SECURITY GAP — anonymous direct insert is granted.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'activity_logs_anon_select_blocked';
  select not has_table_privilege(
    'anon',
    'public.activity_logs',
    'SELECT'
  )
  into v_exists;
  passed := coalesce(v_exists, false);
  details := case
    when coalesce(v_exists, false) then 'Anonymous activity-log reads are blocked.'
    else 'SECURITY GAP — anonymous activity-log read is granted.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'support_tickets_anon_access_blocked';
  select not (
    has_table_privilege('anon', 'public.support_tickets', 'SELECT')
    or has_table_privilege('anon', 'public.support_tickets', 'INSERT')
    or has_table_privilege('anon', 'public.support_tickets', 'UPDATE')
  )
  into v_exists;
  passed := coalesce(v_exists, false);
  details := case
    when coalesce(v_exists, false) then 'Anonymous support-ticket access is blocked.'
    else 'SECURITY GAP — anonymous support-ticket privilege exists.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notification_preference_foundation_absent';
  passed := to_regclass('public.notification_preferences') is null;
  details := case
    when passed then 'PLANNED GAP — preferences will be installed by Day 17.'
    else 'Existing preference table requires compatibility review.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notification_template_foundation_absent';
  passed := to_regclass('public.notification_templates') is null;
  details := case
    when passed then 'PLANNED GAP — templates will be installed by Day 17.'
    else 'Existing template table requires compatibility review.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'delivery_attempt_foundation_absent';
  passed := to_regclass('public.notification_delivery_attempts') is null;
  details := case
    when passed then 'PLANNED GAP — retry/failure ledger will be installed by Day 17.'
    else 'Existing attempt table requires compatibility review.'
  end;
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'hotels_timezone_nonblank';
  select count(*)
  into v_count
  from public.hotels h
  where h.timezone is null
     or length(trim(h.timezone)) = 0;
  passed := v_count = 0;
  details := format('%s hotel(s) have a missing timezone.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'hotel_settings_coverage';
  select count(*)
  into v_count
  from public.hotels h
  where h.status <> 'archived'
    and not exists (
      select 1
      from public.hotel_settings hs
      where hs.hotel_id = h.id
    );
  passed := v_count = 0;
  details := format('%s non-archived hotel(s) have no hotel_settings row.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'notifications_hotel_scope';
  select count(*)
  into v_count
  from public.notifications n
  where n.hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = n.hotel_id
     );
  passed := v_count = 0;
  details := format('%s notification row(s) violate hotel scope.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'guest_notifications_session_scope';
  select count(*)
  into v_count
  from public.guest_notifications gn
  left join public.guest_sessions gs
    on gs.id = gn.guest_session_id
   and gs.hotel_id = gn.hotel_id
  where gs.id is null;
  passed := v_count = 0;
  details := format('%s guest notification row(s) have no matching hotel/session.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'activity_logs_hotel_scope';
  select count(*)
  into v_count
  from public.activity_logs al
  where al.hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = al.hotel_id
     );
  passed := v_count = 0;
  details := format('%s activity row(s) violate hotel scope.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'support_ticket_hotel_scope';
  select count(*)
  into v_count
  from public.support_tickets st
  where st.hotel_id is not null
    and not exists (
      select 1
      from public.hotels h
      where h.id = st.hotel_id
    );
  passed := v_count = 0;
  details := format('%s support ticket(s) reference a missing hotel.', v_count);
  return next;

  suite := 'DAY17_GAP_SUMMARY';
  test_name := 'critical_event_notification_triggers';
  select count(*)
  into v_count
  from pg_trigger t
  join pg_class c
    on c.oid = t.tgrelid
  join pg_namespace n
    on n.oid = c.relnamespace
  where not t.tgisinternal
    and n.nspname = 'public'
    and c.relname in ('reservations', 'payments', 'service_requests')
    and (
      pg_get_triggerdef(t.oid) ilike '%notification%'
      or pg_get_triggerdef(t.oid) ilike '%outbox%'
    );
  passed := true;
  details := case
    when v_count > 0 then format('PRESENT — %s notification/outbox trigger(s) detected.', v_count)
    else 'PLANNED GAP — no critical reservation/payment/service notification trigger detected.'
  end;
  return next;

  suite := 'DAY17_GAP_SUMMARY';
  test_name := 'business_day_authority';
  select count(*)
  into v_count
  from pg_proc p
  join pg_namespace n
    on n.oid = p.pronamespace
  where n.nspname in ('public', 'private')
    and (
      p.proname ilike '%business%day%'
      or pg_get_functiondef(p.oid) ilike '%business day%'
    );
  passed := true;
  details := case
    when v_count > 0 then format('PRESENT — %s business-day related function(s) detected.', v_count)
    else 'PLANNED GAP — no canonical hotel business-date resolver detected.'
  end;
  return next;
end;
$$;


ALTER FUNCTION "private"."day17_audit_069_preflight_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_audit_069_preflight_rev2"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rec record;
  v_exists boolean;
  v_count bigint;
  v_count_2 bigint;
  v_text text;
  v_table_regclass regclass;
begin
  -- A. Locked roadmap contract.
  for rec in
    select *
    from (
      values
      ('in_app_realtime', 'In-app realtime notification inbox and live updates.'),
      ('notification_preferences', 'Hotel/user notification channel and event preferences.'),
      ('notification_templates', 'Reusable event templates with safe variables.'),
      ('email_adapters', 'Provider-neutral email adapter and queued delivery boundary.'),
      ('manual_whatsapp_templates', 'Manual WhatsApp templates without automatic message sending.'),
      ('retry_failure_log', 'Delivery attempt, retry and terminal failure audit trail.'),
      ('activity_log_ui', 'Hotel-scoped searchable activity timeline UI.'),
      ('support_tickets', 'Hotel and platform support ticket workflow.'),
      ('announcements', 'Platform and hotel announcement workflow.'),
      ('hotel_settings', 'Operational hotel and system settings.'),
      ('timezone_business_day', 'Timezone and business-day consistency.'),
      ('critical_event_exit_gate', 'Reservation, payment and service events create auditable notifications without cross-hotel leakage.')
    ) roadmap(scope_key, scope_detail)
  loop
    suite := 'ROADMAP_SCOPE';
    test_name := rec.scope_key;
    passed := true;
    details := rec.scope_detail;
    return next;
  end loop;

  -- B. Existing table inventory.
  for rec in
    select *
    from (
      values
      ('notifications', 'Legacy staff-facing notification inbox'),
      ('guest_notifications', 'Day 15 guest-visible status history'),
      ('activity_logs', 'Day 3 tenant activity ledger'),
      ('support_tickets', 'Day 9 support ticket header'),
      ('support_ticket_messages', 'Day 9 support conversation'),
      ('announcements', 'Day 9 platform/hotel announcements'),
      ('hotel_settings', 'Day 8 hotel settings'),
      ('hotels', 'Tenant and timezone authority'),
      ('hotel_info', 'Guest-facing hotel profile'),
      ('staff', 'Hotel staff identity'),
      ('role_permissions', 'Role permission matrix'),
      ('platform_admins', 'Platform administration'),
      ('reservations', 'Critical reservation source'),
      ('reservation_events', 'Reservation lifecycle event source'),
      ('activity_logs', 'Reservation activity source'),
      ('payments', 'Critical payment source'),
      ('payment_collections', 'Cashier collection source'),
      ('payment_events', 'Payment event source when available'),
      ('payment_webhook_events', 'Provider webhook source when available'),
      ('service_requests', 'Critical guest-service source'),
      ('service_request_events', 'Service workflow event source'),
      ('guest_sessions', 'Guest stay scope'),
      ('hotel_subscriptions', 'Commercial lifecycle source'),
      ('subscription_events', 'Commercial event source')
    ) expected(table_name, purpose)
  loop
    select to_regclass('public.' || rec.table_name) is not null
    into v_exists;

    suite := 'LOCKED_TABLE_BASELINE';
    test_name := rec.table_name;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT — ' || rec.purpose
      else 'MISSING LOCKED BASELINE — ' || rec.purpose
    end;
    return next;
  end loop;

  -- C. Existing column inventory.
  for rec in
    select *
    from (
      values
      ('notifications', 'id'),
      ('notifications', 'hotel_id'),
      ('notifications', 'room_id'),
      ('notifications', 'guest_id'),
      ('notifications', 'type'),
      ('notifications', 'title'),
      ('notifications', 'message'),
      ('notifications', 'is_read'),
      ('notifications', 'created_at'),
      ('guest_notifications', 'id'),
      ('guest_notifications', 'hotel_id'),
      ('guest_notifications', 'guest_session_id'),
      ('guest_notifications', 'source_type'),
      ('guest_notifications', 'source_id'),
      ('guest_notifications', 'event_key'),
      ('guest_notifications', 'title'),
      ('guest_notifications', 'message'),
      ('guest_notifications', 'status'),
      ('guest_notifications', 'metadata'),
      ('guest_notifications', 'created_at'),
      ('activity_logs', 'id'),
      ('activity_logs', 'hotel_id'),
      ('activity_logs', 'actor_user_id'),
      ('activity_logs', 'actor_role'),
      ('activity_logs', 'action'),
      ('activity_logs', 'entity_type'),
      ('activity_logs', 'entity_id'),
      ('activity_logs', 'description'),
      ('activity_logs', 'before_data'),
      ('activity_logs', 'after_data'),
      ('activity_logs', 'metadata'),
      ('activity_logs', 'created_at'),
      ('support_tickets', 'id'),
      ('support_tickets', 'hotel_id'),
      ('support_tickets', 'ticket_number'),
      ('support_tickets', 'subject'),
      ('support_tickets', 'description'),
      ('support_tickets', 'category'),
      ('support_tickets', 'priority'),
      ('support_tickets', 'status'),
      ('support_tickets', 'created_by_user_id'),
      ('support_tickets', 'assigned_to_user_id'),
      ('support_tickets', 'created_at'),
      ('support_tickets', 'updated_at'),
      ('support_tickets', 'metadata'),
      ('support_ticket_messages', 'id'),
      ('support_ticket_messages', 'ticket_id'),
      ('support_ticket_messages', 'author_user_id'),
      ('support_ticket_messages', 'message'),
      ('support_ticket_messages', 'created_at'),
      ('announcements', 'id'),
      ('announcements', 'scope'),
      ('announcements', 'hotel_id'),
      ('announcements', 'title'),
      ('announcements', 'body'),
      ('announcements', 'severity'),
      ('announcements', 'status'),
      ('announcements', 'starts_at'),
      ('announcements', 'ends_at'),
      ('announcements', 'created_by_user_id'),
      ('announcements', 'metadata'),
      ('announcements', 'created_at'),
      ('announcements', 'updated_at'),
      ('hotel_settings', 'hotel_id'),
      ('hotel_settings', 'currency_code'),
      ('hotel_settings', 'tax_rate'),
      ('hotel_settings', 'service_charge_rate'),
      ('hotel_settings', 'invoice_prefix'),
      ('hotel_settings', 'reservation_prefix'),
      ('hotel_settings', 'trial_started_at'),
      ('hotel_settings', 'trial_ends_at'),
      ('hotel_settings', 'created_at'),
      ('hotel_settings', 'updated_at'),
      ('hotels', 'id'),
      ('hotels', 'hotel_name'),
      ('hotels', 'status'),
      ('hotels', 'timezone'),
      ('hotels', 'created_at'),
      ('hotels', 'updated_at'),
      ('reservations', 'id'),
      ('reservations', 'hotel_id'),
      ('reservations', 'reservation_number'),
      ('reservations', 'status'),
      ('reservations', 'arrival_date'),
      ('reservations', 'departure_date'),
      ('reservations', 'created_at'),
      ('reservations', 'updated_at'),
      ('payments', 'id'),
      ('payments', 'hotel_id'),
      ('payments', 'payment_status'),
      ('payments', 'amount'),
      ('payments', 'created_at'),
      ('service_requests', 'id'),
      ('service_requests', 'hotel_id'),
      ('service_requests', 'guest_session_id'),
      ('service_requests', 'status'),
      ('service_requests', 'request_type'),
      ('service_requests', 'department'),
      ('service_requests', 'created_at'),
      ('service_requests', 'updated_at')
    ) expected(table_name, column_name)
  loop
    select exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = rec.table_name
        and c.column_name = rec.column_name
    )
    into v_exists;

    suite := 'LOCKED_COLUMN_BASELINE';
    test_name := rec.table_name || '.' || rec.column_name;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT'
      else 'MISSING OR SCHEMA-DIFFERENT — confirm before Migration 056'
    end;
    return next;
  end loop;

  -- D. RLS, policy and authenticated-grant inventory.
  for rec in
    select table_name
    from (
      values
      ('notifications'),
      ('guest_notifications'),
      ('activity_logs'),
      ('support_tickets'),
      ('support_ticket_messages'),
      ('announcements'),
      ('hotel_settings'),
      ('reservations'),
      ('payments'),
      ('service_requests')
    ) expected(table_name)
  loop
    select to_regclass(format('public.%I', rec.table_name))
    into v_table_regclass;

    if v_table_regclass is null then
      suite := 'RLS_BASELINE';
      test_name := rec.table_name || '.rls_enabled';
      passed := false;
      details := 'TABLE MISSING — RLS cannot be evaluated.';
      return next;

      suite := 'RLS_BASELINE';
      test_name := rec.table_name || '.policy_count';
      passed := false;
      details := 'TABLE MISSING — policies cannot be evaluated.';
      return next;

      suite := 'RLS_BASELINE';
      test_name := rec.table_name || '.authenticated_select';
      passed := false;
      details := 'TABLE MISSING — authenticated privilege cannot be evaluated.';
      return next;

      continue;
    end if;

    select coalesce(c.relrowsecurity, false)
    into v_exists
    from pg_class c
    where c.oid = v_table_regclass;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.rls_enabled';
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'RLS ENABLED'
      else 'RLS MISSING'
    end;
    return next;

    select count(*)
    into v_count
    from pg_policies p
    where p.schemaname = 'public'
      and p.tablename = rec.table_name;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.policy_count';
    passed := v_count > 0;
    details := format('%s policy/policies.', v_count);
    return next;

    select has_table_privilege(
      'authenticated',
      v_table_regclass,
      'SELECT'
    )
    into v_exists;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.authenticated_select';
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Authenticated SELECT granted; RLS remains authoritative.'
      else 'Authenticated SELECT not granted.'
    end;
    return next;
  end loop;

  -- E. Existing function/RPC inventory.
  for rec in
    select *
    from (
      values
      ('private.user_has_hotel_access(uuid)', 'Tenant membership guard'),
      ('private.user_has_hotel_role(uuid,text[])', 'Role guard'),
      ('private.is_platform_admin()', 'Platform-admin guard'),
      ('public.create_support_ticket(uuid,text,text,text,text)', 'Support ticket creation'),
      ('public.add_support_ticket_message(uuid,text)', 'Support conversation'),
      ('public.update_support_ticket_status(uuid,text,text,uuid)', 'Support status transition'),
      ('public.create_announcement(uuid,text,text,text,text,timestamptz,timestamptz,jsonb)', 'Announcement management'),
      ('public.get_platform_admin_console()', 'Platform support and announcement console'),
      ('public.create_guest_service_request(text,text,text)', 'Guest service request source'),
      ('public.place_guest_food_order(text,jsonb,text)', 'Guest food order source'),
      ('public.get_report_service_sla(uuid,date,date)', 'Service analytics source')
    ) expected(signature, purpose)
  loop
    select to_regprocedure(rec.signature) is not null
    into v_exists;

    suite := 'LOCKED_FUNCTION_BASELINE';
    test_name := rec.signature;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT — ' || rec.purpose
      else 'MISSING OR SIGNATURE-DIFFERENT — ' || rec.purpose
    end;
    return next;
  end loop;

  -- F. Planned Day 17 table collision checks.
  for rec in
    select *
    from (
      values
      ('notification_event_catalog', 'Canonical event definitions'),
      ('notification_preferences', 'Hotel/user channel preferences'),
      ('notification_templates', 'Localized notification templates'),
      ('notification_template_versions', 'Template publication history'),
      ('notification_outbox', 'Transactional delivery queue'),
      ('notification_deliveries', 'Recipient/channel delivery ledger'),
      ('notification_delivery_attempts', 'Retry/failure attempt log'),
      ('notification_dead_letters', 'Terminal delivery failures'),
      ('notification_recipients', 'Recipient-level inbox/read state'),
      ('email_adapter_configs', 'Hotel/platform email adapter configuration'),
      ('whatsapp_templates', 'Manual WhatsApp template library'),
      ('business_day_settings', 'Business-day cutoff and timezone policy')
    ) proposed(table_name, purpose)
  loop
    select to_regclass('public.' || rec.table_name) is null
    into v_exists;

    suite := 'DAY17_TABLE_COLLISION';
    test_name := rec.table_name;
    passed := v_exists;
    details := case
      when v_exists then 'PLANNED GAP / NAME AVAILABLE — ' || rec.purpose
      else 'OBJECT ALREADY EXISTS — inspect before Migration 056'
    end;
    return next;
  end loop;

  -- G. Planned Day 17 RPC collision checks.
  for rec in
    select *
    from (
      values
      ('public.get_notification_inbox(uuid,integer,timestamptz)', 'Trusted hotel-scoped inbox'),
      ('public.mark_notification_read(uuid)', 'Recipient-scoped read transition'),
      ('public.mark_all_notifications_read(uuid)', 'Hotel/user scoped bulk read'),
      ('public.upsert_notification_preferences(uuid,jsonb)', 'Preference mutation'),
      ('public.publish_notification_template(uuid,text,text,jsonb)', 'Template publication'),
      ('public.enqueue_notification_event(uuid,text,uuid,jsonb)', 'Canonical event/outbox creation'),
      ('public.process_notification_outbox(integer)', 'Delivery dispatcher'),
      ('public.retry_notification_delivery(uuid)', 'Controlled retry'),
      ('public.get_activity_timeline(uuid,timestamptz,timestamptz,jsonb)', 'Trusted activity UI feed'),
      ('public.get_hotel_system_settings(uuid)', 'Trusted settings read'),
      ('public.update_hotel_system_settings(uuid,jsonb)', 'Trusted settings update'),
      ('private.resolve_hotel_business_date(uuid,timestamptz)', 'Business-date authority')
    ) proposed(signature, purpose)
  loop
    select to_regprocedure(rec.signature) is null
    into v_exists;

    suite := 'DAY17_FUNCTION_COLLISION';
    test_name := rec.signature;
    passed := v_exists;
    details := case
      when v_exists then 'PLANNED GAP / SIGNATURE AVAILABLE — ' || rec.purpose
      else 'FUNCTION ALREADY EXISTS — inspect before Migration 056'
    end;
    return next;
  end loop;

  -- H. Realtime, security and data-quality boundary checks.
  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notifications_realtime_publication';
  select exists (
    select 1
    from pg_publication_tables pt
    where pt.pubname = 'supabase_realtime'
      and pt.schemaname = 'public'
      and pt.tablename = 'notifications'
  )
  into v_exists;
  passed := v_exists;
  details := case
    when v_exists then 'Legacy notifications is published to Supabase Realtime.'
    else 'GAP — Navbar subscription cannot receive postgres_changes until publication is installed.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'guest_notifications_realtime_publication';
  select exists (
    select 1
    from pg_publication_tables pt
    where pt.pubname = 'supabase_realtime'
      and pt.schemaname = 'public'
      and pt.tablename = 'guest_notifications'
  )
  into v_exists;
  passed := true;
  details := case
    when v_exists then 'PRESENT — guest notifications are realtime enabled.'
    else 'PLANNED GAP — decide whether guest status history requires realtime publication.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notifications_anon_insert_blocked';
  select to_regclass('public.notifications')
  into v_table_regclass;
  if v_table_regclass is null then
    passed := false;
    details := 'TABLE MISSING — anonymous insert boundary cannot be evaluated.';
  else
    select not has_table_privilege(
      'anon',
      v_table_regclass,
      'INSERT'
    )
    into v_exists;
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Anonymous direct insert is blocked.'
      else 'SECURITY GAP — anonymous direct insert is granted.'
    end;
  end if;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'activity_logs_anon_select_blocked';
  select to_regclass('public.activity_logs')
  into v_table_regclass;
  if v_table_regclass is null then
    passed := false;
    details := 'TABLE MISSING — anonymous activity-log boundary cannot be evaluated.';
  else
    select not has_table_privilege(
      'anon',
      v_table_regclass,
      'SELECT'
    )
    into v_exists;
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Anonymous activity-log reads are blocked.'
      else 'SECURITY GAP — anonymous activity-log read is granted.'
    end;
  end if;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'support_tickets_anon_access_blocked';
  select to_regclass('public.support_tickets')
  into v_table_regclass;
  if v_table_regclass is null then
    passed := false;
    details := 'TABLE MISSING — anonymous support-ticket boundary cannot be evaluated.';
  else
    select not (
      has_table_privilege('anon', v_table_regclass, 'SELECT')
      or has_table_privilege('anon', v_table_regclass, 'INSERT')
      or has_table_privilege('anon', v_table_regclass, 'UPDATE')
    )
    into v_exists;
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Anonymous support-ticket access is blocked.'
      else 'SECURITY GAP — anonymous support-ticket privilege exists.'
    end;
  end if;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notification_preference_foundation_absent';
  passed := to_regclass('public.notification_preferences') is null;
  details := case
    when passed then 'PLANNED GAP — preferences will be installed by Day 17.'
    else 'Existing preference table requires compatibility review.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notification_template_foundation_absent';
  passed := to_regclass('public.notification_templates') is null;
  details := case
    when passed then 'PLANNED GAP — templates will be installed by Day 17.'
    else 'Existing template table requires compatibility review.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'delivery_attempt_foundation_absent';
  passed := to_regclass('public.notification_delivery_attempts') is null;
  details := case
    when passed then 'PLANNED GAP — retry/failure ledger will be installed by Day 17.'
    else 'Existing attempt table requires compatibility review.'
  end;
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'hotels_timezone_nonblank';
  select count(*)
  into v_count
  from public.hotels h
  where h.timezone is null
     or length(trim(h.timezone)) = 0;
  passed := v_count = 0;
  details := format('%s hotel(s) have a missing timezone.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'hotel_settings_coverage';
  select count(*)
  into v_count
  from public.hotels h
  where h.status <> 'archived'
    and not exists (
      select 1
      from public.hotel_settings hs
      where hs.hotel_id = h.id
    );
  passed := v_count = 0;
  details := format('%s non-archived hotel(s) have no hotel_settings row.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'notifications_hotel_scope';
  select count(*)
  into v_count
  from public.notifications n
  where n.hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = n.hotel_id
     );
  passed := v_count = 0;
  details := format('%s notification row(s) violate hotel scope.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'guest_notifications_session_scope';
  select count(*)
  into v_count
  from public.guest_notifications gn
  left join public.guest_sessions gs
    on gs.id = gn.guest_session_id
   and gs.hotel_id = gn.hotel_id
  where gs.id is null;
  passed := v_count = 0;
  details := format('%s guest notification row(s) have no matching hotel/session.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'activity_logs_hotel_scope';
  select count(*)
  into v_count
  from public.activity_logs al
  where al.hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = al.hotel_id
     );
  passed := v_count = 0;
  details := format('%s activity row(s) violate hotel scope.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'support_ticket_hotel_scope';
  select count(*)
  into v_count
  from public.support_tickets st
  where st.hotel_id is not null
    and not exists (
      select 1
      from public.hotels h
      where h.id = st.hotel_id
    );
  passed := v_count = 0;
  details := format('%s support ticket(s) reference a missing hotel.', v_count);
  return next;

  suite := 'DAY17_GAP_SUMMARY';
  test_name := 'critical_event_notification_triggers';
  select count(*)
  into v_count
  from pg_trigger t
  join pg_class c
    on c.oid = t.tgrelid
  join pg_namespace n
    on n.oid = c.relnamespace
  where not t.tgisinternal
    and n.nspname = 'public'
    and c.relname in ('reservations', 'payments', 'service_requests')
    and (
      pg_get_triggerdef(t.oid) ilike '%notification%'
      or pg_get_triggerdef(t.oid) ilike '%outbox%'
    );
  passed := true;
  details := case
    when v_count > 0 then format('PRESENT — %s notification/outbox trigger(s) detected.', v_count)
    else 'PLANNED GAP — no critical reservation/payment/service notification trigger detected.'
  end;
  return next;

  suite := 'DAY17_GAP_SUMMARY';
  test_name := 'business_day_authority';
  select count(*)
  into v_count
  from pg_proc p
  join pg_namespace n
    on n.oid = p.pronamespace
  where n.nspname in ('public', 'private')
    and (
      p.proname ilike '%business%day%'
      or pg_get_functiondef(p.oid) ilike '%business day%'
    );
  passed := true;
  details := case
    when v_count > 0 then format('PRESENT — %s business-day related function(s) detected.', v_count)
    else 'PLANNED GAP — no canonical hotel business-date resolver detected.'
  end;
  return next;
end;
$$;


ALTER FUNCTION "private"."day17_audit_069_preflight_rev2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_audit_069_preflight_rev3"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rec record;
  v_exists boolean;
  v_count bigint;
  v_count_2 bigint;
  v_text text;
  v_table_regclass regclass;
begin
  -- A. Locked roadmap contract.
  for rec in
    select *
    from (
      values
      ('in_app_realtime', 'In-app realtime notification inbox and live updates.'),
      ('notification_preferences', 'Hotel/user notification channel and event preferences.'),
      ('notification_templates', 'Reusable event templates with safe variables.'),
      ('email_adapters', 'Provider-neutral email adapter and queued delivery boundary.'),
      ('manual_whatsapp_templates', 'Manual WhatsApp templates without automatic message sending.'),
      ('retry_failure_log', 'Delivery attempt, retry and terminal failure audit trail.'),
      ('activity_log_ui', 'Hotel-scoped searchable activity timeline UI.'),
      ('support_tickets', 'Hotel and platform support ticket workflow.'),
      ('announcements', 'Platform and hotel announcement workflow.'),
      ('hotel_settings', 'Operational hotel and system settings.'),
      ('timezone_business_day', 'Timezone and business-day consistency.'),
      ('critical_event_exit_gate', 'Reservation, payment and service events create auditable notifications without cross-hotel leakage.')
    ) roadmap(scope_key, scope_detail)
  loop
    suite := 'ROADMAP_SCOPE';
    test_name := rec.scope_key;
    passed := true;
    details := rec.scope_detail;
    return next;
  end loop;

  -- B. Existing table inventory.
  for rec in
    select *
    from (
      values
      ('notifications', 'Legacy staff-facing notification inbox'),
      ('guest_notifications', 'Day 15 guest-visible status history'),
      ('activity_logs', 'Day 3 tenant activity ledger'),
      ('support_tickets', 'Day 9 support ticket header'),
      ('support_ticket_messages', 'Day 9 support conversation'),
      ('announcements', 'Day 9 platform/hotel announcements'),
      ('hotel_settings', 'Day 8 hotel settings'),
      ('hotels', 'Tenant and timezone authority'),
      ('hotel_info', 'Guest-facing hotel profile'),
      ('staff', 'Hotel staff identity'),
      ('role_permissions', 'Role permission matrix'),
      ('platform_admins', 'Platform administration'),
      ('reservations', 'Critical reservation source'),
      ('reservation_events', 'Reservation lifecycle event source'),
      ('activity_logs', 'Reservation activity source'),
      ('payments', 'Critical payment source'),
      ('payment_collections', 'Cashier collection source'),
      ('payment_events', 'Payment event source when available'),
      ('payment_webhook_events', 'Provider webhook source when available'),
      ('service_requests', 'Critical guest-service source'),
      ('service_request_events', 'Service workflow event source'),
      ('guest_sessions', 'Guest stay scope'),
      ('hotel_subscriptions', 'Commercial lifecycle source'),
      ('subscription_events', 'Commercial event source')
    ) expected(table_name, purpose)
  loop
    select to_regclass('public.' || rec.table_name) is not null
    into v_exists;

    suite := 'LOCKED_TABLE_BASELINE';
    test_name := rec.table_name;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT — ' || rec.purpose
      else 'MISSING LOCKED BASELINE — ' || rec.purpose
    end;
    return next;
  end loop;

  -- C. Existing column inventory.
  for rec in
    select *
    from (
      values
      ('notifications', 'id'),
      ('notifications', 'hotel_id'),
      ('notifications', 'room_id'),
      ('notifications', 'guest_id'),
      ('notifications', 'type'),
      ('notifications', 'title'),
      ('notifications', 'message'),
      ('notifications', 'is_read'),
      ('notifications', 'created_at'),
      ('guest_notifications', 'id'),
      ('guest_notifications', 'hotel_id'),
      ('guest_notifications', 'guest_session_id'),
      ('guest_notifications', 'source_type'),
      ('guest_notifications', 'source_id'),
      ('guest_notifications', 'event_key'),
      ('guest_notifications', 'title'),
      ('guest_notifications', 'message'),
      ('guest_notifications', 'status'),
      ('guest_notifications', 'metadata'),
      ('guest_notifications', 'created_at'),
      ('activity_logs', 'id'),
      ('activity_logs', 'hotel_id'),
      ('activity_logs', 'actor_user_id'),
      ('activity_logs', 'actor_role'),
      ('activity_logs', 'action'),
      ('activity_logs', 'entity_type'),
      ('activity_logs', 'entity_id'),
      ('activity_logs', 'description'),
      ('activity_logs', 'before_data'),
      ('activity_logs', 'after_data'),
      ('activity_logs', 'metadata'),
      ('activity_logs', 'created_at'),
      ('support_tickets', 'id'),
      ('support_tickets', 'hotel_id'),
      ('support_tickets', 'ticket_number'),
      ('support_tickets', 'subject'),
      ('support_tickets', 'description'),
      ('support_tickets', 'category'),
      ('support_tickets', 'priority'),
      ('support_tickets', 'status'),
      ('support_tickets', 'created_by_user_id'),
      ('support_tickets', 'assigned_to_user_id'),
      ('support_tickets', 'created_at'),
      ('support_tickets', 'updated_at'),
      ('support_tickets', 'metadata'),
      ('support_ticket_messages', 'id'),
      ('support_ticket_messages', 'ticket_id'),
      ('support_ticket_messages', 'author_user_id'),
      ('support_ticket_messages', 'message'),
      ('support_ticket_messages', 'created_at'),
      ('announcements', 'id'),
      ('announcements', 'scope'),
      ('announcements', 'hotel_id'),
      ('announcements', 'title'),
      ('announcements', 'body'),
      ('announcements', 'severity'),
      ('announcements', 'status'),
      ('announcements', 'starts_at'),
      ('announcements', 'ends_at'),
      ('announcements', 'created_by_user_id'),
      ('announcements', 'metadata'),
      ('announcements', 'created_at'),
      ('announcements', 'updated_at'),
      ('hotel_settings', 'hotel_id'),
      ('hotel_settings', 'currency_code'),
      ('hotel_settings', 'tax_rate'),
      ('hotel_settings', 'service_charge_rate'),
      ('hotel_settings', 'invoice_prefix'),
      ('hotel_settings', 'reservation_prefix'),
      ('hotel_settings', 'trial_started_at'),
      ('hotel_settings', 'trial_ends_at'),
      ('hotel_settings', 'created_at'),
      ('hotel_settings', 'updated_at'),
      ('hotels', 'id'),
      ('hotels', 'hotel_name'),
      ('hotels', 'status'),
      ('hotels', 'timezone'),
      ('hotels', 'created_at'),
      ('hotels', 'updated_at'),
      ('reservations', 'id'),
      ('reservations', 'hotel_id'),
      ('reservations', 'reservation_number'),
      ('reservations', 'status'),
      ('reservations', 'arrival_date'),
      ('reservations', 'departure_date'),
      ('reservations', 'created_at'),
      ('reservations', 'updated_at'),
      ('payments', 'id'),
      ('payments', 'hotel_id'),
      ('payments', 'payment_status'),
      ('payments', 'amount'),
      ('payments', 'created_at'),
      ('service_requests', 'id'),
      ('service_requests', 'hotel_id'),
      ('service_requests', 'guest_session_id'),
      ('service_requests', 'status'),
      ('service_requests', 'request_type'),
      ('service_requests', 'department'),
      ('service_requests', 'created_at'),
      ('service_requests', 'updated_at')
    ) expected(table_name, column_name)
  loop
    select exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = rec.table_name
        and c.column_name = rec.column_name
    )
    into v_exists;

    suite := 'LOCKED_COLUMN_BASELINE';
    test_name := rec.table_name || '.' || rec.column_name;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT'
      else 'MISSING OR SCHEMA-DIFFERENT — confirm before Migration 056'
    end;
    return next;
  end loop;

  -- D. RLS, policy and authenticated-grant inventory.
  for rec in
    select table_name
    from (
      values
      ('notifications'),
      ('guest_notifications'),
      ('activity_logs'),
      ('support_tickets'),
      ('support_ticket_messages'),
      ('announcements'),
      ('hotel_settings'),
      ('reservations'),
      ('payments'),
      ('service_requests')
    ) expected(table_name)
  loop
    select to_regclass(format('public.%I', rec.table_name))
    into v_table_regclass;

    if v_table_regclass is null then
      suite := 'RLS_BASELINE';
      test_name := rec.table_name || '.rls_enabled';
      passed := false;
      details := 'TABLE MISSING — RLS cannot be evaluated.';
      return next;

      suite := 'RLS_BASELINE';
      test_name := rec.table_name || '.policy_count';
      passed := false;
      details := 'TABLE MISSING — policies cannot be evaluated.';
      return next;

      suite := 'RLS_BASELINE';
      test_name := rec.table_name || '.authenticated_select';
      passed := false;
      details := 'TABLE MISSING — authenticated privilege cannot be evaluated.';
      return next;

      continue;
    end if;

    select coalesce(c.relrowsecurity, false)
    into v_exists
    from pg_class c
    where c.oid = v_table_regclass;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.rls_enabled';
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'RLS ENABLED'
      else 'RLS MISSING'
    end;
    return next;

    select count(*)
    into v_count
    from pg_policies p
    where p.schemaname = 'public'
      and p.tablename = rec.table_name;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.policy_count';
    passed := v_count > 0;
    details := format('%s policy/policies.', v_count);
    return next;

    select has_table_privilege(
      'authenticated',
      v_table_regclass,
      'SELECT'
    )
    into v_exists;

    suite := 'RLS_BASELINE';
    test_name := rec.table_name || '.authenticated_select';
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Authenticated SELECT granted; RLS remains authoritative.'
      else 'Authenticated SELECT not granted.'
    end;
    return next;
  end loop;

  -- E. Existing function/RPC inventory.
  for rec in
    select *
    from (
      values
      ('private.user_has_hotel_access(uuid)', 'Tenant membership guard'),
      ('private.user_has_hotel_role(uuid,text[])', 'Role guard'),
      ('private.is_platform_admin()', 'Platform-admin guard'),
      ('public.create_support_ticket(uuid,text,text,text,text)', 'Support ticket creation'),
      ('public.add_support_ticket_message(uuid,text)', 'Support conversation'),
      ('public.update_support_ticket_status(uuid,text,text,uuid)', 'Support status transition'),
      ('public.create_announcement(uuid,text,text,text,text,timestamptz,timestamptz,jsonb)', 'Announcement management'),
      ('public.get_platform_admin_console()', 'Platform support and announcement console'),
      ('public.create_guest_service_request(text,text,text)', 'Guest service request source'),
      ('public.place_guest_food_order(text,jsonb,text)', 'Guest food order source'),
      ('public.get_report_service_sla(uuid,date,date)', 'Service analytics source')
    ) expected(signature, purpose)
  loop
    select to_regprocedure(rec.signature) is not null
    into v_exists;

    suite := 'LOCKED_FUNCTION_BASELINE';
    test_name := rec.signature;
    passed := v_exists;
    details := case
      when v_exists then 'PRESENT — ' || rec.purpose
      else 'MISSING OR SIGNATURE-DIFFERENT — ' || rec.purpose
    end;
    return next;
  end loop;

  -- F. Planned Day 17 table collision checks.
  for rec in
    select *
    from (
      values
      ('notification_event_catalog', 'Canonical event definitions'),
      ('notification_preferences', 'Hotel/user channel preferences'),
      ('notification_templates', 'Localized notification templates'),
      ('notification_template_versions', 'Template publication history'),
      ('notification_outbox', 'Transactional delivery queue'),
      ('notification_deliveries', 'Recipient/channel delivery ledger'),
      ('notification_delivery_attempts', 'Retry/failure attempt log'),
      ('notification_dead_letters', 'Terminal delivery failures'),
      ('notification_recipients', 'Recipient-level inbox/read state'),
      ('email_adapter_configs', 'Hotel/platform email adapter configuration'),
      ('whatsapp_templates', 'Manual WhatsApp template library'),
      ('business_day_settings', 'Business-day cutoff and timezone policy')
    ) proposed(table_name, purpose)
  loop
    select to_regclass('public.' || rec.table_name) is null
    into v_exists;

    suite := 'DAY17_TABLE_COLLISION';
    test_name := rec.table_name;
    passed := v_exists;
    details := case
      when v_exists then 'PLANNED GAP / NAME AVAILABLE — ' || rec.purpose
      else 'OBJECT ALREADY EXISTS — inspect before Migration 056'
    end;
    return next;
  end loop;

  -- G. Planned Day 17 RPC collision checks.
  for rec in
    select *
    from (
      values
      ('public.get_notification_inbox(uuid,integer,timestamptz)', 'Trusted hotel-scoped inbox'),
      ('public.mark_notification_read(uuid)', 'Recipient-scoped read transition'),
      ('public.mark_all_notifications_read(uuid)', 'Hotel/user scoped bulk read'),
      ('public.upsert_notification_preferences(uuid,jsonb)', 'Preference mutation'),
      ('public.publish_notification_template(uuid,text,text,jsonb)', 'Template publication'),
      ('public.enqueue_notification_event(uuid,text,uuid,jsonb)', 'Canonical event/outbox creation'),
      ('public.process_notification_outbox(integer)', 'Delivery dispatcher'),
      ('public.retry_notification_delivery(uuid)', 'Controlled retry'),
      ('public.get_activity_timeline(uuid,timestamptz,timestamptz,jsonb)', 'Trusted activity UI feed'),
      ('public.get_hotel_system_settings(uuid)', 'Trusted settings read'),
      ('public.update_hotel_system_settings(uuid,jsonb)', 'Trusted settings update'),
      ('private.resolve_hotel_business_date(uuid,timestamptz)', 'Business-date authority')
    ) proposed(signature, purpose)
  loop
    select to_regprocedure(rec.signature) is null
    into v_exists;

    suite := 'DAY17_FUNCTION_COLLISION';
    test_name := rec.signature;
    passed := v_exists;
    details := case
      when v_exists then 'PLANNED GAP / SIGNATURE AVAILABLE — ' || rec.purpose
      else 'FUNCTION ALREADY EXISTS — inspect before Migration 056'
    end;
    return next;
  end loop;

  -- H. Realtime, security and data-quality boundary checks.
  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notifications_realtime_publication';
  select exists (
    select 1
    from pg_publication_tables pt
    where pt.pubname = 'supabase_realtime'
      and pt.schemaname = 'public'
      and pt.tablename = 'notifications'
  )
  into v_exists;
  passed := v_exists;
  details := case
    when v_exists then 'Legacy notifications is published to Supabase Realtime.'
    else 'GAP — Navbar subscription cannot receive postgres_changes until publication is installed.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'guest_notifications_realtime_publication';
  select exists (
    select 1
    from pg_publication_tables pt
    where pt.pubname = 'supabase_realtime'
      and pt.schemaname = 'public'
      and pt.tablename = 'guest_notifications'
  )
  into v_exists;
  passed := true;
  details := case
    when v_exists then 'PRESENT — guest notifications are realtime enabled.'
    else 'PLANNED GAP — decide whether guest status history requires realtime publication.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notifications_anon_insert_blocked';
  select to_regclass('public.notifications')
  into v_table_regclass;
  if v_table_regclass is null then
    passed := false;
    details := 'TABLE MISSING — anonymous insert boundary cannot be evaluated.';
  else
    select not has_table_privilege(
      'anon',
      v_table_regclass,
      'INSERT'
    )
    into v_exists;
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Anonymous direct insert is blocked.'
      else 'SECURITY GAP — anonymous direct insert is granted.'
    end;
  end if;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'activity_logs_anon_select_blocked';
  select to_regclass('public.activity_logs')
  into v_table_regclass;
  if v_table_regclass is null then
    passed := false;
    details := 'TABLE MISSING — anonymous activity-log boundary cannot be evaluated.';
  else
    select not has_table_privilege(
      'anon',
      v_table_regclass,
      'SELECT'
    )
    into v_exists;
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Anonymous activity-log reads are blocked.'
      else 'SECURITY GAP — anonymous activity-log read is granted.'
    end;
  end if;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'support_tickets_anon_access_blocked';
  select to_regclass('public.support_tickets')
  into v_table_regclass;
  if v_table_regclass is null then
    passed := false;
    details := 'TABLE MISSING — anonymous support-ticket boundary cannot be evaluated.';
  else
    select not (
      has_table_privilege('anon', v_table_regclass, 'SELECT')
      or has_table_privilege('anon', v_table_regclass, 'INSERT')
      or has_table_privilege('anon', v_table_regclass, 'UPDATE')
    )
    into v_exists;
    passed := coalesce(v_exists, false);
    details := case
      when coalesce(v_exists, false) then 'Anonymous support-ticket access is blocked.'
      else 'SECURITY GAP — anonymous support-ticket privilege exists.'
    end;
  end if;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notification_preference_foundation_absent';
  passed := to_regclass('public.notification_preferences') is null;
  details := case
    when passed then 'PLANNED GAP — preferences will be installed by Day 17.'
    else 'Existing preference table requires compatibility review.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'notification_template_foundation_absent';
  passed := to_regclass('public.notification_templates') is null;
  details := case
    when passed then 'PLANNED GAP — templates will be installed by Day 17.'
    else 'Existing template table requires compatibility review.'
  end;
  return next;

  suite := 'REALTIME_AND_SECURITY';
  test_name := 'delivery_attempt_foundation_absent';
  passed := to_regclass('public.notification_delivery_attempts') is null;
  details := case
    when passed then 'PLANNED GAP — retry/failure ledger will be installed by Day 17.'
    else 'Existing attempt table requires compatibility review.'
  end;
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'hotels_timezone_nonblank';
  select count(*)
  into v_count
  from public.hotels h
  where h.timezone is null
     or length(trim(h.timezone)) = 0;
  passed := v_count = 0;
  details := format('%s hotel(s) have a missing timezone.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'hotel_settings_coverage';
  select count(*)
  into v_count
  from public.hotels h
  where h.status <> 'archived'
    and not exists (
      select 1
      from public.hotel_settings hs
      where hs.hotel_id = h.id
    );
  passed := v_count = 0;
  details := format('%s non-archived hotel(s) have no hotel_settings row.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'notifications_hotel_scope';
  select count(*)
  into v_count
  from public.notifications n
  where n.hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = n.hotel_id
     );
  passed := v_count = 0;
  details := format('%s notification row(s) violate hotel scope.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'guest_notifications_session_scope';
  select count(*)
  into v_count
  from public.guest_notifications gn
  left join public.guest_sessions gs
    on gs.id = gn.guest_session_id
   and gs.hotel_id = gn.hotel_id
  where gs.id is null;
  passed := v_count = 0;
  details := format('%s guest notification row(s) have no matching hotel/session.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'activity_logs_hotel_scope';
  select count(*)
  into v_count
  from public.activity_logs al
  where al.hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = al.hotel_id
     );
  passed := v_count = 0;
  details := format('%s activity row(s) violate hotel scope.', v_count);
  return next;

  suite := 'DATA_QUALITY';
  test_name := 'support_ticket_hotel_scope';
  select count(*)
  into v_count
  from public.support_tickets st
  where st.hotel_id is not null
    and not exists (
      select 1
      from public.hotels h
      where h.id = st.hotel_id
    );
  passed := v_count = 0;
  details := format('%s support ticket(s) reference a missing hotel.', v_count);
  return next;

  suite := 'DAY17_GAP_SUMMARY';
  test_name := 'critical_event_notification_triggers';
  select count(*)
  into v_count
  from pg_trigger t
  join pg_class c
    on c.oid = t.tgrelid
  join pg_namespace n
    on n.oid = c.relnamespace
  where not t.tgisinternal
    and n.nspname = 'public'
    and c.relname in ('reservations', 'payments', 'service_requests')
    and (
      pg_get_triggerdef(t.oid) ilike '%notification%'
      or pg_get_triggerdef(t.oid) ilike '%outbox%'
    );
  passed := true;
  details := case
    when v_count > 0 then format('PRESENT — %s notification/outbox trigger(s) detected.', v_count)
    else 'PLANNED GAP — no critical reservation/payment/service notification trigger detected.'
  end;
  return next;

  suite := 'DAY17_GAP_SUMMARY';
  test_name := 'business_day_authority';
  select count(*)
  into v_count
  from pg_proc p
  join pg_namespace n
    on n.oid = p.pronamespace
  where n.nspname in ('public', 'private')
    and (
      p.proname ilike '%business%day%'
      or case
        when p.prokind in ('f', 'p')
          then pg_get_functiondef(p.oid) ilike '%business day%'
        else false
      end
    );
  passed := true;
  details := case
    when v_count > 0 then format('PRESENT — %s business-day related function(s) detected.', v_count)
    else 'PLANNED GAP — no canonical hotel business-date resolver detected.'
  end;
  return next;
end;
$$;


ALTER FUNCTION "private"."day17_audit_069_preflight_rev3"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_can_manage_hotel"("p_hotel_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    private.is_platform_admin()
    or private.user_has_hotel_role(
      p_hotel_id,
      array['owner', 'manager', 'hotel_admin', 'admin']
    );
$$;


ALTER FUNCTION "private"."day17_can_manage_hotel"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_capture_announcement_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_hotel record;
begin
  if new.status <> 'published'
     or (
       tg_op = 'UPDATE'
       and old.status = 'published'
       and new.title is not distinct from old.title
       and new.body is not distinct from old.body
       and new.starts_at is not distinct from old.starts_at
       and new.ends_at is not distinct from old.ends_at
     )
  then
    return new;
  end if;

  for v_hotel in
    select h.id
    from public.hotels h
    where h.status = 'active'
      and (
        new.scope = 'global'
        or h.id = new.target_hotel_id
      )
  loop
    perform private.day17_enqueue_notification_event_internal(
      v_hotel.id,
      'announcement.published',
      new.id,
      jsonb_build_object(
        'idempotency_key',
          'announcement.published:' || new.id::text || ':' ||
          extract(epoch from coalesce(new.published_at, new.updated_at, now()))::text,
        'title', new.title,
        'body', new.body,
        'severity', new.severity,
        'occurred_at', coalesce(new.published_at, new.updated_at, now())
      ),
      (select auth.uid())
    );
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "private"."day17_capture_announcement_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_capture_critical_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_new jsonb := to_jsonb(new);
  v_old jsonb := case
    when tg_op = 'UPDATE' then to_jsonb(old)
    else '{}'::jsonb
  end;
  v_hotel_id uuid := (v_new ->> 'hotel_id')::uuid;
  v_source_id uuid := (v_new ->> 'id')::uuid;
  v_source_type text;
  v_event_key text;
  v_status text;
  v_old_status text;
  v_payload jsonb;
begin
  v_source_type := case tg_table_name
    when 'reservations' then 'reservation'
    when 'payments' then 'payment'
    when 'service_requests' then 'service_request'
    else tg_table_name
  end;

  v_status := coalesce(
    nullif(v_new ->> 'status', ''),
    nullif(v_new ->> 'payment_status', ''),
    'recorded'
  );

  v_old_status := coalesce(
    nullif(v_old ->> 'status', ''),
    nullif(v_old ->> 'payment_status', '')
  );

  if tg_op = 'INSERT' then
    v_event_key := v_source_type || '.created';
  elsif v_status is distinct from v_old_status then
    v_event_key := v_source_type || '.status_changed';
  else
    return new;
  end if;

  v_payload := jsonb_strip_nulls(
    jsonb_build_object(
      'idempotency_key',
        v_event_key || ':' || v_source_id::text || ':' || v_status,
      'source_type', v_source_type,
      'source_id', v_source_id,
      'status', v_status,
      'old_status', v_old_status,
      'reservation_number', v_new ->> 'reservation_number',
      'amount', v_new ->> 'amount',
      'request_type', v_new ->> 'request_type',
      'department', v_new ->> 'department',
      'guest_session_id', v_new ->> 'guest_session_id',
      'room_id', v_new ->> 'room_id',
      'guest_id', v_new ->> 'guest_id',
      'occurred_at', coalesce(
        v_new ->> 'updated_at',
        v_new ->> 'created_at',
        now()::text
      )
    )
  );

  perform private.day17_enqueue_notification_event_internal(
    v_hotel_id,
    v_event_key,
    v_source_id,
    v_payload,
    (select auth.uid())
  );

  return new;
end;
$$;


ALTER FUNCTION "private"."day17_capture_critical_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_capture_support_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event_key text;
  v_old_status text;
begin
  if tg_op = 'INSERT' then
    v_event_key := 'support.ticket_created';
    v_old_status := null;
  elsif new.status is distinct from old.status then
    v_event_key := 'support.status_changed';
    v_old_status := old.status;
  else
    return new;
  end if;

  perform private.day17_enqueue_notification_event_internal(
    new.hotel_id,
    v_event_key,
    new.id,
    jsonb_build_object(
      'idempotency_key',
        v_event_key || ':' || new.id::text || ':' || new.status,
      'ticket_number', new.ticket_number,
      'subject', new.subject,
      'status', new.status,
      'old_status', v_old_status,
      'occurred_at', coalesce(new.updated_at, new.created_at, now())
    ),
    (select auth.uid())
  );

  return new;
end;
$$;


ALTER FUNCTION "private"."day17_capture_support_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_enqueue_notification_event_internal"("p_hotel_id" "uuid", "p_event_key" "text", "p_source_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_catalog public.notification_event_catalog%rowtype;
  v_outbox public.notification_outbox%rowtype;
  v_existing public.notification_outbox%rowtype;
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_idempotency_key text;
  v_recipient record;
  v_title_template text;
  v_body_template text;
  v_title text;
  v_body text;
  v_locale text;
  v_recipient_count integer := 0;
  v_pending_count integer := 0;
begin
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception 'Notification payload must be a JSON object.';
  end if;

  select *
  into v_catalog
  from public.notification_event_catalog nec
  where nec.event_key = p_event_key
    and nec.is_active;

  if not found then
    raise exception 'Unsupported notification event key: %', p_event_key;
  end if;

  if not exists (
    select 1
    from public.hotels h
    where h.id = p_hotel_id
  ) then
    raise exception 'Notification hotel was not found.';
  end if;

  v_idempotency_key := coalesce(
    nullif(trim(v_payload ->> 'idempotency_key'), ''),
    p_event_key || ':' || p_source_id::text || ':' ||
      coalesce(
        nullif(trim(v_payload ->> 'status'), ''),
        nullif(trim(v_payload ->> 'event_version'), ''),
        'base'
      )
  );

  insert into public.notification_outbox (
    hotel_id,
    event_key,
    source_type,
    source_id,
    idempotency_key,
    payload,
    business_date,
    status,
    created_by,
    occurred_at,
    created_at,
    updated_at
  ) values (
    p_hotel_id,
    p_event_key,
    v_catalog.source_type,
    p_source_id,
    v_idempotency_key,
    v_payload - 'idempotency_key',
    private.resolve_hotel_business_date(
      p_hotel_id,
      coalesce(
        nullif(v_payload ->> 'occurred_at', '')::timestamptz,
        now()
      )
    ),
    'processing',
    p_actor_user_id,
    coalesce(
      nullif(v_payload ->> 'occurred_at', '')::timestamptz,
      now()
    ),
    now(),
    now()
  )
  on conflict (hotel_id, idempotency_key) do nothing
  returning * into v_outbox;

  if v_outbox.id is null then
    select *
    into v_existing
    from public.notification_outbox nox
    where nox.hotel_id = p_hotel_id
      and nox.idempotency_key = v_idempotency_key;

    return jsonb_build_object(
      'outbox_id', v_existing.id,
      'idempotent', true,
      'status', v_existing.status
    );
  end if;

  for v_recipient in
    select
      s.auth_user_id as user_id,
      nullif(trim(s.email), '') as email,
      nullif(trim(s.phone), '') as phone,
      coalesce(np.locale, 'en') as locale,
      coalesce(np.in_app_enabled, true) as in_app_enabled,
      coalesce(np.email_enabled, false) as email_enabled,
      coalesce(np.manual_whatsapp_enabled, false)
        as manual_whatsapp_enabled
    from public.staff s
    left join public.notification_preferences np
      on np.hotel_id = s.hotel_id
     and np.user_id = s.auth_user_id
    where s.hotel_id = p_hotel_id
      and s.status = 'active'
      and s.auth_user_id is not null
  loop
    v_locale := v_recipient.locale;

    select
      nt.title_template,
      nt.body_template
    into
      v_title_template,
      v_body_template
    from public.notification_templates nt
    where nt.event_key = p_event_key
      and nt.channel = 'in_app'
      and nt.status = 'published'
      and (nt.hotel_id = p_hotel_id or nt.hotel_id is null)
      and nt.locale in (v_locale, 'en')
    order by
      case when nt.hotel_id = p_hotel_id then 0 else 1 end,
      case when nt.locale = v_locale then 0 else 1 end,
      nt.updated_at desc
    limit 1;

    v_title := private.day17_render_notification_text(
      coalesce(v_title_template, v_catalog.default_title),
      v_payload
    );
    v_body := private.day17_render_notification_text(
      coalesce(v_body_template, v_catalog.default_body),
      v_payload
    );

    if v_catalog.default_channels ? 'in_app'
       and v_recipient.in_app_enabled
    then
      insert into public.notification_recipients (
        outbox_id,
        hotel_id,
        user_id,
        title,
        message,
        severity,
        status,
        metadata,
        created_at,
        updated_at
      ) values (
        v_outbox.id,
        p_hotel_id,
        v_recipient.user_id,
        v_title,
        v_body,
        v_catalog.severity,
        'unread',
        jsonb_build_object(
          'event_key', p_event_key,
          'source_type', v_catalog.source_type,
          'source_id', p_source_id,
          'business_date', v_outbox.business_date
        ),
        now(),
        now()
      )
      on conflict (outbox_id, user_id) do nothing;

      insert into public.notification_deliveries (
        outbox_id,
        hotel_id,
        recipient_user_id,
        channel,
        address_snapshot,
        locale,
        rendered_title,
        rendered_body,
        status,
        attempt_count,
        delivered_at,
        metadata,
        created_at,
        updated_at
      ) values (
        v_outbox.id,
        p_hotel_id,
        v_recipient.user_id,
        'in_app',
        v_recipient.user_id::text,
        v_locale,
        v_title,
        v_body,
        'delivered',
        1,
        now(),
        jsonb_build_object('delivery_mode', 'realtime_in_app'),
        now(),
        now()
      )
      on conflict do nothing;

      v_recipient_count := v_recipient_count + 1;
    end if;

    if v_catalog.default_channels ? 'email'
       and v_recipient.email_enabled
       and v_recipient.email is not null
    then
      insert into public.notification_deliveries (
        outbox_id,
        hotel_id,
        recipient_user_id,
        channel,
        address_snapshot,
        locale,
        rendered_title,
        rendered_body,
        status,
        metadata,
        created_at,
        updated_at
      ) values (
        v_outbox.id,
        p_hotel_id,
        v_recipient.user_id,
        'email',
        v_recipient.email,
        v_locale,
        v_title,
        v_body,
        'pending',
        jsonb_build_object('delivery_mode', 'provider_adapter'),
        now(),
        now()
      )
      on conflict do nothing;

      v_pending_count := v_pending_count + 1;
    end if;
  end loop;

  update public.notification_outbox nox
  set
    status = case
      when v_pending_count > 0 then 'pending'
      else 'completed'
    end,
    pending_delivery_count = v_pending_count,
    completed_delivery_count = v_recipient_count,
    failed_delivery_count = 0,
    updated_at = now()
  where nox.id = v_outbox.id
  returning * into v_outbox;

  insert into public.activity_logs (
    hotel_id,
    actor_user_id,
    actor_role,
    action,
    entity_type,
    entity_id,
    description,
    metadata,
    created_at
  ) values (
    p_hotel_id,
    p_actor_user_id,
    case
      when p_actor_user_id is null then 'system'
      else 'authenticated'
    end,
    'notification_event_enqueued',
    v_catalog.source_type,
    p_source_id,
    p_event_key,
    jsonb_build_object(
      'outbox_id', v_outbox.id,
      'recipient_count', v_recipient_count,
      'pending_delivery_count', v_pending_count,
      'business_date', v_outbox.business_date
    ),
    now()
  );

  return jsonb_build_object(
    'outbox_id', v_outbox.id,
    'idempotent', false,
    'status', v_outbox.status,
    'recipient_count', v_recipient_count,
    'pending_delivery_count', v_pending_count,
    'business_date', v_outbox.business_date
  );
end;
$$;


ALTER FUNCTION "private"."day17_enqueue_notification_event_internal"("p_hotel_id" "uuid", "p_event_key" "text", "p_source_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_migration_056_acceptance_rev2"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rec record;
  v_exists boolean;
  v_count bigint;
begin
  for v_rec in
    select table_name
    from (
      values
      ('notification_event_catalog'),
      ('notification_preferences'),
      ('notification_templates'),
      ('notification_template_versions'),
      ('notification_outbox'),
      ('notification_deliveries'),
      ('notification_delivery_attempts'),
      ('notification_dead_letters'),
      ('notification_recipients'),
      ('email_adapter_configs'),
      ('whatsapp_templates'),
      ('business_day_settings')
    ) expected(table_name)
  loop
    suite := 'TABLE';
    test_name := v_rec.table_name;
    passed := to_regclass('public.' || v_rec.table_name) is not null;
    details := case when passed then 'PRESENT' else 'MISSING' end;
    return next;
  end loop;

  for v_rec in
    select table_name, column_name
    from (
      values
      ('notification_event_catalog', 'event_key'),
      ('notification_event_catalog', 'source_type'),
      ('notification_event_catalog', 'audience'),
      ('notification_event_catalog', 'severity'),
      ('notification_event_catalog', 'default_channels'),
      ('notification_event_catalog', 'default_title'),
      ('notification_event_catalog', 'default_body'),
      ('notification_event_catalog', 'is_critical'),
      ('notification_event_catalog', 'is_active'),
      ('notification_event_catalog', 'created_at'),
      ('notification_event_catalog', 'updated_at'),
      ('notification_preferences', 'id'),
      ('notification_preferences', 'hotel_id'),
      ('notification_preferences', 'user_id'),
      ('notification_preferences', 'in_app_enabled'),
      ('notification_preferences', 'email_enabled'),
      ('notification_preferences', 'manual_whatsapp_enabled'),
      ('notification_preferences', 'locale'),
      ('notification_preferences', 'quiet_hours_start'),
      ('notification_preferences', 'quiet_hours_end'),
      ('notification_preferences', 'event_overrides'),
      ('notification_preferences', 'created_at'),
      ('notification_preferences', 'updated_at'),
      ('notification_templates', 'id'),
      ('notification_templates', 'hotel_id'),
      ('notification_templates', 'event_key'),
      ('notification_templates', 'channel'),
      ('notification_templates', 'locale'),
      ('notification_templates', 'title_template'),
      ('notification_templates', 'body_template'),
      ('notification_templates', 'status'),
      ('notification_templates', 'current_version'),
      ('notification_templates', 'created_by'),
      ('notification_templates', 'published_by'),
      ('notification_templates', 'published_at'),
      ('notification_templates', 'created_at'),
      ('notification_templates', 'updated_at'),
      ('notification_template_versions', 'id'),
      ('notification_template_versions', 'template_id'),
      ('notification_template_versions', 'version_number'),
      ('notification_template_versions', 'title_template'),
      ('notification_template_versions', 'body_template'),
      ('notification_template_versions', 'created_by'),
      ('notification_template_versions', 'created_at'),
      ('notification_outbox', 'id'),
      ('notification_outbox', 'hotel_id'),
      ('notification_outbox', 'event_key'),
      ('notification_outbox', 'source_type'),
      ('notification_outbox', 'source_id'),
      ('notification_outbox', 'idempotency_key'),
      ('notification_outbox', 'payload'),
      ('notification_outbox', 'business_date'),
      ('notification_outbox', 'status'),
      ('notification_outbox', 'pending_delivery_count'),
      ('notification_outbox', 'completed_delivery_count'),
      ('notification_outbox', 'failed_delivery_count'),
      ('notification_outbox', 'created_by'),
      ('notification_outbox', 'occurred_at'),
      ('notification_outbox', 'created_at'),
      ('notification_outbox', 'updated_at'),
      ('notification_deliveries', 'id'),
      ('notification_deliveries', 'outbox_id'),
      ('notification_deliveries', 'hotel_id'),
      ('notification_deliveries', 'recipient_user_id'),
      ('notification_deliveries', 'guest_session_id'),
      ('notification_deliveries', 'channel'),
      ('notification_deliveries', 'address_snapshot'),
      ('notification_deliveries', 'locale'),
      ('notification_deliveries', 'rendered_title'),
      ('notification_deliveries', 'rendered_body'),
      ('notification_deliveries', 'status'),
      ('notification_deliveries', 'attempt_count'),
      ('notification_deliveries', 'max_attempts'),
      ('notification_deliveries', 'next_attempt_at'),
      ('notification_deliveries', 'last_error_code'),
      ('notification_deliveries', 'last_error_message'),
      ('notification_deliveries', 'manual_action_url'),
      ('notification_deliveries', 'provider_message_id'),
      ('notification_deliveries', 'queued_at'),
      ('notification_deliveries', 'delivered_at'),
      ('notification_deliveries', 'read_at'),
      ('notification_deliveries', 'metadata'),
      ('notification_deliveries', 'created_at'),
      ('notification_deliveries', 'updated_at'),
      ('notification_delivery_attempts', 'id'),
      ('notification_delivery_attempts', 'delivery_id'),
      ('notification_delivery_attempts', 'hotel_id'),
      ('notification_delivery_attempts', 'attempt_number'),
      ('notification_delivery_attempts', 'attempt_status'),
      ('notification_delivery_attempts', 'adapter_key'),
      ('notification_delivery_attempts', 'error_code'),
      ('notification_delivery_attempts', 'error_message'),
      ('notification_delivery_attempts', 'request_metadata'),
      ('notification_delivery_attempts', 'response_metadata'),
      ('notification_delivery_attempts', 'started_at'),
      ('notification_delivery_attempts', 'completed_at'),
      ('notification_delivery_attempts', 'created_at'),
      ('notification_dead_letters', 'id'),
      ('notification_dead_letters', 'delivery_id'),
      ('notification_dead_letters', 'outbox_id'),
      ('notification_dead_letters', 'hotel_id'),
      ('notification_dead_letters', 'reason_code'),
      ('notification_dead_letters', 'reason_message'),
      ('notification_dead_letters', 'payload_snapshot'),
      ('notification_dead_letters', 'resolved_at'),
      ('notification_dead_letters', 'resolved_by'),
      ('notification_dead_letters', 'resolution_note'),
      ('notification_dead_letters', 'created_at'),
      ('notification_recipients', 'id'),
      ('notification_recipients', 'outbox_id'),
      ('notification_recipients', 'hotel_id'),
      ('notification_recipients', 'user_id'),
      ('notification_recipients', 'title'),
      ('notification_recipients', 'message'),
      ('notification_recipients', 'severity'),
      ('notification_recipients', 'status'),
      ('notification_recipients', 'read_at'),
      ('notification_recipients', 'dismissed_at'),
      ('notification_recipients', 'metadata'),
      ('notification_recipients', 'created_at'),
      ('notification_recipients', 'updated_at'),
      ('email_adapter_configs', 'id'),
      ('email_adapter_configs', 'hotel_id'),
      ('email_adapter_configs', 'adapter_key'),
      ('email_adapter_configs', 'provider'),
      ('email_adapter_configs', 'from_name'),
      ('email_adapter_configs', 'from_email'),
      ('email_adapter_configs', 'reply_to_email'),
      ('email_adapter_configs', 'secret_reference'),
      ('email_adapter_configs', 'endpoint_name'),
      ('email_adapter_configs', 'is_enabled'),
      ('email_adapter_configs', 'metadata'),
      ('email_adapter_configs', 'created_by'),
      ('email_adapter_configs', 'updated_by'),
      ('email_adapter_configs', 'created_at'),
      ('email_adapter_configs', 'updated_at'),
      ('whatsapp_templates', 'id'),
      ('whatsapp_templates', 'hotel_id'),
      ('whatsapp_templates', 'event_key'),
      ('whatsapp_templates', 'locale'),
      ('whatsapp_templates', 'template_name'),
      ('whatsapp_templates', 'body_template'),
      ('whatsapp_templates', 'status'),
      ('whatsapp_templates', 'created_by'),
      ('whatsapp_templates', 'updated_by'),
      ('whatsapp_templates', 'created_at'),
      ('whatsapp_templates', 'updated_at'),
      ('business_day_settings', 'hotel_id'),
      ('business_day_settings', 'business_day_cutoff'),
      ('business_day_settings', 'week_starts_on'),
      ('business_day_settings', 'night_audit_time'),
      ('business_day_settings', 'locale'),
      ('business_day_settings', 'created_by'),
      ('business_day_settings', 'updated_by'),
      ('business_day_settings', 'created_at'),
      ('business_day_settings', 'updated_at')
    ) expected(table_name, column_name)
  loop
    suite := 'COLUMN';
    test_name := v_rec.table_name || '.' || v_rec.column_name;
    select exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = v_rec.table_name
        and c.column_name = v_rec.column_name
    ) into passed;
    details := case when passed then 'PRESENT' else 'MISSING' end;
    return next;
  end loop;

  for v_rec in
    select table_name
    from (
      values
      ('notification_event_catalog'),
      ('notification_preferences'),
      ('notification_templates'),
      ('notification_template_versions'),
      ('notification_outbox'),
      ('notification_deliveries'),
      ('notification_delivery_attempts'),
      ('notification_dead_letters'),
      ('notification_recipients'),
      ('email_adapter_configs'),
      ('whatsapp_templates'),
      ('business_day_settings')
    ) expected(table_name)
  loop
    suite := 'RLS';
    test_name := v_rec.table_name || '.enabled';
    select coalesce(c.relrowsecurity, false)
    into passed
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = v_rec.table_name;
    details := case when passed then 'RLS ENABLED' else 'RLS MISSING' end;
    return next;

    suite := 'RLS';
    test_name := v_rec.table_name || '.policy';
    select count(*)
    into v_count
    from pg_policies p
    where p.schemaname = 'public'
      and p.tablename = v_rec.table_name;
    passed := v_count > 0;
    details := format('%s policy/policies.', v_count);
    return next;

    suite := 'GRANT';
    test_name := v_rec.table_name || '.authenticated_select';
    select has_table_privilege(
      'authenticated',
      format('public.%I', v_rec.table_name),
      'SELECT'
    ) into passed;
    details := case when passed then 'SELECT GRANTED' else 'SELECT MISSING' end;
    return next;
  end loop;

  for v_rec in
    select signature
    from (
      values
      ('public.get_notification_inbox(uuid,integer,timestamptz)'),
      ('public.mark_notification_read(uuid)'),
      ('public.mark_all_notifications_read(uuid)'),
      ('public.upsert_notification_preferences(uuid,jsonb)'),
      ('public.publish_notification_template(uuid,text,text,jsonb)'),
      ('public.enqueue_notification_event(uuid,text,uuid,jsonb)'),
      ('public.process_notification_outbox(integer)'),
      ('public.retry_notification_delivery(uuid)'),
      ('public.get_activity_timeline(uuid,timestamptz,timestamptz,jsonb)'),
      ('public.get_hotel_system_settings(uuid)'),
      ('public.update_hotel_system_settings(uuid,jsonb)'),
      ('public.get_support_workspace(uuid)'),
      ('public.get_active_announcements(uuid)')
    ) expected(signature)
  loop
    suite := 'FUNCTION';
    test_name := v_rec.signature;
    passed := to_regprocedure(v_rec.signature) is not null;
    details := case when passed then 'PRESENT' else 'MISSING' end;
    return next;

    suite := 'GRANT';
    test_name := v_rec.signature || '.authenticated_execute';
    select has_function_privilege(
      'authenticated',
      v_rec.signature,
      'EXECUTE'
    ) into passed;
    details := case when passed then 'EXECUTE GRANTED' else 'EXECUTE MISSING' end;
    return next;
  end loop;

  for v_rec in
    select signature
    from (
      values
      ('private.day17_can_manage_hotel(uuid)'),
      ('private.resolve_hotel_business_date(uuid,timestamptz)'),
      ('private.day17_render_notification_text(text,jsonb)'),
      ('private.day17_enqueue_notification_event_internal(uuid,text,uuid,jsonb,uuid)'),
      ('private.day17_capture_critical_event()'),
      ('private.day17_capture_support_event()'),
      ('private.day17_capture_announcement_event()')
    ) expected(signature)
  loop
    suite := 'PRIVATE_FUNCTION';
    test_name := v_rec.signature;
    passed := to_regprocedure(v_rec.signature) is not null;
    details := case when passed then 'PRESENT' else 'MISSING' end;
    return next;
  end loop;

  for v_rec in
    select *
    from (
      values
        ('reservations', 'day17_reservation_notification_event'),
        ('payments', 'day17_payment_notification_event'),
        ('service_requests', 'day17_service_request_notification_event'),
        ('support_tickets', 'day17_support_ticket_notification_event'),
        ('announcements', 'day17_announcement_notification_event')
    ) expected(table_name, trigger_name)
  loop
    suite := 'TRIGGER';
    test_name := v_rec.trigger_name;
    select exists (
      select 1
      from pg_trigger t
      join pg_class c on c.oid = t.tgrelid
      join pg_namespace n on n.oid = c.relnamespace
      where not t.tgisinternal
        and n.nspname = 'public'
        and c.relname = v_rec.table_name
        and t.tgname = v_rec.trigger_name
    ) into passed;
    details := case when passed then 'PRESENT' else 'MISSING' end;
    return next;
  end loop;

  for v_rec in
    select table_name
    from (
      values
        ('notification_recipients'),
        ('notification_deliveries')
    ) expected(table_name)
  loop
    suite := 'REALTIME';
    test_name := v_rec.table_name;
    select exists (
      select 1
      from pg_publication_tables pt
      where pt.pubname = 'supabase_realtime'
        and pt.schemaname = 'public'
        and pt.tablename = v_rec.table_name
    ) into passed;
    details := case when passed then 'PUBLISHED' else 'NOT PUBLISHED' end;
    return next;
  end loop;

  for v_rec in
    select event_key
    from (
      values
      ('reservation.created'),
      ('reservation.status_changed'),
      ('payment.created'),
      ('payment.status_changed'),
      ('service_request.created'),
      ('service_request.status_changed'),
      ('support.ticket_created'),
      ('support.status_changed'),
      ('announcement.published')
    ) expected(event_key)
  loop
    suite := 'CATALOG';
    test_name := v_rec.event_key;
    select exists (
      select 1
      from public.notification_event_catalog nec
      where nec.event_key = v_rec.event_key
        and nec.is_active
    ) into passed;
    details := case when passed then 'ACTIVE' else 'MISSING' end;
    return next;

    suite := 'TEMPLATE';
    test_name := v_rec.event_key || '.in_app.en';
    select exists (
      select 1
      from public.notification_templates nt
      where nt.hotel_id is null
        and nt.event_key = v_rec.event_key
        and nt.channel = 'in_app'
        and nt.locale = 'en'
        and nt.status = 'published'
    ) into passed;
    details := case when passed then 'PUBLISHED' else 'MISSING' end;
    return next;
  end loop;

  suite := 'FINAL';
  test_name := 'audit_069_actual_schema_respected';
  passed :=
    to_regclass('public.support_ticket_events') is not null
    and to_regclass('public.support_ticket_messages') is null
    and exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = 'announcements'
        and c.column_name = 'target_hotel_id'
    )
    and exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = 'support_tickets'
        and c.column_name = 'created_by'
    );
  details := 'Migration uses the real Day 9 support and announcement schema.';
  return next;

  suite := 'FINAL';
  test_name := 'hotel_settings_actual_schema_respected';
  passed :=
    exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = 'hotel_settings'
        and c.column_name = 'default_tax_percent'
    )
    and not exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = 'hotel_settings'
        and c.column_name = 'tax_rate'
    );
  details := 'Day 8 structured settings remain authoritative.';
  return next;

  suite := 'FINAL';
  test_name := 'business_day_settings_coverage';
  select count(*)
  into v_count
  from public.hotels h
  where not exists (
    select 1
    from public.business_day_settings bds
    where bds.hotel_id = h.id
  );
  passed := v_count = 0;
  details := format('%s hotel(s) missing business-day settings.', v_count);
  return next;

  suite := 'FINAL';
  test_name := 'outbox_anon_blocked';
  passed := not (
    has_table_privilege('anon', 'public.notification_outbox', 'SELECT')
    or has_table_privilege('anon', 'public.notification_outbox', 'INSERT')
    or has_table_privilege('anon', 'public.notification_outbox', 'UPDATE')
  );
  details := 'Anonymous outbox access is blocked.';
  return next;

  suite := 'FINAL';
  test_name := 'recipient_anon_blocked';
  passed := not (
    has_table_privilege('anon', 'public.notification_recipients', 'SELECT')
    or has_table_privilege('anon', 'public.notification_recipients', 'INSERT')
    or has_table_privilege('anon', 'public.notification_recipients', 'UPDATE')
  );
  details := 'Anonymous recipient-inbox access is blocked.';
  return next;

  suite := 'FINAL';
  test_name := 'email_secret_not_stored';
  passed := not exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = 'email_adapter_configs'
      and c.column_name in (
        'api_key',
        'api_secret',
        'password',
        'access_token'
      )
  );
  details := 'Only secret references are stored.';
  return next;

  suite := 'FINAL';
  test_name := 'manual_whatsapp_only';
  passed :=
    to_regclass('public.whatsapp_templates') is not null
    and not exists (
      select 1
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
      where n.nspname in ('public', 'private')
        and p.proname ilike '%send%whatsapp%'
    );
  details := 'WhatsApp foundation is manual-template-only.';
  return next;

  suite := 'FINAL';
  test_name := 'critical_triggers_complete';
  select count(*)
  into v_count
  from pg_trigger t
  join pg_class c on c.oid = t.tgrelid
  join pg_namespace n on n.oid = c.relnamespace
  where not t.tgisinternal
    and n.nspname = 'public'
    and c.relname in ('reservations', 'payments', 'service_requests')
    and t.tgname like 'day17_%_notification_event';
  passed := v_count = 3;
  details := format('%s/3 critical source triggers present.', v_count);
  return next;

  suite := 'FINAL';
  test_name := 'legacy_notifications_preserved';
  passed := to_regclass('public.notifications') is not null;
  details := 'Existing Navbar notification table remains intact.';
  return next;

  suite := 'FINAL';
  test_name := 'guest_notifications_preserved';
  passed := to_regclass('public.guest_notifications') is not null;
  details := 'Day 15 guest notification history remains intact.';
  return next;

  suite := 'FINAL';
  test_name := 'support_rpc_preserved';
  passed :=
    to_regprocedure(
      'public.create_support_ticket(uuid,text,text,text,text)'
    ) is not null
    and to_regprocedure(
      'public.add_support_ticket_message(uuid,text)'
    ) is not null
    and to_regprocedure(
      'public.update_support_ticket_status(uuid,text,text,uuid)'
    ) is not null;
  details := 'Day 9 support workflow remains intact.';
  return next;

  suite := 'FINAL';
  test_name := 'announcement_rpc_preserved';
  passed := to_regprocedure(
    'public.save_platform_announcement(jsonb)'
  ) is not null;
  details := 'Actual Day 9 announcement RPC remains intact.';
  return next;

  suite := 'FINAL';
  test_name := 'migration_056_foundation_complete';
  passed := true;
  details :=
    'Day 17 database foundation is installed; runtime and frontend acceptance remain.';
  return next;
end;
$$;


ALTER FUNCTION "private"."day17_migration_056_acceptance_rev2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_migration_057_acceptance_rev1"() RETURNS TABLE("suite" "text", "test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_proc oid;
  v_definition text;
  v_admin_user uuid;
  v_hotel_id uuid;
  v_event_key text;

  v_email_key text :=
    'd17_m057_' || replace(gen_random_uuid()::text, '-', '');
  v_wa_locale text :=
    'x-d17-' || substring(replace(gen_random_uuid()::text, '-', '') from 1 for 8);

  v_email_first jsonb;
  v_email_second jsonb;
  v_wa_first jsonb;
  v_wa_second jsonb;

  v_email_id uuid;
  v_email_id_second uuid;
  v_wa_id uuid;
  v_wa_id_second uuid;

  v_email_insert_seen boolean := false;
  v_email_update_seen boolean := false;
  v_email_secret_absent boolean := false;
  v_email_values_seen boolean := false;
  v_wa_insert_seen boolean := false;
  v_wa_update_seen boolean := false;
  v_wa_values_seen boolean := false;
  v_runtime_completed boolean := false;
  v_runtime_error text;

  v_previous_sub text :=
    current_setting('request.jwt.claim.sub', true);
  v_previous_role text :=
    current_setting('request.jwt.claim.role', true);
  v_previous_claims text :=
    current_setting('request.jwt.claims', true);
begin
  suite := 'HELPER';
  test_name := 'day17_can_manage_hotel.exists';
  passed := to_regprocedure(
    'private.day17_can_manage_hotel(uuid)'
  ) is not null;
  details := case when passed then 'PRESENT' else 'MISSING' end;
  return next;

  select p.oid
  into v_proc
  from pg_proc p
  where p.oid = to_regprocedure(
    'private.day17_can_manage_hotel(uuid)'
  );

  suite := 'HELPER';
  test_name := 'day17_can_manage_hotel.security_definer';
  select p.prosecdef
  into passed
  from pg_proc p
  where p.oid = v_proc;
  details := case when passed then 'SECURITY DEFINER' else 'NOT SECURITY DEFINER' end;
  return next;

  suite := 'HELPER';
  test_name := 'day17_can_manage_hotel.stable';
  select p.provolatile = 's'
  into passed
  from pg_proc p
  where p.oid = v_proc;
  details := case when passed then 'STABLE' else 'VOLATILITY MISMATCH' end;
  return next;

  suite := 'HELPER';
  test_name := 'day17_can_manage_hotel.authenticated_execute';
  select has_function_privilege(
    'authenticated',
    'private.day17_can_manage_hotel(uuid)',
    'EXECUTE'
  )
  into passed;
  details := case when passed then 'EXECUTE GRANTED' else 'EXECUTE MISSING' end;
  return next;

  suite := 'HELPER';
  test_name := 'day17_can_manage_hotel.anon_blocked';
  select not has_function_privilege(
    'anon',
    'private.day17_can_manage_hotel(uuid)',
    'EXECUTE'
  )
  into passed;
  details := case when passed then 'ANON BLOCKED' else 'ANON CAN EXECUTE' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_email_adapter_config.exists';
  passed := to_regprocedure(
    'public.upsert_email_adapter_config(uuid,jsonb)'
  ) is not null;
  details := case when passed then 'PRESENT' else 'MISSING' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_email_adapter_config.security_definer';
  select p.prosecdef
  into passed
  from pg_proc p
  where p.oid = to_regprocedure(
    'public.upsert_email_adapter_config(uuid,jsonb)'
  );
  details := case when passed then 'SECURITY DEFINER' else 'NOT SECURITY DEFINER' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_email_adapter_config.authenticated_execute';
  select has_function_privilege(
    'authenticated',
    'public.upsert_email_adapter_config(uuid,jsonb)',
    'EXECUTE'
  )
  into passed;
  details := case when passed then 'EXECUTE GRANTED' else 'EXECUTE MISSING' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_email_adapter_config.anon_blocked';
  select not has_function_privilege(
    'anon',
    'public.upsert_email_adapter_config(uuid,jsonb)',
    'EXECUTE'
  )
  into passed;
  details := case when passed then 'ANON BLOCKED' else 'ANON CAN EXECUTE' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_email_adapter_config.no_secret_input';
  select pg_get_functiondef(
    to_regprocedure(
      'public.upsert_email_adapter_config(uuid,jsonb)'
    )::oid
  ) not ilike '%p_payload ->> ''secret_reference''%'
  into passed;
  details := case when passed then 'SECRET INPUT BLOCKED' else 'SECRET INPUT FOUND' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_manual_whatsapp_template.exists';
  passed := to_regprocedure(
    'public.upsert_manual_whatsapp_template(uuid,jsonb)'
  ) is not null;
  details := case when passed then 'PRESENT' else 'MISSING' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_manual_whatsapp_template.security_definer';
  select p.prosecdef
  into passed
  from pg_proc p
  where p.oid = to_regprocedure(
    'public.upsert_manual_whatsapp_template(uuid,jsonb)'
  );
  details := case when passed then 'SECURITY DEFINER' else 'NOT SECURITY DEFINER' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_manual_whatsapp_template.authenticated_execute';
  select has_function_privilege(
    'authenticated',
    'public.upsert_manual_whatsapp_template(uuid,jsonb)',
    'EXECUTE'
  )
  into passed;
  details := case when passed then 'EXECUTE GRANTED' else 'EXECUTE MISSING' end;
  return next;

  suite := 'RPC';
  test_name := 'upsert_manual_whatsapp_template.anon_blocked';
  select not has_function_privilege(
    'anon',
    'public.upsert_manual_whatsapp_template(uuid,jsonb)',
    'EXECUTE'
  )
  into passed;
  details := case when passed then 'ANON BLOCKED' else 'ANON CAN EXECUTE' end;
  return next;

  for suite, test_name, passed, details in
    select
      'RLS_POLICY',
      expected.policy_name,
      exists (
        select 1
        from pg_policy pol
        join pg_class c on c.oid = pol.polrelid
        join pg_namespace n on n.oid = c.relnamespace
        where n.nspname = 'public'
          and c.relname = expected.table_name
          and pol.polname = expected.policy_name
          and pg_get_expr(pol.polqual, pol.polrelid)
            ilike '%day17_can_manage_hotel%'
      ),
      format(
        '%s.%s',
        expected.table_name,
        expected.policy_name
      )
    from (
      values
        ('notification_deliveries',
          'notification_deliveries_select_day17'),
        ('notification_delivery_attempts',
          'notification_attempts_select_day17'),
        ('notification_dead_letters',
          'notification_dead_letters_select_day17'),
        ('email_adapter_configs',
          'email_adapter_configs_select_day17')
    ) expected(table_name, policy_name)
  loop
    return next;
  end loop;

  suite := 'TABLE_SECURITY';
  test_name := 'email_adapter_direct_insert_blocked';
  select not has_table_privilege(
    'authenticated',
    'public.email_adapter_configs',
    'INSERT'
  )
  into passed;
  details := case when passed then 'RPC ONLY' else 'DIRECT INSERT GRANTED' end;
  return next;

  suite := 'TABLE_SECURITY';
  test_name := 'email_adapter_direct_update_blocked';
  select not has_table_privilege(
    'authenticated',
    'public.email_adapter_configs',
    'UPDATE'
  )
  into passed;
  details := case when passed then 'RPC ONLY' else 'DIRECT UPDATE GRANTED' end;
  return next;

  suite := 'TABLE_SECURITY';
  test_name := 'whatsapp_direct_insert_blocked';
  select not has_table_privilege(
    'authenticated',
    'public.whatsapp_templates',
    'INSERT'
  )
  into passed;
  details := case when passed then 'RPC ONLY' else 'DIRECT INSERT GRANTED' end;
  return next;

  suite := 'TABLE_SECURITY';
  test_name := 'whatsapp_direct_update_blocked';
  select not has_table_privilege(
    'authenticated',
    'public.whatsapp_templates',
    'UPDATE'
  )
  into passed;
  details := case when passed then 'RPC ONLY' else 'DIRECT UPDATE GRANTED' end;
  return next;

  select pa.user_id
  into v_admin_user
  from public.platform_admins pa
  where pa.status = 'active'
  order by pa.created_at
  limit 1;

  select h.id
  into v_hotel_id
  from public.hotels h
  where h.status = 'active'
  order by h.created_at
  limit 1;

  select nec.event_key
  into v_event_key
  from public.notification_event_catalog nec
  where nec.is_active
  order by nec.event_key
  limit 1;

  suite := 'RUNTIME';
  test_name := 'active_platform_admin_fixture';
  passed := v_admin_user is not null;
  details := coalesce(v_admin_user::text, 'MISSING');
  return next;

  suite := 'RUNTIME';
  test_name := 'active_hotel_fixture';
  passed := v_hotel_id is not null;
  details := coalesce(v_hotel_id::text, 'MISSING');
  return next;

  suite := 'RUNTIME';
  test_name := 'active_event_fixture';
  passed := v_event_key is not null;
  details := coalesce(v_event_key, 'MISSING');
  return next;

  begin
    if v_admin_user is null
       or v_hotel_id is null
       or v_event_key is null
    then
      raise exception 'Required runtime fixtures were not found.';
    end if;

    perform set_config(
      'request.jwt.claim.sub',
      v_admin_user::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );
    perform set_config(
      'request.jwt.claims',
      jsonb_build_object(
        'sub', v_admin_user,
        'role', 'authenticated'
      )::text,
      true
    );

    v_email_first := public.upsert_email_adapter_config(
      v_hotel_id,
      jsonb_build_object(
        'adapter_key', v_email_key,
        'provider', 'manual',
        'from_name', 'Day 17 Runtime One',
        'from_email', 'runtime1@stayqr.test',
        'reply_to_email', 'reply@stayqr.test',
        'endpoint_name', 'day17_runtime',
        'is_enabled', false,
        'metadata', jsonb_build_object('fixture', 'm057'),
        'secret_reference', 'must_not_be_accepted'
      )
    );

    v_email_id := nullif(
      v_email_first #>> '{adapter,id}',
      ''
    )::uuid;

    select
      eac.id = v_email_id,
      eac.secret_reference is null,
      eac.provider = 'manual'
        and eac.from_name = 'Day 17 Runtime One'
        and not eac.is_enabled
    into
      v_email_insert_seen,
      v_email_secret_absent,
      v_email_values_seen
    from public.email_adapter_configs eac
    where eac.hotel_id = v_hotel_id
      and eac.adapter_key = v_email_key;

    v_email_second := public.upsert_email_adapter_config(
      v_hotel_id,
      jsonb_build_object(
        'adapter_key', v_email_key,
        'provider', 'edge_function',
        'from_name', 'Day 17 Runtime Two',
        'from_email', 'runtime2@stayqr.test',
        'reply_to_email', 'reply2@stayqr.test',
        'endpoint_name', 'day17_runtime_v2',
        'is_enabled', false,
        'metadata', jsonb_build_object('fixture', 'm057-v2')
      )
    );

    v_email_id_second := nullif(
      v_email_second #>> '{adapter,id}',
      ''
    )::uuid;

    select
      eac.id = v_email_id
        and v_email_id_second = v_email_id
        and eac.provider = 'edge_function'
        and eac.from_name = 'Day 17 Runtime Two'
    into v_email_update_seen
    from public.email_adapter_configs eac
    where eac.hotel_id = v_hotel_id
      and eac.adapter_key = v_email_key;

    v_wa_first := public.upsert_manual_whatsapp_template(
      v_hotel_id,
      jsonb_build_object(
        'event_key', v_event_key,
        'locale', v_wa_locale,
        'template_name', 'Day 17 Runtime WhatsApp',
        'body_template', 'Runtime message {{hotel_name}}',
        'status', 'draft'
      )
    );

    v_wa_id := nullif(
      v_wa_first #>> '{template,id}',
      ''
    )::uuid;

    select
      wt.id = v_wa_id,
      wt.template_name = 'Day 17 Runtime WhatsApp'
        and wt.status = 'draft'
    into
      v_wa_insert_seen,
      v_wa_values_seen
    from public.whatsapp_templates wt
    where wt.hotel_id = v_hotel_id
      and wt.event_key = v_event_key
      and wt.locale = v_wa_locale;

    v_wa_second := public.upsert_manual_whatsapp_template(
      v_hotel_id,
      jsonb_build_object(
        'event_key', v_event_key,
        'locale', v_wa_locale,
        'template_name', 'Day 17 Runtime WhatsApp Updated',
        'body_template', 'Updated runtime message {{hotel_name}}',
        'status', 'published'
      )
    );

    v_wa_id_second := nullif(
      v_wa_second #>> '{template,id}',
      ''
    )::uuid;

    select
      wt.id = v_wa_id
        and v_wa_id_second = v_wa_id
        and wt.template_name = 'Day 17 Runtime WhatsApp Updated'
        and wt.status = 'published'
    into v_wa_update_seen
    from public.whatsapp_templates wt
    where wt.hotel_id = v_hotel_id
      and wt.event_key = v_event_key
      and wt.locale = v_wa_locale;

    v_runtime_completed := true;

    raise exception 'DAY17_M057_ROLLBACK_COMPLETE'
      using errcode = 'P0001';
  exception
    when others then
      if sqlerrm = 'DAY17_M057_ROLLBACK_COMPLETE' then
        null;
      else
        v_runtime_error := format('%s [%s]', sqlerrm, sqlstate);
      end if;
  end;

  perform set_config(
    'request.jwt.claim.sub',
    coalesce(v_previous_sub, ''),
    true
  );
  perform set_config(
    'request.jwt.claim.role',
    coalesce(v_previous_role, ''),
    true
  );
  perform set_config(
    'request.jwt.claims',
    coalesce(v_previous_claims, '{}'),
    true
  );

  suite := 'RUNTIME';
  test_name := 'email_adapter_insert';
  passed := coalesce(v_email_insert_seen, false);
  details := coalesce(v_email_first::text, v_runtime_error, 'NO RESULT');
  return next;

  suite := 'RUNTIME';
  test_name := 'email_adapter_update_same_identity';
  passed := coalesce(v_email_update_seen, false);
  details := format(
    'first=%s second=%s',
    coalesce(v_email_id::text, 'null'),
    coalesce(v_email_id_second::text, 'null')
  );
  return next;

  suite := 'RUNTIME';
  test_name := 'email_adapter_secret_ignored';
  passed := coalesce(v_email_secret_absent, false)
    and not (coalesce(v_email_first, '{}'::jsonb) #> '{adapter}')
      ? 'secret_reference';
  details := 'secret_reference absent from row and RPC result';
  return next;

  suite := 'RUNTIME';
  test_name := 'email_adapter_values';
  passed := coalesce(v_email_values_seen, false);
  details := 'Validated provider, sender name and disabled state.';
  return next;

  suite := 'RUNTIME';
  test_name := 'whatsapp_template_insert';
  passed := coalesce(v_wa_insert_seen, false);
  details := coalesce(v_wa_first::text, v_runtime_error, 'NO RESULT');
  return next;

  suite := 'RUNTIME';
  test_name := 'whatsapp_template_update_same_identity';
  passed := coalesce(v_wa_update_seen, false);
  details := format(
    'first=%s second=%s',
    coalesce(v_wa_id::text, 'null'),
    coalesce(v_wa_id_second::text, 'null')
  );
  return next;

  suite := 'RUNTIME';
  test_name := 'whatsapp_template_values';
  passed := coalesce(v_wa_values_seen, false);
  details := 'Validated draft template before update.';
  return next;

  suite := 'RUNTIME';
  test_name := 'runtime_completed';
  passed := v_runtime_completed and v_runtime_error is null;
  details := coalesce(v_runtime_error, 'Runtime completed and rolled back.');
  return next;

  suite := 'ROLLBACK';
  test_name := 'email_fixture_removed';
  select not exists (
    select 1
    from public.email_adapter_configs eac
    where eac.hotel_id = v_hotel_id
      and eac.adapter_key = v_email_key
  )
  into passed;
  details := case when passed then 'CLEAN' else 'FIXTURE REMAINS' end;
  return next;

  suite := 'ROLLBACK';
  test_name := 'whatsapp_fixture_removed';
  select not exists (
    select 1
    from public.whatsapp_templates wt
    where wt.hotel_id = v_hotel_id
      and wt.event_key = v_event_key
      and wt.locale = v_wa_locale
  )
  into passed;
  details := case when passed then 'CLEAN' else 'FIXTURE REMAINS' end;
  return next;

  suite := 'ROLLBACK';
  test_name := 'jwt_claim_sub_restored';
  passed := coalesce(
    current_setting('request.jwt.claim.sub', true),
    ''
  ) = coalesce(v_previous_sub, '');
  details := 'JWT subject restored.';
  return next;

  suite := 'ROLLBACK';
  test_name := 'jwt_claims_restored';
  passed := coalesce(
    current_setting('request.jwt.claims', true),
    '{}'
  ) = coalesce(v_previous_claims, '{}');
  details := 'JWT claims restored.';
  return next;
end;
$$;


ALTER FUNCTION "private"."day17_migration_057_acceptance_rev1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."day17_render_notification_text"("p_template" "text", "p_payload" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_result text := coalesce(p_template, '');
  v_pair record;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    return v_result;
  end if;

  for v_pair in
    select key, value
    from jsonb_each_text(p_payload)
  loop
    v_result := replace(
      v_result,
      '{{' || v_pair.key || '}}',
      coalesce(v_pair.value, '')
    );
  end loop;

  return v_result;
end;
$$;


