CREATE OR REPLACE FUNCTION "private"."enforce_room_subscription_limit_20260728"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    perform
      private.assert_subscription_capacity_internal_20260728(
        new.hotel_id,
        null,
        1,
        0
      );
  elsif new.hotel_id is distinct from old.hotel_id then
    perform
      private.assert_subscription_capacity_internal_20260728(
        new.hotel_id,
        null,
        1,
        0
      );
  end if;

  return new;
end;
$$;


