CREATE OR REPLACE FUNCTION "private"."issue_guest_access_token"("target_guest_session_id" "uuid", "force_rotation" boolean DEFAULT false, "rotation_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_row public.guest_sessions%rowtype;
  active_key_id uuid;
  existing_token_id uuid;
  stay_expiry timestamptz;
  new_token_id uuid;
begin
  select gs.*
  into session_row
  from public.guest_sessions gs
  join public.hotels h on h.id = gs.hotel_id
  join public.rooms r
    on r.id = gs.room_id
   and r.hotel_id = gs.hotel_id
  where gs.id = target_guest_session_id
    and gs.status = 'active'
    and h.status = 'active'
  for update of gs;

  if not found then
    raise exception 'Guest access requires an active hotel stay.';
  end if;

  stay_expiry := coalesce(session_row.extended_until, session_row.checkout_time);

  if stay_expiry is null or stay_expiry <= now() then
    raise exception 'Guest access requires a future stay expiry.';
  end if;

  select t.id
  into existing_token_id
  from public.guest_access_tokens t
  where t.guest_session_id = session_row.id
    and t.status = 'active'
    and t.expires_at > now()
  order by t.issued_at desc
  limit 1
  for update;

  if existing_token_id is not null and not force_rotation then
    return existing_token_id;
  end if;

  update public.guest_access_tokens
  set status = 'revoked',
      revoked_at = now(),
      revoked_by = auth.uid(),
      revocation_reason = coalesce(
        nullif(trim(rotation_reason), ''),
        'Superseded by a new signed guest access token'
      ),
      updated_at = now()
  where guest_session_id = session_row.id
    and status = 'active';

  select id
  into active_key_id
  from private.guest_access_signing_keys
  where status = 'active'
  order by created_at desc
  limit 1;

  if active_key_id is null then
    raise exception 'Guest access signing key is unavailable.';
  end if;

  insert into public.guest_access_tokens (
    signing_key_id,
    hotel_id,
    room_id,
    guest_session_id,
    expires_at
  )
  values (
    active_key_id,
    session_row.hotel_id,
    session_row.room_id,
    session_row.id,
    stay_expiry
  )
  returning id into new_token_id;

  return new_token_id;
end;
$$;


ALTER FUNCTION "private"."issue_guest_access_token"("target_guest_session_id" "uuid", "force_rotation" boolean, "rotation_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."log_reservation_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.reservation_status_history (
      hotel_id,
      reservation_id,
      old_status,
      new_status,
      changed_by
    )
    values (
      new.hotel_id,
      new.id,
      null,
      new.status,
      coalesce(new.created_by, auth.uid())
    );

    return new;
  end if;

  if new.status is distinct from old.status then
    insert into public.reservation_status_history (
      hotel_id,
      reservation_id,
      old_status,
      new_status,
      changed_by,
      reason
    )
    values (
      new.hotel_id,
      new.id,
      old.status,
      new.status,
      coalesce(new.updated_by, auth.uid()),
      case
        when new.status = 'cancelled' then new.cancellation_reason
        else null
      end
    );
  end if;

  return new;
end;
$$;


