CREATE OR REPLACE FUNCTION "private"."log_subscription_change_20260728"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  event_name text;
  source_name text := coalesce(
    nullif(
      current_setting(
        'stayqr.subscription_event_source',
        true
      ),
      ''
    ),
    'database'
  );
  target_hotel_id uuid;
  target_subscription_id uuid;
begin
  if tg_op = 'INSERT' then
    event_name := 'subscription_created';
    target_hotel_id := new.hotel_id;
    target_subscription_id := new.id;
  elsif tg_op = 'DELETE' then
    event_name := 'subscription_deleted';
    target_hotel_id := old.hotel_id;
    target_subscription_id := old.id;
  elsif old.status is distinct from new.status then
    event_name :=
      'status_' || coalesce(old.status, 'null')
      || '_to_' || coalesce(new.status, 'null');
    target_hotel_id := new.hotel_id;
    target_subscription_id := new.id;
  elsif old.plan_id is distinct from new.plan_id then
    event_name := 'plan_changed';
    target_hotel_id := new.hotel_id;
    target_subscription_id := new.id;
  elsif old.provider_subscription_id is distinct from
        new.provider_subscription_id
     or old.provider_payment_link_id is distinct from
        new.provider_payment_link_id
     or old.provider_status is distinct from
        new.provider_status
  then
    event_name := 'provider_state_changed';
    target_hotel_id := new.hotel_id;
    target_subscription_id := new.id;
  else
    event_name := 'subscription_updated';
    target_hotel_id := new.hotel_id;
    target_subscription_id := new.id;
  end if;

  insert into public.subscription_events (
    hotel_id,
    subscription_id,
    event_type,
    event_source,
    actor_user_id,
    old_status,
    new_status,
    old_plan_id,
    new_plan_id,
    provider,
    details,
    old_record,
    new_record,
    occurred_at,
    created_at
  ) values (
    target_hotel_id,
    target_subscription_id,
    event_name,
    source_name,
    (select auth.uid()),
    case when tg_op in ('UPDATE', 'DELETE')
      then old.status end,
    case when tg_op in ('INSERT', 'UPDATE')
      then new.status end,
    case when tg_op in ('UPDATE', 'DELETE')
      then old.plan_id end,
    case when tg_op in ('INSERT', 'UPDATE')
      then new.plan_id end,
    case when tg_op = 'DELETE'
      then old.provider else new.provider end,
    jsonb_build_object(
      'trigger_operation', tg_op
    ),
    case when tg_op in ('UPDATE', 'DELETE')
      then to_jsonb(old) end,
    case when tg_op in ('INSERT', 'UPDATE')
      then to_jsonb(new) end,
    now(),
    now()
  );

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."log_subscription_change_20260728"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."next_reservation_number"("target_hotel_id" "uuid", "target_date" "date" DEFAULT CURRENT_DATE) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_year integer;
  next_number bigint;
begin
  if target_hotel_id is null then
    raise exception 'Hotel is required.';
  end if;

  target_year := extract(year from target_date)::integer;

  insert into public.reservation_number_sequences (
    hotel_id,
    sequence_year,
    last_number
  )
  values (
    target_hotel_id,
    target_year,
    1
  )
  on conflict (hotel_id, sequence_year)
  do update
  set
    last_number =
      public.reservation_number_sequences.last_number + 1,
    updated_at = now()
  returning last_number into next_number;

  return
    'RES-' ||
    target_year::text ||
    '-' ||
    lpad(next_number::text, 6, '0');
end;
$$;


