    nullif(
      left(
        trim(
          both '-'
          from regexp_replace(
            lower(coalesce(raw_value, '')),
            '[^a-z0-9]+',
            '-',
            'g'
          )
        ),
        48
      ),
      ''
    ),
    'hotel'
  );
$$;


