    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if current_setting(
    'stayqr.allow_immutable_event_mutation',
    true
  ) = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  raise exception
    '% is append-only; % is not permitted.',
    tg_table_name,
    tg_op;
end;
$$;


