CREATE OR REPLACE FUNCTION "private"."record_subscription_action_20260728"("target_hotel_id" "uuid", "target_subscription_id" "uuid", "target_event_type" "text", "target_event_source" "text", "target_actor_user_id" "uuid", "target_old_status" "text", "target_new_status" "text", "target_old_plan_id" "uuid", "target_new_plan_id" "uuid", "target_provider" "text", "target_provider_event_id" "text", "action_idempotency_key" "text", "action_details" "jsonb", "action_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  inserted_event_id uuid;
  existing_result jsonb;
begin
  if target_hotel_id is null
     or nullif(trim(target_event_type), '') is null
  then
    raise exception
      'Hotel and event type are required.';
  end if;

  if action_idempotency_key is not null
     and nullif(trim(action_idempotency_key), '') is null
  then
    action_idempotency_key := null;
  end if;

  insert into public.subscription_events (
    hotel_id,
    subscription_id,
    event_type,
    event_source,
    actor_user_id,
    old_status,
    new_status,
    old_plan_id,
    new_plan_id,
    provider,
    provider_event_id,
    idempotency_key,
    details,
    occurred_at,
    created_at
  ) values (
    target_hotel_id,
    target_subscription_id,
    target_event_type,
    coalesce(
      nullif(trim(target_event_source), ''),
      'server_action'
    ),
    target_actor_user_id,
    target_old_status,
    target_new_status,
    target_old_plan_id,
    target_new_plan_id,
    target_provider,
    nullif(trim(target_provider_event_id), ''),
    action_idempotency_key,
    coalesce(action_details, '{}'::jsonb)
      || jsonb_build_object(
        'result',
        coalesce(action_result, '{}'::jsonb)
      ),
    now(),
    now()
  )
  on conflict do nothing
  returning id into inserted_event_id;

  if inserted_event_id is not null then
    return action_result;
  end if;

  if action_idempotency_key is not null then
    existing_result :=
      private.subscription_action_result_20260728(
        action_idempotency_key
      );

    if existing_result is not null then
      return existing_result
        || jsonb_build_object('idempotent', true);
    end if;
  end if;

  return action_result;
end;
$$;


