CREATE OR REPLACE FUNCTION "private"."refresh_subscription_usage_internal"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_plan public.subscription_plans%rowtype;
  room_count_value bigint := 0;
  active_staff_value bigint := 0;
  active_room_types_value bigint := 0;
  menu_items_value bigint := 0;
begin
  if target_hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = target_hotel_id
     )
  then
    raise exception 'Unknown hotel.';
  end if;

  select sp.*
  into current_plan
  from public.hotel_subscriptions hs
  join public.subscription_plans sp on sp.id = hs.plan_id
  where hs.hotel_id = target_hotel_id
    and hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
  order by
    coalesce(hs.updated_at, hs.created_at) desc,
    hs.created_at desc,
    hs.id desc
  limit 1;

  select count(*)
  into room_count_value
  from public.rooms r
  where r.hotel_id = target_hotel_id;

  select count(*)
  into active_staff_value
  from public.staff s
  where s.hotel_id = target_hotel_id
    and s.status = 'active';

  select count(*)
  into active_room_types_value
  from public.room_types rt
  where rt.hotel_id = target_hotel_id
    and rt.is_active;

  select count(*)
  into menu_items_value
  from public.menu_items mi
  where mi.hotel_id = target_hotel_id
    and coalesce(mi.is_available, true);

  insert into public.usage_counters (
    hotel_id,
    metric_key,
    current_value,
    limit_value,
    source,
    captured_at,
    updated_at,
    metadata
  )
  values
    (
      target_hotel_id,
      'rooms',
      room_count_value,
      current_plan.max_rooms,
      'database',
      now(),
      now(),
      '{}'::jsonb
    ),
    (
      target_hotel_id,
      'active_staff',
      active_staff_value,
      current_plan.max_staff,
      'database',
      now(),
      now(),
      '{}'::jsonb
    ),
    (
      target_hotel_id,
      'active_room_types',
      active_room_types_value,
      null,
      'database',
      now(),
      now(),
      '{}'::jsonb
    ),
    (
      target_hotel_id,
      'available_menu_items',
      menu_items_value,
      null,
      'database',
      now(),
      now(),
      '{}'::jsonb
    )
  on conflict (hotel_id, metric_key) do update
  set
    current_value = excluded.current_value,
    limit_value = excluded.limit_value,
    source = excluded.source,
    captured_at = excluded.captured_at,
    metadata = excluded.metadata,
    updated_at = now();

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'rooms', room_count_value,
    'active_staff', active_staff_value,
    'active_room_types', active_room_types_value,
    'available_menu_items', menu_items_value,
    'room_limit', current_plan.max_rooms,
    'staff_limit', current_plan.max_staff,
    'captured_at', now()
  );
end;
$$;


ALTER FUNCTION "private"."refresh_subscription_usage_internal"("target_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."render_guest_access_token"("target_token_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  token_row public.guest_access_tokens%rowtype;
  key_secret bytea;
  signature text;
begin
  select t.*
  into token_row
  from public.guest_access_tokens t
  where t.id = target_token_id;

  if not found then
    raise exception 'Guest access token could not be rendered.';
  end if;

  select k.secret
  into key_secret
  from private.guest_access_signing_keys k
  where k.id = token_row.signing_key_id;

  if not found then
    raise exception 'Guest access signing key is unavailable.';
  end if;

  signature := encode(
    extensions.hmac(
      convert_to(private.guest_access_payload(token_row), 'UTF8'),
      key_secret,
      'sha256'
    ),
    'hex'
  );

  return token_row.token_nonce::text || '.' || signature;
end;
$$;


