CREATE OR REPLACE FUNCTION "private"."resolve_guest_access_token"("p_hotel_slug" "text", "p_access_token" "text", "mark_used" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  token_parts text[];
  supplied_nonce uuid;
  supplied_signature text;
  token_row public.guest_access_tokens%rowtype;
  key_secret bytea;
  expected_signature text;
begin
  token_parts := string_to_array(coalesce(trim(p_access_token), ''), '.');

  if array_length(token_parts, 1) <> 2 then
    return null;
  end if;

  begin
    supplied_nonce := token_parts[1]::uuid;
  exception when others then
    return null;
  end;

  supplied_signature := lower(token_parts[2]);

  if supplied_signature !~ '^[0-9a-f]{64}$' then
    return null;
  end if;

  select t.*
  into token_row
  from public.guest_access_tokens t
  join private.guest_access_signing_keys k
    on k.id = t.signing_key_id
  join public.hotels h
    on h.id = t.hotel_id
  join public.rooms r
    on r.id = t.room_id
   and r.hotel_id = t.hotel_id
  join public.guest_sessions gs
    on gs.id = t.guest_session_id
   and gs.hotel_id = t.hotel_id
   and gs.room_id = t.room_id
  where t.token_nonce = supplied_nonce
    and t.status = 'active'
    and t.expires_at > now()
    and lower(h.slug) = lower(trim(p_hotel_slug))
    and h.status = 'active'
    and gs.status = 'active'
    and coalesce(gs.extended_until, gs.checkout_time) > now();

  if not found then
    return null;
  end if;

  select k.secret
  into key_secret
  from private.guest_access_signing_keys k
  where k.id = token_row.signing_key_id;

  if not found then
    return null;
  end if;

  expected_signature := encode(
    extensions.hmac(
      convert_to(private.guest_access_payload(token_row), 'UTF8'),
      key_secret,
      'sha256'
    ),
    'hex'
  );

  if extensions.digest(convert_to(expected_signature, 'UTF8'), 'sha256') <>
     extensions.digest(convert_to(supplied_signature, 'UTF8'), 'sha256') then
    return null;
  end if;

  if mark_used then
    update public.guest_access_tokens
    set last_used_at = now(),
        use_count = use_count + 1,
        updated_at = now()
    where id = token_row.id;
  end if;

  return token_row.id;
end;
$_$;


ALTER FUNCTION "private"."resolve_guest_access_token"("p_hotel_slug" "text", "p_access_token" "text", "mark_used" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."resolve_hotel_business_date"("p_hotel_id" "uuid", "p_occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_cutoff time;
  v_local timestamp;
begin
  select
    coalesce(nullif(trim(h.timezone), ''), 'Asia/Kolkata'),
    coalesce(bds.business_day_cutoff, '00:00'::time)
  into v_timezone, v_cutoff
  from public.hotels h
  left join public.business_day_settings bds
    on bds.hotel_id = h.id
  where h.id = p_hotel_id;

  if not found then
    raise exception 'Hotel was not found.';
  end if;

  v_local := p_occurred_at at time zone v_timezone;

  return case
    when v_local::time < v_cutoff
      then v_local::date - 1
    else v_local::date
  end;
end;
$$;


