CREATE OR REPLACE FUNCTION "private"."resolve_or_create_guest_day10"("target_hotel_id" "uuid", "guest_payload" "jsonb") RETURNS "public"."guests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  guest_row public.guests%rowtype;
  guest_id_value uuid;
  normalized_phone_value text;
  normalized_email_value text;
  normalized_type_value text;
  normalized_number_value text;
  candidate_count integer := 0;
  candidate_id uuid;
  full_name_value text;
begin
  if guest_payload is null
     or jsonb_typeof(guest_payload) <> 'object'
  then
    raise exception 'Guest details must be a JSON object.';
  end if;

  if nullif(trim(guest_payload ->> 'id'), '') is not null then
    begin
      guest_id_value := (guest_payload ->> 'id')::uuid;
    exception
      when invalid_text_representation then
        raise exception 'Guest ID is invalid.';
    end;

    select g.*
    into guest_row
    from public.guests g
    where g.hotel_id = target_hotel_id
      and g.id = guest_id_value
    for update;

    if not found then
      raise exception 'Selected guest profile was not found for this hotel.';
    end if;

    return guest_row;
  end if;

  normalized_phone_value :=
    private.normalize_guest_phone(guest_payload ->> 'phone');
  normalized_email_value :=
    private.normalize_guest_email(guest_payload ->> 'email');
  normalized_type_value :=
    private.normalize_guest_id_type(guest_payload ->> 'id_type');
  normalized_number_value :=
    private.normalize_guest_id_number(guest_payload ->> 'id_number');

  if normalized_number_value is not null
     and normalized_type_value is null
  then
    raise exception 'ID type is required when an ID number is provided.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:guest-identity:'
      || target_hotel_id::text
      || ':'
      || coalesce(
        normalized_type_value || ':' || normalized_number_value,
        normalized_email_value,
        normalized_phone_value,
        gen_random_uuid()::text
      ),
      0
    )
  );

  if normalized_number_value is not null then
    select
      count(*)::integer,
      (array_agg(g.id order by g.created_at, g.id))[1]
    into candidate_count, candidate_id
    from public.guests g
    where g.hotel_id = target_hotel_id
      and g.normalized_id_type is not distinct from normalized_type_value
      and g.normalized_id_number = normalized_number_value;

    if candidate_count > 1 then
      raise exception
        'Multiple guest profiles share this identity document. Select the intended guest explicitly.';
    end if;
  end if;

  if candidate_count = 0 and normalized_email_value is not null then
    select
      count(*)::integer,
      (array_agg(g.id order by g.created_at, g.id))[1]
    into candidate_count, candidate_id
    from public.guests g
    where g.hotel_id = target_hotel_id
      and g.normalized_email = normalized_email_value;

    if candidate_count > 1 then
      raise exception
        'Multiple guest profiles share this email. Select the intended guest explicitly.';
    end if;
  end if;

  if candidate_count = 0 and normalized_phone_value is not null then
    select
      count(*)::integer,
      (array_agg(g.id order by g.created_at, g.id))[1]
    into candidate_count, candidate_id
    from public.guests g
    where g.hotel_id = target_hotel_id
      and g.normalized_phone = normalized_phone_value;

    if candidate_count > 1 then
      raise exception
        'Multiple guest profiles share this phone number. Select the intended guest explicitly.';
    end if;
  end if;

  if candidate_count = 1 then
    select g.*
    into guest_row
    from public.guests g
    where g.hotel_id = target_hotel_id
      and g.id = candidate_id
    for update;

    update public.guests g
    set
      full_name = coalesce(
        nullif(trim(guest_payload ->> 'full_name'), ''),
        g.full_name
      ),
      phone = coalesce(
        nullif(trim(guest_payload ->> 'phone'), ''),
        g.phone
      ),
      email = coalesce(
        nullif(trim(guest_payload ->> 'email'), ''),
        g.email
      ),
      id_type = coalesce(
        nullif(trim(guest_payload ->> 'id_type'), ''),
        g.id_type
      ),
      id_number = coalesce(
        nullif(trim(guest_payload ->> 'id_number'), ''),
        g.id_number
      ),
      preferred_language = coalesce(
        nullif(trim(guest_payload ->> 'preferred_language'), ''),
        g.preferred_language
      ),
      date_of_birth = coalesce(
        nullif(guest_payload ->> 'date_of_birth', '')::date,
        g.date_of_birth
      ),
      gender = coalesce(
        nullif(lower(trim(guest_payload ->> 'gender')), ''),
        g.gender
      ),
      nationality = coalesce(
        nullif(trim(guest_payload ->> 'nationality'), ''),
        g.nationality
      ),
      country_of_residence = coalesce(
        nullif(trim(guest_payload ->> 'country_of_residence'), ''),
        g.country_of_residence
      ),
      address_line1 = coalesce(
        nullif(trim(guest_payload ->> 'address_line1'), ''),
        g.address_line1
      ),
      address_line2 = coalesce(
        nullif(trim(guest_payload ->> 'address_line2'), ''),
        g.address_line2
      ),
      city = coalesce(
        nullif(trim(guest_payload ->> 'city'), ''),
        g.city
      ),
      state_region = coalesce(
        nullif(trim(guest_payload ->> 'state_region'), ''),
        g.state_region
      ),
      postal_code = coalesce(
        nullif(trim(guest_payload ->> 'postal_code'), ''),
        g.postal_code
      ),
      purpose_of_visit = coalesce(
        nullif(trim(guest_payload ->> 'purpose_of_visit'), ''),
        g.purpose_of_visit
      ),
      is_foreign_guest = coalesce(
        (guest_payload ->> 'is_foreign_guest')::boolean,
        g.is_foreign_guest
      )
    where g.hotel_id = target_hotel_id
      and g.id = candidate_id
    returning g.* into guest_row;

    return guest_row;
  end if;

  full_name_value := nullif(trim(guest_payload ->> 'full_name'), '');

  if full_name_value is null then
    raise exception 'Guest full name is required.';
  end if;

  insert into public.guests (
    hotel_id,
    full_name,
    phone,
    email,
    id_type,
    id_number,
    preferred_language,
    date_of_birth,
    gender,
    nationality,
    country_of_residence,
    address_line1,
    address_line2,
    city,
    state_region,
    postal_code,
    purpose_of_visit,
    is_foreign_guest
  )
  values (
    target_hotel_id,
    full_name_value,
    nullif(trim(guest_payload ->> 'phone'), ''),
    nullif(trim(guest_payload ->> 'email'), ''),
    nullif(trim(guest_payload ->> 'id_type'), ''),
    nullif(trim(guest_payload ->> 'id_number'), ''),
    coalesce(
      nullif(trim(guest_payload ->> 'preferred_language'), ''),
      'english'
    ),
    nullif(guest_payload ->> 'date_of_birth', '')::date,
    nullif(lower(trim(guest_payload ->> 'gender')), ''),
    nullif(trim(guest_payload ->> 'nationality'), ''),
    nullif(trim(guest_payload ->> 'country_of_residence'), ''),
    nullif(trim(guest_payload ->> 'address_line1'), ''),
    nullif(trim(guest_payload ->> 'address_line2'), ''),
    nullif(trim(guest_payload ->> 'city'), ''),
    nullif(trim(guest_payload ->> 'state_region'), ''),
    nullif(trim(guest_payload ->> 'postal_code'), ''),
    nullif(trim(guest_payload ->> 'purpose_of_visit'), ''),
    coalesce((guest_payload ->> 'is_foreign_guest')::boolean, false)
  )
  returning * into guest_row;

  return guest_row;
end;
$$;


ALTER FUNCTION "private"."resolve_or_create_guest_day10"("target_hotel_id" "uuid", "guest_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."resolve_reservation_guest"("target_hotel_id" "uuid", "guest_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_guest_id uuid;
  new_guest_id uuid;
  guest_name text;
  guest_phone text;
  guest_email text;
begin
  if guest_payload is null then
    raise exception 'Guest information is required.';
  end if;

  if nullif(trim(guest_payload->>'id'), '') is not null then
    existing_guest_id := (guest_payload->>'id')::uuid;

    if not exists (
      select 1
      from public.guests g
      where g.id = existing_guest_id
        and g.hotel_id = target_hotel_id
    ) then
      raise exception 'Selected guest does not belong to this hotel.';
    end if;

    return existing_guest_id;
  end if;

  guest_name := nullif(trim(guest_payload->>'full_name'), '');
  guest_phone := nullif(trim(guest_payload->>'phone'), '');
  guest_email :=
    nullif(lower(trim(guest_payload->>'email')), '');

  if guest_name is null then
    raise exception 'Guest full name is required.';
  end if;

  insert into public.guests (
    hotel_id,
    full_name,
    phone,
    email,
    id_type,
    id_number,
    preferred_language
  )
  values (
    target_hotel_id,
    guest_name,
    guest_phone,
    guest_email,
    nullif(trim(guest_payload->>'id_type'), ''),
    nullif(trim(guest_payload->>'id_number'), ''),
    coalesce(
      nullif(trim(guest_payload->>'preferred_language'), ''),
      'english'
    )
  )
  returning id into new_guest_id;

  return new_guest_id;
end;
$$;


ALTER FUNCTION "private"."resolve_reservation_guest"("target_hotel_id" "uuid", "guest_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."run_day2_reservation_exit_gate_20260720"() RETURNS TABLE("test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  platform_test_user uuid;
  unaffiliated_user uuid := gen_random_uuid();

  hotel_a uuid;
  hotel_b uuid;
  hotel_a_name text;
  hotel_b_name text;

  room_a uuid;
  room_b uuid;
  room_a_number text;
  room_b_number text;
  room_type_a uuid;
  room_type_b uuid;
  rate_plan_a uuid;
  rate_plan_b uuid;

  test_start date := current_date + 900;
  test_end date := current_date + 902;

  reservation_a uuid;
  reservation_room_a uuid;
  reservation_a_number text;

  overlapping_reservation uuid;
  cross_tenant_reservation uuid;
  cross_tenant_reservation_room uuid;
  cross_tenant_number text;

  block_a uuid;
  adjacent_block uuid;

  before_room_visible boolean := false;
  after_booking_room_hidden boolean := false;
  after_release_room_visible boolean := false;

  before_type_available bigint := 0;
  after_type_available bigint := 0;

  status_history_created boolean := false;
  reservation_overlap_rejected boolean := false;
  block_overlap_rejected boolean := false;
  adjacent_block_allowed boolean := false;
  block_hides_room boolean := false;
  reservation_against_block_rejected boolean := false;
  cross_tenant_same_dates_allowed boolean := false;
  rate_quote_correct boolean := false;
  booking_number_correct boolean := false;
  unaffiliated_access_denied boolean := false;
  cleanup_completed boolean := false;

  quote_count bigint := 0;
  status_history_count bigint := 0;

  test_sequence_year integer := extract(year from (current_date + 900))::integer;
  sequence_a_existed boolean := false;
  sequence_b_existed boolean := false;
  sequence_a_before bigint;
  sequence_b_before bigint;

  generated_a_1 text;
  generated_a_2 text;
  generated_b_1 text;
begin
  select pa.user_id
  into platform_test_user
  from public.platform_admins pa
  where pa.status = 'active'
  order by pa.created_at
  limit 1;

  if platform_test_user is null then
    raise exception
      'Day 2 exit gate requires one active platform administrator.';
  end if;

  -- Choose two different hotels, each with one usable room and rate plan.
  select
    h.id,
    h.hotel_name,
    r.id,
    r.room_number,
    r.room_type_id,
    rp.id
  into
    hotel_a,
    hotel_a_name,
    room_a,
    room_a_number,
    room_type_a,
    rate_plan_a
  from public.hotels h
  join public.rooms r
    on r.hotel_id = h.id
   and r.status not in ('maintenance', 'out_of_order')
  join lateral (
    select candidate.id
    from public.rate_plans candidate
    where candidate.hotel_id = r.hotel_id
      and candidate.room_type_id = r.room_type_id
      and candidate.is_active
    order by candidate.priority, candidate.created_at
    limit 1
  ) rp on true
  where h.status = 'active'
    and not exists (
      select 1
      from public.room_inventory_allocations ria
      where ria.hotel_id = h.id
        and ria.room_id = r.id
        and ria.status = 'active'
        and ria.stay_dates &&
          daterange(test_start, test_end + 2, '[)')
    )
  order by h.created_at
  limit 1;

  select
    h.id,
    h.hotel_name,
    r.id,
    r.room_number,
    r.room_type_id,
    rp.id
  into
    hotel_b,
    hotel_b_name,
    room_b,
    room_b_number,
    room_type_b,
    rate_plan_b
  from public.hotels h
  join public.rooms r
    on r.hotel_id = h.id
   and r.status not in ('maintenance', 'out_of_order')
  join lateral (
    select candidate.id
    from public.rate_plans candidate
    where candidate.hotel_id = r.hotel_id
      and candidate.room_type_id = r.room_type_id
      and candidate.is_active
    order by candidate.priority, candidate.created_at
    limit 1
  ) rp on true
  where h.status = 'active'
    and h.id <> hotel_a
    and not exists (
      select 1
      from public.room_inventory_allocations ria
      where ria.hotel_id = h.id
        and ria.room_id = r.id
        and ria.status = 'active'
        and ria.stay_dates &&
          daterange(test_start, test_end + 2, '[)')
    )
  order by h.created_at
  limit 1;

  if hotel_a is null or hotel_b is null then
    raise exception
      'Day 2 exit gate requires usable rooms in two different hotels.';
  end if;

  -- Simulate an authenticated platform-admin request for the secure RPCs.
  perform set_config(
    'request.jwt.claim.sub',
    platform_test_user::text,
    true
  );

  -- --------------------------------------------------------------------------
  -- 1. Availability before allocation
  -- --------------------------------------------------------------------------
  select exists (
    select 1
    from public.get_available_rooms(
      hotel_a,
      test_start,
      test_end,
      room_type_a
    ) ar
    where ar.room_id = room_a
  )
  into before_room_visible;

  select coalesce(max(rta.available_rooms), 0)
  into before_type_available
  from public.get_room_type_availability(
    hotel_a,
    test_start,
    test_end
  ) rta
  where rta.room_type_id = room_type_a;

  -- --------------------------------------------------------------------------
  -- 2. Booking-number sequence
  -- --------------------------------------------------------------------------
  select exists (
    select 1
    from public.reservation_number_sequences s
    where s.hotel_id = hotel_a
      and s.sequence_year = test_sequence_year
  )
  into sequence_a_existed;

  if sequence_a_existed then
    select s.last_number
    into sequence_a_before
    from public.reservation_number_sequences s
    where s.hotel_id = hotel_a
      and s.sequence_year = test_sequence_year;
  end if;

  select exists (
    select 1
    from public.reservation_number_sequences s
    where s.hotel_id = hotel_b
      and s.sequence_year = test_sequence_year
  )
  into sequence_b_existed;

  if sequence_b_existed then
    select s.last_number
    into sequence_b_before
    from public.reservation_number_sequences s
    where s.hotel_id = hotel_b
      and s.sequence_year = test_sequence_year;
  end if;

  generated_a_1 :=
    private.next_reservation_number(hotel_a, test_start);
  generated_a_2 :=
    private.next_reservation_number(hotel_a, test_start);
  generated_b_1 :=
    private.next_reservation_number(hotel_b, test_start);

  booking_number_correct :=
    generated_a_1 ~ ('^RES-' || test_sequence_year::text || '-[0-9]{6}$')
    and generated_a_2 ~ ('^RES-' || test_sequence_year::text || '-[0-9]{6}$')
    and generated_b_1 ~ ('^RES-' || test_sequence_year::text || '-[0-9]{6}$')
    and generated_a_1 <> generated_a_2;

  reservation_a_number := generated_a_1;
  cross_tenant_number := generated_b_1;

  -- --------------------------------------------------------------------------
  -- 3. Rate quote
  -- --------------------------------------------------------------------------
  select count(*)
  into quote_count
  from public.get_rate_quote(
    hotel_a,
    rate_plan_a,
    test_start,
    test_end
  );

  rate_quote_correct := quote_count = (test_end - test_start);

  -- --------------------------------------------------------------------------
  -- 4. Confirmed reservation, status history and availability reduction
  -- --------------------------------------------------------------------------
  insert into public.reservations (
    hotel_id,
    reservation_number,
    status,
    booking_source,
    arrival_date,
    departure_date,
    currency_code,
    adults,
    children,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount
  )
  values (
    hotel_a,
    reservation_a_number,
    'confirmed',
    'other',
    test_start,
    test_end,
    'INR',
    1,
    0,
    0,
    0,
    0,
    0
  )
  returning id into reservation_a;

  insert into public.reservation_rooms (
    hotel_id,
    reservation_id,
    room_type_id,
    room_id,
    rate_plan_id,
    status,
    adults,
    children,
    nightly_rate,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount
  )
  values (
    hotel_a,
    reservation_a,
    room_type_a,
    room_a,
    rate_plan_a,
    'confirmed',
    1,
    0,
    0,
    0,
    0,
    0,
    0
  )
  returning id into reservation_room_a;

  select not exists (
    select 1
    from public.get_available_rooms(
      hotel_a,
      test_start,
      test_end,
      room_type_a
    ) ar
    where ar.room_id = room_a
  )
  into after_booking_room_hidden;

  select coalesce(max(rta.available_rooms), 0)
  into after_type_available
  from public.get_room_type_availability(
    hotel_a,
    test_start,
    test_end
  ) rta
  where rta.room_type_id = room_type_a;

  select count(*)
  into status_history_count
  from public.reservation_status_history h
  where h.hotel_id = hotel_a
    and h.reservation_id = reservation_a;

  status_history_created := status_history_count = 1;

  -- --------------------------------------------------------------------------
  -- 5. Overlapping reservation rejected
  -- --------------------------------------------------------------------------
  begin
    insert into public.reservations (
      hotel_id,
      reservation_number,
      status,
      booking_source,
      arrival_date,
      departure_date,
      currency_code,
      adults,
      children,
      room_subtotal,
      tax_amount,
      discount_amount,
      total_amount
    )
    values (
      hotel_a,
      'EXIT-OVERLAP-' || replace(gen_random_uuid()::text, '-', ''),
      'confirmed',
      'other',
      test_start + 1,
      test_end + 1,
      'INR',
      1,
      0,
      0,
      0,
      0,
      0
    )
    returning id into overlapping_reservation;

    insert into public.reservation_rooms (
      hotel_id,
      reservation_id,
      room_type_id,
      room_id,
      rate_plan_id,
      status,
      adults,
      children,
      nightly_rate,
      room_subtotal,
      tax_amount,
      discount_amount,
      total_amount
    )
    values (
      hotel_a,
      overlapping_reservation,
      room_type_a,
      room_a,
      rate_plan_a,
      'confirmed',
      1,
      0,
      0,
      0,
      0,
      0,
      0
    );
  exception
    when exclusion_violation then
      reservation_overlap_rejected := true;
  end;

  -- --------------------------------------------------------------------------
  -- 6. Overlapping room block rejected
  -- --------------------------------------------------------------------------
  begin
    insert into public.room_blocks (
      hotel_id,
      room_id,
      block_type,
      status,
      start_date,
      end_date,
      reason
    )
    values (
      hotel_a,
      room_a,
      'maintenance',
      'active',
      test_start + 1,
      test_end + 1,
      'Day 2 overlap test'
    );
  exception
    when exclusion_violation then
      block_overlap_rejected := true;
  end;

  -- --------------------------------------------------------------------------
  -- 7. Adjacent block accepted: reservation is [start, end), so a block
  --    starting exactly at checkout date must not overlap.
  -- --------------------------------------------------------------------------
  insert into public.room_blocks (
    hotel_id,
    room_id,
    block_type,
    status,
    start_date,
    end_date,
    reason
  )
  values (
    hotel_a,
    room_a,
    'operational',
    'active',
    test_end,
    test_end + 1,
    'Day 2 adjacent-date test'
  )
  returning id into adjacent_block;

  adjacent_block_allowed := exists (
    select 1
    from public.room_inventory_allocations ria
    where ria.room_block_id = adjacent_block
      and ria.status = 'active'
      and ria.starts_on = test_end
      and ria.ends_on = test_end + 1
  );

  delete from public.room_blocks
  where id = adjacent_block
    and hotel_id = hotel_a;

  adjacent_block := null;

  -- --------------------------------------------------------------------------
  -- 8. Same dates in another hotel are independent
  -- --------------------------------------------------------------------------
  insert into public.reservations (
    hotel_id,
    reservation_number,
    status,
    booking_source,
    arrival_date,
    departure_date,
    currency_code,
    adults,
    children,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount
  )
  values (
    hotel_b,
    cross_tenant_number,
    'confirmed',
    'other',
    test_start,
    test_end,
    'INR',
    1,
    0,
    0,
    0,
    0,
    0
  )
  returning id into cross_tenant_reservation;

  insert into public.reservation_rooms (
    hotel_id,
    reservation_id,
    room_type_id,
    room_id,
    rate_plan_id,
    status,
    adults,
    children,
    nightly_rate,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount
  )
  values (
    hotel_b,
    cross_tenant_reservation,
    room_type_b,
    room_b,
    rate_plan_b,
    'confirmed',
    1,
    0,
    0,
    0,
    0,
    0,
    0
  )
  returning id into cross_tenant_reservation_room;

  cross_tenant_same_dates_allowed :=
    exists (
      select 1
      from public.room_inventory_allocations ria
      where ria.reservation_room_id = reservation_room_a
        and ria.status = 'active'
    )
    and exists (
      select 1
      from public.room_inventory_allocations ria
      where ria.reservation_room_id = cross_tenant_reservation_room
        and ria.status = 'active'
    );

  delete from public.reservations
  where id = cross_tenant_reservation
    and hotel_id = hotel_b;

  cross_tenant_reservation := null;
  cross_tenant_reservation_room := null;

  -- --------------------------------------------------------------------------
  -- 9. Release reservation and verify availability returns
  -- --------------------------------------------------------------------------
  update public.reservations
  set status = 'checked_in'
  where id = reservation_a
    and hotel_id = hotel_a;

  update public.reservations
  set status = 'checked_out'
  where id = reservation_a
    and hotel_id = hotel_a;

  select exists (
    select 1
    from public.get_available_rooms(
      hotel_a,
      test_start,
      test_end,
      room_type_a
    ) ar
    where ar.room_id = room_a
  )
  into after_release_room_visible;

  -- --------------------------------------------------------------------------
  -- 10. Active room block hides availability and rejects a reservation
  -- --------------------------------------------------------------------------
  insert into public.room_blocks (
    hotel_id,
    room_id,
    block_type,
    status,
    start_date,
    end_date,
    reason
  )
  values (
    hotel_a,
    room_a,
    'maintenance',
    'active',
    test_start,
    test_end,
    'Day 2 room-block availability test'
  )
  returning id into block_a;

  select not exists (
    select 1
    from public.get_available_rooms(
      hotel_a,
      test_start,
      test_end,
      room_type_a
    ) ar
    where ar.room_id = room_a
  )
  into block_hides_room;

  begin
    insert into public.reservations (
      hotel_id,
      reservation_number,
      status,
      booking_source,
      arrival_date,
      departure_date,
      currency_code,
      adults,
      children,
      room_subtotal,
      tax_amount,
      discount_amount,
      total_amount
    )
    values (
      hotel_a,
      'EXIT-BLOCKED-' || replace(gen_random_uuid()::text, '-', ''),
      'confirmed',
      'other',
      test_start,
      test_end,
      'INR',
      1,
      0,
      0,
      0,
      0,
      0
    )
    returning id into overlapping_reservation;

    insert into public.reservation_rooms (
      hotel_id,
      reservation_id,
      room_type_id,
      room_id,
      rate_plan_id,
      status,
      adults,
      children,
      nightly_rate,
      room_subtotal,
      tax_amount,
      discount_amount,
      total_amount
    )
    values (
      hotel_a,
      overlapping_reservation,
      room_type_a,
      room_a,
      rate_plan_a,
      'confirmed',
      1,
      0,
      0,
      0,
      0,
      0,
      0
    );
  exception
    when exclusion_violation then
      reservation_against_block_rejected := true;
  end;

  delete from public.room_blocks
  where id = block_a
    and hotel_id = hotel_a;

  block_a := null;

  -- --------------------------------------------------------------------------
  -- 11. Unaffiliated identity is denied the hotel-scoped RPC
  -- --------------------------------------------------------------------------
  perform set_config(
    'request.jwt.claim.sub',
    unaffiliated_user::text,
    true
  );

  begin
    perform *
    from public.get_available_rooms(
      hotel_a,
      test_start,
      test_end,
      null
    );

    unaffiliated_access_denied := false;
  exception
    when others then
      unaffiliated_access_denied :=
        position('Hotel access denied' in sqlerrm) > 0;
  end;

  -- Restore the test platform admin for remaining checks/cleanup.
  perform set_config(
    'request.jwt.claim.sub',
    platform_test_user::text,
    true
  );

  -- --------------------------------------------------------------------------
  -- 12. Cleanup all successful test data
  -- --------------------------------------------------------------------------
  if block_a is not null then
    delete from public.room_blocks
    where id = block_a and hotel_id = hotel_a;
  end if;

  if adjacent_block is not null then
    delete from public.room_blocks
    where id = adjacent_block and hotel_id = hotel_a;
  end if;

  if cross_tenant_reservation is not null then
    delete from public.reservations
    where id = cross_tenant_reservation
      and hotel_id = hotel_b;
  end if;

  if overlapping_reservation is not null then
    delete from public.reservations
    where id = overlapping_reservation
      and hotel_id = hotel_a;
  end if;

  if reservation_a is not null then
    delete from public.reservations
    where id = reservation_a
      and hotel_id = hotel_a;
  end if;

  -- Restore reservation sequence state exactly as it was.
  if sequence_a_existed then
    update public.reservation_number_sequences
    set last_number = sequence_a_before
    where hotel_id = hotel_a
      and sequence_year = test_sequence_year;
  else
    delete from public.reservation_number_sequences
    where hotel_id = hotel_a
      and reservation_number_sequences.sequence_year =
        test_sequence_year;
  end if;

  if sequence_b_existed then
    update public.reservation_number_sequences
    set last_number = sequence_b_before
    where hotel_id = hotel_b
      and reservation_number_sequences.sequence_year =
        test_sequence_year;
  else
    delete from public.reservation_number_sequences
    where hotel_id = hotel_b
      and reservation_number_sequences.sequence_year =
        test_sequence_year;
  end if;

  cleanup_completed :=
    not exists (
      select 1
      from public.reservations r
      where r.reservation_number in (
        generated_a_1,
        generated_a_2,
        generated_b_1
      )
      or r.reservation_number like 'EXIT-OVERLAP-%'
      or r.reservation_number like 'EXIT-BLOCKED-%'
    )
    and not exists (
      select 1
      from public.room_blocks rb
      where rb.reason like 'Day 2 %test%'
    );

  return query
  values
    (
      'availability_room_before_booking'::text,
      before_room_visible,
      format(
        '%s room %s was available before allocation.',
        hotel_a_name,
        room_a_number
      )
    ),
    (
      'availability_room_hidden_after_booking'::text,
      after_booking_room_hidden,
      'The allocated room was removed from the availability RPC.'::text
    ),
    (
      'availability_room_type_decreased'::text,
      after_type_available = greatest(before_type_available - 1, 0),
      format(
        'Room-type availability changed from %s to %s.',
        before_type_available,
        after_type_available
      )
    ),
    (
      'availability_room_returned_after_release'::text,
      after_release_room_visible,
      'Checked-out reservation released the room back to availability.'::text
    ),
    (
      'booking_number_generation'::text,
      booking_number_correct,
      format(
        'Generated numbers: %s, %s and %s.',
        generated_a_1,
        generated_a_2,
        generated_b_1
      )
    ),
    (
      'rate_quote_nightly_rows'::text,
      rate_quote_correct,
      format(
        'Rate quote returned %s row(s) for %s night(s).',
        quote_count,
        test_end - test_start
      )
    ),
    (
      'reservation_status_history'::text,
      status_history_created,
      format(
        'Initial confirmed reservation created %s history row(s).',
        status_history_count
      )
    ),
    (
      'overlapping_reservation_rejected'::text,
      reservation_overlap_rejected,
      'Same-room overlapping reservation was rejected.'::text
    ),
    (
      'overlapping_room_block_rejected'::text,
      block_overlap_rejected,
      'A room block overlapping a reservation was rejected.'::text
    ),
    (
      'adjacent_non_overlapping_block_allowed'::text,
      adjacent_block_allowed,
      'A block beginning exactly at reservation checkout was accepted.'::text
    ),
    (
      'room_block_hides_availability'::text,
      block_hides_room,
      'An active room block removed the room from availability.'::text
    ),
    (
      'reservation_against_block_rejected'::text,
      reservation_against_block_rejected,
      'A reservation overlapping an active room block was rejected.'::text
    ),
    (
      'same_dates_across_hotels_allowed'::text,
      cross_tenant_same_dates_allowed,
      format(
        'Same dates allocated independently in %s and %s.',
        hotel_a_name,
        hotel_b_name
      )
    ),
    (
      'unaffiliated_hotel_access_denied'::text,
      unaffiliated_access_denied,
      'A random authenticated identity was denied the hotel availability RPC.'::text
    ),
    (
      'cleanup_completed'::text,
      cleanup_completed,
      'All exit-gate test reservations, blocks and sequence changes were removed.'::text
    );
exception
  when others then
    -- Best-effort cleanup before surfacing an unexpected failure.
    perform set_config(
      'request.jwt.claim.sub',
      platform_test_user::text,
      true
    );

    if block_a is not null then
      delete from public.room_blocks
      where id = block_a and hotel_id = hotel_a;
    end if;

    if adjacent_block is not null then
      delete from public.room_blocks
      where id = adjacent_block and hotel_id = hotel_a;
    end if;

    if cross_tenant_reservation is not null then
      delete from public.reservations
      where id = cross_tenant_reservation
        and hotel_id = hotel_b;
    end if;

    if overlapping_reservation is not null then
      delete from public.reservations
      where id = overlapping_reservation
        and hotel_id = hotel_a;
    end if;

    if reservation_a is not null then
      delete from public.reservations
      where id = reservation_a
        and hotel_id = hotel_a;
    end if;

    if sequence_a_existed and hotel_a is not null then
      update public.reservation_number_sequences
      set last_number = sequence_a_before
      where hotel_id = hotel_a
        and reservation_number_sequences.sequence_year =
          test_sequence_year;
    elsif hotel_a is not null then
      delete from public.reservation_number_sequences
      where hotel_id = hotel_a
        and reservation_number_sequences.sequence_year =
          test_sequence_year;
    end if;

    if sequence_b_existed and hotel_b is not null then
      update public.reservation_number_sequences
      set last_number = sequence_b_before
      where hotel_id = hotel_b
        and reservation_number_sequences.sequence_year =
          test_sequence_year;
    elsif hotel_b is not null then
      delete from public.reservation_number_sequences
      where hotel_id = hotel_b
        and reservation_number_sequences.sequence_year =
          test_sequence_year;
    end if;

    raise;
end;
$_$;


ALTER FUNCTION "private"."run_day2_reservation_exit_gate_20260720"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."run_day3_crud_exit_test_20260722"() RETURNS TABLE("test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user uuid;
  target_hotel uuid;
  target_hotel_name text;
  target_room uuid;
  target_room_type uuid;
  target_rate_plan uuid;
  target_room_number text;

  test_arrival date := current_date + 1050;
  original_departure date := current_date + 1052;
  edited_arrival date := current_date + 1055;
  edited_departure date := current_date + 1058;
  no_show_arrival date := current_date + 1062;
  no_show_departure date := current_date + 1064;

  seasonal_rate_id uuid;
  created_reservation jsonb;
  edited_reservation jsonb;
  cancelled_reservation jsonb;
  no_show_reservation jsonb;

  created_reservation_id uuid;
  no_show_reservation_id uuid;
  created_guest_id uuid;
  no_show_guest_id uuid;

  created_number text;
  no_show_number text;

  test_sequence_year integer :=
    extract(year from (current_date + 1050))::integer;
  sequence_existed boolean := false;
  sequence_before bigint;

  quoted_nightly numeric(12,2) := 1250;
  expected_create_total numeric(12,2) := 2500;
  expected_edit_total numeric(12,2) := 3750;

  create_flow_passed boolean := false;
  deposit_passed boolean := false;
  availability_after_create_passed boolean := false;
  guest_lookup_passed boolean := false;
  edit_flow_passed boolean := false;
  amount_recalculated_passed boolean := false;
  availability_recalculated_passed boolean := false;
  cancel_flow_passed boolean := false;
  cancel_released_passed boolean := false;
  no_show_flow_passed boolean := false;
  no_show_released_passed boolean := false;
  status_history_passed boolean := false;
  activity_logs_passed boolean := false;
  cleanup_passed boolean := false;

  create_updated_at timestamptz;
begin
  select pa.user_id
  into actor_user
  from public.platform_admins pa
  where pa.status = 'active'
  order by pa.created_at
  limit 1;

  if actor_user is null then
    raise exception 'Day 3 test requires an active platform admin.';
  end if;

  perform set_config(
    'request.jwt.claim.sub',
    actor_user::text,
    true
  );

  select
    h.id,
    h.hotel_name,
    r.id,
    r.room_number,
    r.room_type_id,
    rp.id
  into
    target_hotel,
    target_hotel_name,
    target_room,
    target_room_number,
    target_room_type,
    target_rate_plan
  from public.hotels h
  join public.rooms r
    on r.hotel_id = h.id
   and r.status not in ('maintenance', 'out_of_order')
  join lateral (
    select candidate.id
    from public.rate_plans candidate
    where candidate.hotel_id = r.hotel_id
      and candidate.room_type_id = r.room_type_id
      and candidate.is_active
    order by candidate.priority, candidate.created_at
    limit 1
  ) rp on true
  where h.status = 'active'
    and not exists (
      select 1
      from public.room_inventory_allocations ria
      where ria.hotel_id = h.id
        and ria.room_id = r.id
        and ria.status = 'active'
        and ria.stay_dates &&
          daterange(
            test_arrival,
            no_show_departure,
            '[)'
          )
    )
  order by h.created_at, r.created_at
  limit 1;

  if target_room is null then
    raise exception
      'Day 3 test requires one usable room and rate plan.';
  end if;

  select exists (
    select 1
    from public.reservation_number_sequences s
    where s.hotel_id = target_hotel
      and s.sequence_year = test_sequence_year
  )
  into sequence_existed;

  if sequence_existed then
    select s.last_number
    into sequence_before
    from public.reservation_number_sequences s
    where s.hotel_id = target_hotel
      and s.sequence_year = test_sequence_year;
  end if;

  insert into public.seasonal_rates (
    hotel_id,
    rate_plan_id,
    name,
    start_date,
    end_date,
    nightly_rate,
    priority,
    is_active
  )
  values (
    target_hotel,
    target_rate_plan,
    'Day 3 CRUD Test Rate',
    test_arrival - 1,
    no_show_departure + 1,
    quoted_nightly,
    -1000,
    true
  )
  returning id into seasonal_rate_id;

  created_reservation := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'phone',
      'source_reference', 'DAY3-CREATE-TEST',
      'arrival_date', test_arrival,
      'departure_date', original_departure,
      'adults', 1,
      'children', 0,
      'room_type_id', target_room_type,
      'room_id', target_room,
      'rate_plan_id', target_rate_plan,
      'deposit_required', 500,
      'deposit_amount', 500,
      'payment_method', 'upi',
      'payment_reference', 'DAY3-UPI-TEST',
      'special_requests', 'Day 3 create test',
      'internal_notes', 'Remove after test',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 3 Test Guest',
        'phone', '9000000003',
        'email', 'day3-test@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  created_reservation_id :=
    (created_reservation->>'id')::uuid;
  created_guest_id :=
    (created_reservation->'guest'->>'id')::uuid;
  created_number :=
    created_reservation->>'reservation_number';
  create_updated_at :=
    (created_reservation->>'updated_at')::timestamptz;

  create_flow_passed :=
    created_reservation->>'status' = 'confirmed'
    and (created_reservation->>'total_amount')::numeric =
      expected_create_total
    and jsonb_array_length(
      created_reservation->'rooms'
    ) = 1;

  deposit_passed :=
    (created_reservation->>'deposit_collected')::numeric = 500
    and jsonb_array_length(
      created_reservation->'payments'
    ) = 1;

  availability_after_create_passed := not exists (
    select 1
    from public.get_reservation_available_rooms(
      target_hotel,
      test_arrival,
      original_departure,
      target_room_type,
      null
    ) available
    where available.room_id = target_room
  );

  guest_lookup_passed := exists (
    select 1
    from public.search_reservation_guests(
      target_hotel,
      '9000000003',
      10
    ) guest
    where guest.guest_id = created_guest_id
  );

  edited_reservation := public.update_reservation(
    target_hotel,
    created_reservation_id,
    jsonb_build_object(
      'arrival_date', edited_arrival,
      'departure_date', edited_departure,
      'room_type_id', target_room_type,
      'room_id', target_room,
      'rate_plan_id', target_rate_plan,
      'adults', 1,
      'children', 0,
      'booking_source', 'website',
      'source_reference', 'DAY3-EDIT-TEST',
      'deposit_required', 750,
      'additional_deposit_amount', 250,
      'payment_method', 'cash',
      'payment_reference', 'DAY3-CASH-TEST',
      'special_requests', 'Updated request'
    ),
    create_updated_at
  );

  edit_flow_passed :=
    (edited_reservation->>'arrival_date')::date =
      edited_arrival
    and (edited_reservation->>'departure_date')::date =
      edited_departure
    and edited_reservation->>'booking_source' = 'website'
    and (edited_reservation->>'deposit_collected')::numeric =
      750;

  amount_recalculated_passed :=
    (edited_reservation->>'total_amount')::numeric =
      expected_edit_total
    and (edited_reservation->>'room_subtotal')::numeric =
      expected_edit_total;

  availability_recalculated_passed :=
    exists (
      select 1
      from public.get_reservation_available_rooms(
        target_hotel,
        test_arrival,
        original_departure,
        target_room_type,
        null
      ) available
      where available.room_id = target_room
    )
    and not exists (
      select 1
      from public.get_reservation_available_rooms(
        target_hotel,
        edited_arrival,
        edited_departure,
        target_room_type,
        null
      ) available
      where available.room_id = target_room
    );

  cancelled_reservation := public.change_reservation_status(
    target_hotel,
    created_reservation_id,
    'cancelled',
    'Day 3 cancellation test'
  );

  cancel_flow_passed :=
    cancelled_reservation->>'status' = 'cancelled'
    and cancelled_reservation->>'cancellation_reason' =
      'Day 3 cancellation test';

  cancel_released_passed := exists (
    select 1
    from public.get_reservation_available_rooms(
      target_hotel,
      edited_arrival,
      edited_departure,
      target_room_type,
      null
    ) available
    where available.room_id = target_room
  );

  no_show_reservation := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'walk_in',
      'source_reference', 'DAY3-NOSHOW-TEST',
      'arrival_date', no_show_arrival,
      'departure_date', no_show_departure,
      'adults', 1,
      'children', 0,
      'room_type_id', target_room_type,
      'room_id', target_room,
      'rate_plan_id', target_rate_plan,
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 3 No Show Guest',
        'phone', '9000000004',
        'email', 'day3-noshow@stayqr.invalid'
      )
    )
  );

  no_show_reservation_id :=
    (no_show_reservation->>'id')::uuid;
  no_show_guest_id :=
    (no_show_reservation->'guest'->>'id')::uuid;
  no_show_number :=
    no_show_reservation->>'reservation_number';

  no_show_reservation := public.change_reservation_status(
    target_hotel,
    no_show_reservation_id,
    'no_show',
    'Day 3 no-show test'
  );

  no_show_flow_passed :=
    no_show_reservation->>'status' = 'no_show'
    and no_show_reservation->>'no_show_at' is not null;

  no_show_released_passed := exists (
    select 1
    from public.get_reservation_available_rooms(
      target_hotel,
      no_show_arrival,
      no_show_departure,
      target_room_type,
      null
    ) available
    where available.room_id = target_room
  );

  status_history_passed :=
    (
      select count(*)
      from public.reservation_status_history history
      where history.hotel_id = target_hotel
        and history.reservation_id =
          created_reservation_id
    ) >= 2
    and
    (
      select count(*)
      from public.reservation_status_history history
      where history.hotel_id = target_hotel
        and history.reservation_id =
          no_show_reservation_id
    ) >= 2;

  activity_logs_passed :=
    exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id = created_reservation_id
        and log.action = 'reservation.created'
    )
    and exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id = created_reservation_id
        and log.action = 'reservation.updated'
    )
    and exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id = created_reservation_id
        and log.action = 'reservation.cancelled'
    )
    and exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id = no_show_reservation_id
        and log.action = 'reservation.no_show'
    );

  delete from public.activity_logs
  where hotel_id = target_hotel
    and entity_type = 'reservation'
    and entity_id in (
      created_reservation_id,
      no_show_reservation_id
    );

  delete from public.reservations
  where hotel_id = target_hotel
    and id in (
      created_reservation_id,
      no_show_reservation_id
    );

  delete from public.guests
  where hotel_id = target_hotel
    and id in (
      created_guest_id,
      no_show_guest_id
    );

  delete from public.seasonal_rates
  where id = seasonal_rate_id
    and hotel_id = target_hotel;

  if sequence_existed then
    update public.reservation_number_sequences
    set last_number = sequence_before
    where hotel_id = target_hotel
      and sequence_year =
        test_sequence_year;
  else
    delete from public.reservation_number_sequences
    where hotel_id = target_hotel
      and sequence_year =
        test_sequence_year;
  end if;

  cleanup_passed :=
    not exists (
      select 1
      from public.reservations
      where reservation_number in (
        created_number,
        no_show_number
      )
    )
    and not exists (
      select 1
      from public.guests
      where id in (
        created_guest_id,
        no_show_guest_id
      )
    )
    and not exists (
      select 1
      from public.seasonal_rates
      where id = seasonal_rate_id
    )
    and not exists (
      select 1
      from public.activity_logs
      where entity_id in (
        created_reservation_id,
        no_show_reservation_id
      )
    );

  return query
  values
    (
      'create_reservation_flow'::text,
      create_flow_passed,
      format(
        'Created %s for %s at total %s.',
        created_number,
        target_hotel_name,
        expected_create_total
      )
    ),
    (
      'deposit_collection'::text,
      deposit_passed,
      'Initial deposit was recorded and synchronized.'::text
    ),
    (
      'availability_after_create'::text,
      availability_after_create_passed,
      format(
        'Room %s was removed from availability.',
        target_room_number
      )
    ),
    (
      'guest_lookup'::text,
      guest_lookup_passed,
      'New guest was returned by secure hotel-scoped search.'::text
    ),
    (
      'edit_reservation_flow'::text,
      edit_flow_passed,
      'Dates, source, notes and additional deposit were updated.'::text
    ),
    (
      'amount_recalculation'::text,
      amount_recalculated_passed,
      format(
        'Total recalculated from %s to %s.',
        expected_create_total,
        expected_edit_total
      )
    ),
    (
      'availability_recalculation'::text,
      availability_recalculated_passed,
      'Old dates were released and edited dates were allocated.'::text
    ),
    (
      'cancel_reservation_flow'::text,
      cancel_flow_passed,
      'Reservation was cancelled with a required reason.'::text
    ),
    (
      'cancel_releases_availability'::text,
      cancel_released_passed,
      'Cancelled reservation released the room.'::text
    ),
    (
      'no_show_flow'::text,
      no_show_flow_passed,
      'Confirmed reservation changed to no_show.'::text
    ),
    (
      'no_show_releases_availability'::text,
      no_show_released_passed,
      'No-show reservation released the room.'::text
    ),
    (
      'status_history'::text,
      status_history_passed,
      'Create, cancel and no-show status history was recorded.'::text
    ),
    (
      'activity_logs'::text,
      activity_logs_passed,
      'Create, update, cancellation and no-show actions were logged.'::text
    ),
    (
      'cleanup_completed'::text,
      cleanup_passed,
      'All test reservations, guests, rates, logs and sequence changes were removed.'::text
    );
exception
  when others then
    if actor_user is not null then
      perform set_config(
        'request.jwt.claim.sub',
        actor_user::text,
        true
      );
    end if;

    if created_reservation_id is not null
       or no_show_reservation_id is not null
    then
      delete from public.activity_logs
      where hotel_id = target_hotel
        and entity_id in (
          created_reservation_id,
          no_show_reservation_id
        );

      delete from public.reservations
      where hotel_id = target_hotel
        and id in (
          created_reservation_id,
          no_show_reservation_id
        );
    end if;

    if created_guest_id is not null
       or no_show_guest_id is not null
    then
      delete from public.guests
      where hotel_id = target_hotel
        and id in (
          created_guest_id,
          no_show_guest_id
        );
    end if;

    if seasonal_rate_id is not null then
      delete from public.seasonal_rates
      where id = seasonal_rate_id
        and hotel_id = target_hotel;
    end if;

    if target_hotel is not null then
      if sequence_existed then
        update public.reservation_number_sequences
        set last_number = sequence_before
        where hotel_id = target_hotel
          and sequence_year =
            test_sequence_year;
      else
        delete from public.reservation_number_sequences
        where hotel_id = target_hotel
          and sequence_year =
            test_sequence_year;
      end if;
    end if;

    raise;
end;
$$;


ALTER FUNCTION "private"."run_day3_crud_exit_test_20260722"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."run_day4_calendar_exit_test_20260723"() RETURNS TABLE("test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user uuid;
  unaffiliated_user uuid := gen_random_uuid();

  target_hotel uuid;
  target_hotel_name text;
  source_room uuid;
  source_room_number text;
  source_room_type uuid;
  source_rate_plan uuid;

  temporary_room uuid;
  temporary_room_number text :=
    'D4-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  test_guest uuid;
  test_guest_phone text :=
    'D4' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 10);

  seasonal_rate uuid;
  fixed_nightly_rate numeric(12,2) := 1700;

  test_start date := current_date + 1200;
  test_end date := current_date + 1202;
  moved_start date := current_date + 1205;
  moved_end date := current_date + 1207;
  adjacent_end date := current_date + 1209;

  main_reservation jsonb;
  main_reservation_id uuid;
  main_reservation_room_id uuid;
  main_reservation_number text;
  main_updated_at timestamptz;

  draft_reservation jsonb;
  unallocated_reservation_id uuid;
  unallocated_reservation_room_id uuid;
  unallocated_reservation_number text;
  unallocated_updated_at timestamptz;

  active_block jsonb;
  active_block_id uuid;
  adjacent_block jsonb;
  adjacent_block_id uuid;

  test_sequence_year integer :=
    extract(year from (current_date + 1200))::integer;
  sequence_existed boolean := false;
  sequence_before bigint;

  day_calendar jsonb;
  week_calendar jsonb;
  month_calendar jsonb;
  first_page jsonb;
  second_page jsonb;
  unallocated_calendar jsonb;
  assigned_calendar jsonb;

  calendar_day_passed boolean := false;
  calendar_week_passed boolean := false;
  calendar_month_passed boolean := false;
  pagination_passed boolean := false;
  valid_reassignment_passed boolean := false;
  invalid_drag_rejected boolean := false;
  invalid_drag_no_corruption boolean := false;
  block_create_passed boolean := false;
  block_overlap_rejected boolean := false;
  block_update_passed boolean := false;
  block_release_passed boolean := false;
  adjacent_block_passed boolean := false;
  unallocated_visible_passed boolean := false;
  unallocated_assignment_passed boolean := false;
  cross_hotel_access_denied boolean := false;
  activity_logs_passed boolean := false;
  cleanup_passed boolean := false;

  rejected_message text;
begin
  select administrator.user_id
  into actor_user
  from public.platform_admins administrator
  where administrator.status = 'active'
  order by administrator.created_at
  limit 1;

  if actor_user is null then
    raise exception 'Day 4 test requires an active platform administrator.';
  end if;

  perform set_config(
    'request.jwt.claim.sub',
    actor_user::text,
    true
  );

  select
    hotel.id,
    hotel.hotel_name,
    room.id,
    room.room_number,
    room.room_type_id,
    rate_plan.id
  into
    target_hotel,
    target_hotel_name,
    source_room,
    source_room_number,
    source_room_type,
    source_rate_plan
  from public.hotels hotel
  join public.rooms room
    on room.hotel_id = hotel.id
   and room.status not in ('maintenance', 'out_of_order')
  join lateral (
    select candidate.id
    from public.rate_plans candidate
    where candidate.hotel_id = room.hotel_id
      and candidate.room_type_id = room.room_type_id
      and candidate.is_active
    order by candidate.priority, candidate.created_at
    limit 1
  ) rate_plan on true
  where hotel.status = 'active'
    and not exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.hotel_id = hotel.id
        and allocation.room_id = room.id
        and allocation.status = 'active'
        and allocation.stay_dates &&
          daterange(test_start, adjacent_end, '[)')
    )
  order by hotel.created_at, room.created_at
  limit 1;

  if source_room is null then
    raise exception
      'Day 4 test requires one usable room and active rate plan.';
  end if;

  select exists (
    select 1
    from public.reservation_number_sequences sequence
    where sequence.hotel_id = target_hotel
      and sequence.sequence_year =
        test_sequence_year
  )
  into sequence_existed;

  if sequence_existed then
    select sequence.last_number
    into sequence_before
    from public.reservation_number_sequences sequence
    where sequence.hotel_id = target_hotel
      and sequence.sequence_year =
        test_sequence_year;
  end if;

  insert into public.rooms (
    hotel_id,
    room_number,
    room_type,
    room_type_id,
    status
  )
  select
    target_hotel,
    temporary_room_number,
    room.room_type,
    source_room_type,
    'available'
  from public.rooms room
  where room.id = source_room
    and room.hotel_id = target_hotel
  returning id into temporary_room;

  insert into public.guests (
    hotel_id,
    full_name,
    phone,
    email,
    preferred_language
  )
  values (
    target_hotel,
    'StayQR Day 4 Calendar Test Guest',
    test_guest_phone,
    'day4-calendar-test@stayqr.invalid',
    'english'
  )
  returning id into test_guest;

  insert into public.seasonal_rates (
    hotel_id,
    rate_plan_id,
    name,
    start_date,
    end_date,
    nightly_rate,
    priority,
    is_active
  )
  values (
    target_hotel,
    source_rate_plan,
    'Day 4 Calendar Fixed Test Rate',
    test_start - 1,
    adjacent_end + 1,
    fixed_nightly_rate,
    -2000,
    true
  )
  returning id into seasonal_rate;

  main_reservation := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'other',
      'source_reference', 'DAY4-CALENDAR-MAIN',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', source_room,
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest),
      'internal_notes', 'Day 4 calendar exit test'
    )
  );

  main_reservation_id := (main_reservation->>'id')::uuid;
  main_reservation_room_id :=
    (main_reservation->'rooms'->0->>'id')::uuid;
  main_reservation_number :=
    main_reservation->>'reservation_number';
  main_updated_at :=
    (main_reservation->>'updated_at')::timestamptz;

  day_calendar := public.get_booking_calendar(
    target_hotel,
    test_start,
    test_start + 1,
    null,
    array['confirmed'],
    array['active'],
    100,
    0
  );

  week_calendar := public.get_booking_calendar(
    target_hotel,
    test_start - 1,
    test_start + 6,
    null,
    array['confirmed'],
    array['active'],
    100,
    0
  );

  month_calendar := public.get_booking_calendar(
    target_hotel,
    test_start - 7,
    test_start + 35,
    null,
    array['confirmed'],
    array['active'],
    100,
    0
  );

  calendar_day_passed := exists (
    select 1
    from jsonb_array_elements(day_calendar->'events') event
    where event->>'event_type' = 'reservation'
      and (event->>'reservation_id')::uuid =
        main_reservation_id
  );

  calendar_week_passed := exists (
    select 1
    from jsonb_array_elements(week_calendar->'events') event
    where event->>'event_type' = 'reservation'
      and (event->>'reservation_id')::uuid =
        main_reservation_id
  );

  calendar_month_passed := exists (
    select 1
    from jsonb_array_elements(month_calendar->'events') event
    where event->>'event_type' = 'reservation'
      and (event->>'reservation_id')::uuid =
        main_reservation_id
  );

  first_page := public.get_booking_calendar(
    target_hotel,
    test_start,
    test_end,
    source_room_type,
    array['confirmed'],
    array['active'],
    1,
    0
  );

  second_page := public.get_booking_calendar(
    target_hotel,
    test_start,
    test_end,
    source_room_type,
    array['confirmed'],
    array['active'],
    1,
    1
  );

  pagination_passed :=
    (first_page->'pagination'->>'total_rooms')::integer >= 2
    and jsonb_array_length(first_page->'rooms') = 1
    and jsonb_array_length(second_page->'rooms') = 1
    and first_page->'rooms'->0->>'id' is distinct from
      second_page->'rooms'->0->>'id';

  main_reservation := public.move_reservation_on_calendar(
    target_hotel,
    main_reservation_id,
    main_reservation_room_id,
    temporary_room,
    moved_start,
    main_updated_at
  );

  main_updated_at :=
    (main_reservation->>'updated_at')::timestamptz;

  valid_reassignment_passed :=
    (main_reservation->>'arrival_date')::date = moved_start
    and (main_reservation->>'departure_date')::date = moved_end
    and (
      main_reservation->'rooms'->0->>'room_id'
    )::uuid = temporary_room
    and exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.hotel_id = target_hotel
        and allocation.reservation_room_id =
          main_reservation_room_id
        and allocation.room_id = temporary_room
        and allocation.starts_on = moved_start
        and allocation.ends_on = moved_end
        and allocation.status = 'active'
    );

  active_block := public.create_calendar_room_block(
    target_hotel,
    jsonb_build_object(
      'room_id', source_room,
      'block_type', 'maintenance',
      'start_date', moved_start,
      'end_date', moved_end,
      'reason', 'Day 4 invalid-drag blocker'
    )
  );

  active_block_id := (active_block->>'id')::uuid;
  block_create_passed :=
    active_block->>'status' = 'active'
    and exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.room_block_id = active_block_id
        and allocation.status = 'active'
    );

  begin
    perform public.move_reservation_on_calendar(
      target_hotel,
      main_reservation_id,
      main_reservation_room_id,
      source_room,
      moved_start,
      main_updated_at
    );
  exception
    when others then
      rejected_message := sqlerrm;
      invalid_drag_rejected :=
        position('unavailable' in lower(sqlerrm)) > 0
        or position('overlap' in lower(sqlerrm)) > 0;
  end;

  invalid_drag_no_corruption :=
    exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.hotel_id = target_hotel
        and allocation.reservation_room_id =
          main_reservation_room_id
        and allocation.room_id = temporary_room
        and allocation.starts_on = moved_start
        and allocation.ends_on = moved_end
        and allocation.status = 'active'
    )
    and not exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.hotel_id = target_hotel
        and allocation.reservation_room_id =
          main_reservation_room_id
        and allocation.room_id = source_room
        and allocation.status = 'active'
    );

  begin
    perform public.create_calendar_room_block(
      target_hotel,
      jsonb_build_object(
        'room_id', temporary_room,
        'block_type', 'operational',
        'start_date', moved_start,
        'end_date', moved_end,
        'reason', 'Day 4 overlap rejection test'
      )
    );
  exception
    when others then
      block_overlap_rejected :=
        position('overlap' in lower(sqlerrm)) > 0
        or position('inventory' in lower(sqlerrm)) > 0;
  end;

  adjacent_block := public.create_calendar_room_block(
    target_hotel,
    jsonb_build_object(
      'room_id', temporary_room,
      'block_type', 'deep_cleaning',
      'start_date', moved_end,
      'end_date', moved_end + 1,
      'reason', 'Day 4 adjacent block test'
    )
  );

  adjacent_block_id := (adjacent_block->>'id')::uuid;
  adjacent_block_passed :=
    adjacent_block->>'status' = 'active';

  active_block := public.update_calendar_room_block(
    target_hotel,
    active_block_id,
    jsonb_build_object(
      'end_date', moved_end + 1,
      'reason', 'Day 4 updated invalid-drag blocker'
    ),
    (active_block->>'updated_at')::timestamptz
  );

  block_update_passed :=
    (active_block->>'end_date')::date = moved_end + 1
    and active_block->>'reason' =
      'Day 4 updated invalid-drag blocker';

  active_block := public.change_calendar_room_block_status(
    target_hotel,
    active_block_id,
    'released',
    'Day 4 release verification'
  );

  block_release_passed :=
    active_block->>'status' = 'released'
    and active_block->>'release_reason' =
      'Day 4 release verification'
    and not exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.room_block_id = active_block_id
        and allocation.status = 'active'
    );

  draft_reservation := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'draft',
      'booking_source', 'other',
      'source_reference', 'DAY4-UNALLOCATED',
      'arrival_date', test_start + 20,
      'departure_date', test_start + 22,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest)
    )
  );

  unallocated_reservation_id :=
    (draft_reservation->>'id')::uuid;
  unallocated_reservation_room_id :=
    (draft_reservation->'rooms'->0->>'id')::uuid;
  unallocated_reservation_number :=
    draft_reservation->>'reservation_number';

  update public.reservations
  set
    status = 'tentative',
    updated_by = actor_user,
    updated_at = now()
  where hotel_id = target_hotel
    and id = unallocated_reservation_id;

  select reservation.updated_at
  into unallocated_updated_at
  from public.reservations reservation
  where reservation.hotel_id = target_hotel
    and reservation.id = unallocated_reservation_id;

  unallocated_calendar := public.get_booking_calendar(
    target_hotel,
    test_start + 19,
    test_start + 24,
    source_room_type,
    array['tentative'],
    array['active'],
    100,
    0
  );

  unallocated_visible_passed := exists (
    select 1
    from jsonb_array_elements(
      unallocated_calendar->'unallocated_reservations'
    ) item
    where (item->>'reservation_id')::uuid =
      unallocated_reservation_id
  );

  draft_reservation := public.move_reservation_on_calendar(
    target_hotel,
    unallocated_reservation_id,
    unallocated_reservation_room_id,
    source_room,
    test_start + 20,
    unallocated_updated_at
  );

  assigned_calendar := public.get_booking_calendar(
    target_hotel,
    test_start + 19,
    test_start + 24,
    source_room_type,
    array['tentative'],
    array['active'],
    100,
    0
  );

  unallocated_assignment_passed :=
    not exists (
      select 1
      from jsonb_array_elements(
        assigned_calendar->'unallocated_reservations'
      ) item
      where (item->>'reservation_id')::uuid =
        unallocated_reservation_id
    )
    and exists (
      select 1
      from jsonb_array_elements(assigned_calendar->'events') event
      where event->>'event_type' = 'reservation'
        and (event->>'reservation_id')::uuid =
          unallocated_reservation_id
        and (event->>'room_id')::uuid = source_room
    )
    and exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.reservation_room_id =
        unallocated_reservation_room_id
        and allocation.room_id = source_room
        and allocation.status = 'active'
    );

  perform set_config(
    'request.jwt.claim.sub',
    unaffiliated_user::text,
    true
  );

  begin
    perform public.get_booking_calendar(
      target_hotel,
      test_start,
      test_end,
      null,
      null,
      array['active'],
      20,
      0
    );
  exception
    when others then
      cross_hotel_access_denied :=
        position('Hotel access denied' in sqlerrm) > 0;
  end;

  perform set_config(
    'request.jwt.claim.sub',
    actor_user::text,
    true
  );

  activity_logs_passed :=
    exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id = main_reservation_id
        and log.action = 'reservation.calendar_moved'
    )
    and exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id = active_block_id
        and log.action = 'room_block.created'
    )
    and exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id = active_block_id
        and log.action = 'room_block.updated'
    )
    and exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id = active_block_id
        and log.action = 'room_block.released'
    );

  -- Cleanup generic logs before their source records.
  delete from public.activity_logs log
  where log.hotel_id = target_hotel
    and (
      log.entity_id in (
        main_reservation_id,
        unallocated_reservation_id,
        active_block_id,
        adjacent_block_id
      )
      or log.description ilike '%Day 4%'
    );

  delete from public.reservations reservation
  where reservation.hotel_id = target_hotel
    and reservation.id in (
      main_reservation_id,
      unallocated_reservation_id
    );

  delete from public.room_blocks block
  where block.hotel_id = target_hotel
    and block.id in (
      active_block_id,
      adjacent_block_id
    );

  delete from public.seasonal_rates rate
  where rate.hotel_id = target_hotel
    and rate.id = seasonal_rate;

  delete from public.guests guest
  where guest.hotel_id = target_hotel
    and guest.id = test_guest;

  delete from public.rooms room
  where room.hotel_id = target_hotel
    and room.id = temporary_room;

  if sequence_existed then
    update public.reservation_number_sequences
    set last_number = sequence_before
    where hotel_id = target_hotel
      and sequence_year =
        test_sequence_year;
  else
    delete from public.reservation_number_sequences
    where hotel_id = target_hotel
      and sequence_year =
        test_sequence_year;
  end if;

  cleanup_passed :=
    not exists (
      select 1
      from public.reservations reservation
      where reservation.reservation_number in (
        main_reservation_number,
        unallocated_reservation_number
      )
        or reservation.source_reference in (
          'DAY4-CALENDAR-MAIN',
          'DAY4-UNALLOCATED'
        )
    )
    and not exists (
      select 1
      from public.rooms room
      where room.id = temporary_room
    )
    and not exists (
      select 1
      from public.room_blocks block
      where block.id in (active_block_id, adjacent_block_id)
    )
    and not exists (
      select 1
      from public.guests guest
      where guest.id = test_guest
    )
    and not exists (
      select 1
      from public.seasonal_rates rate
      where rate.id = seasonal_rate
    );

  return query
  values
    (
      'calendar_day_representation'::text,
      calendar_day_passed,
      'Day view returned the reservation event.'::text
    ),
    (
      'calendar_week_representation'::text,
      calendar_week_passed,
      'Week view returned the same reservation event.'::text
    ),
    (
      'calendar_month_representation'::text,
      calendar_month_passed,
      'Month view returned the same reservation event.'::text
    ),
    (
      'room_pagination'::text,
      pagination_passed,
      'Room pagination returned distinct one-room pages.'::text
    ),
    (
      'valid_calendar_move'::text,
      valid_reassignment_passed,
      'Reservation moved atomically to the target room and dates.'::text
    ),
    (
      'invalid_drag_rejected'::text,
      invalid_drag_rejected,
      coalesce(rejected_message, 'Invalid move was rejected.')::text
    ),
    (
      'invalid_drag_no_corruption'::text,
      invalid_drag_no_corruption,
      'Rejected movement left the authoritative allocation unchanged.'::text
    ),
    (
      'room_block_creation'::text,
      block_create_passed,
      'Active room block created an inventory allocation.'::text
    ),
    (
      'room_block_overlap_rejected'::text,
      block_overlap_rejected,
      'Room block overlapping a reservation was rejected.'::text
    ),
    (
      'room_block_update'::text,
      block_update_passed,
      'Active block dates and reason were updated.'::text
    ),
    (
      'room_block_release'::text,
      block_release_passed,
      'Released block removed its active inventory allocation.'::text
    ),
    (
      'adjacent_block_allowed'::text,
      adjacent_block_passed,
      'Block beginning exactly at checkout was accepted.'::text
    ),
    (
      'unallocated_reservation_visible'::text,
      unallocated_visible_passed,
      'Tentative unallocated reservation appeared in the queue.'::text
    ),
    (
      'unallocated_room_assignment'::text,
      unallocated_assignment_passed,
      'Unallocated reservation received one valid room allocation.'::text
    ),
    (
      'tenant_access_denied'::text,
      cross_hotel_access_denied,
      'Unaffiliated identity was denied calendar access.'::text
    ),
    (
      'activity_logs'::text,
      activity_logs_passed,
      'Calendar movement and room-block actions were logged.'::text
    ),
    (
      'cleanup_completed'::text,
      cleanup_passed,
      format(
        'All Day 4 test records for %s were removed.',
        target_hotel_name
      )
    );
exception
  when others then
    if actor_user is not null then
      perform set_config(
        'request.jwt.claim.sub',
        actor_user::text,
        true
      );
    end if;

    if target_hotel is not null then
      delete from public.activity_logs log
      where log.hotel_id = target_hotel
        and (
          log.entity_id in (
            main_reservation_id,
            unallocated_reservation_id,
            active_block_id,
            adjacent_block_id
          )
          or log.description ilike '%Day 4%'
        );

      delete from public.reservations reservation
      where reservation.hotel_id = target_hotel
        and reservation.id in (
          main_reservation_id,
          unallocated_reservation_id
        );

      delete from public.room_blocks block
      where block.hotel_id = target_hotel
        and block.id in (
          active_block_id,
          adjacent_block_id
        );

      if seasonal_rate is not null then
        delete from public.seasonal_rates rate
        where rate.hotel_id = target_hotel
          and rate.id = seasonal_rate;
      end if;

      if test_guest is not null then
        delete from public.guests guest
        where guest.hotel_id = target_hotel
          and guest.id = test_guest;
      end if;

      if temporary_room is not null then
        delete from public.rooms room
        where room.hotel_id = target_hotel
          and room.id = temporary_room;
      end if;

      if sequence_existed then
        update public.reservation_number_sequences
        set last_number = sequence_before
        where hotel_id = target_hotel
          and sequence_year =
            test_sequence_year;
      else
        delete from public.reservation_number_sequences
        where hotel_id = target_hotel
          and sequence_year =
            test_sequence_year;
      end if;
    end if;

    raise;
end;
$$;


ALTER FUNCTION "private"."run_day4_calendar_exit_test_20260723"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."run_day4_final_acceptance_gate_20260723"() RETURNS TABLE("test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user uuid;
  target_hotel uuid;
  target_room uuid;
  target_room_number text;
  target_room_type uuid;
  target_rate_plan uuid;
  max_adults integer;
  max_children integer;
  max_occupancy integer;

  temporary_room uuid;
  temporary_room_number text :=
    'D4A-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  test_guest uuid;
  test_phone text :=
    'D4A' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 10);
  test_source_reference text :=
    'DAY4-FINAL-ACCEPTANCE-' ||
    upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  baseline_rate uuid;
  changed_rate uuid;
  baseline_nightly numeric(12,2) := 1400;
  changed_nightly numeric(12,2) := 2400;

  test_start date := current_date + 2200;
  test_end date := current_date + 2202;
  changed_start date := current_date + 2210;
  changed_end date := current_date + 2212;
  block_start date := current_date + 2220;
  block_end date := current_date + 2222;

  created_reservation jsonb;
  test_reservation_id uuid;
  test_reservation_room_id uuid;
  reservation_number text;
  reservation_updated_at timestamptz;
  original_activity_count bigint;
  final_activity_count bigint;

  created_block jsonb;
  block_id uuid;
  cancelled_block jsonb;

  test_sequence_year integer :=
    extract(year from (current_date + 2200))::integer;
  sequence_existed boolean := false;
  sequence_before bigint;

  matching_calendar jsonb;
  excluding_calendar jsonb;

  filter_include_passed boolean := false;
  filter_exclude_passed boolean := false;
  stale_rejected boolean := false;
  capacity_rejected boolean := false;
  rate_change_rejected boolean := false;
  no_partial_activity boolean := false;
  block_actor_visible boolean := false;
  block_reason_required boolean := false;
  block_cancel_passed boolean := false;
  cleanup_passed boolean := false;

  stale_message text;
  capacity_message text;
  rate_message text;
  reason_message text;
begin
  select administrator.user_id
  into actor_user
  from public.platform_admins administrator
  where administrator.status = 'active'
  order by administrator.created_at
  limit 1;

  if actor_user is null then
    raise exception 'Day 4 acceptance requires an active platform administrator.';
  end if;

  perform set_config(
    'request.jwt.claim.sub',
    actor_user::text,
    true
  );

  select
    hotel.id,
    room.id,
    room.room_number,
    room.room_type_id,
    rate_plan.id,
    room_type.max_adults,
    room_type.max_children,
    room_type.max_occupancy
  into
    target_hotel,
    target_room,
    target_room_number,
    target_room_type,
    target_rate_plan,
    max_adults,
    max_children,
    max_occupancy
  from public.hotels hotel
  join public.rooms room
    on room.hotel_id = hotel.id
   and room.status not in ('maintenance', 'out_of_order')
  join public.room_types room_type
    on room_type.id = room.room_type_id
   and room_type.hotel_id = room.hotel_id
   and room_type.is_active
  join lateral (
    select candidate.id
    from public.rate_plans candidate
    where candidate.hotel_id = room.hotel_id
      and candidate.room_type_id = room.room_type_id
      and candidate.is_active
    order by candidate.priority, candidate.created_at
    limit 1
  ) rate_plan on true
  where hotel.status = 'active'
    and not exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.hotel_id = hotel.id
        and allocation.room_id = room.id
        and allocation.status = 'active'
        and allocation.stay_dates &&
          daterange(test_start, block_end, '[)')
    )
  order by hotel.created_at, room.created_at
  limit 1;

  if target_room is null then
    raise exception
      'Day 4 acceptance requires one usable room and active rate plan.';
  end if;

  select exists (
    select 1
    from public.reservation_number_sequences sequence
    where sequence.hotel_id = target_hotel
      and sequence.sequence_year = test_sequence_year
  )
  into sequence_existed;

  if sequence_existed then
    select sequence.last_number
    into sequence_before
    from public.reservation_number_sequences sequence
    where sequence.hotel_id = target_hotel
      and sequence.sequence_year = test_sequence_year;
  end if;

  insert into public.rooms (
    hotel_id,
    room_number,
    room_type,
    room_type_id,
    status
  )
  select
    target_hotel,
    temporary_room_number,
    room.room_type,
    target_room_type,
    'available'
  from public.rooms room
  where room.id = target_room
    and room.hotel_id = target_hotel
  returning id into temporary_room;

  insert into public.guests (
    hotel_id,
    full_name,
    phone,
    email,
    preferred_language
  )
  values (
    target_hotel,
    'StayQR Day 4 Final Acceptance Guest',
    test_phone,
    lower(test_source_reference) || '@stayqr.invalid',
    'english'
  )
  returning id into test_guest;

  insert into public.seasonal_rates (
    hotel_id,
    rate_plan_id,
    name,
    start_date,
    end_date,
    nightly_rate,
    priority,
    is_active
  )
  values (
    target_hotel,
    target_rate_plan,
    'Day 4 Final Acceptance Baseline Rate',
    test_start,
    test_end,
    baseline_nightly,
    -3000,
    true
  )
  returning id into baseline_rate;

  insert into public.seasonal_rates (
    hotel_id,
    rate_plan_id,
    name,
    start_date,
    end_date,
    nightly_rate,
    priority,
    is_active
  )
  values (
    target_hotel,
    target_rate_plan,
    'Day 4 Final Acceptance Changed Rate',
    changed_start,
    changed_end,
    changed_nightly,
    -3000,
    true
  )
  returning id into changed_rate;

  created_reservation := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'other',
      'source_reference', test_source_reference,
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', target_room_type,
      'room_id', target_room,
      'rate_plan_id', target_rate_plan,
      'guest', jsonb_build_object('id', test_guest),
      'internal_notes', 'Temporary Day 4 final acceptance record'
    )
  );

  test_reservation_id := (created_reservation->>'id')::uuid;
  test_reservation_room_id :=
    (created_reservation->'rooms'->0->>'id')::uuid;
  reservation_number := created_reservation->>'reservation_number';
  reservation_updated_at :=
    (created_reservation->>'updated_at')::timestamptz;

  matching_calendar := public.get_booking_calendar(
    target_hotel,
    test_start - 1,
    test_end + 1,
    target_room_type,
    array['confirmed'],
    array['active'],
    100,
    0
  );

  excluding_calendar := public.get_booking_calendar(
    target_hotel,
    test_start - 1,
    test_end + 1,
    target_room_type,
    array['draft'],
    array['active'],
    100,
    0
  );

  filter_include_passed := exists (
    select 1
    from jsonb_array_elements(matching_calendar->'events') event
    where event->>'event_type' = 'reservation'
      and (event->>'reservation_id')::uuid = test_reservation_id
  );

  filter_exclude_passed := not exists (
    select 1
    from jsonb_array_elements(excluding_calendar->'events') event
    where event->>'event_type' = 'reservation'
      and (event->>'reservation_id')::uuid = test_reservation_id
  );

  select count(*)
  into original_activity_count
  from public.activity_logs log
  where log.hotel_id = target_hotel
    and log.entity_type = 'reservation'
    and log.entity_id = test_reservation_id;

  begin
    perform public.move_reservation_on_calendar(
      target_hotel,
      test_reservation_id,
      test_reservation_room_id,
      temporary_room,
      test_start,
      reservation_updated_at - interval '1 second'
    );
  exception
    when others then
      stale_message := sqlerrm;
      stale_rejected :=
        position('Refresh and try again' in sqlerrm) > 0
        or position('changed after the calendar loaded' in lower(sqlerrm)) > 0;
  end;

  update public.reservations
  set
    adults = greatest(max_adults, max_occupancy) + 1,
    updated_by = actor_user,
    updated_at = now()
  where hotel_id = target_hotel
    and id = test_reservation_id;

  select reservation.updated_at
  into reservation_updated_at
  from public.reservations reservation
  where reservation.hotel_id = target_hotel
    and reservation.id = test_reservation_id;

  begin
    perform public.move_reservation_on_calendar(
      target_hotel,
      test_reservation_id,
      test_reservation_room_id,
      temporary_room,
      test_start,
      reservation_updated_at
    );
  exception
    when others then
      capacity_message := sqlerrm;
      capacity_rejected :=
        position('capacity' in lower(sqlerrm)) > 0
        or position('guest count exceeds' in lower(sqlerrm)) > 0;
  end;

  update public.reservations
  set
    adults = 1,
    children = 0,
    updated_by = actor_user,
    updated_at = now()
  where hotel_id = target_hotel
    and id = test_reservation_id;

  select reservation.updated_at
  into reservation_updated_at
  from public.reservations reservation
  where reservation.hotel_id = target_hotel
    and reservation.id = test_reservation_id;

  begin
    perform public.move_reservation_on_calendar(
      target_hotel,
      test_reservation_id,
      test_reservation_room_id,
      temporary_room,
      changed_start,
      reservation_updated_at
    );
  exception
    when others then
      rate_message := sqlerrm;
      rate_change_rejected :=
        position('change the reservation rate' in lower(sqlerrm)) > 0
        or position('target dates change' in lower(sqlerrm)) > 0;
  end;

  select count(*)
  into final_activity_count
  from public.activity_logs log
  where log.hotel_id = target_hotel
    and log.entity_type = 'reservation'
    and log.entity_id = test_reservation_id;

  no_partial_activity :=
    final_activity_count = original_activity_count
    and exists (
      select 1
      from public.reservation_rooms room_record
      where room_record.hotel_id = target_hotel
        and room_record.id = test_reservation_room_id
        and room_record.room_id = target_room
        and room_record.status = 'confirmed'
    )
    and exists (
      select 1
      from public.reservations reservation
      where reservation.hotel_id = target_hotel
        and reservation.id = test_reservation_id
        and reservation.arrival_date = test_start
        and reservation.departure_date = test_end
    )
    and exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.hotel_id = target_hotel
        and allocation.reservation_room_id = test_reservation_room_id
        and allocation.room_id = target_room
        and allocation.status = 'active'
        and allocation.stay_dates = daterange(test_start, test_end, '[)')
    );

  created_block := public.create_calendar_room_block(
    target_hotel,
    jsonb_build_object(
      'room_id', temporary_room,
      'block_type', 'operational',
      'start_date', block_start,
      'end_date', block_end,
      'reason', 'Day 4 final acceptance cancellation test',
      'notes', 'Temporary record; must be cleaned automatically'
    )
  );

  block_id := (created_block->>'id')::uuid;
  created_block := public.get_calendar_room_block_details(
    target_hotel,
    block_id
  );

  block_actor_visible :=
    nullif(trim(created_block->>'created_by_name'), '') is not null;

  begin
    perform public.change_calendar_room_block_status(
      target_hotel,
      block_id,
      'cancelled',
      null
    );
  exception
    when others then
      reason_message := sqlerrm;
      block_reason_required :=
        position('reason is required' in lower(sqlerrm)) > 0;
  end;

  cancelled_block := public.change_calendar_room_block_status(
    target_hotel,
    block_id,
    'cancelled',
    'Day 4 final acceptance cancellation reason'
  );

  block_cancel_passed :=
    cancelled_block->>'status' = 'cancelled'
    and cancelled_block->>'release_reason' =
      'Day 4 final acceptance cancellation reason'
    and not exists (
      select 1
      from public.room_inventory_allocations allocation
      where allocation.hotel_id = target_hotel
        and allocation.room_block_id = block_id
        and allocation.status = 'active'
    )
    and exists (
      select 1
      from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_type = 'room_block'
        and log.entity_id = block_id
        and log.action = 'room_block.cancelled'
    );

  delete from public.activity_logs log
  where log.hotel_id = target_hotel
    and log.entity_id in (test_reservation_id, block_id);

  delete from public.reservations reservation
  where reservation.hotel_id = target_hotel
    and reservation.id = test_reservation_id;

  delete from public.room_blocks block
  where block.hotel_id = target_hotel
    and block.id = block_id;

  delete from public.seasonal_rates rate
  where rate.hotel_id = target_hotel
    and rate.id in (baseline_rate, changed_rate);

  delete from public.guests guest
  where guest.hotel_id = target_hotel
    and guest.id = test_guest;

  delete from public.rooms room
  where room.hotel_id = target_hotel
    and room.id = temporary_room;

  if sequence_existed then
    update public.reservation_number_sequences sequence
    set last_number = sequence_before
    where sequence.hotel_id = target_hotel
      and sequence.sequence_year = test_sequence_year;
  else
    delete from public.reservation_number_sequences sequence
    where sequence.hotel_id = target_hotel
      and sequence.sequence_year = test_sequence_year;
  end if;

  cleanup_passed :=
    not exists (
      select 1
      from public.reservations reservation
      where reservation.id = test_reservation_id
        or reservation.source_reference = test_source_reference
    )
    and not exists (
      select 1
      from public.room_blocks block
      where block.id = block_id
    )
    and not exists (
      select 1
      from public.rooms room
      where room.id = temporary_room
    )
    and not exists (
      select 1
      from public.guests guest
      where guest.id = test_guest
    )
    and not exists (
      select 1
      from public.seasonal_rates rate
      where rate.id in (baseline_rate, changed_rate)
    );

  return query
  values
    (
      'status_filter_includes_matching_reservation'::text,
      filter_include_passed,
      'Confirmed filter returned the confirmed test reservation.'::text
    ),
    (
      'status_filter_excludes_non_matching_reservation'::text,
      filter_exclude_passed,
      'Draft filter excluded the confirmed test reservation.'::text
    ),
    (
      'stale_update_rejected'::text,
      stale_rejected,
      coalesce(stale_message, 'Expected stale-update rejection was not raised.')::text
    ),
    (
      'capacity_violation_rejected'::text,
      capacity_rejected,
      coalesce(capacity_message, 'Expected capacity rejection was not raised.')::text
    ),
    (
      'rate_changing_move_rejected'::text,
      rate_change_rejected,
      coalesce(rate_message, 'Expected rate-change rejection was not raised.')::text
    ),
    (
      'rejected_moves_created_no_partial_activity'::text,
      no_partial_activity,
      'Rejected moves left room, dates, inventory and activity unchanged.'::text
    ),
    (
      'room_block_created_by_visible'::text,
      block_actor_visible,
      coalesce(
        'Created by: ' || nullif(created_block->>'created_by_name', ''),
        'Room-block actor name was missing.'
      )::text
    ),
    (
      'room_block_cancellation_requires_reason'::text,
      block_reason_required,
      coalesce(reason_message, 'Expected mandatory-reason rejection was not raised.')::text
    ),
    (
      'room_block_cancellation_releases_inventory'::text,
      block_cancel_passed,
      'Cancelled block released inventory and recorded activity.'::text
    ),
    (
      'cleanup_completed'::text,
      cleanup_passed,
      format(
        'Temporary reservation %s, room %s and related records were removed.',
        coalesce(reservation_number, 'unknown'),
        coalesce(temporary_room_number, 'unknown')
      )::text
    );
exception
  when others then
    if actor_user is not null then
      perform set_config(
        'request.jwt.claim.sub',
        actor_user::text,
        true
      );
    end if;

    if target_hotel is not null then
      delete from public.activity_logs log
      where log.hotel_id = target_hotel
        and log.entity_id in (test_reservation_id, block_id);

      if test_reservation_id is not null then
        delete from public.reservations reservation
        where reservation.hotel_id = target_hotel
          and reservation.id = test_reservation_id;
      end if;

      if block_id is not null then
        delete from public.room_blocks block
        where block.hotel_id = target_hotel
          and block.id = block_id;
      end if;

      delete from public.seasonal_rates rate
      where rate.hotel_id = target_hotel
        and rate.id in (baseline_rate, changed_rate);

      if test_guest is not null then
        delete from public.guests guest
        where guest.hotel_id = target_hotel
          and guest.id = test_guest;
      end if;

      if temporary_room is not null then
        delete from public.rooms room
        where room.hotel_id = target_hotel
          and room.id = temporary_room;
      end if;

      if sequence_existed then
        update public.reservation_number_sequences sequence
        set last_number = sequence_before
        where sequence.hotel_id = target_hotel
          and sequence.sequence_year = test_sequence_year;
      else
        delete from public.reservation_number_sequences sequence
        where sequence.hotel_id = target_hotel
          and sequence.sequence_year = test_sequence_year;
      end if;
    end if;

    raise;
end;
$$;


ALTER FUNCTION "private"."run_day4_final_acceptance_gate_20260723"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."run_day5_checkout_final_gate_20260724"() RETURNS TABLE("test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_state jsonb;
  v_actor_user uuid;
  v_target_hotel uuid;
  v_other_hotel uuid;
  v_reservation_id uuid;
  v_reservation_room_id uuid;
  v_room_id uuid;
  v_guest_id uuid;
  v_session_id uuid;
  v_invoice_id uuid;
  v_expected_total numeric(12,2);
  v_expected_deposit numeric(12,2);
  v_duplicate_rejected boolean := false;
  v_duplicate_reason text := '';
  v_operations_today jsonb;
  v_operations_departure jsonb;
begin
  select s.payload into v_state
  from private.day5_checkout_smoke_state_20260724 s
  where s.singleton;

  if v_state is null then
    raise exception 'Day 5 checkout smoke state is missing. Run audit 027 first.';
  end if;

  v_actor_user := (v_state->>'actor_user')::uuid;
  v_target_hotel := (v_state->>'hotel_id')::uuid;
  v_other_hotel := nullif(v_state->>'other_hotel_id', '')::uuid;
  v_reservation_id := (v_state->>'reservation_id')::uuid;
  v_reservation_room_id := (v_state->>'reservation_room_id')::uuid;
  v_room_id := (v_state->>'room_id')::uuid;
  v_guest_id := (v_state->>'guest_id')::uuid;
  v_expected_total := (v_state->>'expected_total')::numeric(12,2);
  v_expected_deposit := (v_state->>'deposit_amount')::numeric(12,2);

  select gs.id into v_session_id
  from public.guest_sessions gs
  where gs.hotel_id = v_target_hotel
    and gs.reservation_room_id = v_reservation_room_id
  limit 1;

  select inv.id into v_invoice_id
  from public.invoices inv
  where inv.hotel_id = v_target_hotel
    and inv.guest_session_id = v_session_id
  limit 1;

  perform set_config('request.jwt.claim.sub', v_actor_user::text, true);

  begin
    perform public.checkout_guest_session(
      v_target_hotel,
      v_session_id,
      0,
      'fixed',
      0,
      true,
      'cash',
      'D5CO-DUPLICATE-RETRY',
      'Duplicate checkout rejection test',
      false
    );
  exception when others then
    v_duplicate_reason := sqlerrm;
    v_duplicate_rejected :=
      position('already checked out' in lower(sqlerrm)) > 0
      or position('invoice already exists' in lower(sqlerrm)) > 0
      or position('only an active guest stay' in lower(sqlerrm)) > 0;
  end;

  v_operations_today := public.get_reservation_operations(
    v_target_hotel,
    (v_state->>'business_date')::date,
    7
  );

  v_operations_departure := public.get_reservation_operations(
    v_target_hotel,
    (v_state->>'departure_test_date')::date,
    7
  );

  return query
  with checks(test_name, passed, details) as (
    values
      (
        '01_controlled_state_present',
        v_state is not null and v_session_id is not null and v_invoice_id is not null,
        'The controlled reservation, stay and final invoice are present.'
      ),
      (
        '02_reservation_and_room_checked_out',
        exists (
          select 1
          from public.reservations r
          join public.reservation_rooms rr
            on rr.hotel_id = r.hotel_id
           and rr.reservation_id = r.id
          where r.hotel_id = v_target_hotel
            and r.id = v_reservation_id
            and r.status = 'checked_out'
            and rr.id = v_reservation_room_id
            and rr.status = 'checked_out'
        ),
        'The linked booking header and physical reservation room are checked out.'
      ),
      (
        '03_guest_session_completed_and_qr_expired',
        exists (
          select 1
          from public.guest_sessions gs
          where gs.hotel_id = v_target_hotel
            and gs.id = v_session_id
            and gs.status = 'completed'
            and gs.expired_at is not null
            and gs.checked_out_at is not null
        ),
        'The stay is completed and guest/QR access has been expired.'
      ),
      (
        '04_invoice_created_once_and_paid',
        (
          select count(*) = 1
          from public.invoices inv
          where inv.hotel_id = v_target_hotel
            and inv.guest_session_id = v_session_id
            and inv.payment_status = 'paid'
            and inv.invoice_status = 'paid'
            and inv.pending_amount = 0
            and inv.total_amount = v_expected_total
            and inv.paid_amount = v_expected_total
            and inv.previous_paid_amount = v_expected_deposit
            and inv.amount_to_collect = v_expected_total - v_expected_deposit
        ),
        'Exactly one paid invoice carries the correct total, deposit and remaining settlement.'
      ),
      (
        '05_invoice_items_match_final_total',
        coalesce((
          select round(sum(ii.amount), 2) = v_expected_total
          from public.invoice_items ii
          where ii.hotel_id = v_target_hotel
            and ii.invoice_id = v_invoice_id
        ), false),
        'The itemised invoice rows reconcile exactly to the final invoice total.'
      ),
      (
        '06_deposit_and_final_collection_exactly_once',
        coalesce((
          select round(sum(pc.amount), 2) = v_expected_total
          from public.payment_collections pc
          where pc.hotel_id = v_target_hotel
            and pc.guest_session_id = v_session_id
            and pc.invoice_id = v_invoice_id
        ), false)
        and (
          select count(*) = 1
          from public.reservation_payment_transfers transfer
          where transfer.hotel_id = v_target_hotel
            and transfer.reservation_room_id = v_reservation_room_id
            and transfer.amount = v_expected_deposit
        ),
        'The ₹500 reservation deposit and the remaining checkout collection total the invoice exactly once.'
      ),
      (
        '07_room_cleaning_and_inventory_released',
        exists (
          select 1 from public.rooms room
          where room.hotel_id = v_target_hotel
            and room.id = v_room_id
            and room.status = 'cleaning'
        )
        and not exists (
          select 1 from public.room_inventory_allocations allocation
          where allocation.hotel_id = v_target_hotel
            and allocation.reservation_room_id = v_reservation_room_id
            and allocation.status = 'active'
        )
        and exists (
          select 1 from public.room_inventory_allocations allocation
          where allocation.hotel_id = v_target_hotel
            and allocation.reservation_room_id = v_reservation_room_id
            and allocation.status = 'released'
            and allocation.released_at is not null
        ),
        'Checkout sends the room to cleaning and releases the authoritative inventory allocation.'
      ),
      (
        '08_one_housekeeping_task',
        (
          select count(*) = 1
          from public.housekeeping_tasks task
          where task.hotel_id = v_target_hotel
            and task.room_id = v_room_id
            and task.task_type = 'room_cleaning'
            and task.status in ('pending', 'in_progress')
        ),
        'Exactly one active room-cleaning task exists for the checked-out room.'
      ),
      (
        '09_checkout_event_created_once',
        (
          select count(*) = 1
          from public.reservation_checkout_events event
          where event.hotel_id = v_target_hotel
            and event.guest_session_id = v_session_id
            and event.invoice_id = v_invoice_id
        ),
        'Exactly one immutable checkout event anchors the transaction.'
      ),
      (
        '10_duplicate_checkout_rejected',
        v_duplicate_rejected,
        coalesce(nullif(v_duplicate_reason, ''), 'The duplicate call did not return the required rejection.')
      ),
      (
        '11_operational_queues_refreshed',
        not exists (
          select 1
          from jsonb_array_elements(coalesce(v_operations_today->'in_house', '[]'::jsonb)) item
          where item->>'reservation_id' = v_reservation_id::text
        )
        and not exists (
          select 1
          from jsonb_array_elements(coalesce(v_operations_today->'today_arrivals', '[]'::jsonb)) item
          where item->>'reservation_id' = v_reservation_id::text
        )
        and not exists (
          select 1
          from jsonb_array_elements(coalesce(v_operations_departure->'today_departures', '[]'::jsonb)) item
          where item->>'reservation_id' = v_reservation_id::text
        ),
        'The checked-out room no longer appears in arrivals, in-house or pending-departure queues.'
      ),
      (
        '12_no_active_guest_or_duplicate_financial_records',
        not exists (
          select 1 from public.guest_sessions gs
          where gs.hotel_id = v_target_hotel
            and gs.id = v_session_id
            and gs.status = 'active'
        )
        and (
          select count(*) = 1
          from public.reservation_checkin_events event
          where event.hotel_id = v_target_hotel
            and event.reservation_room_id = v_reservation_room_id
        )
        and (
          select count(*) = 1
          from public.reservation_checkout_events event
          where event.hotel_id = v_target_hotel
            and event.guest_session_id = v_session_id
        ),
        'No active stay, duplicate check-in event or duplicate checkout event remains.'
      ),
      (
        '13_tenant_isolation',
        v_other_hotel is null
        or (
          not exists (
            select 1 from public.reservations r
            where r.hotel_id = v_other_hotel
              and r.source_reference = 'DAY5-CHECKOUT-SMOKE'
          )
          and not exists (
            select 1 from public.rooms room
            where room.hotel_id = v_other_hotel
              and room.room_number like (v_state->>'room_prefix') || '%'
          )
          and not exists (
            select 1 from public.invoices inv
            where inv.hotel_id = v_other_hotel
              and inv.guest_id = v_guest_id
          )
        ),
        'No controlled reservation, room or invoice leaked into the second hotel.'
      )
  )
  select checks.test_name, checks.passed, checks.details
  from checks
  order by checks.test_name;
end;
$$;


ALTER FUNCTION "private"."run_day5_checkout_final_gate_20260724"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."run_day9_commercial_foundation_acceptance_20260728"() RETURNS TABLE("test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  platform_admin_user_id uuid;
  platform_admin_email text;
  owner_user_id uuid;
  owner_email text;

  own_hotel_id uuid;
  own_hotel_name text;
  other_hotel_id uuid;
  other_hotel_name text;
  own_subscription_id uuid;
  own_plan_id uuid;

  suffix text := left(replace(gen_random_uuid()::text, '-', ''), 12);
  ticket_own_id uuid;
  ticket_other_id uuid;
  ticket_event_id uuid;
  support_session_id uuid;
  webhook_id uuid;
  global_announcement_id uuid;
  own_announcement_id uuid;
  other_announcement_id uuid;
  admin_plan_price_id uuid;
  generated_subscription_event_id uuid;

  resolved_identities boolean := false;
  vd_reconciliation_ok boolean := false;
  apex_reconciliation_ok boolean := false;
  reconciliation_archive_ok boolean := false;
  migration_events_ok boolean := false;
  plan_price_coverage_ok boolean := false;
  usage_seed_accuracy_ok boolean := false;
  usage_refresh_ok boolean := false;
  subscription_event_generated boolean := false;
  subscription_event_immutable boolean := false;
  support_ticket_foundation_ok boolean := false;
  support_ticket_event_immutable boolean := false;
  support_access_unique_active boolean := false;
  webhook_idempotency_unique boolean := false;
  platform_admin_announcement_write boolean := false;
  platform_admin_plan_price_write boolean := false;
  platform_admin_global_visibility boolean := false;
  owner_own_subscription_events boolean := false;
  owner_cross_subscription_events_blocked boolean := false;
  owner_own_usage_visible boolean := false;
  owner_cross_usage_blocked boolean := false;
  owner_own_support_visible boolean := false;
  owner_cross_support_blocked boolean := false;
  owner_announcement_visibility boolean := false;
  owner_other_announcement_blocked boolean := false;
  owner_plan_prices_visible boolean := false;
  owner_support_insert_blocked boolean := false;
  owner_plan_price_insert_blocked boolean := false;
  owner_webhook_visibility_blocked boolean := false;
  anon_subscription_events_blocked boolean := false;
  anon_usage_support_webhook_blocked boolean := false;
  production_counts_unchanged boolean := false;
  synthetic_records_rolled_back boolean := false;

  role_switched boolean := false;
  audit_failure text;

  before_subscription_event_count bigint;
  before_usage_count bigint;
  before_ticket_count bigint;
  before_ticket_event_count bigint;
  before_announcement_count bigint;
  before_support_session_count bigint;
  before_webhook_count bigint;
  before_plan_price_count bigint;

  after_subscription_event_count bigint;
  after_usage_count bigint;
  after_ticket_count bigint;
  after_ticket_event_count bigint;
  after_announcement_count bigint;
  after_support_session_count bigint;
  after_webhook_count bigint;
  after_plan_price_count bigint;

  refreshed_usage jsonb;
  results jsonb := '[]'::jsonb;
begin
  -- ------------------------------------------------------------------------
  -- Resolve a real Platform Admin and a real non-platform hotel owner.
  -- ------------------------------------------------------------------------
  select pa.user_id, lower(au.email)
  into platform_admin_user_id, platform_admin_email
  from public.platform_admins pa
  join auth.users au on au.id = pa.user_id
  where pa.status = 'active'
    and au.email is not null
    and coalesce(
      au.banned_until,
      '-infinity'::timestamptz
    ) <= now()
  order by pa.created_at, pa.user_id
  limit 1;

  select
    s.auth_user_id,
    lower(s.email),
    h.id,
    h.hotel_name
  into
    owner_user_id,
    owner_email,
    own_hotel_id,
    own_hotel_name
  from public.staff s
  join public.hotels h on h.id = s.hotel_id
  where h.slug = 'stayqr-day-8-test-hotel'
    and s.status = 'active'
    and s.auth_user_id is not null
    and lower(replace(trim(s.role::text), ' ', '_')) = 'owner'
    and not exists (
      select 1
      from public.platform_admins pa
      where pa.user_id = s.auth_user_id
        and pa.status = 'active'
    )
  order by s.created_at, s.id
  limit 1;

  select h.id, h.hotel_name
  into other_hotel_id, other_hotel_name
  from public.hotels h
  where h.id <> own_hotel_id
  order by
    case when h.slug = 'vd-stay-inn' then 0 else 1 end,
    h.created_at,
    h.id
  limit 1;

  select hs.id, hs.plan_id
  into own_subscription_id, own_plan_id
  from public.hotel_subscriptions hs
  where hs.hotel_id = own_hotel_id
    and hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
  order by
    coalesce(hs.updated_at, hs.created_at) desc,
    hs.created_at desc,
    hs.id desc
  limit 1;

  resolved_identities :=
    platform_admin_user_id is not null
    and platform_admin_email is not null
    and owner_user_id is not null
    and owner_email is not null
    and own_hotel_id is not null
    and other_hotel_id is not null
    and own_subscription_id is not null
    and own_plan_id is not null;

  -- ------------------------------------------------------------------------
  -- Verify committed guarded reconciliation.
  -- ------------------------------------------------------------------------
  vd_reconciliation_ok := exists (
    select 1
    from public.hotel_subscriptions hs
    join public.subscription_plans sp on sp.id = hs.plan_id
    where hs.hotel_id =
        '77d850d0-016d-4155-bc44-a6207d30e7b9'::uuid
      and hs.status = 'active'
      and hs.billing_mode = 'complimentary'
      and hs.amount_minor = 0
      and sp.max_rooms >= (
        select count(*)
        from public.rooms r
        where r.hotel_id = hs.hotel_id
      )
  );

  apex_reconciliation_ok :=
    exists (
      select 1
      from public.hotel_subscriptions hs
      where hs.id =
          'b2870090-4736-4716-819e-56e403e930cb'::uuid
        and hs.hotel_id =
          '9e105be7-0d93-4dc9-84c6-f729b53f1368'::uuid
        and hs.status = 'expired'
        and hs.end_date <= now()
    )
    and exists (
      select 1
      from public.hotels h
      where h.id =
          '9e105be7-0d93-4dc9-84c6-f729b53f1368'::uuid
        and h.subscription_status = 'expired'
    );

  reconciliation_archive_ok := (
    select count(*) = 2
    from private.day9_subscription_reconciliation_archive_20260728 a
    where a.archive_key in (
      'vd-stay-inn-before-migration-020',
      'hotel-apex-before-migration-020'
    )
  );

  migration_events_ok :=
    exists (
      select 1
      from public.subscription_events se
      where se.hotel_id =
          '77d850d0-016d-4155-bc44-a6207d30e7b9'::uuid
        and se.event_type = 'subscription_created'
        and se.event_source = 'migration_020'
    )
    and exists (
      select 1
      from public.subscription_events se
      where se.hotel_id =
          '9e105be7-0d93-4dc9-84c6-f729b53f1368'::uuid
        and se.event_type = 'status_active_to_expired'
        and se.event_source = 'migration_020'
    );

  plan_price_coverage_ok := not exists (
    select 1
    from public.subscription_plans sp
    where not exists (
      select 1
      from public.subscription_plan_prices spp
      where spp.plan_id = sp.id
        and spp.provider = 'manual'
        and spp.billing_cycle = 'monthly'
        and spp.currency_code = sp.currency_code
    )
  );

  usage_seed_accuracy_ok := not exists (
    select 1
    from public.hotels h
    left join public.usage_counters room_usage
      on room_usage.hotel_id = h.id
     and room_usage.metric_key = 'rooms'
    left join public.usage_counters staff_usage
      on staff_usage.hotel_id = h.id
     and staff_usage.metric_key = 'active_staff'
    where room_usage.hotel_id is null
       or staff_usage.hotel_id is null
       or room_usage.current_value <> (
         select count(*)
         from public.rooms r
         where r.hotel_id = h.id
       )
       or staff_usage.current_value <> (
         select count(*)
         from public.staff s
         where s.hotel_id = h.id
           and s.status = 'active'
       )
  );

  select count(*) into before_subscription_event_count
  from public.subscription_events;
  select count(*) into before_usage_count
  from public.usage_counters;
  select count(*) into before_ticket_count
  from public.support_tickets;
  select count(*) into before_ticket_event_count
  from public.support_ticket_events;
  select count(*) into before_announcement_count
  from public.announcements;
  select count(*) into before_support_session_count
  from public.support_access_sessions;
  select count(*) into before_webhook_count
  from public.webhook_events;
  select count(*) into before_plan_price_count
  from public.subscription_plan_prices;

  -- ------------------------------------------------------------------------
  -- Reversible runtime acceptance.
  -- ------------------------------------------------------------------------
  begin
    if not resolved_identities then
      raise exception
        'Runtime identities, hotels or current subscription could not be resolved.';
    end if;

    perform set_config(
      'stayqr.subscription_event_source',
      'audit_051',
      true
    );

    -- Trigger a reversible subscription update and prove automatic logging.
    update public.hotel_subscriptions hs
    set
      provider_status = 'audit-051-' || suffix,
      provider_metadata =
        coalesce(hs.provider_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'audit_051', suffix
        ),
      updated_at = now()
    where hs.id = own_subscription_id;

    select se.id
    into generated_subscription_event_id
    from public.subscription_events se
    where se.subscription_id = own_subscription_id
      and se.event_source = 'audit_051'
      and se.event_type = 'provider_state_changed'
      and se.new_record
        ->> 'provider_status'
        = 'audit-051-' || suffix
    order by se.created_at desc, se.id desc
    limit 1;

    subscription_event_generated :=
      generated_subscription_event_id is not null;

    begin
      update public.subscription_events se
      set details = se.details || '{"tampered":true}'::jsonb
      where se.id = generated_subscription_event_id;
    exception when others then
      subscription_event_immutable :=
        lower(sqlerrm) like '%append-only%'
        or lower(sqlerrm) like '%not permitted%';
    end;

    -- Refresh and verify authoritative usage.
    refreshed_usage :=
      private.refresh_subscription_usage_internal(
        own_hotel_id
      );

    usage_refresh_ok :=
      coalesce(
        (refreshed_usage ->> 'rooms')::bigint,
        -1
      ) = (
        select count(*)
        from public.rooms r
        where r.hotel_id = own_hotel_id
      )
      and coalesce(
        (refreshed_usage ->> 'active_staff')::bigint,
        -1
      ) = (
        select count(*)
        from public.staff s
        where s.hotel_id = own_hotel_id
          and s.status = 'active'
      );

    -- Synthetic support tickets and immutable event.
    insert into public.support_tickets (
      ticket_number,
      hotel_id,
      subject,
      description,
      category,
      priority,
      status,
      created_by,
      metadata
    ) values (
      'AUD-051-OWN-' || upper(suffix),
      own_hotel_id,
      'Audit 051 own-hotel ticket',
      'Reversible support-ticket visibility test.',
      'technical',
      'normal',
      'open',
      owner_user_id,
      jsonb_build_object('audit', '051', 'suffix', suffix)
    )
    returning id into ticket_own_id;

    insert into public.support_tickets (
      ticket_number,
      hotel_id,
      subject,
      description,
      category,
      priority,
      status,
      created_by,
      metadata
    ) values (
      'AUD-051-OTHER-' || upper(suffix),
      other_hotel_id,
      'Audit 051 cross-hotel ticket',
      'Reversible cross-tenant support visibility test.',
      'technical',
      'high',
      'open',
      platform_admin_user_id,
      jsonb_build_object('audit', '051', 'suffix', suffix)
    )
    returning id into ticket_other_id;

    insert into public.support_ticket_events (
      ticket_id,
      hotel_id,
      event_type,
      actor_user_id,
      message,
      new_status,
      details
    ) values (
      ticket_own_id,
      own_hotel_id,
      'ticket_created',
      owner_user_id,
      'Reversible Audit 051 event.',
      'open',
      jsonb_build_object('audit', '051')
    )
    returning id into ticket_event_id;

    support_ticket_foundation_ok :=
      ticket_own_id is not null
      and ticket_other_id is not null
      and ticket_event_id is not null;

    begin
      delete from public.support_ticket_events ste
      where ste.id = ticket_event_id;
    exception when others then
      support_ticket_event_immutable :=
        lower(sqlerrm) like '%append-only%'
        or lower(sqlerrm) like '%not permitted%';
    end;

    -- Time-bound support access and unique active-session protection.
    insert into public.support_access_sessions (
      hotel_id,
      platform_admin_user_id,
      reason,
      status,
      permissions,
      started_at,
      expires_at,
      metadata
    ) values (
      own_hotel_id,
      platform_admin_user_id,
      'Audit 051 reversible safe-support session.',
      'active',
      array['read_only']::text[],
      now(),
      now() + interval '1 hour',
      jsonb_build_object('audit', '051')
    )
    returning id into support_session_id;

    begin
      insert into public.support_access_sessions (
        hotel_id,
        platform_admin_user_id,
        reason,
        status,
        permissions,
        started_at,
        expires_at,
        metadata
      ) values (
        own_hotel_id,
        platform_admin_user_id,
        'Duplicate Audit 051 session must fail.',
        'active',
        array['read_only']::text[],
        now(),
        now() + interval '1 hour',
        jsonb_build_object('audit', '051', 'duplicate', true)
      );
    exception when unique_violation then
      support_access_unique_active := true;
    end;

    -- Webhook event idempotency.
    insert into public.webhook_events (
      provider,
      provider_event_id,
      event_type,
      processing_status,
      signature_valid,
      payload_hash,
      payload,
      headers,
      attempts,
      hotel_id,
      subscription_id,
      metadata
    ) values (
      'audit',
      'evt_051_' || suffix,
      'subscription.audit',
      'received',
      true,
      md5('audit-051-' || suffix),
      jsonb_build_object(
        'event', 'subscription.audit',
        'suffix', suffix
      ),
      jsonb_build_object(
        'x-audit-signature', 'valid'
      ),
      0,
      own_hotel_id,
      own_subscription_id,
      jsonb_build_object('audit', '051')
    )
    returning id into webhook_id;

    begin
      insert into public.webhook_events (
        provider,
        provider_event_id,
        event_type,
        processing_status,
        signature_valid,
        payload,
        headers,
        attempts,
        metadata
      ) values (
        'audit',
        'evt_051_' || suffix,
        'subscription.audit.duplicate',
        'received',
        true,
        jsonb_build_object('duplicate', true),
        '{}'::jsonb,
        0,
        jsonb_build_object('audit', '051')
      );
    exception when unique_violation then
      webhook_idempotency_unique := true;
    end;

    -- ------------------------------------------------------
    -- Platform Admin real authenticated RLS/write boundary.
    -- ------------------------------------------------------
    perform set_config(
      'request.jwt.claim.sub',
      platform_admin_user_id::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );

    execute 'set local role authenticated';
    role_switched := true;

    insert into public.announcements (
      scope,
      target_hotel_id,
      title,
      body,
      severity,
      status,
      starts_at,
      created_by,
      published_by,
      published_at,
      metadata
    ) values (
      'global',
      null,
      'Audit 051 global announcement ' || suffix,
      'Reversible global visibility test.',
      'info',
      'published',
      now() - interval '1 minute',
      platform_admin_user_id,
      platform_admin_user_id,
      now(),
      jsonb_build_object('audit', '051')
    )
    returning id into global_announcement_id;

    insert into public.announcements (
      scope,
      target_hotel_id,
      title,
      body,
      severity,
      status,
      starts_at,
      created_by,
      published_by,
      published_at,
      metadata
    ) values (
      'hotel',
      own_hotel_id,
      'Audit 051 own announcement ' || suffix,
      'Reversible own-hotel visibility test.',
      'success',
      'published',
      now() - interval '1 minute',
      platform_admin_user_id,
      platform_admin_user_id,
      now(),
      jsonb_build_object('audit', '051')
    )
    returning id into own_announcement_id;

    insert into public.announcements (
      scope,
      target_hotel_id,
      title,
      body,
      severity,
      status,
      starts_at,
      created_by,
      published_by,
      published_at,
      metadata
    ) values (
      'hotel',
      other_hotel_id,
      'Audit 051 other announcement ' || suffix,
      'Reversible cross-hotel visibility test.',
      'warning',
      'published',
      now() - interval '1 minute',
      platform_admin_user_id,
      platform_admin_user_id,
      now(),
      jsonb_build_object('audit', '051')
    )
    returning id into other_announcement_id;

    platform_admin_announcement_write :=
      global_announcement_id is not null
      and own_announcement_id is not null
      and other_announcement_id is not null;

    insert into public.subscription_plan_prices (
      plan_id,
      provider,
      billing_cycle,
      currency_code,
      amount_minor,
      status,
      metadata,
      created_by,
      updated_by
    ) values (
      own_plan_id,
      'audit-051-' || suffix,
      'one_time',
      'INR',
      1,
      'draft',
      jsonb_build_object('audit', '051'),
      platform_admin_user_id,
      platform_admin_user_id
    )
    returning id into admin_plan_price_id;

    platform_admin_plan_price_write :=
      admin_plan_price_id is not null;

    platform_admin_global_visibility :=
      (
        select count(*) = 2
        from public.support_tickets st
        where st.id in (ticket_own_id, ticket_other_id)
      )
      and exists (
        select 1
        from public.webhook_events we
        where we.id = webhook_id
      )
      and exists (
        select 1
        from public.support_access_sessions sas
        where sas.id = support_session_id
      )
      and (
        select count(*) = 3
        from public.announcements a
        where a.id in (
          global_announcement_id,
          own_announcement_id,
          other_announcement_id
        )
      );

    execute 'reset role';
    role_switched := false;

    -- ------------------------------------------------------
    -- Real non-platform owner tenant isolation.
    -- ------------------------------------------------------
    perform set_config(
      'request.jwt.claim.sub',
      owner_user_id::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );

    execute 'set local role authenticated';
    role_switched := true;

    owner_own_subscription_events := exists (
      select 1
      from public.subscription_events se
      where se.hotel_id = own_hotel_id
        and se.id = generated_subscription_event_id
    );

    owner_cross_subscription_events_blocked :=
      (
        select count(*) = 0
        from public.subscription_events se
        where se.hotel_id = other_hotel_id
      );

    owner_own_usage_visible := exists (
      select 1
      from public.usage_counters uc
      where uc.hotel_id = own_hotel_id
        and uc.metric_key = 'rooms'
    );

    owner_cross_usage_blocked :=
      (
        select count(*) = 0
        from public.usage_counters uc
        where uc.hotel_id = other_hotel_id
      );

    owner_own_support_visible := exists (
      select 1
      from public.support_tickets st
      where st.id = ticket_own_id
    );

    owner_cross_support_blocked :=
      not exists (
        select 1
        from public.support_tickets st
        where st.id = ticket_other_id
      );

    owner_announcement_visibility :=
      exists (
        select 1
        from public.announcements a
        where a.id = global_announcement_id
      )
      and exists (
        select 1
        from public.announcements a
        where a.id = own_announcement_id
      );

    owner_other_announcement_blocked :=
      not exists (
        select 1
        from public.announcements a
        where a.id = other_announcement_id
      );

    owner_plan_prices_visible := exists (
      select 1
      from public.subscription_plan_prices spp
      where spp.plan_id = own_plan_id
        and spp.provider = 'manual'
        and spp.status = 'active'
    );

    owner_webhook_visibility_blocked :=
      not exists (
        select 1
        from public.webhook_events we
        where we.id = webhook_id
      );

    begin
      insert into public.support_tickets (
        ticket_number,
        hotel_id,
        subject,
        description,
        created_by
      ) values (
        'AUD-051-DIRECT-' || upper(suffix),
        own_hotel_id,
        'Direct browser insert must fail',
        'Support creation must use a future authorized RPC.',
        owner_user_id
      );
    exception when others then
      owner_support_insert_blocked :=
        lower(sqlerrm) like '%permission denied%'
        or lower(sqlerrm) like '%row-level security%';
    end;

    begin
      insert into public.subscription_plan_prices (
        plan_id,
        provider,
        billing_cycle,
        currency_code,
        amount_minor,
        status,
        metadata,
        created_by
      ) values (
        own_plan_id,
        'owner-denied-' || suffix,
        'one_time',
        'INR',
        1,
        'draft',
        jsonb_build_object('audit', '051'),
        owner_user_id
      );
    exception when others then
      owner_plan_price_insert_blocked :=
        lower(sqlerrm) like '%permission denied%'
        or lower(sqlerrm) like '%row-level security%';
    end;

    execute 'reset role';
    role_switched := false;

    -- ------------------------------------------------------
    -- Anonymous blocking through the real anon role.
    -- ------------------------------------------------------
    perform set_config(
      'request.jwt.claim.sub',
      '',
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'anon',
      true
    );

    execute 'set local role anon';
    role_switched := true;

    begin
      perform 1
      from public.subscription_events
      limit 1;
    exception when others then
      anon_subscription_events_blocked :=
        lower(sqlerrm) like '%permission denied%';
    end;

    begin
      perform 1
      from public.usage_counters
      limit 1;

      anon_usage_support_webhook_blocked := false;
    exception when others then
      anon_usage_support_webhook_blocked :=
        lower(sqlerrm) like '%permission denied%';
    end;

    if anon_usage_support_webhook_blocked then
      begin
        perform 1
        from public.support_tickets
        limit 1;

        anon_usage_support_webhook_blocked := false;
      exception when others then
        anon_usage_support_webhook_blocked :=
          lower(sqlerrm) like '%permission denied%';
      end;
    end if;

    if anon_usage_support_webhook_blocked then
      begin
        perform 1
        from public.webhook_events
        limit 1;

        anon_usage_support_webhook_blocked := false;
      exception when others then
        anon_usage_support_webhook_blocked :=
          lower(sqlerrm) like '%permission denied%';
      end;
    end if;

    execute 'reset role';
    role_switched := false;

    -- Roll back all synthetic records and reversible subscription change.
    raise exception using
      errcode = 'P7920',
      message =
        'StayQR Day 9 Migration 020 runtime acceptance rollback';
  exception
    when sqlstate 'P7920' then
      null;
    when others then
      if role_switched then
        begin
          execute 'reset role';
        exception when others then
          null;
        end;
        role_switched := false;
      end if;

      audit_failure := format(
        'Audit harness failure [%s] %s',
        sqlstate,
        sqlerrm
      );
  end;

  -- ------------------------------------------------------------------------
  -- Confirm production counts and synthetic cleanup.
  -- ------------------------------------------------------------------------
  select count(*) into after_subscription_event_count
  from public.subscription_events;
  select count(*) into after_usage_count
  from public.usage_counters;
  select count(*) into after_ticket_count
  from public.support_tickets;
  select count(*) into after_ticket_event_count
  from public.support_ticket_events;
  select count(*) into after_announcement_count
  from public.announcements;
  select count(*) into after_support_session_count
  from public.support_access_sessions;
  select count(*) into after_webhook_count
  from public.webhook_events;
  select count(*) into after_plan_price_count
  from public.subscription_plan_prices;

  production_counts_unchanged :=
    before_subscription_event_count =
      after_subscription_event_count
    and before_usage_count = after_usage_count
    and before_ticket_count = after_ticket_count
    and before_ticket_event_count = after_ticket_event_count
    and before_announcement_count = after_announcement_count
    and before_support_session_count =
      after_support_session_count
    and before_webhook_count = after_webhook_count
    and before_plan_price_count = after_plan_price_count;

  synthetic_records_rolled_back :=
    not exists (
      select 1
      from public.support_tickets st
      where st.ticket_number in (
        'AUD-051-OWN-' || upper(suffix),
        'AUD-051-OTHER-' || upper(suffix),
        'AUD-051-DIRECT-' || upper(suffix)
      )
    )
    and not exists (
      select 1
      from public.webhook_events we
      where we.provider = 'audit'
        and we.provider_event_id = 'evt_051_' || suffix
    )
    and not exists (
      select 1
      from public.announcements a
      where a.metadata ->> 'audit' = '051'
        and a.title like '%' || suffix
    )
    and not exists (
      select 1
      from public.subscription_plan_prices spp
      where spp.provider in (
        'audit-051-' || suffix,
        'owner-denied-' || suffix
      )
    )
    and not exists (
      select 1
      from public.support_access_sessions sas
      where sas.metadata ->> 'audit' = '051'
    )
    and not exists (
      select 1
      from public.subscription_events se
      where se.event_source = 'audit_051'
        and se.new_record
          ->> 'provider_status'
          = 'audit-051-' || suffix
    );

  -- ------------------------------------------------------------------------
  -- Final 32-row acceptance result.
  -- ------------------------------------------------------------------------
  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '01_runtime_identities_resolved',
    'passed', resolved_identities,
    'details', format(
      'Platform Admin=%s; owner=%s; own hotel=%s; comparison hotel=%s.',
      coalesce(platform_admin_email, 'NOT FOUND'),
      coalesce(owner_email, 'NOT FOUND'),
      coalesce(own_hotel_name, 'NOT FOUND'),
      coalesce(other_hotel_name, 'NOT FOUND')
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '02_vd_complimentary_reconciliation',
    'passed', vd_reconciliation_ok,
    'details',
      'VD Stay Inn has one capacity-safe active complimentary subscription with zero MRR.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '03_apex_expiry_reconciliation',
    'passed', apex_reconciliation_ok,
    'details',
      'Apex subscription and cached hotel state are both expired.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '04_reconciliation_snapshots_archived',
    'passed', reconciliation_archive_ok,
    'details',
      'Both pre-migration production records have private JSON snapshots.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '05_reconciliation_events_logged',
    'passed', migration_events_ok,
    'details',
      'VD subscription creation and Apex active-to-expired transition are immutable migration events.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '06_plan_price_mapping_coverage',
    'passed', plan_price_coverage_ok,
    'details',
      'Every plan has a provider-neutral monthly price mapping.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '07_seeded_usage_accuracy',
    'passed', usage_seed_accuracy_ok,
    'details',
      'Seeded room and active-staff usage matches authoritative tenant tables.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '08_usage_refresh_runtime',
    'passed', usage_refresh_ok,
    'details',
      'Internal usage refresh recomputed the selected hotel correctly.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '09_subscription_update_event_generated',
    'passed', subscription_event_generated,
    'details',
      'A reversible provider-state update generated an immutable subscription event.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '10_subscription_event_immutable',
    'passed', subscription_event_immutable,
    'details',
      'A subscription event could not be updated after insertion.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '11_support_ticket_foundation_runtime',
    'passed', support_ticket_foundation_ok,
    'details',
      'Own-tenant and cross-tenant support tickets plus an event were created inside the reversible test.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '12_support_ticket_event_immutable',
    'passed', support_ticket_event_immutable,
    'details',
      'A support ticket event could not be deleted.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '13_single_active_support_session',
    'passed', support_access_unique_active,
    'details',
      'A second active support session for the same Platform Admin and hotel was rejected.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '14_webhook_event_idempotency',
    'passed', webhook_idempotency_unique,
    'details',
      'A duplicate provider plus provider_event_id receipt was rejected.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '15_platform_admin_announcement_write',
    'passed', platform_admin_announcement_write,
    'details',
      'The real authenticated Platform Admin created global and hotel-targeted announcements.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '16_platform_admin_plan_price_write',
    'passed', platform_admin_plan_price_write,
    'details',
      'The real authenticated Platform Admin created a reversible provider-price mapping.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '17_platform_admin_global_visibility',
    'passed', platform_admin_global_visibility,
    'details',
      'The Platform Admin could see support tickets, webhook receipt, support session and announcements globally.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '18_owner_own_subscription_events',
    'passed', owner_own_subscription_events,
    'details',
      'The hotel owner could read their own subscription event.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '19_owner_cross_subscription_events_blocked',
    'passed', owner_cross_subscription_events_blocked,
    'details',
      'The hotel owner received zero subscription events from another hotel.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '20_owner_own_usage_visible',
    'passed', owner_own_usage_visible,
    'details',
      'The hotel owner could read their own usage counters.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '21_owner_cross_usage_blocked',
    'passed', owner_cross_usage_blocked,
    'details',
      'The hotel owner received zero usage rows from another hotel.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '22_owner_own_support_visible',
    'passed', owner_own_support_visible,
    'details',
      'The hotel owner could read the support ticket belonging to their hotel.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '23_owner_cross_support_blocked',
    'passed', owner_cross_support_blocked,
    'details',
      'The hotel owner could not read the other hotel support ticket.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '24_owner_announcement_visibility',
    'passed', owner_announcement_visibility,
    'details',
      'The owner could read active global and own-hotel announcements.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '25_owner_other_announcement_blocked',
    'passed', owner_other_announcement_blocked,
    'details',
      'The owner could not read another hotel targeted announcement.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '26_owner_active_plan_prices_visible',
    'passed', owner_plan_prices_visible,
    'details',
      'The owner could read active public plan-price mappings.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '27_owner_direct_support_insert_blocked',
    'passed', owner_support_insert_blocked,
    'details',
      'Direct browser insertion into support_tickets was blocked; a future RPC is required.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '28_owner_plan_price_write_blocked',
    'passed', owner_plan_price_insert_blocked,
    'details',
      'The owner could not create provider plan-price records.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '29_owner_webhook_visibility_blocked',
    'passed', owner_webhook_visibility_blocked,
    'details',
      'Webhook receipts remained visible only to the Platform Admin.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '30_anonymous_day9_tables_blocked',
    'passed',
      anon_subscription_events_blocked
      and anon_usage_support_webhook_blocked,
    'details',
      'The real anon role could read neither subscription events, usage, support tickets nor webhook receipts.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '31_production_counts_and_rollback',
    'passed',
      production_counts_unchanged
      and synthetic_records_rolled_back,
    'details', format(
      'Events %s→%s; usage %s→%s; tickets %s→%s; ticket events %s→%s; announcements %s→%s; support sessions %s→%s; webhooks %s→%s; plan prices %s→%s.',
      before_subscription_event_count,
      after_subscription_event_count,
      before_usage_count,
      after_usage_count,
      before_ticket_count,
      after_ticket_count,
      before_ticket_event_count,
      after_ticket_event_count,
      before_announcement_count,
      after_announcement_count,
      before_support_session_count,
      after_support_session_count,
      before_webhook_count,
      after_webhook_count,
      before_plan_price_count,
      after_plan_price_count
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '32_day9_foundation_runtime_ready',
    'passed',
      vd_reconciliation_ok
      and apex_reconciliation_ok
      and migration_events_ok
      and usage_seed_accuracy_ok
      and subscription_event_generated
      and subscription_event_immutable
      and support_ticket_event_immutable
      and webhook_idempotency_unique
      and platform_admin_global_visibility
      and owner_cross_subscription_events_blocked
      and owner_cross_usage_blocked
      and owner_cross_support_blocked
      and owner_other_announcement_blocked
      and anon_subscription_events_blocked
      and anon_usage_support_webhook_blocked
      and production_counts_unchanged
      and synthetic_records_rolled_back,
    'details', coalesce(
      audit_failure,
      'Migration 020 commercial, event, usage, support and webhook foundation passed runtime acceptance.'
    )
  ));

  return query
  select
    item.test_name,
    item.passed,
    item.details
  from jsonb_to_recordset(results)
    as item(
      test_name text,
      passed boolean,
      details text
    )
  order by item.test_name;
exception when others then
  if role_switched then
    begin
      execute 'reset role';
    exception when others then
      null;
    end;
  end if;

  return query
  select
    '00_audit_harness_error'::text,
    false,
    format('[%s] %s', sqlstate, sqlerrm);
end;
$$;


ALTER FUNCTION "private"."run_day9_commercial_foundation_acceptance_20260728"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."run_day9_commercial_foundation_acceptance_20260728"() IS 'Reversible runtime acceptance REV2 for Day 9 Migration 020 reconciliation, immutable events, usage, support, announcements, safe support access, webhook idempotency and tenant isolation. Remove after evidence export.';



CREATE OR REPLACE FUNCTION "private"."run_day9_lifecycle_runtime_acceptance_20260728"() RETURNS TABLE("test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  platform_admin_user_id uuid;
  platform_admin_email text;
  owner_user_id uuid;
  owner_email text;
  owner_hotel_id uuid;
  owner_hotel_name text;
  comparison_hotel_id uuid;

  suffix text := left(replace(gen_random_uuid()::text, '-', ''), 12);
  contact_email_value text;
  request_id_value uuid := gen_random_uuid();

  plan_one_result jsonb;
  plan_two_result jsonb;
  plan_one_id uuid;
  plan_two_id uuid;

  bootstrap_result jsonb;
  hotel_id_value uuid;
  subscription_id_value uuid;
  owner_staff_id_value uuid;

  configure_result jsonb;
  import_result jsonb;
  usage_result jsonb;
  capacity_error text;
  trigger_limit_error text;

  extend_result_one jsonb;
  extend_result_two jsonb;
  paid_result_one jsonb;
  paid_result_two jsonb;
  suspend_result jsonb;
  reactivate_result jsonb;
  change_plan_result jsonb;
  renew_result jsonb;
  cancel_result jsonb;
  reconcile_result jsonb;
  dashboard_result jsonb;

  support_create_result jsonb;
  support_message_result jsonb;
  support_triage_result jsonb;
  support_ticket_id uuid;
  cross_support_error text;

  support_access_start_result jsonb;
  support_access_end_result jsonb;
  support_session_id uuid;
  announcement_result jsonb;
  announcement_id uuid;

  baseline_mrr_minor bigint := 0;
  expected_paid_mrr_minor bigint := 19900;

  identities_resolved boolean := false;
  plan_create_ok boolean := false;
  plan_price_rows_ok boolean := false;
  fresh_bootstrap_ok boolean := false;
  bootstrap_owner_ok boolean := false;
  normalized_trial_contract_ok boolean := false;
  bootstrap_defaults_ok boolean := false;
  inventory_config_ok boolean := false;
  room_import_ok boolean := false;
  usage_rpc_ok boolean := false;
  capacity_rpc_blocked boolean := false;
  room_trigger_blocked boolean := false;
  trial_extension_ok boolean := false;
  trial_extension_idempotent boolean := false;
  paid_activation_ok boolean := false;
  paid_activation_idempotent boolean := false;
  dashboard_mrr_ok boolean := false;
  suspension_ok boolean := false;
  reactivation_ok boolean := false;
  plan_change_ok boolean := false;
  renewal_ok boolean := false;
  scheduled_cancel_ok boolean := false;
  expiry_reconciliation_ok boolean := false;
  lifecycle_events_ok boolean := false;
  support_create_ok boolean := false;
  support_message_ok boolean := false;
  cross_hotel_support_blocked boolean := false;
  support_triage_ok boolean := false;
  safe_support_start_ok boolean := false;
  safe_support_end_ok boolean := false;
  support_access_events_ok boolean := false;
  announcement_ok boolean := false;
  owner_announcement_visible boolean := false;
  owner_dashboard_blocked boolean := false;
  owner_lifecycle_blocked boolean := false;
  anon_paid_blocked boolean := false;
  anon_support_blocked boolean := false;
  anon_dashboard_blocked boolean := false;
  current_subscription_unique boolean := false;
  day8_rpcs_preserved boolean := false;
  production_counts_unchanged boolean := false;
  synthetic_records_rolled_back boolean := false;
  final_runtime_ready boolean := false;

  role_switched boolean := false;
  audit_failure text;

  before_hotels bigint;
  before_plans bigint;
  before_plan_prices bigint;
  before_subscriptions bigint;
  before_subscription_events bigint;
  before_rooms bigint;
  before_room_types bigint;
  before_rate_plans bigint;
  before_usage bigint;
  before_tickets bigint;
  before_ticket_events bigint;
  before_support_sessions bigint;
  before_support_access_events bigint;
  before_announcements bigint;

  after_hotels bigint;
  after_plans bigint;
  after_plan_prices bigint;
  after_subscriptions bigint;
  after_subscription_events bigint;
  after_rooms bigint;
  after_room_types bigint;
  after_rate_plans bigint;
  after_usage bigint;
  after_tickets bigint;
  after_ticket_events bigint;
  after_support_sessions bigint;
  after_support_access_events bigint;
  after_announcements bigint;

  results jsonb := '[]'::jsonb;
begin
  -- ------------------------------------------------------------------------
  -- Resolve real identities used only for authorization-boundary testing.
  -- ------------------------------------------------------------------------
  select pa.user_id, lower(au.email)
  into platform_admin_user_id, platform_admin_email
  from public.platform_admins pa
  join auth.users au on au.id = pa.user_id
  where pa.status = 'active'
    and au.email is not null
    and coalesce(
      au.banned_until,
      '-infinity'::timestamptz
    ) <= now()
  order by pa.created_at, pa.user_id
  limit 1;

  select
    s.auth_user_id,
    lower(s.email),
    h.id,
    h.hotel_name
  into
    owner_user_id,
    owner_email,
    owner_hotel_id,
    owner_hotel_name
  from public.staff s
  join public.hotels h on h.id = s.hotel_id
  where h.slug = 'stayqr-day-8-test-hotel'
    and s.status = 'active'
    and s.auth_user_id is not null
    and lower(replace(trim(s.role::text), ' ', '_')) = 'owner'
    and not exists (
      select 1
      from public.platform_admins pa
      where pa.user_id = s.auth_user_id
        and pa.status = 'active'
    )
  order by s.created_at, s.id
  limit 1;

  select h.id
  into comparison_hotel_id
  from public.hotels h
  where h.id <> owner_hotel_id
  order by
    case when h.slug = 'vd-stay-inn' then 0 else 1 end,
    h.created_at,
    h.id
  limit 1;

  identities_resolved :=
    platform_admin_user_id is not null
    and platform_admin_email is not null
    and owner_user_id is not null
    and owner_email is not null
    and owner_hotel_id is not null
    and comparison_hotel_id is not null;

  select coalesce(
    round(
      sum(
        case hs.billing_cycle
          when 'monthly' then hs.amount_minor
          when 'annual' then hs.amount_minor / 12.0
          else 0
        end
      )
    ),
    0
  )::bigint
  into baseline_mrr_minor
  from public.hotel_subscriptions hs
  where hs.status = 'active'
    and hs.billing_mode = 'paid'
    and hs.amount_minor > 0;

  select count(*) into before_hotels from public.hotels;
  select count(*) into before_plans from public.subscription_plans;
  select count(*) into before_plan_prices
  from public.subscription_plan_prices;
  select count(*) into before_subscriptions
  from public.hotel_subscriptions;
  select count(*) into before_subscription_events
  from public.subscription_events;
  select count(*) into before_rooms from public.rooms;
  select count(*) into before_room_types from public.room_types;
  select count(*) into before_rate_plans from public.rate_plans;
  select count(*) into before_usage from public.usage_counters;
  select count(*) into before_tickets from public.support_tickets;
  select count(*) into before_ticket_events
  from public.support_ticket_events;
  select count(*) into before_support_sessions
  from public.support_access_sessions;
  select count(*) into before_support_access_events
  from public.support_access_events;
  select count(*) into before_announcements
  from public.announcements;

  contact_email_value :=
    'day9-runtime-' || suffix || '@stayqr.test';

  -- ------------------------------------------------------------------------
  -- Reversible runtime acceptance.
  -- ------------------------------------------------------------------------
  begin
    if not identities_resolved then
      raise exception
        'Required Platform Admin and real hotel-owner identities were not found.';
    end if;

    -- ------------------------------------------------------
    -- Platform Admin creates two reversible plans.
    -- ------------------------------------------------------
    perform set_config(
      'request.jwt.claim.sub',
      platform_admin_user_id::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );

    execute 'set local role authenticated';
    role_switched := true;

    plan_one_result := public.save_subscription_plan(
      jsonb_build_object(
        'plan_name', 'Audit 052 Starter ' || suffix,
        'plan_code', 'AUD052A' || upper(left(suffix, 8)),
        'price_monthly', 199,
        'price_annual', 1990,
        'max_rooms', 2,
        'max_staff', 1,
        'max_properties', 1,
        'max_storage_mb', 512,
        'trial_days', 14,
        'currency_code', 'INR',
        'features', jsonb_build_array(
          'Audit 052 starter feature'
        ),
        'is_public', true,
        'status', 'active'
      )
    );

    plan_two_result := public.save_subscription_plan(
      jsonb_build_object(
        'plan_name', 'Audit 052 Growth ' || suffix,
        'plan_code', 'AUD052B' || upper(left(suffix, 8)),
        'price_monthly', 299,
        'price_annual', 2990,
        'max_rooms', 3,
        'max_staff', 2,
        'max_properties', 1,
        'max_storage_mb', 1024,
        'trial_days', 14,
        'currency_code', 'INR',
        'features', jsonb_build_array(
          'Audit 052 growth feature'
        ),
        'is_public', true,
        'status', 'active'
      )
    );

    plan_one_id :=
      (plan_one_result -> 'plan' ->> 'id')::uuid;
    plan_two_id :=
      (plan_two_result -> 'plan' ->> 'id')::uuid;

    plan_create_ok :=
      plan_one_id is not null
      and plan_two_id is not null
      and plan_one_id <> plan_two_id;

    plan_price_rows_ok :=
      (
        select count(*) = 2
        from public.subscription_plan_prices spp
        where spp.plan_id = plan_one_id
          and spp.provider = 'manual'
          and spp.billing_cycle in ('monthly', 'annual')
      )
      and (
        select count(*) = 2
        from public.subscription_plan_prices spp
        where spp.plan_id = plan_two_id
          and spp.provider = 'manual'
          and spp.billing_cycle in ('monthly', 'annual')
      );

    -- ------------------------------------------------------
    -- Fresh Day 8 bootstrap after Day 9 limit triggers.
    -- ------------------------------------------------------
    bootstrap_result := public.bootstrap_hotel_onboarding(
      jsonb_build_object(
        'request_id', request_id_value,
        'hotel_name', 'StayQR Day 9 Runtime Hotel ' || suffix,
        'owner_name', 'Day 9 Runtime Owner',
        'contact_email', contact_email_value,
        'phone', '9999999995',
        'address', 'Temporary Day 9 runtime address',
        'city', 'Nagpur',
        'state', 'Maharashtra',
        'location', 'Nagpur, Maharashtra',
        'timezone', 'Asia/Kolkata',
        'currency_code', 'INR',
        'hotel_slug',
          'stayqr-day9-runtime-' || suffix,
        'plan_id', plan_one_id,
        'trial_days', 14,
        'default_tax_percent', 12,
        'prices_include_tax', false,
        'checkin_time', '14:00',
        'checkout_time', '11:00'
      )
    );

    hotel_id_value :=
      (bootstrap_result ->> 'hotel_id')::uuid;
    subscription_id_value :=
      (
        bootstrap_result
        -> 'trial'
        ->> 'subscription_id'
      )::uuid;
    owner_staff_id_value :=
      (bootstrap_result ->> 'owner_staff_id')::uuid;

    fresh_bootstrap_ok :=
      hotel_id_value is not null
      and subscription_id_value is not null
      and owner_staff_id_value is not null
      and coalesce(
        (bootstrap_result ->> 'idempotent')::boolean,
        true
      ) = false;

    bootstrap_owner_ok := exists (
      select 1
      from public.staff s
      where s.id = owner_staff_id_value
        and s.hotel_id = hotel_id_value
        and s.auth_user_id = platform_admin_user_id
        and s.status = 'active'
        and lower(replace(trim(s.role::text), ' ', '_')) = 'owner'
    );

    normalized_trial_contract_ok := exists (
      select 1
      from public.hotel_subscriptions hs
      where hs.id = subscription_id_value
        and hs.hotel_id = hotel_id_value
        and hs.plan_id = plan_one_id
        and hs.status = 'trialing'
        and hs.billing_mode = 'trial'
        and hs.billing_cycle = 'none'
        and hs.amount_minor = 0
        and hs.provider_status = 'trialing'
        and hs.current_period_start is not null
        and hs.current_period_end > hs.current_period_start
    );

    bootstrap_defaults_ok :=
      exists (
        select 1
        from public.hotel_settings hs
        where hs.hotel_id = hotel_id_value
      )
      and exists (
        select 1
        from public.floors f
        where f.hotel_id = hotel_id_value
          and upper(trim(f.code)) = 'DEFAULT'
      )
      and exists (
        select 1
        from public.invoice_number_sequences ins
        where ins.hotel_id = hotel_id_value
      )
      and exists (
        select 1
        from public.amenities a
        where a.hotel_id = hotel_id_value
          and a.is_active
      )
      and exists (
        select 1
        from public.service_request_types srt
        where srt.hotel_id = hotel_id_value
          and srt.is_active
      );

    configure_result := public.configure_hotel_inventory(
      hotel_id_value,
      jsonb_build_object(
        'room_types',
        jsonb_build_array(
          jsonb_build_object(
            'name', 'Audit Standard Room',
            'code', 'STD',
            'base_occupancy', 1,
            'max_adults', 2,
            'max_children', 1,
            'max_occupancy', 3,
            'base_rate', 1999,
            'is_active', true
          )
        ),
        'rate_plans',
        jsonb_build_array(
          jsonb_build_object(
            'name', 'Audit Standard Rate',
            'code', 'STD-BAR',
            'room_type_code', 'STD',
            'meal_plan', 'room_only',
            'currency_code', 'INR',
            'base_rate', 1999,
            'minimum_stay', 1,
            'is_refundable', true,
            'is_active', true
          )
        )
      )
    );

    inventory_config_ok :=
      coalesce(
        (
          configure_result
          -> 'room_types'
          ->> 'inserted'
        )::integer,
        0
      ) = 1
      and coalesce(
        (
          configure_result
          -> 'rate_plans'
          ->> 'inserted'
        )::integer,
        0
      ) = 1;

    import_result := public.import_hotel_rooms(
      hotel_id_value,
      jsonb_build_array(
        jsonb_build_object(
          'room_number', '901',
          'room_type_code', 'STD',
          'floor_code', 'DEFAULT',
          'status', 'available'
        ),
        jsonb_build_object(
          'room_number', '902',
          'room_type_code', 'STD',
          'floor_code', 'DEFAULT',
          'status', 'available'
        )
      )
    );

    room_import_ok :=
      coalesce(
        (import_result ->> 'inserted')::integer,
        0
      ) = 2
      and (
        select count(*) = 2
        from public.rooms r
        where r.hotel_id = hotel_id_value
          and r.room_number in ('901', '902')
      );

    usage_result := public.get_hotel_subscription_usage(
      hotel_id_value
    );

    usage_rpc_ok :=
      coalesce((usage_result ->> 'rooms')::integer, -1) = 2
      and coalesce(
        (usage_result ->> 'active_staff')::integer,
        -1
      ) = 1
      and coalesce(
        (usage_result ->> 'room_limit')::integer,
        -1
      ) = 2
      and coalesce(
        (usage_result ->> 'staff_limit')::integer,
        -1
      ) = 1;

    begin
      perform public.assert_subscription_capacity(
        hotel_id_value,
        'rooms',
        1
      );
    exception when others then
      capacity_error := sqlerrm;
      capacity_rpc_blocked :=
        lower(sqlerrm) like '%room limit exceeded%';
    end;

    begin
      perform public.import_hotel_rooms(
        hotel_id_value,
        jsonb_build_array(
          jsonb_build_object(
            'room_number', '903',
            'room_type_code', 'STD',
            'floor_code', 'DEFAULT',
            'status', 'available'
          )
        )
      );
    exception when others then
      trigger_limit_error := sqlerrm;
      room_trigger_blocked :=
        lower(sqlerrm) like '%room limit exceeded%';
    end;

    -- ------------------------------------------------------
    -- Trial extension and idempotency.
    -- ------------------------------------------------------
    extend_result_one := public.extend_hotel_trial(
      hotel_id_value,
      7,
      'Audit 052 reversible extension.',
      'audit052:extend:' || suffix
    );

    extend_result_two := public.extend_hotel_trial(
      hotel_id_value,
      7,
      'Audit 052 repeated extension.',
      'audit052:extend:' || suffix
    );

    trial_extension_ok :=
      (extend_result_one ->> 'status') = 'trialing'
      and coalesce(
        (extend_result_one ->> 'extension_days')::integer,
        0
      ) = 7;

    trial_extension_idempotent :=
      (extend_result_two ->> 'subscription_id')::uuid
        = subscription_id_value
      and coalesce(
        (extend_result_two ->> 'idempotent')::boolean,
        false
      )
      and extend_result_two ->> 'trial_ends_at'
        = extend_result_one ->> 'trial_ends_at';

    -- ------------------------------------------------------
    -- Trial-to-paid conversion and idempotency.
    -- ------------------------------------------------------
    paid_result_one := public.activate_paid_subscription(
      hotel_id_value,
      jsonb_build_object(
        'plan_id', plan_one_id,
        'billing_cycle', 'monthly',
        'currency_code', 'INR',
        'amount_minor', expected_paid_mrr_minor,
        'provider', 'audit',
        'provider_customer_id',
          'cust_052_' || suffix,
        'provider_subscription_id',
          'sub_052_' || suffix,
        'provider_status', 'active',
        'current_period_start', now(),
        'current_period_end',
          now() + interval '30 days',
        'last_payment_at', now(),
        'idempotency_key',
          'audit052:paid:' || suffix,
        'provider_event_id',
          'evt_paid_052_' || suffix,
        'provider_metadata',
          jsonb_build_object('audit', '052')
      )
    );

    paid_result_two := public.activate_paid_subscription(
      hotel_id_value,
      jsonb_build_object(
        'plan_id', plan_one_id,
        'billing_cycle', 'monthly',
        'currency_code', 'INR',
        'amount_minor', expected_paid_mrr_minor,
        'provider', 'audit',
        'provider_subscription_id',
          'sub_052_' || suffix,
        'provider_status', 'active',
        'current_period_start', now(),
        'current_period_end',
          now() + interval '30 days',
        'idempotency_key',
          'audit052:paid:' || suffix,
        'provider_event_id',
          'evt_paid_052_' || suffix
      )
    );

    paid_activation_ok :=
      (paid_result_one ->> 'status') = 'active'
      and (paid_result_one ->> 'billing_mode') = 'paid'
      and coalesce(
        (paid_result_one ->> 'amount_minor')::bigint,
        0
      ) = expected_paid_mrr_minor
      and paid_result_one
        ->> 'provider_subscription_id'
        = 'sub_052_' || suffix;

    paid_activation_idempotent :=
      (paid_result_two ->> 'subscription_id')::uuid
        = subscription_id_value
      and coalesce(
        (paid_result_two ->> 'idempotent')::boolean,
        false
      );

    dashboard_result := public.get_super_admin_dashboard();

    dashboard_mrr_ok :=
      coalesce(
        (
          dashboard_result
          -> 'revenue'
          ->> 'mrr_minor'
        )::bigint,
        -1
      ) = baseline_mrr_minor + expected_paid_mrr_minor
      and coalesce(
        (
          dashboard_result
          -> 'subscriptions'
          ->> 'active_paid'
        )::integer,
        0
      ) >= 1;

    -- ------------------------------------------------------
    -- Suspension and recovery.
    -- ------------------------------------------------------
    suspend_result := public.suspend_hotel_subscription(
      hotel_id_value,
      'Audit 052 reversible suspension.',
      'audit052:suspend:' || suffix
    );

    suspension_ok :=
      (suspend_result ->> 'status') = 'suspended'
      and exists (
        select 1
        from public.hotels h
        where h.id = hotel_id_value
          and h.status = 'suspended'
          and h.subscription_status = 'suspended'
      );

    reactivate_result :=
      public.reactivate_hotel_subscription(
        hotel_id_value,
        'Audit 052 reversible recovery.',
        'audit052:reactivate:' || suffix
      );

    reactivation_ok :=
      (reactivate_result ->> 'status') = 'active'
      and exists (
        select 1
        from public.hotels h
        where h.id = hotel_id_value
          and h.status = 'active'
          and h.subscription_status = 'active'
      );

    -- ------------------------------------------------------
    -- Plan change and renewal.
    -- ------------------------------------------------------
    change_plan_result :=
      public.change_hotel_subscription_plan(
        hotel_id_value,
        jsonb_build_object(
          'plan_id', plan_two_id,
          'amount_minor', 29900,
          'currency_code', 'INR',
          'reason',
            'Audit 052 reversible upgrade.',
          'idempotency_key',
            'audit052:change-plan:' || suffix
        )
      );

    plan_change_ok :=
      (change_plan_result ->> 'old_plan_id')::uuid
        = plan_one_id
      and (change_plan_result ->> 'plan_id')::uuid
        = plan_two_id
      and coalesce(
        (change_plan_result ->> 'amount_minor')::bigint,
        0
      ) = 29900;

    renew_result := public.renew_hotel_subscription(
      hotel_id_value,
      jsonb_build_object(
        'billing_cycle', 'monthly',
        'currency_code', 'INR',
        'amount_minor', 29900,
        'provider', 'audit',
        'provider_status', 'active',
        'provider_subscription_id',
          'sub_052_' || suffix,
        'current_period_start',
          now() + interval '30 days',
        'current_period_end',
          now() + interval '60 days',
        'last_payment_at', now(),
        'idempotency_key',
          'audit052:renew:' || suffix,
        'provider_event_id',
          'evt_renew_052_' || suffix
      )
    );

    renewal_ok :=
      (renew_result ->> 'status') = 'active'
      and coalesce(
        (renew_result ->> 'amount_minor')::bigint,
        0
      ) = 29900
      and (
        renew_result ->> 'current_period_end'
      )::timestamptz
        > (
          renew_result ->> 'current_period_start'
        )::timestamptz;

    -- ------------------------------------------------------
    -- Scheduled cancellation and expiry reconciliation.
    -- ------------------------------------------------------
    cancel_result := public.cancel_hotel_subscription(
      hotel_id_value,
      'Audit 052 scheduled cancellation.',
      false,
      'audit052:cancel:' || suffix
    );

    scheduled_cancel_ok :=
      (cancel_result ->> 'status') = 'active'
      and coalesce(
        (
          cancel_result
          ->> 'cancel_at_period_end'
        )::boolean,
        false
      );

    execute 'reset role';
    role_switched := false;

    -- Move only the synthetic current period into the past so the real
    -- reconciliation RPC can complete the scheduled cancellation.
    perform set_config(
      'stayqr.subscription_event_source',
      'audit_052_prepare_expiry',
      true
    );

    update public.hotel_subscriptions hs
    set
      start_date = now() - interval '2 days',
      end_date = now() - interval '1 day',
      current_period_start = now() - interval '2 days',
      current_period_end = now() - interval '1 day',
      grace_ends_at = null,
      updated_at = now()
    where hs.id = subscription_id_value;

    perform set_config(
      'request.jwt.claim.sub',
      platform_admin_user_id::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );

    execute 'set local role authenticated';
    role_switched := true;

    reconcile_result :=
      public.reconcile_expired_subscriptions(now());

    expiry_reconciliation_ok :=
      coalesce(
        (
          reconcile_result
          ->> 'scheduled_cancellations_completed'
        )::integer,
        0
      ) >= 1
      and exists (
        select 1
        from public.hotel_subscriptions hs
        where hs.id = subscription_id_value
          and hs.status = 'cancelled'
      )
      and exists (
        select 1
        from public.hotels h
        where h.id = hotel_id_value
          and h.status = 'suspended'
          and h.subscription_status = 'cancelled'
      );

    lifecycle_events_ok :=
      not exists (
        select required_event
        from unnest(array[
          'trial_extended',
          'paid_subscription_activated',
          'hotel_suspended',
          'hotel_reactivated',
          'subscription_plan_changed',
          'subscription_renewed',
          'subscription_cancellation_scheduled'
        ]::text[]) required_event
        where not exists (
          select 1
          from public.subscription_events se
          where se.hotel_id = hotel_id_value
            and se.event_type = required_event
        )
      );

    -- ------------------------------------------------------
    -- Real hotel-owner support workflow.
    -- ------------------------------------------------------
    execute 'reset role';
    role_switched := false;

    perform set_config(
      'request.jwt.claim.sub',
      owner_user_id::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );

    execute 'set local role authenticated';
    role_switched := true;

    support_create_result := public.create_support_ticket(
      owner_hotel_id,
      'Audit 052 support ticket ' || suffix,
      'Reversible Day 9 support ticket runtime acceptance.',
      'technical',
      'high'
    );

    support_ticket_id :=
      (
        support_create_result
        -> 'ticket'
        ->> 'id'
      )::uuid;

    support_create_ok :=
      support_ticket_id is not null
      and exists (
        select 1
        from public.support_tickets st
        where st.id = support_ticket_id
          and st.hotel_id = owner_hotel_id
          and st.status = 'open'
          and st.created_by = owner_user_id
      );

    support_message_result :=
      public.add_support_ticket_message(
        support_ticket_id,
        'Audit 052 owner follow-up message.'
      );

    support_message_ok :=
      (
        support_message_result
        ->> 'ticket_id'
      )::uuid = support_ticket_id
      and exists (
        select 1
        from public.support_ticket_events ste
        where ste.ticket_id = support_ticket_id
          and ste.event_type = 'message_added'
          and ste.actor_user_id = owner_user_id
      );

    begin
      perform public.create_support_ticket(
        comparison_hotel_id,
        'Cross-hotel ticket must fail',
        'This request must be rejected.',
        'technical',
        'normal'
      );
    exception when others then
      cross_support_error := sqlerrm;
      cross_hotel_support_blocked :=
        lower(sqlerrm) like '%access denied%';
    end;

    begin
      perform public.get_super_admin_dashboard();
    exception when others then
      owner_dashboard_blocked :=
        lower(sqlerrm) like '%platform admin access required%';
    end;

    begin
      perform public.suspend_hotel_subscription(
        comparison_hotel_id,
        'Owner must not suspend another hotel.',
        'audit052:owner-denied:' || suffix
      );
    exception when others then
      owner_lifecycle_blocked :=
        lower(sqlerrm) like '%platform admin access required%';
    end;

    execute 'reset role';
    role_switched := false;

    -- ------------------------------------------------------
    -- Platform Admin support triage, access and announcement.
    -- ------------------------------------------------------
    perform set_config(
      'request.jwt.claim.sub',
      platform_admin_user_id::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );

    execute 'set local role authenticated';
    role_switched := true;

    support_triage_result :=
      public.update_support_ticket_status(
        support_ticket_id,
        'resolved',
        'Audit 052 resolved by Platform Admin.',
        platform_admin_user_id
      );

    support_triage_ok :=
      (
        support_triage_result
        -> 'ticket'
        ->> 'status'
      ) = 'resolved'
      and exists (
        select 1
        from public.support_ticket_events ste
        where ste.ticket_id = support_ticket_id
          and ste.event_type = 'status_changed'
          and ste.new_status = 'resolved'
          and ste.actor_user_id = platform_admin_user_id
      );

    support_access_start_result :=
      public.start_safe_support_access(
        owner_hotel_id,
        'Audit 052 reversible support access.',
        30,
        array[
          'read_only',
          'ticket_support'
        ]::text[]
      );

    support_session_id :=
      (
        support_access_start_result
        -> 'session'
        ->> 'id'
      )::uuid;

    safe_support_start_ok :=
      support_session_id is not null
      and exists (
        select 1
        from public.support_access_sessions sas
        where sas.id = support_session_id
          and sas.status = 'active'
          and sas.expires_at > sas.started_at
      );

    support_access_end_result :=
      public.end_safe_support_access(
        support_session_id,
        'Audit 052 support work completed.'
      );

    safe_support_end_ok :=
      (
        support_access_end_result
        -> 'session'
        ->> 'status'
      ) = 'ended'
      and exists (
        select 1
        from public.support_access_sessions sas
        where sas.id = support_session_id
          and sas.status = 'ended'
          and sas.ended_at is not null
      );

    support_access_events_ok :=
      (
        select count(*) = 2
        from public.support_access_events sae
        where sae.session_id = support_session_id
          and sae.event_type in (
            'support_access_started',
            'support_access_ended'
          )
      );

    announcement_result :=
      public.save_platform_announcement(
        jsonb_build_object(
          'scope', 'hotel',
          'target_hotel_id', owner_hotel_id,
          'title',
            'Audit 052 announcement ' || suffix,
          'body',
            'Reversible Day 9 announcement runtime acceptance.',
          'severity', 'info',
          'status', 'published',
          'starts_at', now() - interval '1 minute',
          'ends_at', now() + interval '1 hour',
          'metadata',
            jsonb_build_object(
              'audit', '052',
              'suffix', suffix
            )
        )
      );

    announcement_id :=
      (
        announcement_result
        -> 'announcement'
        ->> 'id'
      )::uuid;

    announcement_ok :=
      announcement_id is not null
      and exists (
        select 1
        from public.announcements a
        where a.id = announcement_id
          and a.scope = 'hotel'
          and a.target_hotel_id = owner_hotel_id
          and a.status = 'published'
      );

    execute 'reset role';
    role_switched := false;

    perform set_config(
      'request.jwt.claim.sub',
      owner_user_id::text,
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'authenticated',
      true
    );

    execute 'set local role authenticated';
    role_switched := true;

    owner_announcement_visible := exists (
      select 1
      from public.announcements a
      where a.id = announcement_id
    );

    execute 'reset role';
    role_switched := false;

    -- ------------------------------------------------------
    -- Real anonymous blocking.
    -- ------------------------------------------------------
    perform set_config(
      'request.jwt.claim.sub',
      '',
      true
    );
    perform set_config(
      'request.jwt.claim.role',
      'anon',
      true
    );

    execute 'set local role anon';
    role_switched := true;

    begin
      perform public.activate_paid_subscription(
        hotel_id_value,
        '{}'::jsonb
      );
    exception when others then
      anon_paid_blocked :=
        lower(sqlerrm) like '%permission denied%';
    end;

    begin
      perform public.create_support_ticket(
        owner_hotel_id,
        'Anonymous ticket',
        'Must fail.',
        'general',
        'normal'
      );
    exception when others then
      anon_support_blocked :=
        lower(sqlerrm) like '%permission denied%';
    end;

    begin
      perform public.get_super_admin_dashboard();
    exception when others then
      anon_dashboard_blocked :=
        lower(sqlerrm) like '%permission denied%';
    end;

    execute 'reset role';
    role_switched := false;

    current_subscription_unique := not exists (
      select 1
      from (
        select hs.hotel_id
        from public.hotel_subscriptions hs
        where hs.status in (
          'trial',
          'trialing',
          'active',
          'past_due',
          'suspended'
        )
        group by hs.hotel_id
        having count(*) > 1
      ) duplicate_current
    );

    day8_rpcs_preserved :=
      to_regprocedure(
        'public.bootstrap_hotel_onboarding(jsonb)'
      ) is not null
      and to_regprocedure(
        'public.configure_hotel_inventory(uuid,jsonb)'
      ) is not null
      and to_regprocedure(
        'public.import_hotel_rooms(uuid,jsonb)'
      ) is not null
      and to_regprocedure(
        'public.get_hotel_onboarding_readiness(uuid)'
      ) is not null;

    raise exception using
      errcode = 'P7922',
      message =
        'StayQR Day 9 lifecycle runtime acceptance rollback';
  exception
    when sqlstate 'P7922' then
      null;
    when others then
      if role_switched then
        begin
          execute 'reset role';
        exception when others then
          null;
        end;
        role_switched := false;
      end if;

      audit_failure := format(
        'Audit harness failure [%s] %s',
        sqlstate,
        sqlerrm
      );
  end;

  -- ------------------------------------------------------------------------
  -- Confirm production counts and full synthetic rollback.
  -- ------------------------------------------------------------------------
  select count(*) into after_hotels from public.hotels;
  select count(*) into after_plans from public.subscription_plans;
  select count(*) into after_plan_prices
  from public.subscription_plan_prices;
  select count(*) into after_subscriptions
  from public.hotel_subscriptions;
  select count(*) into after_subscription_events
  from public.subscription_events;
  select count(*) into after_rooms from public.rooms;
  select count(*) into after_room_types from public.room_types;
  select count(*) into after_rate_plans from public.rate_plans;
  select count(*) into after_usage from public.usage_counters;
  select count(*) into after_tickets from public.support_tickets;
  select count(*) into after_ticket_events
  from public.support_ticket_events;
  select count(*) into after_support_sessions
  from public.support_access_sessions;
  select count(*) into after_support_access_events
  from public.support_access_events;
  select count(*) into after_announcements
  from public.announcements;

  production_counts_unchanged :=
    before_hotels = after_hotels
    and before_plans = after_plans
    and before_plan_prices = after_plan_prices
    and before_subscriptions = after_subscriptions
    and before_subscription_events =
      after_subscription_events
    and before_rooms = after_rooms
    and before_room_types = after_room_types
    and before_rate_plans = after_rate_plans
    and before_usage = after_usage
    and before_tickets = after_tickets
    and before_ticket_events = after_ticket_events
    and before_support_sessions = after_support_sessions
    and before_support_access_events =
      after_support_access_events
    and before_announcements = after_announcements;

  synthetic_records_rolled_back :=
    not exists (
      select 1
      from public.hotels h
      where h.slug = 'stayqr-day9-runtime-' || suffix
    )
    and not exists (
      select 1
      from public.subscription_plans sp
      where sp.plan_name in (
        'Audit 052 Starter ' || suffix,
        'Audit 052 Growth ' || suffix
      )
    )
    and not exists (
      select 1
      from public.support_tickets st
      where st.subject =
        'Audit 052 support ticket ' || suffix
    )
    and not exists (
      select 1
      from public.announcements a
      where a.metadata ->> 'audit' = '052'
        and a.metadata ->> 'suffix' = suffix
    )
    and not exists (
      select 1
      from public.support_access_sessions sas
      where sas.reason =
        'Audit 052 reversible support access.'
    );

  final_runtime_ready :=
    plan_create_ok
    and plan_price_rows_ok
    and fresh_bootstrap_ok
    and bootstrap_owner_ok
    and normalized_trial_contract_ok
    and room_import_ok
    and capacity_rpc_blocked
    and room_trigger_blocked
    and trial_extension_idempotent
    and paid_activation_idempotent
    and dashboard_mrr_ok
    and suspension_ok
    and reactivation_ok
    and plan_change_ok
    and renewal_ok
    and scheduled_cancel_ok
    and expiry_reconciliation_ok
    and support_create_ok
    and support_message_ok
    and cross_hotel_support_blocked
    and support_triage_ok
    and safe_support_start_ok
    and safe_support_end_ok
    and announcement_ok
    and owner_announcement_visible
    and owner_dashboard_blocked
    and owner_lifecycle_blocked
    and anon_paid_blocked
    and anon_support_blocked
    and anon_dashboard_blocked
    and production_counts_unchanged
    and synthetic_records_rolled_back;

  -- ------------------------------------------------------------------------
  -- Final 42-row result.
  -- ------------------------------------------------------------------------
  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '01_runtime_identities_resolved',
    'passed', identities_resolved,
    'details', format(
      'Platform Admin=%s; real owner=%s; owner hotel=%s.',
      coalesce(platform_admin_email, 'NOT FOUND'),
      coalesce(owner_email, 'NOT FOUND'),
      coalesce(owner_hotel_name, 'NOT FOUND')
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '02_plan_management_runtime',
    'passed', plan_create_ok,
    'details',
      'Platform Admin created two reversible plans with independent IDs.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '03_plan_price_rows_runtime',
    'passed', plan_price_rows_ok,
    'details',
      'Each reversible plan received monthly and annual provider-neutral price rows.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '04_post_day9_fresh_bootstrap',
    'passed', fresh_bootstrap_ok,
    'details',
      'Locked Day 8 bootstrap created a fresh hotel, owner and trial after Day 9 limit enforcement.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '05_bootstrap_owner_exception',
    'passed', bootstrap_owner_ok,
    'details',
      'The exact first active owner row was created and linked to the authenticated actor.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '06_trial_contract_normalized',
    'passed', normalized_trial_contract_ok,
    'details',
      'Fresh trial stored billing_mode=trial, billing_cycle=none, amount=0 and valid current-period dates.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '07_bootstrap_configuration_defaults',
    'passed', bootstrap_defaults_ok,
    'details',
      'Settings, default floor, invoice numbering, amenities and request categories were created.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '08_inventory_configuration_runtime',
    'passed', inventory_config_ok,
    'details',
      'One room type and one rate plan were configured through the Day 8 RPC.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '09_room_import_at_plan_limit',
    'passed', room_import_ok,
    'details',
      'Two rooms were imported successfully against a two-room plan limit.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '10_usage_rpc_runtime',
    'passed', usage_rpc_ok,
    'details',
      'Usage RPC returned two rooms, one active owner, room limit two and staff limit one.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '11_capacity_rpc_blocks_extra_room',
    'passed', capacity_rpc_blocked,
    'details', coalesce(
      capacity_error,
      'Capacity RPC rejected the extra room.'
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '12_room_trigger_blocks_extra_room',
    'passed', room_trigger_blocked,
    'details', coalesce(
      trigger_limit_error,
      'Database room-limit trigger rejected the extra room.'
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '13_trial_extension_runtime',
    'passed', trial_extension_ok,
    'details',
      'Platform Admin extended the synthetic trial by seven days.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '14_trial_extension_idempotent',
    'passed', trial_extension_idempotent,
    'details',
      'Repeating the same extension key returned the original end date without extending twice.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '15_trial_to_paid_runtime',
    'passed', paid_activation_ok,
    'details',
      'The synthetic trial converted to an active paid monthly subscription with provider evidence.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '16_paid_activation_idempotent',
    'passed', paid_activation_idempotent,
    'details',
      'Repeating the paid-activation key returned the original subscription result.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '17_global_dashboard_mrr_runtime',
    'passed', dashboard_mrr_ok,
    'details', format(
      'Baseline MRR minor=%s; expected reversible increase=%s.',
      baseline_mrr_minor,
      expected_paid_mrr_minor
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '18_suspension_runtime',
    'passed', suspension_ok,
    'details',
      'Subscription and hotel state both moved to suspended.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '19_reactivation_runtime',
    'passed', reactivation_ok,
    'details',
      'Valid paid-period recovery restored subscription and hotel state to active.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '20_plan_change_runtime',
    'passed', plan_change_ok,
    'details',
      'The subscription upgraded to the second capacity-safe plan.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '21_renewal_runtime',
    'passed', renewal_ok,
    'details',
      'The paid period renewed with valid dates and updated amount.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '22_scheduled_cancellation_runtime',
    'passed', scheduled_cancel_ok,
    'details',
      'Cancellation was scheduled while the paid contract remained active through period end.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '23_expiry_reconciliation_runtime',
    'passed', expiry_reconciliation_ok,
    'details',
      'Expiry reconciliation completed the scheduled cancellation and suspended hotel access.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '24_lifecycle_event_coverage',
    'passed', lifecycle_events_ok,
    'details',
      'Trial extension, paid activation, suspension, recovery, plan change, renewal and cancellation events exist.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '25_owner_support_create_runtime',
    'passed', support_create_ok,
    'details',
      'The real hotel owner created a ticket for their own hotel through the approved RPC.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '26_owner_support_message_runtime',
    'passed', support_message_ok,
    'details',
      'The owner appended an immutable support-ticket message.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '27_cross_hotel_support_create_blocked',
    'passed', cross_hotel_support_blocked,
    'details', coalesce(
      cross_support_error,
      'Owner cross-hotel ticket creation was rejected.'
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '28_platform_admin_support_triage',
    'passed', support_triage_ok,
    'details',
      'Platform Admin assigned/resolved the ticket and produced immutable status history.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '29_safe_support_start_runtime',
    'passed', safe_support_start_ok,
    'details',
      'Platform Admin opened an explicit 30-minute support-access session.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '30_safe_support_end_runtime',
    'passed', safe_support_end_ok,
    'details',
      'The support-access session ended explicitly.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '31_support_access_event_history',
    'passed', support_access_events_ok,
    'details',
      'Support-access start and end events were both recorded.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '32_announcement_server_action',
    'passed', announcement_ok,
    'details',
      'Platform Admin published a reversible hotel-targeted announcement through the RPC.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '33_owner_announcement_visibility',
    'passed', owner_announcement_visible,
    'details',
      'The real owner could read the active announcement targeted to their hotel.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '34_owner_dashboard_blocked',
    'passed', owner_dashboard_blocked,
    'details',
      'A non-platform owner could not execute the global Super Admin dashboard.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '35_owner_lifecycle_admin_action_blocked',
    'passed', owner_lifecycle_blocked,
    'details',
      'A non-platform owner could not suspend another hotel.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '36_anonymous_paid_activation_blocked',
    'passed', anon_paid_blocked,
    'details',
      'The real anon role could not execute paid activation.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '37_anonymous_support_creation_blocked',
    'passed', anon_support_blocked,
    'details',
      'The real anon role could not create a support ticket.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '38_anonymous_dashboard_blocked',
    'passed', anon_dashboard_blocked,
    'details',
      'The real anon role could not execute the Super Admin dashboard.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '39_current_subscription_uniqueness',
    'passed', current_subscription_unique,
    'details',
      'No hotel had more than one current lifecycle subscription during the full workflow.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '40_day8_rpc_compatibility_preserved',
    'passed', day8_rpcs_preserved,
    'details',
      'Locked Day 8 bootstrap, inventory, room import and readiness RPCs remain installed.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '41_production_counts_and_rollback',
    'passed',
      production_counts_unchanged
      and synthetic_records_rolled_back,
    'details', format(
      'Hotels %s→%s; plans %s→%s; prices %s→%s; subscriptions %s→%s; events %s→%s; rooms %s→%s; room types %s→%s; rates %s→%s; usage %s→%s; tickets %s→%s; ticket events %s→%s; support sessions %s→%s; support events %s→%s; announcements %s→%s.',
      before_hotels,
      after_hotels,
      before_plans,
      after_plans,
      before_plan_prices,
      after_plan_prices,
      before_subscriptions,
      after_subscriptions,
      before_subscription_events,
      after_subscription_events,
      before_rooms,
      after_rooms,
      before_room_types,
      after_room_types,
      before_rate_plans,
      after_rate_plans,
      before_usage,
      after_usage,
      before_tickets,
      after_tickets,
      before_ticket_events,
      after_ticket_events,
      before_support_sessions,
      after_support_sessions,
      before_support_access_events,
      after_support_access_events,
      before_announcements,
      after_announcements
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'test_name', '42_day9_lifecycle_runtime_ready',
    'passed', final_runtime_ready,
    'details', coalesce(
      audit_failure,
      'Day 8 compatibility, Day 9 lifecycle, limits, MRR, support, safe access and announcements passed runtime acceptance.'
    )
  ));

  return query
  select
    item.test_name,
    item.passed,
    item.details
  from jsonb_to_recordset(results)
    as item(
      test_name text,
      passed boolean,
      details text
    )
  order by item.test_name;
exception when others then
  if role_switched then
    begin
      execute 'reset role';
    exception when others then
      null;
    end;
  end if;

  return query
  select
    '00_audit_harness_error'::text,
    false,
    format('[%s] %s', sqlstate, sqlerrm);
end;
$$;


ALTER FUNCTION "private"."run_day9_lifecycle_runtime_acceptance_20260728"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."run_day9_lifecycle_runtime_acceptance_20260728"() IS 'Reversible runtime acceptance for post-Day-9 fresh onboarding, trial normalization, plan limits, full subscription lifecycle, MRR, support, safe support access, announcements, authorization and rollback. Remove after evidence export.';



CREATE OR REPLACE FUNCTION "private"."run_day9_super_admin_subscription_preflight_20260728"() RETURNS TABLE("check_name" "text", "status" "text", "details" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  results jsonb := '[]'::jsonb;

  hotel_count bigint := 0;
  active_hotel_count bigint := 0;
  suspended_hotel_count bigint := 0;

  plan_count bigint := 0;
  active_plan_count bigint := 0;
  duplicate_plan_names bigint := 0;
  invalid_plan_features bigint := 0;

  subscription_count bigint := 0;
  current_subscription_count bigint := 0;
  hotels_without_current_subscription bigint := 0;
  hotels_with_multiple_current bigint := 0;
  invalid_subscription_dates bigint := 0;
  expired_trials_not_reconciled bigint := 0;
  hotel_subscription_status_drift bigint := 0;
  hotels_over_room_limit bigint := 0;

  platform_admin_count bigint := 0;

  optional_count bigint := 0;
  optional_policy_count bigint := 0;
  optional_rls boolean := false;
  optional_unique boolean := false;

  lifecycle_columns integer := 0;
  provider_columns integer := 0;
  plan_limit_columns text[];
  missing_plan_limit_columns text[];

  function_exists boolean := false;
  table_exists boolean := false;
begin
  -- ------------------------------------------------------------------------
  -- Current production inventory.
  -- ------------------------------------------------------------------------
  select
    count(*),
    count(*) filter (where h.status = 'active'),
    count(*) filter (where h.status in ('suspended', 'inactive'))
  into
    hotel_count,
    active_hotel_count,
    suspended_hotel_count
  from public.hotels h;

  select
    count(*),
    count(*) filter (where sp.status = 'active'),
    count(*) filter (
      where sp.features is not null
        and jsonb_typeof(sp.features) not in ('array', 'object')
    )
  into
    plan_count,
    active_plan_count,
    invalid_plan_features
  from public.subscription_plans sp;

  select count(*)
  into duplicate_plan_names
  from (
    select lower(trim(sp.plan_name))
    from public.subscription_plans sp
    group by lower(trim(sp.plan_name))
    having count(*) > 1
  ) duplicate_plan;

  select count(*)
  into subscription_count
  from public.hotel_subscriptions;

  select count(*)
  into current_subscription_count
  from public.hotel_subscriptions hs
  where hs.status in (
    'trial',
    'trialing',
    'active',
    'past_due',
    'suspended'
  );

  select count(*)
  into hotels_without_current_subscription
  from public.hotels h
  where not exists (
    select 1
    from public.hotel_subscriptions hs
    where hs.hotel_id = h.id
      and hs.status in (
        'trial',
        'trialing',
        'active',
        'past_due',
        'suspended'
      )
  );

  select count(*)
  into hotels_with_multiple_current
  from (
    select hs.hotel_id
    from public.hotel_subscriptions hs
    where hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
    group by hs.hotel_id
    having count(*) > 1
  ) duplicate_current;

  select count(*)
  into invalid_subscription_dates
  from public.hotel_subscriptions hs
  where
    (
      hs.end_date is not null
      and hs.start_date is not null
      and hs.end_date <= hs.start_date
    )
    or (
      hs.trial_ends_at is not null
      and hs.trial_started_at is not null
      and hs.trial_ends_at <= hs.trial_started_at
    )
    or (
      hs.cancelled_at is not null
      and hs.cancelled_at <
        coalesce(hs.start_date, hs.created_at)
    );

  select count(*)
  into expired_trials_not_reconciled
  from public.hotel_subscriptions hs
  where hs.status in ('trial', 'trialing')
    and coalesce(hs.trial_ends_at, hs.end_date) <= now();

  with latest_subscription as (
    select distinct on (hs.hotel_id)
      hs.hotel_id,
      hs.status
    from public.hotel_subscriptions hs
    order by
      hs.hotel_id,
      coalesce(hs.updated_at, hs.created_at) desc,
      hs.created_at desc,
      hs.id desc
  )
  select count(*)
  into hotel_subscription_status_drift
  from public.hotels h
  join latest_subscription ls on ls.hotel_id = h.id
  where
    case lower(coalesce(h.subscription_status, ''))
      when 'trial' then 'trialing'
      else lower(coalesce(h.subscription_status, ''))
    end
    <>
    case lower(coalesce(ls.status, ''))
      when 'trial' then 'trialing'
      else lower(coalesce(ls.status, ''))
    end;

  with current_subscription as (
    select distinct on (hs.hotel_id)
      hs.hotel_id,
      hs.plan_id
    from public.hotel_subscriptions hs
    where hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
    order by
      hs.hotel_id,
      coalesce(hs.updated_at, hs.created_at) desc,
      hs.created_at desc,
      hs.id desc
  ),
  room_usage as (
    select
      h.id as hotel_id,
      count(r.id) as room_count
    from public.hotels h
    left join public.rooms r on r.hotel_id = h.id
    group by h.id
  )
  select count(*)
  into hotels_over_room_limit
  from current_subscription cs
  join public.subscription_plans sp on sp.id = cs.plan_id
  join room_usage ru on ru.hotel_id = cs.hotel_id
  where sp.max_rooms is not null
    and ru.room_count > sp.max_rooms;

  if to_regclass('public.platform_admins') is not null then
    execute $sql$
      select count(*)
      from public.platform_admins pa
      where pa.status = 'active'
    $sql$
    into platform_admin_count;
  end if;

  select count(*)
  into lifecycle_columns
  from information_schema.columns c
  where c.table_schema = 'public'
    and c.table_name = 'hotel_subscriptions'
    and c.column_name in (
      'trial_started_at',
      'trial_ends_at',
      'activated_at',
      'cancelled_at',
      'cancellation_reason',
      'metadata',
      'updated_at'
    );

  select array_agg(c.column_name order by c.ordinal_position)
  into plan_limit_columns
  from information_schema.columns c
  where c.table_schema = 'public'
    and c.table_name = 'subscription_plans'
    and c.column_name in (
      'max_rooms',
      'max_staff',
      'max_users',
      'max_properties',
      'max_storage_mb',
      'features',
      'price_monthly',
      'price_annual',
      'plan_code',
      'trial_days'
    );

  select array_agg(required_name order by required_name)
  into missing_plan_limit_columns
  from unnest(array[
    'max_staff',
    'max_properties',
    'max_storage_mb',
    'price_annual',
    'plan_code',
    'trial_days'
  ]::text[]) required_name
  where not exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = 'subscription_plans'
      and c.column_name = required_name
  );

  select count(*)
  into provider_columns
  from information_schema.columns c
  where c.table_schema = 'public'
    and c.table_name = 'hotel_subscriptions'
    and c.column_name in (
      'provider',
      'provider_customer_id',
      'provider_subscription_id',
      'provider_payment_link_id',
      'provider_status',
      'provider_metadata'
    );

  -- ------------------------------------------------------------------------
  -- 01–15: locked baseline, plans, subscriptions and production-data risks.
  -- ------------------------------------------------------------------------
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '01_day8_locked_baseline',
    'status', case
      when to_regprocedure(
        'public.bootstrap_hotel_onboarding(jsonb)'
      ) is not null
       and to_regprocedure(
        'public.activate_hotel_trial(uuid,uuid,integer)'
      ) is not null
       and to_regclass('public.hotel_onboarding') is not null
        then 'READY' else 'RISK' end,
    'details',
      'Day 8 hotel bootstrap, trial activation and onboarding state must remain intact during Day 9.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '02_platform_admin_identity',
    'status', case
      when platform_admin_count >= 1 then 'READY'
      else 'RISK' end,
    'details', format(
      'Active Platform Admin identities=%s.',
      platform_admin_count
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '03_hotel_inventory',
    'status', 'INFO',
    'details', format(
      'Hotels=%s; active=%s; suspended/inactive=%s.',
      hotel_count,
      active_hotel_count,
      suspended_hotel_count
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '04_subscription_plan_inventory',
    'status', case
      when plan_count > 0 and active_plan_count > 0
        then 'READY' else 'RISK' end,
    'details', format(
      'Plans=%s; active=%s.',
      plan_count,
      active_plan_count
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '05_plan_limit_schema',
    'status', case
      when coalesce(cardinality(missing_plan_limit_columns), 0) = 0
        then 'READY' else 'GAP' end,
    'details', format(
      'Existing commercial/limit columns=%s; recommended missing fields=%s.',
      coalesce(array_to_string(plan_limit_columns, ', '), 'none'),
      coalesce(array_to_string(missing_plan_limit_columns, ', '), 'none')
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '06_plan_name_uniqueness',
    'status', case
      when duplicate_plan_names = 0 then 'READY'
      else 'RISK' end,
    'details', format(
      'Duplicate case-insensitive plan-name groups=%s.',
      duplicate_plan_names
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '07_plan_features_integrity',
    'status', case
      when invalid_plan_features = 0 then 'READY'
      else 'RISK' end,
    'details', format(
      'Plans with invalid non-array/non-object features JSON=%s.',
      invalid_plan_features
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '08_subscription_inventory',
    'status', 'INFO',
    'details', format(
      'Subscription history rows=%s; current lifecycle rows=%s.',
      subscription_count,
      current_subscription_count
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '09_current_subscription_coverage',
    'status', case
      when hotels_without_current_subscription = 0
        then 'READY' else 'RISK' end,
    'details', format(
      'Hotels without trial/active/past_due/suspended subscription=%s.',
      hotels_without_current_subscription
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '10_single_current_subscription',
    'status', case
      when hotels_with_multiple_current = 0
        then 'READY' else 'RISK' end,
    'details', format(
      'Hotels with multiple current lifecycle subscriptions=%s.',
      hotels_with_multiple_current
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '11_explicit_lifecycle_columns',
    'status', case
      when lifecycle_columns = 7 then 'READY'
      else 'GAP' end,
    'details', format(
      'Required Day 8/9 lifecycle columns present=%s/7.',
      lifecycle_columns
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '12_subscription_date_integrity',
    'status', case
      when invalid_subscription_dates = 0
        then 'READY' else 'RISK' end,
    'details', format(
      'Invalid start/end, trial or cancellation date rows=%s.',
      invalid_subscription_dates
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '13_expired_trial_reconciliation',
    'status', case
      when expired_trials_not_reconciled = 0
        then 'READY' else 'RISK' end,
    'details', format(
      'Expired trials still marked trial/trialing=%s.',
      expired_trials_not_reconciled
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '14_hotel_subscription_status_consistency',
    'status', case
      when hotel_subscription_status_drift = 0
        then 'READY' else 'RISK' end,
    'details', format(
      'Hotels whose cached subscription_status differs from latest subscription=%s.',
      hotel_subscription_status_drift
    )
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '15_current_room_limit_usage',
    'status', case
      when hotels_over_room_limit = 0
        then 'READY' else 'RISK' end,
    'details', format(
      'Hotels currently exceeding subscription_plans.max_rooms=%s.',
      hotels_over_room_limit
    )
  ));

  -- ------------------------------------------------------------------------
  -- 16–22: lifecycle server actions.
  -- ------------------------------------------------------------------------
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '16_trial_start_rpc',
    'status', case
      when to_regprocedure(
        'public.activate_hotel_trial(uuid,uuid,integer)'
      ) is not null then 'READY' else 'GAP' end,
    'details',
      'Dedicated one-time trial activation RPC from Day 8.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'extend_hotel_trial',
        'admin_extend_hotel_trial'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '17_trial_extend_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Super Admin trial extension must be transactional, authorized and event-logged.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'expire_hotel_trials',
        'process_expired_trials',
        'reconcile_expired_subscriptions'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '18_trial_expiry_reconciliation_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'A repeatable expiry/reconciliation action is required for scheduled execution.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'activate_paid_subscription',
        'convert_trial_to_paid',
        'admin_activate_subscription'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '19_paid_activation_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Paid conversion must atomically activate the subscription and hotel access state.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'suspend_hotel',
        'admin_suspend_hotel',
        'suspend_hotel_subscription'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '20_suspend_hotel_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Suspension must update subscription/hotel state and revoke ordinary hotel access safely.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'reactivate_hotel',
        'admin_reactivate_hotel',
        'reactivate_hotel_subscription'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '21_reactivate_hotel_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Recovery must restore valid hotel access without creating duplicate subscriptions.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'renew_hotel_subscription',
        'change_hotel_subscription_plan',
        'cancel_hotel_subscription',
        'admin_manage_subscription'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '22_renew_change_cancel_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Renewal, plan change and cancellation need an authoritative lifecycle action.'
  ));

  -- ------------------------------------------------------------------------
  -- 23–33: events, usage, MRR, support, announcements and safe access.
  -- ------------------------------------------------------------------------
  table_exists :=
    to_regclass('public.subscription_events') is not null;
  optional_count := 0;
  optional_rls := false;
  optional_policy_count := 0;

  if table_exists then
    execute 'select count(*) from public.subscription_events'
      into optional_count;

    select c.relrowsecurity
    into optional_rls
    from pg_class c
    where c.oid = 'public.subscription_events'::regclass;

    select count(*)
    into optional_policy_count
    from pg_policies p
    where p.schemaname = 'public'
      and p.tablename = 'subscription_events';
  end if;

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '23_subscription_events',
    'status', case when table_exists then 'READY' else 'GAP' end,
    'details', case
      when table_exists then format(
        'Rows=%s; RLS=%s; policies=%s.',
        optional_count,
        optional_rls,
        optional_policy_count
      )
      else
        'No immutable subscription lifecycle event ledger exists.'
    end
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '24_subscription_event_immutability',
    'status', case
      when table_exists
       and optional_rls
       and not exists (
         select 1
         from pg_policies p
         where p.schemaname = 'public'
           and p.tablename = 'subscription_events'
           and p.cmd in ('UPDATE', 'DELETE', 'ALL')
           and (
             'authenticated' = any(p.roles)
             or 'public' = any(p.roles)
           )
       )
        then 'READY'
      else 'GAP'
    end,
    'details',
      'Hotel users must not update/delete historical lifecycle events through normal browser access.'
  ));

  table_exists :=
    to_regclass('public.usage_counters') is not null;

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '25_usage_counters',
    'status', case when table_exists then 'READY' else 'GAP' end,
    'details',
      'Day 9 requires hotel usage snapshots/counters for plan-limit enforcement and Super Admin visibility.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'get_hotel_subscription_usage',
        'refresh_hotel_subscription_usage',
        'get_platform_usage'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '26_usage_calculation_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Usage should be calculated server-side from authoritative tenant records.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('public', 'private')
      and p.proname in (
        'enforce_subscription_limit',
        'subscription_limit_allows',
        'assert_subscription_capacity'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '27_plan_limit_enforcement',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Limits must be enforced in server actions, not only displayed in the frontend.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'get_platform_mrr',
        'get_subscription_mrr',
        'get_super_admin_metrics'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '28_mrr_metrics_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'MRR must count paid active subscriptions using authoritative plan prices and lifecycle status.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'get_super_admin_dashboard',
        'get_platform_dashboard',
        'get_platform_control_center'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '29_global_dashboard_rpc',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'The Super Admin dashboard currently loads separate browser table queries rather than one controlled server summary.'
  ));

  table_exists :=
    to_regclass('public.support_tickets') is not null;
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '30_support_tickets',
    'status', case when table_exists then 'READY' else 'GAP' end,
    'details',
      'Hotel-owned support tickets with Platform Admin triage are required.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'create_support_ticket',
        'update_support_ticket_status',
        'assign_support_ticket'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '31_support_ticket_lifecycle',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Ticket creation, assignment, status and resolution need authorized server actions and audit history.'
  ));

  table_exists :=
    to_regclass('public.announcements') is not null;
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '32_platform_announcements',
    'status', case when table_exists then 'READY' else 'GAP' end,
    'details',
      'System announcements are part of the locked Super Admin product system, although broader notification delivery continues on Day 17.'
  ));

  table_exists :=
    to_regclass('public.support_access_sessions') is not null
    or to_regclass('public.safe_support_sessions') is not null;
  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'start_safe_support_access',
        'end_safe_support_access',
        'get_support_context'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '33_safe_support_access',
    'status', case
      when table_exists and function_exists then 'READY'
      else 'GAP' end,
    'details',
      'Support access must be explicit, time-bound and auditable; silent impersonation is not acceptable.'
  ));

  -- ------------------------------------------------------------------------
  -- 34–39: Razorpay provider and webhook foundation.
  -- ------------------------------------------------------------------------
  table_exists :=
    to_regclass('public.webhook_events') is not null;

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '34_webhook_event_ledger',
    'status', case when table_exists then 'READY' else 'GAP' end,
    'details',
      'Provider webhook payload identity, processing state, attempts and errors need an idempotency ledger.'
  ));

  optional_unique := false;
  if table_exists then
    select exists (
      select 1
      from pg_index i
      join pg_class c on c.oid = i.indrelid
      join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname = 'webhook_events'
        and i.indisunique
        and pg_get_indexdef(i.indexrelid) ~*
          '(event_id|provider_event_id|external_event_id)'
    )
    into optional_unique;
  end if;

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '35_webhook_idempotency_key',
    'status', case
      when table_exists and optional_unique then 'READY'
      else 'GAP' end,
    'details',
      'A unique provider event identifier is required to make webhook replay harmless.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '36_subscription_provider_identifiers',
    'status', case
      when provider_columns >= 4 then 'READY'
      else 'GAP' end,
    'details', format(
      'Razorpay/provider lifecycle columns present=%s/6.',
      provider_columns
    )
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'create_razorpay_subscription',
        'create_provider_subscription'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '37_razorpay_subscription_server_action',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'No database RPC detected. A trusted Edge Function may satisfy this instead; source audit follows.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'create_razorpay_payment_link',
        'create_subscription_payment_link',
        'create_provider_payment_link'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '38_payment_link_server_action',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'Payment links must be created server-side with no Razorpay secret in the browser.'
  ));

  function_exists := exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'handle_razorpay_webhook',
        'process_subscription_webhook',
        'process_provider_webhook'
      )
  );
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '39_signed_webhook_handler',
    'status', case when function_exists then 'READY' else 'GAP' end,
    'details',
      'No database webhook handler detected. A signed Edge Function may satisfy this instead; source audit follows.'
  ));

  -- ------------------------------------------------------------------------
  -- 40–42: access-control baseline and summary.
  -- ------------------------------------------------------------------------
  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '40_anonymous_saas_table_access',
    'status', case
      when not exists (
        select 1
        from information_schema.role_table_grants g
        where g.table_schema = 'public'
          and g.grantee in ('anon', 'PUBLIC')
          and g.table_name in (
            'hotels',
            'subscription_plans',
            'hotel_subscriptions',
            'subscription_events',
            'usage_counters',
            'support_tickets',
            'announcements',
            'webhook_events'
          )
      ) then 'READY' else 'RISK' end,
    'details',
      'Anonymous direct-table grants must remain absent.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '41_existing_subscription_rls',
    'status', case
      when (
        select c.relrowsecurity
        from pg_class c
        where c.oid = 'public.hotel_subscriptions'::regclass
      )
      and (
        select c.relrowsecurity
        from pg_class c
        where c.oid = 'public.subscription_plans'::regclass
      )
      and (
        select count(*) >= 6
        from pg_policies p
        where p.schemaname = 'public'
          and p.tablename in (
            'hotel_subscriptions',
            'subscription_plans'
          )
      )
        then 'READY' else 'RISK' end,
    'details',
      'Current subscription and plan tables must retain RLS and Platform Admin-controlled writes.'
  ));

  results := results || jsonb_build_array(jsonb_build_object(
    'check_name', '42_day9_preflight_summary',
    'status', 'INFO',
    'details',
      'Use this evidence to design the first bounded Day 9 migration. Do not manually edit subscription or hotel status rows and do not add Razorpay secrets to the frontend.'
  ));

  return query
  select
    item.check_name,
    item.status,
    item.details
  from jsonb_to_recordset(results)
    as item(
      check_name text,
      status text,
      details text
    )
  order by item.check_name;
end;
$_$;


ALTER FUNCTION "private"."run_day9_super_admin_subscription_preflight_20260728"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."run_day9_super_admin_subscription_preflight_20260728"() IS 'Read-only Day 9 Super Admin, subscription lifecycle, usage, support and Razorpay/webhook production preflight. Remove after Day 9 foundation acceptance.';



CREATE OR REPLACE FUNCTION "private"."run_reservation_foundation_smoke_test_20260720"() RETURNS TABLE("test_name" "text", "passed" boolean, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  test_hotel_id uuid;
  test_room_id uuid;
  test_room_type_id uuid;
  test_rate_plan_id uuid;

  first_reservation_id uuid;
  first_reservation_room_id uuid;
  first_reservation_number text;

  second_reservation_id uuid;
  second_reservation_room_id uuid;
  second_reservation_number text;

  test_start date := current_date + 730;
  test_end date := current_date + 732;

  first_allocation_created boolean := false;
  overlapping_allocation_rejected boolean := false;
  cleanup_completed boolean := false;
begin
  select
    r.hotel_id,
    r.id,
    r.room_type_id,
    rp.id
  into
    test_hotel_id,
    test_room_id,
    test_room_type_id,
    test_rate_plan_id
  from public.rooms r
  join lateral (
    select candidate.id
    from public.rate_plans candidate
    where candidate.hotel_id = r.hotel_id
      and candidate.room_type_id = r.room_type_id
      and candidate.is_active
    order by candidate.priority, candidate.created_at
    limit 1
  ) rp on true
  where r.status not in ('maintenance', 'out_of_order')
    and not exists (
      select 1
      from public.room_inventory_allocations ria
      where ria.hotel_id = r.hotel_id
        and ria.room_id = r.id
        and ria.status = 'active'
        and ria.stay_dates &&
          daterange(test_start, test_end + 1, '[)')
    )
  order by r.created_at
  limit 1;

  if test_room_id is null then
    raise exception
      'Smoke test requires a room with an active rate plan and a clear future date range.';
  end if;

  first_reservation_number :=
    'SMOKE-A-' || replace(gen_random_uuid()::text, '-', '');

  second_reservation_number :=
    'SMOKE-B-' || replace(gen_random_uuid()::text, '-', '');

  insert into public.reservations (
    hotel_id,
    reservation_number,
    status,
    booking_source,
    arrival_date,
    departure_date,
    currency_code,
    adults,
    children,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount
  )
  values (
    test_hotel_id,
    first_reservation_number,
    'confirmed',
    'other',
    test_start,
    test_end,
    'INR',
    1,
    0,
    0,
    0,
    0,
    0
  )
  returning id into first_reservation_id;

  insert into public.reservation_rooms (
    hotel_id,
    reservation_id,
    room_type_id,
    room_id,
    rate_plan_id,
    status,
    adults,
    children,
    nightly_rate,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount
  )
  values (
    test_hotel_id,
    first_reservation_id,
    test_room_type_id,
    test_room_id,
    test_rate_plan_id,
    'confirmed',
    1,
    0,
    0,
    0,
    0,
    0,
    0
  )
  returning id into first_reservation_room_id;

  first_allocation_created := exists (
    select 1
    from public.room_inventory_allocations ria
    where ria.hotel_id = test_hotel_id
      and ria.room_id = test_room_id
      and ria.reservation_room_id = first_reservation_room_id
      and ria.status = 'active'
      and ria.starts_on = test_start
      and ria.ends_on = test_end
  );

  begin
    insert into public.reservations (
      hotel_id,
      reservation_number,
      status,
      booking_source,
      arrival_date,
      departure_date,
      currency_code,
      adults,
      children,
      room_subtotal,
      tax_amount,
      discount_amount,
      total_amount
    )
    values (
      test_hotel_id,
      second_reservation_number,
      'confirmed',
      'other',
      test_start + 1,
      test_end + 1,
      'INR',
      1,
      0,
      0,
      0,
      0,
      0
    )
    returning id into second_reservation_id;

    insert into public.reservation_rooms (
      hotel_id,
      reservation_id,
      room_type_id,
      room_id,
      rate_plan_id,
      status,
      adults,
      children,
      nightly_rate,
      room_subtotal,
      tax_amount,
      discount_amount,
      total_amount
    )
    values (
      test_hotel_id,
      second_reservation_id,
      test_room_type_id,
      test_room_id,
      test_rate_plan_id,
      'confirmed',
      1,
      0,
      0,
      0,
      0,
      0,
      0
    )
    returning id into second_reservation_room_id;

  exception
    when exclusion_violation then
      overlapping_allocation_rejected := true;
  end;

  delete from public.reservations
  where id = first_reservation_id
    and hotel_id = test_hotel_id
    and reservation_number = first_reservation_number;

  if second_reservation_id is not null then
    delete from public.reservations
    where id = second_reservation_id
      and hotel_id = test_hotel_id
      and reservation_number = second_reservation_number;
  end if;

  cleanup_completed :=
    not exists (
      select 1
      from public.reservations r
      where r.reservation_number in (
        first_reservation_number,
        second_reservation_number
      )
    )
    and not exists (
      select 1
      from public.room_inventory_allocations ria
      where ria.reservation_room_id in (
        first_reservation_room_id,
        second_reservation_room_id
      )
    );

  return query
  values
    (
      'cleanup_completed'::text,
      cleanup_completed,
      'All smoke-test reservations and allocations were removed.'::text
    ),
    (
      'first_allocation_created'::text,
      first_allocation_created,
      'A confirmed reservation room created one active inventory allocation.'::text
    ),
    (
      'overlapping_allocation_rejected'::text,
      overlapping_allocation_rejected,
      'The database rejected an overlapping allocation for the same room.'::text
    );
exception
  when others then
    if first_reservation_id is not null then
      delete from public.reservations
      where id = first_reservation_id
        and hotel_id = test_hotel_id;
    end if;

    if second_reservation_id is not null then
      delete from public.reservations
      where id = second_reservation_id
        and hotel_id = test_hotel_id;
    end if;

    raise;
end;
$$;


ALTER FUNCTION "private"."run_reservation_foundation_smoke_test_20260720"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."seed_day4_browser_acceptance_20260723"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user uuid;
  target_hotel uuid;
  target_hotel_name text;
  hotel_timezone text;
  source_room uuid;
  source_room_type uuid;
  source_room_type_name text;
  source_rate_plan uuid;

  test_start date := current_date + 2300;
  test_end date := current_date + 2302;
  test_sequence_year integer := extract(year from (current_date + 2300))::integer;
  sequence_existed boolean := false;
  sequence_before bigint;

  test_guest uuid;
  direct_guest uuid;
  test_rate uuid;
  direct_session uuid;
  room_ids uuid[] := array[]::uuid[];
  room_id uuid;
  generated_room_number text;
  prefix text := 'D4QA-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
  created jsonb;
  created_id uuid;
  created_room_id uuid;
  block_one jsonb;
  block_two jsonb;
  block_three jsonb;
  reservation_ids uuid[] := array[]::uuid[];
  block_ids uuid[] := array[]::uuid[];
  source_references text[] := array[]::text[];
  i integer;
begin
  if exists (
    select 1
    from private.day4_browser_acceptance_state_20260723
  ) then
    raise exception
      'Day 4 browser acceptance data already exists. Run audit 018 before reseeding.';
  end if;

  if exists (
    select 1
    from public.reservations reservation
    where reservation.source_reference like 'DAY4-ACCEPT-%'
  ) then
    raise exception
      'Existing DAY4-ACCEPT reservations were found. Run audit 018 before reseeding.';
  end if;

  select administrator.user_id
  into actor_user
  from public.platform_admins administrator
  where administrator.status = 'active'
  order by administrator.created_at
  limit 1;

  if actor_user is null then
    raise exception 'Browser acceptance seed requires an active platform administrator.';
  end if;

  perform set_config(
    'request.jwt.claim.sub',
    actor_user::text,
    true
  );

  select
    hotel.id,
    hotel.hotel_name,
    coalesce(hotel.timezone, 'UTC'),
    room.id,
    room.room_type_id,
    room_type.name,
    rate_plan.id
  into
    target_hotel,
    target_hotel_name,
    hotel_timezone,
    source_room,
    source_room_type,
    source_room_type_name,
    source_rate_plan
  from public.hotels hotel
  join public.rooms room
    on room.hotel_id = hotel.id
   and room.status not in ('maintenance', 'out_of_order')
  join public.room_types room_type
    on room_type.id = room.room_type_id
   and room_type.hotel_id = room.hotel_id
   and room_type.is_active
  join lateral (
    select candidate.id
    from public.rate_plans candidate
    where candidate.hotel_id = room.hotel_id
      and candidate.room_type_id = room.room_type_id
      and candidate.is_active
    order by candidate.priority, candidate.created_at
    limit 1
  ) rate_plan on true
  where hotel.status = 'active'
  order by hotel.created_at, room.created_at
  limit 1;

  if target_hotel is null then
    raise exception
      'Browser acceptance seed requires an active hotel, room type and rate plan.';
  end if;

  select exists (
    select 1
    from public.reservation_number_sequences sequence
    where sequence.hotel_id = target_hotel
      and sequence.sequence_year = test_sequence_year
  )
  into sequence_existed;

  if sequence_existed then
    select sequence.last_number
    into sequence_before
    from public.reservation_number_sequences sequence
    where sequence.hotel_id = target_hotel
      and sequence.sequence_year = test_sequence_year;
  end if;

  for i in 1..20 loop
    generated_room_number := prefix || '-' || lpad(i::text, 2, '0');

    insert into public.rooms (
      hotel_id,
      room_number,
      room_type,
      room_type_id,
      status
    )
    select
      target_hotel,
      generated_room_number,
      source.room_type,
      source_room_type,
      'available'
    from public.rooms source
    where source.id = source_room
      and source.hotel_id = target_hotel
    returning id into room_id;

    room_ids := array_append(room_ids, room_id);
  end loop;

  insert into public.guests (
    hotel_id,
    full_name,
    phone,
    email,
    preferred_language
  )
  values (
    target_hotel,
    'StayQR Day 4 Browser Acceptance Guest',
    '9000040404',
    'day4-browser-acceptance@stayqr.invalid',
    'english'
  )
  returning id into test_guest;

  insert into public.guests (
    hotel_id,
    full_name,
    phone,
    email,
    preferred_language
  )
  values (
    target_hotel,
    'StayQR Day 4 Direct Stay Guest',
    '9000040405',
    'day4-direct-stay@stayqr.invalid',
    'english'
  )
  returning id into direct_guest;

  insert into public.seasonal_rates (
    hotel_id,
    rate_plan_id,
    name,
    start_date,
    end_date,
    nightly_rate,
    priority,
    is_active
  )
  values (
    target_hotel,
    source_rate_plan,
    'Day 4 Browser Acceptance Fixed Rate',
    test_start - 2,
    test_start + 35,
    1500,
    -4000,
    true
  )
  returning id into test_rate;

  -- Draft reservation on Room 01.
  source_references := array_append(source_references, 'DAY4-ACCEPT-DRAFT');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'draft',
      'booking_source', 'other',
      'source_reference', 'DAY4-ACCEPT-DRAFT',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[1],
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest),
      'internal_notes', 'Day 4 status rendering: Draft'
    )
  );
  reservation_ids := array_append(reservation_ids, (created->>'id')::uuid);

  -- Tentative reservation on Room 02.
  source_references := array_append(source_references, 'DAY4-ACCEPT-TENTATIVE');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'tentative',
      'booking_source', 'other',
      'source_reference', 'DAY4-ACCEPT-TENTATIVE',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[2],
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest),
      'internal_notes', 'Day 4 status rendering: Tentative'
    )
  );
  reservation_ids := array_append(reservation_ids, (created->>'id')::uuid);

  -- Confirmed reservation used for Edit + Cancel refresh testing on Room 03.
  source_references := array_append(source_references, 'DAY4-ACCEPT-CONFIRMED-EDIT-CANCEL');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'website',
      'source_reference', 'DAY4-ACCEPT-CONFIRMED-EDIT-CANCEL',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 2,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[3],
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest),
      'internal_notes', 'Use this record for Open Reservation, edit and cancellation refresh tests'
    )
  );
  reservation_ids := array_append(reservation_ids, (created->>'id')::uuid);

  -- Second confirmed reservation used for No-show refresh testing on Room 13.
  source_references := array_append(source_references, 'DAY4-ACCEPT-CONFIRMED-NOSHOW');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'phone',
      'source_reference', 'DAY4-ACCEPT-CONFIRMED-NOSHOW',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[13],
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest),
      'internal_notes', 'Use this record for no-show calendar refresh testing'
    )
  );
  reservation_ids := array_append(reservation_ids, (created->>'id')::uuid);

  -- Checked-in reservation on Room 04.
  source_references := array_append(source_references, 'DAY4-ACCEPT-CHECKED-IN');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'other',
      'source_reference', 'DAY4-ACCEPT-CHECKED-IN',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[4],
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest)
    )
  );
  created_id := (created->>'id')::uuid;
  created_room_id := (created->'rooms'->0->>'id')::uuid;
  reservation_ids := array_append(reservation_ids, created_id);
  update public.reservations
  set status = 'checked_in', updated_by = actor_user, updated_at = now()
  where hotel_id = target_hotel and id = created_id;
  update public.reservation_rooms
  set status = 'checked_in', updated_at = now()
  where hotel_id = target_hotel and id = created_room_id;

  -- Checked-out historical reservation on Room 05.
  source_references := array_append(source_references, 'DAY4-ACCEPT-CHECKED-OUT');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'other',
      'source_reference', 'DAY4-ACCEPT-CHECKED-OUT',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[5],
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest)
    )
  );
  created_id := (created->>'id')::uuid;
  created_room_id := (created->'rooms'->0->>'id')::uuid;
  reservation_ids := array_append(reservation_ids, created_id);
  update public.reservations
  set status = 'checked_in', updated_by = actor_user, updated_at = now()
  where hotel_id = target_hotel and id = created_id;
  update public.reservation_rooms
  set status = 'checked_in', updated_at = now()
  where hotel_id = target_hotel and id = created_room_id;
  update public.reservations
  set status = 'checked_out', updated_by = actor_user, updated_at = now()
  where hotel_id = target_hotel and id = created_id;
  update public.reservation_rooms
  set status = 'checked_out', updated_at = now()
  where hotel_id = target_hotel and id = created_room_id;

  -- Cancelled historical reservation on Room 06.
  source_references := array_append(source_references, 'DAY4-ACCEPT-CANCELLED');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'other',
      'source_reference', 'DAY4-ACCEPT-CANCELLED',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[6],
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest)
    )
  );
  created_id := (created->>'id')::uuid;
  reservation_ids := array_append(reservation_ids, created_id);
  perform public.change_reservation_status(
    target_hotel,
    created_id,
    'cancelled',
    'Day 4 browser acceptance pre-seeded cancellation'
  );

  -- No-show historical reservation on Room 07.
  source_references := array_append(source_references, 'DAY4-ACCEPT-NO-SHOW');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'other',
      'source_reference', 'DAY4-ACCEPT-NO-SHOW',
      'arrival_date', test_start,
      'departure_date', test_end,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[7],
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest)
    )
  );
  created_id := (created->>'id')::uuid;
  reservation_ids := array_append(reservation_ids, created_id);
  perform public.change_reservation_status(
    target_hotel,
    created_id,
    'no_show',
    'Day 4 browser acceptance pre-seeded no-show'
  );

  -- Unallocated tentative reservation for queue drag on Room 12 target.
  source_references := array_append(source_references, 'DAY4-ACCEPT-UNALLOCATED');
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'draft',
      'booking_source', 'other',
      'source_reference', 'DAY4-ACCEPT-UNALLOCATED',
      'arrival_date', test_start + 3,
      'departure_date', test_start + 5,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'rate_plan_id', source_rate_plan,
      'guest', jsonb_build_object('id', test_guest),
      'internal_notes', 'Drag this queue record into a compatible free temporary room'
    )
  );
  created_id := (created->>'id')::uuid;
  reservation_ids := array_append(reservation_ids, created_id);
  update public.reservations
  set status = 'tentative', updated_by = actor_user, updated_at = now()
  where hotel_id = target_hotel and id = created_id;

  block_one := public.create_calendar_room_block(
    target_hotel,
    jsonb_build_object(
      'room_id', room_ids[8],
      'block_type', 'maintenance',
      'start_date', test_start,
      'end_date', test_end,
      'reason', 'DAY4 ACCEPT Maintenance block',
      'notes', 'Open details to verify Created by; then leave for cleanup.'
    )
  );
  block_ids := array_append(block_ids, (block_one->>'id')::uuid);

  block_two := public.create_calendar_room_block(
    target_hotel,
    jsonb_build_object(
      'room_id', room_ids[9],
      'block_type', 'operational',
      'start_date', test_start,
      'end_date', test_end,
      'reason', 'DAY4 ACCEPT Operational block — cancel this in browser',
      'notes', 'Use mandatory reason: Day 4 browser cancellation passed'
    )
  );
  block_ids := array_append(block_ids, (block_two->>'id')::uuid);

  block_three := public.create_calendar_room_block(
    target_hotel,
    jsonb_build_object(
      'room_id', room_ids[10],
      'block_type', 'out_of_order',
      'start_date', test_start,
      'end_date', test_end,
      'reason', 'DAY4 ACCEPT Out-of-order block',
      'notes', 'Status and legend rendering verification'
    )
  );
  block_ids := array_append(block_ids, (block_three->>'id')::uuid);

  insert into public.guest_sessions (
    hotel_id,
    room_id,
    guest_id,
    checkin_time,
    checkout_time,
    status
  )
  values (
    target_hotel,
    room_ids[11],
    direct_guest,
    (test_start::timestamp + interval '14 hours') at time zone hotel_timezone,
    (test_end::timestamp + interval '11 hours') at time zone hotel_timezone,
    'active'
  )
  returning id into direct_session;

  insert into private.day4_browser_acceptance_state_20260723 (
    singleton,
    payload
  )
  values (
    true,
    jsonb_build_object(
      'actor_user', actor_user,
      'hotel_id', target_hotel,
      'hotel_name', target_hotel_name,
      'hotel_timezone', hotel_timezone,
      'test_start', test_start,
      'test_end', test_end,
      'room_type_id', source_room_type,
      'room_type_name', source_room_type_name,
      'rate_plan_id', source_rate_plan,
      'room_prefix', prefix,
      'room_ids', to_jsonb(room_ids),
      'reservation_ids', to_jsonb(reservation_ids),
      'source_references', to_jsonb(source_references),
      'block_ids', to_jsonb(block_ids),
      'guest_ids', jsonb_build_array(test_guest, direct_guest),
      'guest_session_id', direct_session,
      'seasonal_rate_id', test_rate,
      'sequence_year', test_sequence_year,
      'sequence_existed', sequence_existed,
      'sequence_before', sequence_before
    )
  );

  return jsonb_build_object(
    'result', 'DAY 4 BROWSER ACCEPTANCE DATA CREATED',
    'hotel', target_hotel_name,
    'date_to_open', test_start,
    'week_range', format('%s to %s', test_start, test_start + 6),
    'month_to_open', to_char(test_start, 'YYYY-MM'),
    'room_type_filter', source_room_type_name,
    'temporary_room_prefix', prefix,
    'temporary_rooms', cardinality(room_ids),
    'reservation_records', cardinality(reservation_ids),
    'room_blocks', cardinality(block_ids),
    'direct_stay_session', direct_session,
    'unallocated_source_reference', 'DAY4-ACCEPT-UNALLOCATED',
    'cleanup_instruction', 'Run audit 018 only after browser acceptance is complete.'
  );
exception
  when others then
    -- The state row is written last. If setup fails before that point, remove
    -- records by the unique acceptance prefixes and references.
    if target_hotel is not null then
      delete from public.activity_logs log
      where log.hotel_id = target_hotel
        and (
          log.entity_id = any(reservation_ids)
          or log.entity_id = any(block_ids)
          or log.entity_id = direct_session
        );

      delete from public.reservations reservation
      where reservation.hotel_id = target_hotel
        and (
          reservation.id = any(reservation_ids)
          or reservation.source_reference like 'DAY4-ACCEPT-%'
        );

      delete from public.room_blocks block
      where block.hotel_id = target_hotel
        and (
          block.id = any(block_ids)
          or block.reason like 'DAY4 ACCEPT%'
        );

      if direct_session is not null then
        delete from public.guest_sessions session
        where session.hotel_id = target_hotel
          and session.id = direct_session;
      end if;

      if test_rate is not null then
        delete from public.seasonal_rates rate
        where rate.hotel_id = target_hotel
          and rate.id = test_rate;
      end if;

      if test_guest is not null or direct_guest is not null then
        delete from public.guests guest
        where guest.hotel_id = target_hotel
          and guest.id in (test_guest, direct_guest);
      end if;

      delete from public.rooms room
      where room.hotel_id = target_hotel
        and (
          room.id = any(room_ids)
          or room.room_number like prefix || '%'
        );

      if sequence_existed then
        update public.reservation_number_sequences sequence
        set last_number = sequence_before
        where sequence.hotel_id = target_hotel
          and sequence.sequence_year = test_sequence_year;
      else
        delete from public.reservation_number_sequences sequence
        where sequence.hotel_id = target_hotel
          and sequence.sequence_year = test_sequence_year;
      end if;
    end if;

    raise;
end;
$$;


ALTER FUNCTION "private"."seed_day4_browser_acceptance_20260723"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."seed_day5_browser_acceptance_20260724"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user uuid;
  target_hotel uuid;
  target_hotel_name text;
  hotel_timezone text;
  source_room uuid;
  source_room_type uuid;
  source_room_type_name text;
  source_rate_plan uuid;
  source_currency_code text;
  temporary_rate_plan_created boolean := false;
  temporary_rate_plan_code text;
  test_today date;
  test_sequence_year integer;
  sequence_existed boolean := false;
  sequence_before bigint;
  room_ids uuid[] := array[]::uuid[];
  room_id uuid;
  generated_room_number text;
  room_prefix text := 'D5QA-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
  created jsonb;
  group_created jsonb;
  group_after_add jsonb;
  inhouse_created jsonb;
  atomic_quote jsonb;
  atomic_deposit numeric(12,2);
  group_updated_at timestamptz;
  inhouse_result jsonb;
  i integer;
begin
  if exists (select 1 from private.day5_browser_acceptance_state_20260724) then
    raise exception 'Day 5 browser acceptance data already exists. Run audit 023 before reseeding.';
  end if;

  if exists (
    select 1 from public.reservations r
    where r.source_reference like 'DAY5-ACCEPT-%'
  ) then
    raise exception 'Existing DAY5-ACCEPT reservations were found. Run audit 023 before reseeding.';
  end if;

  select pa.user_id
  into actor_user
  from public.platform_admins pa
  where pa.status = 'active'
  order by pa.created_at
  limit 1;

  if actor_user is null then
    raise exception 'Day 5 browser acceptance requires an active platform administrator.';
  end if;

  perform set_config('request.jwt.claim.sub', actor_user::text, true);

  -- Select the hotel/room foundation independently from rate plans. Some
  -- existing properties legitimately have zero-value legacy rate plans, so
  -- the acceptance seed must not fail only because production pricing has not
  -- yet been configured. In that case, a temporary positive test rate plan is
  -- created and removed by audit 023.
  select
    h.id,
    h.hotel_name,
    coalesce(h.timezone, 'UTC'),
    coalesce(nullif(trim(h.currency_code), ''), 'INR'),
    rm.id,
    rm.room_type_id,
    rt.name
  into
    target_hotel,
    target_hotel_name,
    hotel_timezone,
    source_currency_code,
    source_room,
    source_room_type,
    source_room_type_name
  from public.hotels h
  join public.rooms rm
    on rm.hotel_id = h.id
   and rm.room_type_id is not null
   and rm.status not in ('maintenance', 'out_of_order')
  join public.room_types rt
    on rt.hotel_id = rm.hotel_id
   and rt.id = rm.room_type_id
   and rt.is_active
  where h.status = 'active'
  order by
    case when lower(h.hotel_name) = 'vd stay inn' then 0 else 1 end,
    h.created_at,
    rm.created_at
  limit 1;

  if target_hotel is null then
    raise exception 'Day 5 seed requires an active hotel with at least one room linked to an active room type.';
  end if;

  select candidate.id
  into source_rate_plan
  from public.rate_plans candidate
  where candidate.hotel_id = target_hotel
    and candidate.room_type_id = source_room_type
    and candidate.is_active
    and candidate.base_rate > 0
  order by candidate.priority, candidate.created_at
  limit 1;

  if source_rate_plan is null then
    temporary_rate_plan_code :=
      'D5QA-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));

    insert into public.rate_plans (
      hotel_id,
      room_type_id,
      name,
      code,
      description,
      meal_plan,
      currency_code,
      base_rate,
      extra_adult_rate,
      extra_child_rate,
      minimum_stay,
      is_refundable,
      is_active,
      priority
    )
    select
      target_hotel,
      rt.id,
      'Day 5 Acceptance Rate',
      temporary_rate_plan_code,
      'Temporary positive rate used only by the controlled Day 5 browser acceptance dataset.',
      'room_only',
      source_currency_code,
      greatest(coalesce(rt.base_rate, 0), 1500)::numeric(12,2),
      greatest(coalesce(rt.extra_adult_rate, 0), 0)::numeric(12,2),
      greatest(coalesce(rt.extra_child_rate, 0), 0)::numeric(12,2),
      1,
      true,
      true,
      1
    from public.room_types rt
    where rt.hotel_id = target_hotel
      and rt.id = source_room_type
      and rt.is_active
    returning id into source_rate_plan;

    if source_rate_plan is null then
      raise exception 'Day 5 seed could not create a temporary positive rate plan for the selected room type.';
    end if;

    temporary_rate_plan_created := true;
  end if;

  test_today := (now() at time zone hotel_timezone)::date;
  test_sequence_year := extract(year from test_today)::integer;

  select exists (
    select 1
    from public.reservation_number_sequences s
    where s.hotel_id = target_hotel
      and s.sequence_year = test_sequence_year
  ) into sequence_existed;

  if sequence_existed then
    select s.last_number
    into sequence_before
    from public.reservation_number_sequences s
    where s.hotel_id = target_hotel
      and s.sequence_year = test_sequence_year;
  end if;

  for i in 1..7 loop
    generated_room_number := room_prefix || '-' || lpad(i::text, 2, '0');

    insert into public.rooms (
      hotel_id,
      room_number,
      room_type,
      room_type_id,
      status
    )
    select
      target_hotel,
      generated_room_number,
      src.room_type,
      source_room_type,
      'available'
    from public.rooms src
    where src.id = source_room
      and src.hotel_id = target_hotel
    returning id into room_id;

    room_ids := array_append(room_ids, room_id);
  end loop;

  atomic_quote := public.get_reservation_rate_quote(
    target_hotel,
    source_rate_plan,
    test_today,
    test_today + 2,
    1,
    0
  );
  atomic_deposit := least(
    500::numeric,
    (atomic_quote->>'total_amount')::numeric
  )::numeric(12,2);

  if atomic_deposit <= 0 then
    raise exception 'Day 5 deposit-transfer test requires a positive reservation total.';
  end if;

  -- 1. Atomic check-in + positive deposit-transfer candidate.
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'website',
      'source_reference', 'DAY5-ACCEPT-ATOMIC-CHECKIN',
      'arrival_date', test_today,
      'departure_date', test_today + 2,
      'expected_checkin_time', '14:00',
      'expected_checkout_time', '11:00',
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[1],
      'rate_plan_id', source_rate_plan,
      'deposit_required', atomic_deposit,
      'deposit_amount', atomic_deposit,
      'payment_method', 'upi',
      'payment_reference', 'DAY5-ACCEPT-DEPOSIT-UPI',
      'payment_notes', 'Transfer exactly once during atomic check-in',
      'internal_notes', 'Primary Day 5 atomic check-in and deposit-transfer browser test',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 5 Atomic Check-In Guest',
        'phone', '9000050501',
        'email', 'day5-atomic@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  -- 2. Two-room group booking. Check in one room and verify the other remains.
  group_created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'other',
      'source_reference', 'DAY5-ACCEPT-GROUP',
      'arrival_date', test_today,
      'departure_date', test_today + 3,
      'expected_checkin_time', '14:00',
      'expected_checkout_time', '11:00',
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[2],
      'rate_plan_id', source_rate_plan,
      'internal_notes', 'Day 5 two-room partial group check-in test',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 5 Group Booking Guest',
        'phone', '9000050502',
        'email', 'day5-group@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  group_updated_at := (group_created->>'updated_at')::timestamptz;

  group_after_add := public.add_reservation_room(
    target_hotel,
    (group_created->>'id')::uuid,
    jsonb_build_object(
      'room_type_id', source_room_type,
      'room_id', room_ids[3],
      'rate_plan_id', source_rate_plan,
      'adults', 1,
      'children', 0,
      'notes', 'Second room of the controlled Day 5 group booking'
    ),
    group_updated_at
  );

  -- 3. Upcoming confirmed arrival.
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'phone',
      'source_reference', 'DAY5-ACCEPT-UPCOMING',
      'arrival_date', test_today + 1,
      'departure_date', test_today + 3,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[4],
      'rate_plan_id', source_rate_plan,
      'internal_notes', 'Upcoming-arrivals queue verification',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 5 Upcoming Guest',
        'phone', '9000050503',
        'email', 'day5-upcoming@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  -- 4. Overdue confirmed arrival that has not checked in.
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'walk_in',
      'source_reference', 'DAY5-ACCEPT-OVERDUE',
      'arrival_date', test_today - 1,
      'departure_date', test_today + 2,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[5],
      'rate_plan_id', source_rate_plan,
      'internal_notes', 'Overdue-arrivals queue verification',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 5 Overdue Guest',
        'phone', '9000050504',
        'email', 'day5-overdue@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  -- 5. Valid unallocated tentative arrival.
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'draft',
      'booking_source', 'other',
      'source_reference', 'DAY5-ACCEPT-UNALLOCATED',
      'arrival_date', test_today,
      'departure_date', test_today + 2,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'rate_plan_id', source_rate_plan,
      'internal_notes', 'Assign a physical room before check-in',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 5 Unallocated Guest',
        'phone', '9000050505',
        'email', 'day5-unallocated@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  update public.reservations r
  set status = 'tentative', updated_by = actor_user, updated_at = now()
  where r.hotel_id = target_hotel
    and r.id = (created->>'id')::uuid;

  -- 6. Existing in-house stay. It becomes Tomorrow's departure when the
  -- business date is advanced by one day in the UI.
  inhouse_created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'website',
      'source_reference', 'DAY5-ACCEPT-INHOUSE',
      'arrival_date', test_today - 1,
      'departure_date', test_today + 1,
      'expected_checkout_time', '11:00',
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[6],
      'rate_plan_id', source_rate_plan,
      'internal_notes', 'In-house and next-business-date departure queue verification',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 5 In-House Guest',
        'phone', '9000050506',
        'email', 'day5-inhouse@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  inhouse_result := public.check_in_reservation_room(
    target_hotel,
    (inhouse_created->>'id')::uuid,
    (inhouse_created->'rooms'->0->>'id')::uuid,
    (inhouse_created->>'updated_at')::timestamptz
  );

  -- 7. Failure/rollback candidate: reservation allocation exists, but the room
  -- is made unavailable before check-in. The browser action must reject safely.
  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'other',
      'source_reference', 'DAY5-ACCEPT-OCCUPIED-REJECT',
      'arrival_date', test_today,
      'departure_date', test_today + 2,
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', room_ids[7],
      'rate_plan_id', source_rate_plan,
      'internal_notes', 'Check-in must reject because the room status is unavailable',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 5 Rollback Guest',
        'phone', '9000050507',
        'email', 'day5-rollback@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  update public.rooms rm
  set status = 'occupied'
  where rm.hotel_id = target_hotel
    and rm.id = room_ids[7];

  insert into private.day5_browser_acceptance_state_20260724 (singleton, payload)
  values (
    true,
    jsonb_build_object(
      'actor_user', actor_user,
      'hotel_id', target_hotel,
      'hotel_name', target_hotel_name,
      'hotel_timezone', hotel_timezone,
      'business_date', test_today,
      'departure_test_date', test_today + 1,
      'room_prefix', room_prefix,
      'room_type_id', source_room_type,
      'room_type_name', source_room_type_name,
      'rate_plan_id', source_rate_plan,
      'temporary_rate_plan_created', temporary_rate_plan_created,
      'temporary_rate_plan_code', temporary_rate_plan_code,
      'sequence_year', test_sequence_year,
      'sequence_existed', sequence_existed,
      'sequence_before', sequence_before,
      'atomic_reservation_number', (
        select r.reservation_number from public.reservations r
        where r.hotel_id = target_hotel and r.source_reference = 'DAY5-ACCEPT-ATOMIC-CHECKIN'
      ),
      'group_reservation_number', group_after_add->>'reservation_number',
      'upcoming_reservation_number', (
        select r.reservation_number from public.reservations r
        where r.hotel_id = target_hotel and r.source_reference = 'DAY5-ACCEPT-UPCOMING'
      ),
      'overdue_reservation_number', (
        select r.reservation_number from public.reservations r
        where r.hotel_id = target_hotel and r.source_reference = 'DAY5-ACCEPT-OVERDUE'
      ),
      'unallocated_reservation_number', (
        select r.reservation_number from public.reservations r
        where r.hotel_id = target_hotel and r.source_reference = 'DAY5-ACCEPT-UNALLOCATED'
      ),
      'inhouse_reservation_number', inhouse_created->>'reservation_number',
      'rollback_reservation_number', created->>'reservation_number',
      'atomic_deposit', atomic_deposit,
      'expected_today_arrivals', 4,
      'expected_upcoming_arrivals', 1,
      'expected_in_house', 1,
      'expected_unallocated', 1,
      'expected_overdue', 1,
      'expected_departures_on_next_date', 1
    )
  );

  return jsonb_build_object(
    'result', 'DAY 5 BROWSER ACCEPTANCE DATA CREATED',
    'hotel', target_hotel_name,
    'business_date', test_today,
    'departure_test_date', test_today + 1,
    'room_prefix', room_prefix,
    'room_type', source_room_type_name,
    'rate_plan', jsonb_build_object(
      'id', source_rate_plan,
      'temporary', temporary_rate_plan_created,
      'code', temporary_rate_plan_code
    ),
    'atomic_checkin', jsonb_build_object(
      'reservation', (
        select r.reservation_number from public.reservations r
        where r.hotel_id = target_hotel and r.source_reference = 'DAY5-ACCEPT-ATOMIC-CHECKIN'
      ),
      'room', room_prefix || '-01',
      'deposit', atomic_deposit
    ),
    'group_booking', jsonb_build_object(
      'reservation', group_after_add->>'reservation_number',
      'rooms', jsonb_build_array(room_prefix || '-02', room_prefix || '-03')
    ),
    'upcoming', room_prefix || '-04',
    'overdue', room_prefix || '-05',
    'in_house', jsonb_build_object(
      'reservation', inhouse_created->>'reservation_number',
      'room', room_prefix || '-06'
    ),
    'occupied_room_rejection', room_prefix || '-07',
    'expected_counts_today', jsonb_build_object(
      'today_arrivals', 4,
      'upcoming_arrivals', 1,
      'today_departures', 0,
      'in_house', 1,
      'unallocated', 1,
      'overdue', 1
    ),
    'expected_departures_on_next_business_date', 1,
    'cleanup_instruction', 'Run audit 023 only after all Day 5 browser tests are complete.'
  );
end;
$$;


ALTER FUNCTION "private"."seed_day5_browser_acceptance_20260724"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."seed_day5_checkout_smoke_20260724"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user uuid;
  target_hotel uuid;
  target_hotel_name text;
  other_hotel uuid;
  other_hotel_name text;
  hotel_timezone text;
  currency_code text;
  source_room uuid;
  source_room_type uuid;
  source_room_type_name text;
  source_rate_plan uuid;
  temporary_rate_plan_created boolean := false;
  temporary_rate_plan_code text;
  test_today date;
  test_year integer;
  sequence_existed boolean := false;
  sequence_before bigint;
  room_prefix text := 'D5CO-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
  smoke_room uuid;
  created jsonb;
  rate_quote jsonb;
  deposit_amount numeric(12,2);
begin
  if exists (select 1 from private.day5_checkout_smoke_state_20260724) then
    raise exception 'Day 5 checkout smoke data already exists. Run audit 029 before reseeding.';
  end if;

  if exists (
    select 1 from public.reservations
    where source_reference = 'DAY5-CHECKOUT-SMOKE'
  ) then
    raise exception 'Existing DAY5-CHECKOUT-SMOKE data was found. Run audit 029 before reseeding.';
  end if;

  select pa.user_id
  into actor_user
  from public.platform_admins pa
  where pa.status = 'active'
  order by pa.created_at
  limit 1;

  if actor_user is null then
    raise exception 'An active Platform Admin is required for the controlled checkout smoke test.';
  end if;

  perform set_config('request.jwt.claim.sub', actor_user::text, true);

  select
    h.id,
    h.hotel_name,
    coalesce(h.timezone, 'UTC'),
    coalesce(nullif(trim(h.currency_code), ''), 'INR'),
    rm.id,
    rm.room_type_id,
    rt.name
  into
    target_hotel,
    target_hotel_name,
    hotel_timezone,
    currency_code,
    source_room,
    source_room_type,
    source_room_type_name
  from public.hotels h
  join public.rooms rm
    on rm.hotel_id = h.id
   and rm.room_type_id is not null
   and rm.status not in ('maintenance', 'out_of_order')
  join public.room_types rt
    on rt.hotel_id = rm.hotel_id
   and rt.id = rm.room_type_id
   and rt.is_active
  where h.status = 'active'
  order by
    case when lower(h.hotel_name) = 'vd stay inn' then 0 else 1 end,
    h.created_at,
    rm.created_at
  limit 1;

  if target_hotel is null then
    raise exception 'The checkout smoke seed requires an active hotel, room and room type.';
  end if;

  select h.id, h.hotel_name
  into other_hotel, other_hotel_name
  from public.hotels h
  where h.status = 'active'
    and h.id <> target_hotel
  order by h.created_at
  limit 1;

  select rp.id
  into source_rate_plan
  from public.rate_plans rp
  where rp.hotel_id = target_hotel
    and rp.room_type_id = source_room_type
    and rp.is_active
    and rp.base_rate > 0
  order by rp.priority, rp.created_at
  limit 1;

  if source_rate_plan is null then
    temporary_rate_plan_code :=
      'D5CO-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));

    insert into public.rate_plans (
      hotel_id,
      room_type_id,
      name,
      code,
      description,
      meal_plan,
      currency_code,
      base_rate,
      extra_adult_rate,
      extra_child_rate,
      minimum_stay,
      is_refundable,
      is_active,
      priority
    ) values (
      target_hotel,
      source_room_type,
      'Day 5 Checkout Smoke Rate',
      temporary_rate_plan_code,
      'Temporary rate used only for the controlled Day 5 booking-to-checkout smoke test.',
      'room_only',
      currency_code,
      1500,
      0,
      0,
      1,
      true,
      true,
      1
    ) returning id into source_rate_plan;

    temporary_rate_plan_created := true;
  end if;

  test_today := (now() at time zone hotel_timezone)::date;
  test_year := extract(year from test_today)::integer;

  select exists (
    select 1
    from public.reservation_number_sequences s
    where s.hotel_id = target_hotel
      and s.sequence_year = test_year
  ) into sequence_existed;

  if sequence_existed then
    select s.last_number
    into sequence_before
    from public.reservation_number_sequences s
    where s.hotel_id = target_hotel
      and s.sequence_year = test_year;
  end if;

  insert into public.rooms (
    hotel_id,
    room_number,
    room_type,
    room_type_id,
    status
  )
  select
    target_hotel,
    room_prefix || '-01',
    src.room_type,
    source_room_type,
    'available'
  from public.rooms src
  where src.hotel_id = target_hotel
    and src.id = source_room
  returning id into smoke_room;

  rate_quote := public.get_reservation_rate_quote(
    target_hotel,
    source_rate_plan,
    test_today,
    test_today + 1,
    1,
    0
  );

  deposit_amount := least(
    500::numeric,
    (rate_quote->>'total_amount')::numeric
  )::numeric(12,2);

  if deposit_amount <= 0 then
    raise exception 'The checkout smoke test requires a positive reservation total and deposit.';
  end if;

  created := public.create_reservation(
    target_hotel,
    jsonb_build_object(
      'status', 'confirmed',
      'booking_source', 'website',
      'source_reference', 'DAY5-CHECKOUT-SMOKE',
      'arrival_date', test_today,
      'departure_date', test_today + 1,
      'expected_checkin_time', '14:00',
      'expected_checkout_time', '11:00',
      'adults', 1,
      'children', 0,
      'room_type_id', source_room_type,
      'room_id', smoke_room,
      'rate_plan_id', source_rate_plan,
      'deposit_required', deposit_amount,
      'deposit_amount', deposit_amount,
      'payment_method', 'upi',
      'payment_reference', 'D5CO-DEPOSIT-500',
      'payment_notes', 'Controlled deposit for booking-to-checkout smoke test',
      'internal_notes', 'Day 5 final reservation-to-checkout acceptance record',
      'guest', jsonb_build_object(
        'full_name', 'StayQR Day 5 Checkout Smoke Guest',
        'phone', '9000050599',
        'email', 'day5-checkout-smoke@stayqr.invalid',
        'preferred_language', 'english'
      )
    )
  );

  insert into private.day5_checkout_smoke_state_20260724 (singleton, payload)
  values (
    true,
    jsonb_build_object(
      'actor_user', actor_user,
      'hotel_id', target_hotel,
      'hotel_name', target_hotel_name,
      'other_hotel_id', other_hotel,
      'other_hotel_name', other_hotel_name,
      'hotel_timezone', hotel_timezone,
      'business_date', test_today,
      'departure_test_date', test_today + 1,
      'room_id', smoke_room,
      'room_number', room_prefix || '-01',
      'room_prefix', room_prefix,
      'room_type_id', source_room_type,
      'room_type_name', source_room_type_name,
      'rate_plan_id', source_rate_plan,
      'temporary_rate_plan_created', temporary_rate_plan_created,
      'temporary_rate_plan_code', temporary_rate_plan_code,
      'sequence_year', test_year,
      'sequence_existed', sequence_existed,
      'sequence_before', sequence_before,
      'reservation_id', (created->>'id')::uuid,
      'reservation_number', created->>'reservation_number',
      'reservation_room_id', (created->'rooms'->0->>'id')::uuid,
      'guest_id', (created->'guest'->>'id')::uuid,
      'deposit_amount', deposit_amount,
      'expected_total', (created->>'total_amount')::numeric
    )
  );

  return jsonb_build_object(
    'result', 'DAY 5 BOOKING-TO-CHECKOUT SMOKE DATA CREATED',
    'hotel', target_hotel_name,
    'other_hotel_for_isolation', other_hotel_name,
    'business_date', test_today,
    'departure_test_date', test_today + 1,
    'reservation', created->>'reservation_number',
    'guest', created->'guest'->>'full_name',
    'room', room_prefix || '-01',
    'room_type', source_room_type_name,
    'total', (created->>'total_amount')::numeric,
    'deposit', deposit_amount,
    'remaining_expected_at_checkout',
      greatest((created->>'total_amount')::numeric - deposit_amount, 0),
    'rate_plan', jsonb_build_object(
      'id', source_rate_plan,
      'temporary', temporary_rate_plan_created,
      'code', temporary_rate_plan_code
    ),
    'browser_instruction',
      'Check in this reservation in Arrivals & Departures, then use Guests > Final Bill & Checkout. Do not run audit 028 until checkout succeeds.'
  );
end;
$$;


ALTER FUNCTION "private"."seed_day5_checkout_smoke_20260724"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."seed_hotel_configuration_defaults_internal"("target_hotel_id" "uuid", "actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  seed_row record;
  amenities_inserted integer := 0;
  request_types_inserted integer := 0;
  menu_result jsonb;
begin
  if target_hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = target_hotel_id
     )
  then
    raise exception 'Unknown hotel.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:seed-configuration-defaults:'
      || target_hotel_id::text
    )
  );

  for seed_row in
    select *
    from (
      values
        ('Wi-Fi'::text, 'wifi'::text, 'connectivity'::text,
         'Wireless internet access.', 'wifi'::text, 10),
        ('Air Conditioning'::text, 'air-conditioning'::text,
         'room'::text, 'In-room air conditioning.',
         'air-conditioning'::text, 20),
        ('Hot Water'::text, 'hot-water'::text, 'bathroom'::text,
         'Hot-water availability.', 'droplets'::text, 30),
        ('Television'::text, 'television'::text, 'entertainment'::text,
         'In-room television.', 'tv'::text, 40),
        ('Housekeeping'::text, 'housekeeping'::text, 'service'::text,
         'Housekeeping support.', 'sparkles'::text, 50)
    ) as defaults(
      name,
      code,
      category,
      description,
      icon,
      sort_order
    )
  loop
    if not exists (
      select 1
      from public.amenities a
      where a.hotel_id = target_hotel_id
        and (
          upper(trim(a.code)) = upper(seed_row.code)
          or lower(trim(a.name)) = lower(seed_row.name)
        )
    ) then
      insert into public.amenities (
        hotel_id,
        name,
        code,
        category,
        description,
        icon,
        guest_visible,
        is_active,
        sort_order,
        created_by,
        updated_by,
        created_at,
        updated_at
      ) values (
        target_hotel_id,
        seed_row.name,
        seed_row.code,
        seed_row.category,
        seed_row.description,
        seed_row.icon,
        true,
        true,
        seed_row.sort_order,
        actor_user_id,
        actor_user_id,
        now(),
        now()
      );

      amenities_inserted := amenities_inserted + 1;
    end if;
  end loop;

  for seed_row in
    select *
    from (
      values
        ('Housekeeping'::text, 'housekeeping'::text,
         'Housekeeping assistance.', 'normal'::text, 20, 10),
        ('Towel'::text, 'towel'::text,
         'Request additional towels.', 'normal'::text, 15, 20),
        ('Water'::text, 'water'::text,
         'Request drinking water.', 'normal'::text, 10, 30),
        ('Checkout Request'::text, 'checkout-request'::text,
         'Request checkout assistance.', 'high'::text, 15, 40)
    ) as defaults(
      name,
      code,
      description,
      default_priority,
      default_estimated_minutes,
      sort_order
    )
  loop
    if not exists (
      select 1
      from public.service_request_types srt
      where srt.hotel_id = target_hotel_id
        and (
          upper(trim(srt.code)) = upper(seed_row.code)
          or lower(trim(srt.name)) = lower(seed_row.name)
        )
    ) then
      insert into public.service_request_types (
        hotel_id,
        name,
        code,
        description,
        default_priority,
        default_estimated_minutes,
        guest_visible,
        is_active,
        sort_order,
        created_by,
        updated_by,
        created_at,
        updated_at
      ) values (
        target_hotel_id,
        seed_row.name,
        seed_row.code,
        seed_row.description,
        seed_row.default_priority,
        seed_row.default_estimated_minutes,
        true,
        true,
        seed_row.sort_order,
        actor_user_id,
        actor_user_id,
        now(),
        now()
      );

      request_types_inserted := request_types_inserted + 1;
    end if;
  end loop;

  menu_result :=
    private.seed_hotel_menu_defaults_internal(
      target_hotel_id,
      actor_user_id
    );

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'amenities_inserted', amenities_inserted,
    'request_types_inserted', request_types_inserted,
    'menu', menu_result
  );
end;
$$;


ALTER FUNCTION "private"."seed_hotel_configuration_defaults_internal"("target_hotel_id" "uuid", "actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."seed_hotel_menu_defaults_internal"("target_hotel_id" "uuid", "actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  seed_row record;
  inserted_count integer := 0;
begin
  if target_hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = target_hotel_id
     )
  then
    raise exception 'Unknown hotel.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:seed-menu-defaults:' || target_hotel_id::text
    )
  );

  for seed_row in
    select *
    from (
      values
        ('Beverages'::text, 'beverages'::text,
         'Hot and cold beverages.', 10),
        ('Breakfast'::text, 'breakfast'::text,
         'Breakfast and morning service.', 20),
        ('Meal'::text, 'meal'::text,
         'Lunch, dinner and all-day meals.', 30)
    ) as defaults(name, code, description, sort_order)
  loop
    if not exists (
      select 1
      from public.menu_categories mc
      where mc.hotel_id = target_hotel_id
        and (
          upper(trim(mc.code)) = upper(seed_row.code)
          or lower(trim(mc.name)) = lower(seed_row.name)
        )
    ) then
      insert into public.menu_categories (
        hotel_id,
        name,
        code,
        description,
        sort_order,
        is_active,
        created_by,
        updated_by,
        created_at,
        updated_at
      ) values (
        target_hotel_id,
        seed_row.name,
        seed_row.code,
        seed_row.description,
        seed_row.sort_order,
        true,
        actor_user_id,
        actor_user_id,
        now(),
        now()
      );

      inserted_count := inserted_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'menu_categories_inserted', inserted_count
  );
end;
$$;


ALTER FUNCTION "private"."seed_hotel_menu_defaults_internal"("target_hotel_id" "uuid", "actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."seed_new_hotel_configuration_defaults_20260727"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.seed_hotel_configuration_defaults_internal(
    new.id,
    (select auth.uid())
  );

  return new;
