CREATE OR REPLACE FUNCTION "private"."sync_guest_access_from_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_expiry timestamptz;
begin
  if tg_op = 'DELETE' then
    update public.guest_access_tokens
    set status = 'revoked',
        revoked_at = now(),
        revocation_reason = 'Guest session deleted',
        updated_at = now()
    where guest_session_id = old.id
      and status = 'active';

    return old;
  end if;

  session_expiry := coalesce(new.extended_until, new.checkout_time);

  if new.status = 'active' and session_expiry > now() then
    if tg_op = 'INSERT' then
      perform private.issue_guest_access_token(new.id, false, null);
    elsif old.status is distinct from new.status
       or old.hotel_id is distinct from new.hotel_id
       or old.room_id is distinct from new.room_id
       or old.guest_id is distinct from new.guest_id
       or old.checkout_time is distinct from new.checkout_time
       or old.extended_until is distinct from new.extended_until then
      perform private.issue_guest_access_token(
        new.id,
        true,
        'Guest stay access-defining details changed'
      );
    end if;
  else
    update public.guest_access_tokens
    set status = case when session_expiry <= now() then 'expired' else 'revoked' end,
        revoked_at = coalesce(revoked_at, now()),
        revocation_reason = case
          when session_expiry <= now() then 'Guest stay expired'
          else 'Guest stay is no longer active'
        end,
        updated_at = now()
    where guest_session_id = new.id
      and status = 'active';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."sync_guest_access_from_session"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."sync_guest_session_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  hotel_timezone text;
  starts_date date;
  ends_date date;
begin
  if tg_op = 'DELETE' then
    delete from public.room_inventory_allocations
    where guest_session_id = old.id;

    return old;
  end if;

  -- Reservation-linked stays keep the reservation allocation as the source
  -- of truth, preventing a duplicate overlapping allocation for the same stay.
  if new.reservation_room_id is not null then
    update public.room_inventory_allocations
    set
      status = 'released',
      released_at = coalesce(released_at, now()),
      updated_at = now()
    where guest_session_id = new.id
      and status = 'active';

    return new;
  end if;

  if new.status <> 'active' or new.room_id is null then
    update public.room_inventory_allocations
    set
      status = 'released',
      released_at = coalesce(released_at, now()),
      updated_at = now()
    where guest_session_id = new.id
      and status = 'active';

    return new;
  end if;

  select h.timezone
  into hotel_timezone
  from public.hotels h
  where h.id = new.hotel_id;

  if hotel_timezone is null then
    raise exception
      'Hotel timezone is missing for guest session %.',
      new.id;
  end if;

  starts_date :=
    (new.checkin_time at time zone hotel_timezone)::date;

  ends_date :=
    (coalesce(new.extended_until, new.checkout_time)
      at time zone hotel_timezone)::date;

  if ends_date <= starts_date then
    ends_date := starts_date + 1;
  end if;

  insert into public.room_inventory_allocations (
    hotel_id,
    room_id,
    allocation_type,
    guest_session_id,
    starts_on,
    ends_on,
    status,
    released_at
  )
  values (
    new.hotel_id,
    new.room_id,
    'stay',
    new.id,
    starts_date,
    ends_date,
    'active',
    null
  )
  on conflict (guest_session_id)
    where guest_session_id is not null
  do update
  set
    room_id = excluded.room_id,
    starts_on = excluded.starts_on,
    ends_on = excluded.ends_on,
    status = 'active',
    released_at = null,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "private"."sync_guest_session_allocation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."sync_menu_item_category_20260727"() RETURNS "trigger"
