CREATE OR REPLACE FUNCTION "private"."sync_reservation_deposit_total"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    perform private.recalculate_reservation_deposit_total(
      new.hotel_id,
      new.reservation_id
    );

    return new;
  end if;

  if tg_op = 'DELETE' then
    perform private.recalculate_reservation_deposit_total(
      old.hotel_id,
      old.reservation_id
    );

    return old;
  end if;

  -- UPDATE: always refresh the new parent.
  perform private.recalculate_reservation_deposit_total(
    new.hotel_id,
    new.reservation_id
  );

  -- Also refresh the old parent if a trusted future workflow moves a payment.
  if old.hotel_id is distinct from new.hotel_id
     or old.reservation_id is distinct from new.reservation_id
  then
    perform private.recalculate_reservation_deposit_total(
      old.hotel_id,
      old.reservation_id
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."sync_reservation_deposit_total"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."sync_reservation_from_guest_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  active_room_count integer;
  unfinished_room_count integer;
begin
  if new.reservation_room_id is null then return new; end if;

  if new.status = 'active' then
    update public.reservation_rooms
    set status = 'checked_in'
    where hotel_id = new.hotel_id
      and id = new.reservation_room_id
      and status = 'confirmed';

    update public.reservations
    set status = 'checked_in'
    where hotel_id = new.hotel_id
      and id = new.reservation_id
      and status = 'confirmed';

    update public.rooms
    set status = 'occupied'
    where hotel_id = new.hotel_id
      and id = new.room_id;

    return new;
  end if;

  if old.status = 'active' and new.status in ('completed', 'checked_out', 'expired') then
    update public.reservation_rooms
    set status = 'checked_out'
    where hotel_id = new.hotel_id
      and id = new.reservation_room_id
      and status = 'checked_in';

    update public.rooms
    set status = 'cleaning'
    where hotel_id = new.hotel_id
      and id = new.room_id
      and status = 'occupied';

    select
      count(*) filter (where rr.status = 'checked_in')::integer,
      count(*) filter (where rr.status not in ('checked_out', 'cancelled', 'released'))::integer
    into active_room_count, unfinished_room_count
    from public.reservation_rooms rr
    where rr.hotel_id = new.hotel_id
      and rr.reservation_id = new.reservation_id;

    if active_room_count = 0 and unfinished_room_count = 0 then
      update public.reservations
      set status = 'checked_out'
      where hotel_id = new.hotel_id
        and id = new.reservation_id
        and status = 'checked_in';
    end if;

    perform private.write_activity_log(
      new.hotel_id,
      'reservation.room_checked_out',
      'reservation',
      new.reservation_id,
      'A reservation room completed checkout.',
      jsonb_build_object('guest_session_status', old.status),
      jsonb_build_object('guest_session_status', new.status),
      jsonb_build_object(
        'reservation_room_id', new.reservation_room_id,
        'guest_session_id', new.id,
        'room_id', new.room_id
      )
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."sync_reservation_from_guest_session"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."sync_reservation_header_allocations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status in ('tentative', 'confirmed', 'checked_in') then
    insert into public.room_inventory_allocations (
      hotel_id,
      room_id,
      allocation_type,
      reservation_room_id,
      starts_on,
      ends_on,
      status,
      released_at
    )
    select
      rr.hotel_id,
      rr.room_id,
      'reservation',
      rr.id,
      new.arrival_date,
      new.departure_date,
      'active',
      null
    from public.reservation_rooms rr
    where rr.hotel_id = new.hotel_id
      and rr.reservation_id = new.id
      and rr.room_id is not null
      and rr.status in ('held', 'confirmed', 'checked_in')
    on conflict (reservation_room_id)
      where reservation_room_id is not null
    do update
    set
      room_id = excluded.room_id,
      starts_on = excluded.starts_on,
      ends_on = excluded.ends_on,
      status = 'active',
      released_at = null,
      updated_at = now();
  else
    update public.room_inventory_allocations ria
    set
      status = 'released',
      released_at = coalesce(ria.released_at, now()),
      updated_at = now()
    where ria.allocation_type = 'reservation'
      and ria.status = 'active'
      and exists (
        select 1
        from public.reservation_rooms rr
        where rr.id = ria.reservation_room_id
          and rr.hotel_id = new.hotel_id
          and rr.reservation_id = new.id
      );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."sync_reservation_header_allocations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."sync_reservation_room_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reservation_row public.reservations%rowtype;
  should_allocate boolean;
begin
  if tg_op = 'DELETE' then
    delete from public.room_inventory_allocations
    where reservation_room_id = old.id;

    return old;
  end if;

  select *
  into reservation_row
  from public.reservations r
  where r.id = new.reservation_id
    and r.hotel_id = new.hotel_id;

  if not found then
    raise exception
      'Reservation % does not belong to hotel %.',
      new.reservation_id,
      new.hotel_id;
  end if;

  should_allocate :=
    new.room_id is not null
    and reservation_row.status in ('tentative', 'confirmed', 'checked_in')
    and new.status in ('held', 'confirmed', 'checked_in');

  if not should_allocate then
    update public.room_inventory_allocations
    set
      status = 'released',
      released_at = coalesce(released_at, now()),
      updated_at = now()
    where reservation_room_id = new.id
      and status = 'active';

    return new;
  end if;

  insert into public.room_inventory_allocations (
    hotel_id,
    room_id,
    allocation_type,
    reservation_room_id,
    starts_on,
    ends_on,
    status,
    released_at
  )
  values (
    new.hotel_id,
    new.room_id,
    'reservation',
    new.id,
    reservation_row.arrival_date,
    reservation_row.departure_date,
    'active',
    null
  )
  on conflict (reservation_room_id)
    where reservation_room_id is not null
  do update
  set
    room_id = excluded.room_id,
    starts_on = excluded.starts_on,
    ends_on = excluded.ends_on,
    status = 'active',
    released_at = null,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "private"."sync_reservation_room_allocation"() OWNER TO "postgres";


