CREATE OR REPLACE FUNCTION "private"."validate_reservation_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status = 'cancelled' and new.cancelled_at is null then
      new.cancelled_at := now();
      new.cancelled_by := coalesce(new.cancelled_by, auth.uid());
    end if;

    if new.status = 'no_show' and new.no_show_at is null then
      new.no_show_at := now();
    end if;

    return new;
  end if;

  if new.status = old.status then
    return new;
  end if;

  if not (
    (old.status = 'draft'
      and new.status in ('tentative', 'confirmed', 'cancelled'))
    or
    (old.status = 'tentative'
      and new.status in ('confirmed', 'cancelled', 'no_show'))
    or
    (old.status = 'confirmed'
      and new.status in ('checked_in', 'cancelled', 'no_show'))
    or
    (old.status = 'checked_in'
      and new.status = 'checked_out')
  ) then
    raise exception
      'Invalid reservation status transition: % -> %',
      old.status,
      new.status;
  end if;

  if new.status = 'cancelled' then
    new.cancelled_at := coalesce(new.cancelled_at, now());
    new.cancelled_by := coalesce(new.cancelled_by, auth.uid());
  end if;

  if new.status = 'no_show' then
    new.no_show_at := coalesce(new.no_show_at, now());
  end if;

  new.updated_by := coalesce(auth.uid(), new.updated_by);
  return new;
end;
$$;


ALTER FUNCTION "private"."validate_reservation_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."write_activity_log"("target_hotel_id" "uuid", "target_action" "text", "target_entity_type" "text", "target_entity_id" "uuid", "target_description" "text" DEFAULT NULL::"text", "target_before_data" "jsonb" DEFAULT NULL::"jsonb", "target_after_data" "jsonb" DEFAULT NULL::"jsonb", "target_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
