CREATE OR REPLACE FUNCTION "public"."activate_hotel_trial"("target_hotel_id" "uuid", "target_plan_id" "uuid", "trial_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  plan_row public.subscription_plans%rowtype;
  existing_row public.hotel_subscriptions%rowtype;
  created_row public.hotel_subscriptions%rowtype;
  start_at timestamptz := now();
  finish_at timestamptz;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if target_hotel_id is null or target_plan_id is null then
    raise exception 'Hotel and subscription plan are required.';
  end if;

  if trial_days is null or trial_days < 1 or trial_days > 30 then
    raise exception 'Trial duration must be between 1 and 30 days.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('stayqr:hotel-trial:' || target_hotel_id::text)
  );

  if not (
    private.is_platform_admin()
    or private.user_has_permission(target_hotel_id, 'hotel.manage')
    or exists (
      select 1
      from public.hotel_onboarding ho
      where ho.hotel_id = target_hotel_id
        and ho.owner_user_id = actor_user_id
    )
  ) then
    raise exception 'Trial activation access denied.';
  end if;

  select sp.*
  into plan_row
  from public.subscription_plans sp
  where sp.id = target_plan_id
    and sp.status = 'active'
  for share;

  if not found then
    raise exception 'The selected subscription plan is not active.';
  end if;

  select hsub.*
  into existing_row
  from public.hotel_subscriptions hsub
  where hsub.hotel_id = target_hotel_id
    and hsub.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
  order by hsub.created_at desc
  limit 1
  for update;

  if found then
    if existing_row.status in ('trial', 'trialing')
       and existing_row.plan_id = target_plan_id
       and coalesce(existing_row.trial_ends_at, existing_row.end_date) > now()
    then
      return jsonb_build_object(
        'hotel_id', target_hotel_id,
        'subscription_id', existing_row.id,
        'plan_id', existing_row.plan_id,
        'status', existing_row.status,
        'trial_started_at', coalesce(
          existing_row.trial_started_at,
          existing_row.start_date
        ),
        'trial_ends_at', coalesce(
          existing_row.trial_ends_at,
          existing_row.end_date
        ),
        'idempotent', true
      );
    end if;

    raise exception
      'This hotel already has a current subscription with status %.',
      existing_row.status;
  end if;

  if exists (
    select 1
    from public.hotel_subscriptions history
    where history.hotel_id = target_hotel_id
      and (
        history.trial_started_at is not null
        or history.status in ('trial', 'trialing')
      )
  ) then
    raise exception 'The one-time hotel trial has already been used.';
  end if;

  finish_at := start_at + make_interval(days => trial_days);

  insert into public.hotel_subscriptions (
    hotel_id,
    plan_id,
    status,
    start_date,
    end_date,
    created_at,
    trial_started_at,
    trial_ends_at,
    activated_at,
    metadata,
    updated_at
  ) values (
    target_hotel_id,
    target_plan_id,
    'trialing',
    start_at,
    finish_at,
    start_at,
    start_at,
    finish_at,
    null,
    jsonb_build_object(
      'source', 'day8_onboarding',
      'trial_days', trial_days,
      'activated_by', actor_user_id
    ),
    start_at
  )
  returning * into created_row;

  update public.hotels h
  set
    subscription_status = 'trialing',
    updated_at = now()
  where h.id = target_hotel_id;

  update public.hotel_onboarding ho
  set
    completed_steps = array(
      select distinct completed_step
      from unnest(
        coalesce(ho.completed_steps, '{}'::text[])
        || array['subscription']::text[]
      ) completed_step
      order by completed_step
    ),
    last_saved_at = now(),
    updated_by = actor_user_id,
    version = ho.version + 1
  where ho.hotel_id = target_hotel_id;

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', created_row.id,
    'plan_id', created_row.plan_id,
    'status', created_row.status,
    'trial_started_at', created_row.trial_started_at,
    'trial_ends_at', created_row.trial_ends_at,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION "public"."activate_hotel_trial"("target_hotel_id" "uuid", "target_plan_id" "uuid", "trial_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_my_staff_invitation"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := (select auth.uid());
  current_email text := lower(coalesce((select auth.jwt() ->> 'email'), ''));
  activated_staff integer := 0;
  activated_memberships integer := 0;
begin
  if current_user_id is null or current_email = '' then
    raise exception 'Authentication is required.' using errcode = '28000';
  end if;

  update public.staff s
  set
    status = 'active',
    accepted_at = coalesce(s.accepted_at, now()),
    disabled_at = null,
    updated_by = current_user_id
  where s.auth_user_id = current_user_id
    and lower(s.email) = current_email
    and s.status = 'invited';
  get diagnostics activated_staff = row_count;

  update public.hotel_users hu
  set
    status = 'active',
    accepted_at = coalesce(hu.accepted_at, now()),
    disabled_at = null
  where hu.user_id = current_user_id
    and lower(hu.email) = current_email
    and hu.status = 'invited';
  get diagnostics activated_memberships = row_count;

  return jsonb_build_object(
    'staff_activated', activated_staff,
    'memberships_activated', activated_memberships
  );
end;
$$;


ALTER FUNCTION "public"."activate_my_staff_invitation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_paid_subscription"("target_hotel_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_user_id uuid := (select auth.uid());
  caller_role text :=
    current_setting('request.jwt.claim.role', true);
  actor_is_platform boolean :=
    actor_user_id is not null
    and private.is_platform_admin();
  existing_result jsonb;
  action_key text;
  plan_id_value uuid;
  plan_row public.subscription_plans%rowtype;
  subscription_row public.hotel_subscriptions%rowtype;
  subscription_found boolean := false;
  provider_payment_link_value text;
  linked_subscription_id uuid;
  payment_link_found boolean := false;
  old_status_value text;
  old_plan_id_value uuid;
  billing_cycle_value text;
  currency_value text;
  provider_value text;
  amount_value bigint;
  period_start_value timestamptz;
  period_end_value timestamptz;
  result jsonb;
begin
  if not (actor_is_platform or caller_role = 'service_role') then
    raise exception
      'Platform Admin or service-role access required.';
  end if;

  if target_hotel_id is null
     or payload is null
     or jsonb_typeof(payload) <> 'object'
  then
    raise exception
      'Hotel and paid-subscription payload are required.';
  end if;

  action_key :=
    nullif(trim(payload ->> 'idempotency_key'), '');
  existing_result :=
    private.subscription_action_result_20260728(action_key);

  if existing_result is not null then
    return existing_result
      || jsonb_build_object('idempotent', true);
  end if;

  plan_id_value :=
    nullif(trim(payload ->> 'plan_id'), '')::uuid;
  billing_cycle_value :=
    coalesce(
      nullif(trim(payload ->> 'billing_cycle'), ''),
      'monthly'
    );
  currency_value := upper(
    coalesce(
      nullif(trim(payload ->> 'currency_code'), ''),
      'INR'
    )
  );
  provider_value :=
    coalesce(
      nullif(trim(payload ->> 'provider'), ''),
      'manual'
    );
  provider_payment_link_value :=
    nullif(trim(payload ->> 'provider_payment_link_id'), '');
  amount_value :=
    coalesce(
      nullif(trim(payload ->> 'amount_minor'), '')::bigint,
      0
    );
  period_start_value :=
    coalesce(
      nullif(
        trim(payload ->> 'current_period_start'),
        ''
      )::timestamptz,
      now()
    );
  period_end_value :=
    nullif(
      trim(payload ->> 'current_period_end'),
      ''
    )::timestamptz;

  if plan_id_value is null
     or period_end_value is null
     or period_end_value <= period_start_value
  then
    raise exception
      'Active plan and a valid paid period are required.';
  end if;

  if billing_cycle_value not in ('monthly', 'annual') then
    raise exception
      'Paid billing cycle must be monthly or annual.';
  end if;

  if amount_value < 0
     or currency_value !~ '^[A-Z]{3}$'
  then
    raise exception
      'Paid amount and currency are invalid.';
  end if;

  select sp.*
  into plan_row
  from public.subscription_plans sp
  where sp.id = plan_id_value
    and sp.status = 'active'
  for share;

  if not found then
    raise exception 'Selected plan is not active.';
  end if;

  perform
    private.assert_subscription_capacity_internal_20260728(
      target_hotel_id,
      plan_id_value,
      0,
      0
    );

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:activate-paid:' || target_hotel_id::text
    )
  );

  select hs.*
  into subscription_row
  from public.hotel_subscriptions hs
  where hs.hotel_id = target_hotel_id
    and hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
  order by
    coalesce(hs.updated_at, hs.created_at) desc,
    hs.created_at desc,
    hs.id desc
  limit 1
  for update;

  subscription_found := found;

  perform set_config(
    'stayqr.subscription_event_source',
    'activate_paid_subscription',
    true
  );

  if subscription_found then
    old_status_value := subscription_row.status;
    old_plan_id_value := subscription_row.plan_id;

    update public.hotel_subscriptions hs
    set
      plan_id = plan_id_value,
      status = 'active',
      billing_mode = 'paid',
      billing_cycle = billing_cycle_value,
      currency_code = currency_value,
      amount_minor = amount_value,
      provider = provider_value,
      provider_customer_id = coalesce(
        nullif(trim(payload ->> 'provider_customer_id'), ''),
        hs.provider_customer_id
      ),
      provider_subscription_id = coalesce(
        nullif(
          trim(payload ->> 'provider_subscription_id'),
          ''
        ),
        hs.provider_subscription_id
      ),
      provider_payment_link_id = coalesce(
        nullif(
          trim(payload ->> 'provider_payment_link_id'),
          ''
        ),
        hs.provider_payment_link_id
      ),
      provider_status = coalesce(
        nullif(trim(payload ->> 'provider_status'), ''),
        'active'
      ),
      provider_metadata =
        coalesce(hs.provider_metadata, '{}'::jsonb)
        || coalesce(payload -> 'provider_metadata', '{}'::jsonb),
      start_date = period_start_value,
      end_date = period_end_value,
      current_period_start = period_start_value,
      current_period_end = period_end_value,
      grace_ends_at = null,
      activated_at = coalesce(hs.activated_at, now()),
      suspended_at = null,
      reactivated_at = case
        when old_status_value = 'suspended'
          then now()
        else hs.reactivated_at
      end,
      cancelled_at = null,
      cancellation_reason = null,
      last_payment_at = coalesce(
        nullif(
          trim(payload ->> 'last_payment_at'),
          ''
        )::timestamptz,
        now()
      ),
      metadata = coalesce(hs.metadata, '{}'::jsonb)
        || coalesce(payload -> 'metadata', '{}'::jsonb)
        || jsonb_build_object(
          'last_paid_activation',
          jsonb_build_object(
            'activated_at', now(),
            'activated_by', actor_user_id,
            'source_role', caller_role
          )
        ),
      updated_at = now()
    where hs.id = subscription_row.id
    returning * into subscription_row;
  else
    old_status_value := null;
    old_plan_id_value := null;

    insert into public.hotel_subscriptions (
      hotel_id,
      plan_id,
      status,
      start_date,
      end_date,
      created_at,
      activated_at,
      metadata,
      updated_at,
      billing_mode,
      billing_cycle,
      currency_code,
      amount_minor,
      provider,
      provider_customer_id,
      provider_subscription_id,
      provider_payment_link_id,
      provider_status,
      provider_metadata,
      current_period_start,
      current_period_end,
      last_payment_at
    ) values (
      target_hotel_id,
      plan_id_value,
      'active',
      period_start_value,
      period_end_value,
      now(),
      now(),
      coalesce(payload -> 'metadata', '{}'::jsonb)
        || jsonb_build_object(
          'source', 'activate_paid_subscription',
          'activated_by', actor_user_id,
          'source_role', caller_role
        ),
      now(),
      'paid',
      billing_cycle_value,
      currency_value,
      amount_value,
      provider_value,
      nullif(trim(payload ->> 'provider_customer_id'), ''),
      nullif(
        trim(payload ->> 'provider_subscription_id'),
        ''
      ),
      nullif(
        trim(payload ->> 'provider_payment_link_id'),
        ''
      ),
      coalesce(
        nullif(trim(payload ->> 'provider_status'), ''),
        'active'
      ),
      coalesce(
        payload -> 'provider_metadata',
        '{}'::jsonb
      ),
      period_start_value,
      period_end_value,
      coalesce(
        nullif(
          trim(payload ->> 'last_payment_at'),
          ''
        )::timestamptz,
        now()
      )
    )
    returning * into subscription_row;
  end if;

  if subscription_row.id is null
     or subscription_row.status <> 'active'
     or subscription_row.billing_mode <> 'paid'
     or subscription_row.plan_id is distinct from plan_id_value
  then
    raise exception
      'Paid subscription activation did not produce a valid active paid subscription.';
  end if;

  if provider_payment_link_value is not null then
    select spl.subscription_id
    into linked_subscription_id
    from public.subscription_payment_links spl
    where spl.hotel_id = target_hotel_id
      and spl.provider = provider_value
      and spl.provider_link_id = provider_payment_link_value
    limit 1
    for update;

    payment_link_found := found;

    if payment_link_found
       and linked_subscription_id is not null
       and linked_subscription_id <> subscription_row.id
    then
      raise exception
        'Provider payment link is already linked to another subscription.';
    end if;

    if payment_link_found then
      update public.subscription_payment_links spl
      set
        subscription_id = subscription_row.id,
        updated_at = now()
      where spl.hotel_id = target_hotel_id
        and spl.provider = provider_value
        and spl.provider_link_id = provider_payment_link_value;
    end if;
  end if;

  update public.hotels h
  set
    status = 'active',
    subscription_status = 'active',
    updated_at = now()
  where h.id = target_hotel_id;

  perform
    private.refresh_subscription_usage_internal(
      target_hotel_id
    );

  result := jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', subscription_row.id,
    'plan_id', subscription_row.plan_id,
    'status', subscription_row.status,
    'billing_mode', subscription_row.billing_mode,
    'billing_cycle', subscription_row.billing_cycle,
    'amount_minor', subscription_row.amount_minor,
    'currency_code', subscription_row.currency_code,
    'current_period_start',
      subscription_row.current_period_start,
    'current_period_end',
      subscription_row.current_period_end,
    'provider', subscription_row.provider,
    'provider_subscription_id',
      subscription_row.provider_subscription_id,
    'idempotent', false
  );

  return private.record_subscription_action_20260728(
    target_hotel_id,
    subscription_row.id,
    'paid_subscription_activated',
    'activate_paid_subscription',
    actor_user_id,
    old_status_value,
    subscription_row.status,
    old_plan_id_value,
    subscription_row.plan_id,
    subscription_row.provider,
    nullif(trim(payload ->> 'provider_event_id'), ''),
    action_key,
    jsonb_build_object(
      'billing_cycle', billing_cycle_value,
      'amount_minor', amount_value,
      'currency_code', currency_value
    ),
    result
  );
end;
$_$;


ALTER FUNCTION "public"."activate_paid_subscription"("target_hotel_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_reservation_room"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "room_payload" "jsonb", "expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reservation_row public.reservations%rowtype;
  room_type_row public.room_types%rowtype;
  target_room_type_id uuid;
  target_rate_plan_id uuid;
  target_room_id uuid;
  target_adults integer;
  target_children integer;
  quote jsonb;
  created_room_id uuid;
  before_json jsonb;
  after_json jsonb;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  if room_payload is null then
    raise exception 'Room payload is required.';
  end if;

  select r.*
  into reservation_row
  from public.reservations r
  where r.hotel_id = target_hotel_id
    and r.id = target_reservation_id
  for update;

  if not found then raise exception 'Reservation not found.'; end if;

  if reservation_row.status not in ('draft', 'tentative', 'confirmed') then
    raise exception 'Rooms may only be added before check-in.';
  end if;

  if expected_updated_at is not null
     and reservation_row.updated_at is distinct from expected_updated_at
  then
    raise exception 'Reservation changed after it was opened. Refresh and try again.';
  end if;

  before_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  target_room_type_id := nullif(room_payload->>'room_type_id', '')::uuid;
  target_rate_plan_id := nullif(room_payload->>'rate_plan_id', '')::uuid;
  target_room_id := nullif(room_payload->>'room_id', '')::uuid;
  target_adults := coalesce(nullif(room_payload->>'adults', '')::integer, 1);
  target_children := coalesce(nullif(room_payload->>'children', '')::integer, 0);

  select rt.* into room_type_row
  from public.room_types rt
  where rt.hotel_id = target_hotel_id
    and rt.id = target_room_type_id
    and rt.is_active;

  if not found then raise exception 'Active room type not found.'; end if;

  if target_adults < 1
     or target_children < 0
     or target_adults > room_type_row.max_adults
     or target_children > room_type_row.max_children
     or target_adults + target_children > room_type_row.max_occupancy
  then
    raise exception 'Guest count exceeds the selected room capacity.';
  end if;

  if not exists (
    select 1 from public.rate_plans rp
    where rp.hotel_id = target_hotel_id
      and rp.id = target_rate_plan_id
      and rp.room_type_id = target_room_type_id
      and rp.is_active
  ) then
    raise exception 'Rate plan does not belong to the selected room type.';
  end if;

  quote := public.get_reservation_rate_quote(
    target_hotel_id,
    target_rate_plan_id,
    reservation_row.arrival_date,
    reservation_row.departure_date,
    target_adults,
    target_children
  );

  if target_room_id is not null and not exists (
    select 1
    from public.get_reservation_available_rooms(
      target_hotel_id,
      reservation_row.arrival_date,
      reservation_row.departure_date,
      target_room_type_id,
      target_reservation_id
    ) available
    where available.room_id = target_room_id
  ) then
    raise exception 'Selected room is unavailable for the reservation dates.';
  end if;

  if reservation_row.status = 'confirmed' and target_room_id is null then
    raise exception 'Confirmed reservation rooms require a physical room assignment.';
  end if;

  insert into public.reservation_rooms (
    hotel_id,
    reservation_id,
    room_type_id,
    room_id,
    rate_plan_id,
    status,
    adults,
    children,
    nightly_rate,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount,
    notes
  )
  values (
    target_hotel_id,
    target_reservation_id,
    target_room_type_id,
    target_room_id,
    target_rate_plan_id,
    case when reservation_row.status = 'confirmed' then 'confirmed' else 'held' end,
    target_adults,
    target_children,
    (quote->>'average_nightly_rate')::numeric(12,2),
    (quote->>'room_subtotal')::numeric(12,2),
    0,
    0,
    (quote->>'total_amount')::numeric(12,2),
    nullif(trim(room_payload->>'notes'), '')
  )
  returning id into created_room_id;

  update public.reservations r
  set
    adults = totals.total_adults,
    children = totals.total_children,
    room_subtotal = totals.room_subtotal,
    tax_amount = totals.tax_amount,
    discount_amount = totals.discount_amount,
    total_amount = greatest(
      totals.room_subtotal + totals.tax_amount - totals.discount_amount,
      0
    ),
    deposit_required = least(
      r.deposit_required,
      greatest(
        totals.room_subtotal + totals.tax_amount - totals.discount_amount,
        0
      )
    ),
    updated_by = auth.uid()
  from (
    select
      sum(rr.adults)::integer as total_adults,
      sum(rr.children)::integer as total_children,
      sum(rr.room_subtotal)::numeric(12,2) as room_subtotal,
      sum(rr.tax_amount)::numeric(12,2) as tax_amount,
      sum(rr.discount_amount)::numeric(12,2) as discount_amount
    from public.reservation_rooms rr
    where rr.hotel_id = target_hotel_id
      and rr.reservation_id = target_reservation_id
      and rr.status not in ('cancelled', 'released')
  ) totals
  where r.hotel_id = target_hotel_id
    and r.id = target_reservation_id;

  after_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'reservation.room_added',
    'reservation',
    target_reservation_id,
    'A room was added to the reservation.',
    before_json,
    after_json,
    jsonb_build_object('reservation_room_id', created_room_id)
  );

  return after_json;
end;
$$;


ALTER FUNCTION "public"."add_reservation_room"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "room_payload" "jsonb", "expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_support_ticket_message"("target_ticket_id" "uuid", "message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  ticket_row public.support_tickets%rowtype;
  event_id_value uuid;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if nullif(trim(message), '') is null then
    raise exception 'Support message is required.';
  end if;

  select st.*
  into ticket_row
  from public.support_tickets st
  where st.id = target_ticket_id
  for update;

  if not found then
    raise exception 'Support ticket was not found.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_hotel_access(ticket_row.hotel_id)
  ) then
    raise exception 'Support ticket access denied.';
  end if;

  if ticket_row.status = 'closed' then
    raise exception
      'Closed support tickets cannot receive new messages.';
  end if;

  update public.support_tickets st
  set
    last_response_at = now(),
    updated_at = now()
  where st.id = target_ticket_id;

  insert into public.support_ticket_events (
    ticket_id,
    hotel_id,
    event_type,
    actor_user_id,
    message,
    old_status,
    new_status,
    details,
    created_at
  ) values (
    ticket_row.id,
    ticket_row.hotel_id,
    'message_added',
    actor_user_id,
    trim(message),
    ticket_row.status,
    ticket_row.status,
    '{}'::jsonb,
    now()
  )
  returning id into event_id_value;

  return jsonb_build_object(
    'ticket_id', ticket_row.id,
    'event_id', event_id_value,
    'status', ticket_row.status
  );
end;
$$;


ALTER FUNCTION "public"."add_support_ticket_message"("target_ticket_id" "uuid", "message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_provider_subscription_event"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_role text :=
    current_setting('request.jwt.claim.role', true);

  event_action text;
  provider_value text;
  provider_event_id_value text;
  idempotency_value text;

  target_hotel_id uuid;
  target_plan_id uuid;
  target_subscription_id uuid;

  billing_cycle_value text;
  currency_value text;
  amount_value bigint;
  period_start_value timestamptz;
  period_end_value timestamptz;
  grace_end_value timestamptz;

  provider_subscription_id_value text;
  provider_payment_link_id_value text;
  provider_payment_id_value text;
  provider_status_value text;

  current_row public.hotel_subscriptions%rowtype;
  old_status_value text;
  result jsonb;
  existing_result jsonb;
begin
  if caller_role <> 'service_role' then
    raise exception
      'Service-role access required for provider webhook application.';
  end if;

  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Provider event payload must be a JSON object.';
  end if;

  event_action :=
    lower(nullif(trim(payload ->> 'event_action'), ''));
  provider_value :=
    lower(coalesce(nullif(trim(payload ->> 'provider'), ''), 'manual'));
  provider_event_id_value :=
    nullif(trim(payload ->> 'provider_event_id'), '');
  idempotency_value := case
    when provider_event_id_value is null then
      nullif(trim(payload ->> 'idempotency_key'), '')
    else
      provider_value || ':webhook:' || provider_event_id_value
  end;

  target_hotel_id :=
    nullif(trim(payload ->> 'hotel_id'), '')::uuid;
  target_plan_id :=
    nullif(trim(payload ->> 'plan_id'), '')::uuid;
  target_subscription_id :=
    nullif(trim(payload ->> 'subscription_id'), '')::uuid;

  billing_cycle_value :=
    coalesce(nullif(trim(payload ->> 'billing_cycle'), ''), 'monthly');
  currency_value :=
    upper(coalesce(nullif(trim(payload ->> 'currency_code'), ''), 'INR'));
  amount_value :=
    coalesce(nullif(trim(payload ->> 'amount_minor'), '')::bigint, 0);
  period_start_value :=
    coalesce(
      nullif(trim(payload ->> 'current_period_start'), '')::timestamptz,
      now()
    );
  period_end_value :=
    nullif(trim(payload ->> 'current_period_end'), '')::timestamptz;
  grace_end_value :=
    nullif(trim(payload ->> 'grace_ends_at'), '')::timestamptz;

  provider_subscription_id_value :=
    nullif(trim(payload ->> 'provider_subscription_id'), '');
  provider_payment_link_id_value :=
    nullif(trim(payload ->> 'provider_payment_link_id'), '');
  provider_payment_id_value :=
    nullif(trim(payload ->> 'provider_payment_id'), '');
  provider_status_value :=
    coalesce(
      nullif(trim(payload ->> 'provider_status'), ''),
      event_action
    );

  if event_action not in (
    'payment_succeeded',
    'payment_failed',
    'subscription_suspended',
    'subscription_cancelled',
    'subscription_resumed'
  ) then
    raise exception
      'Unsupported provider event action: %.',
      coalesce(event_action, 'missing');
  end if;

  if target_hotel_id is null then
    raise exception 'Provider event hotel_id is required.';
  end if;

  existing_result :=
    private.subscription_action_result_20260728(idempotency_value);

  if existing_result is not null then
    return existing_result
      || jsonb_build_object('idempotent', true);
  end if;

  select hs.*
  into current_row
  from public.hotel_subscriptions hs
  where hs.hotel_id = target_hotel_id
    and (
      target_subscription_id is null
      or hs.id = target_subscription_id
    )
    and hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
  order by
    coalesce(hs.updated_at, hs.created_at) desc,
    hs.created_at desc,
    hs.id desc
  limit 1
  for update;

  if event_action in ('payment_succeeded', 'subscription_resumed') then
    target_plan_id := coalesce(target_plan_id, current_row.plan_id);

    if target_plan_id is null
       or period_end_value is null
       or period_end_value <= period_start_value
       or amount_value < 0
    then
      raise exception
        'Successful provider events require plan, valid period and non-negative amount.';
    end if;

    if found
       and current_row.status = 'active'
       and current_row.billing_mode = 'paid'
    then
      return public.renew_hotel_subscription(
        target_hotel_id,
        jsonb_build_object(
          'billing_cycle', billing_cycle_value,
          'currency_code', currency_value,
          'amount_minor', amount_value,
          'provider', provider_value,
          'provider_status', provider_status_value,
          'provider_subscription_id',
            coalesce(
              provider_subscription_id_value,
              current_row.provider_subscription_id
            ),
          'provider_payment_link_id',
            coalesce(
              provider_payment_link_id_value,
              current_row.provider_payment_link_id
            ),
          'current_period_start', period_start_value,
          'current_period_end', period_end_value,
          'last_payment_at', now(),
          'idempotency_key', idempotency_value,
          'provider_event_id', provider_event_id_value,
          'provider_metadata',
            coalesce(payload -> 'provider_metadata', '{}'::jsonb)
              || jsonb_build_object(
                'provider_payment_id',
                provider_payment_id_value
              ),
          'metadata',
            jsonb_build_object(
              'provider_event_action', event_action
            )
        )
      );
    end if;

    return public.activate_paid_subscription(
      target_hotel_id,
      jsonb_build_object(
        'plan_id', target_plan_id,
        'billing_cycle', billing_cycle_value,
        'currency_code', currency_value,
        'amount_minor', amount_value,
        'provider', provider_value,
        'provider_status', provider_status_value,
        'provider_subscription_id',
          provider_subscription_id_value,
        'provider_payment_link_id',
          provider_payment_link_id_value,
        'current_period_start', period_start_value,
        'current_period_end', period_end_value,
        'last_payment_at', now(),
        'idempotency_key', idempotency_value,
        'provider_event_id', provider_event_id_value,
        'provider_metadata',
          coalesce(payload -> 'provider_metadata', '{}'::jsonb)
            || jsonb_build_object(
              'provider_payment_id',
              provider_payment_id_value
            ),
        'metadata',
          jsonb_build_object(
            'provider_event_action', event_action
          )
      )
    );
  end if;

  if not found then
    raise exception
      'No current subscription was found for provider event action %.',
      event_action;
  end if;

  old_status_value := current_row.status;

  perform set_config(
    'stayqr.subscription_event_source',
    'provider_webhook',
    true
  );

  if event_action = 'payment_failed' then
    update public.hotel_subscriptions hs
    set
      status = case
        when hs.status in ('suspended', 'cancelled', 'expired')
          then hs.status
        else 'past_due'
      end,
      provider = provider_value,
      provider_status = provider_status_value,
      provider_subscription_id = coalesce(
        provider_subscription_id_value,
        hs.provider_subscription_id
      ),
      provider_payment_link_id = coalesce(
        provider_payment_link_id_value,
        hs.provider_payment_link_id
      ),
      grace_ends_at = coalesce(
        grace_end_value,
        hs.grace_ends_at,
        now() + interval '3 days'
      ),
      provider_metadata =
        coalesce(hs.provider_metadata, '{}'::jsonb)
        || coalesce(payload -> 'provider_metadata', '{}'::jsonb),
      updated_at = now()
    where hs.id = current_row.id
    returning * into current_row;

    update public.hotels h
    set
      subscription_status = current_row.status,
      updated_at = now()
    where h.id = target_hotel_id;

  elsif event_action = 'subscription_suspended' then
    update public.hotel_subscriptions hs
    set
      status = 'suspended',
      provider = provider_value,
      provider_status = provider_status_value,
      provider_subscription_id = coalesce(
        provider_subscription_id_value,
        hs.provider_subscription_id
      ),
      suspended_at = coalesce(hs.suspended_at, now()),
      provider_metadata =
        coalesce(hs.provider_metadata, '{}'::jsonb)
        || coalesce(payload -> 'provider_metadata', '{}'::jsonb),
      updated_at = now()
    where hs.id = current_row.id
    returning * into current_row;

    update public.hotels h
    set
      status = 'suspended',
      subscription_status = 'suspended',
      updated_at = now()
    where h.id = target_hotel_id;

  elsif event_action = 'subscription_cancelled' then
    update public.hotel_subscriptions hs
    set
      status = 'cancelled',
      provider = provider_value,
      provider_status = provider_status_value,
      provider_subscription_id = coalesce(
        provider_subscription_id_value,
        hs.provider_subscription_id
      ),
      cancelled_at = coalesce(hs.cancelled_at, now()),
      cancellation_reason = coalesce(
        nullif(trim(payload ->> 'reason'), ''),
        hs.cancellation_reason,
        'Provider subscription cancelled.'
      ),
      provider_metadata =
        coalesce(hs.provider_metadata, '{}'::jsonb)
        || coalesce(payload -> 'provider_metadata', '{}'::jsonb),
      updated_at = now()
    where hs.id = current_row.id
    returning * into current_row;

    update public.hotels h
    set
      status = 'suspended',
      subscription_status = 'cancelled',
      updated_at = now()
    where h.id = target_hotel_id;
  end if;

  result := jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', current_row.id,
    'event_action', event_action,
    'status', current_row.status,
    'provider', provider_value,
    'provider_event_id', provider_event_id_value,
    'idempotent', false
  );

  return private.record_subscription_action_20260728(
    target_hotel_id,
    current_row.id,
    'provider_' || event_action,
    'provider_webhook',
    null,
    old_status_value,
    current_row.status,
    current_row.plan_id,
    current_row.plan_id,
    provider_value,
    provider_event_id_value,
    idempotency_value,
    jsonb_build_object(
      'provider_status', provider_status_value,
      'provider_payment_id', provider_payment_id_value,
      'safe_metadata',
        coalesce(payload -> 'provider_metadata', '{}'::jsonb)
    ),
    result
  );
end;
$$;


ALTER FUNCTION "public"."apply_provider_subscription_event"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_housekeeping_room_ready"("target_hotel_id" "uuid", "target_task_id" "uuid", "notes_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.housekeeping_tasks%rowtype;
  room_row public.rooms%rowtype;
  previous_status_value text;
  commitments jsonb;
  existing_event_id uuid;
begin
  actor_id_value :=
    private.day13_require_housekeeping_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select event_record.id
  into existing_event_id
  from public.housekeeping_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type = 'room_ready';

  if existing_event_id is not null then
    select task.*
    into task_row
    from public.housekeeping_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    select room.*
    into room_row
    from public.rooms room
    where room.hotel_id = target_hotel_id
      and room.id = task_row.room_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row),
      'room', to_jsonb(room_row)
    );
  end if;

  select task.*
  into task_row
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Housekeeping task was not found.';
  end if;

  if task_row.status <> 'inspected'
     or task_row.inspection_status <> 'passed'
  then
    raise exception
      'Room-ready approval requires a passed inspection.';
  end if;

  select room.*
  into room_row
  from public.rooms room
  where room.hotel_id = target_hotel_id
    and room.id = task_row.room_id
  for update;

  if not found then
    raise exception 'Task room was not found.';
  end if;

  if room_row.status <> 'cleaning' then
    raise exception
      'Room-ready approval requires room status cleaning, found %.',
      room_row.status;
  end if;

  commitments :=
    private.day13_room_commitments(
      target_hotel_id,
      room_row.id
    );

  if (
    commitments
    ->> 'active_stays'
  )::integer > 0
  or (
    commitments
    ->> 'active_blocks'
  )::integer > 0
  then
    raise exception
      'Active stay or room block prevents room-ready approval.';
  end if;

  previous_status_value := task_row.status;

  update public.housekeeping_tasks
  set
    status = 'ready',
    room_ready_at = now(),
    room_ready_by = actor_id_value,
    notes =
      coalesce(
        nullif(trim(notes_value), ''),
        notes
      ),
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'room_ready_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform set_config(
    'stayqr.day13_request_id',
    request_key || ':room',
    true
  );

  perform set_config(
    'stayqr.day13_event_source',
    'housekeeping',
    true
  );

  perform set_config(
    'stayqr.day13_status_reason',
    'Housekeeping inspection passed and room approved ready',
    true
  );

  update public.rooms
  set
    status = 'available',
    status_changed_at = now(),
    status_changed_by = actor_id_value,
    updated_by = actor_id_value,
    metadata =
      (metadata - 'active_housekeeping_task_id')
      || jsonb_build_object(
        'last_room_ready_task_id',
        target_task_id,
        'last_room_ready_at',
        now()
      )
  where hotel_id = target_hotel_id
    and id = task_row.room_id
  returning *
  into room_row;

  perform private.day13_insert_housekeeping_event(
    target_hotel_id,
    target_task_id,
    'room_ready',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'room_id', room_row.id,
      'room_status', room_row.status
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row),
    'room', to_jsonb(room_row)
  );
end;
$$;


ALTER FUNCTION "public"."approve_housekeeping_room_ready"("target_hotel_id" "uuid", "target_task_id" "uuid", "notes_value" "text", "request_id_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_housekeeping_room_ready"("target_hotel_id" "uuid", "target_task_id" "uuid", "notes_value" "text", "request_id_value" "text") IS 'Only housekeeping workflow path that changes a cleaned inspected room back to available.';



CREATE OR REPLACE FUNCTION "public"."archive_floor"("h" "uuid", "floor_id_value" "uuid", "reason_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; row_value public.floors%rowtype; c integer;
begin
  actor:=private.day13_require_room_manager(h);
  if nullif(trim(request_id_value),'') is null or length(trim(request_id_value))<8 then raise exception 'A request ID of at least eight characters is required.'; end if;
  if nullif(trim(reason_value),'') is null then raise exception 'Archive reason is required.'; end if;
  select * into row_value from public.floors where hotel_id=h and id=floor_id_value for update;
  if not found then raise exception 'Floor was not found.'; end if;
  if not row_value.is_active then return jsonb_build_object('ok',true,'idempotent',true,'floor',to_jsonb(row_value)); end if;
  select count(*) into c from public.rooms where hotel_id=h and floor_id=floor_id_value and is_active;
  if c>0 then raise exception 'Floor cannot be archived while % active room(s) remain.',c; end if;
  update public.floors set is_active=false,archived_at=now(),archived_by=actor,
    archive_reason=trim(reason_value),updated_by=actor,
    metadata=metadata||jsonb_build_object('archive_request_id',request_id_value)
  where hotel_id=h and id=floor_id_value returning * into row_value;
  return jsonb_build_object('ok',true,'idempotent',false,'floor',to_jsonb(row_value));
end;
$$;


ALTER FUNCTION "public"."archive_floor"("h" "uuid", "floor_id_value" "uuid", "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_room"("h" "uuid", "room_id_value" "uuid", "reason_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; row_value public.rooms%rowtype; cm jsonb; req text;
begin
  actor:=private.day13_require_room_manager(h);
  req:=nullif(trim(request_id_value),'');
  if req is null or length(req)<8 then raise exception 'A request ID of at least eight characters is required.'; end if;
  if nullif(trim(reason_value),'') is null then raise exception 'Archive reason is required.'; end if;
  select * into row_value from public.rooms where hotel_id=h and id=room_id_value for update;
  if not found then raise exception 'Room was not found.'; end if;
  if not row_value.is_active then return jsonb_build_object('ok',true,'idempotent',true,'room',to_jsonb(row_value)); end if;
  cm:=private.day13_room_commitments(h,room_id_value);
  if ((cm->>'active_stays')::int)>0 or ((cm->>'active_or_future_allocations')::int)>0 or ((cm->>'active_blocks')::int)>0
    then raise exception 'Room cannot be archived while active/future commitments remain.'; end if;
  perform set_config('stayqr.day13_request_id',req,true);
  perform set_config('stayqr.day13_event_source','archive_rpc',true);
  perform set_config('stayqr.day13_status_reason',trim(reason_value),true);
  update public.rooms set is_active=false,status='out_of_order',archived_at=now(),archived_by=actor,
    archive_reason=trim(reason_value),status_changed_at=now(),status_changed_by=actor,updated_by=actor,
    metadata=metadata||jsonb_build_object('archive_request_id',req,'last_status_reason',trim(reason_value))
  where hotel_id=h and id=room_id_value returning * into row_value;
  return jsonb_build_object('ok',true,'idempotent',false,'room',to_jsonb(row_value));
end;
$$;


ALTER FUNCTION "public"."archive_room"("h" "uuid", "room_id_value" "uuid", "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_room_type"("h" "uuid", "type_id_value" "uuid", "reason_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; row_value public.room_types%rowtype; c integer;
begin
  actor:=private.day13_require_room_manager(h);
  if nullif(trim(request_id_value),'') is null or length(trim(request_id_value))<8 then raise exception 'A request ID of at least eight characters is required.'; end if;
  if nullif(trim(reason_value),'') is null then raise exception 'Archive reason is required.'; end if;
  select * into row_value from public.room_types where hotel_id=h and id=type_id_value for update;
  if not found then raise exception 'Room type was not found.'; end if;
  if not row_value.is_active then return jsonb_build_object('ok',true,'idempotent',true,'room_type',to_jsonb(row_value)); end if;
  select count(*) into c from public.rooms where hotel_id=h and room_type_id=type_id_value and is_active;
  if c>0 then raise exception 'Room type cannot be archived while % active room(s) remain.',c; end if;
  update public.room_types set is_active=false,archived_at=now(),archived_by=actor,
    archive_reason=trim(reason_value),updated_by=actor,
    metadata=metadata||jsonb_build_object('archive_request_id',request_id_value)
  where hotel_id=h and id=type_id_value returning * into row_value;
  return jsonb_build_object('ok',true,'idempotent',false,'room_type',to_jsonb(row_value));
end;
$$;


ALTER FUNCTION "public"."archive_room_type"("h" "uuid", "type_id_value" "uuid", "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_subscription_capacity"("target_hotel_id" "uuid", "metric_key" "text", "additional_units" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_permission(
      target_hotel_id,
      'hotel.manage'
    )
  ) then
    raise exception 'Subscription capacity access denied.';
  end if;

  if metric_key = 'rooms' then
    return
      private.assert_subscription_capacity_internal_20260728(
        target_hotel_id,
        null,
        additional_units,
        0
      );
  elsif metric_key = 'active_staff' then
    return
      private.assert_subscription_capacity_internal_20260728(
        target_hotel_id,
        null,
        0,
        additional_units
      );
  end if;

  raise exception
    'Unsupported capacity metric: %.',
    metric_key;
end;
$$;


ALTER FUNCTION "public"."assert_subscription_capacity"("target_hotel_id" "uuid", "metric_key" "text", "additional_units" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_housekeeping_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "target_staff_id" "uuid", "priority_value" "text", "due_at_value" timestamp with time zone, "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.housekeeping_tasks%rowtype;
  staff_row public.staff%rowtype;
  previous_status_value text;
  existing_event_id uuid;
begin
  actor_id_value :=
    private.day13_require_housekeeping_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select event_record.id
  into existing_event_id
  from public.housekeeping_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type = 'assigned';

  if existing_event_id is not null then
    select task.*
    into task_row
    from public.housekeeping_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select staff.*
  into staff_row
  from public.staff staff
  where staff.hotel_id = target_hotel_id
    and staff.id = target_staff_id
    and staff.status = 'active'
    and staff.disabled_at is null;

  if staff_row.id is null then
    raise exception
      'Assigned staff is not active in this hotel.';
  end if;

  select task.*
  into task_row
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Housekeeping task was not found.';
  end if;

  if task_row.status not in (
    'pending',
    'assigned',
    'inspection_failed'
  ) then
    raise exception
      'Task cannot be assigned from status %.',
      task_row.status;
  end if;

  previous_status_value := task_row.status;

  update public.housekeeping_tasks
  set
    assigned_staff_id = target_staff_id,
    priority =
      coalesce(
        nullif(trim(priority_value), ''),
        priority
      ),
    due_at = due_at_value,
    assigned_at = now(),
    assigned_by = actor_id_value,
    status =
      case
        when status = 'pending'
          then 'assigned'
        else status
      end,
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'assignment_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_housekeeping_event(
    target_hotel_id,
    target_task_id,
    'assigned',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'staff_id', target_staff_id,
      'staff_name', staff_row.full_name,
      'priority', task_row.priority,
      'due_at', task_row.due_at
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row),
    'staff', to_jsonb(staff_row)
  );
end;
$$;


ALTER FUNCTION "public"."assign_housekeeping_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "target_staff_id" "uuid", "priority_value" "text", "due_at_value" timestamp with time zone, "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "target_staff_id" "uuid", "due_at_value" timestamp with time zone, "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.maintenance_tasks%rowtype;
  staff_row public.staff%rowtype;
  existing_event uuid;
  previous_status_value text;
begin
  actor_id_value :=
    private.day13_require_maintenance_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select event_record.id
  into existing_event
  from public.maintenance_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type = 'assigned';

  if existing_event is not null then
    select task.*
    into task_row
    from public.maintenance_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select staff.*
  into staff_row
  from public.staff staff
  where staff.hotel_id = target_hotel_id
    and staff.id = target_staff_id
    and staff.status = 'active'
    and staff.disabled_at is null;

  if staff_row.id is null then
    raise exception
      'Assigned maintenance staff is not active in this hotel.';
  end if;

  select task.*
  into task_row
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Maintenance task was not found.';
  end if;

  if task_row.status not in (
    'reported',
    'assigned',
    'on_hold'
  ) then
    raise exception
      'Maintenance task cannot be assigned from status %.',
      task_row.status;
  end if;

  previous_status_value := task_row.status;

  update public.maintenance_tasks
  set
    assigned_staff_id = target_staff_id,
    status =
      case
        when status = 'reported'
          then 'assigned'
        else status
      end,
    assigned_at = now(),
    assigned_by = actor_id_value,
    due_at = coalesce(
      due_at_value,
      due_at
    ),
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'assignment_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_maintenance_event(
    target_hotel_id,
    target_task_id,
    'assigned',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'staff_id', target_staff_id,
      'staff_name', staff_row.full_name,
      'due_at', task_row.due_at
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row),
    'staff', to_jsonb(staff_row)
  );
end;
$$;


ALTER FUNCTION "public"."assign_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "target_staff_id" "uuid", "due_at_value" timestamp with time zone, "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_service_request"("p_hotel_id" "uuid", "p_request_id" "uuid", "p_staff_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.service_requests%rowtype;
  v_staff public.staff%rowtype;
  v_actor_staff_id uuid;
begin
  if not private.user_has_permission(p_hotel_id, 'services.manage') then
    raise exception 'Service request assignment access denied.';
  end if;

  select sr.* into v_request
  from public.service_requests sr
  where sr.hotel_id = p_hotel_id
    and sr.id = p_request_id
  for update;

  if not found then
    raise exception 'Service request was not found in the selected hotel.';
  end if;

  if p_staff_id is not null then
    select s.* into v_staff
    from public.staff s
    where s.hotel_id = p_hotel_id
      and s.id = p_staff_id
      and s.status = 'active';

    if not found then
      raise exception 'The selected staff member is not active in this hotel.';
    end if;
  end if;

  if v_request.assigned_staff_id is not distinct from p_staff_id then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'request_id', v_request.id,
      'assigned_staff_id', p_staff_id
    );
  end if;

  v_actor_staff_id := private.day15_actor_staff_id(p_hotel_id);

  update public.service_requests
  set assigned_staff_id = p_staff_id
  where hotel_id = p_hotel_id
    and id = p_request_id;

  insert into public.service_request_events (
    hotel_id,
    service_request_id,
    event_type,
    actor_user_id,
    actor_staff_id,
    assigned_staff_id,
    idempotency_key,
    metadata
  ) values (
    p_hotel_id,
    p_request_id,
    'assignment_changed',
    auth.uid(),
    v_actor_staff_id,
    p_staff_id,
    'assignment:' || coalesce(p_staff_id::text, 'unassigned'),
    jsonb_build_object('previous_staff_id', v_request.assigned_staff_id)
  )
  on conflict (hotel_id, service_request_id, idempotency_key) do nothing;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'request_id', v_request.id,
    'assigned_staff_id', p_staff_id
  );
end;
$$;


ALTER FUNCTION "public"."assign_service_request"("p_hotel_id" "uuid", "p_request_id" "uuid", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bootstrap_hotel_onboarding"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_user_id uuid := (select auth.uid());
  actor_email text;
  actor_is_platform_admin boolean := false;

  request_id uuid;
  existing_hotel_id uuid;
  existing_slug text;

  hotel_name_value text;
  owner_name_value text;
  contact_email_value text;
  phone_value text;
  address_value text;
  city_value text;
  state_value text;
  location_value text;
  website_value text;
  gst_value text;
  timezone_value text;
  currency_value text;
  requested_slug text;
  slug_base text;
  slug_candidate text;
  slug_suffix integer := 1;

  plan_id_value uuid;
  trial_days_value integer := 14;

  default_tax_percent_value numeric(6,3) := 0;
  prices_include_tax_value boolean := false;
  checkin_time_value time := '14:00';
  checkout_time_value time := '11:00';
  cancellation_policy_value text;
  house_rules_value text;
  terms_value text;
  invoice_notes_value text;

  new_hotel_id uuid := gen_random_uuid();
  owner_staff_id uuid;
  default_floor_id uuid;
  invoice_prefix text;
  trial_result jsonb;
  readiness jsonb;
  source_value text;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Onboarding payload must be a JSON object.';
  end if;

  select lower(au.email)
  into actor_email
  from auth.users au
  where au.id = actor_user_id
    and au.email is not null;

  if actor_email is null then
    raise exception 'The authenticated account must have an email address.';
  end if;

  actor_is_platform_admin := private.is_platform_admin();

  begin
    request_id := coalesce(
      nullif(trim(payload ->> 'request_id'), '')::uuid,
      gen_random_uuid()
    );
  exception when invalid_text_representation then
    raise exception 'request_id must be a valid UUID.';
  end;

  perform pg_advisory_xact_lock(
    hashtext('stayqr:bootstrap-request:' || request_id::text)
  );

  select ho.hotel_id, h.slug
  into existing_hotel_id, existing_slug
  from public.hotel_onboarding ho
  join public.hotels h on h.id = ho.hotel_id
  where ho.bootstrap_request_id = request_id
  limit 1;

  if existing_hotel_id is not null then
    if not (
      actor_is_platform_admin
      or exists (
        select 1
        from public.hotel_onboarding ho
        where ho.hotel_id = existing_hotel_id
          and ho.owner_user_id = actor_user_id
      )
    ) then
      raise exception 'The bootstrap request belongs to another account.';
    end if;

    return jsonb_build_object(
      'hotel_id', existing_hotel_id,
      'hotel_slug', existing_slug,
      'request_id', request_id,
      'onboarding', (
        select to_jsonb(ho)
        from public.hotel_onboarding ho
        where ho.hotel_id = existing_hotel_id
      ),
      'readiness',
        private.compute_hotel_onboarding_readiness(existing_hotel_id),
      'idempotent', true
    );
  end if;

  if not actor_is_platform_admin
     and exists (
       select 1
       from public.staff s
       where s.auth_user_id = actor_user_id
         and s.status in ('active', 'invited')
     )
  then
    raise exception
      'Self-service bootstrap is limited to accounts without existing active hotel access.';
  end if;

  hotel_name_value := nullif(trim(payload ->> 'hotel_name'), '');
  owner_name_value := nullif(trim(payload ->> 'owner_name'), '');

  if hotel_name_value is null then
    raise exception 'hotel_name is required.';
  end if;

  if owner_name_value is null then
    raise exception 'owner_name is required.';
  end if;

  contact_email_value := lower(
    coalesce(
      nullif(trim(payload ->> 'contact_email'), ''),
      actor_email
    )
  );

  if contact_email_value !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'contact_email is invalid.';
  end if;

  phone_value := nullif(trim(payload ->> 'phone'), '');
  address_value := nullif(trim(payload ->> 'address'), '');
  city_value := nullif(trim(payload ->> 'city'), '');
  state_value := nullif(trim(payload ->> 'state'), '');
  location_value := coalesce(
    nullif(trim(payload ->> 'location'), ''),
    nullif(trim(concat_ws(', ', city_value, state_value)), '')
  );
  website_value := nullif(trim(payload ->> 'website'), '');
  gst_value := nullif(trim(payload ->> 'tax_registration_number'), '');
  timezone_value := coalesce(
    nullif(trim(payload ->> 'timezone'), ''),
    'Asia/Kolkata'
  );
  currency_value := upper(
    coalesce(
      nullif(trim(payload ->> 'currency_code'), ''),
      'INR'
    )
  );

  if not exists (
    select 1
    from pg_catalog.pg_timezone_names tzn
    where tzn.name = timezone_value
  ) then
    raise exception 'Unknown timezone: %.', timezone_value;
  end if;

  if currency_value !~ '^[A-Z]{3}$' then
    raise exception 'currency_code must contain exactly three letters.';
  end if;

  begin
    plan_id_value := nullif(trim(payload ->> 'plan_id'), '')::uuid;
  exception when invalid_text_representation then
    raise exception 'plan_id must be a valid UUID.';
  end;

  if plan_id_value is null then
    raise exception 'plan_id is required.';
  end if;

  if not exists (
    select 1
    from public.subscription_plans sp
    where sp.id = plan_id_value
      and sp.status = 'active'
  ) then
    raise exception 'The selected subscription plan is not active.';
  end if;

  begin
    trial_days_value := coalesce(
      nullif(trim(payload ->> 'trial_days'), '')::integer,
      14
    );
  exception when invalid_text_representation then
    raise exception 'trial_days must be an integer.';
  end;

  if trial_days_value < 1 or trial_days_value > 30 then
    raise exception 'trial_days must be between 1 and 30.';
  end if;

  begin
    default_tax_percent_value := coalesce(
      nullif(trim(payload ->> 'default_tax_percent'), '')::numeric,
      0
    );
  exception when invalid_text_representation then
    raise exception 'default_tax_percent must be numeric.';
  end;

  if default_tax_percent_value < 0
     or default_tax_percent_value > 100
  then
    raise exception 'default_tax_percent must be between 0 and 100.';
  end if;

  begin
    prices_include_tax_value := coalesce(
      nullif(trim(payload ->> 'prices_include_tax'), '')::boolean,
      false
    );
  exception when invalid_text_representation then
    raise exception 'prices_include_tax must be true or false.';
  end;

  begin
    checkin_time_value := coalesce(
      nullif(trim(payload ->> 'checkin_time'), '')::time,
      '14:00'::time
    );
    checkout_time_value := coalesce(
      nullif(trim(payload ->> 'checkout_time'), '')::time,
      '11:00'::time
    );
  exception when invalid_datetime_format then
    raise exception 'Check-in and checkout values must be valid times.';
  end;

  cancellation_policy_value :=
    nullif(trim(payload ->> 'cancellation_policy'), '');
  house_rules_value := nullif(trim(payload ->> 'house_rules'), '');
  terms_value := nullif(trim(payload ->> 'terms_and_conditions'), '');
  invoice_notes_value := nullif(trim(payload ->> 'invoice_notes'), '');

  requested_slug := nullif(trim(payload ->> 'hotel_slug'), '');
  slug_base := private.normalize_hotel_slug(
    coalesce(requested_slug, hotel_name_value)
  );

  perform pg_advisory_xact_lock(
    hashtext('stayqr:hotel-slug:' || slug_base)
  );

  loop
    slug_candidate := case
      when slug_suffix = 1 then slug_base
      else left(
        slug_base,
        greatest(1, 48 - length(slug_suffix::text) - 1)
      ) || '-' || slug_suffix::text
    end;

    exit when not exists (
      select 1
      from public.hotels h
      where lower(h.slug) = lower(slug_candidate)
    );

    slug_suffix := slug_suffix + 1;

    if slug_suffix > 9999 then
      raise exception 'A unique hotel slug could not be generated.';
    end if;
  end loop;

  source_value := case
    when actor_is_platform_admin then 'platform_admin'
    else 'self_service'
  end;

  insert into public.hotels (
    id,
    hotel_name,
    owner_name,
    email,
    phone,
    address,
    city,
    state,
    location,
    status,
    subscription_status,
    website,
    gst_number,
    slug,
    timezone,
    currency_code,
    created_at,
    updated_at
  ) values (
    new_hotel_id,
    hotel_name_value,
    owner_name_value,
    contact_email_value,
    phone_value,
    address_value,
    city_value,
    state_value,
    location_value,
    'active',
    'trialing',
    website_value,
    gst_value,
    slug_candidate,
    timezone_value,
    currency_value,
    now(),
    now()
  );

  insert into public.staff (
    hotel_id,
    full_name,
    email,
    phone,
    role,
    status,
    auth_user_id,
    created_at,
    updated_at,
    invited_at,
    accepted_at,
    disabled_at,
    created_by,
    updated_by,
    identity_reconciliation_status,
    identity_reconciliation_note,
    identity_reconciled_at
  ) values (
    new_hotel_id,
    owner_name_value,
    actor_email,
    phone_value,
    'owner',
    'active',
    actor_user_id,
    now(),
    now(),
    now(),
    now(),
    null,
    actor_user_id,
    actor_user_id,
    'linked',
    'Owner identity created atomically by Day 8 hotel onboarding.',
    now()
  )
  returning id into owner_staff_id;

  insert into public.hotel_info (
    hotel_id,
    hotel_name,
    address,
    reception_phone,
    emergency_phone,
    checkin_time,
    checkout_time,
    breakfast_time,
    wifi_name,
    wifi_password,
    hotel_rules,
    about,
    created_at,
    google_review_url,
    reward_title,
    reward_description,
    reward_enabled
  ) values (
    new_hotel_id,
    hotel_name_value,
    coalesce(address_value, location_value),
    phone_value,
    phone_value,
    to_char(checkin_time_value, 'HH12:MI AM'),
    to_char(checkout_time_value, 'HH12:MI AM'),
    null,
    null,
    null,
    house_rules_value,
    hotel_name_value ||
      ' uses StayQR for a smarter and more convenient guest experience.',
    now(),
    null,
    'Guest Reward',
    'Contact reception to learn about available guest rewards.',
    false
  );

  insert into public.hotel_settings (
    hotel_id,
    legal_name,
    tax_registration_number,
    default_tax_percent,
    prices_include_tax,
    tax_label,
    checkin_time,
    checkout_time,
    cancellation_policy,
    house_rules,
    terms_and_conditions,
    invoice_notes,
    locale,
    date_format,
    created_by,
    updated_by,
    created_at,
    updated_at
  ) values (
    new_hotel_id,
    hotel_name_value,
    gst_value,
    default_tax_percent_value,
    prices_include_tax_value,
    'Tax',
    checkin_time_value,
    checkout_time_value,
    cancellation_policy_value,
    house_rules_value,
    terms_value,
    invoice_notes_value,
    'en-IN',
    'DD/MM/YYYY',
    actor_user_id,
    actor_user_id,
    now(),
    now()
  );

  insert into public.hotel_onboarding (
    hotel_id,
    owner_user_id,
    status,
    current_step,
    completed_steps,
    form_state,
    readiness_state,
    last_error,
    version,
    started_at,
    last_saved_at,
    completed_at,
    created_by,
    updated_by,
    created_at,
    updated_at,
    bootstrap_request_id,
    onboarding_source
  ) values (
    new_hotel_id,
    actor_user_id,
    'in_progress',
    'subscription',
    array['account', 'hotel_details', 'policies']::text[],
    jsonb_build_object(
      'account', jsonb_build_object(
        'owner_name', owner_name_value,
        'owner_email', actor_email
      ),
      'hotel_details', jsonb_build_object(
        'hotel_name', hotel_name_value,
        'hotel_slug', slug_candidate,
        'contact_email', contact_email_value,
        'phone', phone_value,
        'address', address_value,
        'city', city_value,
        'state', state_value,
        'location', location_value,
        'website', website_value,
        'timezone', timezone_value,
        'currency_code', currency_value
      ),
      'policies', jsonb_build_object(
        'default_tax_percent', default_tax_percent_value,
        'prices_include_tax', prices_include_tax_value,
        'checkin_time', checkin_time_value,
        'checkout_time', checkout_time_value
      )
    ),
    '{}'::jsonb,
    null,
    1,
    now(),
    now(),
    null,
    actor_user_id,
    actor_user_id,
    now(),
    now(),
    request_id,
    source_value
  );

  insert into public.floors (
    hotel_id,
    name,
    code,
    floor_number,
    description,
    sort_order,
    is_active,
    created_by,
    updated_by,
    created_at,
    updated_at
  ) values (
    new_hotel_id,
    'Default Floor',
    'DEFAULT',
    0,
    'Initial floor created during hotel onboarding.',
    0,
    true,
    actor_user_id,
    actor_user_id,
    now(),
    now()
  )
  returning id into default_floor_id;

  invoice_prefix :=
    coalesce(
      nullif(
        upper(
          left(
            regexp_replace(slug_candidate, '[^a-z0-9]', '', 'g'),
            4
          )
        ),
        ''
      ),
      'INV'
    ) || '-INV';

  insert into public.invoice_number_sequences (
    hotel_id,
    sequence_year,
    prefix,
    last_number,
    padding,
    reset_annually,
    updated_by,
    created_at,
    updated_at
  ) values (
    new_hotel_id,
    extract(year from now())::integer,
    invoice_prefix,
    0,
    6,
    true,
    actor_user_id,
    now(),
    now()
  );

  trial_result := public.activate_hotel_trial(
    new_hotel_id,
    plan_id_value,
    trial_days_value
  );

  update public.hotel_onboarding ho
  set
    current_step = 'room_types',
    completed_steps = array[
      'account',
      'hotel_details',
      'policies',
      'subscription'
    ]::text[],
    form_state = jsonb_set(
      ho.form_state,
      '{subscription}',
      jsonb_build_object(
        'plan_id', plan_id_value,
        'trial_days', trial_days_value,
        'trial', trial_result
      ),
      true
    ),
    last_saved_at = now(),
    updated_by = actor_user_id,
    version = ho.version + 1
  where ho.hotel_id = new_hotel_id;

  readiness := private.compute_hotel_onboarding_readiness(new_hotel_id);

  update public.hotel_onboarding ho
  set
    readiness_state = readiness,
    last_saved_at = now(),
    updated_by = actor_user_id,
    version = ho.version + 1
  where ho.hotel_id = new_hotel_id;

  return jsonb_build_object(
    'hotel_id', new_hotel_id,
    'hotel_slug', slug_candidate,
    'owner_staff_id', owner_staff_id,
    'default_floor_id', default_floor_id,
    'request_id', request_id,
    'trial', trial_result,
    'onboarding', (
      select to_jsonb(ho)
      from public.hotel_onboarding ho
      where ho.hotel_id = new_hotel_id
    ),
    'readiness', readiness,
    'idempotent', false
  );
exception
  when unique_violation then
    raise exception
      'Hotel onboarding could not be completed because a unique hotel, email, slug or request value is already in use.';
end;
$_$;


