CREATE OR REPLACE FUNCTION "public"."cancel_guest_food_order"("p_hotel_slug" "text", "p_access_token" "text", "p_order_id" "uuid", "p_reason" "text" DEFAULT 'Cancelled by guest'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_context record;
  v_order public.food_orders%rowtype;
  v_reason text;
begin
  select * into v_context
  from private.day15_guest_context(
    p_hotel_slug,
    p_access_token,
    true
  );

  v_reason := coalesce(nullif(trim(p_reason), ''), 'Cancelled by guest');

  select fo.* into v_order
  from public.food_orders fo
  where fo.id = p_order_id
    and fo.hotel_id = v_context.hotel_id
    and (
      fo.guest_session_id = v_context.guest_session_id
      or (
        fo.guest_session_id is null
        and fo.room_id = v_context.room_id
        and fo.guest_id = v_context.guest_id
      )
    )
  for update;

  if not found then
    raise exception 'Food order was not found for this stay.';
  end if;

  if v_order.order_status = 'cancelled' then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'order_id', v_order.id,
      'order_status', 'cancelled'
    );
  end if;

  if not (
    v_order.order_status = 'pending'
    or (
      v_order.order_status = 'accepted'
      and coalesce(v_order.accepted_at, v_order.created_at) > now() - interval '2 minutes'
    )
  ) then
    raise exception 'This order can no longer be cancelled from the guest portal. Please call reception.';
  end if;

  update public.food_orders
  set
    order_status = 'cancelled',
    cancelled_at = now(),
    cancellation_reason = v_reason,
    estimated_minutes = null,
    estimated_delivery_time = null
  where id = v_order.id
    and hotel_id = v_order.hotel_id;

  insert into public.food_order_events (
    hotel_id,
    food_order_id,
    event_type,
    from_status,
    to_status,
    message,
    idempotency_key,
    metadata
  ) values (
    v_order.hotel_id,
    v_order.id,
    'guest_cancelled',
    v_order.order_status,
    'cancelled',
    v_reason,
    'guest-cancelled',
    jsonb_build_object('reason', v_reason)
  )
  on conflict (hotel_id, food_order_id, idempotency_key) do nothing;

  perform private.day15_notify_guest(
    v_context.hotel_id,
    v_context.guest_session_id,
    v_context.room_id,
    v_context.guest_id,
    'food_order',
    v_order.id,
    'cancelled',
    'Order cancelled',
    'Your food order has been cancelled.',
    jsonb_build_object('reason', v_reason)
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'order_id', v_order.id,
    'order_status', 'cancelled'
  );
end;
$$;


ALTER FUNCTION "public"."cancel_guest_food_order"("p_hotel_slug" "text", "p_access_token" "text", "p_order_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_guest_service_request"("p_hotel_slug" "text", "p_access_token" "text", "p_request_id" "uuid", "p_reason" "text" DEFAULT 'Cancelled by guest'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_context record;
  v_request public.service_requests%rowtype;
  v_reason text;
begin
  select * into v_context
  from private.day15_guest_context(p_hotel_slug, p_access_token, true);

  v_reason := coalesce(nullif(trim(p_reason), ''), 'Cancelled by guest');

  select sr.* into v_request
  from public.service_requests sr
  where sr.hotel_id = v_context.hotel_id
    and sr.id = p_request_id
    and (
      sr.guest_session_id = v_context.guest_session_id
      or (
        sr.guest_session_id is null
        and sr.room_id = v_context.room_id
        and sr.guest_id = v_context.guest_id
      )
    )
  for update;

  if not found then
    raise exception 'Service request was not found for this stay.';
  end if;

  if v_request.status = 'cancelled' then
    return jsonb_build_object('ok', true, 'idempotent', true, 'request_id', v_request.id);
  end if;

  if v_request.status not in ('pending','accepted') then
    raise exception 'This request can no longer be cancelled from the guest portal.';
  end if;

  update public.service_requests
  set
    status = 'cancelled',
    cancelled_at = now(),
    cancellation_reason = v_reason
  where hotel_id = v_request.hotel_id
    and id = v_request.id;

  insert into public.service_request_events (
    hotel_id,
    service_request_id,
    event_type,
    from_status,
    to_status,
    message,
    idempotency_key,
    metadata
  ) values (
    v_request.hotel_id,
    v_request.id,
    'guest_cancelled',
    v_request.status,
    'cancelled',
    v_reason,
    'guest-cancelled',
    jsonb_build_object('reason', v_reason)
  )
  on conflict (hotel_id, service_request_id, idempotency_key) do nothing;

  perform private.day15_notify_guest(
    v_context.hotel_id,
    v_context.guest_session_id,
    v_context.room_id,
    v_context.guest_id,
    'service_request',
    v_request.id,
    'cancelled',
    'Request cancelled',
    'Your service request has been cancelled.',
    jsonb_build_object('reason', v_reason)
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'request_id', v_request.id,
    'status', 'cancelled'
  );
end;
$$;


ALTER FUNCTION "public"."cancel_guest_service_request"("p_hotel_slug" "text", "p_access_token" "text", "p_request_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_hotel_subscription"("target_hotel_id" "uuid", "reason" "text", "immediate" boolean DEFAULT false, "action_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  existing_result jsonb;
  subscription_row public.hotel_subscriptions%rowtype;
  old_status_value text;
  result jsonb;
begin
  if target_hotel_id is null
     or nullif(trim(reason), '') is null
  then
    raise exception
      'Hotel and cancellation reason are required.';
  end if;

  existing_result :=
    private.subscription_action_result_20260728(
      action_idempotency_key
    );

  if existing_result is not null then
    return existing_result
      || jsonb_build_object('idempotent', true);
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:cancel-subscription:' || target_hotel_id::text
    )
  );

  select hs.*
  into subscription_row
  from public.hotel_subscriptions hs
  where hs.hotel_id = target_hotel_id
    and hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
  order by hs.updated_at desc, hs.id desc
  limit 1
  for update;

  if not found then
    raise exception
      'No current subscription was found.';
  end if;

  old_status_value := subscription_row.status;

  perform set_config(
    'stayqr.subscription_event_source',
    'cancel_hotel_subscription',
    true
  );

  if coalesce(immediate, false) then
    update public.hotel_subscriptions hs
    set
      status = 'cancelled',
      provider_status = 'cancelled',
      cancelled_at = now(),
      cancellation_reason = trim(reason),
      metadata = coalesce(hs.metadata, '{}'::jsonb)
        - 'cancel_at_period_end'
        || jsonb_build_object(
          'last_cancellation',
          jsonb_build_object(
            'immediate', true,
            'reason', trim(reason),
            'cancelled_by', actor_user_id,
            'cancelled_at', now()
          )
        ),
      updated_at = now()
    where hs.id = subscription_row.id
    returning * into subscription_row;

    update public.hotels h
    set
      status = 'suspended',
      subscription_status = 'cancelled',
      updated_at = now()
    where h.id = target_hotel_id;
  else
    update public.hotel_subscriptions hs
    set
      cancellation_reason = trim(reason),
      metadata = coalesce(hs.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'cancel_at_period_end', true,
          'cancellation_requested_at', now(),
          'cancellation_requested_by', actor_user_id,
          'cancellation_reason', trim(reason)
        ),
      updated_at = now()
    where hs.id = subscription_row.id
    returning * into subscription_row;
  end if;

  result := jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', subscription_row.id,
    'status', subscription_row.status,
    'immediate', coalesce(immediate, false),
    'cancel_at_period_end',
      coalesce(
        (
          subscription_row.metadata
          ->> 'cancel_at_period_end'
        )::boolean,
        false
      ),
    'idempotent', false
  );

  return private.record_subscription_action_20260728(
    target_hotel_id,
    subscription_row.id,
    case when coalesce(immediate, false)
      then 'subscription_cancelled'
      else 'subscription_cancellation_scheduled'
    end,
    'cancel_hotel_subscription',
    actor_user_id,
    old_status_value,
    subscription_row.status,
    subscription_row.plan_id,
    subscription_row.plan_id,
    subscription_row.provider,
    null,
    action_idempotency_key,
    jsonb_build_object(
      'reason', trim(reason),
      'immediate', coalesce(immediate, false)
    ),
    result
  );
end;
$$;


ALTER FUNCTION "public"."cancel_hotel_subscription"("target_hotel_id" "uuid", "reason" "text", "immediate" boolean, "action_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_housekeeping_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "reason_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.housekeeping_tasks%rowtype;
  previous_status_value text;
  existing_event_id uuid;
begin
  actor_id_value :=
    private.day13_require_housekeeping_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  if nullif(trim(reason_value), '') is null then
    raise exception 'Cancellation reason is required.';
  end if;

  select event_record.id
  into existing_event_id
  from public.housekeeping_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type = 'cancelled';

  if existing_event_id is not null then
    select task.*
    into task_row
    from public.housekeeping_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select task.*
  into task_row
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Housekeeping task was not found.';
  end if;

  if task_row.status in (
    'ready',
    'completed',
    'cancelled'
  ) then
    raise exception
      'Task cannot be cancelled from status %.',
      task_row.status;
  end if;

  previous_status_value := task_row.status;

  update public.housekeeping_tasks
  set
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = actor_id_value,
    cancellation_reason = trim(reason_value),
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'cancel_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_housekeeping_event(
    target_hotel_id,
    target_task_id,
    'cancelled',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'reason', trim(reason_value)
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row)
  );
end;
$$;


ALTER FUNCTION "public"."cancel_housekeeping_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "reason_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.maintenance_tasks%rowtype;
  room_row public.rooms%rowtype;
  block_row public.room_blocks%rowtype;
  previous_status_value text;
  commitments jsonb;
  existing_event uuid;
begin
  actor_id_value :=
    private.day13_require_maintenance_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  if nullif(trim(reason_value), '') is null then
    raise exception 'Cancellation reason is required.';
  end if;

  select event_record.id
  into existing_event
  from public.maintenance_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type = 'cancelled';

  if existing_event is not null then
    select task.*
    into task_row
    from public.maintenance_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select task.*
  into task_row
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Maintenance task was not found.';
  end if;

  if task_row.status in (
    'resolved',
    'verified',
    'cancelled'
  ) then
    raise exception
      'Maintenance task cannot be cancelled from status %.',
      task_row.status;
  end if;

  if task_row.room_block_id is not null then
    update public.room_blocks
    set
      status = 'cancelled',
      released_at = now(),
      released_by = actor_id_value,
      release_reason = trim(reason_value),
      updated_by = actor_id_value
    where hotel_id = target_hotel_id
      and id = task_row.room_block_id
      and status = 'active'
    returning *
    into block_row;
  end if;

  if task_row.inventory_impact <> 'none' then
    commitments :=
      private.day13_room_commitments(
        target_hotel_id,
        task_row.room_id
      );

    if (
      commitments
      ->> 'active_stays'
    )::integer = 0
    and (
      commitments
      ->> 'active_blocks'
    )::integer = 0
    and (
      commitments
      ->> 'pending_housekeeping'
    )::integer = 0
    then
      perform public.transition_room_status(
        target_hotel_id,
        task_row.room_id,
        case
          when task_row.previous_room_status in (
            'available',
            'cleaning'
          ) then task_row.previous_room_status
          else 'available'
        end,
        'Maintenance task cancelled',
        'maintenance',
        request_key || ':room'
      );
    end if;
  end if;

  previous_status_value := task_row.status;

  update public.maintenance_tasks
  set
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = actor_id_value,
    cancellation_reason =
      trim(reason_value),
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'cancel_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_maintenance_event(
    target_hotel_id,
    target_task_id,
    'cancelled',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'reason', trim(reason_value),
      'room_block_id', block_row.id
    )
  );

  select room.*
  into room_row
  from public.rooms room
  where room.hotel_id = target_hotel_id
    and room.id = task_row.room_id;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row),
    'room', to_jsonb(room_row),
    'room_block',
      case
        when block_row.id is null
          then null
        else to_jsonb(block_row)
      end
  );
end;
$$;


ALTER FUNCTION "public"."cancel_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."change_calendar_room_block_status"("target_hotel_id" "uuid", "target_room_block_id" "uuid", "target_status" "text", "reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_block public.room_blocks%rowtype;
  normalized_status text;
  normalized_reason text;
  before_json jsonb;
  after_json jsonb;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  normalized_status := lower(trim(coalesce(target_status, '')));
  normalized_reason := nullif(trim(reason), '');

  if normalized_status not in ('released', 'cancelled') then
    raise exception
      'Room-block status may change only to released or cancelled.';
  end if;

  if normalized_reason is null then
    raise exception 'Room-block release/cancellation reason is required.';
  end if;

  select block.*
  into current_block
  from public.room_blocks block
  where block.id = target_room_block_id
    and block.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Room block not found.';
  end if;

  if current_block.status <> 'active' then
    raise exception 'Only active room blocks may be released or cancelled.';
  end if;

  before_json := private.build_room_block_json(
    target_hotel_id,
    current_block.id
  );

  update public.room_blocks
  set
    status = normalized_status,
    release_reason = normalized_reason,
    released_at = now(),
    released_by = auth.uid(),
    updated_by = auth.uid(),
    updated_at = now()
  where id = current_block.id
    and hotel_id = target_hotel_id;

  after_json := private.build_room_block_json(
    target_hotel_id,
    current_block.id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'room_block.' || normalized_status,
    'room_block',
    current_block.id,
    format(
      'Room block for room %s changed to %s.',
      after_json->>'room_number',
      normalized_status
    ),
    before_json,
    after_json,
    jsonb_build_object('reason', normalized_reason)
  );

  return after_json;
end;
$$;


ALTER FUNCTION "public"."change_calendar_room_block_status"("target_hotel_id" "uuid", "target_room_block_id" "uuid", "target_status" "text", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."change_hotel_subscription_plan"("target_hotel_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  action_key text;
  existing_result jsonb;
  target_plan_id uuid;
  subscription_row public.hotel_subscriptions%rowtype;
  old_plan_id_value uuid;
  result jsonb;
begin
  if target_hotel_id is null
     or payload is null
     or jsonb_typeof(payload) <> 'object'
  then
    raise exception 'Hotel and plan-change payload are required.';
  end if;

  action_key :=
    nullif(trim(payload ->> 'idempotency_key'), '');
  existing_result :=
    private.subscription_action_result_20260728(action_key);

  if existing_result is not null then
    return existing_result
      || jsonb_build_object('idempotent', true);
  end if;

  target_plan_id :=
    nullif(trim(payload ->> 'plan_id'), '')::uuid;

  if target_plan_id is null then
    raise exception 'Target plan is required.';
  end if;

  perform
    private.assert_subscription_capacity_internal_20260728(
      target_hotel_id,
      target_plan_id,
      0,
      0
    );

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:change-plan:' || target_hotel_id::text
    )
  );

  select hs.*
  into subscription_row
  from public.hotel_subscriptions hs
  where hs.hotel_id = target_hotel_id
    and hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due',
      'suspended'
    )
  order by hs.updated_at desc, hs.id desc
  limit 1
  for update;

  if not found then
    raise exception
      'No current subscription was found.';
  end if;

  old_plan_id_value := subscription_row.plan_id;

  if old_plan_id_value = target_plan_id then
    return jsonb_build_object(
      'hotel_id', target_hotel_id,
      'subscription_id', subscription_row.id,
      'plan_id', target_plan_id,
      'status', subscription_row.status,
      'idempotent', true
    );
  end if;

  perform set_config(
    'stayqr.subscription_event_source',
    'change_hotel_subscription_plan',
    true
  );

  update public.hotel_subscriptions hs
  set
    plan_id = target_plan_id,
    amount_minor = coalesce(
      nullif(trim(payload ->> 'amount_minor'), '')::bigint,
      hs.amount_minor
    ),
    currency_code = upper(
      coalesce(
        nullif(trim(payload ->> 'currency_code'), ''),
        hs.currency_code
      )
    ),
    metadata = coalesce(hs.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'last_plan_change',
        jsonb_build_object(
          'from_plan_id', old_plan_id_value,
          'to_plan_id', target_plan_id,
          'reason',
            nullif(trim(payload ->> 'reason'), ''),
          'changed_by', actor_user_id,
          'changed_at', now()
        )
      ),
    updated_at = now()
  where hs.id = subscription_row.id
  returning * into subscription_row;

  perform
    private.refresh_subscription_usage_internal(
      target_hotel_id
    );

  result := jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', subscription_row.id,
    'old_plan_id', old_plan_id_value,
    'plan_id', subscription_row.plan_id,
    'status', subscription_row.status,
    'amount_minor', subscription_row.amount_minor,
    'idempotent', false
  );

  return private.record_subscription_action_20260728(
    target_hotel_id,
    subscription_row.id,
    'subscription_plan_changed',
    'change_hotel_subscription_plan',
    actor_user_id,
    subscription_row.status,
    subscription_row.status,
    old_plan_id_value,
    subscription_row.plan_id,
    subscription_row.provider,
    null,
    action_key,
    jsonb_build_object(
      'reason', nullif(trim(payload ->> 'reason'), '')
    ),
    result
  );
end;
$$;


ALTER FUNCTION "public"."change_hotel_subscription_plan"("target_hotel_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."change_reservation_status"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "target_status" "text", "reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_reservation public.reservations%rowtype;
  normalized_status text;
  before_json jsonb;
  after_json jsonb;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  normalized_status := lower(trim(coalesce(target_status, '')));

  if normalized_status not in ('cancelled', 'no_show') then
    raise exception
      'Day 3 status action supports cancelled or no_show.';
  end if;

  select r.*
  into current_reservation
  from public.reservations r
  where r.id = target_reservation_id
    and r.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Reservation not found.';
  end if;

  if normalized_status = 'cancelled'
     and nullif(trim(reason), '') is null
  then
    raise exception 'Cancellation reason is required.';
  end if;

  before_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  update public.reservations
  set
    status = normalized_status,
    cancellation_reason = case
      when normalized_status = 'cancelled'
        then nullif(trim(reason), '')
      else cancellation_reason
    end,
    updated_by = auth.uid(),
    updated_at = now()
  where id = target_reservation_id
    and hotel_id = target_hotel_id;

  update public.reservation_rooms
  set
    status = case
      when normalized_status = 'cancelled'
        then 'cancelled'
      else 'released'
    end,
    updated_at = now()
  where reservation_id = target_reservation_id
    and hotel_id = target_hotel_id;

  after_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'reservation.' || normalized_status,
    'reservation',
    target_reservation_id,
    format(
      'Reservation %s changed to %s.',
      current_reservation.reservation_number,
      normalized_status
    ),
    before_json,
    after_json,
    jsonb_build_object('reason', nullif(trim(reason), ''))
  );

  return after_json;
end;
$$;


ALTER FUNCTION "public"."change_reservation_status"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "target_status" "text", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_in_reservation_room"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "target_reservation_room_id" "uuid", "expected_reservation_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reservation_row public.reservations%rowtype;
  reservation_room_row public.reservation_rooms%rowtype;
  room_row public.rooms%rowtype;
  room_type_row public.room_types%rowtype;
  guest_row public.guests%rowtype;
  hotel_timezone text;
  hotel_today date;
  target_checkin_time timestamptz := now();
  target_checkout_time timestamptz;
  created_session_id uuid;
  created_payment_id uuid;
  created_collection_id uuid;
  created_transfer_id uuid;
  payment_row public.reservation_payments%rowtype;
  already_transferred numeric(12,2);
  transfer_amount numeric(12,2);
  room_credit_remaining numeric(12,2);
  transferred_total numeric(12,2) := 0;
  snapshot jsonb;
  room_count integer;
  checked_in_count integer;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  select r.* into reservation_row
  from public.reservations r
  where r.hotel_id = target_hotel_id
    and r.id = target_reservation_id
  for update;

  if not found then raise exception 'Reservation not found.'; end if;

  if expected_reservation_updated_at is not null
     and reservation_row.updated_at is distinct from expected_reservation_updated_at
  then
    raise exception 'Reservation changed after it was opened. Refresh and try again.';
  end if;

  if reservation_row.status not in ('confirmed', 'checked_in') then
    raise exception 'Only confirmed reservations may be checked in.';
  end if;

  select rr.* into reservation_room_row
  from public.reservation_rooms rr
  where rr.hotel_id = target_hotel_id
    and rr.reservation_id = target_reservation_id
    and rr.id = target_reservation_room_id
  for update;

  if not found then raise exception 'Reservation room not found.'; end if;

  if reservation_room_row.status = 'checked_in'
     or exists (
       select 1 from public.reservation_checkin_events e
       where e.hotel_id = target_hotel_id
         and e.reservation_room_id = target_reservation_room_id
     )
  then
    raise exception 'This reservation room is already checked in.';
  end if;

  if reservation_room_row.status <> 'confirmed' then
    raise exception 'The selected reservation room is not confirmed.';
  end if;

  if reservation_room_row.room_id is null then
    raise exception 'Assign a physical room before check-in.';
  end if;

  select h.timezone into hotel_timezone
  from public.hotels h
  where h.id = target_hotel_id
    and h.status = 'active';

  if hotel_timezone is null then raise exception 'Hotel timezone is missing.'; end if;

  hotel_today := (now() at time zone hotel_timezone)::date;

  if hotel_today < reservation_row.arrival_date then
    raise exception 'This reservation has not reached its arrival date.';
  end if;

  if hotel_today >= reservation_row.departure_date then
    raise exception 'This reservation is past its departure date.';
  end if;

  select rt.* into room_type_row
  from public.room_types rt
  where rt.hotel_id = target_hotel_id
    and rt.id = reservation_room_row.room_type_id;

  if not found then raise exception 'Reservation room type not found.'; end if;

  if reservation_room_row.adults > room_type_row.max_adults
     or reservation_room_row.children > room_type_row.max_children
     or reservation_room_row.adults + reservation_room_row.children > room_type_row.max_occupancy
  then
    raise exception 'Guest count exceeds room capacity.';
  end if;

  select rm.* into room_row
  from public.rooms rm
  where rm.hotel_id = target_hotel_id
    and rm.id = reservation_room_row.room_id
  for update;

  if not found then raise exception 'Assigned room not found.'; end if;

  if room_row.room_type_id <> reservation_room_row.room_type_id then
    raise exception 'Assigned room does not match the reservation room type.';
  end if;

  if room_row.status <> 'available' then
    raise exception 'Assigned room is not currently available.';
  end if;

  if not exists (
    select 1
    from public.room_inventory_allocations allocation
    where allocation.hotel_id = target_hotel_id
      and allocation.reservation_room_id = target_reservation_room_id
      and allocation.room_id = reservation_room_row.room_id
      and allocation.status = 'active'
      and allocation.starts_on = reservation_row.arrival_date
      and allocation.ends_on = reservation_row.departure_date
  ) then
    raise exception 'Authoritative room allocation is missing or stale.';
  end if;

  if exists (
    select 1 from public.guest_sessions session
    where session.hotel_id = target_hotel_id
      and session.room_id = reservation_room_row.room_id
      and session.status = 'active'
  ) then
    raise exception 'The assigned room already has an active guest stay.';
  end if;

  select g.* into guest_row
  from public.guests g
  where g.hotel_id = target_hotel_id
    and g.id = reservation_row.primary_guest_id;

  if not found then raise exception 'Primary guest profile not found.'; end if;

  target_checkout_time := (
    reservation_row.departure_date::timestamp
      + coalesce(reservation_row.expected_checkout_time, time '11:00')
  ) at time zone hotel_timezone;

  if target_checkout_time <= target_checkin_time then
    raise exception 'Calculated checkout time must be after check-in.';
  end if;

  insert into public.guest_sessions (
    hotel_id,
    room_id,
    guest_id,
    checkin_time,
    checkout_time,
    status,
    reservation_id,
    reservation_room_id,
    checked_in_by
  )
  values (
    target_hotel_id,
    reservation_room_row.room_id,
    reservation_row.primary_guest_id,
    target_checkin_time,
    target_checkout_time,
    'active',
    target_reservation_id,
    target_reservation_room_id,
    auth.uid()
  )
  returning id into created_session_id;

  insert into public.payments (
    hotel_id,
    guest_id,
    room_id,
    amount,
    payment_type,
    payment_status,
    notes,
    payment_method,
    guest_session_id,
    reservation_id,
    reservation_room_id
  )
  values (
    target_hotel_id,
    reservation_row.primary_guest_id,
    reservation_room_row.room_id,
    reservation_room_row.total_amount,
    'room_charge',
    'pending',
    format('Reservation %s · Room %s charge', reservation_row.reservation_number, room_row.room_number),
    'cash',
    created_session_id,
    target_reservation_id,
    target_reservation_room_id
  )
  returning id into created_payment_id;

  room_credit_remaining := reservation_room_row.total_amount;

  for payment_row in
    select rp.*
    from public.reservation_payments rp
    where rp.hotel_id = target_hotel_id
      and rp.reservation_id = target_reservation_id
      and rp.payment_status = 'collected'
    order by rp.collected_at, rp.id
    for update
  loop
    exit when room_credit_remaining <= 0;

    select coalesce(sum(t.amount), 0)::numeric(12,2)
    into already_transferred
    from public.reservation_payment_transfers t
    where t.hotel_id = target_hotel_id
      and t.reservation_payment_id = payment_row.id;

    transfer_amount := least(
      greatest(payment_row.amount - already_transferred, 0),
      room_credit_remaining
    )::numeric(12,2);

    if transfer_amount > 0 then
      insert into public.reservation_payment_transfers (
        hotel_id,
        reservation_id,
        reservation_payment_id,
        reservation_room_id,
        guest_session_id,
        payment_id,
        amount,
        transferred_by,
        metadata
      )
      values (
        target_hotel_id,
        target_reservation_id,
        payment_row.id,
        target_reservation_room_id,
        created_session_id,
        created_payment_id,
        transfer_amount,
        auth.uid(),
        jsonb_build_object(
          'payment_method', payment_row.payment_method,
          'transaction_reference', payment_row.transaction_reference,
          'collected_at', payment_row.collected_at
        )
      )
      returning id into created_transfer_id;

      insert into public.payment_collections (
        hotel_id,
        payment_id,
        guest_id,
        room_id,
        amount,
        payment_method,
        transaction_reference,
        notes,
        collected_by,
        collected_at,
        guest_session_id,
        reservation_id,
        reservation_payment_id
      )
      values (
        target_hotel_id,
        created_payment_id,
        reservation_row.primary_guest_id,
        reservation_room_row.room_id,
        transfer_amount,
        payment_row.payment_method,
        payment_row.transaction_reference,
        coalesce(payment_row.notes, 'Reservation deposit transferred at check-in'),
        coalesce(payment_row.collected_by, auth.uid()),
        payment_row.collected_at,
        created_session_id,
        target_reservation_id,
        payment_row.id
      )
      returning id into created_collection_id;

      update public.reservation_payment_transfers
      set payment_collection_id = created_collection_id
      where hotel_id = target_hotel_id
        and id = created_transfer_id;

      room_credit_remaining := room_credit_remaining - transfer_amount;
      transferred_total := transferred_total + transfer_amount;
    end if;
  end loop;

  update public.reservation_rooms
  set status = 'checked_in'
  where hotel_id = target_hotel_id
    and id = target_reservation_room_id;

  if reservation_row.status = 'confirmed' then
    update public.reservations
    set
      status = 'checked_in',
      updated_by = auth.uid()
    where hotel_id = target_hotel_id
      and id = target_reservation_id;
  end if;

  update public.rooms
  set status = 'occupied'
  where hotel_id = target_hotel_id
    and id = reservation_room_row.room_id;

  snapshot := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  insert into public.reservation_checkin_events (
    hotel_id,
    reservation_id,
    reservation_room_id,
    guest_session_id,
    room_id,
    payment_id,
    checked_in_by,
    reservation_snapshot,
    metadata
  )
  values (
    target_hotel_id,
    target_reservation_id,
    target_reservation_room_id,
    created_session_id,
    reservation_room_row.room_id,
    created_payment_id,
    auth.uid(),
    snapshot,
    jsonb_build_object(
      'deposit_transferred', transferred_total,
      'room_charge', reservation_room_row.total_amount
    )
  );

  perform private.write_activity_log(
    target_hotel_id,
    'reservation.room_checked_in',
    'reservation',
    target_reservation_id,
    format(
      'Reservation %s checked in to Room %s.',
      reservation_row.reservation_number,
      room_row.room_number
    ),
    null,
    snapshot,
    jsonb_build_object(
      'reservation_room_id', target_reservation_room_id,
      'guest_session_id', created_session_id,
      'payment_id', created_payment_id,
      'deposit_transferred', transferred_total
    )
  );

  select count(*)::integer,
         count(*) filter (where rr.status in ('checked_in', 'checked_out'))::integer
  into room_count, checked_in_count
  from public.reservation_rooms rr
  where rr.hotel_id = target_hotel_id
    and rr.reservation_id = target_reservation_id
    and rr.status not in ('cancelled', 'released');

  return jsonb_build_object(
    'success', true,
    'reservation_id', target_reservation_id,
    'reservation_room_id', target_reservation_room_id,
    'guest_session_id', created_session_id,
    'payment_id', created_payment_id,
    'room_id', reservation_room_row.room_id,
    'room_number', room_row.room_number,
    'deposit_transferred', transferred_total,
    'checked_in_rooms', checked_in_count,
    'total_rooms', room_count,
    'reservation', snapshot
  );
end;
$$;


ALTER FUNCTION "public"."check_in_reservation_room"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "target_reservation_room_id" "uuid", "expected_reservation_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_in_walk_in_guest"("target_hotel_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_event public.walkin_checkin_events%rowtype;
  hotel_timezone text;
  room_row public.rooms%rowtype;
  room_type_row public.room_types%rowtype;
  guest_row public.guests%rowtype;
  companion_row public.guests%rowtype;
  companion_payload jsonb;
  companions_payload jsonb;
  stay_payload jsonb;
  request_id_value text;
  room_id_value uuid;
  checkin_time_value timestamptz;
  checkout_time_value timestamptz;
  starts_on_value date;
  ends_on_value date;
  room_charge_value numeric(12,2);
  adults_value integer;
  children_value integer;
  created_session_id uuid;
  created_payment_id uuid;
  companion_count integer := 0;
  companion_adults integer := 0;
  companion_children integer := 0;
  result_value jsonb;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Walk-in check-in payload must be a JSON object.';
  end if;

  request_id_value := nullif(trim(payload ->> 'request_id'), '');

  if request_id_value is null or length(request_id_value) < 8 then
    raise exception 'A stable request_id of at least 8 characters is required.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:walkin:'
      || target_hotel_id::text
      || ':'
      || request_id_value,
      0
    )
  );

  select event.*
  into existing_event
  from public.walkin_checkin_events event
  where event.hotel_id = target_hotel_id
    and event.idempotency_key = request_id_value
  limit 1;

  if existing_event.id is not null then
    return coalesce(existing_event.result_snapshot, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  begin
    room_id_value := (payload ->> 'room_id')::uuid;
  exception
    when invalid_text_representation then
      raise exception 'Room ID is invalid.';
  end;

  if room_id_value is null then
    raise exception 'Room is required.';
  end if;

  begin
    checkin_time_value := coalesce(
      nullif(payload ->> 'checkin_time', '')::timestamptz,
      now()
    );
    checkout_time_value :=
      nullif(payload ->> 'checkout_time', '')::timestamptz;
    room_charge_value :=
      round(coalesce((payload ->> 'room_charge')::numeric, 0), 2);
    adults_value :=
      greatest(coalesce((payload ->> 'adults')::integer, 1), 1);
    children_value :=
      greatest(coalesce((payload ->> 'children')::integer, 0), 0);
  exception
    when invalid_text_representation
      or numeric_value_out_of_range then
      raise exception 'Check-in time, checkout time, occupancy or room charge is invalid.';
  end;

  if checkout_time_value is null
     or checkout_time_value <= checkin_time_value
  then
    raise exception 'Checkout time must be after check-in time.';
  end if;

  if room_charge_value < 0 then
    raise exception 'Room charge cannot be negative.';
  end if;

  companions_payload := coalesce(payload -> 'companions', '[]'::jsonb);

  if jsonb_typeof(companions_payload) <> 'array' then
    raise exception 'Companions must be a JSON array.';
  end if;

  select
    (
      count(*) filter (
        where coalesce(
          nullif(lower(trim(item ->> 'guest_category')), ''),
          'adult'
        ) = 'adult'
      )
    )::integer,
    (
      count(*) filter (
        where coalesce(
          nullif(lower(trim(item ->> 'guest_category')), ''),
          'adult'
        ) in ('child', 'infant')
      )
    )::integer
  into companion_adults, companion_children
  from jsonb_array_elements(companions_payload) as companion(item);

  if adults_value <> companion_adults + 1
     or children_value <> companion_children
  then
    raise exception
      'Adults/children counts must match the primary guest and companion categories.';
  end if;

  select h.timezone
  into hotel_timezone
  from public.hotels h
  where h.id = target_hotel_id
    and h.status = 'active'
  for update;

  if hotel_timezone is null then
    raise exception 'Active hotel or hotel timezone was not found.';
  end if;

  starts_on_value :=
    (checkin_time_value at time zone hotel_timezone)::date;
  ends_on_value :=
    (checkout_time_value at time zone hotel_timezone)::date;

  if ends_on_value <= starts_on_value then
    ends_on_value := starts_on_value + 1;
  end if;

  select room.*
  into room_row
  from public.rooms room
  where room.hotel_id = target_hotel_id
    and room.id = room_id_value
  for update;

  if not found then
    raise exception 'Selected room was not found for this hotel.';
  end if;

  if room_row.status <> 'available' then
    raise exception 'Selected room is not currently available.';
  end if;

  select room_type.*
  into room_type_row
  from public.room_types room_type
  where room_type.hotel_id = target_hotel_id
    and room_type.id = room_row.room_type_id;

  if not found then
    raise exception 'Selected room type was not found.';
  end if;

  if adults_value > room_type_row.max_adults
     or children_value > room_type_row.max_children
     or adults_value + children_value > room_type_row.max_occupancy
  then
    raise exception 'Guest count exceeds room capacity.';
  end if;

  if exists (
    select 1
    from public.guest_sessions session
    where session.hotel_id = target_hotel_id
      and session.room_id = room_id_value
      and session.status = 'active'
  ) then
    raise exception 'Selected room already has an active guest stay.';
  end if;

  if exists (
    select 1
    from public.room_inventory_allocations allocation
    where allocation.hotel_id = target_hotel_id
      and allocation.room_id = room_id_value
      and allocation.status = 'active'
      and allocation.stay_dates
        && daterange(starts_on_value, ends_on_value, '[)')
  ) then
    raise exception
      'Selected room is reserved, blocked or occupied during the requested stay.';
  end if;

  select *
  into guest_row
  from private.resolve_or_create_guest_day10(
    target_hotel_id,
    coalesce(payload -> 'guest', '{}'::jsonb)
  );

  insert into public.guest_sessions (
    hotel_id,
    room_id,
    guest_id,
    checkin_time,
    checkout_time,
    status,
    checked_in_by
  )
  values (
    target_hotel_id,
    room_id_value,
    guest_row.id,
    checkin_time_value,
    checkout_time_value,
    'active',
    auth.uid()
  )
  returning id into created_session_id;

  insert into public.payments (
    hotel_id,
    guest_id,
    room_id,
    amount,
    payment_type,
    payment_status,
    notes,
    payment_method,
    guest_session_id
  )
  values (
    target_hotel_id,
    guest_row.id,
    room_id_value,
    room_charge_value,
    'room_charge',
    'pending',
    coalesce(
      nullif(trim(payload ->> 'notes'), ''),
      format(
        'Walk-in room charge · Room %s · %s',
        room_row.room_number,
        guest_row.full_name
      )
    ),
    'cash',
    created_session_id
  )
  returning id into created_payment_id;

  update public.rooms
  set status = 'occupied'
  where hotel_id = target_hotel_id
    and id = room_id_value
    and status = 'available';

  if not found then
    raise exception
      'Room status changed during check-in. No check-in was committed.';
  end if;

  insert into public.stay_room_history (
    hotel_id,
    guest_session_id,
    room_id,
    segment_number,
    movement_type,
    segment_start,
    rate_amount,
    created_by,
    metadata
  )
  values (
    target_hotel_id,
    created_session_id,
    room_id_value,
    1,
    'check_in',
    checkin_time_value,
    room_charge_value,
    auth.uid(),
    jsonb_build_object(
      'source', 'check_in_walk_in_guest',
      'request_id', request_id_value
    )
  );

  for companion_payload in
    select companion.item
    from jsonb_array_elements(companions_payload) as companion(item)
  loop
    select *
    into companion_row
    from private.resolve_or_create_guest_day10(
      target_hotel_id,
      companion_payload
    );

    if companion_row.id = guest_row.id then
      raise exception 'Primary guest cannot also be added as a companion.';
    end if;

    insert into public.guest_companions (
      hotel_id,
      guest_session_id,
      primary_guest_id,
      guest_id,
      relationship,
      guest_category,
      form_c_required,
      created_by
    )
    values (
      target_hotel_id,
      created_session_id,
      guest_row.id,
      companion_row.id,
      nullif(trim(companion_payload ->> 'relationship'), ''),
      coalesce(
        nullif(lower(trim(companion_payload ->> 'guest_category')), ''),
        'adult'
      ),
      coalesce(
        (companion_payload ->> 'form_c_required')::boolean,
        false
      ),
      auth.uid()
    );

    companion_count := companion_count + 1;
  end loop;

  stay_payload := coalesce(payload -> 'stay_details', '{}'::jsonb);

  if jsonb_typeof(stay_payload) <> 'object' then
    raise exception 'Stay details must be a JSON object.';
  end if;

  insert into public.guest_stay_details (
    hotel_id,
    guest_session_id,
    purpose_of_visit,
    arrival_from,
    next_destination,
    arrival_mode,
    arrival_transport_number,
    departure_mode,
    departure_transport_number,
    passport_number,
    passport_issue_country,
    passport_issued_on,
    passport_expires_on,
    visa_number,
    visa_type,
    visa_issue_place,
    visa_issued_on,
    visa_expires_on,
    date_of_arrival_in_india,
    intended_duration_in_india_days,
    form_c_status,
    early_checkin,
    late_checkout,
    special_notes,
    created_by,
    updated_by
  )
  values (
    target_hotel_id,
    created_session_id,
    nullif(trim(stay_payload ->> 'purpose_of_visit'), ''),
    nullif(trim(stay_payload ->> 'arrival_from'), ''),
    nullif(trim(stay_payload ->> 'next_destination'), ''),
    nullif(trim(stay_payload ->> 'arrival_mode'), ''),
    nullif(trim(stay_payload ->> 'arrival_transport_number'), ''),
    nullif(trim(stay_payload ->> 'departure_mode'), ''),
    nullif(trim(stay_payload ->> 'departure_transport_number'), ''),
    nullif(trim(stay_payload ->> 'passport_number'), ''),
    nullif(trim(stay_payload ->> 'passport_issue_country'), ''),
    nullif(stay_payload ->> 'passport_issued_on', '')::date,
    nullif(stay_payload ->> 'passport_expires_on', '')::date,
    nullif(trim(stay_payload ->> 'visa_number'), ''),
    nullif(trim(stay_payload ->> 'visa_type'), ''),
    nullif(trim(stay_payload ->> 'visa_issue_place'), ''),
    nullif(stay_payload ->> 'visa_issued_on', '')::date,
    nullif(stay_payload ->> 'visa_expires_on', '')::date,
    nullif(stay_payload ->> 'date_of_arrival_in_india', '')::date,
    nullif(stay_payload ->> 'intended_duration_in_india_days', '')::integer,
    coalesce(
      nullif(trim(stay_payload ->> 'form_c_status'), ''),
      case
        when guest_row.is_foreign_guest then 'pending'
        else 'not_required'
      end
    ),
    coalesce((stay_payload ->> 'early_checkin')::boolean, false),
    coalesce((stay_payload ->> 'late_checkout')::boolean, false),
    nullif(trim(stay_payload ->> 'special_notes'), ''),
    auth.uid(),
    auth.uid()
  );

  result_value := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'request_id', request_id_value,
    'hotel_id', target_hotel_id,
    'guest_id', guest_row.id,
    'guest_session_id', created_session_id,
    'room_id', room_id_value,
    'room_number', room_row.room_number,
    'payment_id', created_payment_id,
    'room_charge', room_charge_value,
    'checkin_time', checkin_time_value,
    'checkout_time', checkout_time_value,
    'companion_count', companion_count
  );

  insert into public.walkin_checkin_events (
    hotel_id,
    guest_session_id,
    guest_id,
    room_id,
    payment_id,
    idempotency_key,
    checked_in_by,
    checked_in_at,
    request_snapshot,
    result_snapshot,
    metadata
  )
  values (
    target_hotel_id,
    created_session_id,
    guest_row.id,
    room_id_value,
    created_payment_id,
    request_id_value,
    auth.uid(),
    checkin_time_value,
    jsonb_build_object(
      'request_id', request_id_value,
      'room_id', room_id_value,
      'checkout_time', checkout_time_value,
      'room_charge', room_charge_value,
      'guest_id', guest_row.id,
      'companion_count', companion_count
    ),
    result_value,
    jsonb_build_object(
      'source', 'check_in_walk_in_guest',
      'hotel_timezone', hotel_timezone
    )
  );

  perform private.write_activity_log(
    target_hotel_id,
    'front_office.walkin_checked_in',
    'guest_session',
    created_session_id,
    format(
      'Walk-in guest %s checked in to Room %s.',
      guest_row.full_name,
      room_row.room_number
    ),
    null,
    result_value,
    jsonb_build_object(
      'request_id', request_id_value,
      'guest_id', guest_row.id,
      'room_id', room_id_value,
      'payment_id', created_payment_id,
      'companion_count', companion_count
    )
  );

  return result_value;
end;
$$;


ALTER FUNCTION "public"."check_in_walk_in_guest"("target_hotel_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_in_walk_in_guest"("target_hotel_id" "uuid", "payload" "jsonb") IS 'Day 10 authoritative atomic direct/walk-in check-in. Creates/reuses the guest, stay, room charge, inventory allocation, stay details, companions, room history and immutable event in one transaction.';



CREATE OR REPLACE FUNCTION "public"."checkout_guest_session"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "tax_percent" numeric DEFAULT 0, "discount_type" "text" DEFAULT 'fixed'::"text", "discount_value" numeric DEFAULT 0, "remaining_payment_collected" boolean DEFAULT false, "settlement_payment_method" "text" DEFAULT 'cash'::"text", "settlement_transaction_reference" "text" DEFAULT NULL::"text", "invoice_notes" "text" DEFAULT NULL::"text", "allow_excess_paid" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_row public.guest_sessions%rowtype;
  room_row public.rooms%rowtype;
  guest_row public.guests%rowtype;
  existing_event public.reservation_checkout_events%rowtype;
  existing_invoice public.invoices%rowtype;
  payment_row public.payments%rowtype;
  stay_end timestamptz := now();
  stay_hours integer;
  stay_nights integer;
  safe_tax_percent numeric(12,2);
  safe_discount_value numeric(12,2);
  room_amount numeric(12,2) := 0;
  food_amount numeric(12,2) := 0;
  manual_amount numeric(12,2) := 0;
  service_amount numeric(12,2) := 0;
  subtotal numeric(12,2) := 0;
  tax_amount numeric(12,2) := 0;
  discount_amount numeric(12,2) := 0;
  grand_total numeric(12,2) := 0;
  previously_paid numeric(12,2) := 0;
  amount_to_collect numeric(12,2) := 0;
  excess_paid numeric(12,2) := 0;
  amount_remaining numeric(12,2) := 0;
  payment_collected numeric(12,2) := 0;
  payment_balance numeric(12,2) := 0;
  collection_amount numeric(12,2) := 0;
  created_invoice_id uuid;
  created_invoice_number text;
  settlement_payment_id uuid;
  housekeeping_task_id uuid;
  reservation_snapshot jsonb;
  checkout_snapshot jsonb;
  open_food_count integer := 0;
  food_order_count integer := 0;
  food_item_count integer := 0;
  actor_id uuid := auth.uid();
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  if target_guest_session_id is null then
    raise exception 'Guest session is required.';
  end if;

  safe_tax_percent := round(coalesce(tax_percent, 0)::numeric, 2);
  safe_discount_value := round(coalesce(discount_value, 0)::numeric, 2);
  discount_type := lower(trim(coalesce(discount_type, 'fixed')));
  settlement_payment_method := lower(trim(coalesce(settlement_payment_method, 'cash')));

  if safe_tax_percent < 0 or safe_tax_percent > 100 then
    raise exception 'Tax percentage must be between 0 and 100.';
  end if;

  if discount_type not in ('fixed', 'percentage') then
    raise exception 'Discount type must be fixed or percentage.';
  end if;

  if safe_discount_value < 0 then
    raise exception 'Discount value cannot be negative.';
  end if;

  if discount_type = 'percentage' and safe_discount_value > 100 then
    raise exception 'Discount percentage cannot exceed 100%%.';
  end if;

  if settlement_payment_method not in ('cash', 'upi', 'card', 'bank_transfer', 'other') then
    raise exception 'Unsupported settlement payment method.';
  end if;

  if settlement_payment_method in ('upi', 'card', 'bank_transfer')
     and length(trim(coalesce(settlement_transaction_reference, ''))) = 0
  then
    raise exception 'A transaction/reference number is required for this payment method.';
  end if;

  select gs.*
  into session_row
  from public.guest_sessions gs
  where gs.hotel_id = target_hotel_id
    and gs.id = target_guest_session_id
  for update;

  if not found then
    raise exception 'Guest stay not found.';
  end if;

  select event.*
  into existing_event
  from public.reservation_checkout_events event
  where event.hotel_id = target_hotel_id
    and event.guest_session_id = target_guest_session_id
  limit 1;

  if existing_event.id is not null then
    select inv.* into existing_invoice
    from public.invoices inv
    where inv.id = existing_event.invoice_id;

    raise exception 'This stay is already checked out. Invoice: %',
      coalesce(existing_invoice.invoice_number, existing_event.invoice_id::text);
  end if;

  if session_row.status <> 'active' then
    raise exception 'Only an active guest stay can be checked out.';
  end if;

  if session_row.checkin_time is null then
    raise exception 'Guest check-in time is missing.';
  end if;

  select rm.* into room_row
  from public.rooms rm
  where rm.hotel_id = target_hotel_id
    and rm.id = session_row.room_id
  for update;

  if not found then raise exception 'Stay room not found.'; end if;

  select g.* into guest_row
  from public.guests g
  where g.hotel_id = target_hotel_id
    and g.id = session_row.guest_id
  for update;

  if not found then raise exception 'Stay guest not found.'; end if;

  select inv.* into existing_invoice
  from public.invoices inv
  where inv.hotel_id = target_hotel_id
    and inv.guest_session_id = target_guest_session_id
  order by inv.created_at
  limit 1
  for update;

  if existing_invoice.id is not null then
    raise exception 'Invoice already exists for this stay: %',
      coalesce(existing_invoice.invoice_number, existing_invoice.id::text);
  end if;

  select count(*)::integer
  into open_food_count
  from public.food_orders fo
  where fo.hotel_id = target_hotel_id
    and fo.guest_id = session_row.guest_id
    and fo.room_id = session_row.room_id
    and fo.created_at >= session_row.checkin_time
    and fo.order_status in ('pending', 'accepted', 'preparing', 'out_for_delivery');

  if open_food_count > 0 then
    raise exception '% food order(s) are still active. Complete or cancel them before checkout.', open_food_count;
  end if;

  stay_hours := greatest(
    1,
    ceil(extract(epoch from (stay_end - session_row.checkin_time)) / 3600.0)::integer
  );
  stay_nights := greatest(1, ceil(stay_hours / 24.0)::integer);

  -- Reservation-linked payments are exact. Legacy/direct stays fall back to
  -- same hotel + guest + room + stay window.
  select coalesce(sum(p.amount), 0)::numeric(12,2)
  into room_amount
  from public.payments p
  where p.hotel_id = target_hotel_id
    and p.guest_id = session_row.guest_id
    and p.room_id = session_row.room_id
    and p.payment_type = 'room_charge'
    and (
      p.guest_session_id = target_guest_session_id
      or (
        p.guest_session_id is null
        and p.created_at >= session_row.checkin_time
      )
    );

  select
    coalesce(sum(fo.total_amount), 0)::numeric(12,2),
    count(*)::integer
  into food_amount, food_order_count
  from public.food_orders fo
  where fo.hotel_id = target_hotel_id
    and fo.guest_id = session_row.guest_id
    and fo.room_id = session_row.room_id
    and fo.order_status = 'delivered'
    and fo.created_at >= session_row.checkin_time;

  select coalesce(sum(foi.quantity), 0)::integer
  into food_item_count
  from public.food_orders fo
  join public.food_order_items foi
    on foi.order_id = fo.id
  where fo.hotel_id = target_hotel_id
    and fo.guest_id = session_row.guest_id
    and fo.room_id = session_row.room_id
    and fo.order_status = 'delivered'
    and fo.created_at >= session_row.checkin_time;

  select coalesce(sum(mc.charge_amount), 0)::numeric(12,2)
  into manual_amount
  from public.manual_charges mc
  where mc.hotel_id = target_hotel_id
    and mc.guest_id = session_row.guest_id
    and mc.room_id = session_row.room_id
    and mc.created_at >= session_row.checkin_time;

  -- service_requests currently has no mandatory monetary column. Reading via
  -- to_jsonb preserves compatibility if a charge field is added later.
  select coalesce(sum(
    coalesce(
      nullif(to_jsonb(sr)->>'service_amount', '')::numeric,
      nullif(to_jsonb(sr)->>'charge_amount', '')::numeric,
      nullif(to_jsonb(sr)->>'amount', '')::numeric,
      0
    )
  ), 0)::numeric(12,2)
  into service_amount
  from public.service_requests sr
  where sr.hotel_id = target_hotel_id
    and sr.guest_id = session_row.guest_id
    and sr.room_id = session_row.room_id
    and sr.status = 'completed'
    and sr.created_at >= session_row.checkin_time;

  subtotal := round(room_amount + food_amount + manual_amount + service_amount, 2);
  tax_amount := round(subtotal * safe_tax_percent / 100.0, 2);

  if discount_type = 'percentage' then
    discount_amount := round((subtotal + tax_amount) * safe_discount_value / 100.0, 2);
  else
    discount_amount := safe_discount_value;
  end if;

  discount_amount := least(subtotal + tax_amount, discount_amount);
  grand_total := greatest(round(subtotal + tax_amount - discount_amount, 2), 0);

  select coalesce(sum(paid_amount_value), 0)::numeric(12,2)
  into previously_paid
  from (
    select pc.amount as paid_amount_value
    from public.payment_collections pc
    join public.payments p
      on p.hotel_id = pc.hotel_id
     and p.id = pc.payment_id
    where pc.hotel_id = target_hotel_id
      and p.guest_id = session_row.guest_id
      and p.room_id = session_row.room_id
      and (
        p.guest_session_id = target_guest_session_id
        or (
          p.guest_session_id is null
          and p.created_at >= session_row.checkin_time
        )
      )

    union all

    select p.amount
    from public.payments p
    where p.hotel_id = target_hotel_id
      and p.guest_id = session_row.guest_id
      and p.room_id = session_row.room_id
      and p.payment_status = 'paid'
      and (
        p.guest_session_id = target_guest_session_id
        or (
          p.guest_session_id is null
          and p.created_at >= session_row.checkin_time
        )
      )
      and not exists (
        select 1
        from public.payment_collections pc
        where pc.hotel_id = p.hotel_id
          and pc.payment_id = p.id
      )
  ) paid_rows;

  amount_to_collect := greatest(round(grand_total - previously_paid, 2), 0);
  excess_paid := greatest(round(previously_paid - grand_total, 2), 0);

  if amount_to_collect > 0 and not coalesce(remaining_payment_collected, false) then
    raise exception 'Confirm collection of the remaining amount before checkout.';
  end if;

  if excess_paid > 0 and not coalesce(allow_excess_paid, false) then
    raise exception 'Previous payments exceed the final bill by %. Verify refund/adjustment before checkout.', excess_paid;
  end if;

  created_invoice_number := format(
    'INV-%s-%s',
    to_char(stay_end at time zone 'UTC', 'YYYYMMDD'),
    upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8))
  );

  insert into public.invoices (
    hotel_id,
    guest_session_id,
    room_id,
    guest_id,
    invoice_number,
    room_amount,
    food_amount,
    manual_amount,
    service_amount,
    subtotal_amount,
    tax_percent,
    tax_amount,
    discount_type,
    discount_value,
    discount_amount,
    previous_paid_amount,
    amount_to_collect,
    total_amount,
    payment_status,
    invoice_status,
    paid_amount,
    pending_amount,
    settled_at,
    checkin_time,
    checkout_time,
    stay_hours,
    stay_nights,
    food_order_count,
    food_item_count,
    invoice_notes
  ) values (
    target_hotel_id,
    target_guest_session_id,
    session_row.room_id,
    session_row.guest_id,
    created_invoice_number,
    room_amount,
    food_amount,
    manual_amount,
    service_amount,
    subtotal,
    safe_tax_percent,
    tax_amount,
    discount_type,
    safe_discount_value,
    discount_amount,
    previously_paid,
    amount_to_collect,
    grand_total,
    'paid',
    'paid',
    grand_total,
    0,
    stay_end,
    session_row.checkin_time,
    stay_end,
    stay_hours,
    stay_nights,
    food_order_count,
    food_item_count,
    nullif(trim(coalesce(invoice_notes, '')), '')
  ) returning id into created_invoice_id;

  if room_amount > 0 then
    insert into public.invoice_items (
      invoice_id, hotel_id, guest_id, room_id,
      item_type, description, quantity, unit_price, amount, source_id
    ) values (
      created_invoice_id,
      target_hotel_id,
      session_row.guest_id,
      session_row.room_id,
      'room',
      format('%s · %s night(s)', coalesce(room_row.room_type, 'Hotel Room'), stay_nights),
      stay_nights,
      case when stay_nights > 0 then round(room_amount / stay_nights, 2) else room_amount end,
      room_amount,
      target_guest_session_id
    );
  end if;

  insert into public.invoice_items (
    invoice_id, hotel_id, guest_id, room_id,
    item_type, description, quantity, unit_price, amount, source_id
  )
  select
    created_invoice_id,
    target_hotel_id,
    session_row.guest_id,
    session_row.room_id,
    'food',
    coalesce(mi.item_name, 'Food Item'),
    foi.quantity,
    foi.price,
    round(foi.quantity * foi.price, 2),
    fo.id
  from public.food_orders fo
  join public.food_order_items foi
    on foi.order_id = fo.id
  left join public.menu_items mi
    on mi.id = foi.menu_item_id
  where fo.hotel_id = target_hotel_id
    and fo.guest_id = session_row.guest_id
    and fo.room_id = session_row.room_id
    and fo.order_status = 'delivered'
    and fo.created_at >= session_row.checkin_time
    and foi.quantity > 0
    and foi.price > 0;

  insert into public.invoice_items (
    invoice_id, hotel_id, guest_id, room_id,
    item_type, description, quantity, unit_price, amount, source_id
  )
  select
    created_invoice_id,
    target_hotel_id,
    session_row.guest_id,
    session_row.room_id,
    'manual_charge',
    coalesce(mc.charge_name, 'Additional Charge'),
    1,
    mc.charge_amount,
    mc.charge_amount,
    mc.id
  from public.manual_charges mc
  where mc.hotel_id = target_hotel_id
    and mc.guest_id = session_row.guest_id
    and mc.room_id = session_row.room_id
    and mc.created_at >= session_row.checkin_time
    and mc.charge_amount > 0;

  if service_amount > 0 then
    insert into public.invoice_items (
      invoice_id, hotel_id, guest_id, room_id,
      item_type, description, quantity, unit_price, amount, source_id
    ) values (
      created_invoice_id,
      target_hotel_id,
      session_row.guest_id,
      session_row.room_id,
      'service',
      'Completed hotel services',
      1,
      service_amount,
      service_amount,
      null
    );
  end if;

  if tax_amount > 0 then
    insert into public.invoice_items (
      invoice_id, hotel_id, guest_id, room_id,
      item_type, description, quantity, unit_price, amount, source_id
    ) values (
      created_invoice_id,
      target_hotel_id,
      session_row.guest_id,
      session_row.room_id,
      'tax',
      format('Tax %s%%', safe_tax_percent),
      1,
      tax_amount,
      tax_amount,
      null
    );
  end if;

  if discount_amount > 0 then
    insert into public.invoice_items (
      invoice_id, hotel_id, guest_id, room_id,
      item_type, description, quantity, unit_price, amount, source_id
    ) values (
      created_invoice_id,
      target_hotel_id,
      session_row.guest_id,
      session_row.room_id,
      'discount',
      case
        when discount_type = 'percentage' then format('Discount %s%%', safe_discount_value)
        else 'Fixed Discount'
      end,
      1,
      -discount_amount,
      -discount_amount,
      null
    );
  end if;

  -- Record the newly collected balance against existing payment demands first.
  amount_remaining := amount_to_collect;

  for payment_row in
    select p.*
    from public.payments p
    where p.hotel_id = target_hotel_id
      and p.guest_id = session_row.guest_id
      and p.room_id = session_row.room_id
      and (
        p.guest_session_id = target_guest_session_id
        or (
          p.guest_session_id is null
          and p.created_at >= session_row.checkin_time
        )
      )
    order by p.created_at, p.id
    for update
  loop
    select coalesce(sum(pc.amount), 0)::numeric(12,2)
    into payment_collected
    from public.payment_collections pc
    where pc.hotel_id = target_hotel_id
      and pc.payment_id = payment_row.id;

    payment_balance := greatest(round(payment_row.amount - payment_collected, 2), 0);
    collection_amount := least(amount_remaining, payment_balance);

    if collection_amount > 0 then
      insert into public.payment_collections (
        hotel_id,
        payment_id,
        guest_id,
        room_id,
        amount,
        payment_method,
        transaction_reference,
        notes,
        collected_by,
        collected_at,
        guest_session_id,
        reservation_id,
        invoice_id
      ) values (
        target_hotel_id,
        payment_row.id,
        session_row.guest_id,
        session_row.room_id,
        collection_amount,
        settlement_payment_method,
        nullif(trim(coalesce(settlement_transaction_reference, '')), ''),
        'Final checkout settlement collected by StayQR',
        actor_id,
        stay_end,
        target_guest_session_id,
        session_row.reservation_id,
        created_invoice_id
      );

      amount_remaining := round(amount_remaining - collection_amount, 2);
      payment_collected := round(payment_collected + collection_amount, 2);
    end if;

    update public.payments
    set
      invoice_id = created_invoice_id,
      payment_status = case
        when payment_collected >= payment_row.amount then 'paid'
        when payment_collected > 0 then 'partial'
        else payment_row.payment_status
      end,
      payment_method = case
        when collection_amount > 0 then settlement_payment_method
        else payment_method
      end,
      transaction_reference = case
        when collection_amount > 0 then nullif(trim(coalesce(settlement_transaction_reference, '')), '')
        else transaction_reference
      end,
      paid_at = case
        when payment_collected >= payment_row.amount then stay_end
        else paid_at
      end
    where hotel_id = target_hotel_id
      and id = payment_row.id;
  end loop;

  -- Charges without an existing demand receive one exact settlement demand.
  if amount_remaining > 0 then
    insert into public.payments (
      hotel_id,
      guest_id,
      room_id,
      amount,
      payment_type,
      payment_status,
      notes,
      payment_method,
      transaction_reference,
      paid_at,
      collected_by,
      payment_notes,
      invoice_id,
      guest_session_id,
      reservation_id,
      reservation_room_id
    ) values (
      target_hotel_id,
      session_row.guest_id,
      session_row.room_id,
      amount_remaining,
      'checkout_settlement',
      'paid',
      format('Final checkout settlement for %s', created_invoice_number),
      settlement_payment_method,
      nullif(trim(coalesce(settlement_transaction_reference, '')), ''),
      stay_end,
      actor_id,
      'Created atomically during final checkout',
      created_invoice_id,
      target_guest_session_id,
      session_row.reservation_id,
      session_row.reservation_room_id
    ) returning id into settlement_payment_id;

    insert into public.payment_collections (
      hotel_id,
      payment_id,
      guest_id,
      room_id,
      amount,
      payment_method,
      transaction_reference,
      notes,
      collected_by,
      collected_at,
      guest_session_id,
      reservation_id,
      invoice_id
    ) values (
      target_hotel_id,
      settlement_payment_id,
      session_row.guest_id,
      session_row.room_id,
      amount_remaining,
      settlement_payment_method,
      nullif(trim(coalesce(settlement_transaction_reference, '')), ''),
      'Final checkout settlement collected by StayQR',
      actor_id,
      stay_end,
      target_guest_session_id,
      session_row.reservation_id,
      created_invoice_id
    );

    amount_remaining := 0;
  end if;

  update public.payment_collections pc
  set invoice_id = created_invoice_id
  from public.payments p
  where p.hotel_id = target_hotel_id
    and p.id = pc.payment_id
    and pc.hotel_id = target_hotel_id
    and p.guest_id = session_row.guest_id
    and p.room_id = session_row.room_id
    and (
      p.guest_session_id = target_guest_session_id
      or (
        p.guest_session_id is null
        and p.created_at >= session_row.checkin_time
      )
    );

  update public.food_orders
  set payment_status = 'paid'
  where hotel_id = target_hotel_id
    and guest_id = session_row.guest_id
    and room_id = session_row.room_id
    and order_status = 'delivered'
    and created_at >= session_row.checkin_time;

  update public.manual_charges
  set payment_status = 'paid'
  where hotel_id = target_hotel_id
    and guest_id = session_row.guest_id
    and room_id = session_row.room_id
    and created_at >= session_row.checkin_time;

  update public.guest_sessions
  set
    status = 'completed',
    expired_at = stay_end,
    checked_out_at = stay_end,
    checked_out_by = actor_id
  where hotel_id = target_hotel_id
    and id = target_guest_session_id
    and status = 'active';

  if not found then
    raise exception 'Checkout lost its active-stay lock. Refresh and try again.';
  end if;

  -- Release the active inventory ledger entry so an early checkout does not
  -- keep the room unavailable until the original departure date.
  update public.room_inventory_allocations
  set
    status = 'released',
    released_at = stay_end,
    updated_at = stay_end
  where hotel_id = target_hotel_id
    and status = 'active'
    and (
      reservation_room_id = session_row.reservation_room_id
      or guest_session_id = target_guest_session_id
    );

  -- The Day 5 guest-session trigger advances linked reservation records and
  -- changes occupied rooms to cleaning. Direct stays are handled here too.
  update public.rooms
  set status = 'cleaning'
  where hotel_id = target_hotel_id
    and id = session_row.room_id
    and status = 'occupied';

  select task.id into housekeeping_task_id
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.room_id = session_row.room_id
    and task.task_type = 'room_cleaning'
    and task.status in ('pending', 'in_progress')
  order by task.created_at
  limit 1
  for update;

  if housekeeping_task_id is null then
    insert into public.housekeeping_tasks (
      hotel_id,
      room_id,
      room_number,
      task_type,
      status,
      notes
    ) values (
      target_hotel_id,
      session_row.room_id,
      room_row.room_number,
      'room_cleaning',
      'pending',
      format('Checkout cleaning task for invoice %s', created_invoice_number)
    ) returning id into housekeeping_task_id;
  end if;

  if session_row.reservation_id is not null then
    reservation_snapshot := private.build_reservation_json(
      target_hotel_id,
      session_row.reservation_id
    );
  end if;

  checkout_snapshot := jsonb_build_object(
    'invoice_id', created_invoice_id,
    'invoice_number', created_invoice_number,
    'hotel_id', target_hotel_id,
    'guest_session_id', target_guest_session_id,
    'reservation_id', session_row.reservation_id,
    'reservation_room_id', session_row.reservation_room_id,
    'room_id', session_row.room_id,
    'room_number', room_row.room_number,
    'guest_id', session_row.guest_id,
    'guest_name', guest_row.full_name,
    'checkin_time', session_row.checkin_time,
    'checkout_time', stay_end,
    'stay_hours', stay_hours,
    'stay_nights', stay_nights,
    'room_amount', room_amount,
    'food_amount', food_amount,
    'manual_amount', manual_amount,
    'service_amount', service_amount,
    'subtotal', subtotal,
    'tax_percent', safe_tax_percent,
    'tax_amount', tax_amount,
    'discount_type', discount_type,
    'discount_value', safe_discount_value,
    'discount_amount', discount_amount,
    'grand_total', grand_total,
    'previously_paid', previously_paid,
    'amount_collected_at_checkout', amount_to_collect,
    'excess_paid', excess_paid,
    'housekeeping_task_id', housekeeping_task_id,
    'reservation', reservation_snapshot
  );

  insert into public.reservation_checkout_events (
    hotel_id,
    guest_session_id,
    reservation_id,
    reservation_room_id,
    room_id,
    guest_id,
    invoice_id,
    checked_out_by,
    checked_out_at,
    settlement_snapshot,
    metadata
  ) values (
    target_hotel_id,
    target_guest_session_id,
    session_row.reservation_id,
    session_row.reservation_room_id,
    session_row.room_id,
    session_row.guest_id,
    created_invoice_id,
    actor_id,
    stay_end,
    checkout_snapshot,
    jsonb_build_object(
      'payment_method', settlement_payment_method,
      'transaction_reference', nullif(trim(coalesce(settlement_transaction_reference, '')), '')
    )
  );

  if session_row.reservation_id is not null then
    perform private.write_activity_log(
      target_hotel_id,
      'reservation.room_checkout_completed',
      'reservation',
      session_row.reservation_id,
      format('Room %s checkout completed with invoice %s.', room_row.room_number, created_invoice_number),
      null,
      reservation_snapshot,
      jsonb_build_object(
        'reservation_room_id', session_row.reservation_room_id,
        'guest_session_id', target_guest_session_id,
        'invoice_id', created_invoice_id,
        'housekeeping_task_id', housekeeping_task_id,
        'grand_total', grand_total,
        'amount_collected_at_checkout', amount_to_collect
      )
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'invoice_id', created_invoice_id,
    'invoice_number', created_invoice_number,
    'guest_session_id', target_guest_session_id,
    'reservation_id', session_row.reservation_id,
    'reservation_room_id', session_row.reservation_room_id,
    'room_id', session_row.room_id,
    'room_number', room_row.room_number,
    'housekeeping_task_id', housekeeping_task_id,
    'grand_total', grand_total,
    'previously_paid', previously_paid,
    'amount_collected_at_checkout', amount_to_collect,
    'room_status', 'cleaning',
    'stay_status', 'completed',
    'reservation', reservation_snapshot
  );
end;
$$;


ALTER FUNCTION "public"."checkout_guest_session"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "tax_percent" numeric, "discount_type" "text", "discount_value" numeric, "remaining_payment_collected" boolean, "settlement_payment_method" "text", "settlement_transaction_reference" "text", "invoice_notes" "text", "allow_excess_paid" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_cashier_shift"("h" "uuid", "shift_id_value" "uuid", "declared_cash_value" numeric, "notes_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  request_key text;
  s public.cashier_shifts%rowtype;
  snap jsonb;
  hash_value text;
  expected_value numeric;
begin
  if not private.user_has_any_permission(h,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Cashier shift closing access denied.';
  end if;
  actor:=private.day11_require_current_actor();
  request_key:=nullif(trim(request_id_value),'');
  if request_key is null or length(request_key)<8 then raise exception 'Request ID of at least eight characters required.'; end if;
  if declared_cash_value is null or declared_cash_value<0 then raise exception 'Declared cash cannot be negative.'; end if;
  select * into s from public.cashier_shifts where hotel_id=h and id=shift_id_value for update;
  if not found then raise exception 'Cashier shift not found.'; end if;
  if s.status='closed' then
    if s.close_idempotency_key=request_key then
      return jsonb_build_object('ok',true,'idempotent',true,'shift',to_jsonb(s),'snapshot',s.snapshot_json);
    end if;
    raise exception 'Cashier shift already closed.';
  end if;
  if s.opened_by<>actor then raise exception 'Only opening cashier can close shift.'; end if;
  snap:=private.day12_build_cashier_shift_snapshot(h,shift_id_value);
  expected_value:=(snap->>'expected_cash')::numeric;
  snap:=snap||jsonb_build_object(
    'declared_cash',declared_cash_value,'cash_variance',declared_cash_value-expected_value,
    'closed_at',now(),'closed_by',actor,'close_notes',nullif(trim(notes_value),''),
    'close_request_id',request_key
  );
  hash_value:=private.day12_hash_snapshot(snap);
  update public.cashier_shifts
  set status='closed',closed_at=now(),closed_by=actor,expected_cash=expected_value,
      declared_cash=declared_cash_value,cash_variance=declared_cash_value-expected_value,
      close_notes=nullif(trim(notes_value),''),close_idempotency_key=request_key,
      snapshot_json=snap,snapshot_hash=hash_value,
      metadata=metadata||jsonb_build_object('close_request_id',request_key),updated_at=now()
  where hotel_id=h and id=shift_id_value returning * into s;
  return jsonb_build_object('ok',true,'idempotent',false,'shift',to_jsonb(s),'snapshot',snap);
end;
$$;


ALTER FUNCTION "public"."close_cashier_shift"("h" "uuid", "shift_id_value" "uuid", "declared_cash_value" numeric, "notes_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_night_audit"("h" "uuid", "business_date_value" "date", "acknowledge_exceptions" boolean, "notes_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  request_key text;
  existing public.night_audits%rowtype;
  audit_row public.night_audits%rowtype;
  export_row public.accounting_exports%rowtype;
  preview jsonb;
  financial jsonb;
  snap jsonb;
  hash_value text;
  b integer;
  w integer;
  er record;
begin
  if not private.user_has_any_permission(h,array['invoices.manage','payments.manage','checkout.manage']::text[]) then
    raise exception 'Night-audit close access denied.';
  end if;
  actor:=private.day11_require_current_actor();
  request_key:=nullif(trim(request_id_value),'');
  if request_key is null or length(request_key)<8 then raise exception 'Request ID of at least eight characters required.'; end if;
  perform pg_advisory_xact_lock(hashtextextended('stayqr:night-audit:'||h::text||':'||business_date_value::text,0));
  select * into existing from public.night_audits where hotel_id=h and idempotency_key=request_key;
  if existing.id is not null then
    return jsonb_build_object('ok',true,'idempotent',true,'night_audit',to_jsonb(existing),'snapshot',existing.snapshot_json);
  end if;
  if exists(select 1 from public.night_audits where hotel_id=h and business_date=business_date_value and status='closed') then
    raise exception 'Business date % is already closed.',business_date_value;
  end if;
  preview:=private.day12_build_day_close_preview(h,business_date_value);
  b:=(preview->>'blocker_count')::integer;
  w:=(preview->>'warning_count')::integer;
  if b>0 and not coalesce(acknowledge_exceptions,false) then
    raise exception 'Day close has % blocker(s). Explicit acknowledgement is required.',b;
  end if;
  financial:=preview->'financial_summary';
  snap:=preview||jsonb_build_object(
    'closed_at',now(),'closed_by',actor,'acknowledged_exceptions',coalesce(acknowledge_exceptions,false),
    'close_notes',nullif(trim(notes_value),''),'request_id',request_key
  );
  hash_value:=private.day12_hash_snapshot(snap);
  insert into public.night_audits(
    hotel_id,business_date,audit_number,status,closed_with_exceptions,started_at,closed_at,closed_by,close_notes,
    blocker_count,warning_count,exception_count,charges_amount,discounts_amount,taxes_amount,collections_amount,
    refunds_amount,credits_amount,open_balance_amount,idempotency_key,snapshot_json,snapshot_hash,metadata
  ) values (
    h,business_date_value,'NA/'||to_char(business_date_value,'YYYYMMDD'),'closed',(b+w)>0,now(),now(),actor,
    nullif(trim(notes_value),''),b,w,b+w,(financial->>'charges_amount')::numeric,(financial->>'discounts_amount')::numeric,
    (financial->>'taxes_amount')::numeric,(financial->>'collections_amount')::numeric,(financial->>'refunds_amount')::numeric,
    (financial->>'credits_amount')::numeric,(financial->>'open_balance_amount')::numeric,request_key,snap,hash_value,
    jsonb_build_object('acknowledged_exceptions',coalesce(acknowledge_exceptions,false),'day',12)
  ) returning * into audit_row;

  for er in select value from jsonb_array_elements(preview->'exceptions')
  loop
    insert into public.night_audit_exceptions(
      hotel_id,night_audit_id,exception_type,severity,entity_type,entity_id,amount,message,status,acknowledged,
      resolution_notes,source_snapshot
    ) values (
      h,audit_row.id,er.value->>'exception_type',er.value->>'severity',er.value->>'entity_type',
      nullif(er.value->>'entity_id','')::uuid,nullif(er.value->>'amount','')::numeric,er.value->>'message',
      case when coalesce(acknowledge_exceptions,false) then 'waived' else 'open' end,
      coalesce(acknowledge_exceptions,false),
      case when coalesce(acknowledge_exceptions,false) then nullif(trim(notes_value),'') else null end,
      coalesce(er.value->'source_snapshot','{}'::jsonb)
    );
  end loop;

  export_row:=private.day12_create_accounting_export(
    h,audit_row.id,business_date_value,business_date_value,'night-audit-export:'||audit_row.id::text,actor
  );
  return jsonb_build_object(
    'ok',true,'idempotent',false,'night_audit',to_jsonb(audit_row),'snapshot',snap,'accounting_export',to_jsonb(export_row)
  );
end;
$$;


ALTER FUNCTION "public"."close_night_audit"("h" "uuid", "business_date_value" "date", "acknowledge_exceptions" boolean, "notes_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_housekeeping_cleaning"("target_hotel_id" "uuid", "target_task_id" "uuid", "notes_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.housekeeping_tasks%rowtype;
  incomplete_required integer;
  previous_status_value text;
  existing_event_id uuid;
begin
  actor_id_value :=
    private.day13_require_housekeeping_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select event_record.id
  into existing_event_id
  from public.housekeeping_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type =
        'cleaning_completed';

  if existing_event_id is not null then
    select task.*
    into task_row
    from public.housekeeping_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select task.*
  into task_row
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Housekeeping task was not found.';
  end if;

  if task_row.status <> 'in_progress' then
    raise exception
      'Cleaning can complete only from in_progress status.';
  end if;

  select count(*)
  into incomplete_required
  from public.housekeeping_task_items item
  where item.hotel_id = target_hotel_id
    and item.task_id = target_task_id
    and item.is_required
    and item.item_status not in (
      'completed',
      'not_applicable'
    );

  if incomplete_required > 0 then
    raise exception
      '% required checklist item(s) remain incomplete.',
      incomplete_required;
  end if;

  previous_status_value := task_row.status;

  update public.housekeeping_tasks
  set
    status = 'cleaning_complete',
    cleaning_completed_at = now(),
    cleaning_completed_by = actor_id_value,
    inspection_status = 'pending',
    notes =
      coalesce(
        nullif(trim(notes_value), ''),
        notes
      ),
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'cleaning_complete_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_housekeeping_event(
    target_hotel_id,
    target_task_id,
    'cleaning_completed',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'required_items_complete', true
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row)
  );
end;
$$;


ALTER FUNCTION "public"."complete_housekeeping_cleaning"("target_hotel_id" "uuid", "target_task_id" "uuid", "notes_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."configure_hotel_inventory"("target_hotel_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  floor_item jsonb;
  room_type_item jsonb;
  rate_item jsonb;

  item_name text;
  item_code text;
  item_description text;
  room_type_code_value text;
  currency_value text;

  existing_id uuid;
  resolved_room_type_id uuid;

  floor_inserted integer := 0;
  floor_updated integer := 0;
  room_type_inserted integer := 0;
  room_type_updated integer := 0;
  rate_inserted integer := 0;
  rate_updated integer := 0;

  readiness jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if target_hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = target_hotel_id
     )
  then
    raise exception 'Unknown hotel.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_permission(target_hotel_id, 'hotel.manage')
  ) then
    raise exception 'Hotel inventory access denied.';
  end if;

  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Inventory payload must be a JSON object.';
  end if;

  if payload ? 'floors'
     and coalesce(
       jsonb_typeof(payload -> 'floors'),
       'null'
     ) <> 'array'
  then
    raise exception 'floors must be a JSON array.';
  end if;

  if payload ? 'room_types'
     and coalesce(
       jsonb_typeof(payload -> 'room_types'),
       'null'
     ) <> 'array'
  then
    raise exception 'room_types must be a JSON array.';
  end if;

  if payload ? 'rate_plans'
     and coalesce(
       jsonb_typeof(payload -> 'rate_plans'),
       'null'
     ) <> 'array'
  then
    raise exception 'rate_plans must be a JSON array.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:configure-inventory:' || target_hotel_id::text
    )
  );

  for floor_item in
    select value
    from jsonb_array_elements(
      coalesce(payload -> 'floors', '[]'::jsonb)
    )
  loop
    item_name := nullif(trim(floor_item ->> 'name'), '');
    item_code := upper(
      coalesce(
        nullif(trim(floor_item ->> 'code'), ''),
        private.normalize_hotel_slug(item_name)
      )
    );
    item_description :=
      nullif(trim(floor_item ->> 'description'), '');

    if item_name is null or item_code is null then
      raise exception 'Each floor requires a name and code.';
    end if;

    select f.id
    into existing_id
    from public.floors f
    where f.hotel_id = target_hotel_id
      and upper(trim(f.code)) = item_code
    limit 1;

    if existing_id is null then
      insert into public.floors (
        hotel_id,
        name,
        code,
        floor_number,
        description,
        sort_order,
        is_active,
        created_by,
        updated_by,
        created_at,
        updated_at
      ) values (
        target_hotel_id,
        item_name,
        item_code,
        nullif(trim(floor_item ->> 'floor_number'), '')::integer,
        item_description,
        coalesce(
          nullif(trim(floor_item ->> 'sort_order'), '')::integer,
          0
        ),
        coalesce(
          nullif(trim(floor_item ->> 'is_active'), '')::boolean,
          true
        ),
        actor_user_id,
        actor_user_id,
        now(),
        now()
      );

      floor_inserted := floor_inserted + 1;
    else
      update public.floors f
      set
        name = item_name,
        floor_number = coalesce(
          nullif(trim(floor_item ->> 'floor_number'), '')::integer,
          f.floor_number
        ),
        description = item_description,
        sort_order = coalesce(
          nullif(trim(floor_item ->> 'sort_order'), '')::integer,
          f.sort_order
        ),
        is_active = coalesce(
          nullif(trim(floor_item ->> 'is_active'), '')::boolean,
          f.is_active
        ),
        updated_by = actor_user_id,
        updated_at = now()
      where f.id = existing_id;

      floor_updated := floor_updated + 1;
    end if;
  end loop;

  for room_type_item in
    select value
    from jsonb_array_elements(
      coalesce(payload -> 'room_types', '[]'::jsonb)
    )
  loop
    item_name :=
      nullif(trim(room_type_item ->> 'name'), '');
    item_code := upper(
      coalesce(
        nullif(trim(room_type_item ->> 'code'), ''),
        private.normalize_hotel_slug(item_name)
      )
    );
    item_description :=
      nullif(trim(room_type_item ->> 'description'), '');

    if item_name is null or item_code is null then
      raise exception
        'Each room type requires a name and code.';
    end if;

    select rt.id
    into existing_id
    from public.room_types rt
    where rt.hotel_id = target_hotel_id
      and upper(trim(rt.code)) = item_code
    limit 1;

    if existing_id is null then
      insert into public.room_types (
        hotel_id,
        name,
        code,
        description,
        base_occupancy,
        max_adults,
        max_children,
        max_occupancy,
        base_rate,
        extra_adult_rate,
        extra_child_rate,
        is_active,
        sort_order,
        created_at,
        updated_at
      ) values (
        target_hotel_id,
        item_name,
        item_code,
        item_description,
        coalesce(
          nullif(trim(room_type_item ->> 'base_occupancy'), '')::integer,
          1
        ),
        coalesce(
          nullif(trim(room_type_item ->> 'max_adults'), '')::integer,
          2
        ),
        coalesce(
          nullif(trim(room_type_item ->> 'max_children'), '')::integer,
          1
        ),
        coalesce(
          nullif(trim(room_type_item ->> 'max_occupancy'), '')::integer,
          3
        ),
        coalesce(
          nullif(trim(room_type_item ->> 'base_rate'), '')::numeric,
          0
        ),
        coalesce(
          nullif(trim(room_type_item ->> 'extra_adult_rate'), '')::numeric,
          0
        ),
        coalesce(
          nullif(trim(room_type_item ->> 'extra_child_rate'), '')::numeric,
          0
        ),
        coalesce(
          nullif(trim(room_type_item ->> 'is_active'), '')::boolean,
          true
        ),
        coalesce(
          nullif(trim(room_type_item ->> 'sort_order'), '')::integer,
          0
        ),
        now(),
        now()
      );

      room_type_inserted := room_type_inserted + 1;
    else
      update public.room_types rt
      set
        name = item_name,
        description = item_description,
        base_occupancy = coalesce(
          nullif(trim(room_type_item ->> 'base_occupancy'), '')::integer,
          rt.base_occupancy
        ),
        max_adults = coalesce(
          nullif(trim(room_type_item ->> 'max_adults'), '')::integer,
          rt.max_adults
        ),
        max_children = coalesce(
          nullif(trim(room_type_item ->> 'max_children'), '')::integer,
          rt.max_children
        ),
        max_occupancy = coalesce(
          nullif(trim(room_type_item ->> 'max_occupancy'), '')::integer,
          rt.max_occupancy
        ),
        base_rate = coalesce(
          nullif(trim(room_type_item ->> 'base_rate'), '')::numeric,
          rt.base_rate
        ),
        extra_adult_rate = coalesce(
          nullif(trim(room_type_item ->> 'extra_adult_rate'), '')::numeric,
          rt.extra_adult_rate
        ),
        extra_child_rate = coalesce(
          nullif(trim(room_type_item ->> 'extra_child_rate'), '')::numeric,
          rt.extra_child_rate
        ),
        is_active = coalesce(
          nullif(trim(room_type_item ->> 'is_active'), '')::boolean,
          rt.is_active
        ),
        sort_order = coalesce(
          nullif(trim(room_type_item ->> 'sort_order'), '')::integer,
          rt.sort_order
        ),
        updated_at = now()
      where rt.id = existing_id;

      room_type_updated := room_type_updated + 1;
    end if;
  end loop;

  select h.currency_code
  into currency_value
  from public.hotels h
  where h.id = target_hotel_id;

  for rate_item in
    select value
    from jsonb_array_elements(
      coalesce(payload -> 'rate_plans', '[]'::jsonb)
    )
  loop
    item_name := nullif(trim(rate_item ->> 'name'), '');
    item_code := upper(
      coalesce(
        nullif(trim(rate_item ->> 'code'), ''),
        private.normalize_hotel_slug(item_name)
      )
    );
    room_type_code_value :=
      upper(nullif(trim(rate_item ->> 'room_type_code'), ''));
    item_description :=
      nullif(trim(rate_item ->> 'description'), '');

    if item_name is null
       or item_code is null
       or room_type_code_value is null
    then
      raise exception
        'Each rate plan requires name, code and room_type_code.';
    end if;

    select rt.id
    into resolved_room_type_id
    from public.room_types rt
    where rt.hotel_id = target_hotel_id
      and upper(trim(rt.code)) = room_type_code_value
    limit 1;

    if resolved_room_type_id is null then
      raise exception
        'Unknown room_type_code for rate plan: %.',
        room_type_code_value;
    end if;

    select rp.id
    into existing_id
    from public.rate_plans rp
    where rp.hotel_id = target_hotel_id
      and upper(trim(rp.code)) = item_code
    limit 1;

    if existing_id is null then
      insert into public.rate_plans (
        hotel_id,
        room_type_id,
        name,
        code,
        description,
        meal_plan,
        currency_code,
        base_rate,
        extra_adult_rate,
        extra_child_rate,
        minimum_stay,
        maximum_stay,
        cancellation_policy,
        is_refundable,
        is_active,
        priority,
        created_at,
        updated_at
      ) values (
        target_hotel_id,
        resolved_room_type_id,
        item_name,
        item_code,
        item_description,
        coalesce(
          nullif(trim(rate_item ->> 'meal_plan'), ''),
          'room_only'
        ),
        upper(
          coalesce(
            nullif(trim(rate_item ->> 'currency_code'), ''),
            currency_value
          )
        ),
        coalesce(
          nullif(trim(rate_item ->> 'base_rate'), '')::numeric,
          0
        ),
        coalesce(
          nullif(trim(rate_item ->> 'extra_adult_rate'), '')::numeric,
          0
        ),
        coalesce(
          nullif(trim(rate_item ->> 'extra_child_rate'), '')::numeric,
          0
        ),
        coalesce(
          nullif(trim(rate_item ->> 'minimum_stay'), '')::integer,
          1
        ),
        nullif(trim(rate_item ->> 'maximum_stay'), '')::integer,
        nullif(trim(rate_item ->> 'cancellation_policy'), ''),
        coalesce(
          nullif(trim(rate_item ->> 'is_refundable'), '')::boolean,
          true
        ),
        coalesce(
          nullif(trim(rate_item ->> 'is_active'), '')::boolean,
          true
        ),
        coalesce(
          nullif(trim(rate_item ->> 'priority'), '')::integer,
          100
        ),
        now(),
        now()
      );

      rate_inserted := rate_inserted + 1;
    else
      update public.rate_plans rp
      set
        room_type_id = resolved_room_type_id,
        name = item_name,
        description = item_description,
        meal_plan = coalesce(
          nullif(trim(rate_item ->> 'meal_plan'), ''),
          rp.meal_plan
        ),
        currency_code = upper(
          coalesce(
            nullif(trim(rate_item ->> 'currency_code'), ''),
            rp.currency_code
          )
        ),
        base_rate = coalesce(
          nullif(trim(rate_item ->> 'base_rate'), '')::numeric,
          rp.base_rate
        ),
        extra_adult_rate = coalesce(
          nullif(trim(rate_item ->> 'extra_adult_rate'), '')::numeric,
          rp.extra_adult_rate
        ),
        extra_child_rate = coalesce(
          nullif(trim(rate_item ->> 'extra_child_rate'), '')::numeric,
          rp.extra_child_rate
        ),
        minimum_stay = coalesce(
          nullif(trim(rate_item ->> 'minimum_stay'), '')::integer,
          rp.minimum_stay
        ),
        maximum_stay = case
          when rate_item ? 'maximum_stay'
            then nullif(
              trim(rate_item ->> 'maximum_stay'),
              ''
            )::integer
          else rp.maximum_stay
        end,
        cancellation_policy = case
          when rate_item ? 'cancellation_policy'
            then nullif(
              trim(rate_item ->> 'cancellation_policy'),
              ''
            )
          else rp.cancellation_policy
        end,
        is_refundable = coalesce(
          nullif(trim(rate_item ->> 'is_refundable'), '')::boolean,
          rp.is_refundable
        ),
        is_active = coalesce(
          nullif(trim(rate_item ->> 'is_active'), '')::boolean,
          rp.is_active
        ),
        priority = coalesce(
          nullif(trim(rate_item ->> 'priority'), '')::integer,
          rp.priority
        ),
        updated_at = now()
      where rp.id = existing_id;

      rate_updated := rate_updated + 1;
    end if;
  end loop;

  readiness :=
    private.compute_hotel_onboarding_readiness(
      target_hotel_id
    );

  update public.hotel_onboarding ho
  set
    readiness_state = readiness,
    last_saved_at = now(),
    updated_by = actor_user_id,
    version = ho.version + 1
  where ho.hotel_id = target_hotel_id;

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'floors', jsonb_build_object(
      'inserted', floor_inserted,
      'updated', floor_updated
    ),
    'room_types', jsonb_build_object(
      'inserted', room_type_inserted,
      'updated', room_type_updated
    ),
    'rate_plans', jsonb_build_object(
      'inserted', rate_inserted,
      'updated', rate_updated
    ),
    'readiness', readiness
  );
exception
  when invalid_text_representation
    or numeric_value_out_of_range
    or check_violation
  then
    raise exception
      'Invalid inventory value: %.',
      sqlerrm;
end;
$$;


ALTER FUNCTION "public"."configure_hotel_inventory"("target_hotel_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."configure_service_request_charge"("target_hotel_id" "uuid", "target_request_type_id" "uuid", "charge_enabled_value" boolean, "default_charge_amount_value" numeric DEFAULT NULL::numeric, "posting_policy_value" "text" DEFAULT 'manual'::"text", "charge_description_value" "text" DEFAULT NULL::"text", "taxable_value" boolean DEFAULT false, "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  updated_type public.service_request_types%rowtype;
  request_record record;
  posted_count integer := 0;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'payments.manage',
      'invoices.manage',
      'checkout.manage'
    ]::text[]
  ) then
    raise exception 'Service charge configuration access denied.';
  end if;

  if posting_policy_value not in (
    'manual',
    'on_completion'
  ) then
    raise exception 'Invalid service charge posting policy.';
  end if;

  if
    charge_enabled_value
    and (
      default_charge_amount_value is null
      or default_charge_amount_value <= 0
    )
  then
    raise exception
      'Enabled service pricing requires a positive default amount.';
  end if;

  update public.service_request_types request_type
  set
    charge_enabled = charge_enabled_value,
    default_charge_amount =
      default_charge_amount_value,
    charge_posting_policy =
      posting_policy_value,
    charge_taxable = taxable_value,
    charge_description =
      nullif(trim(charge_description_value), ''),
    updated_at = now(),
    updated_by =
      private.day11_valid_auth_actor(auth.uid())
  where request_type.hotel_id = target_hotel_id
    and request_type.id = target_request_type_id
  returning request_type.*
  into updated_type;

  if updated_type.id is null then
    raise exception 'Service request type was not found.';
  end if;

  if
    updated_type.charge_enabled
    and updated_type.charge_posting_policy =
      'on_completion'
  then
    for request_record in
      select request.id
      from public.service_requests request
      where request.hotel_id = target_hotel_id
        and request.request_type_id =
          target_request_type_id
        and request.status = 'completed'
      order by request.created_at, request.id
    loop
      if coalesce(
        (
          private.day11_post_service_request_charge(
            request_record.id,
            false,
            request_id_value
          ) ->> 'ok'
        )::boolean,
        false
      ) then
        posted_count := posted_count + 1;
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'ok', true,
    'request_id', coalesce(
      nullif(trim(request_id_value), ''),
      gen_random_uuid()::text
    ),
    'request_type', to_jsonb(updated_type),
    'completed_requests_processed',
      posted_count
  );
end;
$$;


ALTER FUNCTION "public"."configure_service_request_charge"("target_hotel_id" "uuid", "target_request_type_id" "uuid", "charge_enabled_value" boolean, "default_charge_amount_value" numeric, "posting_policy_value" "text", "charge_description_value" "text", "taxable_value" boolean, "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_calendar_room_block"("target_hotel_id" "uuid", "block_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_room_id uuid;
  target_block_type text;
  target_start_date date;
  target_end_date date;
  target_reason text;
  created_block_id uuid;
  result jsonb;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  if block_payload is null then
    raise exception 'Room-block payload is required.';
  end if;

  target_room_id :=
    nullif(block_payload->>'room_id', '')::uuid;
  target_block_type :=
    lower(coalesce(
      nullif(trim(block_payload->>'block_type'), ''),
      'operational'
    ));
  target_start_date :=
    nullif(block_payload->>'start_date', '')::date;
  target_end_date :=
    nullif(block_payload->>'end_date', '')::date;
  target_reason :=
    nullif(trim(block_payload->>'reason'), '');

  if target_room_id is null
     or target_start_date is null
     or target_end_date is null
  then
    raise exception 'Room and block dates are required.';
  end if;

  if target_end_date <= target_start_date
     or target_end_date - target_start_date > 365
  then
    raise exception
      'Room-block length must be between 1 and 365 days.';
  end if;

  if target_block_type not in (
    'operational',
    'maintenance',
    'out_of_order',
    'owner_use',
    'deep_cleaning',
    'other'
  ) then
    raise exception 'Room-block type is invalid.';
  end if;

  if target_reason is null then
    raise exception 'Room-block reason is required.';
  end if;

  perform 1
  from public.rooms room
  where room.id = target_room_id
    and room.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Room does not belong to this hotel.';
  end if;

  if not private.calendar_room_is_available(
    target_hotel_id,
    target_room_id,
    target_start_date,
    target_end_date,
    null,
    null
  ) then
    raise exception
      'Room cannot be blocked because the dates overlap active inventory.';
  end if;

  insert into public.room_blocks (
    hotel_id,
    room_id,
    block_type,
    status,
    start_date,
    end_date,
    reason,
    notes,
    created_by,
    updated_by
  )
  values (
    target_hotel_id,
    target_room_id,
    target_block_type,
    'active',
    target_start_date,
    target_end_date,
    target_reason,
    nullif(trim(block_payload->>'notes'), ''),
    auth.uid(),
    auth.uid()
  )
  returning id into created_block_id;

  result := private.build_room_block_json(
    target_hotel_id,
    created_block_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'room_block.created',
    'room_block',
    created_block_id,
    format(
      'Room %s blocked from %s to %s.',
      result->>'room_number',
      target_start_date,
      target_end_date
    ),
    null,
    result,
    jsonb_build_object(
      'block_type', target_block_type
    )
  );

  return result;
end;
$$;


ALTER FUNCTION "public"."create_calendar_room_block"("target_hotel_id" "uuid", "block_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_guest_service_request"("p_hotel_slug" "text", "p_access_token" "text", "p_request_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_context record;
  v_type public.service_request_types%rowtype;
  v_request_id uuid;
  v_lookup text := trim(coalesce(p_request_type, ''));
begin
  select * into v_context
  from private.day15_guest_context(p_hotel_slug, p_access_token, true);

  select srt.* into v_type
  from public.service_request_types srt
  where srt.hotel_id = v_context.hotel_id
    and srt.is_active
    and srt.guest_visible
    and (
      lower(trim(srt.code)) = lower(v_lookup)
      or lower(trim(srt.name)) = lower(v_lookup)
    )
  order by case when lower(trim(srt.code)) = lower(v_lookup) then 0 else 1 end
  limit 1;

  if not found then
    raise exception 'This service is not available for guest requests.';
  end if;

  if exists (
    select 1
    from public.service_requests sr
    where sr.hotel_id = v_context.hotel_id
      and sr.guest_session_id = v_context.guest_session_id
      and sr.request_type_id = v_type.id
      and sr.status not in ('completed','cancelled')
  ) then
    raise exception 'This service request is already active.';
  end if;

  if (
    select count(*)
    from public.service_requests sr
    where sr.hotel_id = v_context.hotel_id
      and sr.guest_session_id = v_context.guest_session_id
      and sr.created_at > now() - interval '1 minute'
  ) >= 5 then
    raise exception 'Too many service requests were submitted. Please wait and try again.';
  end if;

  insert into public.service_requests (
    hotel_id,
    room_id,
    guest_id,
    guest_session_id,
    request_type_id,
    request_type,
    request_details,
    department,
    status,
    priority,
    estimated_minutes,
    estimated_arrival_time,
    sla_due_at,
    escalation_due_at
  ) values (
    v_context.hotel_id,
    v_context.room_id,
    v_context.guest_id,
    v_context.guest_session_id,
    v_type.id,
    v_type.name,
    v_type.name || ' requested from Room ' || v_context.room_number,
    v_type.department,
    'pending',
    v_type.default_priority,
    v_type.default_estimated_minutes,
    case when v_type.default_estimated_minutes is not null
      then now() + make_interval(mins => v_type.default_estimated_minutes)
      else null
    end,
    now() + make_interval(mins => v_type.sla_minutes),
    now() + make_interval(mins => v_type.sla_minutes + v_type.escalation_minutes)
  ) returning id into v_request_id;

  insert into public.service_request_events (
    hotel_id,
    service_request_id,
    event_type,
    from_status,
    to_status,
    idempotency_key,
    metadata
  ) values (
    v_context.hotel_id,
    v_request_id,
    'request_submitted',
    null,
    'pending',
    'submitted',
    jsonb_build_object(
      'request_type_id', v_type.id,
      'department', v_type.department,
      'sla_minutes', v_type.sla_minutes
    )
  );

  insert into public.notifications (
    hotel_id,
    room_id,
    guest_id,
    type,
    title,
    message,
    is_read
  ) values (
    v_context.hotel_id,
    v_context.room_id,
    v_context.guest_id,
    'service_request',
    v_type.name || ' Request',
    'Room ' || v_context.room_number || ' requested ' || v_type.name
      || ' for ' || replace(v_type.department, '_', ' '),
    false
  );

  perform private.day15_notify_guest(
    v_context.hotel_id,
    v_context.guest_session_id,
    v_context.room_id,
    v_context.guest_id,
    'service_request',
    v_request_id,
    'submitted',
    'Request received',
    'Your ' || v_type.name || ' request has been sent to '
      || replace(v_type.department, '_', ' ') || '.',
    jsonb_build_object('department', v_type.department)
  );

  return jsonb_build_object(
    'result', 'SERVICE REQUEST CREATED',
    'request_id', v_request_id,
    'request_type', v_type.name,
    'department', v_type.department,
    'sla_due_at', now() + make_interval(mins => v_type.sla_minutes)
  );
end;
$$;


ALTER FUNCTION "public"."create_guest_service_request"("p_hotel_slug" "text", "p_access_token" "text", "p_request_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_housekeeping_task"("target_hotel_id" "uuid", "target_room_id" "uuid", "task_type_value" "text", "priority_value" "text", "due_at_value" timestamp with time zone, "notes_value" "text", "source_type_value" "text", "source_guest_session_id_value" "uuid", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.housekeeping_tasks%rowtype;
begin
  actor_id_value :=
    private.day13_require_housekeeping_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select task.*
  into task_row
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.request_id = request_key;

  if task_row.id is not null then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row),
      'items',
        (
          select coalesce(
            jsonb_agg(
              to_jsonb(item)
              order by item.sort_order
            ),
            '[]'::jsonb
          )
          from public.housekeeping_task_items item
          where item.hotel_id = target_hotel_id
            and item.task_id = task_row.id
        )
    );
  end if;

  insert into public.housekeeping_tasks (
    hotel_id,
    room_id,
    task_type,
    status,
    priority,
    due_at,
    notes,
    source_type,
    source_guest_session_id,
    request_id,
    updated_by,
    metadata
  )
  values (
    target_hotel_id,
    target_room_id,
    coalesce(
      nullif(trim(task_type_value), ''),
      'room_cleaning'
    ),
    'pending',
    coalesce(
      nullif(trim(priority_value), ''),
      'normal'
    ),
    due_at_value,
    nullif(trim(notes_value), ''),
    coalesce(
      nullif(trim(source_type_value), ''),
      'manual'
    ),
    source_guest_session_id_value,
    request_key,
    actor_id_value,
    jsonb_build_object(
      'created_via', 'create_housekeeping_task'
    )
  )
  returning *
  into task_row;

  perform private.day13_insert_housekeeping_event(
    target_hotel_id,
    task_row.id,
    'created',
    null,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'room_id', task_row.room_id,
      'task_type', task_row.task_type
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row),
    'items',
      (
        select jsonb_agg(
          to_jsonb(item)
          order by item.sort_order
        )
        from public.housekeeping_task_items item
        where item.hotel_id = target_hotel_id
          and item.task_id = task_row.id
      )
  );
end;
$$;


ALTER FUNCTION "public"."create_housekeeping_task"("target_hotel_id" "uuid", "target_room_id" "uuid", "task_type_value" "text", "priority_value" "text", "due_at_value" timestamp with time zone, "notes_value" "text", "source_type_value" "text", "source_guest_session_id_value" "uuid", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_reservation"("target_hotel_id" "uuid", "reservation_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := auth.uid();
  hotel_row public.hotels%rowtype;
  room_type_row public.room_types%rowtype;
  selected_room_id uuid;
  selected_room_number text;
  target_room_type_id uuid;
  target_rate_plan_id uuid;
  target_guest_id uuid;
  target_status text;
  target_booking_source text;
  target_arrival_date date;
  target_departure_date date;
  target_adults integer;
  target_children integer;
  target_deposit_required numeric(12,2);
  target_deposit_amount numeric(12,2);
  target_payment_method text;
  quote jsonb;
  target_subtotal numeric(12,2);
  target_total numeric(12,2);
  target_average_rate numeric(12,2);
  generated_number text;
  created_reservation_id uuid;
  created_reservation_room_id uuid;
  reservation_result jsonb;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  if reservation_payload is null then
    raise exception 'Reservation payload is required.';
  end if;

  select h.*
  into hotel_row
  from public.hotels h
  where h.id = target_hotel_id
    and h.status = 'active';

  if not found then
    raise exception 'Active hotel not found.';
  end if;

  target_status :=
    lower(coalesce(
      nullif(trim(reservation_payload->>'status'), ''),
      'confirmed'
    ));

  if target_status not in ('draft', 'tentative', 'confirmed') then
    raise exception
      'New reservations may be draft, tentative or confirmed.';
  end if;

  target_booking_source :=
    lower(coalesce(
      nullif(trim(reservation_payload->>'booking_source'), ''),
      'walk_in'
    ));

  if target_booking_source not in (
    'walk_in',
    'phone',
    'website',
    'ota_manual',
    'travel_agent',
    'corporate',
    'repeat_guest',
    'other'
  ) then
    raise exception 'Unsupported booking source.';
  end if;

  target_arrival_date :=
    nullif(reservation_payload->>'arrival_date', '')::date;
  target_departure_date :=
    nullif(reservation_payload->>'departure_date', '')::date;

  if target_arrival_date is null
     or target_departure_date is null
     or target_departure_date <= target_arrival_date
  then
    raise exception 'Departure date must be after arrival date.';
  end if;

  if target_departure_date - target_arrival_date > 365 then
    raise exception 'Reservations are limited to 365 nights.';
  end if;

  target_adults :=
    coalesce(
      nullif(reservation_payload->>'adults', '')::integer,
      1
    );
  target_children :=
    coalesce(
      nullif(reservation_payload->>'children', '')::integer,
      0
    );

  target_room_type_id :=
    nullif(reservation_payload->>'room_type_id', '')::uuid;
  target_rate_plan_id :=
    nullif(reservation_payload->>'rate_plan_id', '')::uuid;

  if target_room_type_id is null or target_rate_plan_id is null then
    raise exception 'Room type and rate plan are required.';
  end if;

  select rt.*
  into room_type_row
  from public.room_types rt
  where rt.id = target_room_type_id
    and rt.hotel_id = target_hotel_id
    and rt.is_active;

  if not found then
    raise exception 'Active room type not found.';
  end if;

  if not exists (
    select 1
    from public.rate_plans rp
    where rp.id = target_rate_plan_id
      and rp.hotel_id = target_hotel_id
      and rp.room_type_id = target_room_type_id
      and rp.is_active
  ) then
    raise exception 'Rate plan does not belong to the selected room type.';
  end if;

  quote := public.get_reservation_rate_quote(
    target_hotel_id,
    target_rate_plan_id,
    target_arrival_date,
    target_departure_date,
    target_adults,
    target_children
  );

  target_subtotal := (quote->>'room_subtotal')::numeric(12,2);
  target_total := (quote->>'total_amount')::numeric(12,2);
  target_average_rate :=
    (quote->>'average_nightly_rate')::numeric(12,2);

  if nullif(trim(reservation_payload->>'room_id'), '') is not null then
    selected_room_id :=
      (reservation_payload->>'room_id')::uuid;

    select available.room_number
    into selected_room_number
    from public.get_reservation_available_rooms(
      target_hotel_id,
      target_arrival_date,
      target_departure_date,
      target_room_type_id,
      null
    ) available
    where available.room_id = selected_room_id;

    if not found then
      raise exception
        'Selected room is not available for these dates.';
    end if;
  elsif target_status in ('tentative', 'confirmed') then
    select
      available.room_id,
      available.room_number
    into
      selected_room_id,
      selected_room_number
    from public.get_reservation_available_rooms(
      target_hotel_id,
      target_arrival_date,
      target_departure_date,
      target_room_type_id,
      null
    ) available
    order by available.room_number
    limit 1;

    if selected_room_id is null then
      raise exception
        'No room is available for the selected room type and dates.';
    end if;
  end if;

  target_guest_id := private.resolve_reservation_guest(
    target_hotel_id,
    reservation_payload->'guest'
  );

  target_deposit_amount :=
    coalesce(
      nullif(reservation_payload->>'deposit_amount', '')::numeric,
      0
    )::numeric(12,2);

  target_deposit_required :=
    greatest(
      coalesce(
        nullif(
          reservation_payload->>'deposit_required',
          ''
        )::numeric,
        0
      ),
      target_deposit_amount
    )::numeric(12,2);

  if target_deposit_amount < 0
     or target_deposit_required < 0
     or target_deposit_required > target_total
     or target_deposit_amount > target_total
  then
    raise exception
      'Deposit values must be between zero and the reservation total.';
  end if;

  target_payment_method :=
    lower(coalesce(
      nullif(trim(reservation_payload->>'payment_method'), ''),
      'cash'
    ));

  generated_number := private.next_reservation_number(
    target_hotel_id,
    target_arrival_date
  );

  insert into public.reservations (
    hotel_id,
    reservation_number,
    primary_guest_id,
    status,
    booking_source,
    source_reference,
    arrival_date,
    departure_date,
    expected_checkin_time,
    expected_checkout_time,
    adults,
    children,
    currency_code,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount,
    deposit_required,
    deposit_collected,
    special_requests,
    internal_notes,
    created_by,
    updated_by
  )
  values (
    target_hotel_id,
    generated_number,
    target_guest_id,
    target_status,
    target_booking_source,
    nullif(trim(reservation_payload->>'source_reference'), ''),
    target_arrival_date,
    target_departure_date,
    nullif(
      reservation_payload->>'expected_checkin_time',
      ''
    )::time,
    nullif(
      reservation_payload->>'expected_checkout_time',
      ''
    )::time,
    target_adults,
    target_children,
    hotel_row.currency_code,
    target_subtotal,
    0,
    0,
    target_total,
    target_deposit_required,
    0,
    nullif(trim(reservation_payload->>'special_requests'), ''),
    nullif(trim(reservation_payload->>'internal_notes'), ''),
    actor_user_id,
    actor_user_id
  )
  returning id into created_reservation_id;

  insert into public.reservation_rooms (
    hotel_id,
    reservation_id,
    room_type_id,
    room_id,
    rate_plan_id,
    status,
    adults,
    children,
    nightly_rate,
    room_subtotal,
    tax_amount,
    discount_amount,
    total_amount,
    notes
  )
  values (
    target_hotel_id,
    created_reservation_id,
    target_room_type_id,
    selected_room_id,
    target_rate_plan_id,
    case
      when target_status = 'confirmed' then 'confirmed'
      else 'held'
    end,
    target_adults,
    target_children,
    target_average_rate,
    target_subtotal,
    0,
    0,
    target_total,
    nullif(trim(reservation_payload->>'room_notes'), '')
  )
  returning id into created_reservation_room_id;

  insert into public.reservation_guests (
    hotel_id,
    reservation_id,
    guest_id,
    is_primary
  )
  values (
    target_hotel_id,
    created_reservation_id,
    target_guest_id,
    true
  );

  if target_deposit_amount > 0 then
    insert into public.reservation_payments (
      hotel_id,
      reservation_id,
      amount,
      payment_method,
      payment_status,
      transaction_reference,
      notes,
      collected_by
    )
    values (
      target_hotel_id,
      created_reservation_id,
      target_deposit_amount,
      target_payment_method,
      'collected',
      nullif(
        trim(reservation_payload->>'payment_reference'),
        ''
      ),
      nullif(trim(reservation_payload->>'payment_notes'), ''),
      actor_user_id
    );
  end if;

  reservation_result := private.build_reservation_json(
    target_hotel_id,
    created_reservation_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'reservation.created',
    'reservation',
    created_reservation_id,
    format(
      'Reservation %s created for room %s.',
      generated_number,
      coalesce(selected_room_number, 'unassigned')
    ),
    null,
    reservation_result,
    jsonb_build_object(
      'reservation_room_id', created_reservation_room_id,
      'booking_source', target_booking_source,
      'deposit_amount', target_deposit_amount
    )
  );

  return reservation_result;
end;
$$;


ALTER FUNCTION "public"."create_reservation"("target_hotel_id" "uuid", "reservation_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_support_ticket"("target_hotel_id" "uuid", "subject" "text", "description" "text", "category" "text" DEFAULT 'general'::"text", "priority" "text" DEFAULT 'normal'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  ticket_row public.support_tickets%rowtype;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_hotel_access(target_hotel_id)
  ) then
    raise exception 'Support ticket access denied.';
  end if;

  if nullif(trim(subject), '') is null
     or nullif(trim(description), '') is null
  then
    raise exception
      'Support subject and description are required.';
  end if;

  insert into public.support_tickets (
    hotel_id,
    subject,
    description,
    category,
    priority,
    status,
    created_by,
    last_response_at,
    metadata,
    created_at,
    updated_at
  ) values (
    target_hotel_id,
    trim(subject),
    trim(description),
    coalesce(nullif(trim(category), ''), 'general'),
    coalesce(nullif(trim(priority), ''), 'normal'),
    'open',
    actor_user_id,
    now(),
    '{}'::jsonb,
    now(),
    now()
  )
  returning * into ticket_row;

  insert into public.support_ticket_events (
    ticket_id,
    hotel_id,
    event_type,
    actor_user_id,
    message,
    new_status,
    details,
    created_at
  ) values (
    ticket_row.id,
    target_hotel_id,
    'ticket_created',
    actor_user_id,
    trim(description),
    ticket_row.status,
    jsonb_build_object(
      'subject', ticket_row.subject,
      'category', ticket_row.category,
      'priority', ticket_row.priority
    ),
    now()
  );

  return jsonb_build_object(
    'ticket', to_jsonb(ticket_row)
  );
end;
$$;


ALTER FUNCTION "public"."create_support_ticket"("target_hotel_id" "uuid", "subject" "text", "description" "text", "category" "text", "priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_safe_support_access"("target_session_id" "uuid", "reason" "text" DEFAULT 'Support work completed.'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  session_row public.support_access_sessions%rowtype;
  resolved_reason text := coalesce(
    nullif(trim($2), ''),
    'Support work completed.'
  );
begin
  select sas.*
  into session_row
  from public.support_access_sessions sas
  where sas.id = target_session_id
  for update;

  if not found then
    raise exception
      'Support-access session was not found.';
  end if;

  if session_row.status <> 'active' then
    return jsonb_build_object(
      'session_id', session_row.id,
      'status', session_row.status,
      'idempotent', true
    );
  end if;

  update public.support_access_sessions sas
  set
    status = 'ended',
    ended_at = now(),
    ended_by = actor_user_id,
    metadata = sas.metadata
      || jsonb_build_object(
        'end_reason',
        resolved_reason
      ),
    updated_at = now()
  where sas.id = target_session_id
  returning * into session_row;

  insert into public.support_access_events (
    session_id,
    hotel_id,
    event_type,
    actor_user_id,
    message,
    details,
    created_at
  ) values (
    session_row.id,
    session_row.hotel_id,
    'support_access_ended',
    actor_user_id,
    resolved_reason,
    jsonb_build_object(
      'ended_at', session_row.ended_at
    ),
    now()
  );

  return jsonb_build_object(
    'session', to_jsonb(session_row),
    'idempotent', false
  );
end;
$_$;


ALTER FUNCTION "public"."end_safe_support_access"("target_session_id" "uuid", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."end_safe_support_access"("target_session_id" "uuid", "reason" "text") IS 'Ends an active Platform Admin support-access session and appends immutable end history. Migration 023 resolves the reason parameter/column ambiguity.';



CREATE OR REPLACE FUNCTION "public"."enqueue_notification_event"("p_hotel_id" "uuid", "p_event_key" "text", "p_source_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required.';
  end if;

  if not private.user_has_hotel_access(p_hotel_id) then
    raise exception 'Notification event access denied.';
  end if;

  return private.day17_enqueue_notification_event_internal(
    p_hotel_id,
    p_event_key,
    p_source_id,
    coalesce(p_payload, '{}'::jsonb),
    (select auth.uid())
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_notification_event"("p_hotel_id" "uuid", "p_event_key" "text", "p_source_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_guest_folio"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_folio public.folios%rowtype;
  stay_row public.guest_sessions%rowtype;
  hotel_row public.hotels%rowtype;
  generated_id uuid := gen_random_uuid();
  request_id_value text;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'payments.manage',
      'invoices.manage',
      'checkout.manage'
    ]::text[]
  ) then
    raise exception 'Folio management access denied.';
  end if;

  request_id_value :=
    coalesce(
      nullif(trim(request_id), ''),
      generated_id::text
    );

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:folio:'
      || target_hotel_id::text
      || ':'
      || target_guest_session_id::text,
      0
    )
  );

  select folio.*
  into existing_folio
  from public.folios folio
  where folio.hotel_id = target_hotel_id
    and folio.guest_session_id = target_guest_session_id
  limit 1;

  if existing_folio.id is not null then
    return to_jsonb(existing_folio)
      || jsonb_build_object(
        'ok', true,
        'idempotent', true,
        'request_id', request_id_value
      );
  end if;

  select stay.*
  into stay_row
  from public.guest_sessions stay
  where stay.hotel_id = target_hotel_id
    and stay.id = target_guest_session_id
  for share;

  if not found then
    raise exception 'Guest session was not found.';
  end if;

  if stay_row.guest_id is null then
    raise exception 'Guest session has no guest.';
  end if;

  select hotel.*
  into hotel_row
  from public.hotels hotel
  where hotel.id = target_hotel_id;

  insert into public.folios (
    id,
    hotel_id,
    folio_number,
    guest_session_id,
    reservation_id,
    reservation_room_id,
    guest_id,
    room_id,
    status,
    currency_code,
    opened_by,
    metadata
  )
  values (
    generated_id,
    target_hotel_id,
    'FOL-'
      || to_char(
        now() at time zone hotel_row.timezone,
        'YYYYMMDD'
      )
      || '-'
      || upper(substr(replace(generated_id::text, '-', ''), 1, 8)),
    target_guest_session_id,
    stay_row.reservation_id,
    stay_row.reservation_room_id,
    stay_row.guest_id,
    stay_row.room_id,
    'open',
    coalesce(hotel_row.currency_code, 'INR'),
    auth.uid(),
    jsonb_build_object(
      'source', 'ensure_guest_folio',
      'request_id', request_id_value,
      'day', 11
    )
  )
  returning *
  into existing_folio;

  perform private.write_folio_event(
    target_hotel_id,
    existing_folio.id,
    'folio.opened',
    'guest_session',
    target_guest_session_id,
    to_jsonb(existing_folio),
    jsonb_build_object(
      'request_id', request_id_value
    )
  );

  return to_jsonb(existing_folio)
    || jsonb_build_object(
      'ok', true,
      'idempotent', false,
      'request_id', request_id_value
    );
end;
$$;


ALTER FUNCTION "public"."ensure_guest_folio"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "request_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_guest_folio"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "request_id" "text") IS 'Creates or safely reuses the one authoritative folio for a guest session. Does not backfill legacy charge sources.';



CREATE OR REPLACE FUNCTION "public"."escalate_overdue_service_requests"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request record;
  v_level integer;
  v_count integer := 0;
begin
  if not private.user_has_permission(p_hotel_id, 'services.manage') then
    raise exception 'Service escalation access denied.';
  end if;

  for v_request in
    select sr.*
    from public.service_requests sr
    where sr.hotel_id = p_hotel_id
      and sr.status in ('pending','accepted','in_progress','escalated')
      and coalesce(sr.escalation_due_at, sr.sla_due_at) <= now()
    order by coalesce(sr.escalation_due_at, sr.sla_due_at), sr.id
    for update skip locked
  loop
    v_level := least(coalesce(v_request.escalation_level, 0) + 1, 10);

    insert into public.service_escalations (
      hotel_id,
      service_request_id,
      escalation_level,
      reason,
      metadata
    ) values (
      p_hotel_id,
      v_request.id,
      v_level,
      'SLA deadline exceeded',
      jsonb_build_object(
        'previous_status', v_request.status,
        'sla_due_at', v_request.sla_due_at,
        'department', v_request.department
      )
    )
    on conflict (hotel_id, service_request_id, escalation_level) do nothing;

    if found then
      update public.service_requests
      set
        status = 'escalated',
        escalated_at = coalesce(escalated_at, now()),
        escalation_level = v_level,
        escalation_due_at = now() + interval '15 minutes'
      where hotel_id = p_hotel_id
        and id = v_request.id;

      insert into public.service_request_events (
        hotel_id,
        service_request_id,
        event_type,
        from_status,
        to_status,
        actor_user_id,
        actor_staff_id,
        idempotency_key,
        metadata
      ) values (
        p_hotel_id,
        v_request.id,
        'sla_escalated',
        v_request.status,
        'escalated',
        auth.uid(),
        private.day15_actor_staff_id(p_hotel_id),
        'sla-escalated:' || v_level::text,
        jsonb_build_object('escalation_level', v_level)
      )
      on conflict (hotel_id, service_request_id, idempotency_key) do nothing;

      perform private.day15_notify_guest(
        p_hotel_id,
        v_request.guest_session_id,
        v_request.room_id,
        v_request.guest_id,
        'service_request',
        v_request.id,
        'escalated-' || v_level::text,
        'Request escalated',
        'Your request has been escalated to the responsible team.',
        jsonb_build_object('escalation_level', v_level)
      );

      v_count := v_count + 1;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'escalated_count', v_count);
end;
$$;


ALTER FUNCTION "public"."escalate_overdue_service_requests"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extend_active_walkin_guest_stay"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_event
    public.guest_session_extension_events%rowtype;
  session_row public.guest_sessions%rowtype;
  room_row public.rooms%rowtype;
  allocation_row public.room_inventory_allocations%rowtype;
  refreshed_allocation
    public.room_inventory_allocations%rowtype;
  payment_row public.payments%rowtype;
  history_row public.stay_room_history%rowtype;
  actor_id uuid := auth.uid();
  hotel_timezone text;
  request_id_value text;
  extension_reason_value text;
  expected_checkout_at_value timestamptz;
  new_checkout_at_value timestamptz;
  current_checkout_at_value timestamptz;
  current_room_charge numeric(12,2);
  additional_room_charge_value numeric(12,2);
  final_room_charge numeric(12,2);
  confirm_room_charge boolean;
  old_end_date date;
  new_end_date date;
  session_before jsonb;
  allocation_before jsonb;
  payment_before jsonb;
  result_value jsonb;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'guests.manage',
      'checkin.manage'
    ]::text[]
  ) then
    raise exception
      'Active-stay extension access denied.';
  end if;

  if target_guest_session_id is null then
    raise exception
      'Guest session is required.';
  end if;

  if payload is null
     or jsonb_typeof(payload) <> 'object'
  then
    raise exception
      'Stay-extension payload must be a JSON object.';
  end if;

  request_id_value :=
    nullif(trim(payload ->> 'request_id'), '');

  if request_id_value is null
     or length(request_id_value) < 8
  then
    raise exception
      'A stable request_id of at least 8 characters is required.';
  end if;

  extension_reason_value :=
    nullif(trim(payload ->> 'extension_reason'), '');

  if extension_reason_value is null
     or length(extension_reason_value) < 3
  then
    raise exception
      'An extension reason of at least 3 characters is required.';
  end if;

  begin
    expected_checkout_at_value :=
      nullif(
        trim(payload ->> 'expected_checkout_at'),
        ''
      )::timestamptz;
  exception
    when others then
      raise exception
        'expected_checkout_at must be a valid timestamp.';
  end;

  if expected_checkout_at_value is null then
    raise exception
      'expected_checkout_at is required for stale-screen protection.';
  end if;

  begin
    new_checkout_at_value :=
      nullif(
        trim(payload ->> 'new_checkout_at'),
        ''
      )::timestamptz;
  exception
    when others then
      raise exception
        'new_checkout_at must be a valid timestamp.';
  end;

  if new_checkout_at_value is null then
    raise exception
      'new_checkout_at is required.';
  end if;

  begin
    additional_room_charge_value :=
      nullif(
        trim(payload ->> 'additional_room_charge'),
        ''
      )::numeric;
  exception
    when others then
      raise exception
        'additional_room_charge must be a valid amount.';
  end;

  if additional_room_charge_value is null
     or additional_room_charge_value < 0
  then
    raise exception
      'A non-negative additional room charge is required.';
  end if;

  begin
    confirm_room_charge :=
      coalesce(
        nullif(
          trim(payload ->> 'confirm_room_charge'),
          ''
        )::boolean,
        false
      );
  exception
    when others then
      raise exception
        'confirm_room_charge must be true or false.';
  end;

  if not confirm_room_charge then
    raise exception
      'The additional room charge must be explicitly confirmed.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:active-stay-extension:'
      || target_hotel_id::text
      || ':'
      || request_id_value,
      0
    )
  );

  select event_record.*
  into existing_event
  from public.guest_session_extension_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.idempotency_key = request_id_value
  limit 1;

  if existing_event.id is not null then
    if existing_event.guest_session_id
         is distinct from target_guest_session_id
       or existing_event.new_checkout_at
         is distinct from new_checkout_at_value
    then
      raise exception
        'This request_id was already used for a different stay extension.';
    end if;

    return coalesce(
      existing_event.result_snapshot,
      '{}'::jsonb
    ) || jsonb_build_object('idempotent', true);
  end if;

  select stay.*
  into session_row
  from public.guest_sessions stay
  where stay.hotel_id = target_hotel_id
    and stay.id = target_guest_session_id
  for update;

  if not found then
    raise exception
      'Active guest session was not found.';
  end if;

  if session_row.status <> 'active' then
    raise exception
      'Only an active guest session may be extended.';
  end if;

  if session_row.reservation_id is not null
     or session_row.reservation_room_id is not null
  then
    raise exception
      'This workflow currently accepts direct walk-in stays only. Use the reservation modification workflow for reservation-linked stays.';
  end if;

  if session_row.room_id is null then
    raise exception
      'The active stay has no physical room assigned.';
  end if;

  current_checkout_at_value :=
    coalesce(
      session_row.extended_until,
      session_row.checkout_time
    );

  if current_checkout_at_value
       is distinct from expected_checkout_at_value
  then
    raise exception
      'The checkout time changed after the screen loaded. Refresh and try again.';
  end if;

  if new_checkout_at_value <= current_checkout_at_value then
    raise exception
      'The new checkout must be later than the current checkout.';
  end if;

  if new_checkout_at_value
       > current_checkout_at_value + interval '365 days'
  then
    raise exception
      'A single stay extension cannot exceed 365 days.';
  end if;

  if new_checkout_at_value <= now() then
    raise exception
      'The new checkout must be in the future.';
  end if;

  select hotel.timezone
  into hotel_timezone
  from public.hotels hotel
  where hotel.id = target_hotel_id;

  if hotel_timezone is null then
    raise exception
      'Hotel timezone is missing.';
  end if;

  old_end_date :=
    (
      current_checkout_at_value
      at time zone hotel_timezone
    )::date;

  new_end_date :=
    (
      new_checkout_at_value
      at time zone hotel_timezone
    )::date;

  select room_record.*
  into room_row
  from public.rooms room_record
  where room_record.hotel_id = target_hotel_id
    and room_record.id = session_row.room_id
  for update;

  if not found then
    raise exception
      'The stay room was not found.';
  end if;

  if room_row.status <> 'occupied' then
    raise exception
      'The stay room is not marked occupied. Refresh and review the stay.';
  end if;

  select allocation.*
  into allocation_row
  from public.room_inventory_allocations allocation
  where allocation.hotel_id = target_hotel_id
    and allocation.guest_session_id =
        target_guest_session_id
    and allocation.status = 'active'
  for update;

  if not found then
    raise exception
      'The active stay allocation is missing.';
  end if;

  if allocation_row.room_id
       is distinct from session_row.room_id
  then
    raise exception
      'The active allocation does not match the stay room.';
  end if;

  if allocation_row.ends_on
       is distinct from old_end_date
  then
    raise exception
      'The stay allocation changed after the screen loaded. Refresh and try again.';
  end if;

  if exists (
    select 1
    from public.room_inventory_allocations other_allocation
    where other_allocation.hotel_id = target_hotel_id
      and other_allocation.room_id = session_row.room_id
      and other_allocation.status = 'active'
      and other_allocation.id <> allocation_row.id
      and other_allocation.stay_dates
            && daterange(
              allocation_row.starts_on,
              new_end_date,
              '[)'
            )
  ) then
    raise exception
      'The room is unavailable for the requested extension period.';
  end if;

  select payment_record.*
  into payment_row
  from public.payments payment_record
  where payment_record.hotel_id = target_hotel_id
    and payment_record.guest_session_id =
        target_guest_session_id
    and payment_record.payment_type = 'room_charge'
  for update;

  if not found then
    raise exception
      'The stay room-charge record is missing.';
  end if;

  select history.*
  into history_row
  from public.stay_room_history history
  where history.hotel_id = target_hotel_id
    and history.guest_session_id =
        target_guest_session_id
    and history.segment_end is null
  for update;

  if not found then
    raise exception
      'The open room-history segment is missing.';
  end if;

  if history_row.room_id
       is distinct from session_row.room_id
  then
    raise exception
      'The open room-history segment does not match the stay room.';
  end if;

  current_room_charge :=
    coalesce(payment_row.amount, 0);

  final_room_charge :=
    current_room_charge +
    additional_room_charge_value;

  session_before := to_jsonb(session_row);
  allocation_before := to_jsonb(allocation_row);
  payment_before := to_jsonb(payment_row);

  update public.guest_sessions
  set extended_until = new_checkout_at_value
  where hotel_id = target_hotel_id
    and id = target_guest_session_id
    and status = 'active'
    and coalesce(extended_until, checkout_time)
          = expected_checkout_at_value;

  if not found then
    raise exception
      'The active stay changed while the extension was processing.';
  end if;

  select allocation.*
  into refreshed_allocation
  from public.room_inventory_allocations allocation
  where allocation.hotel_id = target_hotel_id
    and allocation.guest_session_id =
        target_guest_session_id
    and allocation.status = 'active'
  for update;

  if refreshed_allocation.id is null
     or refreshed_allocation.room_id
          is distinct from session_row.room_id
     or refreshed_allocation.ends_on
          is distinct from new_end_date
  then
    raise exception
      'The stay allocation did not extend to the requested date.';
  end if;

  update public.payments
  set amount = final_room_charge
  where hotel_id = target_hotel_id
    and id = payment_row.id
    and guest_session_id =
        target_guest_session_id
    and payment_type = 'room_charge'
    and amount = current_room_charge;

  if not found then
    raise exception
      'The room-charge record changed while the extension was processing.';
  end if;

  update public.stay_room_history
  set
    rate_amount = final_room_charge,
    metadata =
      coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'last_stay_extension',
        jsonb_build_object(
          'request_id', request_id_value,
          'previous_checkout_at',
            current_checkout_at_value,
          'new_checkout_at',
            new_checkout_at_value,
          'additional_room_charge',
            additional_room_charge_value,
          'extended_by', actor_id,
          'extended_at', now()
        )
      )
  where hotel_id = target_hotel_id
    and id = history_row.id
    and segment_end is null;

  if not found then
    raise exception
      'The active room-history segment changed while the extension was processing.';
  end if;

  result_value := jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'hotel_id', target_hotel_id,
    'guest_session_id', target_guest_session_id,
    'guest_id', session_row.guest_id,
    'room_id', session_row.room_id,
    'room_number', room_row.room_number,
    'request_id', request_id_value,
    'extension_reason', extension_reason_value,
    'previous_checkout_at',
      current_checkout_at_value,
    'new_checkout_at',
      new_checkout_at_value,
    'hotel_timezone', hotel_timezone,
    'allocation', jsonb_build_object(
      'id', refreshed_allocation.id,
      'room_id', refreshed_allocation.room_id,
      'starts_on', refreshed_allocation.starts_on,
      'previous_ends_on', allocation_row.ends_on,
      'ends_on', refreshed_allocation.ends_on,
      'stay_dates', refreshed_allocation.stay_dates,
      'status', refreshed_allocation.status
    ),
    'room_charge', jsonb_build_object(
      'payment_id', payment_row.id,
      'previous_amount', current_room_charge,
      'additional_amount',
        additional_room_charge_value,
      'current_amount', final_room_charge,
      'payment_status', payment_row.payment_status
    ),
    'room_history', jsonb_build_object(
      'segment_id', history_row.id,
      'segment_number', history_row.segment_number,
      'room_id', history_row.room_id,
      'rate_amount', final_room_charge
    )
  );

  insert into public.guest_session_extension_events (
    hotel_id,
    guest_session_id,
    room_id,
    idempotency_key,
    previous_checkout_at,
    new_checkout_at,
    previous_room_charge,
    additional_room_charge,
    current_room_charge,
    extension_reason,
    result_snapshot,
    created_by
  )
  values (
    target_hotel_id,
    target_guest_session_id,
    session_row.room_id,
    request_id_value,
    current_checkout_at_value,
    new_checkout_at_value,
    current_room_charge,
    additional_room_charge_value,
    final_room_charge,
    extension_reason_value,
    result_value,
    actor_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'front_office.active_stay_extended',
    'guest_session',
    target_guest_session_id,
    format(
      'Active stay in Room %s extended from %s to %s.',
      room_row.room_number,
      current_checkout_at_value,
      new_checkout_at_value
    ),
    jsonb_build_object(
      'guest_session', session_before,
      'allocation', allocation_before,
      'room_charge', payment_before,
      'open_history_segment_id', history_row.id
    ),
    result_value,
    jsonb_build_object(
      'request_id', request_id_value,
      'extension_reason',
        extension_reason_value,
      'previous_checkout_at',
        current_checkout_at_value,
      'new_checkout_at',
        new_checkout_at_value,
      'additional_room_charge',
        additional_room_charge_value,
      'payment_id', payment_row.id,
      'allocation_id', allocation_row.id
    )
  );

  return result_value;
end;
$$;


ALTER FUNCTION "public"."extend_active_walkin_guest_stay"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."extend_active_walkin_guest_stay"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "payload" "jsonb") IS 'Day 10 authoritative atomic direct-walk-in stay extension. Validates hotel-local checkout, stale screens, room availability, one active allocation, explicitly confirmed charge impact, open room history, immutable activity evidence and request idempotency in one transaction.';



CREATE OR REPLACE FUNCTION "public"."extend_hotel_trial"("target_hotel_id" "uuid", "extension_days" integer, "reason" "text", "action_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  existing_result jsonb;
  subscription_row public.hotel_subscriptions%rowtype;
  old_status_value text;
  old_plan_id_value uuid;
  new_end_at timestamptz;
  result jsonb;
begin
  if target_hotel_id is null
     or extension_days is null
     or extension_days < 1
     or extension_days > 60
  then
    raise exception
      'Hotel and an extension between 1 and 60 days are required.';
  end if;

  if nullif(trim(reason), '') is null then
    raise exception 'Trial extension reason is required.';
  end if;

  existing_result :=
    private.subscription_action_result_20260728(
      action_idempotency_key
    );

  if existing_result is not null then
    return existing_result
      || jsonb_build_object('idempotent', true);
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:extend-trial:' || target_hotel_id::text
    )
  );

  select hs.*
  into subscription_row
  from public.hotel_subscriptions hs
  where hs.hotel_id = target_hotel_id
    and hs.status in ('trial', 'trialing')
  order by hs.created_at desc, hs.id desc
  limit 1
  for update;

  if not found then
    if exists (
      select 1
      from public.hotel_subscriptions current_row
      where current_row.hotel_id = target_hotel_id
        and current_row.status in (
          'active',
          'past_due',
          'suspended'
        )
    ) then
      raise exception
        'A paid/current subscription already exists.';
    end if;

    select hs.*
    into subscription_row
    from public.hotel_subscriptions hs
    where hs.hotel_id = target_hotel_id
      and hs.status = 'expired'
      and hs.trial_started_at is not null
    order by hs.created_at desc, hs.id desc
    limit 1
    for update;

    if not found then
      raise exception
        'No extendable trial subscription was found.';
    end if;
  end if;

  old_status_value := subscription_row.status;
  old_plan_id_value := subscription_row.plan_id;

  new_end_at :=
    greatest(
      coalesce(
        subscription_row.trial_ends_at,
        subscription_row.end_date,
        now()
      ),
      now()
    )
    + make_interval(days => extension_days);

  if subscription_row.trial_started_at is not null
     and new_end_at
       > subscription_row.trial_started_at
         + interval '90 days'
  then
    raise exception
      'Total trial duration cannot exceed 90 days.';
  end if;

  perform set_config(
    'stayqr.subscription_event_source',
    'extend_hotel_trial',
    true
  );

  update public.hotel_subscriptions hs
  set
    status = 'trialing',
    billing_mode = 'trial',
    provider_status = 'trialing',
    trial_ends_at = new_end_at,
    end_date = new_end_at,
    current_period_end = new_end_at,
    cancelled_at = null,
    cancellation_reason = null,
    metadata = coalesce(hs.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'last_trial_extension',
        jsonb_build_object(
          'days', extension_days,
          'reason', trim(reason),
          'extended_by', actor_user_id,
          'extended_at', now()
        )
      ),
    updated_at = now()
  where hs.id = subscription_row.id
  returning * into subscription_row;

  update public.hotels h
  set
    status = 'active',
    subscription_status = 'trialing',
    updated_at = now()
  where h.id = target_hotel_id;

  result := jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', subscription_row.id,
    'status', subscription_row.status,
    'trial_ends_at', subscription_row.trial_ends_at,
    'extension_days', extension_days,
    'idempotent', false
  );

  return private.record_subscription_action_20260728(
    target_hotel_id,
    subscription_row.id,
    'trial_extended',
    'extend_hotel_trial',
    actor_user_id,
    old_status_value,
    subscription_row.status,
    old_plan_id_value,
    subscription_row.plan_id,
    subscription_row.provider,
    null,
    action_idempotency_key,
    jsonb_build_object('reason', trim(reason)),
    result
  );
end;
$$;


ALTER FUNCTION "public"."extend_hotel_trial"("target_hotel_id" "uuid", "extension_days" integer, "reason" "text", "action_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_accounting_csv"("h" "uuid", "d1" "date", "d2" "date", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  request_key text;
  e public.accounting_exports%rowtype;
  existed boolean;
begin
  if not private.user_has_any_permission(h,array['invoices.manage','payments.manage','checkout.manage']::text[]) then
    raise exception 'Accounting export access denied.';
  end if;
  actor:=private.day11_require_current_actor();
  request_key:=nullif(trim(request_id_value),'');
  if request_key is null or length(request_key)<8 then raise exception 'Request ID of at least eight characters required.'; end if;
  existed:=exists(select 1 from public.accounting_exports where hotel_id=h and idempotency_key=request_key);
  e:=private.day12_create_accounting_export(h,null,d1,d2,request_key,actor);
  return jsonb_build_object('ok',true,'idempotent',existed,'export',to_jsonb(e));
end;
$$;


ALTER FUNCTION "public"."generate_accounting_csv"("h" "uuid", "d1" "date", "d2" "date", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_announcements"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_hotel_access(p_hotel_id) then
    raise exception 'Announcement access denied.';
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'id', a.id,
          'scope', a.scope,
          'target_hotel_id', a.target_hotel_id,
          'title', a.title,
          'body', a.body,
          'severity', a.severity,
          'starts_at', a.starts_at,
          'ends_at', a.ends_at,
          'published_at', a.published_at
        )
        order by
          case a.severity
            when 'critical' then 0
            when 'warning' then 1
            else 2
          end,
          a.published_at desc nulls last,
          a.created_at desc
      )
      from public.announcements a
      where a.status = 'published'
        and (
          a.scope = 'global'
          or (
            a.scope = 'hotel'
            and a.target_hotel_id = p_hotel_id
          )
        )
        and (a.starts_at is null or a.starts_at <= now())
        and (a.ends_at is null or a.ends_at > now())
    ),
    '[]'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."get_active_announcements"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_activity_logs_page"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor" "text" DEFAULT NULL::"text", "p_entity_type" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := private.day18_page_limit(p_limit);
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
begin
  perform private.day18_assert_page_access(p_hotel_id);

  select cursor_at, cursor_id
  into v_cursor_at, v_cursor_id
  from private.day18_decode_cursor(p_cursor);

  with candidates as (
    select
      al.*,
      row_number() over (
        order by al.created_at desc, al.id desc
      ) as rn
    from public.activity_logs al
    where al.hotel_id = p_hotel_id
      and (
        p_entity_type is null
        or al.entity_type = p_entity_type
      )
      and (p_action is null or al.action = p_action)
      and (
        v_cursor_at is null
        or v_cursor_id is null
        or (al.created_at, al.id) < (v_cursor_at, v_cursor_id)
      )
    order by al.created_at desc, al.id desc
    limit v_limit + 1
  ),
  visible as (
    select *
    from candidates
    where rn <= v_limit
  )
  select jsonb_build_object(
    'items',
      coalesce(
        (
          select jsonb_agg(
            (to_jsonb(v) - 'rn')
            order by v.created_at desc, v.id desc
          )
          from visible v
        ),
        '[]'::jsonb
      ),
    'limit', v_limit,
    'has_more', (select count(*) > v_limit from candidates),
    'next_cursor',
      case
        when (select count(*) > v_limit from candidates)
        then (
          select private.day18_encode_cursor(v.created_at, v.id)
          from visible v
          order by v.created_at asc, v.id asc
          limit 1
        )
        else null
      end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_activity_logs_page"("p_hotel_id" "uuid", "p_limit" integer, "p_cursor" "text", "p_entity_type" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_activity_timeline"("p_hotel_id" "uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_filters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := greatest(
    1,
    least(
      coalesce((p_filters ->> 'limit')::integer, 100),
      500
    )
  );
  v_result jsonb;
begin
  if not private.user_has_hotel_access(p_hotel_id) then
    raise exception 'Activity timeline access denied.';
  end if;

  select coalesce(
    jsonb_agg(to_jsonb(source) order by source.created_at desc),
    '[]'::jsonb
  )
  into v_result
  from (
    select
      al.id,
      al.hotel_id,
      al.actor_user_id,
      al.actor_role,
      al.action,
      al.entity_type,
      al.entity_id,
      al.description,
      al.before_data,
      al.after_data,
      al.metadata,
      al.created_at
    from public.activity_logs al
    where al.hotel_id = p_hotel_id
      and (p_from is null or al.created_at >= p_from)
      and (p_to is null or al.created_at <= p_to)
      and (
        nullif(trim(p_filters ->> 'entity_type'), '') is null
        or al.entity_type = trim(p_filters ->> 'entity_type')
      )
      and (
        nullif(trim(p_filters ->> 'action'), '') is null
        or al.action = trim(p_filters ->> 'action')
      )
      and (
        nullif(trim(p_filters ->> 'actor_user_id'), '') is null
        or al.actor_user_id =
          nullif(trim(p_filters ->> 'actor_user_id'), '')::uuid
      )
    order by al.created_at desc
    limit v_limit
  ) source;

  return jsonb_build_object(
    'hotel_id', p_hotel_id,
    'items', v_result
  );
end;
$$;


ALTER FUNCTION "public"."get_activity_timeline"("p_hotel_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_available_rooms"("target_hotel_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date", "target_room_type_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("room_id" "uuid", "room_number" "text", "room_type_id" "uuid", "room_type_name" "text", "room_status" "text", "max_adults" integer, "max_children" integer, "max_occupancy" integer, "standard_rate" numeric, "active_rate_plan_id" "uuid", "active_rate_plan_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_hotel_access(target_hotel_id) then raise exception 'Hotel access denied.'; end if;
  if target_arrival_date is null or target_departure_date is null or target_departure_date<=target_arrival_date
    then raise exception 'Departure date must be after arrival date.'; end if;
  if target_departure_date-target_arrival_date>365 then raise exception 'Availability searches are limited to 365 nights.'; end if;
  return query
  select r.id,r.room_number,t.id,t.name,r.status,t.max_adults,t.max_children,t.max_occupancy,
    coalesce(rp.base_rate,t.base_rate)::numeric,rp.id,rp.name
  from public.rooms r
  join public.floors f on f.id=r.floor_id and f.hotel_id=r.hotel_id and f.is_active
  join public.room_types t on t.id=r.room_type_id and t.hotel_id=r.hotel_id and t.is_active
  left join lateral(
    select p.* from public.rate_plans p where p.hotel_id=r.hotel_id and p.room_type_id=r.room_type_id and p.is_active
    order by p.priority,p.created_at limit 1
  ) rp on true
  join public.hotels h on h.id=r.hotel_id
  where r.hotel_id=target_hotel_id and r.is_active
    and (target_room_type_id is null or r.room_type_id=target_room_type_id)
    and r.status not in ('maintenance','out_of_order')
    and not(r.status='cleaning' and target_arrival_date<=(now() at time zone h.timezone)::date)
    and not exists(
      select 1 from public.room_inventory_allocations a
      where a.hotel_id=r.hotel_id and a.room_id=r.id and a.status='active'
        and a.stay_dates&&daterange(target_arrival_date,target_departure_date,'[)')
    )
  order by t.sort_order,nullif(regexp_replace(r.room_number,'[^0-9]','','g'),'')::int nulls last,r.room_number;
end;
$$;


ALTER FUNCTION "public"."get_available_rooms"("target_hotel_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date", "target_room_type_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_available_rooms"("target_hotel_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date", "target_room_type_id" "uuid") IS 'Excludes archived rooms/floors/types, maintenance/out-of-order, same-day cleaning, and allocated rooms.';



CREATE OR REPLACE FUNCTION "public"."get_booking_calendar"("target_hotel_id" "uuid", "range_start" "date", "range_end" "date", "room_type_filter" "uuid" DEFAULT NULL::"uuid", "reservation_status_filter" "text"[] DEFAULT NULL::"text"[], "block_status_filter" "text"[] DEFAULT ARRAY['active'::"text"], "page_limit" integer DEFAULT 40, "page_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  safe_limit integer;
  safe_offset integer;
  total_rooms bigint;
  room_rows jsonb;
  reservation_events jsonb;
  block_events jsonb;
  direct_stay_events jsonb;
  unallocated_rows jsonb;
  normalized_reservation_statuses text[];
  normalized_block_statuses text[];
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception 'Hotel access denied.';
  end if;

  if range_start is null
     or range_end is null
     or range_end <= range_start
  then
    raise exception
      'Calendar end date must be after the start date.';
  end if;

  if range_end - range_start > 62 then
    raise exception
      'Calendar ranges are limited to 62 days.';
  end if;

  if room_type_filter is not null
     and not exists (
       select 1
       from public.room_types room_type
       where room_type.id = room_type_filter
         and room_type.hotel_id = target_hotel_id
     )
  then
    raise exception 'Room type does not belong to this hotel.';
  end if;

  if reservation_status_filter is not null
     and exists (
       select 1
       from unnest(reservation_status_filter) status_value
       where status_value not in (
         'draft',
         'tentative',
         'confirmed',
         'checked_in',
         'checked_out',
         'cancelled',
         'no_show'
       )
     )
  then
    raise exception 'Reservation status filter is invalid.';
  end if;

  if block_status_filter is not null
     and exists (
       select 1
       from unnest(block_status_filter) status_value
       where status_value not in (
         'active',
         'released',
         'cancelled'
       )
     )
  then
    raise exception 'Room-block status filter is invalid.';
  end if;

  normalized_reservation_statuses :=
    case
      when reservation_status_filter is null
        or cardinality(reservation_status_filter) = 0
      then null
      else reservation_status_filter
    end;

  normalized_block_statuses :=
    case
      when block_status_filter is null
        or cardinality(block_status_filter) = 0
      then null
      else block_status_filter
    end;

  safe_limit := least(greatest(coalesce(page_limit, 40), 1), 100);
  safe_offset := greatest(coalesce(page_offset, 0), 0);

  select count(*)
  into total_rooms
  from public.rooms room
  join public.room_types room_type
    on room_type.id = room.room_type_id
   and room_type.hotel_id = room.hotel_id
  where room.hotel_id = target_hotel_id
    and (
      room_type_filter is null
      or room.room_type_id = room_type_filter
    );

  with paged_rooms as (
    select
      room.id,
      room.hotel_id,
      room.room_number,
      room.status,
      room.room_type_id,
      room_type.name as room_type_name,
      room_type.max_adults,
      room_type.max_children,
      room_type.max_occupancy,
      room_type.sort_order
    from public.rooms room
    join public.room_types room_type
      on room_type.id = room.room_type_id
     and room_type.hotel_id = room.hotel_id
    where room.hotel_id = target_hotel_id
      and (
        room_type_filter is null
        or room.room_type_id = room_type_filter
      )
    order by
      room_type.sort_order,
      nullif(
        regexp_replace(room.room_number, '[^0-9]', '', 'g'),
        ''
      )::integer nulls last,
      room.room_number
    limit safe_limit
    offset safe_offset
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', paged_rooms.id,
        'hotel_id', paged_rooms.hotel_id,
        'room_number', paged_rooms.room_number,
        'status', paged_rooms.status,
        'room_type_id', paged_rooms.room_type_id,
        'room_type_name', paged_rooms.room_type_name,
        'max_adults', paged_rooms.max_adults,
        'max_children', paged_rooms.max_children,
        'max_occupancy', paged_rooms.max_occupancy
      )
      order by
        paged_rooms.sort_order,
        nullif(
          regexp_replace(
            paged_rooms.room_number,
            '[^0-9]',
            '',
            'g'
          ),
          ''
        )::integer nulls last,
        paged_rooms.room_number
    ),
    '[]'::jsonb
  )
  into room_rows
  from paged_rooms;

  with paged_rooms as (
    select room.id
    from public.rooms room
    join public.room_types room_type
      on room_type.id = room.room_type_id
     and room_type.hotel_id = room.hotel_id
    where room.hotel_id = target_hotel_id
      and (
        room_type_filter is null
        or room.room_type_id = room_type_filter
      )
    order by
      room_type.sort_order,
      nullif(
        regexp_replace(room.room_number, '[^0-9]', '', 'g'),
        ''
      )::integer nulls last,
      room.room_number
    limit safe_limit
    offset safe_offset
  )
  select coalesce(
    jsonb_agg(event_payload order by event_start, event_label),
    '[]'::jsonb
  )
  into reservation_events
  from (
    select
      reservation.arrival_date as event_start,
      reservation.reservation_number as event_label,
      jsonb_build_object(
        'event_type', 'reservation',
        'id', reservation_room.id,
        'reservation_id', reservation.id,
        'reservation_room_id', reservation_room.id,
        'room_id', reservation_room.room_id,
        'room_number', room.room_number,
        'room_type_id', reservation_room.room_type_id,
        'room_type_name', room_type.name,
        'reservation_number', reservation.reservation_number,
        'guest_id', guest.id,
        'guest_name', guest.full_name,
        'guest_phone', guest.phone,
        'status', reservation.status,
        'room_status', reservation_room.status,
        'start_date', reservation.arrival_date,
        'end_date', reservation.departure_date,
        'adults', reservation.adults,
        'children', reservation.children,
        'booking_source', reservation.booking_source,
        'source_reference', reservation.source_reference,
        'currency_code', reservation.currency_code,
        'total_amount', reservation.total_amount,
        'deposit_required', reservation.deposit_required,
        'deposit_collected', reservation.deposit_collected,
        'special_requests', reservation.special_requests,
        'internal_notes', reservation.internal_notes,
        'updated_at', reservation.updated_at,
        'occupies_inventory', exists (
          select 1
          from public.room_inventory_allocations allocation
          where allocation.hotel_id = reservation.hotel_id
            and allocation.reservation_room_id = reservation_room.id
            and allocation.status = 'active'
        )
      ) as event_payload
    from public.reservations reservation
    join public.reservation_rooms reservation_room
      on reservation_room.hotel_id = reservation.hotel_id
     and reservation_room.reservation_id = reservation.id
    join paged_rooms
      on paged_rooms.id = reservation_room.room_id
    join public.rooms room
      on room.id = reservation_room.room_id
     and room.hotel_id = reservation_room.hotel_id
    join public.room_types room_type
      on room_type.id = reservation_room.room_type_id
     and room_type.hotel_id = reservation_room.hotel_id
    left join public.guests guest
      on guest.id = reservation.primary_guest_id
     and guest.hotel_id = reservation.hotel_id
    where reservation.hotel_id = target_hotel_id
      and reservation.arrival_date < range_end
      and reservation.departure_date > range_start
      and (
        normalized_reservation_statuses is null
        or reservation.status =
          any(normalized_reservation_statuses)
      )
  ) reservation_event_rows;

  with paged_rooms as (
    select room.id
    from public.rooms room
    join public.room_types room_type
      on room_type.id = room.room_type_id
     and room_type.hotel_id = room.hotel_id
    where room.hotel_id = target_hotel_id
      and (
        room_type_filter is null
        or room.room_type_id = room_type_filter
      )
    order by
      room_type.sort_order,
      nullif(
        regexp_replace(room.room_number, '[^0-9]', '', 'g'),
        ''
      )::integer nulls last,
      room.room_number
    limit safe_limit
    offset safe_offset
  )
  select coalesce(
    jsonb_agg(event_payload order by event_start, event_label),
    '[]'::jsonb
  )
  into block_events
  from (
    select
      block.start_date as event_start,
      block.reason as event_label,
      jsonb_build_object(
        'event_type', 'room_block',
        'id', block.id,
        'room_block_id', block.id,
        'room_id', block.room_id,
        'room_number', room.room_number,
        'room_type_id', room.room_type_id,
        'room_type_name', room_type.name,
        'block_type', block.block_type,
        'status', block.status,
        'start_date', block.start_date,
        'end_date', block.end_date,
        'reason', block.reason,
        'notes', block.notes,
        'release_reason', block.release_reason,
        'created_by', block.created_by,
        'updated_by', block.updated_by,
        'released_at', block.released_at,
        'released_by', block.released_by,
        'created_at', block.created_at,
        'updated_at', block.updated_at,
        'occupies_inventory', exists (
          select 1
          from public.room_inventory_allocations allocation
          where allocation.hotel_id = block.hotel_id
            and allocation.room_block_id = block.id
            and allocation.status = 'active'
        )
      ) as event_payload
    from public.room_blocks block
    join paged_rooms
      on paged_rooms.id = block.room_id
    join public.rooms room
      on room.id = block.room_id
     and room.hotel_id = block.hotel_id
    join public.room_types room_type
      on room_type.id = room.room_type_id
     and room_type.hotel_id = room.hotel_id
    where block.hotel_id = target_hotel_id
      and block.start_date < range_end
      and block.end_date > range_start
      and (
        normalized_block_statuses is null
        or block.status = any(normalized_block_statuses)
      )
  ) block_event_rows;

  with
  hotel_context as (
    select hotel.timezone
    from public.hotels hotel
    where hotel.id = target_hotel_id
  ),
  paged_rooms as (
    select room.id
    from public.rooms room
    join public.room_types room_type
      on room_type.id = room.room_type_id
     and room_type.hotel_id = room.hotel_id
    where room.hotel_id = target_hotel_id
      and (
        room_type_filter is null
        or room.room_type_id = room_type_filter
      )
    order by
      room_type.sort_order,
      nullif(
        regexp_replace(room.room_number, '[^0-9]', '', 'g'),
        ''
      )::integer nulls last,
      room.room_number
    limit safe_limit
    offset safe_offset
  ),
  direct_stays as (
    select
      stay.id,
      stay.room_id,
      stay.guest_id,
      stay.status,
      (stay.checkin_time at time zone hotel_context.timezone)::date
        as starts_on,
      greatest(
        (
          coalesce(stay.extended_until, stay.checkout_time)
          at time zone hotel_context.timezone
        )::date,
        (stay.checkin_time at time zone hotel_context.timezone)::date + 1
      ) as ends_on
    from public.guest_sessions stay
    cross join hotel_context
    join paged_rooms on paged_rooms.id = stay.room_id
    where stay.hotel_id = target_hotel_id
      and stay.reservation_room_id is null
  )
  select coalesce(
    jsonb_agg(event_payload order by event_start, event_label),
    '[]'::jsonb
  )
  into direct_stay_events
  from (
    select
      direct_stays.starts_on as event_start,
      coalesce(guest.full_name, room.room_number) as event_label,
      jsonb_build_object(
        'event_type', 'direct_stay',
        'id', direct_stays.id,
        'guest_session_id', direct_stays.id,
        'room_id', direct_stays.room_id,
        'room_number', room.room_number,
        'room_type_id', room.room_type_id,
        'room_type_name', room_type.name,
        'guest_id', guest.id,
        'guest_name', guest.full_name,
        'guest_phone', guest.phone,
        'status', direct_stays.status,
        'start_date', direct_stays.starts_on,
        'end_date', direct_stays.ends_on,
        'occupies_inventory', exists (
          select 1
          from public.room_inventory_allocations allocation
          where allocation.hotel_id = target_hotel_id
            and allocation.guest_session_id = direct_stays.id
            and allocation.status = 'active'
        )
      ) as event_payload
    from direct_stays
    join public.rooms room
      on room.id = direct_stays.room_id
     and room.hotel_id = target_hotel_id
    join public.room_types room_type
      on room_type.id = room.room_type_id
     and room_type.hotel_id = room.hotel_id
    left join public.guests guest
      on guest.id = direct_stays.guest_id
     and guest.hotel_id = target_hotel_id
    where direct_stays.starts_on < range_end
      and direct_stays.ends_on > range_start
  ) direct_stay_event_rows;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'reservation_id', reservation.id,
        'reservation_room_id', reservation_room.id,
        'reservation_number', reservation.reservation_number,
        'guest_id', guest.id,
        'guest_name', guest.full_name,
        'guest_phone', guest.phone,
        'status', reservation.status,
        'room_status', reservation_room.status,
        'room_type_id', reservation_room.room_type_id,
        'room_type_name', room_type.name,
        'start_date', reservation.arrival_date,
        'end_date', reservation.departure_date,
        'adults', reservation.adults,
        'children', reservation.children,
        'booking_source', reservation.booking_source,
        'source_reference', reservation.source_reference,
        'total_amount', reservation.total_amount,
        'deposit_collected', reservation.deposit_collected,
        'updated_at', reservation.updated_at
      )
      order by reservation.arrival_date, reservation.created_at
    ),
    '[]'::jsonb
  )
  into unallocated_rows
  from public.reservations reservation
  join public.reservation_rooms reservation_room
    on reservation_room.hotel_id = reservation.hotel_id
   and reservation_room.reservation_id = reservation.id
  join public.room_types room_type
    on room_type.id = reservation_room.room_type_id
   and room_type.hotel_id = reservation_room.hotel_id
  left join public.guests guest
    on guest.id = reservation.primary_guest_id
   and guest.hotel_id = reservation.hotel_id
  where reservation.hotel_id = target_hotel_id
    and reservation_room.room_id is null
    and reservation.arrival_date < range_end
    and reservation.departure_date > range_start
    and (
      room_type_filter is null
      or reservation_room.room_type_id = room_type_filter
    )
    and (
      normalized_reservation_statuses is null
      or reservation.status =
        any(normalized_reservation_statuses)
    );

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'range_start', range_start,
    'range_end', range_end,
    'day_count', range_end - range_start,
    'room_type_filter', room_type_filter,
    'reservation_status_filter',
      normalized_reservation_statuses,
    'block_status_filter', normalized_block_statuses,
    'pagination', jsonb_build_object(
      'total_rooms', total_rooms,
      'limit', safe_limit,
      'offset', safe_offset,
      'has_previous', safe_offset > 0,
      'has_next', safe_offset + safe_limit < total_rooms
    ),
    'rooms', room_rows,
    'events',
      coalesce(reservation_events, '[]'::jsonb)
      || coalesce(block_events, '[]'::jsonb)
      || coalesce(direct_stay_events, '[]'::jsonb),
    'unallocated_reservations', unallocated_rows,
    'generated_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_booking_calendar"("target_hotel_id" "uuid", "range_start" "date", "range_end" "date", "room_type_filter" "uuid", "reservation_status_filter" "text"[], "block_status_filter" "text"[], "page_limit" integer, "page_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_booking_calendar_room_status"("target_hotel_id" "uuid", "range_start" "date", "range_end" "date", "room_type_filter" "uuid" DEFAULT NULL::"uuid", "reservation_status_filter" "text"[] DEFAULT NULL::"text"[], "block_status_filter" "text"[] DEFAULT ARRAY['active'::"text"], "page_limit" integer DEFAULT 40, "page_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  raw_calendar jsonb;
  normalized_reservation_statuses text[];
  room_status_events jsonb;
  room_status_unallocated jsonb;
begin
  if reservation_status_filter is not null
     and exists (
       select 1
       from unnest(reservation_status_filter) status_value
       where status_value not in (
         'draft',
         'tentative',
         'confirmed',
         'checked_in',
         'checked_out',
         'cancelled',
         'no_show'
       )
     )
  then
    raise exception 'Reservation status filter is invalid.';
  end if;

  normalized_reservation_statuses :=
    case
      when reservation_status_filter is null
        or cardinality(reservation_status_filter) = 0
      then null
      else reservation_status_filter
    end;

  -- Day 4's read model remains authoritative for room, block, direct-stay,
  -- date-boundary and tenant-isolation rules. Reservation filtering is
  -- intentionally disabled here so mixed-status group bookings can be
  -- filtered at reservation-room level below.
  raw_calendar := public.get_booking_calendar(
    target_hotel_id => target_hotel_id,
    range_start => range_start,
    range_end => range_end,
    room_type_filter => room_type_filter,
    reservation_status_filter => null,
    block_status_filter => block_status_filter,
    page_limit => page_limit,
    page_offset => page_offset
  );

  select coalesce(
    jsonb_agg(
      case
        when event_row.item ->> 'event_type' = 'reservation'
        then event_row.item || jsonb_build_object(
          'booking_status', event_row.item ->> 'status',
          'status', coalesce(
            nullif(event_row.item ->> 'room_status', ''),
            event_row.item ->> 'status'
          ),
          'status_scope', 'reservation_room'
        )
        else event_row.item
      end
      order by event_row.ordinality
    ),
    '[]'::jsonb
  )
  into room_status_events
  from jsonb_array_elements(
    coalesce(raw_calendar -> 'events', '[]'::jsonb)
  ) with ordinality as event_row(item, ordinality)
  where event_row.item ->> 'event_type' <> 'reservation'
     or normalized_reservation_statuses is null
     or coalesce(
          nullif(event_row.item ->> 'room_status', ''),
          event_row.item ->> 'status'
        ) = any(normalized_reservation_statuses);

  select coalesce(
    jsonb_agg(
      unallocated_row.item || jsonb_build_object(
        'booking_status', unallocated_row.item ->> 'status',
        'status', coalesce(
          nullif(unallocated_row.item ->> 'room_status', ''),
          unallocated_row.item ->> 'status'
        ),
        'status_scope', 'reservation_room'
      )
      order by unallocated_row.ordinality
    ),
    '[]'::jsonb
  )
  into room_status_unallocated
  from jsonb_array_elements(
    coalesce(raw_calendar -> 'unallocated_reservations', '[]'::jsonb)
  ) with ordinality as unallocated_row(item, ordinality)
  where normalized_reservation_statuses is null
     or coalesce(
          nullif(unallocated_row.item ->> 'room_status', ''),
          unallocated_row.item ->> 'status'
        ) = any(normalized_reservation_statuses);

  return raw_calendar || jsonb_build_object(
    'events', room_status_events,
    'unallocated_reservations', room_status_unallocated,
    'reservation_status_filter', normalized_reservation_statuses,
    'reservation_status_scope', 'reservation_room'
  );
end;
$$;


ALTER FUNCTION "public"."get_booking_calendar_room_status"("target_hotel_id" "uuid", "range_start" "date", "range_end" "date", "room_type_filter" "uuid", "reservation_status_filter" "text"[], "block_status_filter" "text"[], "page_limit" integer, "page_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_booking_calendar_room_status"("target_hotel_id" "uuid", "range_start" "date", "range_end" "date", "room_type_filter" "uuid", "reservation_status_filter" "text"[], "block_status_filter" "text"[], "page_limit" integer, "page_offset" integer) IS 'Day 5 booking-calendar read model that uses reservation_rooms.status for room cards and status filters while preserving the reservation header status as booking_status.';



CREATE OR REPLACE FUNCTION "public"."get_calendar_room_block_details"("target_hotel_id" "uuid", "target_room_block_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception 'Hotel access denied.';
  end if;

  result := private.build_room_block_json(
    target_hotel_id,
    target_room_block_id
  );

  if result is null then
    raise exception 'Room block not found.';
  end if;

  return result;
end;
$$;


