CREATE OR REPLACE FUNCTION "public"."get_day18_query_health"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tables jsonb;
  v_indexes jsonb;
begin
  if p_hotel_id is null
     or not private.day17_can_manage_hotel(p_hotel_id)
  then
    raise exception 'Hotel management access required.'
      using errcode = '42501';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'table', stats.relname,
        'estimated_rows', stats.n_live_tup,
        'dead_rows', stats.n_dead_tup,
        'sequential_scans', stats.seq_scan,
        'index_scans', stats.idx_scan,
        'last_analyze', stats.last_analyze,
        'last_autoanalyze', stats.last_autoanalyze
      )
      order by stats.relname
    ),
    '[]'::jsonb
  )
  into v_tables
  from pg_catalog.pg_stat_user_tables stats
  where stats.schemaname = 'public'
    and stats.relname = any(
      array[
        'reservations',
        'guests',
        'guest_sessions',
        'service_requests',
        'food_orders',
        'activity_logs',
        'notification_deliveries',
        'folios',
        'invoices',
        'payments',
        'housekeeping_tasks',
        'maintenance_tasks'
      ]
    );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'index', index_state.indexrelname,
        'table', index_state.relname,
        'scans', index_state.idx_scan,
        'tuples_read', index_state.idx_tup_read,
        'tuples_fetched', index_state.idx_tup_fetch
      )
      order by index_state.indexrelname
    ),
    '[]'::jsonb
  )
  into v_indexes
  from pg_catalog.pg_stat_user_indexes index_state
  where index_state.schemaname = 'public'
    and index_state.indexrelname like 'idx_d18_%';

  return jsonb_build_object(
    'captured_at', now(),
    'hotel_id', p_hotel_id,
    'invalid_index_count',
      (
        select count(*)
        from pg_catalog.pg_index index_catalog
        join pg_catalog.pg_class index_relation
          on index_relation.oid = index_catalog.indexrelid
        join pg_catalog.pg_namespace index_namespace
          on index_namespace.oid = index_relation.relnamespace
        where index_namespace.nspname = 'public'
          and not index_catalog.indisvalid
      ),
    'day18_index_count',
      (
        select count(*)
        from pg_catalog.pg_indexes
        where schemaname = 'public'
          and indexname like 'idx_d18_%'
      ),
    'tables', v_tables,
    'indexes', v_indexes
  );
end;
$$;


ALTER FUNCTION "public"."get_day18_query_health"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_folios_page"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := private.day18_page_limit(p_limit);
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
begin
  perform private.day18_assert_page_access(p_hotel_id);

  select cursor_at, cursor_id
  into v_cursor_at, v_cursor_id
  from private.day18_decode_cursor(p_cursor);

  with candidates as (
    select
      f.*,
      g.full_name as guest_name,
      r.room_number,
      row_number() over (
        order by f.updated_at desc, f.id desc
      ) as rn
    from public.folios f
    left join public.guests g
      on g.hotel_id = f.hotel_id
     and g.id = f.guest_id
    left join public.rooms r
      on r.hotel_id = f.hotel_id
     and r.id = f.room_id
    where f.hotel_id = p_hotel_id
      and (p_status is null or f.status = p_status)
      and (
        v_cursor_at is null
        or v_cursor_id is null
        or (f.updated_at, f.id) < (v_cursor_at, v_cursor_id)
      )
    order by f.updated_at desc, f.id desc
    limit v_limit + 1
  ),
  visible as (
    select *
    from candidates
    where rn <= v_limit
  )
  select jsonb_build_object(
    'items',
      coalesce(
        (
          select jsonb_agg(
            (to_jsonb(v) - 'rn')
            order by v.updated_at desc, v.id desc
          )
          from visible v
        ),
        '[]'::jsonb
      ),
    'limit', v_limit,
    'has_more', (select count(*) > v_limit from candidates),
    'next_cursor',
      case
        when (select count(*) > v_limit from candidates)
        then (
          select private.day18_encode_cursor(v.updated_at, v.id)
          from visible v
          order by v.updated_at asc, v.id asc
          limit 1
        )
        else null
      end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_folios_page"("p_hotel_id" "uuid", "p_limit" integer, "p_cursor" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_food_operations_analytics"("p_hotel_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_permission(p_hotel_id, 'foodorders.view') then
    raise exception 'Food analytics access denied.';
  end if;

  if p_from is null or p_to is null or p_to <= p_from then
    raise exception 'A valid analytics date range is required.';
  end if;

  return jsonb_build_object(
    'orders', (
      select count(*) from public.food_orders fo
      where fo.hotel_id = p_hotel_id
        and fo.created_at >= p_from and fo.created_at < p_to
    ),
    'delivered_orders', (
      select count(*) from public.food_orders fo
      where fo.hotel_id = p_hotel_id
        and fo.created_at >= p_from and fo.created_at < p_to
        and fo.order_status = 'delivered'
    ),
    'cancelled_orders', (
      select count(*) from public.food_orders fo
      where fo.hotel_id = p_hotel_id
        and fo.created_at >= p_from and fo.created_at < p_to
        and fo.order_status = 'cancelled'
    ),
    'revenue', (
      select coalesce(sum(fo.total_amount), 0) from public.food_orders fo
      where fo.hotel_id = p_hotel_id
        and fo.created_at >= p_from and fo.created_at < p_to
        and fo.order_status = 'delivered'
    ),
    'average_order_value', (
      select coalesce(avg(fo.total_amount), 0) from public.food_orders fo
      where fo.hotel_id = p_hotel_id
        and fo.created_at >= p_from and fo.created_at < p_to
        and fo.order_status = 'delivered'
    ),
    'average_prep_minutes', (
      select coalesce(avg(extract(epoch from (fo.ready_at - fo.accepted_at)) / 60), 0)
      from public.food_orders fo
      where fo.hotel_id = p_hotel_id
        and fo.created_at >= p_from and fo.created_at < p_to
        and fo.ready_at is not null and fo.accepted_at is not null
    ),
    'popular_items', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'item_name', item_name_snapshot,
          'quantity', total_quantity,
          'revenue', revenue
        ) order by total_quantity desc, item_name_snapshot
      )
      from (
        select
          foi.item_name_snapshot,
          sum(foi.quantity)::integer as total_quantity,
          sum(foi.line_total) as revenue
        from public.food_order_items foi
        join public.food_orders fo
          on fo.id = foi.order_id
         and fo.hotel_id = foi.hotel_id
        where fo.hotel_id = p_hotel_id
          and fo.created_at >= p_from and fo.created_at < p_to
          and fo.order_status = 'delivered'
        group by foi.item_name_snapshot
        order by total_quantity desc
        limit 10
      ) ranked
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_food_operations_analytics"("p_hotel_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_food_order_kot"("p_hotel_id" "uuid", "p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.food_orders%rowtype;
  v_ticket public.kitchen_tickets%rowtype;
  v_actor uuid;
  v_result jsonb;
begin
  if not private.user_has_permission(p_hotel_id, 'foodorders.view') then
    raise exception 'Kitchen ticket access denied.';
  end if;

  select fo.* into v_order
  from public.food_orders fo
  where fo.hotel_id = p_hotel_id
    and fo.id = p_order_id;

  if not found then
    raise exception 'Food order was not found in the selected hotel.';
  end if;

  v_actor := auth.uid();

  insert into public.kitchen_tickets (
    hotel_id,
    food_order_id,
    ticket_number,
    print_count,
    first_printed_at,
    last_printed_at,
    last_printed_by
  ) values (
    p_hotel_id,
    p_order_id,
    'KOT-' || to_char(v_order.created_at at time zone 'UTC', 'YYYYMMDD')
      || '-' || upper(substr(replace(v_order.id::text, '-', ''), 1, 8)),
    1,
    now(),
    now(),
    v_actor
  )
  on conflict (hotel_id, food_order_id)
  do update set
    print_count = public.kitchen_tickets.print_count + 1,
    first_printed_at = coalesce(public.kitchen_tickets.first_printed_at, now()),
    last_printed_at = now(),
    last_printed_by = v_actor
  returning * into v_ticket;

  select jsonb_build_object(
    'ticket_id', v_ticket.id,
    'ticket_number', v_ticket.ticket_number,
    'print_count', v_ticket.print_count,
    'printed_at', v_ticket.last_printed_at,
    'order_id', v_order.id,
    'order_status', v_order.order_status,
    'created_at', v_order.created_at,
    'estimated_minutes', v_order.estimated_minutes,
    'room', jsonb_build_object('room_number', r.room_number),
    'guest', jsonb_build_object('full_name', g.full_name),
    'items', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'item_name', foi.item_name_snapshot,
          'quantity', foi.quantity,
          'modifiers', coalesce((
            select jsonb_agg(foim.modifier_name_snapshot order by foim.created_at, foim.id)
            from public.food_order_item_modifiers foim
            where foim.hotel_id = foi.hotel_id
              and foim.food_order_item_id = foi.id
          ), '[]'::jsonb)
        ) order by foi.id
      )
      from public.food_order_items foi
      where foi.hotel_id = v_order.hotel_id
        and foi.order_id = v_order.id
    ), '[]'::jsonb)
  ) into v_result
  from public.rooms r
  join public.guests g
    on g.id = v_order.guest_id
   and g.hotel_id = v_order.hotel_id
  where r.id = v_order.room_id
    and r.hotel_id = v_order.hotel_id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_food_order_kot"("p_hotel_id" "uuid", "p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_food_orders_page"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := private.day18_page_limit(p_limit);
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
begin
  perform private.day18_assert_page_access(p_hotel_id);

  select cursor_at, cursor_id
  into v_cursor_at, v_cursor_id
  from private.day18_decode_cursor(p_cursor);

  with candidates as (
    select
      fo.*,
      g.full_name as guest_name,
      r.room_number,
      row_number() over (
        order by fo.created_at desc, fo.id desc
      ) as rn
    from public.food_orders fo
    left join public.guests g
      on g.hotel_id = fo.hotel_id
     and g.id = fo.guest_id
    left join public.rooms r
      on r.hotel_id = fo.hotel_id
     and r.id = fo.room_id
    where fo.hotel_id = p_hotel_id
      and (p_status is null or fo.order_status = p_status)
      and (
        v_cursor_at is null
        or v_cursor_id is null
        or (fo.created_at, fo.id) < (v_cursor_at, v_cursor_id)
      )
    order by fo.created_at desc, fo.id desc
    limit v_limit + 1
  ),
  visible as (
    select *
    from candidates
    where rn <= v_limit
  )
  select jsonb_build_object(
    'items',
      coalesce(
        (
          select jsonb_agg(
            (to_jsonb(v) - 'rn')
            order by v.created_at desc, v.id desc
          )
          from visible v
        ),
        '[]'::jsonb
      ),
    'limit', v_limit,
    'has_more', (select count(*) > v_limit from candidates),
    'next_cursor',
      case
        when (select count(*) > v_limit from candidates)
        then (
          select private.day18_encode_cursor(v.created_at, v.id)
          from visible v
          order by v.created_at asc, v.id asc
          limit 1
        )
        else null
      end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_food_orders_page"("p_hotel_id" "uuid", "p_limit" integer, "p_cursor" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_guest_access_links"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb := '[]'::jsonb;
  room_row record;
  latest_token_id uuid;
  latest_token_status text;
  latest_token_expires_at timestamptz;
  latest_token_issued_at timestamptz;
  latest_token_last_used_at timestamptz;
  latest_token_use_count bigint;
  latest_revocation_reason text;
  token_history_exists boolean;
  rendered_token text;
begin
  if not private.user_has_permission(target_hotel_id, 'hotel.manage') then
    raise exception 'You do not have permission to manage guest access.';
  end if;

  -- Keep metadata honest even when no guest request arrives after expiry.
  update public.guest_access_tokens
  set status = 'expired',
      revoked_at = coalesce(revoked_at, now()),
      revocation_reason = coalesce(
        nullif(trim(revocation_reason), ''),
        'Signed guest access expired'
      ),
      updated_at = now()
  where hotel_id = target_hotel_id
    and status = 'active'
    and expires_at <= now();

  for room_row in
    select
      r.id as room_id,
      r.room_number,
      r.room_type,
      h.slug as hotel_slug,
      gs.id as guest_session_id,
      gs.checkout_time,
      gs.extended_until,
      g.full_name as guest_name
    from public.rooms r
    join public.hotels h on h.id = r.hotel_id
    left join lateral (
      select active_session.*
      from public.guest_sessions active_session
      where active_session.hotel_id = r.hotel_id
        and active_session.room_id = r.id
        and active_session.status = 'active'
        and coalesce(active_session.extended_until, active_session.checkout_time) > now()
      order by active_session.checkin_time desc
      limit 1
    ) gs on true
    left join public.guests g
      on g.id = gs.guest_id
     and g.hotel_id = r.hotel_id
    where r.hotel_id = target_hotel_id
    order by r.room_number
  loop
    latest_token_id := null;
    latest_token_status := null;
    latest_token_expires_at := null;
    latest_token_issued_at := null;
    latest_token_last_used_at := null;
    latest_token_use_count := 0;
    latest_revocation_reason := null;
    token_history_exists := false;
    rendered_token := null;

    if room_row.guest_session_id is not null then
      select
        t.id,
        t.status,
        t.expires_at,
        t.issued_at,
        t.last_used_at,
        t.use_count,
        t.revocation_reason
      into
        latest_token_id,
        latest_token_status,
        latest_token_expires_at,
        latest_token_issued_at,
        latest_token_last_used_at,
        latest_token_use_count,
        latest_revocation_reason
      from public.guest_access_tokens t
      where t.guest_session_id = room_row.guest_session_id
        and t.hotel_id = target_hotel_id
        and t.room_id = room_row.room_id
      order by t.issued_at desc, t.created_at desc
      limit 1;

      token_history_exists := latest_token_id is not null;

      -- Recovery path for an active legacy stay that has never had a token.
      -- A revoked/expired token is intentionally NOT replaced here.
      if not token_history_exists then
        latest_token_id := private.issue_guest_access_token(
          room_row.guest_session_id,
          false,
          null
        );

        select
          t.status,
          t.expires_at,
          t.issued_at,
          t.last_used_at,
          t.use_count,
          t.revocation_reason
        into
          latest_token_status,
          latest_token_expires_at,
          latest_token_issued_at,
          latest_token_last_used_at,
          latest_token_use_count,
          latest_revocation_reason
        from public.guest_access_tokens t
        where t.id = latest_token_id;
      end if;

      if latest_token_status = 'active'
         and latest_token_expires_at > now() then
        rendered_token := private.render_guest_access_token(latest_token_id);
      end if;
    end if;

    result := result || jsonb_build_array(
      jsonb_build_object(
        'room_id', room_row.room_id,
        'room_number', room_row.room_number,
        'room_type', room_row.room_type,
        'guest_session_id', room_row.guest_session_id,
        'guest_name', room_row.guest_name,
        -- Legacy compatibility field. It now means an active stay exists.
        'active', room_row.guest_session_id is not null,
        'stay_active', room_row.guest_session_id is not null,
        'access_active', rendered_token is not null,
        'access_status', case
          when room_row.guest_session_id is null then 'no_active_stay'
          when rendered_token is not null then 'active'
          when latest_token_status = 'revoked' then 'revoked'
          when latest_token_status = 'expired' then 'expired'
          else 'not_issued'
        end,
        'expires_at', coalesce(room_row.extended_until, room_row.checkout_time),
        'token_expires_at', latest_token_expires_at,
        'token_issued_at', latest_token_issued_at,
        'token_last_used_at', latest_token_last_used_at,
        'token_use_count', coalesce(latest_token_use_count, 0),
        'revocation_reason', latest_revocation_reason,
        'guest_path', case
          when rendered_token is null then null
          else '/guest/' || room_row.hotel_slug || '/' || rendered_token
        end,
        'food_path', case
          when rendered_token is null then null
          else '/food/' || room_row.hotel_slug || '/' || rendered_token
        end
      )
    );
  end loop;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_guest_access_links"("target_hotel_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_guest_access_links"("target_hotel_id" "uuid") IS 'Returns hotel-scoped signed guest links. Manual revocation persists until explicit token rotation.';



CREATE OR REPLACE FUNCTION "public"."get_guest_folio_snapshot"("target_hotel_id" "uuid", "target_folio_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result_value jsonb;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'payments.view',
      'payments.manage',
      'invoices.view',
      'invoices.manage',
      'checkout.manage'
    ]::text[]
  ) then
    raise exception 'Folio view access denied.';
  end if;

  select jsonb_build_object(
    'folio', to_jsonb(folio),
    'items', coalesce((
      select jsonb_agg(
        to_jsonb(item)
        order by item.service_at, item.created_at, item.id
      )
      from public.folio_items item
      where item.hotel_id = folio.hotel_id
        and item.folio_id = folio.id
    ), '[]'::jsonb),
    'collections', coalesce((
      select jsonb_agg(
        to_jsonb(collection)
        order by collection.collected_at, collection.id
      )
      from public.folio_collections collection
      where collection.hotel_id = folio.hotel_id
        and collection.folio_id = folio.id
    ), '[]'::jsonb),
    'adjustments', coalesce((
      select jsonb_agg(
        to_jsonb(adjustment)
        order by adjustment.posted_at, adjustment.id
      )
      from public.folio_adjustments adjustment
      where adjustment.hotel_id = folio.hotel_id
        and adjustment.folio_id = folio.id
    ), '[]'::jsonb),
    'discount_approvals', coalesce((
      select jsonb_agg(
        to_jsonb(approval)
        order by approval.requested_at, approval.id
      )
      from public.discount_approvals approval
      where approval.hotel_id = folio.hotel_id
        and approval.folio_id = folio.id
    ), '[]'::jsonb),
    'refunds', coalesce((
      select jsonb_agg(
        to_jsonb(refund)
        order by refund.requested_at, refund.id
      )
      from public.refunds refund
      where refund.hotel_id = folio.hotel_id
        and refund.folio_id = folio.id
    ), '[]'::jsonb),
    'credit_notes', coalesce((
      select jsonb_agg(
        to_jsonb(credit)
        order by credit.issued_at, credit.id
      )
      from public.credit_notes credit
      where credit.hotel_id = folio.hotel_id
        and credit.folio_id = folio.id
    ), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(
        to_jsonb(event_record)
        order by event_record.created_at, event_record.id
      )
      from public.folio_events event_record
      where event_record.hotel_id = folio.hotel_id
        and event_record.folio_id = folio.id
    ), '[]'::jsonb),
    'equation', jsonb_build_object(
      'charges', folio.charges_amount,
      'discounts', folio.discount_amount,
      'taxes', folio.tax_amount,
      'collections', folio.collection_amount,
      'refunds', folio.refund_amount,
      'credits', folio.credit_amount,
      'balance', folio.balance_amount,
      'formula',
        'charges - discounts + taxes - collections + refunds - credits = balance'
    )
  )
  into result_value
  from public.folios folio
  where folio.hotel_id = target_hotel_id
    and folio.id = target_folio_id;

  if result_value is null then
    raise exception 'Folio was not found.';
  end if;

  return result_value;
end;
$$;


ALTER FUNCTION "public"."get_guest_folio_snapshot"("target_hotel_id" "uuid", "target_folio_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_guest_folio_snapshot"("target_hotel_id" "uuid", "target_folio_id" "uuid") IS 'Returns the authoritative Day 11 folio header, line items, collections, adjustments, approvals, refunds, credits, events and reconciliation equation.';



CREATE OR REPLACE FUNCTION "public"."get_guest_food_menu"("p_hotel_slug" "text", "p_access_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context
  from private.day15_guest_context(
    p_hotel_slug,
    p_access_token,
    true
  );

  select coalesce(
    jsonb_agg(item_json order by category_sort, item_sort, item_name),
    '[]'::jsonb
  )
  into v_result
  from (
    select
      coalesce(mc.sort_order, 0) as category_sort,
      coalesce(mi.sort_order, 0) as item_sort,
      mi.item_name,
      jsonb_build_object(
        'id', mi.id,
        'item_name', mi.item_name,
        'description', mi.description,
        'translations', coalesce(mi.translations, '{}'::jsonb),
        'price', mi.price,
        'image_url', mi.image_url,
        'category_id', mc.id,
        'category', coalesce(mc.name, mi.category, 'Menu'),
        'category_code', mc.code,
        'category_translations', coalesce(mc.translations, '{}'::jsonb),
        'tax_rate', mi.tax_rate,
        'tax_inclusive', mi.tax_inclusive,
        'preparation_minutes', mi.preparation_minutes,
        'currency_code', v_context.currency_code,
        'service_start_time', mc.service_start_time,
        'service_end_time', mc.service_end_time,
        'modifier_groups', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'id', mg.id,
              'name', mg.name,
              'translations', coalesce(mg.translations, '{}'::jsonb),
              'min_selections', mg.min_selections,
              'max_selections', mg.max_selections,
              'is_required', mg.is_required,
              'modifiers', coalesce((
                select jsonb_agg(
                  jsonb_build_object(
                    'id', mm.id,
                    'name', mm.name,
                    'translations', coalesce(mm.translations, '{}'::jsonb),
                    'price_delta', mm.price_delta
                  )
                  order by mm.sort_order, mm.name
                )
                from public.menu_item_modifiers mm
                where mm.hotel_id = mg.hotel_id
                  and mm.modifier_group_id = mg.id
                  and mm.is_available
              ), '[]'::jsonb)
            )
            order by mg.sort_order, mg.name
          )
          from public.menu_item_modifier_groups mg
          where mg.hotel_id = mi.hotel_id
            and mg.menu_item_id = mi.id
            and mg.is_active
        ), '[]'::jsonb)
      ) as item_json
    from public.menu_items mi
    join public.menu_categories mc
      on mc.id = mi.category_id
     and mc.hotel_id = mi.hotel_id
    where mi.hotel_id = v_context.hotel_id
      and mi.is_available
      and mi.archived_at is null
      and private.day15_menu_item_available_now(
        mc,
        v_context.hotel_timezone
      )
  ) available_items;

  return coalesce(v_result, '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_guest_food_menu"("p_hotel_slug" "text", "p_access_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_guest_food_orders"("p_hotel_slug" "text", "p_access_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context
  from private.day15_guest_context(
    p_hotel_slug,
    p_access_token,
    true
  );

  select coalesce(
    jsonb_agg(order_json order by created_at desc),
    '[]'::jsonb
  ) into v_result
  from (
    select
      fo.created_at,
      jsonb_build_object(
        'id', fo.id,
        'subtotal_amount', fo.subtotal_amount,
        'modifier_amount', fo.modifier_amount,
        'tax_amount', fo.tax_amount,
        'total_amount', fo.total_amount,
        'currency_code', fo.currency_code,
        'payment_status', fo.payment_status,
        'order_status', fo.order_status,
        'created_at', fo.created_at,
        'estimated_minutes', fo.estimated_minutes,
        'estimated_delivery_time', fo.estimated_delivery_time,
        'accepted_at', fo.accepted_at,
        'preparing_at', fo.preparing_at,
        'ready_at', fo.ready_at,
        'out_for_delivery_at', fo.out_for_delivery_at,
        'delivered_at', fo.delivered_at,
        'cancelled_at', fo.cancelled_at,
        'cancellation_reason', fo.cancellation_reason,
        'can_cancel', (
          fo.order_status = 'pending'
          or (
            fo.order_status = 'accepted'
            and coalesce(fo.accepted_at, fo.created_at) > now() - interval '2 minutes'
          )
        ),
        'food_order_items', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'id', foi.id,
              'menu_item_id', foi.menu_item_id,
              'quantity', foi.quantity,
              'price', foi.price,
              'unit_price', foi.unit_price,
              'modifier_amount', foi.modifier_amount,
              'tax_amount', foi.tax_amount,
              'line_total', foi.line_total,
              'item_name', foi.item_name_snapshot,
              'translations', coalesce(mi.translations, '{}'::jsonb),
              'modifiers', coalesce((
                select jsonb_agg(
                  jsonb_build_object(
                    'modifier_id', foim.modifier_id,
                    'name', foim.modifier_name_snapshot,
                    'translations', coalesce(mm.translations, '{}'::jsonb),
                    'price_delta', foim.price_delta
                  ) order by foim.created_at, foim.id
                )
                from public.food_order_item_modifiers foim
                left join public.menu_item_modifiers mm
                  on mm.hotel_id = foim.hotel_id
                 and mm.id = foim.modifier_id
                where foim.hotel_id = foi.hotel_id
                  and foim.food_order_item_id = foi.id
              ), '[]'::jsonb)
            ) order by foi.id
          )
          from public.food_order_items foi
          left join public.menu_items mi
            on mi.hotel_id = foi.hotel_id
           and mi.id = foi.menu_item_id
          where foi.hotel_id = fo.hotel_id
            and foi.order_id = fo.id
        ), '[]'::jsonb),
        'events', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'event_type', foe.event_type,
              'from_status', foe.from_status,
              'to_status', foe.to_status,
              'estimated_minutes', foe.estimated_minutes,
              'message', foe.message,
              'created_at', foe.created_at
            ) order by foe.created_at, foe.id
          )
          from public.food_order_events foe
          where foe.hotel_id = fo.hotel_id
            and foe.food_order_id = fo.id
        ), '[]'::jsonb)
      ) as order_json
    from public.food_orders fo
    where fo.hotel_id = v_context.hotel_id
      and (
        fo.guest_session_id = v_context.guest_session_id
        or (
          fo.guest_session_id is null
          and fo.room_id = v_context.room_id
          and fo.guest_id = v_context.guest_id
        )
      )
  ) orders;

  return coalesce(v_result, '[]'::jsonb);
end;
$$;


