CREATE OR REPLACE FUNCTION "public"."get_guest_guide_builder"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_permission(
    p_hotel_id,
    'hotel.manage'
  ) then
    raise exception 'Guest guide builder access denied.';
  end if;

  return private.day14_build_guide_snapshot(p_hotel_id)
    || jsonb_build_object(
      'publish_state',
      (
        select jsonb_build_object(
          'publish_status', s.publish_status,
          'draft_revision', s.draft_revision,
          'published_version', s.published_version,
          'published_at', s.published_at
        )
        from public.guest_guide_settings s
        where s.hotel_id = p_hotel_id
      ),
      'room_types',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', rt.id,
              'name', rt.name,
              'code', rt.code,
              'description', rt.description,
              'is_active', rt.is_active
            )
            order by rt.sort_order, rt.name
          )
          from public.room_types rt
          where rt.hotel_id = p_hotel_id
        ),
        '[]'::jsonb
      ),
      'rooms',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', r.id,
              'room_number', r.room_number,
              'room_type_id', r.room_type_id,
              'room_type', r.room_type,
              'status', r.status,
              'is_active', r.is_active
            )
            order by r.room_number
          )
          from public.rooms r
          where r.hotel_id = p_hotel_id
        ),
        '[]'::jsonb
      ),
      'versions',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', v.id,
              'version_number', v.version_number,
              'publish_note', v.publish_note,
              'published_at', v.published_at,
              'published_by', v.published_by
            )
            order by v.version_number desc
          )
          from public.guest_guide_versions v
          where v.hotel_id = p_hotel_id
        ),
        '[]'::jsonb
      )
    );
end;
$$;


