CREATE OR REPLACE FUNCTION "public"."get_guest_sessions_page"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := private.day18_page_limit(p_limit);
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
begin
  perform private.day18_assert_page_access(p_hotel_id);

  select cursor_at, cursor_id
  into v_cursor_at, v_cursor_id
  from private.day18_decode_cursor(p_cursor);

  with candidates as (
    select
      gs.*,
      g.full_name as guest_name,
      r.room_number,
      row_number() over (
        order by gs.created_at desc, gs.id desc
      ) as rn
    from public.guest_sessions gs
    left join public.guests g
      on g.hotel_id = gs.hotel_id
     and g.id = gs.guest_id
    left join public.rooms r
      on r.hotel_id = gs.hotel_id
     and r.id = gs.room_id
    where gs.hotel_id = p_hotel_id
      and (p_status is null or gs.status = p_status)
      and (
        v_cursor_at is null
        or v_cursor_id is null
        or (gs.created_at, gs.id) < (v_cursor_at, v_cursor_id)
      )
    order by gs.created_at desc, gs.id desc
    limit v_limit + 1
  ),
  visible as (
    select *
    from candidates
    where rn <= v_limit
  )
  select jsonb_build_object(
    'items',
      coalesce(
        (
          select jsonb_agg(
            (to_jsonb(v) - 'rn')
            order by v.created_at desc, v.id desc
          )
          from visible v
        ),
        '[]'::jsonb
      ),
    'limit', v_limit,
    'has_more', (select count(*) > v_limit from candidates),
    'next_cursor',
      case
        when (select count(*) > v_limit from candidates)
        then (
          select private.day18_encode_cursor(v.created_at, v.id)
          from visible v
          order by v.created_at asc, v.id asc
          limit 1
        )
        else null
      end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_guest_sessions_page"("p_hotel_id" "uuid", "p_limit" integer, "p_cursor" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_guests_page"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := private.day18_page_limit(p_limit);
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
  v_search text := nullif(lower(trim(p_search)), '');
begin
  perform private.day18_assert_page_access(p_hotel_id);

  select cursor_at, cursor_id
  into v_cursor_at, v_cursor_id
  from private.day18_decode_cursor(p_cursor);

  with candidates as (
    select
      g.*,
      row_number() over (
        order by g.updated_at desc, g.id desc
      ) as rn
    from public.guests g
    where g.hotel_id = p_hotel_id
      and (
        v_search is null
        or lower(g.full_name) like v_search || '%'
        or coalesce(g.normalized_phone, '') like v_search || '%'
        or coalesce(g.normalized_email, '') like v_search || '%'
      )
      and (
        v_cursor_at is null
        or v_cursor_id is null
        or (g.updated_at, g.id) < (v_cursor_at, v_cursor_id)
      )
    order by g.updated_at desc, g.id desc
    limit v_limit + 1
  ),
  visible as (
    select *
    from candidates
    where rn <= v_limit
  )
  select jsonb_build_object(
    'items',
      coalesce(
        (
          select jsonb_agg(
            (to_jsonb(v) - 'rn')
            order by v.updated_at desc, v.id desc
          )
          from visible v
        ),
        '[]'::jsonb
      ),
    'limit', v_limit,
    'has_more', (select count(*) > v_limit from candidates),
    'next_cursor',
      case
        when (select count(*) > v_limit from candidates)
        then (
          select private.day18_encode_cursor(v.updated_at, v.id)
          from visible v
          order by v.updated_at asc, v.id asc
          limit 1
        )
        else null
      end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_guests_page"("p_hotel_id" "uuid", "p_limit" integer, "p_cursor" "text", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_hotel_guest_content"("p_hotel_id" "uuid", "p_locale" "text" DEFAULT 'en'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_locale text := coalesce(nullif(trim(p_locale), ''), 'en');
  v_result jsonb;
begin
  if not private.user_has_permission(p_hotel_id, 'hotel.manage') then
    raise exception 'Guest content access denied.';
  end if;

  if v_locale !~ '^[a-z]{2}(-[A-Z]{2})?$' then
    raise exception 'Invalid locale.';
  end if;

  select jsonb_build_object(
    'hotel_id', h.id,
    'locale', v_locale,
    'base_profile', jsonb_strip_nulls(
      jsonb_build_object(
        'hotel_name', coalesce(hi.hotel_name, h.hotel_name),
        'address', coalesce(hi.address, h.address, h.location),
        'about', hi.about,
        'wifi_name', hi.wifi_name,
        'wifi_password', hi.wifi_password,
        'checkin_time', hi.checkin_time,
        'checkout_time', hi.checkout_time,
        'breakfast_time', hi.breakfast_time,
        'reception_phone', hi.reception_phone,
        'emergency_phone', hi.emergency_phone,
        'hotel_rules', hi.hotel_rules,
        'google_review_url', hi.google_review_url,
        'reward_enabled', coalesce(hi.reward_enabled, false),
        'reward_title', hi.reward_title,
        'reward_description', hi.reward_description
      )
    ),
    'content', coalesce(hgc.content, '{}'::jsonb),
    'is_active', coalesce(hgc.is_active, true),
    'available_locales', coalesce(
      (
        select jsonb_agg(c.locale order by c.locale)
        from public.hotel_guest_content c
        where c.hotel_id = h.id
          and c.is_active
      ),
      '[]'::jsonb
    ),
    'amenities', coalesce(
      (
        select jsonb_agg(
          jsonb_strip_nulls(
            jsonb_build_object(
              'id', a.id,
              'name', a.name,
              'description', a.description,
              'instructions', a.instructions,
              'icon', a.icon,
              'sort_order', a.sort_order
            )
          )
          order by a.sort_order, a.name
        )
        from public.amenities a
        where a.hotel_id = h.id
          and a.is_active
          and a.guest_visible
      ),
      '[]'::jsonb
    )
  )
  into v_result
  from public.hotels h
  left join public.hotel_info hi
    on hi.hotel_id = h.id
  left join public.hotel_guest_content hgc
    on hgc.hotel_id = h.id
   and hgc.locale = v_locale
  where h.id = p_hotel_id;

  if v_result is null then
    raise exception 'Hotel was not found.';
  end if;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."get_hotel_guest_content"("p_hotel_id" "uuid", "p_locale" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_hotel_onboarding_readiness"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_hotel_access(target_hotel_id)
    or exists (
      select 1
      from public.hotel_onboarding ho
      where ho.hotel_id = target_hotel_id
        and ho.owner_user_id = actor_user_id
    )
  ) then
    raise exception 'Hotel access denied.';
  end if;

  return private.compute_hotel_onboarding_readiness(target_hotel_id);
end;
$$;


ALTER FUNCTION "public"."get_hotel_onboarding_readiness"("target_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_hotel_subscription_usage"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  refreshed jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_hotel_access(target_hotel_id)
  ) then
    raise exception 'Hotel usage access denied.';
  end if;

  refreshed :=
    private.refresh_subscription_usage_internal(
      target_hotel_id
    );

  return refreshed || jsonb_build_object(
    'counters',
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'metric_key', uc.metric_key,
            'current_value', uc.current_value,
            'limit_value', uc.limit_value,
            'captured_at', uc.captured_at
          )
          order by uc.metric_key
        ),
        '[]'::jsonb
      )
      from public.usage_counters uc
      where uc.hotel_id = target_hotel_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_hotel_subscription_usage"("target_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_hotel_system_settings"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_hotel_access(p_hotel_id) then
    raise exception 'Hotel settings access denied.';
  end if;

  return (
    select jsonb_build_object(
      'hotel', jsonb_build_object(
        'id', h.id,
        'hotel_name', h.hotel_name,
        'timezone', h.timezone,
        'currency_code', h.currency_code,
        'status', h.status
      ),
      'hotel_settings', to_jsonb(hs),
      'business_day_settings', to_jsonb(bds),
      'notification_preferences', (
        select to_jsonb(np)
        from public.notification_preferences np
        where np.hotel_id = p_hotel_id
          and np.user_id = (select auth.uid())
      ),
      'email_adapter', case
        when private.day17_can_manage_hotel(p_hotel_id) then (
          select to_jsonb(eac) - 'secret_reference'
          from public.email_adapter_configs eac
          where eac.hotel_id = p_hotel_id
          order by eac.updated_at desc
          limit 1
        )
        else null
      end
    )
    from public.hotels h
    left join public.hotel_settings hs
      on hs.hotel_id = h.id
    left join public.business_day_settings bds
      on bds.hotel_id = h.id
    where h.id = p_hotel_id
  );
end;
$$;


ALTER FUNCTION "public"."get_hotel_system_settings"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_housekeeping_mobile_queue"("target_hotel_id" "uuid", "target_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'housekeeping.view',
      'housekeeping.manage',
      'rooms.view',
      'rooms.manage'
    ]::text[]
  ) then
    raise exception
      'Housekeeping mobile access denied.';
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'task_id', task.id,
          'room_id', task.room_id,
          'room_number', room.room_number,
          'room_status', room.status,
          'task_type', task.task_type,
          'status', task.status,
          'priority', task.priority,
          'due_at', task.due_at,
          'notes', task.notes,
          'assigned_staff_id',
            task.assigned_staff_id,
          'assigned_to', task.assigned_to,
          'completed_items',
            (
              select count(*)
              from public.housekeeping_task_items item
              where item.hotel_id = task.hotel_id
                and item.task_id = task.id
                and item.item_status in (
                  'completed',
                  'not_applicable'
                )
            ),
          'total_items',
            (
              select count(*)
              from public.housekeeping_task_items item
              where item.hotel_id = task.hotel_id
                and item.task_id = task.id
            )
        )
        order by
          case task.priority
            when 'urgent' then 1
            when 'high' then 2
            when 'normal' then 3
            else 4
          end,
          task.due_at nulls last,
          task.created_at
      )
      from public.housekeeping_tasks task
      join public.rooms room
        on room.hotel_id = task.hotel_id
       and room.id = task.room_id
      where task.hotel_id = target_hotel_id
        and task.status in (
          'pending',
          'assigned',
          'in_progress',
          'cleaning_complete',
          'inspection_failed',
          'inspected'
        )
        and (
          target_staff_id is null
          or task.assigned_staff_id =
             target_staff_id
          or task.assigned_staff_id is null
        )
    ),
    '[]'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."get_housekeeping_mobile_queue"("target_hotel_id" "uuid", "target_staff_id" "uuid") OWNER TO "postgres";


