CREATE OR REPLACE FUNCTION "public"."get_housekeeping_workspace"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'housekeeping.view',
      'housekeeping.manage',
      'rooms.view',
      'rooms.manage'
    ]::text[]
  ) then
    raise exception
      'Housekeeping workspace access denied.';
  end if;

  return jsonb_build_object(
    'tasks',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(task)
            || jsonb_build_object(
              'room',
                jsonb_build_object(
                  'id', room.id,
                  'room_number', room.room_number,
                  'status', room.status,
                  'floor_id', room.floor_id,
                  'room_type_id', room.room_type_id
                ),
              'staff',
                case
                  when staff.id is null then null
                  else jsonb_build_object(
                    'id', staff.id,
                    'full_name', staff.full_name,
                    'role', staff.role,
                    'status', staff.status
                  )
                end,
              'items',
                (
                  select coalesce(
                    jsonb_agg(
                      to_jsonb(item)
                      order by item.sort_order
                    ),
                    '[]'::jsonb
                  )
                  from public.housekeeping_task_items item
                  where item.hotel_id = task.hotel_id
                    and item.task_id = task.id
                ),
              'latest_inspection',
                (
                  select to_jsonb(inspection)
                  from public.housekeeping_inspections inspection
                  where inspection.hotel_id = task.hotel_id
                    and inspection.task_id = task.id
                  order by inspection.inspected_at desc
                  limit 1
                )
            )
            order by
              case task.priority
                when 'urgent' then 1
                when 'high' then 2
                when 'normal' then 3
                else 4
              end,
              task.due_at nulls last,
              task.created_at
          )
          from public.housekeeping_tasks task
          join public.rooms room
            on room.hotel_id = task.hotel_id
           and room.id = task.room_id
          left join public.staff staff
            on staff.hotel_id = task.hotel_id
           and staff.id = task.assigned_staff_id
          where task.hotel_id = target_hotel_id
        ),
        '[]'::jsonb
      ),
    'workload',
      coalesce(
        (
          select jsonb_agg(
            workload_row
            order by
              workload_row ->> 'staff_name'
          )
          from (
            select jsonb_build_object(
              'staff_id', staff.id,
              'staff_name', staff.full_name,
              'role', staff.role,
              'open_tasks',
                count(task.id) filter (
                  where task.status in (
                    'assigned',
                    'in_progress',
                    'cleaning_complete',
                    'inspection_failed',
                    'inspected'
                  )
                ),
              'urgent_tasks',
                count(task.id) filter (
                  where task.priority = 'urgent'
                    and task.status in (
                      'assigned',
                      'in_progress',
                      'cleaning_complete',
                      'inspection_failed',
                      'inspected'
                    )
                ),
              'in_progress_tasks',
                count(task.id) filter (
                  where task.status = 'in_progress'
                ),
              'ready_today',
                count(task.id) filter (
                  where task.status = 'ready'
                    and task.room_ready_at::date =
                        current_date
                )
            ) workload_row
            from public.staff staff
            left join public.housekeeping_tasks task
              on task.hotel_id = staff.hotel_id
             and task.assigned_staff_id = staff.id
            where staff.hotel_id = target_hotel_id
              and staff.status = 'active'
              and staff.disabled_at is null
            group by
              staff.id,
              staff.full_name,
              staff.role
          ) staff_workload
        ),
        '[]'::jsonb
      ),
    'unassigned_open_tasks',
      (
        select count(*)
        from public.housekeeping_tasks task
        where task.hotel_id = target_hotel_id
          and task.assigned_staff_id is null
          and task.status in (
            'pending',
            'inspection_failed'
          )
      ),
    'rooms_waiting_for_ready',
      (
        select count(*)
        from public.rooms room
        where room.hotel_id = target_hotel_id
          and room.status = 'cleaning'
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_housekeeping_workspace"("target_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invoice_snapshot"("target_hotel_id" "uuid", "target_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invoice_row public.invoices%rowtype;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'invoices.view',
      'invoices.manage',
      'checkout.manage'
    ]::text[]
  ) then
    raise exception 'Invoice access denied.';
  end if;

  select invoice.*
  into invoice_row
  from public.invoices invoice
  where invoice.hotel_id = target_hotel_id
    and invoice.id = target_invoice_id;

  if not found then
    raise exception 'Invoice was not found.';
  end if;

  return jsonb_build_object(
    'invoice', to_jsonb(invoice_row),
    'snapshot', invoice_row.snapshot_json,
    'snapshot_hash', invoice_row.snapshot_hash,
    'verification_token',
      invoice_row.verification_token,
    'events',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(event_record)
            order by event_record.created_at,
                     event_record.id
          )
          from public.invoice_events event_record
          where event_record.hotel_id =
                target_hotel_id
            and event_record.invoice_id =
                target_invoice_id
        ),
        '[]'::jsonb
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_invoice_snapshot"("target_hotel_id" "uuid", "target_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_maintenance_mobile_queue"("target_hotel_id" "uuid", "target_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'rooms.view',
      'rooms.manage',
      'housekeeping.view',
      'housekeeping.manage',
      'hotel.manage'
    ]::text[]
  ) then
    raise exception
      'Maintenance mobile access denied.';
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'task_id', task.id,
          'task_number', task.task_number,
          'room_id', task.room_id,
          'room_number', room.room_number,
          'room_status', room.status,
          'title', task.title,
          'category', task.category,
          'severity', task.severity,
          'status', task.status,
          'inventory_impact',
            task.inventory_impact,
          'due_at', task.due_at,
          'expected_return_date',
            task.expected_return_date,
          'assigned_staff_id',
            task.assigned_staff_id
        )
        order by
          case task.severity
            when 'critical' then 1
            when 'high' then 2
            when 'medium' then 3
            else 4
          end,
          task.due_at nulls last,
          task.created_at
      )
      from public.maintenance_tasks task
      join public.rooms room
        on room.hotel_id = task.hotel_id
       and room.id = task.room_id
      where task.hotel_id =
            target_hotel_id
        and task.status in (
          'reported',
          'assigned',
          'in_progress',
          'on_hold',
          'resolved'
        )
        and (
          target_staff_id is null
          or task.assigned_staff_id =
             target_staff_id
          or task.assigned_staff_id is null
        )
    ),
    '[]'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."get_maintenance_mobile_queue"("target_hotel_id" "uuid", "target_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_maintenance_workspace"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'rooms.view',
      'rooms.manage',
      'housekeeping.view',
      'housekeeping.manage',
      'hotel.manage'
    ]::text[]
  ) then
    raise exception
      'Maintenance workspace access denied.';
  end if;

  return jsonb_build_object(
    'tasks',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(task)
            || jsonb_build_object(
              'room',
                jsonb_build_object(
                  'id', room.id,
                  'room_number',
                    room.room_number,
                  'status', room.status,
                  'floor_id', room.floor_id,
                  'room_type_id',
                    room.room_type_id
                ),
              'staff',
                case
                  when staff.id is null
                    then null
                  else jsonb_build_object(
                    'id', staff.id,
                    'full_name',
                      staff.full_name,
                    'role', staff.role,
                    'status', staff.status
                  )
                end,
              'room_block',
                case
                  when block_record.id is null
                    then null
                  else to_jsonb(block_record)
                end,
              'latest_verification',
                (
                  select to_jsonb(verification)
                  from public.maintenance_verifications verification
                  where verification.hotel_id =
                        task.hotel_id
                    and verification.task_id =
                        task.id
                  order by
                    verification.verified_at desc
                  limit 1
                )
            )
            order by
              case task.severity
                when 'critical' then 1
                when 'high' then 2
                when 'medium' then 3
                else 4
              end,
              task.due_at nulls last,
              task.created_at
          )
          from public.maintenance_tasks task
          join public.rooms room
            on room.hotel_id = task.hotel_id
           and room.id = task.room_id
          left join public.staff staff
            on staff.hotel_id = task.hotel_id
           and staff.id = task.assigned_staff_id
          left join public.room_blocks block_record
            on block_record.hotel_id =
               task.hotel_id
           and block_record.id =
               task.room_block_id
          where task.hotel_id =
                target_hotel_id
        ),
        '[]'::jsonb
      ),
    'workload',
      coalesce(
        (
          select jsonb_agg(
            workload_row
            order by
              workload_row
              ->> 'staff_name'
          )
          from (
            select jsonb_build_object(
              'staff_id', staff.id,
              'staff_name', staff.full_name,
              'role', staff.role,
              'open_tasks',
                count(task.id) filter (
                  where task.status in (
                    'assigned',
                    'in_progress',
                    'on_hold',
                    'resolved'
                  )
                ),
              'critical_tasks',
                count(task.id) filter (
                  where task.severity =
                        'critical'
                    and task.status in (
                      'assigned',
                      'in_progress',
                      'on_hold',
                      'resolved'
                    )
                ),
              'in_progress_tasks',
                count(task.id) filter (
                  where task.status =
                        'in_progress'
                )
            ) workload_row
            from public.staff staff
            left join public.maintenance_tasks task
              on task.hotel_id =
                 staff.hotel_id
             and task.assigned_staff_id =
                 staff.id
            where staff.hotel_id =
                  target_hotel_id
              and staff.status = 'active'
              and staff.disabled_at is null
            group by
              staff.id,
              staff.full_name,
              staff.role
          ) staff_workload
        ),
        '[]'::jsonb
      ),
    'unassigned_open_tasks',
      (
        select count(*)
        from public.maintenance_tasks task
        where task.hotel_id =
              target_hotel_id
          and task.assigned_staff_id is null
          and task.status = 'reported'
      ),
    'offline_rooms',
      (
        select count(distinct task.room_id)
        from public.maintenance_tasks task
        where task.hotel_id =
              target_hotel_id
          and task.inventory_impact <>
              'none'
          and task.status in (
            'reported',
            'assigned',
            'in_progress',
            'on_hold',
            'resolved'
          )
      ),
    'active_room_blocks',
      (
        select count(*)
        from public.room_blocks block_record
        where block_record.hotel_id =
              target_hotel_id
          and block_record.status = 'active'
          and block_record.block_type in (
            'maintenance',
            'out_of_order'
          )
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_maintenance_workspace"("target_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_hotel_permissions"("target_hotel_id" "uuid") RETURNS TABLE("permission_key" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select distinct permission.permission_key
  from (
    select rp.permission_key
    from public.staff s
    join public.role_permissions rp
      on lower(replace(trim(rp.role_name), ' ', '_')) =
         lower(replace(trim(s.role), ' ', '_'))
    where s.hotel_id = target_hotel_id
      and s.auth_user_id = (select auth.uid())
      and s.status = 'active'

    union all

    select rp.permission_key
    from public.role_permissions rp
    where private.is_platform_admin()
  ) permission
  where private.user_has_hotel_access(target_hotel_id)
  order by permission.permission_key;
$$;


ALTER FUNCTION "public"."get_my_hotel_permissions"("target_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_night_audit_snapshot"("h" "uuid", "audit_id_value" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a public.night_audits%rowtype;
begin
  if not private.user_has_any_permission(h,array['payments.view','payments.manage','invoices.view','invoices.manage','checkout.manage']::text[]) then
    raise exception 'Night-audit snapshot access denied.';
  end if;
  select * into a from public.night_audits where hotel_id=h and id=audit_id_value;
  if not found then raise exception 'Night audit not found.'; end if;
  return jsonb_build_object(
    'night_audit',to_jsonb(a),'snapshot',a.snapshot_json,
    'hash_valid',a.snapshot_hash=private.day12_hash_snapshot(a.snapshot_json),
    'exceptions',coalesce((select jsonb_agg(to_jsonb(e) order by e.severity,e.exception_type,e.id)
                           from public.night_audit_exceptions e
                           where e.hotel_id=h and e.night_audit_id=audit_id_value),'[]'::jsonb),
    'exports',coalesce((select jsonb_agg(to_jsonb(x) order by x.generated_at,x.id)
                        from public.accounting_exports x
                        where x.hotel_id=h and x.night_audit_id=audit_id_value),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_night_audit_snapshot"("h" "uuid", "audit_id_value" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_deliveries_page"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_channel" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := private.day18_page_limit(p_limit);
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
begin
  perform private.day18_assert_page_access(p_hotel_id);

  select cursor_at, cursor_id
  into v_cursor_at, v_cursor_id
  from private.day18_decode_cursor(p_cursor);

  with candidates as (
    select
      nd.*,
      row_number() over (
        order by nd.created_at desc, nd.id desc
      ) as rn
    from public.notification_deliveries nd
    where nd.hotel_id = p_hotel_id
      and (p_status is null or nd.status = p_status)
      and (p_channel is null or nd.channel = p_channel)
      and (
        v_cursor_at is null
        or v_cursor_id is null
        or (nd.created_at, nd.id) < (v_cursor_at, v_cursor_id)
      )
    order by nd.created_at desc, nd.id desc
    limit v_limit + 1
  ),
  visible as (
    select *
    from candidates
    where rn <= v_limit
  )
  select jsonb_build_object(
    'items',
      coalesce(
        (
          select jsonb_agg(
            (to_jsonb(v) - 'rn')
            order by v.created_at desc, v.id desc
          )
          from visible v
        ),
        '[]'::jsonb
      ),
    'limit', v_limit,
    'has_more', (select count(*) > v_limit from candidates),
    'next_cursor',
      case
        when (select count(*) > v_limit from candidates)
        then (
          select private.day18_encode_cursor(v.created_at, v.id)
          from visible v
          order by v.created_at asc, v.id asc
          limit 1
        )
        else null
      end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_notification_deliveries_page"("p_hotel_id" "uuid", "p_limit" integer, "p_cursor" "text", "p_status" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_inbox"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_result jsonb;
begin
  if v_user_id is null
     or not private.user_has_hotel_access(p_hotel_id)
  then
    raise exception 'Notification inbox access denied.';
  end if;

  select jsonb_build_object(
    'hotel_id', p_hotel_id,
    'user_id', v_user_id,
    'unread_count', (
      select count(*)
      from public.notification_recipients nr
      where nr.hotel_id = p_hotel_id
        and nr.user_id = v_user_id
        and nr.status = 'unread'
    ),
    'items', coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', source.id,
          'outbox_id', source.outbox_id,
          'event_key', source.event_key,
          'source_type', source.source_type,
          'source_id', source.source_id,
          'title', source.title,
          'message', source.message,
          'severity', source.severity,
          'status', source.status,
          'business_date', source.business_date,
          'read_at', source.read_at,
          'created_at', source.created_at,
          'metadata', source.metadata
        )
        order by source.created_at desc
      ),
      '[]'::jsonb
    )
  )
  into v_result
  from (
    select
      nr.id,
      nr.outbox_id,
      nox.event_key,
      nox.source_type,
      nox.source_id,
      nr.title,
      nr.message,
      nr.severity,
      nr.status,
      nox.business_date,
      nr.read_at,
      nr.created_at,
      nr.metadata
    from public.notification_recipients nr
    join public.notification_outbox nox
      on nox.id = nr.outbox_id
     and nox.hotel_id = nr.hotel_id
    where nr.hotel_id = p_hotel_id
      and nr.user_id = v_user_id
      and (p_before is null or nr.created_at < p_before)
    order by nr.created_at desc
    limit greatest(1, least(coalesce(p_limit, 50), 200))
  ) source;

  return coalesce(
    v_result,
    jsonb_build_object(
      'hotel_id', p_hotel_id,
      'user_id', v_user_id,
      'unread_count', 0,
      'items', '[]'::jsonb
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_notification_inbox"("p_hotel_id" "uuid", "p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_diagnostics"("p_hotel_id" "uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50, "p_status" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_to timestamptz := coalesce(p_to, now());
  v_from timestamptz := coalesce(
    p_from,
    coalesce(p_to, now()) - interval '7 days'
  );
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_status text := nullif(lower(trim(p_status)), '');
  v_severity text := nullif(lower(trim(p_severity)), '');
  v_source text := nullif(lower(trim(p_source)), '');
  v_search text := nullif(lower(trim(p_search)), '');
  v_items jsonb;
  v_summary jsonb;
  v_health jsonb;
begin
  if p_hotel_id is null
     or not private.day17_can_manage_hotel(p_hotel_id)
  then
    raise exception 'Hotel management access required.'
      using errcode = '42501';
  end if;

  if v_from > v_to then
    raise exception 'Diagnostic start must be before end.'
      using errcode = '22007';
  end if;

  if v_to - v_from > interval '31 days' then
    v_from := v_to - interval '31 days';
  end if;

  with visible as (
    select
      event.id,
      event.incident_id,
      event.source,
      event.environment,
      event.severity,
      event.status,
      event.event_name,
      event.error_name,
      event.error_code,
      event.message,
      event.route,
      event.scope,
      event.component,
      event.request_id,
      event.release,
      event.context,
      event.occurrence_count,
      event.first_seen_at,
      event.last_seen_at,
      event.acknowledged_at,
      event.resolved_at,
      event.resolution_note
    from public.operational_error_events event
    where event.hotel_id = p_hotel_id
      and event.last_seen_at between v_from and v_to
      and (v_status is null or event.status = v_status)
      and (v_severity is null or event.severity = v_severity)
      and (v_source is null or event.source = v_source)
      and (
        v_search is null
        or lower(event.incident_id) like '%' || v_search || '%'
        or lower(coalesce(event.request_id, '')) like '%' || v_search || '%'
        or lower(coalesce(event.error_code, '')) like '%' || v_search || '%'
        or lower(event.message) like '%' || v_search || '%'
      )
    order by event.last_seen_at desc, event.id desc
    limit v_limit
  )
  select coalesce(
    jsonb_agg(to_jsonb(visible) order by last_seen_at desc, id desc),
    '[]'::jsonb
  )
  into v_items
  from visible;

  select jsonb_build_object(
    'total_in_window', count(*),
    'open_count', count(*) filter (where status = 'open'),
    'acknowledged_count', count(*) filter (where status = 'acknowledged'),
    'resolved_count', count(*) filter (where status = 'resolved'),
    'ignored_count', count(*) filter (where status = 'ignored'),
    'critical_count', count(*) filter (where severity = 'critical'),
    'error_count', count(*) filter (where severity = 'error'),
    'warning_count', count(*) filter (where severity = 'warning')
  )
  into v_summary
  from public.operational_error_events event
  where event.hotel_id = p_hotel_id
    and event.last_seen_at between v_from and v_to
    and (v_status is null or event.status = v_status)
    and (v_severity is null or event.severity = v_severity)
    and (v_source is null or event.source = v_source)
    and (
      v_search is null
      or lower(event.incident_id) like '%' || v_search || '%'
      or lower(coalesce(event.request_id, '')) like '%' || v_search || '%'
      or lower(coalesce(event.error_code, '')) like '%' || v_search || '%'
      or lower(event.message) like '%' || v_search || '%'
    );

  v_health := public.get_operational_health_snapshot(p_hotel_id);

  return jsonb_build_object(
    'captured_at', now(),
    'hotel_id', p_hotel_id,
    'health_status', v_health ->> 'status',
    'window', jsonb_build_object(
      'from', v_from,
      'to', v_to,
      'limit', v_limit
    ),
    'summary', v_summary,
    'items', v_items,
    'query_health', v_health -> 'query_health',
    'delivery_health', v_health -> 'delivery_health'
  );
end;
$$;


ALTER FUNCTION "public"."get_operational_diagnostics"("p_hotel_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer, "p_status" "text", "p_severity" "text", "p_source" "text", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_health_snapshot"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_query_health jsonb;
  v_unresolved_24h bigint;
  v_critical_24h bigint;
  v_failed_deliveries bigint;
  v_retrying_deliveries bigint;
  v_last_event_at timestamptz;
  v_status text;
begin
  if p_hotel_id is null
     or not private.day17_can_manage_hotel(p_hotel_id)
  then
    raise exception 'Hotel management access required.'
      using errcode = '42501';
  end if;

  v_query_health := public.get_day18_query_health(p_hotel_id);

  select
    count(*) filter (
      where status in ('open', 'acknowledged')
    ),
    count(*) filter (
      where severity = 'critical'
        and status in ('open', 'acknowledged')
    ),
    max(last_seen_at)
  into
    v_unresolved_24h,
    v_critical_24h,
    v_last_event_at
  from public.operational_error_events
  where hotel_id = p_hotel_id
    and last_seen_at >= now() - interval '24 hours';

  select
    count(*) filter (where status = 'failed'),
    count(*) filter (where status = 'retrying')
  into
    v_failed_deliveries,
    v_retrying_deliveries
  from public.notification_deliveries
  where hotel_id = p_hotel_id
    and created_at >= now() - interval '24 hours';

  v_status := case
    when coalesce((v_query_health ->> 'invalid_index_count')::integer, 0) > 0
      or v_critical_24h > 0
    then 'critical'
    when v_unresolved_24h > 0
      or v_failed_deliveries > 0
      or v_retrying_deliveries > 0
    then 'degraded'
    else 'healthy'
  end;

  return jsonb_build_object(
    'captured_at', now(),
    'hotel_id', p_hotel_id,
    'status', v_status,
    'unresolved_24h', v_unresolved_24h,
    'critical_24h', v_critical_24h,
    'last_event_at', v_last_event_at,
    'query_health', v_query_health,
    'delivery_health', jsonb_build_object(
      'failed_24h', v_failed_deliveries,
      'retrying_24h', v_retrying_deliveries
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_operational_health_snapshot"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rate_quote"("target_hotel_id" "uuid", "target_rate_plan_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date") RETURNS TABLE("stay_date" "date", "rate_plan_id" "uuid", "room_type_id" "uuid", "currency_code" "text", "nightly_rate" numeric, "extra_adult_rate" numeric, "extra_child_rate" numeric, "rate_source" "text", "seasonal_rate_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception 'Hotel access denied.';
  end if;

  if target_arrival_date is null
     or target_departure_date is null
     or target_departure_date <= target_arrival_date
  then
    raise exception
      'Departure date must be after arrival date.';
  end if;

  if target_departure_date - target_arrival_date > 365 then
    raise exception
      'Rate quotes are limited to 365 nights.';
  end if;

  if not exists (
    select 1
    from public.rate_plans rp
    where rp.id = target_rate_plan_id
      and rp.hotel_id = target_hotel_id
      and rp.is_active
  ) then
    raise exception
      'Active rate plan not found for this hotel.';
  end if;

  return query
  select
    nights.stay_date,
    rp.id,
    rp.room_type_id,
    rp.currency_code,
    coalesce(sr.nightly_rate, rp.base_rate)::numeric,
    coalesce(sr.extra_adult_rate, rp.extra_adult_rate)::numeric,
    coalesce(sr.extra_child_rate, rp.extra_child_rate)::numeric,
    case
      when sr.id is null then 'base'
      else 'seasonal'
    end,
    sr.id
  from (
    select generate_series(
      target_arrival_date,
      target_departure_date - 1,
      interval '1 day'
    )::date as stay_date
  ) nights
  join public.rate_plans rp
    on rp.id = target_rate_plan_id
   and rp.hotel_id = target_hotel_id
   and rp.is_active
  left join lateral (
    select candidate.*
    from public.seasonal_rates candidate
    where candidate.hotel_id = rp.hotel_id
      and candidate.rate_plan_id = rp.id
      and candidate.is_active
      and nights.stay_date >= candidate.start_date
      and nights.stay_date < candidate.end_date
      and (
        candidate.days_of_week is null
        or extract(dow from nights.stay_date)::smallint =
          any(candidate.days_of_week)
      )
    order by candidate.priority asc, candidate.created_at desc
    limit 1
  ) sr on true
  order by nights.stay_date;
end;
$$;


ALTER FUNCTION "public"."get_rate_quote"("target_hotel_id" "uuid", "target_rate_plan_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_arrivals_departures"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with expected_arrivals as (
    select jsonb_build_object(
      'reservation_id', r.id,
      'reservation_number', r.reservation_number,
      'guest_name', g.full_name,
      'date', r.arrival_date,
      'status', r.status,
      'booking_source', r.booking_source
    ) as item
    from public.reservations r
    left join public.guests g
      on g.hotel_id = r.hotel_id
     and g.id = r.primary_guest_id
    where r.hotel_id = p_hotel_id
      and r.arrival_date between p_date_from and p_date_to
      and r.status not in ('cancelled', 'no_show')
  ),
  expected_departures as (
    select jsonb_build_object(
      'reservation_id', r.id,
      'reservation_number', r.reservation_number,
      'guest_name', g.full_name,
      'date', r.departure_date,
      'status', r.status,
      'booking_source', r.booking_source
    ) as item
    from public.reservations r
    left join public.guests g
      on g.hotel_id = r.hotel_id
     and g.id = r.primary_guest_id
    where r.hotel_id = p_hotel_id
      and r.departure_date between p_date_from and p_date_to
      and r.status not in ('cancelled', 'no_show')
  ),
  actual_arrivals as (
    select jsonb_build_object(
      'guest_session_id', gs.id,
      'guest_name', g.full_name,
      'room_number', room_row.room_number,
      'checkin_time', gs.checkin_time,
      'status', gs.status
    ) as item
    from public.guest_sessions gs
    join public.guests g
      on g.hotel_id = gs.hotel_id
     and g.id = gs.guest_id
    left join public.rooms room_row
      on room_row.hotel_id = gs.hotel_id
     and room_row.id = gs.room_id
    where gs.hotel_id = p_hotel_id
      and (gs.checkin_time at time zone v_timezone)::date
        between p_date_from and p_date_to
  ),
  actual_departures as (
    select jsonb_build_object(
      'guest_session_id', gs.id,
      'guest_name', g.full_name,
      'room_number', room_row.room_number,
      'checkout_time', gs.checkout_time,
      'status', gs.status
    ) as item
    from public.guest_sessions gs
    join public.guests g
      on g.hotel_id = gs.hotel_id
     and g.id = gs.guest_id
    left join public.rooms room_row
      on room_row.hotel_id = gs.hotel_id
     and room_row.id = gs.room_id
    where gs.hotel_id = p_hotel_id
      and gs.checkout_time is not null
      and (gs.checkout_time at time zone v_timezone)::date
        between p_date_from and p_date_to
      and gs.status = 'completed'
  )
  select jsonb_build_object(
    'expected_arrivals',
      coalesce(
        (select jsonb_agg(item order by item ->> 'date')
         from expected_arrivals),
        '[]'::jsonb
      ),
    'expected_departures',
      coalesce(
        (select jsonb_agg(item order by item ->> 'date')
         from expected_departures),
        '[]'::jsonb
      ),
    'actual_arrivals',
      coalesce(
        (select jsonb_agg(item order by item ->> 'checkin_time')
         from actual_arrivals),
        '[]'::jsonb
      ),
    'actual_departures',
      coalesce(
        (select jsonb_agg(item order by item ->> 'checkout_time')
         from actual_departures),
        '[]'::jsonb
      )
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_arrivals_departures"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_export_rows"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_report_key" "text", "p_filters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_key text;
  v_rows jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  v_key := lower(trim(coalesce(p_report_key, '')));

  if jsonb_typeof(coalesce(p_filters, '{}'::jsonb)) <> 'object' then
    raise exception 'Export filters must be a JSON object.';
  end if;

  case v_key
    when 'occupancy_daily' then
      v_rows := public.get_report_occupancy_daily(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'revenue_daily' then
      v_rows := public.get_report_revenue_daily(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'revenue_by_category' then
      v_rows := public.get_report_revenue_by_category(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'reservations_by_source' then
      v_rows := public.get_report_reservations_by_source(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'arrivals_departures' then
      v_rows := public.get_report_arrivals_departures(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'payments_by_method' then
      v_rows := public.get_report_payments_by_method(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'tax_gst_summary' then
      v_rows := public.get_report_tax_gst_summary(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'guest_food_service' then
      v_rows := public.get_report_guest_food_service(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'service_sla' then
      v_rows := public.get_report_service_sla(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'housekeeping' then
      v_rows := public.get_report_housekeeping(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    when 'staff_department' then
      v_rows := public.get_report_staff_department(
        p_hotel_id,
        p_date_from,
        p_date_to
      );
    else
      raise exception
        'Unsupported report key: %',
        coalesce(p_report_key, '<null>');
  end case;

  return jsonb_build_object(
    'hotel_id', p_hotel_id,
    'date_from', p_date_from,
    'date_to', p_date_to,
    'timezone', v_timezone,
    'report_key', v_key,
    'filters', coalesce(p_filters, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_report_export_rows"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_report_key" "text", "p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_filter_options"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone := private.day16_assert_filter_access(p_hotel_id);

  select jsonb_build_object(
    'timezone', v_timezone,
    'booking_sources',
      coalesce(
        (
          select jsonb_agg(source_value order by source_value)
          from (
            select distinct r.booking_source as source_value
            from public.reservations r
            where r.hotel_id = p_hotel_id
          ) source_rows
        ),
        '[]'::jsonb
      ),
    'departments',
      coalesce(
        (
          select jsonb_agg(department_value order by department_value)
          from (
            select distinct sr.department as department_value
            from public.service_requests sr
            where sr.hotel_id = p_hotel_id
              and sr.department is not null
          ) department_rows
        ),
        '[]'::jsonb
      ),
    'payment_methods',
      coalesce(
        (
          select jsonb_agg(method_value order by method_value)
          from (
            select distinct fc.payment_method as method_value
            from public.folio_collections fc
            where fc.hotel_id = p_hotel_id
          ) payment_rows
        ),
        '[]'::jsonb
      ),
    'rooms',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', room_row.id,
              'room_number', room_row.room_number,
              'status', room_row.status
            )
            order by room_row.room_number
          )
          from public.rooms room_row
          where room_row.hotel_id = p_hotel_id
        ),
        '[]'::jsonb
      ),
    'room_types',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', rt.id,
              'name', rt.name
            )
            order by rt.name
          )
          from public.room_types rt
          where rt.hotel_id = p_hotel_id
        ),
        '[]'::jsonb
      ),
    'staff',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', s.id,
              'full_name', s.full_name,
              'role', s.role,
              'status', s.status
            )
            order by s.full_name
          )
          from public.staff s
          where s.hotel_id = p_hotel_id
        ),
        '[]'::jsonb
      )
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_filter_options"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_guest_food_service"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with stay_rows as (
    select gs.*
    from public.guest_sessions gs
    where gs.hotel_id = p_hotel_id
      and (gs.checkin_time at time zone v_timezone)::date
        between p_date_from and p_date_to
  ),
  repeat_guests as (
    select stay_rows.guest_id
    from stay_rows
    group by stay_rows.guest_id
    having count(*) > 1
  ),
  food_rows as (
    select fo.*
    from public.food_orders fo
    where fo.hotel_id = p_hotel_id
      and (fo.created_at at time zone v_timezone)::date
        between p_date_from and p_date_to
  ),
  service_rows as (
    select sr.*
    from public.service_requests sr
    where sr.hotel_id = p_hotel_id
      and (sr.created_at at time zone v_timezone)::date
        between p_date_from and p_date_to
  )
  select jsonb_build_object(
    'stay_count', (select count(*)::integer from stay_rows),
    'unique_guests',
      (select count(distinct guest_id)::integer from stay_rows),
    'repeat_guests',
      (select count(*)::integer from repeat_guests),
    'active_stays',
      (
        select count(*)::integer
        from stay_rows
        where status = 'active'
      ),
    'completed_stays',
      (
        select count(*)::integer
        from stay_rows
        where status = 'completed'
      ),
    'food_orders',
      (select count(*)::integer from food_rows),
    'delivered_food_orders',
      (
        select count(*)::integer
        from food_rows
        where order_status = 'delivered'
      ),
    'cancelled_food_orders',
      (
        select count(*)::integer
        from food_rows
        where order_status = 'cancelled'
      ),
    'delivered_food_revenue',
      (
        select coalesce(sum(total_amount), 0)::numeric(14,2)
        from food_rows
        where order_status = 'delivered'
      ),
    'service_requests',
      (select count(*)::integer from service_rows),
    'completed_service_requests',
      (
        select count(*)::integer
        from service_rows
        where status = 'completed'
      ),
    'cancelled_service_requests',
      (
        select count(*)::integer
        from service_rows
        where status = 'cancelled'
      )
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_guest_food_service"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_housekeeping"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with status_rows as (
    select
      hk.status,
      count(*)::integer as task_count
    from public.housekeeping_tasks hk
    where hk.hotel_id = p_hotel_id
      and (hk.created_at at time zone v_timezone)::date
        between p_date_from and p_date_to
    group by hk.status
  ),
  totals as (
    select
      count(*)::integer as total_tasks,
      count(*) filter (
        where hk.status in ('room_ready', 'completed')
      )::integer as completed_tasks,
      count(*) filter (
        where hk.due_at is not null
          and hk.due_at < now()
          and hk.status not in (
            'room_ready',
            'completed',
            'cancelled'
          )
      )::integer as overdue_tasks,
      round(
        coalesce(
          avg(
            extract(
              epoch from (
                hk.room_ready_at - hk.created_at
              )
            ) / 60.0
          ) filter (
            where hk.room_ready_at is not null
          ),
          0
        )::numeric,
        2
      ) as average_turnaround_minutes
    from public.housekeeping_tasks hk
    where hk.hotel_id = p_hotel_id
      and (hk.created_at at time zone v_timezone)::date
        between p_date_from and p_date_to
  )
  select jsonb_build_object(
    'summary',
      (
        select jsonb_build_object(
          'total_tasks', totals.total_tasks,
          'completed_tasks', totals.completed_tasks,
          'overdue_tasks', totals.overdue_tasks,
          'average_turnaround_minutes',
            totals.average_turnaround_minutes
        )
        from totals
      ),
    'by_status',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'status', status_rows.status,
              'task_count', status_rows.task_count
            )
            order by status_rows.task_count desc,
              status_rows.status
          )
          from status_rows
        ),
        '[]'::jsonb
      )
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_housekeeping"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_kpi_summary"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with room_nights as (
    select
      coalesce(
        sum(
          (day_item ->> 'available_room_nights')::numeric
        ),
        0
      ) as available_room_nights,
      coalesce(
        sum(
          (day_item ->> 'sold_room_nights')::numeric
        ),
        0
      ) as sold_room_nights,
      coalesce(
        sum(
          (day_item ->> 'occupied_room_nights')::numeric
        ),
        0
      ) as occupied_room_nights,
      coalesce(
        sum(
          (day_item ->> 'blocked_room_nights')::numeric
        ),
        0
      ) as blocked_room_nights
    from jsonb_array_elements(
      public.get_report_occupancy_daily(
        p_hotel_id,
        p_date_from,
        p_date_to
      )
    ) day_item
  ),
  revenue as (
    select
      coalesce(
        sum(fi.amount) filter (
          where fi.item_kind = 'charge'
            and fi.charge_category = 'room'
        ),
        0
      )::numeric(14,2) as room_revenue,
      coalesce(
        sum(fi.amount) filter (
          where fi.item_kind = 'charge'
            and fi.charge_category = 'food'
        ),
        0
      )::numeric(14,2) as food_revenue,
      coalesce(
        sum(fi.amount) filter (
          where fi.item_kind = 'charge'
            and fi.charge_category = 'service'
        ),
        0
      )::numeric(14,2) as service_revenue,
      coalesce(
        sum(fi.amount) filter (
          where fi.item_kind = 'charge'
            and fi.charge_category in ('manual', 'other')
        ),
        0
      )::numeric(14,2) as other_revenue,
      coalesce(
        sum(fi.amount) filter (
          where fi.item_kind = 'tax'
        ),
        0
      )::numeric(14,2) as tax_revenue
    from public.folio_items fi
    where fi.hotel_id = p_hotel_id
      and fi.posting_status = 'posted'
      and (fi.service_at at time zone v_timezone)::date
        between p_date_from and p_date_to
  ),
  collections as (
    select
      coalesce(
        sum(fc.amount) filter (
          where fc.status = 'posted'
        ),
        0
      )::numeric(14,2) as collection_amount
    from public.folio_collections fc
    where fc.hotel_id = p_hotel_id
      and (fc.collected_at at time zone v_timezone)::date
        between p_date_from and p_date_to
  )
  select jsonb_build_object(
    'date_from', p_date_from,
    'date_to', p_date_to,
    'timezone', v_timezone,
    'available_room_nights', room_nights.available_room_nights,
    'sold_room_nights', room_nights.sold_room_nights,
    'occupied_room_nights', room_nights.occupied_room_nights,
    'blocked_room_nights', room_nights.blocked_room_nights,
    'occupancy_rate',
      case
        when room_nights.available_room_nights = 0 then 0
        else round(
          (
            room_nights.occupied_room_nights
            / room_nights.available_room_nights
          ) * 100,
          2
        )
      end,
    'adr',
      case
        when room_nights.occupied_room_nights = 0 then 0
        else round(
          revenue.room_revenue
          / room_nights.occupied_room_nights,
          2
        )
      end,
    'arr',
      case
        when room_nights.occupied_room_nights = 0 then 0
        else round(
          revenue.room_revenue
          / room_nights.occupied_room_nights,
          2
        )
      end,
    'revpar',
      case
        when room_nights.available_room_nights = 0 then 0
        else round(
          revenue.room_revenue
          / room_nights.available_room_nights,
          2
        )
      end,
    'room_revenue', revenue.room_revenue,
    'food_revenue', revenue.food_revenue,
    'service_revenue', revenue.service_revenue,
    'other_revenue', revenue.other_revenue,
    'tax_revenue', revenue.tax_revenue,
    'gross_revenue',
      revenue.room_revenue
      + revenue.food_revenue
      + revenue.service_revenue
      + revenue.other_revenue
      + revenue.tax_revenue,
    'collections', collections.collection_amount,
    'reservation_count',
      (
        select count(*)::integer
        from public.reservations r
        where r.hotel_id = p_hotel_id
          and r.arrival_date between p_date_from and p_date_to
      ),
    'arrival_count',
      (
        select count(*)::integer
        from public.guest_sessions gs
        where gs.hotel_id = p_hotel_id
          and (gs.checkin_time at time zone v_timezone)::date
            between p_date_from and p_date_to
      ),
    'departure_count',
      (
        select count(*)::integer
        from public.guest_sessions gs
        where gs.hotel_id = p_hotel_id
          and gs.checkout_time is not null
          and gs.status = 'completed'
          and (gs.checkout_time at time zone v_timezone)::date
            between p_date_from and p_date_to
      ),
    'food_order_count',
      (
        select count(*)::integer
        from public.food_orders fo
        where fo.hotel_id = p_hotel_id
          and (fo.created_at at time zone v_timezone)::date
            between p_date_from and p_date_to
      ),
    'service_request_count',
      (
        select count(*)::integer
        from public.service_requests sr
        where sr.hotel_id = p_hotel_id
          and (sr.created_at at time zone v_timezone)::date
            between p_date_from and p_date_to
      )
  )
  into v_result
  from room_nights
  cross join revenue
  cross join collections;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_kpi_summary"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_occupancy_daily"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with report_days as (
    select day_value::date as report_date
    from generate_series(
      p_date_from::timestamp,
      p_date_to::timestamp,
      interval '1 day'
    ) day_value
  ),
  room_count as (
    select count(*)::integer as total_rooms
    from public.rooms r
    where r.hotel_id = p_hotel_id
  ),
  blocked as (
    select distinct
      allocation.room_id,
      day_value::date as report_date
    from public.room_inventory_allocations allocation
    cross join lateral generate_series(
      greatest(allocation.starts_on, p_date_from)::timestamp,
      least(allocation.ends_on - 1, p_date_to)::timestamp,
      interval '1 day'
    ) day_value
    where allocation.hotel_id = p_hotel_id
      and allocation.allocation_type = 'block'
      and allocation.status <> 'cancelled'
      and allocation.starts_on <= p_date_to
      and allocation.ends_on > p_date_from
  ),
  sold as (
    select distinct
      allocation.room_id,
      day_value::date as report_date
    from public.room_inventory_allocations allocation
    cross join lateral generate_series(
      greatest(allocation.starts_on, p_date_from)::timestamp,
      least(allocation.ends_on - 1, p_date_to)::timestamp,
      interval '1 day'
    ) day_value
    where allocation.hotel_id = p_hotel_id
      and allocation.allocation_type in ('reservation', 'stay')
      and allocation.status <> 'cancelled'
      and allocation.starts_on <= p_date_to
      and allocation.ends_on > p_date_from
  ),
  occupied as (
    select distinct
      allocation.room_id,
      day_value::date as report_date
    from public.room_inventory_allocations allocation
    cross join lateral generate_series(
      greatest(allocation.starts_on, p_date_from)::timestamp,
      least(allocation.ends_on - 1, p_date_to)::timestamp,
      interval '1 day'
    ) day_value
    where allocation.hotel_id = p_hotel_id
      and allocation.allocation_type = 'stay'
      and allocation.status <> 'cancelled'
      and allocation.starts_on <= p_date_to
      and allocation.ends_on > p_date_from
  ),
  daily as (
    select
      report_days.report_date,
      room_count.total_rooms,
      count(distinct blocked.room_id)::integer as blocked_room_nights,
      count(distinct sold.room_id)::integer as sold_room_nights,
      count(distinct occupied.room_id)::integer as occupied_room_nights
    from report_days
    cross join room_count
    left join blocked
      on blocked.report_date = report_days.report_date
    left join sold
      on sold.report_date = report_days.report_date
    left join occupied
      on occupied.report_date = report_days.report_date
    group by report_days.report_date, room_count.total_rooms
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'date', daily.report_date,
        'total_rooms', daily.total_rooms,
        'blocked_room_nights', daily.blocked_room_nights,
        'available_room_nights',
          greatest(daily.total_rooms - daily.blocked_room_nights, 0),
        'sold_room_nights', daily.sold_room_nights,
        'occupied_room_nights', daily.occupied_room_nights,
        'occupancy_rate',
          case
            when greatest(
              daily.total_rooms - daily.blocked_room_nights,
              0
            ) = 0 then 0
            else round(
              (
                daily.occupied_room_nights::numeric
                / greatest(
                    daily.total_rooms - daily.blocked_room_nights,
                    1
                  )
              ) * 100,
              2
            )
          end
      )
      order by daily.report_date
    ),
    '[]'::jsonb
  )
  into v_result
  from daily;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_occupancy_daily"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_payments_by_method"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with method_rows as (
    select
      fc.payment_method,
      count(*) filter (
        where fc.status = 'posted'
      )::integer as posted_count,
      coalesce(
        sum(fc.amount) filter (
          where fc.status = 'posted'
        ),
        0
      )::numeric(14,2) as posted_amount,
      count(*) filter (
        where fc.status in ('voided', 'reversed')
      )::integer as reversed_count,
      coalesce(
        sum(fc.amount) filter (
          where fc.status in ('voided', 'reversed')
        ),
        0
      )::numeric(14,2) as reversed_amount
    from public.folio_collections fc
    where fc.hotel_id = p_hotel_id
      and (fc.collected_at at time zone v_timezone)::date
        between p_date_from and p_date_to
    group by fc.payment_method
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'payment_method', method_rows.payment_method,
        'posted_count', method_rows.posted_count,
        'posted_amount', method_rows.posted_amount,
        'reversed_count', method_rows.reversed_count,
        'reversed_amount', method_rows.reversed_amount
      )
      order by method_rows.posted_amount desc,
        method_rows.payment_method
    ),
    '[]'::jsonb
  )
  into v_result
  from method_rows;

  return v_result;
end;
$$;


