CREATE OR REPLACE FUNCTION "public"."get_report_revenue_daily"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with report_days as (
    select day_value::date as report_date
    from generate_series(
      p_date_from::timestamp,
      p_date_to::timestamp,
      interval '1 day'
    ) day_value
  ),
  charges as (
    select
      (fi.service_at at time zone v_timezone)::date as report_date,
      coalesce(
        sum(fi.amount) filter (
          where fi.item_kind = 'charge'
        ),
        0
      )::numeric(14,2) as charge_revenue,
      coalesce(
        sum(fi.amount) filter (
          where fi.item_kind = 'tax'
        ),
        0
      )::numeric(14,2) as tax_revenue
    from public.folio_items fi
    where fi.hotel_id = p_hotel_id
      and fi.posting_status = 'posted'
      and (fi.service_at at time zone v_timezone)::date
        between p_date_from and p_date_to
    group by (fi.service_at at time zone v_timezone)::date
  ),
  collections as (
    select
      (fc.collected_at at time zone v_timezone)::date as report_date,
      coalesce(
        sum(fc.amount) filter (
          where fc.status = 'posted'
        ),
        0
      )::numeric(14,2) as collections,
      coalesce(
        sum(fc.amount) filter (
          where fc.status in ('voided', 'reversed')
        ),
        0
      )::numeric(14,2) as reversed_or_voided
    from public.folio_collections fc
    where fc.hotel_id = p_hotel_id
      and (fc.collected_at at time zone v_timezone)::date
        between p_date_from and p_date_to
    group by (fc.collected_at at time zone v_timezone)::date
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'date', report_days.report_date,
        'charge_revenue', coalesce(charges.charge_revenue, 0),
        'tax_revenue', coalesce(charges.tax_revenue, 0),
        'gross_revenue',
          coalesce(charges.charge_revenue, 0)
          + coalesce(charges.tax_revenue, 0),
        'collections', coalesce(collections.collections, 0),
        'reversed_or_voided_collections',
          coalesce(collections.reversed_or_voided, 0)
      )
      order by report_days.report_date
    ),
    '[]'::jsonb
  )
  into v_result
  from report_days
  left join charges
    on charges.report_date = report_days.report_date
  left join collections
    on collections.report_date = report_days.report_date;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_revenue_daily"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_service_sla"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with department_rows as (
    select
      sr.department,
      count(*)::integer as request_count,
      count(*) filter (
        where sr.status = 'completed'
      )::integer as completed_count,
      count(*) filter (
        where sr.status = 'cancelled'
      )::integer as cancelled_count,
      count(*) filter (
        where sr.status in (
          'pending',
          'accepted',
          'in_progress',
          'escalated'
        )
          and sr.sla_due_at < now()
      )::integer as currently_overdue_count,
      count(*) filter (
        where sr.status = 'completed'
          and sr.completed_at <= sr.sla_due_at
      )::integer as completed_within_sla,
      round(
        coalesce(
          avg(
            extract(
              epoch from (
                sr.accepted_at - sr.created_at
              )
            ) / 60.0
          ) filter (
            where sr.accepted_at is not null
          ),
          0
        )::numeric,
        2
      ) as average_accept_minutes,
      round(
        coalesce(
          avg(
            extract(
              epoch from (
                sr.completed_at - sr.created_at
              )
            ) / 60.0
          ) filter (
            where sr.completed_at is not null
          ),
          0
        )::numeric,
        2
      ) as average_complete_minutes
    from public.service_requests sr
    where sr.hotel_id = p_hotel_id
      and (sr.created_at at time zone v_timezone)::date
        between p_date_from and p_date_to
    group by sr.department
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'department', department_rows.department,
        'request_count', department_rows.request_count,
        'completed_count', department_rows.completed_count,
        'cancelled_count', department_rows.cancelled_count,
        'currently_overdue_count',
          department_rows.currently_overdue_count,
        'completed_within_sla',
          department_rows.completed_within_sla,
        'sla_met_rate',
          case
            when department_rows.completed_count = 0 then 0
            else round(
              (
                department_rows.completed_within_sla::numeric
                / department_rows.completed_count
              ) * 100,
              2
            )
          end,
        'average_accept_minutes',
          department_rows.average_accept_minutes,
        'average_complete_minutes',
          department_rows.average_complete_minutes
      )
      order by department_rows.request_count desc,
        department_rows.department
    ),
    '[]'::jsonb
  )
  into v_result
  from department_rows;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_service_sla"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_staff_department"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  with service_work as (
    select
      sr.assigned_staff_id as staff_id,
      count(*)::integer as assigned_count,
      count(*) filter (
        where sr.status = 'completed'
      )::integer as completed_count,
      array_remove(
        array_agg(distinct sr.department),
        null
      ) as departments
    from public.service_requests sr
    where sr.hotel_id = p_hotel_id
      and (sr.created_at at time zone v_timezone)::date
        between p_date_from and p_date_to
      and sr.assigned_staff_id is not null
    group by sr.assigned_staff_id
  ),
  housekeeping_work as (
    select
      hk.assigned_staff_id as staff_id,
      count(*)::integer as assigned_count,
      count(*) filter (
        where hk.status in ('room_ready', 'completed')
      )::integer as completed_count
    from public.housekeeping_tasks hk
    where hk.hotel_id = p_hotel_id
      and (hk.created_at at time zone v_timezone)::date
        between p_date_from and p_date_to
      and hk.assigned_staff_id is not null
    group by hk.assigned_staff_id
  ),
  maintenance_work as (
    select
      mt.assigned_staff_id as staff_id,
      count(*)::integer as assigned_count,
      count(*) filter (
        where mt.status in ('resolved', 'verified')
      )::integer as completed_count
    from public.maintenance_tasks mt
    where mt.hotel_id = p_hotel_id
      and (mt.created_at at time zone v_timezone)::date
        between p_date_from and p_date_to
      and mt.assigned_staff_id is not null
    group by mt.assigned_staff_id
  ),
  staff_rows as (
    select
      s.id,
      s.full_name,
      s.role,
      s.status,
      coalesce(service_work.assigned_count, 0)
        + coalesce(housekeeping_work.assigned_count, 0)
        + coalesce(maintenance_work.assigned_count, 0)
        as assigned_count,
      coalesce(service_work.completed_count, 0)
        + coalesce(housekeeping_work.completed_count, 0)
        + coalesce(maintenance_work.completed_count, 0)
        as completed_count,
      coalesce(service_work.departments, array[]::text[])
        || case
             when coalesce(housekeeping_work.assigned_count, 0) > 0
               then array['housekeeping']
             else array[]::text[]
           end
        || case
             when coalesce(maintenance_work.assigned_count, 0) > 0
               then array['maintenance']
             else array[]::text[]
           end
        as work_departments
    from public.staff s
    left join service_work
      on service_work.staff_id = s.id
    left join housekeeping_work
      on housekeeping_work.staff_id = s.id
    left join maintenance_work
      on maintenance_work.staff_id = s.id
    where s.hotel_id = p_hotel_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'staff_id', staff_rows.id,
        'full_name', staff_rows.full_name,
        'role', staff_rows.role,
        'status', staff_rows.status,
        'work_departments',
          to_jsonb(staff_rows.work_departments),
        'assigned_count', staff_rows.assigned_count,
        'completed_count', staff_rows.completed_count,
        'completion_rate',
          case
            when staff_rows.assigned_count = 0 then 0
            else round(
              (
                staff_rows.completed_count::numeric
                / staff_rows.assigned_count
              ) * 100,
              2
            )
          end
      )
      order by staff_rows.assigned_count desc,
        staff_rows.full_name
    ),
    '[]'::jsonb
  )
  into v_result
  from staff_rows;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_staff_department"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_tax_gst_summary"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_result jsonb;
begin
  v_timezone :=
    private.day16_assert_report_access(
      p_hotel_id,
      p_date_from,
      p_date_to
    );

  select jsonb_build_object(
    'invoice_count', count(*)::integer,
    'taxable_amount',
      coalesce(sum(i.taxable_amount), 0)::numeric(14,2),
    'cgst_amount',
      coalesce(sum(i.cgst_amount), 0)::numeric(14,2),
    'sgst_amount',
      coalesce(sum(i.sgst_amount), 0)::numeric(14,2),
    'igst_amount',
      coalesce(sum(i.igst_amount), 0)::numeric(14,2),
    'cess_amount',
      coalesce(sum(i.cess_amount), 0)::numeric(14,2),
    'total_tax',
      coalesce(
        sum(
          i.cgst_amount
          + i.sgst_amount
          + i.igst_amount
          + i.cess_amount
        ),
        0
      )::numeric(14,2),
    'invoice_total',
      coalesce(sum(i.total_amount), 0)::numeric(14,2),
    'invoice_line_count',
      (
        select count(*)::integer
        from public.invoice_items item_row
        join public.invoices invoice_row
          on invoice_row.hotel_id = item_row.hotel_id
         and invoice_row.id = item_row.invoice_id
        where invoice_row.hotel_id = p_hotel_id
          and invoice_row.invoice_date
            between p_date_from and p_date_to
          and invoice_row.invoice_status in ('issued', 'paid')
      )
  )
  into v_result
  from public.invoices i
  where i.hotel_id = p_hotel_id
    and i.invoice_date between p_date_from and p_date_to
    and i.invoice_status in ('issued', 'paid');

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_report_tax_gst_summary"("p_hotel_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reservation_available_rooms"("target_hotel_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date", "target_room_type_id" "uuid" DEFAULT NULL::"uuid", "exclude_reservation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("room_id" "uuid", "room_number" "text", "room_type_id" "uuid", "room_type_name" "text", "room_status" "text", "max_adults" integer, "max_children" integer, "max_occupancy" integer, "standard_rate" numeric, "active_rate_plan_id" "uuid", "active_rate_plan_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_hotel_access(target_hotel_id) then raise exception 'Hotel access denied.'; end if;
  if target_arrival_date is null or target_departure_date is null or target_departure_date<=target_arrival_date
    then raise exception 'Departure date must be after arrival date.'; end if;
  if target_departure_date-target_arrival_date>365 then raise exception 'Availability searches are limited to 365 nights.'; end if;
  return query
  select r.id,r.room_number,t.id,t.name,r.status,t.max_adults,t.max_children,t.max_occupancy,
    coalesce(rp.base_rate,t.base_rate)::numeric,rp.id,rp.name
  from public.rooms r
  join public.floors f on f.id=r.floor_id and f.hotel_id=r.hotel_id and f.is_active
  join public.room_types t on t.id=r.room_type_id and t.hotel_id=r.hotel_id and t.is_active
  left join lateral(
    select p.* from public.rate_plans p where p.hotel_id=r.hotel_id and p.room_type_id=r.room_type_id and p.is_active
    order by p.priority,p.created_at limit 1
  ) rp on true
  join public.hotels h on h.id=r.hotel_id
  where r.hotel_id=target_hotel_id and r.is_active
    and (target_room_type_id is null or r.room_type_id=target_room_type_id)
    and r.status not in ('maintenance','out_of_order')
    and not(r.status='cleaning' and target_arrival_date<=(now() at time zone h.timezone)::date)
    and not exists(
      select 1 from public.room_inventory_allocations a
      where a.hotel_id=r.hotel_id and a.room_id=r.id and a.status='active'
        and a.stay_dates&&daterange(target_arrival_date,target_departure_date,'[)')
        and not(
          exclude_reservation_id is not null and a.allocation_type='reservation'
          and exists(select 1 from public.reservation_rooms x where x.id=a.reservation_room_id and x.hotel_id=target_hotel_id and x.reservation_id=exclude_reservation_id)
        )
    )
  order by t.sort_order,nullif(regexp_replace(r.room_number,'[^0-9]','','g'),'')::int nulls last,r.room_number;
end;
$$;


ALTER FUNCTION "public"."get_reservation_available_rooms"("target_hotel_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date", "target_room_type_id" "uuid", "exclude_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reservation_confirmation"("target_hotel_id" "uuid", "target_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  hotel_json jsonb;
  reservation_json jsonb;
  room_json jsonb;
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception 'Reservation confirmation access denied.';
  end if;

  select jsonb_build_object(
    'id', h.id,
    'hotel_name', h.hotel_name,
    'email', h.email,
    'phone', h.phone,
    'address', h.address,
    'city', h.city,
    'state', h.state,
    'location', h.location,
    'logo_url', h.logo_url,
    'website', h.website,
    'gst_number', h.gst_number,
    'currency_code', h.currency_code,
    'timezone', h.timezone,
    'invoice_terms', h.invoice_terms,
    'invoice_footer', h.invoice_footer
  ) into hotel_json
  from public.hotels h
  where h.id = target_hotel_id;

  if hotel_json is null then raise exception 'Hotel not found.'; end if;

  reservation_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  if reservation_json is null then raise exception 'Reservation not found.'; end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', rr.id,
        'room_type_id', rr.room_type_id,
        'room_type_name', rt.name,
        'room_id', rr.room_id,
        'room_number', room.room_number,
        'rate_plan_id', rr.rate_plan_id,
        'rate_plan_name', rp.name,
        'meal_plan', rp.meal_plan,
        'cancellation_policy', rp.cancellation_policy,
        'is_refundable', rp.is_refundable,
        'status', rr.status,
        'adults', rr.adults,
        'children', rr.children,
        'nightly_rate', rr.nightly_rate,
        'room_subtotal', rr.room_subtotal,
        'tax_amount', rr.tax_amount,
        'discount_amount', rr.discount_amount,
        'total_amount', rr.total_amount,
        'notes', rr.notes
      )
      order by rr.created_at
    ),
    '[]'::jsonb
  ) into room_json
  from public.reservation_rooms rr
  join public.room_types rt
    on rt.id = rr.room_type_id
   and rt.hotel_id = rr.hotel_id
  left join public.rooms room
    on room.id = rr.room_id
   and room.hotel_id = rr.hotel_id
  left join public.rate_plans rp
    on rp.id = rr.rate_plan_id
   and rp.hotel_id = rr.hotel_id
  where rr.hotel_id = target_hotel_id
    and rr.reservation_id = target_reservation_id;

  reservation_json := jsonb_set(
    reservation_json,
    '{rooms}',
    room_json,
    true
  );

  return jsonb_build_object(
    'generated_at', now(),
    'hotel', hotel_json,
    'reservation', reservation_json
  );
end;
$$;


ALTER FUNCTION "public"."get_reservation_confirmation"("target_hotel_id" "uuid", "target_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reservation_details"("target_hotel_id" "uuid", "target_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception 'Hotel access denied.';
  end if;

  result := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  if result is null then
    raise exception 'Reservation not found.';
  end if;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_reservation_details"("target_hotel_id" "uuid", "target_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reservation_operations"("target_hotel_id" "uuid", "target_date" "date" DEFAULT CURRENT_DATE, "upcoming_days" integer DEFAULT 7) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  hotel_timezone text;
  hotel_local_today date;
  as_of_at timestamptz;
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception
      'Reservation operations access denied.';
  end if;

  select hotel.timezone
  into hotel_timezone
  from public.hotels hotel
  where hotel.id = target_hotel_id;

  if hotel_timezone is null then
    raise exception
      'Hotel timezone was not found.';
  end if;

  hotel_local_today :=
    (now() at time zone hotel_timezone)::date;

  if target_date is null then
    target_date := hotel_local_today;
  end if;

  upcoming_days :=
    greatest(
      1,
      least(
        coalesce(upcoming_days, 7),
        31
      )
    );

  -- Current-date boards use the actual current instant. Historical boards use
  -- the selected hotel's local end of business date so their overdue labels
  -- remain deterministic rather than depending on the viewer's timezone.
  as_of_at :=
    case
      when target_date = hotel_local_today
      then now()
      else (
        target_date + time '23:59:59'
      ) at time zone hotel_timezone
    end;

  with reservation_rows as (
    select
      'reservation'::text as operation_source,
      false as is_walk_in,
      reservation.id as reservation_id,
      reservation.reservation_number::text
        as reservation_number,
      reservation.status::text
        as reservation_status,
      reservation.arrival_date,
      case
        when guest_session.status::text = 'active'
         and coalesce(
               guest_session.extended_until,
               guest_session.checkout_time
             ) is not null
        then (
          coalesce(
            guest_session.extended_until,
            guest_session.checkout_time
          ) at time zone hotel_timezone
        )::date
        else reservation.departure_date
      end as departure_date,
      case
        when guest_session.status::text = 'active'
         and guest_session.checkin_time is not null
        then (
          guest_session.checkin_time
          at time zone hotel_timezone
        )::time
        else reservation.expected_checkin_time
      end as expected_checkin_time,
      case
        when guest_session.status::text = 'active'
         and coalesce(
               guest_session.extended_until,
               guest_session.checkout_time
             ) is not null
        then (
          coalesce(
            guest_session.extended_until,
            guest_session.checkout_time
          ) at time zone hotel_timezone
        )::time
        else reservation.expected_checkout_time
      end as expected_checkout_time,
      reservation.primary_guest_id,
      guest.full_name as guest_name,
      guest.phone as guest_phone,
      reservation_room.id as reservation_room_id,
      reservation_room.status::text as room_status,
      reservation_room.room_id,
      room.room_number::text as room_number,
      room_type.name::text as room_type,
      reservation_room.adults::integer as adults,
      reservation_room.children::integer as children,
      reservation_room.total_amount::numeric
        as total_amount,
      reservation.deposit_collected::numeric
        as deposit_collected,
      reservation.updated_at,
      guest_session.id as guest_session_id,
      guest_session.status::text
        as guest_session_status,
      guest_session.checkin_time,
      coalesce(
        guest_session.extended_until,
        guest_session.checkout_time
      ) as checkout_time,
      guest_session.checkout_time
        as scheduled_checkout_time,
      guest_session.extended_until,
      case
        when guest_session.id is not null
         and guest_session.status::text = 'active'
        then true
        else false
      end as can_move_room,
      case
        when guest_session.id is not null
         and guest_session.status::text = 'active'
        then true
        else false
      end as can_extend_stay
    from public.reservations reservation
    join public.reservation_rooms reservation_room
      on reservation_room.hotel_id =
         reservation.hotel_id
     and reservation_room.reservation_id =
         reservation.id
     and reservation_room.status::text
           not in ('cancelled', 'released')
    left join public.guests guest
      on guest.hotel_id = reservation.hotel_id
     and guest.id = reservation.primary_guest_id
    left join public.rooms room
      on room.hotel_id = reservation_room.hotel_id
     and room.id = reservation_room.room_id
    join public.room_types room_type
      on room_type.hotel_id =
         reservation_room.hotel_id
     and room_type.id =
         reservation_room.room_type_id
    left join public.guest_sessions guest_session
      on guest_session.hotel_id =
         reservation_room.hotel_id
     and guest_session.reservation_room_id =
         reservation_room.id
    where reservation.hotel_id = target_hotel_id
  ),

  direct_walkin_rows as (
    select
      'walk_in'::text as operation_source,
      true as is_walk_in,
      null::uuid as reservation_id,
      (
        'WALKIN-'
        || upper(
          substr(
            replace(guest_session.id::text, '-', ''),
            1,
            8
          )
        )
      )::text as reservation_number,
      'checked_in'::text as reservation_status,
      (
        guest_session.checkin_time
        at time zone hotel_timezone
      )::date as arrival_date,
      (
        coalesce(
          guest_session.extended_until,
          guest_session.checkout_time
        ) at time zone hotel_timezone
      )::date as departure_date,
      (
        guest_session.checkin_time
        at time zone hotel_timezone
      )::time as expected_checkin_time,
      (
        coalesce(
          guest_session.extended_until,
          guest_session.checkout_time
        ) at time zone hotel_timezone
      )::time as expected_checkout_time,
      guest_session.guest_id as primary_guest_id,
      guest.full_name as guest_name,
      guest.phone as guest_phone,
      null::uuid as reservation_room_id,
      'checked_in'::text as room_status,
      guest_session.room_id,
      room.room_number::text as room_number,
      room_type.name::text as room_type,
      coalesce(occupancy.adults, 1)::integer
        as adults,
      coalesce(occupancy.children, 0)::integer
        as children,
      coalesce(room_charge.total_amount, 0)::numeric
        as total_amount,
      0::numeric as deposit_collected,
      guest_session.created_at as updated_at,
      guest_session.id as guest_session_id,
      guest_session.status::text
        as guest_session_status,
      guest_session.checkin_time,
      coalesce(
        guest_session.extended_until,
        guest_session.checkout_time
      ) as checkout_time,
      guest_session.checkout_time
        as scheduled_checkout_time,
      guest_session.extended_until,
      true as can_move_room,
      true as can_extend_stay
    from public.guest_sessions guest_session
    join public.guests guest
      on guest.hotel_id = guest_session.hotel_id
     and guest.id = guest_session.guest_id
    join public.rooms room
      on room.hotel_id = guest_session.hotel_id
     and room.id = guest_session.room_id
    join public.room_types room_type
      on room_type.hotel_id = room.hotel_id
     and room_type.id = room.room_type_id

    left join lateral (
      select
        (
          1
          + count(*) filter (
              where coalesce(
                nullif(
                  lower(
                    trim(
                      companion.guest_category::text
                    )
                  ),
                  ''
                ),
                'adult'
              ) = 'adult'
            )
        )::integer as adults,
        (
          count(*) filter (
            where coalesce(
              nullif(
                lower(
                  trim(
                    companion.guest_category::text
                  )
                ),
                ''
              ),
              'adult'
            ) in ('child', 'infant')
          )
        )::integer as children
      from public.guest_companions companion
      where companion.hotel_id =
            guest_session.hotel_id
        and companion.guest_session_id =
            guest_session.id
    ) occupancy on true

    left join lateral (
      select
        coalesce(
          sum(payment.amount),
          0
        )::numeric as total_amount
      from public.payments payment
      where payment.hotel_id =
            guest_session.hotel_id
        and payment.guest_session_id =
            guest_session.id
        and payment.payment_type::text =
            'room_charge'
    ) room_charge on true

    where guest_session.hotel_id =
          target_hotel_id
      and guest_session.status::text =
          'active'
      and guest_session.reservation_id
          is null
      and guest_session.reservation_room_id
          is null
      and guest_session.room_id is not null
  ),

  operation_rows as (
    select * from reservation_rows
    union all
    select * from direct_walkin_rows
  ),

  classified_rows as (
    select
      operation_row.*,

      case
        -- A confirmed reservation from an earlier business date never
        -- generated a guest session.
        when operation_row.operation_source =
             'reservation'
         and operation_row.guest_session_id is null
         and operation_row.room_status = 'confirmed'
         and operation_row.reservation_status
               in ('confirmed', 'checked_in')
         and operation_row.arrival_date < target_date
        then 'missed_arrival'

        -- Today's expected check-in time has passed without a guest session.
        when operation_row.operation_source =
             'reservation'
         and operation_row.guest_session_id is null
         and operation_row.room_status = 'confirmed'
         and operation_row.reservation_status
               in ('confirmed', 'checked_in')
         and operation_row.arrival_date = target_date
         and target_date = hotel_local_today
         and operation_row.expected_checkin_time
               is not null
         and (
           operation_row.arrival_date
           + operation_row.expected_checkin_time
         ) at time zone hotel_timezone < now()
        then 'late_arrival'

        -- An active checked-in stay remained open after an earlier checkout
        -- business date.
        when operation_row.room_status = 'checked_in'
         and operation_row.guest_session_status =
             'active'
         and operation_row.departure_date <
             target_date
        then 'overdue_departure'

        -- Today's effective checkout time has passed and the stay is active.
        -- An extension changes checkout_time/departure_date first, so properly
        -- extended stays are not classified as late.
        when operation_row.room_status = 'checked_in'
         and operation_row.guest_session_status =
             'active'
         and operation_row.departure_date =
             target_date
         and target_date = hotel_local_today
         and operation_row.checkout_time < now()
        then 'late_checkout'

        else null
      end as exception_type,

      case
        when operation_row.operation_source =
             'reservation'
         and operation_row.guest_session_id is null
         and operation_row.room_status = 'confirmed'
         and operation_row.reservation_status
               in ('confirmed', 'checked_in')
         and (
           operation_row.arrival_date < target_date
           or (
             operation_row.arrival_date =
               target_date
             and target_date = hotel_local_today
             and operation_row.expected_checkin_time
                   is not null
             and (
               operation_row.arrival_date
               + operation_row.expected_checkin_time
             ) at time zone hotel_timezone < now()
           )
         )
        then (
          operation_row.arrival_date
          + coalesce(
              operation_row.expected_checkin_time,
              time '18:00:00'
            )
        ) at time zone hotel_timezone

        when operation_row.room_status =
             'checked_in'
         and operation_row.guest_session_status =
             'active'
         and (
           operation_row.departure_date <
             target_date
           or (
             operation_row.departure_date =
               target_date
             and target_date = hotel_local_today
             and operation_row.checkout_time < now()
           )
         )
        then operation_row.checkout_time

        else null
      end as overdue_since
    from operation_rows operation_row
  ),

  item_rows as (
    select
      jsonb_build_object(
        'operation_source', operation_source,
        'is_walk_in', is_walk_in,
        'reservation_id', reservation_id,
        'reservation_number', reservation_number,
        'reservation_status', reservation_status,
        'arrival_date', arrival_date,
        'departure_date', departure_date,
        'expected_checkin_time',
          expected_checkin_time,
        'expected_checkout_time',
          expected_checkout_time,
        'guest_id', primary_guest_id,
        'guest_name', guest_name,
        'guest_phone', guest_phone,
        'reservation_room_id',
          reservation_room_id,
        'room_status', room_status,
        'room_id', room_id,
        'room_number', room_number,
        'room_type', room_type,
        'adults', adults,
        'children', children,
        'total_amount', total_amount,
        'deposit_collected',
          deposit_collected,
        'updated_at', updated_at,
        'guest_session_id',
          guest_session_id,
        'guest_session_status',
          guest_session_status,
        'checkin_time', checkin_time,
        'checkout_time', checkout_time,
        'scheduled_checkout_time',
          scheduled_checkout_time,
        'extended_until', extended_until,
        'can_move_room', can_move_room,
        'can_extend_stay', can_extend_stay,

        -- REV1 exception contract.
        'is_overdue',
          exception_type is not null,
        'exception_type', exception_type,
        'overdue_since', overdue_since,
        'minutes_overdue',
          case
            when exception_type is not null
             and overdue_since is not null
            then greatest(
              0,
              floor(
                extract(
                  epoch from (
                    as_of_at - overdue_since
                  )
                ) / 60
              )::bigint
            )
            else 0::bigint
          end
      ) as item,
      classified_rows.*
    from classified_rows
  ),

  overdue_exception_rows as (
    select *
    from item_rows
    where exception_type is not null
  ),

  overdue_arrival_rows as (
    select *
    from item_rows
    where exception_type in (
      'missed_arrival',
      'late_arrival'
    )
  ),

  overdue_departure_rows as (
    select *
    from item_rows
    where exception_type in (
      'overdue_departure',
      'late_checkout'
    )
  )

  select jsonb_build_object(
    'hotel_id', target_hotel_id,
    'business_date', target_date,
    'hotel_timezone', hotel_timezone,
    'hotel_local_today', hotel_local_today,
    'generated_at', now(),
    'as_of_at', as_of_at,

    'today_arrivals', coalesce((
      select jsonb_agg(
        item
        order by
          expected_checkin_time nulls last,
          reservation_number
      )
      from item_rows
      where operation_source = 'reservation'
        and arrival_date = target_date
        and reservation_status
              in ('confirmed', 'checked_in')
        and room_status = 'confirmed'
    ), '[]'::jsonb),

    'upcoming_arrivals', coalesce((
      select jsonb_agg(
        item
        order by
          arrival_date,
          expected_checkin_time nulls last
      )
      from item_rows
      where operation_source = 'reservation'
        and arrival_date > target_date
        and arrival_date <=
            target_date + upcoming_days
        and reservation_status
              in ('confirmed', 'checked_in')
        and room_status = 'confirmed'
    ), '[]'::jsonb),

    -- Today departures intentionally remains the complete schedule for the
    -- selected day. A same-day late checkout can also appear in the exception
    -- queue because schedule and exception queues answer different questions.
    'today_departures', coalesce((
      select jsonb_agg(
        item
        order by
          expected_checkout_time nulls last,
          room_number
      )
      from item_rows
      where departure_date = target_date
        and room_status = 'checked_in'
        and guest_session_status = 'active'
    ), '[]'::jsonb),

    -- In-house intentionally contains every active checked-in stay, including
    -- an overdue stay. The overdue queue is an exception lens, not a removal
    -- from occupancy.
    'in_house', coalesce((
      select jsonb_agg(
        item
        order by
          room_number,
          checkin_time
      )
      from item_rows
      where room_status = 'checked_in'
        and guest_session_status = 'active'
    ), '[]'::jsonb),

    'unallocated_arrivals', coalesce((
      select jsonb_agg(
        item
        order by
          arrival_date,
          reservation_number
      )
      from item_rows
      where operation_source = 'reservation'
        and room_id is null
        and arrival_date <=
            target_date + upcoming_days
        and reservation_status
              in (
                'tentative',
                'confirmed',
                'checked_in'
              )
        and room_status in ('held', 'confirmed')
    ), '[]'::jsonb),

    -- Canonical Day 10 key.
    'overdue_exceptions', coalesce((
      select jsonb_agg(
        item
        order by
          overdue_since,
          room_number nulls last,
          reservation_number
      )
      from overdue_exception_rows
    ), '[]'::jsonb),

    -- Backward-compatible key used by the existing six-tab frontend. It now
    -- contains both arrival and departure exceptions.
    'overdue_arrivals', coalesce((
      select jsonb_agg(
        item
        order by
          overdue_since,
          room_number nulls last,
          reservation_number
      )
      from overdue_exception_rows
    ), '[]'::jsonb),

    -- Specialized keys are supplied for the final hardened frontend and other
    -- consumers without breaking the existing response contract.
    'late_arrivals', coalesce((
      select jsonb_agg(
        item
        order by
          overdue_since,
          reservation_number
      )
      from overdue_arrival_rows
    ), '[]'::jsonb),

    'overdue_departures', coalesce((
      select jsonb_agg(
        item
        order by
          overdue_since,
          room_number nulls last
      )
      from overdue_departure_rows
    ), '[]'::jsonb)
  )
  into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_reservation_operations"("target_hotel_id" "uuid", "target_date" "date", "upcoming_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_reservation_operations"("target_hotel_id" "uuid", "target_date" "date", "upcoming_days" integer) IS 'Day 10 unified front-desk source REV3. Preserves the six existing queues and adds authoritative hotel-timezone-aware missed-arrival, late-arrival, overdue-departure and same-day late-checkout classification. Active overdue stays remain in In House; same-day late checkouts remain in Today Departures and also appear in the exception lens.';



CREATE OR REPLACE FUNCTION "public"."get_reservation_rate_quote"("target_hotel_id" "uuid", "target_rate_plan_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date", "target_adults" integer DEFAULT 1, "target_children" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  room_type_row public.room_types%rowtype;
  rate_plan_row public.rate_plans%rowtype;
  quote_lines jsonb;
  number_of_nights integer;
  extra_adults integer;
  room_subtotal numeric(12,2);
  average_nightly numeric(12,2);
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception 'Hotel access denied.';
  end if;

  if target_adults < 1 or target_children < 0 then
    raise exception 'Guest counts are invalid.';
  end if;

  select rp.*
  into rate_plan_row
  from public.rate_plans rp
  where rp.id = target_rate_plan_id
    and rp.hotel_id = target_hotel_id
    and rp.is_active;

  if not found then
    raise exception 'Active rate plan not found for this hotel.';
  end if;

  select rt.*
  into room_type_row
  from public.room_types rt
  where rt.id = rate_plan_row.room_type_id
    and rt.hotel_id = target_hotel_id
    and rt.is_active;

  if not found then
    raise exception 'Active room type not found for this rate plan.';
  end if;

  if target_adults > room_type_row.max_adults
     or target_children > room_type_row.max_children
     or target_adults + target_children >
       room_type_row.max_occupancy
  then
    raise exception 'Guest count exceeds room-type capacity.';
  end if;

  number_of_nights :=
    target_departure_date - target_arrival_date;

  if number_of_nights < 1 or number_of_nights > 365 then
    raise exception 'Stay length must be between 1 and 365 nights.';
  end if;

  extra_adults :=
    greatest(target_adults - room_type_row.base_occupancy, 0);

  with quoted as (
    select
      q.stay_date,
      q.currency_code,
      q.nightly_rate,
      q.extra_adult_rate,
      q.extra_child_rate,
      q.rate_source,
      q.seasonal_rate_id,
      (
        q.nightly_rate
        + q.extra_adult_rate * extra_adults
        + q.extra_child_rate * target_children
      )::numeric(12,2) as effective_nightly_rate
    from public.get_rate_quote(
      target_hotel_id,
      target_rate_plan_id,
      target_arrival_date,
      target_departure_date
    ) q
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'stay_date', quoted.stay_date,
          'nightly_rate', quoted.nightly_rate,
          'extra_adult_rate', quoted.extra_adult_rate,
          'extra_child_rate', quoted.extra_child_rate,
          'extra_adults', extra_adults,
          'children', target_children,
          'effective_nightly_rate',
            quoted.effective_nightly_rate,
          'rate_source', quoted.rate_source,
          'seasonal_rate_id', quoted.seasonal_rate_id
        )
        order by quoted.stay_date
      ),
      '[]'::jsonb
    ),
    coalesce(sum(quoted.effective_nightly_rate), 0)::numeric(12,2)
  into quote_lines, room_subtotal
  from quoted;

  average_nightly :=
    round(room_subtotal / number_of_nights, 2);

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'rate_plan_id', rate_plan_row.id,
    'rate_plan_name', rate_plan_row.name,
    'room_type_id', room_type_row.id,
    'room_type_name', room_type_row.name,
    'currency_code', rate_plan_row.currency_code,
    'arrival_date', target_arrival_date,
    'departure_date', target_departure_date,
    'nights', number_of_nights,
    'adults', target_adults,
    'children', target_children,
    'extra_adults', extra_adults,
    'average_nightly_rate', average_nightly,
    'room_subtotal', room_subtotal,
    'tax_amount', 0,
    'discount_amount', 0,
    'total_amount', room_subtotal,
    'nightly_breakdown', quote_lines
  );
end;
$$;


ALTER FUNCTION "public"."get_reservation_rate_quote"("target_hotel_id" "uuid", "target_rate_plan_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date", "target_adults" integer, "target_children" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reservations"("target_hotel_id" "uuid", "status_filter" "text" DEFAULT NULL::"text", "search_text" "text" DEFAULT NULL::"text", "arrival_from" "date" DEFAULT NULL::"date", "arrival_to" "date" DEFAULT NULL::"date", "page_limit" integer DEFAULT 50, "page_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_status text;
  normalized_search text;
  safe_limit integer;
  safe_offset integer;
  result_items jsonb;
  result_count bigint;
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception 'Hotel access denied.';
  end if;

  normalized_status :=
    nullif(lower(trim(coalesce(status_filter, ''))), '');
  normalized_search :=
    lower(trim(coalesce(search_text, '')));
  safe_limit := least(greatest(coalesce(page_limit, 50), 1), 100);
  safe_offset := greatest(coalesce(page_offset, 0), 0);

  with filtered as (
    select r.*
    from public.reservations r
    left join public.guests g
      on g.id = r.primary_guest_id
     and g.hotel_id = r.hotel_id
    where r.hotel_id = target_hotel_id
      and (
        normalized_status is null
        or r.status = normalized_status
      )
      and (
        arrival_from is null
        or r.departure_date > arrival_from
      )
      and (
        arrival_to is null
        or r.arrival_date <= arrival_to
      )
      and (
        normalized_search = ''
        or lower(r.reservation_number) like
          '%' || normalized_search || '%'
        or lower(coalesce(g.full_name, '')) like
          '%' || normalized_search || '%'
        or lower(coalesce(g.phone, '')) like
          '%' || normalized_search || '%'
        or lower(coalesce(g.email, '')) like
          '%' || normalized_search || '%'
      )
  ),
  page_rows as (
    select *
    from filtered
    order by arrival_date asc, created_at desc
    limit safe_limit
    offset safe_offset
  )
  select
    coalesce(
      jsonb_agg(
        private.build_reservation_json(
          target_hotel_id,
          page_rows.id
        )
        order by page_rows.arrival_date, page_rows.created_at desc
      ),
      '[]'::jsonb
    )
  into result_items
  from page_rows;

  select count(*)
  into result_count
  from public.reservations r
  left join public.guests g
    on g.id = r.primary_guest_id
   and g.hotel_id = r.hotel_id
  where r.hotel_id = target_hotel_id
    and (
      normalized_status is null
      or r.status = normalized_status
    )
    and (
      arrival_from is null
      or r.departure_date > arrival_from
    )
    and (
      arrival_to is null
      or r.arrival_date <= arrival_to
    )
    and (
      normalized_search = ''
      or lower(r.reservation_number) like
        '%' || normalized_search || '%'
      or lower(coalesce(g.full_name, '')) like
        '%' || normalized_search || '%'
      or lower(coalesce(g.phone, '')) like
        '%' || normalized_search || '%'
      or lower(coalesce(g.email, '')) like
        '%' || normalized_search || '%'
    );

  return jsonb_build_object(
    'items', result_items,
    'total_count', result_count,
    'limit', safe_limit,
    'offset', safe_offset
  );
end;
$$;


ALTER FUNCTION "public"."get_reservations"("target_hotel_id" "uuid", "status_filter" "text", "search_text" "text", "arrival_from" "date", "arrival_to" "date", "page_limit" integer, "page_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reservations_page"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_booking_source" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := private.day18_page_limit(p_limit);
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
  v_search text := nullif(lower(trim(p_search)), '');
begin
  perform private.day18_assert_page_access(p_hotel_id);

  select cursor_at, cursor_id
  into v_cursor_at, v_cursor_id
  from private.day18_decode_cursor(p_cursor);

  with candidates as (
    select
      r.*,
      g.full_name as primary_guest_name,
      row_number() over (
        order by r.created_at desc, r.id desc
      ) as rn
    from public.reservations r
    left join public.guests g
      on g.hotel_id = r.hotel_id
     and g.id = r.primary_guest_id
    where r.hotel_id = p_hotel_id
      and (p_status is null or r.status = p_status)
      and (
        p_booking_source is null
        or r.booking_source = p_booking_source
      )
      and (
        v_search is null
        or lower(r.reservation_number) like v_search || '%'
        or lower(coalesce(g.full_name, '')) like v_search || '%'
      )
      and (
        v_cursor_at is null
        or v_cursor_id is null
        or (r.created_at, r.id) < (v_cursor_at, v_cursor_id)
      )
    order by r.created_at desc, r.id desc
    limit v_limit + 1
  ),
  visible as (
    select *
    from candidates
    where rn <= v_limit
  )
  select jsonb_build_object(
    'items',
      coalesce(
        (
          select jsonb_agg(
            (to_jsonb(v) - 'rn')
            order by v.created_at desc, v.id desc
          )
          from visible v
        ),
        '[]'::jsonb
      ),
    'limit', v_limit,
    'has_more', (select count(*) > v_limit from candidates),
    'next_cursor',
      case
        when (select count(*) > v_limit from candidates)
        then (
          select private.day18_encode_cursor(v.created_at, v.id)
          from visible v
          order by v.created_at asc, v.id asc
          limit 1
        )
        else null
      end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_reservations_page"("p_hotel_id" "uuid", "p_limit" integer, "p_cursor" "text", "p_status" "text", "p_booking_source" "text", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_room_inventory_workspace"("h" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_any_permission(
    h,array['rooms.view','rooms.manage','housekeeping.view','housekeeping.manage','reservations.view','reservations.manage']::text[]
  ) then raise exception 'Room inventory access denied.'; end if;
  return jsonb_build_object(
    'floors',coalesce((select jsonb_agg(to_jsonb(f) order by f.sort_order,f.floor_number nulls last,f.name) from public.floors f where f.hotel_id=h),'[]'::jsonb),
    'room_types',coalesce((select jsonb_agg(to_jsonb(t) order by t.sort_order,t.name) from public.room_types t where t.hotel_id=h),'[]'::jsonb),
    'rooms',coalesce((
      select jsonb_agg(to_jsonb(r)||jsonb_build_object(
        'floor_name',f.name,'floor_code',f.code,'room_type_name',t.name,'room_type_code',t.code,
        'commitments',private.day13_room_commitments(h,r.id)
      ) order by f.sort_order,nullif(regexp_replace(r.room_number,'[^0-9]','','g'),'')::int nulls last,r.room_number)
      from public.rooms r join public.floors f on f.hotel_id=r.hotel_id and f.id=r.floor_id
      join public.room_types t on t.hotel_id=r.hotel_id and t.id=r.room_type_id where r.hotel_id=h
    ),'[]'::jsonb),
    'status_events',coalesce((select jsonb_agg(to_jsonb(q) order by q.occurred_at desc) from (
      select * from public.room_status_events where hotel_id=h order by occurred_at desc limit 200
    ) q),'[]'::jsonb),
    'imports',coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from (
      select * from public.room_import_batches where hotel_id=h order by created_at desc limit 50
    ) q),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_room_inventory_workspace"("h" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_room_type_availability"("target_hotel_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date") RETURNS TABLE("room_type_id" "uuid", "room_type_name" "text", "total_rooms" bigint, "available_rooms" bigint, "standard_rate" numeric, "active_rate_plan_id" "uuid", "active_rate_plan_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_hotel_access(target_hotel_id) then raise exception 'Hotel access denied.'; end if;
  if target_arrival_date is null or target_departure_date is null or target_departure_date<=target_arrival_date
    then raise exception 'Departure date must be after arrival date.'; end if;
  return query
  with av as(select * from public.get_available_rooms(target_hotel_id,target_arrival_date,target_departure_date,null))
  select t.id,t.name,count(r.id)::bigint,count(av.room_id)::bigint,coalesce(rp.base_rate,t.base_rate)::numeric,rp.id,rp.name
  from public.room_types t
  left join public.rooms r on r.hotel_id=t.hotel_id and r.room_type_id=t.id and r.is_active
    and exists(select 1 from public.floors f where f.hotel_id=r.hotel_id and f.id=r.floor_id and f.is_active)
  left join av on av.room_id=r.id
  left join lateral(
    select p.* from public.rate_plans p where p.hotel_id=t.hotel_id and p.room_type_id=t.id and p.is_active
    order by p.priority,p.created_at limit 1
  ) rp on true
  where t.hotel_id=target_hotel_id and t.is_active
  group by t.id,t.name,t.sort_order,t.base_rate,rp.id,rp.name,rp.base_rate
  order by t.sort_order,t.name;
end;
$$;


ALTER FUNCTION "public"."get_room_type_availability"("target_hotel_id" "uuid", "target_arrival_date" "date", "target_departure_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_service_operations_analytics"("p_hotel_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_permission(p_hotel_id, 'services.view') then
    raise exception 'Service analytics access denied.';
  end if;

  if p_from is null or p_to is null or p_to <= p_from then
    raise exception 'A valid analytics date range is required.';
  end if;

  return jsonb_build_object(
    'requests', (
      select count(*) from public.service_requests sr
      where sr.hotel_id = p_hotel_id
        and sr.created_at >= p_from and sr.created_at < p_to
    ),
    'completed', (
      select count(*) from public.service_requests sr
      where sr.hotel_id = p_hotel_id
        and sr.created_at >= p_from and sr.created_at < p_to
        and sr.status = 'completed'
    ),
    'cancelled', (
      select count(*) from public.service_requests sr
      where sr.hotel_id = p_hotel_id
        and sr.created_at >= p_from and sr.created_at < p_to
        and sr.status = 'cancelled'
    ),
    'overdue', (
      select count(*) from public.service_requests sr
      where sr.hotel_id = p_hotel_id
        and sr.created_at >= p_from and sr.created_at < p_to
        and sr.status not in ('completed','cancelled')
        and sr.sla_due_at < now()
    ),
    'average_accept_minutes', (
      select coalesce(avg(extract(epoch from (sr.accepted_at - sr.created_at)) / 60), 0)
      from public.service_requests sr
      where sr.hotel_id = p_hotel_id
        and sr.created_at >= p_from and sr.created_at < p_to
        and sr.accepted_at is not null
    ),
    'average_completion_minutes', (
      select coalesce(avg(extract(epoch from (sr.completed_at - sr.created_at)) / 60), 0)
      from public.service_requests sr
      where sr.hotel_id = p_hotel_id
        and sr.created_at >= p_from and sr.created_at < p_to
        and sr.completed_at is not null
    ),
    'sla_met_rate', (
      select coalesce(
        round(
          100.0 * count(*) filter (where sr.completed_at <= sr.sla_due_at)
          / nullif(count(*) filter (where sr.completed_at is not null), 0),
          2
        ),
        0
      )
      from public.service_requests sr
      where sr.hotel_id = p_hotel_id
        and sr.created_at >= p_from and sr.created_at < p_to
    ),
    'by_department', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'department', department,
          'requests', request_count,
          'completed', completed_count,
          'overdue', overdue_count
        ) order by request_count desc, department
      )
      from (
        select
          sr.department,
          count(*)::integer as request_count,
          count(*) filter (where sr.status = 'completed')::integer as completed_count,
          count(*) filter (
            where sr.status not in ('completed','cancelled')
              and sr.sla_due_at < now()
          )::integer as overdue_count
        from public.service_requests sr
        where sr.hotel_id = p_hotel_id
          and sr.created_at >= p_from and sr.created_at < p_to
        group by sr.department
      ) department_stats
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_service_operations_analytics"("p_hotel_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_service_requests_page"("p_hotel_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := private.day18_page_limit(p_limit);
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
begin
  perform private.day18_assert_page_access(p_hotel_id);

  select cursor_at, cursor_id
  into v_cursor_at, v_cursor_id
  from private.day18_decode_cursor(p_cursor);

  with candidates as (
    select
      sr.*,
      g.full_name as guest_name,
      r.room_number,
      row_number() over (
        order by sr.created_at desc, sr.id desc
      ) as rn
    from public.service_requests sr
    left join public.guests g
      on g.hotel_id = sr.hotel_id
     and g.id = sr.guest_id
    left join public.rooms r
      on r.hotel_id = sr.hotel_id
     and r.id = sr.room_id
    where sr.hotel_id = p_hotel_id
      and (p_status is null or sr.status = p_status)
      and (
        p_department is null
        or sr.department = p_department
      )
      and (
        v_cursor_at is null
        or v_cursor_id is null
        or (sr.created_at, sr.id) < (v_cursor_at, v_cursor_id)
      )
    order by sr.created_at desc, sr.id desc
    limit v_limit + 1
  ),
  visible as (
    select *
    from candidates
    where rn <= v_limit
  )
  select jsonb_build_object(
    'items',
      coalesce(
        (
          select jsonb_agg(
            (to_jsonb(v) - 'rn')
            order by v.created_at desc, v.id desc
          )
          from visible v
        ),
        '[]'::jsonb
      ),
    'limit', v_limit,
    'has_more', (select count(*) > v_limit from candidates),
    'next_cursor',
      case
        when (select count(*) > v_limit from candidates)
        then (
          select private.day18_encode_cursor(v.created_at, v.id)
          from visible v
          order by v.created_at asc, v.id asc
          limit 1
        )
        else null
      end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_service_requests_page"("p_hotel_id" "uuid", "p_limit" integer, "p_cursor" "text", "p_status" "text", "p_department" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_super_admin_commercial_data"("row_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  safe_limit integer := greatest(1, least(coalesce(row_limit, 100), 250));
begin
  return jsonb_build_object(
    'generated_at', now(),
    'generated_by', actor_user_id,
    'summary', public.get_super_admin_dashboard(),

    'hotels', (
      select coalesce(
        jsonb_agg(to_jsonb(hotel_row) order by hotel_row.created_at desc),
        '[]'::jsonb
      )
      from (
        select
          h.id,
          h.hotel_name,
          h.slug,
          h.location,
          h.city,
          h.state,
          h.status,
          h.subscription_status,
          h.currency_code,
          h.created_at,
          hs.id as subscription_id,
          hs.plan_id,
          sp.plan_name,
          sp.plan_code,
          hs.status as lifecycle_status,
          hs.billing_mode,
          hs.billing_cycle,
          hs.amount_minor,
          hs.currency_code as subscription_currency,
          hs.provider,
          hs.provider_status,
          hs.provider_subscription_id,
          hs.provider_payment_link_id,
          hs.trial_ends_at,
          hs.current_period_start,
          hs.current_period_end,
          hs.grace_ends_at,
          hs.last_payment_at
        from public.hotels h
        left join lateral (
          select current_hs.*
          from public.hotel_subscriptions current_hs
          where current_hs.hotel_id = h.id
          order by
            case
              when current_hs.status in (
                'trial',
                'trialing',
                'active',
                'past_due',
                'suspended'
              ) then 0
              else 1
            end,
            coalesce(current_hs.updated_at, current_hs.created_at) desc,
            current_hs.id desc
          limit 1
        ) hs on true
        left join public.subscription_plans sp on sp.id = hs.plan_id
        order by h.created_at desc
        limit safe_limit
      ) hotel_row
    ),

    'plans', (
      select coalesce(
        jsonb_agg(to_jsonb(plan_row) order by plan_row.price_monthly, plan_row.plan_name),
        '[]'::jsonb
      )
      from (
        select
          sp.id,
          sp.plan_name,
          sp.plan_code,
          sp.price_monthly,
          sp.price_annual,
          sp.currency_code,
          sp.max_rooms,
          sp.max_staff,
          sp.max_properties,
          sp.max_storage_mb,
          sp.trial_days,
          sp.features,
          sp.is_public,
          sp.status,
          sp.created_at,
          (
            select count(*)
            from public.hotel_subscriptions hs
            where hs.plan_id = sp.id
              and hs.status in (
                'trial',
                'trialing',
                'active',
                'past_due',
                'suspended'
              )
          ) as current_hotels,
          (
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'provider', spp.provider,
                  'billing_cycle', spp.billing_cycle,
                  'currency_code', spp.currency_code,
                  'amount_minor', spp.amount_minor,
                  'provider_plan_id', spp.provider_plan_id,
                  'status', spp.status
                )
                order by spp.provider, spp.billing_cycle
              ),
              '[]'::jsonb
            )
            from public.subscription_plan_prices spp
            where spp.plan_id = sp.id
          ) as provider_prices
        from public.subscription_plans sp
      ) plan_row
    ),

    'usage', (
      select coalesce(
        jsonb_agg(to_jsonb(usage_row) order by usage_row.hotel_id, usage_row.metric_key),
        '[]'::jsonb
      )
      from (
        select
          uc.hotel_id,
          h.hotel_name,
          uc.metric_key,
          uc.current_value,
          uc.limit_value,
          uc.captured_at
        from public.usage_counters uc
        join public.hotels h on h.id = uc.hotel_id
        order by uc.captured_at desc
        limit safe_limit * 10
      ) usage_row
    ),

    'payment_links', (
      select coalesce(
        jsonb_agg(to_jsonb(link_row) order by link_row.created_at desc),
        '[]'::jsonb
      )
      from (
        select
          spl.id,
          spl.hotel_id,
          h.hotel_name,
          spl.plan_id,
          sp.plan_name,
          spl.subscription_id,
          spl.provider,
          spl.provider_link_id,
          spl.reference_id,
          spl.status,
          spl.billing_cycle,
          spl.currency_code,
          spl.amount_minor,
          spl.provider_url,
          spl.provider_payment_id,
          spl.customer_name,
          spl.customer_email,
          spl.customer_phone,
          spl.expires_at,
          spl.paid_at,
          spl.failure_reason,
          spl.created_at,
          spl.updated_at
        from public.subscription_payment_links spl
        join public.hotels h on h.id = spl.hotel_id
        join public.subscription_plans sp on sp.id = spl.plan_id
        order by spl.created_at desc
        limit safe_limit
      ) link_row
    ),

    'support_tickets', (
      select coalesce(
        jsonb_agg(to_jsonb(ticket_row) order by ticket_row.updated_at desc),
        '[]'::jsonb
      )
      from (
        select
          st.id,
          st.hotel_id,
          h.hotel_name,
          st.subject,
          st.description,
          st.category,
          st.priority,
          st.status,
          st.created_by,
          st.assigned_to,
          st.last_response_at,
          st.resolved_at,
          st.closed_at,
          st.created_at,
          st.updated_at
        from public.support_tickets st
        join public.hotels h on h.id = st.hotel_id
        order by st.updated_at desc
        limit safe_limit
      ) ticket_row
    ),

    'subscription_events', (
      select coalesce(
        jsonb_agg(to_jsonb(event_row) order by event_row.occurred_at desc),
        '[]'::jsonb
      )
      from (
        select
          se.id,
          se.hotel_id,
          h.hotel_name,
          se.subscription_id,
          se.event_type,
          se.event_source,
          se.old_status,
          se.new_status,
          se.old_plan_id,
          se.new_plan_id,
          se.provider,
          se.provider_event_id,
          se.details,
          se.occurred_at
        from public.subscription_events se
        join public.hotels h on h.id = se.hotel_id
        order by se.occurred_at desc
        limit safe_limit
      ) event_row
    ),

    'webhook_events', (
      select coalesce(
        jsonb_agg(to_jsonb(webhook_row) order by webhook_row.received_at desc),
        '[]'::jsonb
      )
      from (
        select
          we.id,
          we.provider,
          we.provider_event_id,
          we.event_type,
          we.processing_status,
          we.signature_valid,
          we.attempts,
          we.last_error,
          we.received_at,
          we.processed_at,
          we.subscription_id,
          we.hotel_id,
          h.hotel_name
        from public.webhook_events we
        left join public.hotels h on h.id = we.hotel_id
        order by we.received_at desc
        limit safe_limit
      ) webhook_row
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_super_admin_commercial_data"("row_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_super_admin_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  mrr_minor numeric := 0;
begin
  select coalesce(
    sum(
      case hs.billing_cycle
        when 'monthly' then hs.amount_minor
        when 'annual' then hs.amount_minor / 12.0
        else 0
      end
    ),
    0
  )
  into mrr_minor
  from public.hotel_subscriptions hs
  where hs.status = 'active'
    and hs.billing_mode = 'paid'
    and hs.amount_minor > 0;

  return jsonb_build_object(
    'generated_at', now(),
    'generated_by', actor_user_id,
    'hotels', jsonb_build_object(
      'total', (
        select count(*) from public.hotels
      ),
      'active', (
        select count(*)
        from public.hotels h
        where h.status = 'active'
      ),
      'suspended', (
        select count(*)
        from public.hotels h
        where h.status = 'suspended'
      )
    ),
    'subscriptions', jsonb_build_object(
      'trialing', (
        select count(*)
        from public.hotel_subscriptions hs
        where hs.status in ('trial', 'trialing')
      ),
      'active_paid', (
        select count(*)
        from public.hotel_subscriptions hs
        where hs.status = 'active'
          and hs.billing_mode = 'paid'
      ),
      'active_complimentary', (
        select count(*)
        from public.hotel_subscriptions hs
        where hs.status = 'active'
          and hs.billing_mode = 'complimentary'
      ),
      'past_due', (
        select count(*)
        from public.hotel_subscriptions hs
        where hs.status = 'past_due'
      ),
      'suspended', (
        select count(*)
        from public.hotel_subscriptions hs
        where hs.status = 'suspended'
      ),
      'expired', (
        select count(*)
        from public.hotel_subscriptions hs
        where hs.status = 'expired'
      ),
      'cancelled', (
        select count(*)
        from public.hotel_subscriptions hs
        where hs.status = 'cancelled'
      ),
      'trials_expiring_7_days', (
        select count(*)
        from public.hotel_subscriptions hs
        where hs.status in ('trial', 'trialing')
          and hs.trial_ends_at > now()
          and hs.trial_ends_at <= now() + interval '7 days'
      )
    ),
    'revenue', jsonb_build_object(
      'currency_code', 'INR',
      'mrr_minor', round(mrr_minor)::bigint,
      'mrr', round(mrr_minor / 100.0, 2)
    ),
    'support', jsonb_build_object(
      'open', (
        select count(*)
        from public.support_tickets st
        where st.status in (
          'open',
          'in_progress',
          'waiting_on_hotel'
        )
      ),
      'urgent_open', (
        select count(*)
        from public.support_tickets st
        where st.status in (
          'open',
          'in_progress',
          'waiting_on_hotel'
        )
          and st.priority = 'urgent'
      )
    ),
    'webhooks', jsonb_build_object(
      'failed', (
        select count(*)
        from public.webhook_events we
        where we.processing_status = 'failed'
      ),
      'pending', (
        select count(*)
        from public.webhook_events we
        where we.processing_status in (
          'received',
          'processing'
        )
      )
    ),
    'usage', jsonb_build_object(
      'hotels_over_room_limit', (
        select count(distinct uc.hotel_id)
        from public.usage_counters uc
        where uc.metric_key = 'rooms'
          and uc.limit_value is not null
          and uc.current_value > uc.limit_value
      ),
      'hotels_over_staff_limit', (
        select count(distinct uc.hotel_id)
        from public.usage_counters uc
        where uc.metric_key = 'active_staff'
          and uc.limit_value is not null
          and uc.current_value > uc.limit_value
      )
    ),
    'plans', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'plan_id', sp.id,
            'plan_code', sp.plan_code,
            'plan_name', sp.plan_name,
            'status', sp.status,
            'price_monthly', sp.price_monthly,
            'max_rooms', sp.max_rooms,
            'max_staff', sp.max_staff,
            'current_hotels', (
              select count(*)
              from public.hotel_subscriptions hs
              where hs.plan_id = sp.id
                and hs.status in (
                  'trial',
                  'trialing',
                  'active',
                  'past_due',
                  'suspended'
                )
            )
          )
          order by sp.price_monthly, sp.plan_name
        ),
        '[]'::jsonb
      )
      from public.subscription_plans sp
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_super_admin_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_support_workspace"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.user_has_hotel_access(p_hotel_id) then
    raise exception 'Support workspace access denied.';
  end if;

  return jsonb_build_object(
    'tickets', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', st.id,
            'ticket_number', st.ticket_number,
            'subject', st.subject,
            'description', st.description,
            'category', st.category,
            'priority', st.priority,
            'status', st.status,
            'created_by', st.created_by,
            'assigned_to', st.assigned_to,
            'last_response_at', st.last_response_at,
            'created_at', st.created_at,
            'updated_at', st.updated_at,
            'events', coalesce(
              (
                select jsonb_agg(
                  to_jsonb(ste)
                  order by ste.created_at
                )
                from public.support_ticket_events ste
                where ste.ticket_id = st.id
                  and ste.hotel_id = st.hotel_id
              ),
              '[]'::jsonb
            )
          )
          order by st.updated_at desc
        )
        from public.support_tickets st
        where st.hotel_id = p_hotel_id
      ),
      '[]'::jsonb
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_support_workspace"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hold_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "reason_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.maintenance_tasks%rowtype;
  previous_status_value text;
  existing_event uuid;
begin
  actor_id_value :=
    private.day13_require_maintenance_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  if nullif(trim(reason_value), '') is null then
    raise exception 'Hold reason is required.';
  end if;

  select event_record.id
  into existing_event
  from public.maintenance_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type = 'held';

  if existing_event is not null then
    select task.*
    into task_row
    from public.maintenance_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select task.*
  into task_row
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Maintenance task was not found.';
  end if;

  if task_row.status <> 'in_progress' then
    raise exception
      'Only an in-progress maintenance task can be put on hold.';
  end if;

  previous_status_value := task_row.status;

  update public.maintenance_tasks
  set
    status = 'on_hold',
    held_at = now(),
    hold_reason = trim(reason_value),
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'hold_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_maintenance_event(
    target_hotel_id,
    target_task_id,
    'held',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'reason', trim(reason_value)
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row)
  );
end;
$$;


ALTER FUNCTION "public"."hold_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_hotel_rooms"("target_hotel_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  room_rows jsonb;
  room_item jsonb;

  room_number_value text;
  room_type_code_value text;
  floor_code_value text;
  status_value text;

  resolved_room_type_id uuid;
  resolved_room_type_name text;
  resolved_floor_id uuid;
  existing_room_id uuid;
  existing_status text;
  existing_room_type_id uuid;
  existing_floor_id uuid;

  inserted_count integer := 0;
  updated_count integer := 0;
  unchanged_count integer := 0;

  readiness jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if target_hotel_id is null
     or not exists (
       select 1
       from public.hotels h
       where h.id = target_hotel_id
     )
  then
    raise exception 'Unknown hotel.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_permission(target_hotel_id, 'hotel.manage')
  ) then
    raise exception 'Room import access denied.';
  end if;

  room_rows := case
    when jsonb_typeof(payload) = 'array' then payload
    when jsonb_typeof(payload) = 'object'
      and jsonb_typeof(payload -> 'rooms') = 'array'
      then payload -> 'rooms'
    else null
  end;

  if room_rows is null then
    raise exception
      'Room import payload must be an array or an object containing a rooms array.';
  end if;

  if jsonb_array_length(room_rows) = 0 then
    raise exception 'At least one room row is required.';
  end if;

  if jsonb_array_length(room_rows) > 1000 then
    raise exception
      'A single room import cannot exceed 1000 rows.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:import-rooms:' || target_hotel_id::text
    )
  );

  if exists (
    select 1
    from (
      select lower(trim(value ->> 'room_number')) as room_key
      from jsonb_array_elements(room_rows)
      group by lower(trim(value ->> 'room_number'))
      having count(*) > 1
    ) duplicate_payload_room
  ) then
    raise exception
      'The import contains duplicate room numbers.';
  end if;

  for room_item in
    select value
    from jsonb_array_elements(room_rows)
  loop
    room_number_value :=
      nullif(trim(room_item ->> 'room_number'), '');
    room_type_code_value :=
      upper(nullif(trim(room_item ->> 'room_type_code'), ''));
    floor_code_value :=
      upper(
        coalesce(
          nullif(trim(room_item ->> 'floor_code'), ''),
          'DEFAULT'
        )
      );
    status_value :=
      lower(
        coalesce(
          nullif(trim(room_item ->> 'status'), ''),
          'available'
        )
      );

    if room_number_value is null then
      raise exception 'Every room row requires room_number.';
    end if;

    if room_type_code_value is null then
      raise exception
        'Room % requires room_type_code.',
        room_number_value;
    end if;

    if status_value not in (
      'available',
      'occupied',
      'cleaning',
      'maintenance',
      'out_of_order'
    ) then
      raise exception
        'Room % has unsupported status %.',
        room_number_value,
        status_value;
    end if;

    select rt.id, rt.name
    into resolved_room_type_id, resolved_room_type_name
    from public.room_types rt
    where rt.hotel_id = target_hotel_id
      and upper(trim(rt.code)) = room_type_code_value
      and rt.is_active
    limit 1;

    if resolved_room_type_id is null then
      raise exception
        'Room % references unknown active room_type_code %.',
        room_number_value,
        room_type_code_value;
    end if;

    select f.id
    into resolved_floor_id
    from public.floors f
    where f.hotel_id = target_hotel_id
      and upper(trim(f.code)) = floor_code_value
      and f.is_active
    limit 1;

    if resolved_floor_id is null then
      raise exception
        'Room % references unknown active floor_code %.',
        room_number_value,
        floor_code_value;
    end if;

    select
      r.id,
      r.status,
      r.room_type_id,
      r.floor_id
    into
      existing_room_id,
      existing_status,
      existing_room_type_id,
      existing_floor_id
    from public.rooms r
    where r.hotel_id = target_hotel_id
      and lower(trim(r.room_number)) =
        lower(room_number_value)
    limit 1
    for update;

    if existing_room_id is null then
      insert into public.rooms (
        hotel_id,
        room_number,
        room_type,
        room_type_id,
        floor_id,
        status,
        created_at
      ) values (
        target_hotel_id,
        room_number_value,
        resolved_room_type_name,
        resolved_room_type_id,
        resolved_floor_id,
        status_value,
        now()
      );

      inserted_count := inserted_count + 1;
    elsif existing_status in ('occupied', 'cleaning')
      and (
        existing_room_type_id is distinct from
          resolved_room_type_id
        or existing_floor_id is distinct from
          resolved_floor_id
        or existing_status is distinct from status_value
      )
    then
      raise exception
        'Occupied/cleaning room % cannot be reconfigured by bulk import.',
        room_number_value;
    elsif existing_room_type_id is not distinct from
          resolved_room_type_id
      and existing_floor_id is not distinct from
          resolved_floor_id
      and existing_status is not distinct from status_value
    then
      unchanged_count := unchanged_count + 1;
    else
      update public.rooms r
      set
        room_type = resolved_room_type_name,
        room_type_id = resolved_room_type_id,
        floor_id = resolved_floor_id,
        status = status_value
      where r.id = existing_room_id;

      updated_count := updated_count + 1;
    end if;
  end loop;

  readiness :=
    private.compute_hotel_onboarding_readiness(
      target_hotel_id
    );

  update public.hotel_onboarding ho
  set
    readiness_state = readiness,
    last_saved_at = now(),
    updated_by = actor_user_id,
    version = ho.version + 1
  where ho.hotel_id = target_hotel_id;

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'total_rows', jsonb_array_length(room_rows),
    'inserted', inserted_count,
    'updated', updated_count,
    'unchanged', unchanged_count,
    'readiness', readiness
  );
end;
$$;


ALTER FUNCTION "public"."import_hotel_rooms"("target_hotel_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_rooms"("h" "uuid", "rows_value" "jsonb", "source_name_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; req text; batch public.room_import_batches%rowtype; n integer; dup integer; exist_count integer;
  rec record; floor_value uuid; type_value uuid; room_value uuid; inserted integer:=0;
begin
  actor:=private.day13_require_room_manager(h);
  req:=nullif(trim(request_id_value),'');
  if req is null or length(req)<8 then raise exception 'A request ID of at least eight characters is required.'; end if;
  select * into batch from public.room_import_batches where hotel_id=h and request_id=req;
  if batch.id is not null then
    return jsonb_build_object('ok',true,'idempotent',true,'batch',to_jsonb(batch),
      'rows',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_number) from public.room_import_rows x where x.hotel_id=h and x.batch_id=batch.id),'[]'::jsonb));
  end if;
  if jsonb_typeof(rows_value)<>'array' then raise exception 'Import rows must be a JSON array.'; end if;
  n:=jsonb_array_length(rows_value);
  if n<1 or n>100 then raise exception 'Room import requires 1 to 100 rows.'; end if;
  select count(*) into dup from (
    select private.day13_normalize_room_number(e.value->>'room_number') nr
    from jsonb_array_elements(rows_value) e(value)
    group by private.day13_normalize_room_number(e.value->>'room_number')
    having count(*)>1 or private.day13_normalize_room_number(e.value->>'room_number') is null
  ) q;
  if dup>0 then raise exception 'Import contains blank or duplicate room numbers.'; end if;
  select count(*) into exist_count
  from jsonb_array_elements(rows_value) e(value)
  join public.rooms r on r.hotel_id=h and r.room_number=private.day13_normalize_room_number(e.value->>'room_number');
  if exist_count>0 then raise exception 'Import contains % room number(s) already present in the hotel.',exist_count; end if;

  insert into public.room_import_batches(hotel_id,request_id,requested_rows,source_name,requested_by,summary)
  values(h,req,n,nullif(trim(source_name_value),''),actor,jsonb_build_object('atomic',true))
  returning * into batch;
  perform set_config('stayqr.day13_event_source','import',true);

  for rec in
    select ordinality::int row_number,value payload
    from jsonb_array_elements(rows_value) with ordinality
  loop
    floor_value:=nullif(rec.payload->>'floor_id','')::uuid;
    if floor_value is null then
      select id into floor_value from public.floors
      where hotel_id=h and is_active and upper(code)=upper(trim(rec.payload->>'floor_code')) limit 1;
    end if;
    type_value:=nullif(rec.payload->>'room_type_id','')::uuid;
    if type_value is null then
      select id into type_value from public.room_types
      where hotel_id=h and is_active and upper(code)=upper(trim(rec.payload->>'room_type_code')) limit 1;
    end if;
    if floor_value is null then raise exception 'Import row % cannot resolve active floor.',rec.row_number; end if;
    if type_value is null then raise exception 'Import row % cannot resolve active room type.',rec.row_number; end if;
    if coalesce(nullif(rec.payload->>'status',''),'available') not in ('available','cleaning','maintenance','out_of_order')
      then raise exception 'Import row % has invalid initial status.',rec.row_number; end if;

    perform set_config('stayqr.day13_request_id',req||':row:'||rec.row_number::text,true);
    insert into public.rooms(hotel_id,room_number,room_type_id,floor_id,status,is_active,updated_by,status_changed_by,metadata)
    values(h,private.day13_normalize_room_number(rec.payload->>'room_number'),type_value,floor_value,
      coalesce(nullif(rec.payload->>'status',''),'available'),true,actor,actor,
      jsonb_build_object('import_batch_id',batch.id,'import_request_id',req,'source_payload',rec.payload))
    returning id into room_value;

    insert into public.room_import_rows(hotel_id,batch_id,row_number,room_id,room_number,floor_id,room_type_id,initial_status,source_payload)
    values(h,batch.id,rec.row_number,room_value,private.day13_normalize_room_number(rec.payload->>'room_number'),
      floor_value,type_value,coalesce(nullif(rec.payload->>'status',''),'available'),rec.payload);
    inserted:=inserted+1;
  end loop;

  update public.room_import_batches set status='completed',inserted_rows=inserted,completed_at=now(),
    summary=summary||jsonb_build_object('inserted_rows',inserted)
  where hotel_id=h and id=batch.id returning * into batch;

  return jsonb_build_object('ok',true,'idempotent',false,'batch',to_jsonb(batch),
    'rows',(select jsonb_agg(to_jsonb(x) order by x.row_number) from public.room_import_rows x where x.hotel_id=h and x.batch_id=batch.id));
end;
$$;


ALTER FUNCTION "public"."import_rooms"("h" "uuid", "rows_value" "jsonb", "source_name_value" "text", "request_id_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."import_rooms"("h" "uuid", "rows_value" "jsonb", "source_name_value" "text", "request_id_value" "text") IS 'Atomically imports 1–100 rooms; existing subscription room-limit trigger remains authoritative.';



CREATE OR REPLACE FUNCTION "public"."inspect_housekeeping_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "result_value" "text", "notes_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.housekeeping_tasks%rowtype;
  inspection_row public.housekeeping_inspections%rowtype;
  snapshot_value jsonb;
  previous_status_value text;
begin
  actor_id_value :=
    private.day13_require_housekeeping_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  if result_value not in (
    'passed',
    'failed'
  ) then
    raise exception
      'Inspection result must be passed or failed.';
  end if;

  select inspection.*
  into inspection_row
  from public.housekeeping_inspections inspection
  where inspection.hotel_id = target_hotel_id
    and inspection.request_id = request_key;

  if inspection_row.id is not null then
    select task.*
    into task_row
    from public.housekeeping_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'inspection', to_jsonb(inspection_row),
      'task', to_jsonb(task_row)
    );
  end if;

  select task.*
  into task_row
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Housekeeping task was not found.';
  end if;

  if task_row.status <> 'cleaning_complete' then
    raise exception
      'Inspection requires cleaning_complete status.';
  end if;

  snapshot_value :=
    jsonb_build_object(
      'task_id', task_row.id,
      'room_id', task_row.room_id,
      'room_number', task_row.room_number,
      'task_type', task_row.task_type,
      'assigned_staff_id',
        task_row.assigned_staff_id,
      'cleaning_completed_at',
        task_row.cleaning_completed_at,
      'result', result_value,
      'notes', nullif(trim(notes_value), ''),
      'items',
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', item.id,
              'code', item.item_code,
              'label', item.label,
              'required', item.is_required,
              'status', item.item_status,
              'completed_at', item.completed_at,
              'completed_by', item.completed_by,
              'notes', item.notes
            )
            order by item.sort_order
          )
          from public.housekeeping_task_items item
          where item.hotel_id = target_hotel_id
            and item.task_id = target_task_id
        )
    );

  insert into public.housekeeping_inspections (
    hotel_id,
    task_id,
    result,
    notes,
    inspected_by,
    request_id,
    snapshot_json,
    snapshot_hash
  )
  values (
    target_hotel_id,
    target_task_id,
    result_value,
    nullif(trim(notes_value), ''),
    actor_id_value,
    request_key,
    snapshot_value,
    private.day13_hash_json(
      snapshot_value
    )
  )
  returning *
  into inspection_row;

  previous_status_value := task_row.status;

  update public.housekeeping_tasks
  set
    status =
      case
        when result_value = 'passed'
          then 'inspected'
        else 'inspection_failed'
      end,
    inspected_at = now(),
    inspected_by = actor_id_value,
    inspection_status = result_value,
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'last_inspection_id',
        inspection_row.id,
        'last_inspection_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_housekeeping_event(
    target_hotel_id,
    target_task_id,
    case
      when result_value = 'passed'
        then 'inspection_passed'
      else 'inspection_failed'
    end,
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'inspection_id', inspection_row.id,
      'snapshot_hash',
        inspection_row.snapshot_hash
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'inspection', to_jsonb(inspection_row),
    'task', to_jsonb(task_row)
  );
end;
$$;


ALTER FUNCTION "public"."inspect_housekeeping_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "result_value" "text", "notes_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_folio_credit_note"("target_hotel_id" "uuid", "target_folio_id" "uuid", "amount_value" numeric, "reason_value" "text", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  folio_row public.folios%rowtype;
  credit_row public.credit_notes%rowtype;
  request_key text;
  generated_id uuid := gen_random_uuid();
  hotel_timezone text;
begin
  if not private.user_has_any_permission(target_hotel_id,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Credit note issue access denied.';
  end if;
  actor_id_value := private.day11_require_current_actor();
  if amount_value is null or amount_value <= 0 then raise exception 'Credit note amount must be positive.'; end if;
  if nullif(trim(reason_value),'') is null then raise exception 'Credit note reason is required.'; end if;
  request_key := coalesce(nullif(trim(request_id_value),''),gen_random_uuid()::text);

  select credit.* into credit_row
  from public.credit_notes credit
  where credit.hotel_id = target_hotel_id and credit.idempotency_key = 'credit-note:' || request_key
  limit 1;
  if credit_row.id is not null then
    if credit_row.folio_id <> target_folio_id or credit_row.amount <> amount_value then raise exception 'Credit note idempotency conflict.'; end if;
    return jsonb_build_object('ok',true,'idempotent',true,'request_id',request_key,'credit_note',to_jsonb(credit_row));
  end if;

  select folio.* into folio_row
  from public.folios folio
  where folio.hotel_id = target_hotel_id and folio.id = target_folio_id
  for update;
  if not found then raise exception 'Folio was not found.'; end if;
  select hotel.timezone into hotel_timezone from public.hotels hotel where hotel.id = target_hotel_id;
  if folio_row.status = 'voided' or amount_value > folio_row.balance_amount then
    raise exception 'Credit note amount % exceeds open balance %.',amount_value,folio_row.balance_amount;
  end if;

  insert into public.credit_notes(
    id,hotel_id,folio_id,credit_note_number,amount,status,reason,idempotency_key,issued_by,metadata
  ) values (
    generated_id,target_hotel_id,target_folio_id,
    'CN-' || to_char(now() at time zone coalesce(hotel_timezone,'Asia/Kolkata'),'YYYYMMDD') || '-' || upper(substr(replace(generated_id::text,'-',''),1,8)),
    amount_value,'issued',trim(reason_value),'credit-note:' || request_key,actor_id_value,
    jsonb_build_object('request_id',request_key,'day',11)
  ) returning * into credit_row;

  perform private.write_folio_event(target_hotel_id,target_folio_id,'folio.credit_note.issued','credit_note',credit_row.id,to_jsonb(credit_row),jsonb_build_object('request_id',request_key,'day',11));
  return jsonb_build_object('ok',true,'idempotent',false,'request_id',request_key,'credit_note',to_jsonb(credit_row));
end;
$$;


ALTER FUNCTION "public"."issue_folio_credit_note"("target_hotel_id" "uuid", "target_folio_id" "uuid", "amount_value" numeric, "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_folio_invoice"("target_hotel_id" "uuid", "target_folio_id" "uuid", "supply_mode_value" "text", "invoice_date_value" "date", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  normalized_request_id text;

  folio_row public.folios%rowtype;
  preview_value jsonb;
  number_value jsonb;
  invoice_row public.invoices%rowtype;
  existing_invoice public.invoices%rowtype;

  line_record record;
  line_snapshot jsonb;

  invoice_id_value uuid := gen_random_uuid();
  verification_token_value uuid := gen_random_uuid();
  finalized_at_value timestamptz := now();

  tax_item_id_value uuid;
  tax_total_value numeric(14,2);

  snapshot_value jsonb;
  snapshot_hash_value text;

  invoice_status_value text;
  payment_status_value text;
begin
  actor_id_value :=
    private.day11_require_current_actor();

  normalized_request_id :=
    nullif(trim(request_id_value), '');

  if normalized_request_id is null
     or length(normalized_request_id) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:issue-folio-invoice:'
      || target_hotel_id::text
      || ':'
      || target_folio_id::text,
      0
    )
  );

  select invoice.*
  into existing_invoice
  from public.invoices invoice
  where invoice.hotel_id = target_hotel_id
    and invoice.invoice_origin =
      'authoritative'
    and invoice.idempotency_key =
      normalized_request_id
  limit 1;

  if existing_invoice.id is not null then
    if existing_invoice.folio_id <>
       target_folio_id
    then
      raise exception
        'Request ID is already used for another folio.';
    end if;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'invoice_id', existing_invoice.id,
      'invoice_number',
        existing_invoice.invoice_number,
      'verification_token',
        existing_invoice.verification_token,
      'snapshot_hash',
        existing_invoice.snapshot_hash,
      'tax_amount',
        existing_invoice.tax_amount,
      'total_amount',
        existing_invoice.total_amount,
      'pending_amount',
        existing_invoice.pending_amount,
      'invoice_status',
        existing_invoice.invoice_status
    );
  end if;

  select folio.*
  into folio_row
  from public.folios folio
  where folio.hotel_id = target_hotel_id
    and folio.id = target_folio_id
  for update;

  if not found then
    raise exception 'Folio was not found.';
  end if;

  if exists (
    select 1
    from public.invoices invoice
    where invoice.hotel_id =
          target_hotel_id
      and invoice.folio_id =
          target_folio_id
      and invoice.invoice_origin =
          'authoritative'
      and invoice.finalized_at is not null
  ) then
    raise exception
      'A final authoritative invoice already exists for this folio.';
  end if;

  preview_value :=
    private.day12_preview_folio_invoice(
      target_hotel_id,
      target_folio_id,
      supply_mode_value,
      invoice_date_value
    );

  number_value :=
    private.day12_next_invoice_number(
      target_hotel_id,
      (
        invoice_date_value::timestamp
        at time zone 'Asia/Kolkata'
      )
    );

  tax_total_value :=
    (
      preview_value
      #>> '{tax_breakup,tax_amount}'
    )::numeric;

  invoice_status_value :=
    preview_value ->> 'invoice_status';

  payment_status_value :=
    preview_value ->> 'payment_status';

  insert into public.invoices (
    id,
    hotel_id,
    folio_id,
    guest_session_id,
    guest_id,
    room_id,

    invoice_number,
    invoice_origin,
    idempotency_key,

    financial_year_start,
    financial_year_label,
    invoice_date,
    currency_code,

    seller_snapshot,
    buyer_snapshot,
    seller_gstin,
    buyer_gstin,
    place_of_supply,
    place_of_supply_code,

    tax_mode,
    room_amount,
    food_amount,
    service_amount,
    manual_amount,
    other_amount,
    discount_type,
    discount_value,
    discount_amount,
    subtotal_amount,
    taxable_amount,
    tax_percent,
    tax_amount,
    cgst_amount,
    sgst_amount,
    igst_amount,
    cess_amount,
    total_amount,

    paid_amount,
    previous_paid_amount,
    pending_amount,
    amount_to_collect,
    payment_status,
    invoice_status,

    checkin_time,
    checkout_time,
    stay_hours,
    stay_nights,

    invoice_notes,
    metadata,
    created_at,
    updated_at
  )
  values (
    invoice_id_value,
    target_hotel_id,
    target_folio_id,
    folio_row.guest_session_id,
    folio_row.guest_id,
    folio_row.room_id,

    number_value ->> 'invoice_number',
    'authoritative',
    normalized_request_id,

    (
      number_value
      ->> 'financial_year_start'
    )::integer,
    number_value
      ->> 'financial_year_label',
    invoice_date_value,
    preview_value ->> 'currency_code',

    preview_value -> 'seller_snapshot',
    preview_value -> 'buyer_snapshot',
    preview_value ->> 'seller_gstin',
    preview_value ->> 'buyer_gstin',
    preview_value ->> 'place_of_supply',
    preview_value ->> 'place_of_supply_code',

    supply_mode_value,
    (
      preview_value
      ->> 'room_amount'
    )::numeric,
    (
      preview_value
      ->> 'food_amount'
    )::numeric,
    (
      preview_value
      ->> 'service_amount'
    )::numeric,
    (
      preview_value
      ->> 'manual_amount'
    )::numeric,
    (
      preview_value
      ->> 'other_amount'
    )::numeric,
    'fixed',
    (
      preview_value
      ->> 'discount_amount'
    )::numeric,
    (
      preview_value
      ->> 'discount_amount'
    )::numeric,
    (
      preview_value
      ->> 'taxable_amount'
    )::numeric,
    (
      preview_value
      ->> 'taxable_amount'
    )::numeric,
    case
      when (
        preview_value
        ->> 'taxable_amount'
      )::numeric > 0
      then round(
        tax_total_value
        * 100
        / (
          preview_value
          ->> 'taxable_amount'
        )::numeric,
        4
      )
      else 0
    end,
    tax_total_value,
    (
      preview_value
      #>> '{tax_breakup,cgst_amount}'
    )::numeric,
    (
      preview_value
      #>> '{tax_breakup,sgst_amount}'
    )::numeric,
    (
      preview_value
      #>> '{tax_breakup,igst_amount}'
    )::numeric,
    (
      preview_value
      #>> '{tax_breakup,cess_amount}'
    )::numeric,
    (
      preview_value
      ->> 'invoice_total'
    )::numeric,

    (
      preview_value
      ->> 'paid_amount'
    )::numeric,
    (
      preview_value
      ->> 'paid_amount'
    )::numeric,
    (
      preview_value
      ->> 'pending_amount'
    )::numeric,
    (
      preview_value
      ->> 'pending_amount'
    )::numeric,
    payment_status_value,
    invoice_status_value,

    (
      preview_value
      ->> 'checkin_time'
    )::timestamptz,
    (
      preview_value
      ->> 'checkout_time'
    )::timestamptz,
    (
      preview_value
      ->> 'stay_hours'
    )::integer,
    (
      preview_value
      ->> 'stay_nights'
    )::integer,

    'Authoritative invoice issued from folio '
      || folio_row.folio_number,
    jsonb_build_object(
      'source', 'folio',
      'request_id', normalized_request_id,
      'migration', '037',
      'preview', preview_value
    ),
    finalized_at_value,
    finalized_at_value
  )
  returning *
  into invoice_row;

  if tax_total_value > 0 then
    insert into public.folio_items (
      hotel_id,
      folio_id,
      item_kind,
      charge_category,
      description,
      quantity,
      unit_amount,
      amount,
      source_table,
      source_id,
      service_at,
      posting_status,
      posted_at,
      posted_by,
      metadata
    )
    values (
      target_hotel_id,
      target_folio_id,
      'tax',
      null,
      'GST for invoice '
        || invoice_row.invoice_number,
      1,
      tax_total_value,
      tax_total_value,
      'invoices',
      invoice_id_value,
      finalized_at_value,
      'posted',
      finalized_at_value,
      actor_id_value,
      jsonb_build_object(
        'invoice_id', invoice_id_value,
        'invoice_number',
          invoice_row.invoice_number,
        'tax_mode', supply_mode_value,
        'tax_breakup',
          preview_value -> 'tax_breakup',
        'request_id', normalized_request_id,
        'source_sync', 'migration_037'
      )
    )
    returning id
    into tax_item_id_value;
  end if;

  for line_record in
    select
      value as line_value
    from jsonb_array_elements(
      preview_value -> 'lines'
    )
  loop
    line_snapshot :=
      line_record.line_value
      || jsonb_build_object(
        'invoice_id', invoice_id_value,
        'invoice_number',
          invoice_row.invoice_number
      );

    insert into public.invoice_items (
      invoice_id,
      hotel_id,
      guest_id,
      room_id,
      item_type,
      description,
      quantity,
      unit_price,
      amount,
      source_id,
      folio_item_id,
      line_number,
      hsn_sac_code,
      taxable_amount,
      tax_rate_id,
      tax_rate_percent,
      cgst_amount,
      sgst_amount,
      igst_amount,
      cess_amount,
      snapshot_json,
      metadata,
      created_at,
      updated_at
    )
    values (
      invoice_id_value,
      target_hotel_id,
      folio_row.guest_id,
      folio_row.room_id,
      line_record.line_value
        ->> 'item_type',
      line_record.line_value
        ->> 'description',
      (
        line_record.line_value
        ->> 'quantity'
      )::numeric,
      (
        line_record.line_value
        ->> 'unit_price'
      )::numeric,
      (
        line_record.line_value
        ->> 'line_total'
      )::numeric,
      (
        line_record.line_value
        ->> 'folio_item_id'
      )::uuid,
      (
        line_record.line_value
        ->> 'folio_item_id'
      )::uuid,
      (
        line_record.line_value
        ->> 'line_number'
      )::integer,
      line_record.line_value
        ->> 'hsn_sac_code',
      (
        line_record.line_value
        ->> 'taxable_amount'
      )::numeric,
      nullif(
        line_record.line_value
          ->> 'tax_rate_id',
        ''
      )::uuid,
      (
        line_record.line_value
        ->> 'tax_rate_percent'
      )::numeric,
      (
        line_record.line_value
        ->> 'cgst_amount'
      )::numeric,
      (
        line_record.line_value
        ->> 'sgst_amount'
      )::numeric,
      (
        line_record.line_value
        ->> 'igst_amount'
      )::numeric,
      (
        line_record.line_value
        ->> 'cess_amount'
      )::numeric,
      line_snapshot,
      jsonb_build_object(
        'gross_amount',
          (
            line_record.line_value
            ->> 'gross_amount'
          )::numeric,
        'discount_amount',
          (
            line_record.line_value
            ->> 'discount_amount'
          )::numeric,
        'charge_category',
          line_record.line_value
            ->> 'charge_category',
        'request_id',
          normalized_request_id,
        'source_sync',
          'migration_037'
      ),
      finalized_at_value,
      finalized_at_value
    );
  end loop;

  update public.invoices
  set
    tax_folio_item_id = tax_item_id_value
  where hotel_id = target_hotel_id
    and id = invoice_id_value;

  snapshot_value :=
    private.day12_build_invoice_snapshot(
      target_hotel_id,
      invoice_id_value,
      finalized_at_value,
      verification_token_value
    );

  snapshot_hash_value :=
    private.day12_hash_snapshot(
      snapshot_value
    );

  update public.invoices
  set
    snapshot_json = snapshot_value,
    snapshot_hash = snapshot_hash_value,
    verification_token =
      verification_token_value,
    finalized_at = finalized_at_value,
    finalized_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'immutable', true,
        'snapshot_hash',
          snapshot_hash_value
      )
  where hotel_id = target_hotel_id
    and id = invoice_id_value
  returning *
  into invoice_row;

  insert into public.invoice_verifications (
    hotel_id,
    invoice_id,
    verification_token,
    snapshot_hash,
    status,
    metadata
  )
  values (
    target_hotel_id,
    invoice_id_value,
    verification_token_value,
    snapshot_hash_value,
    'active',
    jsonb_build_object(
      'authoritative', true,
      'request_id', normalized_request_id,
      'migration', '037'
    )
  );

  insert into public.invoice_events (
    hotel_id,
    invoice_id,
    event_type,
    actor_id,
    event_snapshot,
    metadata
  )
  values (
    target_hotel_id,
    invoice_id_value,
    'invoice.issued',
    actor_id_value,
    snapshot_value,
    jsonb_build_object(
      'request_id', normalized_request_id,
      'invoice_number',
        invoice_row.invoice_number,
      'tax_folio_item_id',
        tax_item_id_value,
      'migration', '037'
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'invoice_id', invoice_row.id,
    'invoice_number',
      invoice_row.invoice_number,
    'financial_year',
      invoice_row.financial_year_label,
    'verification_token',
      invoice_row.verification_token,
    'snapshot_hash',
      invoice_row.snapshot_hash,
    'tax_folio_item_id',
      invoice_row.tax_folio_item_id,
    'taxable_amount',
      invoice_row.taxable_amount,
    'cgst_amount',
      invoice_row.cgst_amount,
    'sgst_amount',
      invoice_row.sgst_amount,
    'igst_amount',
      invoice_row.igst_amount,
    'cess_amount',
      invoice_row.cess_amount,
    'tax_amount',
      invoice_row.tax_amount,
    'total_amount',
      invoice_row.total_amount,
    'paid_amount',
      invoice_row.paid_amount,
    'pending_amount',
      invoice_row.pending_amount,
    'invoice_status',
      invoice_row.invoice_status,
    'request_id', normalized_request_id
  );
end;
$$;


ALTER FUNCTION "public"."issue_folio_invoice"("target_hotel_id" "uuid", "target_folio_id" "uuid", "supply_mode_value" "text", "invoice_date_value" "date", "request_id_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."issue_folio_invoice"("target_hotel_id" "uuid", "target_folio_id" "uuid", "supply_mode_value" "text", "invoice_date_value" "date", "request_id_value" "text") IS 'RPC-only idempotent authoritative invoice issuance with financial-year numbering, tax folio posting, immutable snapshot and QR verification.';



CREATE OR REPLACE FUNCTION "public"."mark_all_notifications_read"("p_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_count integer;
begin
  if v_user_id is null
     or not private.user_has_hotel_access(p_hotel_id)
  then
    raise exception 'Notification inbox access denied.';
  end if;

  update public.notification_recipients nr
  set
    status = 'read',
    read_at = coalesce(nr.read_at, now()),
    updated_at = now()
  where nr.hotel_id = p_hotel_id
    and nr.user_id = v_user_id
    and nr.status = 'unread';

  get diagnostics v_count = row_count;

  update public.notification_deliveries nd
  set
    status = 'read',
    read_at = coalesce(nd.read_at, now()),
    updated_at = now()
  where nd.hotel_id = p_hotel_id
    and nd.recipient_user_id = v_user_id
    and nd.channel = 'in_app'
    and nd.status = 'delivered';

  return jsonb_build_object(
    'hotel_id', p_hotel_id,
    'updated_count', v_count
  );
end;
$$;


ALTER FUNCTION "public"."mark_all_notifications_read"("p_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_notification_read"("p_recipient_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_row public.notification_recipients%rowtype;
begin
  if v_user_id is null then
    raise exception 'Authentication required.';
  end if;

  update public.notification_recipients nr
  set
    status = 'read',
    read_at = coalesce(nr.read_at, now()),
    updated_at = now()
  where nr.id = p_recipient_id
    and nr.user_id = v_user_id
    and private.user_has_hotel_access(nr.hotel_id)
  returning * into v_row;

  if not found then
    raise exception 'Notification was not found or access was denied.';
  end if;

  update public.notification_deliveries nd
  set
    status = case
      when nd.channel = 'in_app' then 'read'
      else nd.status
    end,
    read_at = coalesce(nd.read_at, now()),
    updated_at = now()
  where nd.outbox_id = v_row.outbox_id
    and nd.recipient_user_id = v_user_id
    and nd.channel = 'in_app';

  return jsonb_build_object(
    'notification_id', v_row.id,
    'status', v_row.status,
    'read_at', v_row.read_at
  );
end;
$$;


ALTER FUNCTION "public"."mark_notification_read"("p_recipient_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_active_walkin_guest_room"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "target_room_id" "uuid", "payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_event
    public.guest_session_room_move_events%rowtype;
  session_row public.guest_sessions%rowtype;
  source_room public.rooms%rowtype;
  destination_room public.rooms%rowtype;
  allocation_row public.room_inventory_allocations%rowtype;
  open_history public.stay_room_history%rowtype;
  payment_row public.payments%rowtype;
  refreshed_allocation
    public.room_inventory_allocations%rowtype;
  new_history_id uuid;
  housekeeping_task_id uuid;
  actor_id uuid := auth.uid();
  request_id_value text;
  expected_from_room_id uuid;
  move_reason_value text;
  effective_at_value timestamptz;
  effective_checkout timestamptz;
  movement_type_value text;
  confirm_rate_change boolean;
  requested_room_charge numeric(12,2);
  current_room_charge numeric(12,2);
  final_room_charge numeric(12,2);
  result_value jsonb;
  source_room_before jsonb;
  destination_room_before jsonb;
  session_before jsonb;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'guests.manage',
      'checkin.manage'
    ]::text[]
  ) then
    raise exception
      'Active-stay room movement access denied.';
  end if;

  if target_guest_session_id is null
     or target_room_id is null
  then
    raise exception
      'Guest session and target room are required.';
  end if;

  if payload is null
     or jsonb_typeof(payload) <> 'object'
  then
    raise exception
      'Room-move payload must be a JSON object.';
  end if;

  request_id_value :=
    nullif(trim(payload ->> 'request_id'), '');

  if request_id_value is null
     or length(request_id_value) < 8
  then
    raise exception
      'A stable request_id of at least 8 characters is required.';
  end if;

  begin
    expected_from_room_id :=
      nullif(trim(payload ->> 'expected_from_room_id'), '')::uuid;
  exception
    when others then
      raise exception
        'expected_from_room_id must be a valid UUID.';
  end;

  if expected_from_room_id is null then
    raise exception
      'expected_from_room_id is required for stale-screen protection.';
  end if;

  move_reason_value :=
    nullif(trim(payload ->> 'move_reason'), '');

  if move_reason_value is null
     or length(move_reason_value) < 3
  then
    raise exception
      'A room-move reason of at least 3 characters is required.';
  end if;

  begin
    effective_at_value :=
      coalesce(
        nullif(trim(payload ->> 'effective_at'), '')::timestamptz,
        now()
      );
  exception
    when others then
      raise exception
        'effective_at must be a valid timestamp.';
  end;

  confirm_rate_change :=
    coalesce(
      nullif(trim(payload ->> 'confirm_rate_change'), '')::boolean,
      false
    );

  begin
    requested_room_charge :=
      nullif(trim(payload ->> 'new_room_charge'), '')::numeric;
  exception
    when others then
      raise exception
        'new_room_charge must be a valid amount.';
  end;

  if requested_room_charge is not null
     and requested_room_charge < 0
  then
    raise exception
      'new_room_charge cannot be negative.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:active-room-move:'
      || target_hotel_id::text
      || ':'
      || request_id_value,
      0
    )
  );

  select event_record.*
  into existing_event
  from public.guest_session_room_move_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.idempotency_key = request_id_value
  limit 1;

  if existing_event.id is not null then
    if existing_event.guest_session_id
         is distinct from target_guest_session_id
       or existing_event.to_room_id
         is distinct from target_room_id
    then
      raise exception
        'This request_id was already used for a different room move.';
    end if;

    return coalesce(
      existing_event.result_snapshot,
      '{}'::jsonb
    ) || jsonb_build_object('idempotent', true);
  end if;

  select stay.*
  into session_row
  from public.guest_sessions stay
  where stay.hotel_id = target_hotel_id
    and stay.id = target_guest_session_id
  for update;

  if not found then
    raise exception 'Active guest session was not found.';
  end if;

  if session_row.status <> 'active' then
    raise exception
      'Only an active guest session may be moved.';
  end if;

  if session_row.reservation_id is not null
     or session_row.reservation_room_id is not null
  then
    raise exception
      'This workflow currently accepts direct walk-in stays only. Use the reservation stay workflow for reservation-linked guests.';
  end if;

  if session_row.room_id is null then
    raise exception
      'The active stay has no physical room assigned.';
  end if;

  if session_row.room_id is distinct from
       expected_from_room_id
  then
    raise exception
      'The stay changed after the screen loaded. Refresh and try again.';
  end if;

  if session_row.room_id is not distinct from target_room_id then
    raise exception
      'The target room is already assigned to this stay.';
  end if;

  effective_checkout :=
    coalesce(
      session_row.extended_until,
      session_row.checkout_time
    );

  if effective_at_value < session_row.checkin_time
     or effective_at_value > now() + interval '5 minutes'
  then
    raise exception
      'The movement timestamp is outside the accepted operational window.';
  end if;

  if effective_at_value >= effective_checkout then
    raise exception
      'A stay cannot be moved at or after its effective checkout time.';
  end if;

  -- Lock both room rows in deterministic UUID order.
  perform 1
  from public.rooms room_record
  where room_record.hotel_id = target_hotel_id
    and room_record.id in (
      session_row.room_id,
      target_room_id
    )
  order by room_record.id
  for update;

  select room_record.*
  into source_room
  from public.rooms room_record
  where room_record.hotel_id = target_hotel_id
    and room_record.id = session_row.room_id;

  select room_record.*
  into destination_room
  from public.rooms room_record
  where room_record.hotel_id = target_hotel_id
    and room_record.id = target_room_id;

  if source_room.id is null then
    raise exception
      'The current room no longer belongs to this hotel.';
  end if;

  if destination_room.id is null then
    raise exception
      'The target room does not belong to this hotel.';
  end if;

  if source_room.status <> 'occupied' then
    raise exception
      'The current room is not marked occupied. Refresh and review the stay.';
  end if;

  if destination_room.status <> 'available' then
    raise exception
      'The target room is not currently available.';
  end if;

  select allocation.*
  into allocation_row
  from public.room_inventory_allocations allocation
  where allocation.hotel_id = target_hotel_id
    and allocation.guest_session_id =
        target_guest_session_id
    and allocation.status = 'active'
  for update;

  if not found then
    raise exception
      'The active stay allocation is missing.';
  end if;

  if allocation_row.room_id
       is distinct from source_room.id
  then
    raise exception
      'The active allocation does not match the current room.';
  end if;

  if exists (
    select 1
    from public.room_inventory_allocations other_allocation
    where other_allocation.hotel_id = target_hotel_id
      and other_allocation.room_id = target_room_id
      and other_allocation.status = 'active'
      and other_allocation.guest_session_id
            is distinct from target_guest_session_id
      and other_allocation.stay_dates
            && allocation_row.stay_dates
  ) then
    raise exception
      'The target room is unavailable for the remaining stay dates.';
  end if;

  if exists (
    select 1
    from public.guest_sessions other_stay
    where other_stay.hotel_id = target_hotel_id
      and other_stay.room_id = target_room_id
      and other_stay.status = 'active'
      and other_stay.id <> target_guest_session_id
  ) then
    raise exception
      'Another active stay already occupies the target room.';
  end if;

  select history.*
  into open_history
  from public.stay_room_history history
  where history.hotel_id = target_hotel_id
    and history.guest_session_id =
        target_guest_session_id
    and history.segment_end is null
  for update;

  if not found then
    raise exception
      'The open room-history segment is missing.';
  end if;

  if open_history.room_id is distinct from source_room.id then
    raise exception
      'The open room-history segment does not match the current room.';
  end if;

  if effective_at_value <= open_history.segment_start then
    raise exception
      'The room-move time must be after the current room segment began.';
  end if;

  select payment_record.*
  into payment_row
  from public.payments payment_record
  where payment_record.hotel_id = target_hotel_id
    and payment_record.guest_session_id =
        target_guest_session_id
    and payment_record.payment_type = 'room_charge'
  for update;

  if not found then
    raise exception
      'The stay room-charge record is missing.';
  end if;

  current_room_charge :=
    coalesce(payment_row.amount, 0);

  if destination_room.room_type_id
       is distinct from source_room.room_type_id
  then
    if not confirm_rate_change
       or requested_room_charge is null
    then
      raise exception
        'Changing room type requires an explicitly confirmed new room charge.';
    end if;

    final_room_charge := requested_room_charge;

    movement_type_value :=
      case
        when final_room_charge >= current_room_charge
          then 'upgrade'
        else 'downgrade'
      end;
  else
    if requested_room_charge is not null
       and requested_room_charge
             is distinct from current_room_charge
    then
      raise exception
        'A same-type room move must preserve the existing room charge.';
    end if;

    final_room_charge := current_room_charge;
    movement_type_value := 'move';
  end if;

  source_room_before := to_jsonb(source_room);
  destination_room_before := to_jsonb(destination_room);
  session_before := to_jsonb(session_row);

  update public.stay_room_history
  set segment_end = effective_at_value
  where hotel_id = target_hotel_id
    and id = open_history.id
    and segment_end is null;

  if not found then
    raise exception
      'The active room-history segment changed. Refresh and try again.';
  end if;

  update public.guest_sessions
  set room_id = target_room_id
  where hotel_id = target_hotel_id
    and id = target_guest_session_id
    and status = 'active'
    and room_id = source_room.id;

  if not found then
    raise exception
      'The active stay changed while the room move was processing.';
  end if;

  -- The guest-session allocation trigger updates the one authoritative stay
  -- allocation to the target room. Verify that effect before continuing.
  select allocation.*
  into refreshed_allocation
  from public.room_inventory_allocations allocation
  where allocation.hotel_id = target_hotel_id
    and allocation.guest_session_id =
        target_guest_session_id
    and allocation.status = 'active'
  for update;

  if refreshed_allocation.id is null
     or refreshed_allocation.room_id
          is distinct from target_room_id
  then
    raise exception
      'The stay allocation did not move to the target room.';
  end if;

  update public.payments
  set
    room_id = target_room_id,
    amount = final_room_charge
  where hotel_id = target_hotel_id
    and id = payment_row.id
    and guest_session_id =
        target_guest_session_id;

  if not found then
    raise exception
      'The room-charge record changed while the move was processing.';
  end if;

  update public.rooms
  set status = 'cleaning'
  where hotel_id = target_hotel_id
    and id = source_room.id
    and status = 'occupied';

  if not found then
    raise exception
      'The source room status changed while the move was processing.';
  end if;

  update public.rooms
  set status = 'occupied'
  where hotel_id = target_hotel_id
    and id = destination_room.id
    and status = 'available';

  if not found then
    raise exception
      'The target room status changed while the move was processing.';
  end if;

  insert into public.stay_room_history (
    hotel_id,
    guest_session_id,
    room_id,
    segment_number,
    movement_type,
    segment_start,
    rate_amount,
    move_reason,
    created_by,
    metadata
  )
  values (
    target_hotel_id,
    target_guest_session_id,
    target_room_id,
    open_history.segment_number + 1,
    movement_type_value,
    effective_at_value,
    final_room_charge,
    move_reason_value,
    actor_id,
    jsonb_build_object(
      'source', 'move_active_walkin_guest_room',
      'request_id', request_id_value,
      'from_room_id', source_room.id,
      'from_room_number', source_room.room_number,
      'to_room_id', destination_room.id,
      'to_room_number', destination_room.room_number,
      'previous_segment_id', open_history.id,
      'payment_id', payment_row.id
    )
  )
  returning id into new_history_id;

  select task.id
  into housekeeping_task_id
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.room_id = source_room.id
    and task.task_type = 'room_cleaning'
    and task.status in ('pending', 'in_progress')
  order by task.created_at
  limit 1
  for update;

  if housekeeping_task_id is null then
    insert into public.housekeeping_tasks (
      hotel_id,
      room_id,
      room_number,
      task_type,
      status,
      notes
    )
    values (
      target_hotel_id,
      source_room.id,
      source_room.room_number,
      'room_cleaning',
      'pending',
      format(
        'Room cleaning after active stay moved from Room %s to Room %s.',
        source_room.room_number,
        destination_room.room_number
      )
    )
    returning id into housekeeping_task_id;
  end if;

  result_value := jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'hotel_id', target_hotel_id,
    'guest_session_id', target_guest_session_id,
    'guest_id', session_row.guest_id,
    'request_id', request_id_value,
    'movement_type', movement_type_value,
    'move_reason', move_reason_value,
    'effective_at', effective_at_value,
    'effective_checkout', effective_checkout,
    'from_room', jsonb_build_object(
      'id', source_room.id,
      'room_number', source_room.room_number,
      'room_type_id', source_room.room_type_id,
      'status_before', source_room.status,
      'status_after', 'cleaning'
    ),
    'to_room', jsonb_build_object(
      'id', destination_room.id,
      'room_number', destination_room.room_number,
      'room_type_id', destination_room.room_type_id,
      'status_before', destination_room.status,
      'status_after', 'occupied'
    ),
    'allocation', jsonb_build_object(
      'id', refreshed_allocation.id,
      'room_id', refreshed_allocation.room_id,
      'starts_on', refreshed_allocation.starts_on,
      'ends_on', refreshed_allocation.ends_on,
      'status', refreshed_allocation.status
    ),
    'room_history', jsonb_build_object(
      'closed_segment_id', open_history.id,
      'new_segment_id', new_history_id,
      'new_segment_number',
        open_history.segment_number + 1
    ),
    'room_charge', jsonb_build_object(
      'payment_id', payment_row.id,
      'previous_amount', current_room_charge,
      'current_amount', final_room_charge
    ),
    'housekeeping_task_id', housekeeping_task_id
  );

  insert into public.guest_session_room_move_events (
    hotel_id,
    guest_session_id,
    idempotency_key,
    from_room_id,
    to_room_id,
    movement_type,
    move_reason,
    result_snapshot,
    created_by
  )
  values (
    target_hotel_id,
    target_guest_session_id,
    request_id_value,
    source_room.id,
    destination_room.id,
    movement_type_value,
    move_reason_value,
    result_value,
    actor_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'front_office.active_stay_room_moved',
    'guest_session',
    target_guest_session_id,
    format(
      'Active stay moved from Room %s to Room %s.',
      source_room.room_number,
      destination_room.room_number
    ),
    jsonb_build_object(
      'guest_session', session_before,
      'source_room', source_room_before,
      'target_room', destination_room_before,
      'room_charge', current_room_charge,
      'open_history_segment_id', open_history.id,
      'allocation_id', allocation_row.id
    ),
    result_value,
    jsonb_build_object(
      'request_id', request_id_value,
      'movement_type', movement_type_value,
      'move_reason', move_reason_value,
      'from_room_id', source_room.id,
      'to_room_id', destination_room.id,
      'payment_id', payment_row.id,
      'housekeeping_task_id', housekeeping_task_id
    )
  );

  return result_value;
end;
$$;


ALTER FUNCTION "public"."move_active_walkin_guest_room"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "target_room_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_active_walkin_guest_room"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "target_room_id" "uuid", "payload" "jsonb") IS 'Day 10 authoritative atomic active direct-walk-in room move. Performs stale-screen validation, remaining-stay availability validation, allocation transfer, room-state transition, room-charge preservation or confirmed rate change, room-history segmentation, housekeeping creation, immutable activity evidence and request idempotency in one transaction.';



CREATE OR REPLACE FUNCTION "public"."move_reservation_on_calendar"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "target_reservation_room_id" "uuid", "target_room_id" "uuid", "target_arrival_date" "date", "expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_reservation public.reservations%rowtype;
  current_room public.reservation_rooms%rowtype;
  target_room public.rooms%rowtype;
  original_reservation_room_count integer;
  stay_nights integer;
  target_departure_date date;
  target_quote jsonb;
  quoted_room_subtotal numeric(12,2);
  before_json jsonb;
  after_json jsonb;
  action_name text;
  action_description text;
  next_room_status text;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  if target_room_id is null or target_arrival_date is null then
    raise exception 'Target room and arrival date are required.';
  end if;

  select reservation.*
  into current_reservation
  from public.reservations reservation
  where reservation.id = target_reservation_id
    and reservation.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Reservation not found.';
  end if;

  if current_reservation.status not in ('tentative', 'confirmed') then
    raise exception
      'Only tentative or confirmed reservations may be moved on the calendar.';
  end if;

  if expected_updated_at is not null
     and current_reservation.updated_at is distinct from
       expected_updated_at
  then
    raise exception
      'Reservation changed after the calendar loaded. Refresh and try again.';
  end if;

  select reservation_room.*
  into current_room
  from public.reservation_rooms reservation_room
  where reservation_room.id = target_reservation_room_id
    and reservation_room.hotel_id = target_hotel_id
    and reservation_room.reservation_id = target_reservation_id
  for update;

  if not found then
    raise exception 'Reservation room record not found.';
  end if;

  select count(*)
  into original_reservation_room_count
  from public.reservation_rooms reservation_room
  where reservation_room.hotel_id = target_hotel_id
    and reservation_room.reservation_id = target_reservation_id;

  if original_reservation_room_count > 1
     and target_arrival_date is distinct from
       current_reservation.arrival_date
  then
    raise exception
      'Multi-room date movement requires the group-booking workflow.';
  end if;

  select room.*
  into target_room
  from public.rooms room
  where room.id = target_room_id
    and room.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Target room does not belong to this hotel.';
  end if;

  if target_room.status in ('maintenance', 'out_of_order') then
    raise exception 'Target room is not operational.';
  end if;

  if target_room.room_type_id is distinct from
     current_room.room_type_id
  then
    raise exception
      'Drag-and-drop cannot change room type or rate. Use Reservation Edit.';
  end if;

  if not exists (
    select 1
    from public.room_types room_type
    where room_type.id = current_room.room_type_id
      and room_type.hotel_id = target_hotel_id
      and current_reservation.adults <= room_type.max_adults
      and current_reservation.children <= room_type.max_children
      and current_reservation.adults + current_reservation.children <=
        room_type.max_occupancy
  ) then
    raise exception 'Guest count exceeds the target room capacity.';
  end if;

  stay_nights :=
    current_reservation.departure_date
    - current_reservation.arrival_date;

  if stay_nights < 1 then
    raise exception 'Reservation stay length is invalid.';
  end if;

  target_departure_date := target_arrival_date + stay_nights;

  if target_departure_date - target_arrival_date > 365 then
    raise exception 'Reservation movement exceeds the maximum stay length.';
  end if;

  if current_room.rate_plan_id is null then
    raise exception
      'Calendar movement requires an assigned rate plan.';
  end if;

  target_quote := public.get_reservation_rate_quote(
    target_hotel_id,
    current_room.rate_plan_id,
    target_arrival_date,
    target_departure_date,
    current_room.adults,
    current_room.children
  );

  quoted_room_subtotal :=
    (target_quote->>'room_subtotal')::numeric(12,2);

  if quoted_room_subtotal is distinct from current_room.room_subtotal then
    raise exception
      'Target dates change the reservation rate. Use Reservation Edit to confirm the new amount.';
  end if;

  if not private.calendar_room_is_available(
    target_hotel_id,
    target_room_id,
    target_arrival_date,
    target_departure_date,
    current_room.id,
    null
  ) then
    raise exception
      'Target room is unavailable for the proposed dates.';
  end if;

  if current_room.room_id is not distinct from target_room_id
     and current_reservation.arrival_date is not distinct from
       target_arrival_date
  then
    raise exception 'No room or date change was proposed.';
  end if;

  before_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  action_name := case
    when current_room.room_id is null then
      'reservation.room_assigned'
    when current_room.room_id is distinct from target_room_id
      and current_reservation.arrival_date is distinct from
        target_arrival_date
      then 'reservation.calendar_moved'
    when current_room.room_id is distinct from target_room_id
      then 'reservation.room_reassigned'
    when current_reservation.arrival_date is distinct from
      target_arrival_date
      then 'reservation.dates_moved'
    else 'reservation.calendar_moved'
  end;

  action_description := format(
    'Reservation %s moved from room %s / %s to room %s / %s.',
    current_reservation.reservation_number,
    coalesce(
      (
        select room.room_number
        from public.rooms room
        where room.id = current_room.room_id
          and room.hotel_id = target_hotel_id
      ),
      'unassigned'
    ),
    current_reservation.arrival_date,
    target_room.room_number,
    target_arrival_date
  );

  -- Release the old allocation before updating dates and physical room.
  update public.reservation_rooms
  set status = 'released'
  where id = current_room.id
    and hotel_id = target_hotel_id;

  update public.reservations
  set
    arrival_date = target_arrival_date,
    departure_date = target_departure_date,
    updated_by = auth.uid(),
    updated_at = now()
  where id = target_reservation_id
    and hotel_id = target_hotel_id;

  next_room_status := case
    when current_reservation.status = 'confirmed'
      then 'confirmed'
    else 'held'
  end;

  update public.reservation_rooms
  set
    room_id = target_room_id,
    status = next_room_status,
    updated_at = now()
  where id = current_room.id
    and hotel_id = target_hotel_id;

  after_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    action_name,
    'reservation',
    target_reservation_id,
    action_description,
    before_json,
    after_json,
    jsonb_build_object(
      'reservation_room_id', current_room.id,
      'from_room_id', current_room.room_id,
      'to_room_id', target_room_id,
      'from_arrival_date', current_reservation.arrival_date,
      'to_arrival_date', target_arrival_date,
      'from_departure_date', current_reservation.departure_date,
      'to_departure_date', target_departure_date,
      'stay_nights', stay_nights
    )
  );

  return after_json;
end;
$$;


ALTER FUNCTION "public"."move_reservation_on_calendar"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "target_reservation_room_id" "uuid", "target_room_id" "uuid", "target_arrival_date" "date", "expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_cashier_shift"("h" "uuid", "opening_cash_value" numeric, "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  request_key text;
  s public.cashier_shifts%rowtype;
  open_s public.cashier_shifts%rowtype;
  n text;
begin
  if not private.user_has_any_permission(h,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Cashier shift opening access denied.';
  end if;
  actor:=private.day11_require_current_actor();
  request_key:=nullif(trim(request_id_value),'');
  if request_key is null or length(request_key)<8 then raise exception 'Request ID of at least eight characters required.'; end if;
  if opening_cash_value is null or opening_cash_value<0 then raise exception 'Opening cash cannot be negative.'; end if;
  select * into s from public.cashier_shifts where hotel_id=h and open_idempotency_key=request_key;
  if s.id is not null then return jsonb_build_object('ok',true,'idempotent',true,'shift',to_jsonb(s)); end if;
  select * into open_s from public.cashier_shifts where hotel_id=h and opened_by=actor and status='open';
  if open_s.id is not null then raise exception 'Current cashier already has an open shift.'; end if;
  n:='CS/'||to_char(now() at time zone (select timezone from public.hotels where id=h),'YYYYMMDD-HH24MISS')
     ||'/'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));
  insert into public.cashier_shifts(hotel_id,shift_number,status,opened_at,opened_by,opening_cash,open_idempotency_key,metadata)
  values(h,n,'open',now(),actor,opening_cash_value,request_key,jsonb_build_object('request_id',request_key,'day',12))
  returning * into s;
  return jsonb_build_object('ok',true,'idempotent',false,'shift',to_jsonb(s));
end;
$$;


ALTER FUNCTION "public"."open_cashier_shift"("h" "uuid", "opening_cash_value" numeric, "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_guest_food_order"("p_hotel_slug" "text", "p_access_token" "text", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_context record;
  v_items jsonb;
  v_request_key text;
  v_existing public.food_orders%rowtype;
  v_order_id uuid;
  v_line jsonb;
  v_item public.menu_items%rowtype;
  v_category public.menu_categories%rowtype;
  v_quantity integer;
  v_modifier_ids jsonb;
  v_group record;
  v_selected_count integer;
  v_base_gross numeric(14,2);
  v_modifier_gross numeric(14,2);
  v_base_line numeric(14,2);
  v_modifier_line numeric(14,2);
  v_tax_line numeric(14,2);
  v_line_total numeric(14,2);
  v_gross_unit numeric(14,2);
  v_subtotal numeric(14,2) := 0;
  v_modifier_total numeric(14,2) := 0;
  v_tax_total numeric(14,2) := 0;
  v_total numeric(14,2) := 0;
  v_total_quantity integer := 0;
  v_order_item_id uuid;
  v_modifier record;
  v_line_number integer := 0;
begin
  select * into v_context
  from private.day15_guest_context(
    p_hotel_slug,
    p_access_token,
    true
  );

  if jsonb_typeof(p_items) = 'array' then
    v_items := p_items;
    v_request_key := 'legacy-' || encode(
      extensions.digest(
        convert_to(
          v_context.guest_session_id::text || ':' || p_items::text,
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    );
  elsif jsonb_typeof(p_items) = 'object' then
    v_items := p_items -> 'items';
    v_request_key := nullif(trim(p_items ->> 'request_id'), '');
  else
    raise exception 'The food order payload is invalid.';
  end if;

  if jsonb_typeof(v_items) <> 'array'
     or jsonb_array_length(v_items) < 1
     or jsonb_array_length(v_items) > 20
  then
    raise exception 'The food order must contain between 1 and 20 lines.';
  end if;

  if v_request_key is null
     or length(v_request_key) < 8
     or length(v_request_key) > 160
  then
    raise exception 'A valid food order request identifier is required.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:day15:food:' || v_context.hotel_id::text || ':' || v_request_key,
      0
    )
  );

  select fo.* into v_existing
  from public.food_orders fo
  where fo.hotel_id = v_context.hotel_id
    and fo.idempotency_key = v_request_key;

  if found then
    return jsonb_build_object(
      'result', 'FOOD ORDER ALREADY CREATED',
      'idempotent', true,
      'order_id', v_existing.id,
      'total_amount', v_existing.total_amount,
      'currency_code', v_existing.currency_code,
      'order_status', v_existing.order_status
    );
  end if;

  if (
    select count(*)
    from public.food_orders fo
    where fo.hotel_id = v_context.hotel_id
      and fo.guest_session_id = v_context.guest_session_id
      and fo.created_at > now() - interval '1 minute'
  ) >= 3 then
    raise exception 'Too many food orders were submitted. Please wait and try again.';
  end if;

  insert into public.food_orders (
    hotel_id,
    room_id,
    guest_id,
    guest_session_id,
    subtotal_amount,
    modifier_amount,
    tax_amount,
    total_amount,
    currency_code,
    idempotency_key,
    payment_status,
    order_status,
    estimated_minutes,
    estimated_delivery_time
  ) values (
    v_context.hotel_id,
    v_context.room_id,
    v_context.guest_id,
    v_context.guest_session_id,
    0,
    0,
    0,
    0,
    v_context.currency_code,
    v_request_key,
    'pending',
    'pending',
    null,
    null
  ) returning id into v_order_id;

  for v_line in
    select value
    from jsonb_array_elements(v_items)
  loop
    v_line_number := v_line_number + 1;
    v_quantity := coalesce((v_line ->> 'quantity')::integer, 0);
    v_modifier_ids := coalesce(v_line -> 'modifier_ids', '[]'::jsonb);

    if v_quantity < 1 or v_quantity > 20 then
      raise exception 'Food order line % has an invalid quantity.', v_line_number;
    end if;

    if jsonb_typeof(v_modifier_ids) <> 'array' then
      raise exception 'Food order line % has invalid modifiers.', v_line_number;
    end if;

    select mi.* into v_item
    from public.menu_items mi
    where mi.id = (v_line ->> 'menu_item_id')::uuid
      and mi.hotel_id = v_context.hotel_id
      and mi.is_available
      and mi.archived_at is null
    for share;

    if not found then
      raise exception 'A selected menu item is unavailable.';
    end if;

    select mc.* into v_category
    from public.menu_categories mc
    where mc.id = v_item.category_id
      and mc.hotel_id = v_context.hotel_id
    for share;

    if not found
       or not private.day15_menu_item_available_now(
         v_category,
         v_context.hotel_timezone
       )
    then
      raise exception '% is not available at this time.', v_item.item_name;
    end if;

    v_modifier_line := 0;

    for v_group in
      select mg.*
      from public.menu_item_modifier_groups mg
      where mg.hotel_id = v_context.hotel_id
        and mg.menu_item_id = v_item.id
        and mg.is_active
      order by mg.sort_order, mg.id
    loop
      select count(*) into v_selected_count
      from jsonb_array_elements_text(v_modifier_ids) selected(id_text)
      join public.menu_item_modifiers mm
        on mm.id = selected.id_text::uuid
       and mm.hotel_id = v_context.hotel_id
       and mm.modifier_group_id = v_group.id
       and mm.is_available;

      if v_selected_count < v_group.min_selections
         or v_selected_count > v_group.max_selections
      then
        raise exception 'Select between % and % option(s) for %.',
          v_group.min_selections,
          v_group.max_selections,
          v_group.name;
      end if;
    end loop;

    if exists (
      select 1
      from jsonb_array_elements_text(v_modifier_ids) selected(id_text)
      left join public.menu_item_modifiers mm
        on mm.id = selected.id_text::uuid
       and mm.hotel_id = v_context.hotel_id
       and mm.is_available
      left join public.menu_item_modifier_groups mg
        on mg.id = mm.modifier_group_id
       and mg.hotel_id = v_context.hotel_id
       and mg.menu_item_id = v_item.id
       and mg.is_active
      where mm.id is null or mg.id is null
    ) then
      raise exception 'One or more selected modifiers are invalid or unavailable.';
    end if;

    select coalesce(sum(mm.price_delta), 0) * v_quantity
    into v_modifier_gross
    from jsonb_array_elements_text(v_modifier_ids) selected(id_text)
    join public.menu_item_modifiers mm
      on mm.id = selected.id_text::uuid
     and mm.hotel_id = v_context.hotel_id;

    v_base_gross := round(v_item.price * v_quantity, 2);

    if v_item.tax_inclusive and v_item.tax_rate > 0 then
      v_base_line := round(v_base_gross / (1 + v_item.tax_rate / 100), 2);
      v_modifier_line := round(v_modifier_gross / (1 + v_item.tax_rate / 100), 2);
      v_line_total := round(v_base_gross + v_modifier_gross, 2);
      v_tax_line := round(v_line_total - v_base_line - v_modifier_line, 2);
    else
      v_base_line := v_base_gross;
      v_modifier_line := v_modifier_gross;
      v_tax_line := round(
        (v_base_line + v_modifier_line) * v_item.tax_rate / 100,
        2
      );
      v_line_total := round(v_base_line + v_modifier_line + v_tax_line, 2);
    end if;

    v_gross_unit := round(v_line_total / v_quantity, 2);
    -- Preserve the legacy quantity * price equation exactly, then assign any
    -- paise rounding difference to the tax snapshot so the header equation
    -- remains exact too.
    v_line_total := round(v_gross_unit * v_quantity, 2);
    v_base_line := round(v_line_total - v_modifier_line - v_tax_line, 2);

    insert into public.food_order_items (
      hotel_id,
      order_id,
      menu_item_id,
      quantity,
      price,
      item_name_snapshot,
      unit_price,
      modifier_amount,
      tax_rate,
      tax_amount,
      line_total
    ) values (
      v_context.hotel_id,
      v_order_id,
      v_item.id,
      v_quantity,
      v_gross_unit,
      v_item.item_name,
      v_item.price,
      v_modifier_line,
      v_item.tax_rate,
      v_tax_line,
      v_line_total
    ) returning id into v_order_item_id;

    for v_modifier in
      select mm.*
      from jsonb_array_elements_text(v_modifier_ids) selected(id_text)
      join public.menu_item_modifiers mm
        on mm.id = selected.id_text::uuid
       and mm.hotel_id = v_context.hotel_id
    loop
      insert into public.food_order_item_modifiers (
        hotel_id,
        food_order_item_id,
        modifier_id,
        modifier_name_snapshot,
        price_delta
      ) values (
        v_context.hotel_id,
        v_order_item_id,
        v_modifier.id,
        v_modifier.name,
        v_modifier.price_delta
      );
    end loop;

    v_subtotal := v_subtotal + v_base_line;
    v_modifier_total := v_modifier_total + v_modifier_line;
    v_tax_total := v_tax_total + v_tax_line;
    v_total := v_total + v_line_total;
    v_total_quantity := v_total_quantity + v_quantity;
  end loop;

  if v_total_quantity > 50 then
    raise exception 'The food order quantity is too large.';
  end if;

  update public.food_orders
  set
    subtotal_amount = round(v_subtotal, 2),
    modifier_amount = round(v_modifier_total, 2),
    tax_amount = round(v_tax_total, 2),
    total_amount = round(v_total, 2)
  where id = v_order_id
    and hotel_id = v_context.hotel_id;

  insert into public.food_order_events (
    hotel_id,
    food_order_id,
    event_type,
    from_status,
    to_status,
    idempotency_key,
    metadata
  ) values (
    v_context.hotel_id,
    v_order_id,
    'order_submitted',
    null,
    'pending',
    'submitted:' || v_request_key,
    jsonb_build_object(
      'request_id', v_request_key,
      'total_quantity', v_total_quantity,
      'subtotal_amount', round(v_subtotal, 2),
      'modifier_amount', round(v_modifier_total, 2),
      'tax_amount', round(v_tax_total, 2),
      'total_amount', round(v_total, 2)
    )
  );

  insert into public.notifications (
    hotel_id,
    room_id,
    guest_id,
    type,
    title,
    message,
    is_read
  ) values (
    v_context.hotel_id,
    v_context.room_id,
    v_context.guest_id,
    'food_order',
    'New Food Order',
    'Room ' || v_context.room_number || ' placed a food order for '
      || round(v_total, 2)::text,
    false
  );

  perform private.day15_notify_guest(
    v_context.hotel_id,
    v_context.guest_session_id,
    v_context.room_id,
    v_context.guest_id,
    'food_order',
    v_order_id,
    'submitted',
    'Order received',
    'Your food order has been sent to the kitchen.',
    jsonb_build_object('order_status', 'pending')
  );

  return jsonb_build_object(
    'result', 'FOOD ORDER CREATED',
    'idempotent', false,
    'order_id', v_order_id,
    'subtotal_amount', round(v_subtotal, 2),
    'modifier_amount', round(v_modifier_total, 2),
    'tax_amount', round(v_tax_total, 2),
    'total_amount', round(v_total, 2),
    'currency_code', v_context.currency_code,
    'order_status', 'pending'
  );
exception
  when unique_violation then
    select fo.* into v_existing
    from public.food_orders fo
    where fo.hotel_id = v_context.hotel_id
      and fo.idempotency_key = v_request_key;

    if found then
      return jsonb_build_object(
        'result', 'FOOD ORDER ALREADY CREATED',
        'idempotent', true,
        'order_id', v_existing.id,
        'total_amount', v_existing.total_amount,
        'currency_code', v_existing.currency_code,
        'order_status', v_existing.order_status
      );
    end if;
    raise;
end;
$$;


ALTER FUNCTION "public"."place_guest_food_order"("p_hotel_slug" "text", "p_access_token" "text", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_folio_collection"("target_hotel_id" "uuid", "target_folio_id" "uuid", "amount_value" numeric, "payment_method_value" "text", "transaction_reference_value" "text" DEFAULT NULL::"text", "provider_value" "text" DEFAULT NULL::"text", "provider_payment_id_value" "text" DEFAULT NULL::"text", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
begin
  if not private.user_has_any_permission(target_hotel_id,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Collection posting access denied.';
  end if;
  actor_id_value := private.day11_require_current_actor();
  request_key := coalesce(nullif(trim(request_id_value),''),gen_random_uuid()::text);

  return private.day11_post_collection(
    target_hotel_id,target_folio_id,amount_value,payment_method_value,gen_random_uuid(),
    transaction_reference_value,provider_value,provider_payment_id_value,null,
    'settlement_rpc',null,'collection:' || request_key,now(),actor_id_value,
    jsonb_build_object('request_id',request_key,'posting_mode','single')
  ) || jsonb_build_object('request_id',request_key);
end;
$$;


ALTER FUNCTION "public"."post_folio_collection"("target_hotel_id" "uuid", "target_folio_id" "uuid", "amount_value" numeric, "payment_method_value" "text", "transaction_reference_value" "text", "provider_value" "text", "provider_payment_id_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_folio_split_collection"("target_hotel_id" "uuid", "target_folio_id" "uuid", "collection_lines" "jsonb", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  request_hash text;
  line_count integer;
  existing_count integer;
  existing_hash_count integer;
  group_id_value uuid;
  total_value numeric(14,2) := 0;
  line_record record;
  line_amount numeric(14,2);
  line_method text;
  line_result jsonb;
  result_rows jsonb := '[]'::jsonb;
  folio_row public.folios%rowtype;
begin
  if not private.user_has_any_permission(target_hotel_id,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Split collection posting access denied.';
  end if;
  actor_id_value := private.day11_require_current_actor();

  if jsonb_typeof(collection_lines) <> 'array' then raise exception 'collection_lines must be a JSON array.'; end if;
  line_count := jsonb_array_length(collection_lines);
  if line_count < 2 then raise exception 'Split collection requires at least two payment lines.'; end if;

  request_key := coalesce(nullif(trim(request_id_value),''),gen_random_uuid()::text);
  request_hash := md5(collection_lines::text);

  perform pg_advisory_xact_lock(hashtextextended(
    'stayqr:folio-split:' || target_hotel_id::text || ':' || target_folio_id::text || ':' || request_key,0
  ));

  select count(*),
         count(*) filter (where collection.metadata ->> 'split_request_hash' = request_hash),
         (min(collection.collection_group_id::text))::uuid
  into existing_count, existing_hash_count, group_id_value
  from public.folio_collections collection
  where collection.hotel_id = target_hotel_id
    and collection.folio_id = target_folio_id
    and collection.metadata ->> 'split_request_id' = request_key;

  if existing_count > 0 then
    if existing_count <> line_count or existing_hash_count <> existing_count then
      raise exception 'Split collection idempotency key conflicts with different lines.';
    end if;
    select coalesce(jsonb_agg(to_jsonb(collection) order by (collection.metadata ->> 'split_line_number')::integer),'[]'::jsonb)
    into result_rows
    from public.folio_collections collection
    where collection.hotel_id = target_hotel_id
      and collection.folio_id = target_folio_id
      and collection.metadata ->> 'split_request_id' = request_key;
    return jsonb_build_object('ok',true,'idempotent',true,'request_id',request_key,'request_hash',request_hash,'collection_group_id',group_id_value,'collections',result_rows);
  end if;

  for line_record in
    select element.value as line, element.ordinality::integer as line_number
    from jsonb_array_elements(collection_lines) with ordinality as element(value,ordinality)
  loop
    begin
      line_amount := (line_record.line ->> 'amount')::numeric;
    exception when others then
      raise exception 'Split line % has invalid amount.',line_record.line_number;
    end;
    if line_amount <= 0 then raise exception 'Split line % amount must be positive.',line_record.line_number; end if;
    line_method := nullif(trim(line_record.line ->> 'payment_method'),'');
    if line_method is null then raise exception 'Split line % payment_method is required.',line_record.line_number; end if;
    total_value := total_value + line_amount;
  end loop;

  select folio.* into folio_row
  from public.folios folio
  where folio.hotel_id = target_hotel_id and folio.id = target_folio_id
  for update;
  if not found then raise exception 'Folio was not found.'; end if;
  if total_value > folio_row.balance_amount then
    raise exception 'Split collection total % exceeds open balance %.',total_value,folio_row.balance_amount;
  end if;

  group_id_value := gen_random_uuid();
  for line_record in
    select element.value as line, element.ordinality::integer as line_number
    from jsonb_array_elements(collection_lines) with ordinality as element(value,ordinality)
  loop
    line_result := private.day11_post_collection(
      target_hotel_id,target_folio_id,(line_record.line ->> 'amount')::numeric,
      line_record.line ->> 'payment_method',group_id_value,
      line_record.line ->> 'transaction_reference',line_record.line ->> 'provider',
      line_record.line ->> 'provider_payment_id',null,'settlement_rpc',null,
      'split-collection:' || request_key || ':' || line_record.line_number::text,
      now(),actor_id_value,jsonb_build_object(
        'request_id',request_key,'posting_mode','split','split_request_id',request_key,
        'split_request_hash',request_hash,'split_line_number',line_record.line_number,
        'split_line_count',line_count
      )
    );
    result_rows := result_rows || jsonb_build_array(line_result -> 'collection');
  end loop;

  return jsonb_build_object('ok',true,'idempotent',false,'request_id',request_key,'request_hash',request_hash,'collection_group_id',group_id_value,'total_amount',total_value,'collections',result_rows);
end;
$$;


ALTER FUNCTION "public"."post_folio_split_collection"("target_hotel_id" "uuid", "target_folio_id" "uuid", "collection_lines" "jsonb", "request_id_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_folio_split_collection"("target_hotel_id" "uuid", "target_folio_id" "uuid", "collection_lines" "jsonb", "request_id_value" "text") IS 'Idempotent partial split/multi-method collection group; aggregate amount cannot exceed open folio balance.';



CREATE OR REPLACE FUNCTION "public"."post_food_order_to_folio"("p_hotel_id" "uuid", "p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.food_orders%rowtype;
  v_sync jsonb;
begin
  if not private.user_has_any_permission(
    p_hotel_id,
    array['foodorders.manage','payments.manage','invoices.manage']
  ) then
    raise exception 'Food order folio posting access denied.';
  end if;

  select fo.* into v_order
  from public.food_orders fo
  where fo.hotel_id = p_hotel_id
    and fo.id = p_order_id
  for update;

  if not found then
    raise exception 'Food order was not found in the selected hotel.';
  end if;

  if v_order.order_status <> 'delivered' then
    raise exception 'Only delivered food orders can post to the folio.';
  end if;

  v_sync := private.day11_sync_food_order(v_order.id);

  if coalesce((v_sync ->> 'skipped')::boolean, false) then
    raise exception 'Food order folio posting failed: %.',
      coalesce(v_sync ->> 'reason', 'unknown reason');
  end if;

  update public.food_orders
  set
    folio_item_id = nullif(v_sync ->> 'folio_item_id', '')::uuid,
    folio_posted_at = coalesce(folio_posted_at, now())
  where hotel_id = v_order.hotel_id
    and id = v_order.id;

  return v_sync || jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."post_food_order_to_folio"("p_hotel_id" "uuid", "p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_service_request_charge"("target_hotel_id" "uuid", "target_request_id" "uuid", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request_hotel_id uuid;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'payments.manage',
      'invoices.manage',
      'checkout.manage'
    ]::text[]
  ) then
    raise exception 'Service charge posting access denied.';
  end if;

  select request.hotel_id
  into request_hotel_id
  from public.service_requests request
  where request.id = target_request_id;

  if request_hotel_id is null
     or request_hotel_id <> target_hotel_id
  then
    raise exception
      'Service request was not found in the selected hotel.';
  end if;

  return private.day11_post_service_request_charge(
    target_request_id,
    true,
    coalesce(
      nullif(trim(request_id_value), ''),
      gen_random_uuid()::text
    )
  );
end;
$$;


