CREATE OR REPLACE FUNCTION "public"."process_notification_outbox"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_delivery record;
  v_adapter public.email_adapter_configs%rowtype;
  v_attempt integer;
  v_processed integer := 0;
  v_ready integer := 0;
  v_failed integer := 0;
begin
  if not private.is_platform_admin() then
    raise exception 'Notification dispatcher access denied.';
  end if;

  for v_delivery in
    select nd.*
    from public.notification_deliveries nd
    where nd.status in ('pending', 'retrying')
      and (
        nd.next_attempt_at is null
        or nd.next_attempt_at <= now()
      )
    order by nd.created_at
    limit greatest(1, least(coalesce(p_limit, 50), 500))
    for update skip locked
  loop
    v_processed := v_processed + 1;
    v_attempt := v_delivery.attempt_count + 1;

    if v_delivery.channel = 'manual_whatsapp' then
      update public.notification_deliveries nd
      set
        status = 'manual_ready',
        attempt_count = v_attempt,
        manual_action_url = case
          when nullif(trim(v_delivery.address_snapshot), '') is null
            then null
          else
            'https://wa.me/' ||
            regexp_replace(v_delivery.address_snapshot, '[^0-9]', '', 'g') ||
            '?text=' ||
            replace(v_delivery.rendered_body, ' ', '%20')
        end,
        updated_at = now()
      where nd.id = v_delivery.id;

      insert into public.notification_delivery_attempts (
        delivery_id,
        hotel_id,
        attempt_number,
        attempt_status,
        adapter_key,
        request_metadata,
        response_metadata,
        started_at,
        completed_at,
        created_at
      ) values (
        v_delivery.id,
        v_delivery.hotel_id,
        v_attempt,
        'prepared',
        'manual_whatsapp',
        jsonb_build_object('channel', 'manual_whatsapp'),
        jsonb_build_object('result', 'manual_ready'),
        now(),
        now(),
        now()
      )
      on conflict (delivery_id, attempt_number) do nothing;

      v_ready := v_ready + 1;
      continue;
    end if;

    if v_delivery.channel = 'email' then
      select *
      into v_adapter
      from public.email_adapter_configs eac
      where eac.is_enabled
        and (eac.hotel_id = v_delivery.hotel_id or eac.hotel_id is null)
      order by
        case when eac.hotel_id = v_delivery.hotel_id then 0 else 1 end,
        eac.updated_at desc
      limit 1;

      if found then
        update public.notification_deliveries nd
        set
          status = 'adapter_ready',
          attempt_count = v_attempt,
          last_error_code = null,
          last_error_message = null,
          updated_at = now()
        where nd.id = v_delivery.id;

        insert into public.notification_delivery_attempts (
          delivery_id,
          hotel_id,
          attempt_number,
          attempt_status,
          adapter_key,
          request_metadata,
          response_metadata,
          started_at,
          completed_at,
          created_at
        ) values (
          v_delivery.id,
          v_delivery.hotel_id,
          v_attempt,
          'prepared',
          v_adapter.adapter_key,
          jsonb_build_object(
            'provider', v_adapter.provider,
            'endpoint_name', v_adapter.endpoint_name,
            'secret_reference', v_adapter.secret_reference
          ),
          jsonb_build_object('result', 'adapter_ready'),
          now(),
          now(),
          now()
        )
        on conflict (delivery_id, attempt_number) do nothing;

        v_ready := v_ready + 1;
      else
        insert into public.notification_delivery_attempts (
          delivery_id,
          hotel_id,
          attempt_number,
          attempt_status,
          error_code,
          error_message,
          request_metadata,
          response_metadata,
          started_at,
          completed_at,
          created_at
        ) values (
          v_delivery.id,
          v_delivery.hotel_id,
          v_attempt,
          'failed',
          'EMAIL_ADAPTER_NOT_CONFIGURED',
          'No enabled email adapter is configured.',
          jsonb_build_object('channel', 'email'),
          '{}'::jsonb,
          now(),
          now(),
          now()
        )
        on conflict (delivery_id, attempt_number) do nothing;

        if v_attempt >= v_delivery.max_attempts then
          update public.notification_deliveries nd
          set
            status = 'failed',
            attempt_count = v_attempt,
            last_error_code = 'EMAIL_ADAPTER_NOT_CONFIGURED',
            last_error_message = 'No enabled email adapter is configured.',
            next_attempt_at = null,
            updated_at = now()
          where nd.id = v_delivery.id;

          insert into public.notification_dead_letters (
            delivery_id,
            outbox_id,
            hotel_id,
            reason_code,
            reason_message,
            payload_snapshot,
            created_at
          ) values (
            v_delivery.id,
            v_delivery.outbox_id,
            v_delivery.hotel_id,
            'EMAIL_ADAPTER_NOT_CONFIGURED',
            'No enabled email adapter is configured after maximum retries.',
            jsonb_build_object(
              'address', v_delivery.address_snapshot,
              'title', v_delivery.rendered_title,
              'body', v_delivery.rendered_body
            ),
            now()
          )
          on conflict (delivery_id) do nothing;
        else
          update public.notification_deliveries nd
          set
            status = 'retrying',
            attempt_count = v_attempt,
            last_error_code = 'EMAIL_ADAPTER_NOT_CONFIGURED',
            last_error_message = 'No enabled email adapter is configured.',
            next_attempt_at = now() + make_interval(
              mins => least(60, 5 * v_attempt)
            ),
            updated_at = now()
          where nd.id = v_delivery.id;
        end if;

        v_failed := v_failed + 1;
      end if;
    end if;
  end loop;

  update public.notification_outbox nox
  set
    pending_delivery_count = summary.pending_count,
    completed_delivery_count = summary.completed_count,
    failed_delivery_count = summary.failed_count,
    status = case
      when summary.failed_count > 0 and summary.pending_count = 0
        then 'partial'
      when summary.pending_count > 0
        then 'pending'
      else 'completed'
    end,
    updated_at = now()
  from (
    select
      nd.outbox_id,
      count(*) filter (
        where nd.status in ('pending', 'retrying')
      )::integer as pending_count,
      count(*) filter (
        where nd.status in (
          'adapter_ready',
          'manual_ready',
          'delivered',
          'read',
          'skipped'
        )
      )::integer as completed_count,
      count(*) filter (
        where nd.status = 'failed'
      )::integer as failed_count
    from public.notification_deliveries nd
    group by nd.outbox_id
  ) summary
  where nox.id = summary.outbox_id;

  return jsonb_build_object(
    'processed', v_processed,
    'adapter_or_manual_ready', v_ready,
    'failed_or_retrying', v_failed
  );
end;
$$;


ALTER FUNCTION "public"."process_notification_outbox"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_guest_guide"("p_hotel_id" "uuid", "p_publish_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_next_version integer;
  v_snapshot jsonb;
  v_version public.guest_guide_versions%rowtype;
begin
  if not private.user_has_permission(
    p_hotel_id,
    'hotel.manage'
  ) then
    raise exception 'Guest guide publish denied.';
  end if;

  perform 1
  from public.guest_guide_settings
  where hotel_id = p_hotel_id
  for update;

  select coalesce(max(version_number), 0) + 1
  into v_next_version
  from public.guest_guide_versions
  where hotel_id = p_hotel_id;

  v_snapshot :=
    private.day14_build_guide_snapshot(p_hotel_id);

  insert into public.guest_guide_versions (
    hotel_id,
    version_number,
    snapshot,
    publish_note,
    published_by
  )
  values (
    p_hotel_id,
    v_next_version,
    v_snapshot,
    nullif(trim(coalesce(p_publish_note, '')), ''),
    auth.uid()
  )
  returning *
  into v_version;

  update public.guest_guide_settings
  set
    publish_status = 'published',
    published_version = v_next_version,
    published_at = v_version.published_at,
    published_by = auth.uid(),
    updated_by = auth.uid(),
    updated_at = now()
  where hotel_id = p_hotel_id;

  return jsonb_build_object(
    'result', 'GUEST GUIDE PUBLISHED',
    'version_id', v_version.id,
    'version_number', v_version.version_number,
    'published_at', v_version.published_at
  );
end;
$$;


ALTER FUNCTION "public"."publish_guest_guide"("p_hotel_id" "uuid", "p_publish_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_notification_template"("p_hotel_id" "uuid", "p_event_key" "text", "p_channel" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_row public.notification_templates%rowtype;
  v_next_version integer;
  v_locale text;
begin
  if v_user_id is null
     or not private.day17_can_manage_hotel(p_hotel_id)
  then
    raise exception 'Notification template management denied.';
  end if;

  if p_channel not in ('in_app', 'email', 'manual_whatsapp') then
    raise exception 'Unsupported notification channel.';
  end if;

  if not exists (
    select 1
    from public.notification_event_catalog nec
    where nec.event_key = p_event_key
      and nec.is_active
  ) then
    raise exception 'Unsupported notification event key.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Template payload must be a JSON object.';
  end if;

  if nullif(trim(p_payload ->> 'title_template'), '') is null
     or nullif(trim(p_payload ->> 'body_template'), '') is null
  then
    raise exception 'Template title and body are required.';
  end if;

  v_locale := coalesce(
    nullif(trim(p_payload ->> 'locale'), ''),
    'en'
  );

  select coalesce(max(nt.current_version), 0) + 1
  into v_next_version
  from public.notification_templates nt
  where nt.hotel_id = p_hotel_id
    and nt.event_key = p_event_key
    and nt.channel = p_channel
    and nt.locale = v_locale;

  insert into public.notification_templates (
    hotel_id,
    event_key,
    channel,
    locale,
    title_template,
    body_template,
    status,
    current_version,
    created_by,
    published_by,
    published_at,
    created_at,
    updated_at
  ) values (
    p_hotel_id,
    p_event_key,
    p_channel,
    v_locale,
    trim(p_payload ->> 'title_template'),
    trim(p_payload ->> 'body_template'),
    'published',
    v_next_version,
    v_user_id,
    v_user_id,
    now(),
    now(),
    now()
  )
  on conflict (hotel_id, event_key, channel, locale)
  where hotel_id is not null
  do update
  set
    title_template = excluded.title_template,
    body_template = excluded.body_template,
    status = 'published',
    current_version = public.notification_templates.current_version + 1,
    published_by = v_user_id,
    published_at = now(),
    updated_at = now()
  returning * into v_row;

  insert into public.notification_template_versions (
    template_id,
    version_number,
    title_template,
    body_template,
    created_by,
    created_at
  ) values (
    v_row.id,
    v_row.current_version,
    v_row.title_template,
    v_row.body_template,
    v_user_id,
    now()
  )
  on conflict (template_id, version_number) do nothing;

  return jsonb_build_object(
    'template', to_jsonb(v_row),
    'published', true
  );
end;
$$;


ALTER FUNCTION "public"."publish_notification_template"("p_hotel_id" "uuid", "p_event_key" "text", "p_channel" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reactivate_hotel_subscription"("target_hotel_id" "uuid", "reason" "text", "action_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  existing_result jsonb;
  subscription_row public.hotel_subscriptions%rowtype;
  new_status_value text;
  result jsonb;
begin
  if target_hotel_id is null
     or nullif(trim(reason), '') is null
  then
    raise exception 'Hotel and reactivation reason are required.';
  end if;

  existing_result :=
    private.subscription_action_result_20260728(
      action_idempotency_key
    );

  if existing_result is not null then
    return existing_result
      || jsonb_build_object('idempotent', true);
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:reactivate-subscription:' || target_hotel_id::text
    )
  );

  select hs.*
  into subscription_row
  from public.hotel_subscriptions hs
  where hs.hotel_id = target_hotel_id
    and hs.status = 'suspended'
  order by hs.updated_at desc, hs.id desc
  limit 1
  for update;

  if not found then
    raise exception
      'No suspended subscription was found.';
  end if;

  if coalesce(
    subscription_row.grace_ends_at,
    subscription_row.current_period_end,
    subscription_row.end_date
  ) is not null
  and coalesce(
    subscription_row.grace_ends_at,
    subscription_row.current_period_end,
    subscription_row.end_date
  ) <= now()
  and subscription_row.billing_mode <> 'complimentary'
  then
    raise exception
      'The subscription period has ended; renew or activate a paid period first.';
  end if;

  new_status_value := case
    when subscription_row.billing_mode = 'trial'
      then 'trialing'
    else 'active'
  end;

  perform set_config(
    'stayqr.subscription_event_source',
    'reactivate_hotel_subscription',
    true
  );

  update public.hotel_subscriptions hs
  set
    status = new_status_value,
    provider_status = new_status_value,
    reactivated_at = now(),
    suspended_at = null,
    cancellation_reason = null,
    metadata = coalesce(hs.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'last_reactivation',
        jsonb_build_object(
          'reason', trim(reason),
          'reactivated_by', actor_user_id,
          'reactivated_at', now()
        )
      ),
    updated_at = now()
  where hs.id = subscription_row.id
  returning * into subscription_row;

  update public.hotels h
  set
    status = 'active',
    subscription_status = new_status_value,
    updated_at = now()
  where h.id = target_hotel_id;

  result := jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', subscription_row.id,
    'status', subscription_row.status,
    'hotel_status', 'active',
    'idempotent', false
  );

  return private.record_subscription_action_20260728(
    target_hotel_id,
    subscription_row.id,
    'hotel_reactivated',
    'reactivate_hotel_subscription',
    actor_user_id,
    'suspended',
    subscription_row.status,
    subscription_row.plan_id,
    subscription_row.plan_id,
    subscription_row.provider,
    null,
    action_idempotency_key,
    jsonb_build_object('reason', trim(reason)),
    result
  );
end;
$$;


ALTER FUNCTION "public"."reactivate_hotel_subscription"("target_hotel_id" "uuid", "reason" "text", "action_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_expired_subscriptions"("as_of" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  caller_role text :=
    current_setting('request.jwt.claim.role', true);
  candidate record;
  resulting_status text;
  reconciled_count integer := 0;
  trial_expired_count integer := 0;
  paid_expired_count integer := 0;
  cancelled_count integer := 0;
begin
  if not (
    (
      actor_user_id is not null
      and private.is_platform_admin()
    )
    or caller_role = 'service_role'
  ) then
    raise exception
      'Platform Admin or service-role access required.';
  end if;

  if as_of is null then
    as_of := now();
  end if;

  perform pg_advisory_xact_lock(
    hashtext('stayqr:reconcile-expired-subscriptions')
  );

  perform set_config(
    'stayqr.subscription_event_source',
    'expiry_reconciliation',
    true
  );

  for candidate in
    select hs.*
    from public.hotel_subscriptions hs
    where
      (
        hs.status in ('trial', 'trialing')
        and coalesce(
          hs.trial_ends_at,
          hs.end_date,
          'infinity'::timestamptz
        ) <= as_of
      )
      or
      (
        hs.status in ('active', 'past_due', 'suspended')
        and coalesce(
          hs.grace_ends_at,
          hs.current_period_end,
          hs.end_date,
          'infinity'::timestamptz
        ) <= as_of
      )
    order by hs.hotel_id, hs.created_at, hs.id
    for update
  loop
    resulting_status := case
      when coalesce(
        (candidate.metadata ->> 'cancel_at_period_end')::boolean,
        false
      ) then 'cancelled'
      else 'expired'
    end;

    update public.hotel_subscriptions hs
    set
      status = resulting_status,
      provider_status = resulting_status,
      cancelled_at = case
        when resulting_status = 'cancelled'
          then coalesce(hs.cancelled_at, as_of)
        else hs.cancelled_at
      end,
      cancellation_reason = case
        when resulting_status = 'cancelled'
          then coalesce(
            hs.cancellation_reason,
            'Scheduled cancellation reached period end.'
          )
        else hs.cancellation_reason
      end,
      metadata = coalesce(hs.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'last_expiry_reconciliation',
          jsonb_build_object(
            'as_of', as_of,
            'result', resulting_status
          )
        ),
      updated_at = now()
    where hs.id = candidate.id;

    update public.hotels h
    set
      status = 'suspended',
      subscription_status = resulting_status,
      updated_at = now()
    where h.id = candidate.hotel_id;

    reconciled_count := reconciled_count + 1;

    if candidate.status in ('trial', 'trialing') then
      trial_expired_count := trial_expired_count + 1;
    elsif resulting_status = 'cancelled' then
      cancelled_count := cancelled_count + 1;
    else
      paid_expired_count := paid_expired_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'as_of', as_of,
    'reconciled', reconciled_count,
    'trials_expired', trial_expired_count,
    'paid_expired', paid_expired_count,
    'scheduled_cancellations_completed',
      cancelled_count
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_expired_subscriptions"("as_of" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_food_manual_service_sources"("target_hotel_id" "uuid", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_record record;
  food_processed integer := 0;
  manual_processed integer := 0;
  service_processed integer := 0;
  food_items_value integer;
  manual_items_value integer;
  service_items_value integer;
  open_exceptions_value integer;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'payments.manage',
      'invoices.manage',
      'checkout.manage'
    ]::text[]
  ) then
    raise exception 'Financial source reconciliation access denied.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:day11:migration034:'
      || target_hotel_id::text,
      0
    )
  );

  for source_record in
    select food_order.id
    from public.food_orders food_order
    where food_order.hotel_id = target_hotel_id
    order by food_order.created_at, food_order.id
  loop
    perform private.day11_sync_food_order(
      source_record.id
    );
    food_processed := food_processed + 1;
  end loop;

  for source_record in
    select manual_charge.id
    from public.manual_charges manual_charge
    where manual_charge.hotel_id = target_hotel_id
    order by manual_charge.created_at,
             manual_charge.id
  loop
    perform private.day11_sync_manual_charge(
      source_record.id
    );
    manual_processed := manual_processed + 1;
  end loop;

  for source_record in
    select request.id
    from public.service_requests request
    where request.hotel_id = target_hotel_id
    order by request.created_at, request.id
  loop
    perform private.day11_refresh_service_request_mapping(
      source_record.id
    );

    perform private.day11_post_service_request_charge(
      source_record.id,
      false,
      request_id_value
    );

    service_processed := service_processed + 1;
  end loop;

  select count(*)
  into food_items_value
  from public.folio_items item
  where item.hotel_id = target_hotel_id
    and item.source_table = 'food_orders'
    and item.posting_status = 'posted';

  select count(*)
  into manual_items_value
  from public.folio_items item
  where item.hotel_id = target_hotel_id
    and item.source_table = 'manual_charges'
    and item.posting_status = 'posted';

  select count(*)
  into service_items_value
  from public.folio_items item
  where item.hotel_id = target_hotel_id
    and item.source_table = 'service_requests'
    and item.posting_status = 'posted';

  select count(*)
  into open_exceptions_value
  from public.folio_source_exceptions exception_record
  where exception_record.hotel_id = target_hotel_id
    and exception_record.status = 'open';

  return jsonb_build_object(
    'ok', true,
    'hotel_id', target_hotel_id,
    'request_id', coalesce(
      nullif(trim(request_id_value), ''),
      gen_random_uuid()::text
    ),
    'food_sources_processed', food_processed,
    'manual_sources_processed', manual_processed,
    'service_sources_processed',
      service_processed,
    'posted_food_items', food_items_value,
    'posted_manual_items', manual_items_value,
    'posted_service_items', service_items_value,
    'open_source_exceptions',
      open_exceptions_value,
    'source_sync', 'migration_034'
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_food_manual_service_sources"("target_hotel_id" "uuid", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_legacy_payment_folios"("target_hotel_id" "uuid", "request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  payment_record record;
  payment_count integer := 0;
  folio_count integer;
  item_count integer;
  collection_count integer;
  result_value jsonb;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'payments.manage',
      'invoices.manage',
      'checkout.manage'
    ]::text[]
  ) then
    raise exception 'Legacy financial reconciliation access denied.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'stayqr:day11-reconcile:'
      || target_hotel_id::text,
      0
    )
  );

  for payment_record in
    select payment.id
    from public.payments payment
    where payment.hotel_id = target_hotel_id
      and payment.guest_session_id is not null
    order by payment.created_at, payment.id
  loop
    perform private.day11_sync_payment(payment_record.id);
    payment_count := payment_count + 1;
  end loop;

  select count(*)
  into folio_count
  from public.folios folio
  where folio.hotel_id = target_hotel_id
    and exists (
      select 1
      from public.payments payment
      where payment.hotel_id = target_hotel_id
        and payment.guest_session_id = folio.guest_session_id
    );

  select count(*)
  into item_count
  from public.folio_items item
  where item.hotel_id = target_hotel_id
    and item.source_table = 'payments';

  select count(*)
  into collection_count
  from public.folio_collections collection
  where collection.hotel_id = target_hotel_id
    and collection.source_table in (
      'payments',
      'payment_collections'
    );

  result_value := jsonb_build_object(
    'ok', true,
    'hotel_id', target_hotel_id,
    'request_id', coalesce(
      nullif(trim(request_id), ''),
      gen_random_uuid()::text
    ),
    'payments_processed', payment_count,
    'folios', folio_count,
    'folio_items', item_count,
    'folio_collections', collection_count,
    'source_sync', 'migration_033'
  );

  return result_value;
end;
$$;


ALTER FUNCTION "public"."reconcile_legacy_payment_folios"("target_hotel_id" "uuid", "request_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reconcile_legacy_payment_folios"("target_hotel_id" "uuid", "request_id" "text") IS 'Authorized idempotent reconciliation of all linked legacy payment and collection sources for one hotel.';



CREATE OR REPLACE FUNCTION "public"."reconcile_payment_webhook_event"("provider_value" "text", "provider_event_id_value" "text", "event_type_value" "text", "signature_valid_value" boolean, "payload_hash_value" "text", "target_hotel_id" "uuid" DEFAULT NULL::"uuid", "target_folio_id" "uuid" DEFAULT NULL::"uuid", "amount_value" numeric DEFAULT NULL::numeric, "payment_method_value" "text" DEFAULT NULL::"text", "target_refund_id" "uuid" DEFAULT NULL::"uuid", "provider_object_id_value" "text" DEFAULT NULL::"text", "transaction_reference_value" "text" DEFAULT NULL::"text", "safe_metadata_value" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  webhook_row public.payment_webhook_events%rowtype;
  normalized_provider text;
  normalized_event_type text;
  collection_result jsonb;
  refund_result jsonb;
  collection_id_value uuid;
  refund_row public.refunds%rowtype;
begin
  normalized_provider := lower(trim(provider_value));
  normalized_event_type := lower(trim(event_type_value));

  if nullif(normalized_provider,'') is null
     or nullif(trim(provider_event_id_value),'') is null
     or nullif(normalized_event_type,'') is null
     or nullif(trim(payload_hash_value),'') is null
  then
    raise exception 'Provider, event ID, event type and payload hash are required.';
  end if;

  insert into public.payment_webhook_events(
    hotel_id,provider,provider_event_id,event_type,signature_valid,payload_hash,
    event_status,processing_attempts,folio_id,refund_id,safe_metadata
  ) values (
    target_hotel_id,normalized_provider,trim(provider_event_id_value),normalized_event_type,
    signature_valid_value,trim(payload_hash_value),'received',0,target_folio_id,target_refund_id,
    coalesce(safe_metadata_value,'{}'::jsonb) || jsonb_build_object(
      'amount',amount_value,'payment_method',payment_method_value,
      'provider_object_id',provider_object_id_value,'transaction_reference',transaction_reference_value,'day',11
    )
  ) on conflict (provider,provider_event_id) do nothing;

  select event_record.* into webhook_row
  from public.payment_webhook_events event_record
  where event_record.provider = normalized_provider
    and event_record.provider_event_id = trim(provider_event_id_value)
  for update;

  if webhook_row.payload_hash <> trim(payload_hash_value) then
    raise exception 'Webhook event ID was reused with a different payload hash.';
  end if;

  if webhook_row.event_type <> normalized_event_type
     or webhook_row.signature_valid is distinct from signature_valid_value
  then
    raise exception 'Webhook event ID conflicts with different normalized event attributes.';
  end if;

  if webhook_row.event_status in ('processed','ignored') then
    return jsonb_build_object('ok',true,'idempotent',true,'webhook_event',to_jsonb(webhook_row));
  end if;

  update public.payment_webhook_events
  set processing_attempts = processing_attempts + 1
  where id = webhook_row.id
  returning * into webhook_row;

  if not signature_valid_value then
    update public.payment_webhook_events
    set event_status = 'failed',processed_at = now(),
        last_error = 'Trusted signature verifier reported invalid signature.'
    where id = webhook_row.id
    returning * into webhook_row;
    return jsonb_build_object('ok',false,'idempotent',false,'reason','invalid_signature','webhook_event',to_jsonb(webhook_row));
  end if;

  begin
    if normalized_event_type = 'payment.succeeded' then
      if target_hotel_id is null or target_folio_id is null or amount_value is null or amount_value <= 0
         or nullif(trim(payment_method_value),'') is null
      then
        raise exception 'payment.succeeded requires hotel, folio, positive amount and payment method.';
      end if;

      collection_result := private.day11_post_collection(
        target_hotel_id,target_folio_id,amount_value,payment_method_value,gen_random_uuid(),
        transaction_reference_value,normalized_provider,provider_object_id_value,
        trim(provider_event_id_value),'payment_webhook_events',webhook_row.id,
        'webhook:' || normalized_provider || ':' || trim(provider_event_id_value),
        webhook_row.received_at,null,
        coalesce(safe_metadata_value,'{}'::jsonb) || jsonb_build_object(
          'webhook_event_id',webhook_row.id,'provider_event_id',trim(provider_event_id_value)
        )
      );

      collection_id_value := (collection_result -> 'collection' ->> 'id')::uuid;
      update public.payment_webhook_events
      set event_status = 'processed',processed_at = now(),last_error = null,
          folio_collection_id = collection_id_value,folio_id = target_folio_id,hotel_id = target_hotel_id
      where id = webhook_row.id
      returning * into webhook_row;

    elsif normalized_event_type = 'payment.failed' then
      update public.payment_webhook_events
      set event_status = 'ignored',processed_at = now(),last_error = null
      where id = webhook_row.id returning * into webhook_row;

    elsif normalized_event_type = 'refund.succeeded' then
      if target_refund_id is null then raise exception 'refund.succeeded requires refund_id.'; end if;
      select refund.* into refund_row from public.refunds refund where refund.id = target_refund_id;
      if not found then raise exception 'Webhook refund was not found.'; end if;

      refund_result := private.day11_process_refund(
        target_refund_id,provider_object_id_value,transaction_reference_value,null,true,
        coalesce(safe_metadata_value,'{}'::jsonb) || jsonb_build_object(
          'webhook_event_id',webhook_row.id,'provider',normalized_provider,'provider_event_id',trim(provider_event_id_value)
        )
      );

      update public.payment_webhook_events
      set event_status = 'processed',processed_at = now(),last_error = null,
          hotel_id = refund_row.hotel_id,folio_id = refund_row.folio_id,refund_id = refund_row.id
      where id = webhook_row.id returning * into webhook_row;

    elsif normalized_event_type = 'refund.failed' then
      if target_refund_id is null then raise exception 'refund.failed requires refund_id.'; end if;
      update public.refunds refund
      set status = 'failed',
          failure_reason = coalesce(nullif(trim(safe_metadata_value ->> 'failure_reason'),''),'Provider reported refund failure.'),
          metadata = refund.metadata || coalesce(safe_metadata_value,'{}'::jsonb) || jsonb_build_object('failed_webhook_event_id',webhook_row.id)
      where refund.id = target_refund_id and refund.status = 'pending'
      returning refund.* into refund_row;
      if refund_row.id is null then raise exception 'Pending webhook refund was not found.'; end if;

      update public.payment_webhook_events
      set event_status = 'processed',processed_at = now(),last_error = null,
          hotel_id = refund_row.hotel_id,folio_id = refund_row.folio_id,refund_id = refund_row.id
      where id = webhook_row.id returning * into webhook_row;

    else
      update public.payment_webhook_events
      set event_status = 'ignored',processed_at = now(),last_error = 'Unsupported normalized event type.'
      where id = webhook_row.id returning * into webhook_row;
    end if;
  exception when others then
    update public.payment_webhook_events
    set event_status = 'failed',processed_at = now(),last_error = sqlerrm
    where id = webhook_row.id returning * into webhook_row;
    return jsonb_build_object('ok',false,'idempotent',false,'reason','processing_failed','error',sqlerrm,'webhook_event',to_jsonb(webhook_row));
  end;

  return jsonb_build_object('ok',true,'idempotent',false,'collection_result',collection_result,'refund_result',refund_result,'webhook_event',to_jsonb(webhook_row));
end;
$$;


ALTER FUNCTION "public"."reconcile_payment_webhook_event"("provider_value" "text", "provider_event_id_value" "text", "event_type_value" "text", "signature_valid_value" boolean, "payload_hash_value" "text", "target_hotel_id" "uuid", "target_folio_id" "uuid", "amount_value" numeric, "payment_method_value" "text", "target_refund_id" "uuid", "provider_object_id_value" "text", "transaction_reference_value" "text", "safe_metadata_value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reconcile_payment_webhook_event"("provider_value" "text", "provider_event_id_value" "text", "event_type_value" "text", "signature_valid_value" boolean, "payload_hash_value" "text", "target_hotel_id" "uuid", "target_folio_id" "uuid", "amount_value" numeric, "payment_method_value" "text", "target_refund_id" "uuid", "provider_object_id_value" "text", "transaction_reference_value" "text", "safe_metadata_value" "jsonb") IS 'Provider-neutral idempotent payment/refund webhook reconciliation. Signature verification occurs outside PostgreSQL.';



CREATE OR REPLACE FUNCTION "public"."record_guest_guide_event"("p_hotel_slug" "text", "p_access_token" "text", "p_event_type" "text", "p_section_key" "text" DEFAULT NULL::"text", "p_item_id" "uuid" DEFAULT NULL::"uuid", "p_locale" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_token_id uuid;
  v_token public.guest_access_tokens%rowtype;
  v_row public.guest_guide_events%rowtype;
begin
  v_token_id := private.resolve_guest_access_token(
    p_hotel_slug,
    p_access_token,
    true
  );

  if v_token_id is null then
    raise exception 'This guest access link is invalid or expired.';
  end if;

  select t.*
  into v_token
  from public.guest_access_tokens t
  where t.id = v_token_id;

  insert into public.guest_guide_events (
    hotel_id,
    guest_session_id,
    guest_access_token_id,
    event_type,
    section_key,
    item_id,
    locale,
    metadata
  )
  values (
    v_token.hotel_id,
    v_token.guest_session_id,
    v_token.id,
    lower(trim(p_event_type)),
    nullif(trim(coalesce(p_section_key, '')), ''),
    p_item_id,
    nullif(trim(coalesce(p_locale, '')), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning *
  into v_row;

  return jsonb_build_object(
    'result', 'GUEST GUIDE EVENT RECORDED',
    'event_id', v_row.id,
    'event_type', v_row.event_type,
    'occurred_at', v_row.occurred_at
  );
end;
$$;


ALTER FUNCTION "public"."record_guest_guide_event"("p_hotel_slug" "text", "p_access_token" "text", "p_event_type" "text", "p_section_key" "text", "p_item_id" "uuid", "p_locale" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_guest_review_reward_action"("p_hotel_slug" "text", "p_access_token" "text", "p_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_token_id uuid;
  v_token public.guest_access_tokens%rowtype;
  v_action text := lower(trim(coalesce(p_action, '')));
  v_row public.guest_review_rewards%rowtype;
begin
  if v_action not in (
    'review_opened',
    'reward_viewed',
    'reward_requested',
    'reward_redeemed',
    'reward_declined'
  ) then
    raise exception 'Unsupported review or reward action.';
  end if;

  v_token_id := private.resolve_guest_access_token(
    p_hotel_slug,
    p_access_token,
    true
  );

  if v_token_id is null then
    raise exception 'This guest access link is invalid or expired.';
  end if;

  select t.*
  into v_token
  from public.guest_access_tokens t
  where t.id = v_token_id;

  insert into public.guest_review_rewards (
    hotel_id,
    guest_session_id,
    guest_access_token_id,
    action,
    status
  )
  values (
    v_token.hotel_id,
    v_token.guest_session_id,
    v_token.id,
    v_action,
    case
      when v_action = 'reward_redeemed' then 'redeemed'
      when v_action = 'reward_declined' then 'declined'
      else 'recorded'
    end
  )
  on conflict (guest_session_id, action)
  do update set
    guest_access_token_id = excluded.guest_access_token_id
  returning *
  into v_row;

  return jsonb_build_object(
    'result', 'ACTION RECORDED',
    'action_id', v_row.id,
    'action', v_row.action,
    'status', v_row.status,
    'created_at', v_row.created_at
  );
end;
$$;


ALTER FUNCTION "public"."record_guest_review_reward_action"("p_hotel_slug" "text", "p_access_token" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_hotel_onboarding_readiness"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  readiness jsonb;
  is_ready boolean;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_permission(target_hotel_id, 'hotel.manage')
    or exists (
      select 1
      from public.hotel_onboarding ho
      where ho.hotel_id = target_hotel_id
        and ho.owner_user_id = actor_user_id
    )
  ) then
    raise exception 'Hotel configuration access denied.';
  end if;

  readiness := private.compute_hotel_onboarding_readiness(target_hotel_id);
  is_ready := coalesce((readiness ->> 'ready')::boolean, false);

  update public.hotel_onboarding ho
  set
    readiness_state = readiness,
    status = case when is_ready then 'complete' else 'in_progress' end,
    current_step = case when is_ready then 'complete' else ho.current_step end,
    completed_at = case when is_ready then coalesce(ho.completed_at, now()) else null end,
    last_saved_at = now(),
    updated_by = actor_user_id,
    version = ho.version + 1
  where ho.hotel_id = target_hotel_id;

  if not found then
    raise exception 'Hotel onboarding state is missing.';
  end if;

  return readiness;
end;
$$;


ALTER FUNCTION "public"."refresh_hotel_onboarding_readiness"("target_hotel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_guest_document"("target_hotel_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  requested_document_id uuid;
  requested_request_id uuid;
  requested_guest_id uuid;
  requested_session_id uuid;
  requested_reservation_id uuid;
  requested_document_type text;
  requested_storage_bucket text;
  requested_storage_path text;
  requested_original_name text;
  requested_mime_type text;
  requested_size bigint;
  requested_masked_number text;
  requested_issue_country text;
  requested_issued_on date;
  requested_expires_on date;
  requested_metadata jsonb;
  existing_document public.guest_documents%rowtype;
  inserted_document public.guest_documents%rowtype;
  expected_prefix text;
  activity_id uuid;
begin
  if actor_id is null then
    raise exception 'Authentication is required.';
  end if;

  if not private.user_has_any_permission(
    target_hotel_id,
    array['guests.manage', 'checkin.manage']
  ) then
    raise exception 'You do not have permission to upload guest documents.';
  end if;

  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'A JSON object payload is required.';
  end if;

  requested_document_id := coalesce(
    nullif(payload ->> 'document_id', '')::uuid,
    gen_random_uuid()
  );
  requested_request_id := coalesce(
    nullif(payload ->> 'request_id', '')::uuid,
    requested_document_id
  );
  requested_guest_id := nullif(payload ->> 'guest_id', '')::uuid;
  requested_session_id := nullif(payload ->> 'guest_session_id', '')::uuid;
  requested_reservation_id := nullif(payload ->> 'reservation_id', '')::uuid;
  requested_document_type := lower(trim(coalesce(payload ->> 'document_type', '')));
  requested_storage_bucket := coalesce(
    nullif(trim(payload ->> 'storage_bucket'), ''),
    'guest-documents'
  );
  requested_storage_path := trim(coalesce(payload ->> 'storage_path', ''));
  requested_original_name := nullif(trim(payload ->> 'original_file_name'), '');
  requested_mime_type := lower(trim(coalesce(payload ->> 'mime_type', '')));
  requested_size := nullif(payload ->> 'file_size_bytes', '')::bigint;
  requested_masked_number := nullif(trim(payload ->> 'document_number_masked'), '');
  requested_issue_country := nullif(trim(payload ->> 'issue_country'), '');
  requested_issued_on := nullif(payload ->> 'issued_on', '')::date;
  requested_expires_on := nullif(payload ->> 'expires_on', '')::date;
  requested_metadata := coalesce(payload -> 'metadata', '{}'::jsonb);

  if requested_guest_id is null then
    raise exception 'guest_id is required.';
  end if;

  select *
  into existing_document
  from public.guest_documents gd
  where gd.hotel_id = target_hotel_id
    and gd.request_id = requested_request_id
  limit 1;

  if found then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'document', to_jsonb(existing_document)
    );
  end if;

  if requested_document_type not in (
    'aadhaar',
    'passport',
    'driving_licence',
    'voter_id',
    'pan',
    'visa',
    'form_c',
    'other'
  ) then
    raise exception 'Unsupported document type.';
  end if;

  if requested_storage_bucket <> 'guest-documents' then
    raise exception 'Guest documents must use the private guest-documents bucket.';
  end if;

  if requested_mime_type not in (
    'image/jpeg',
    'image/png',
    'application/pdf'
  ) then
    raise exception 'Only JPEG, PNG and PDF files are allowed.';
  end if;

  if requested_size is null
     or requested_size <= 0
     or requested_size > 15728640 then
    raise exception 'The document must be between 1 byte and 15 MB.';
  end if;

  if requested_original_name is null
     or length(requested_original_name) > 255 then
    raise exception 'A valid original file name is required.';
  end if;

  if requested_masked_number is not null
     and length(requested_masked_number) > 64 then
    raise exception 'The masked document number is too long.';
  end if;

  if requested_issued_on is not null
     and requested_expires_on is not null
     and requested_expires_on < requested_issued_on then
    raise exception 'Document expiry cannot be before issue date.';
  end if;

  if not exists (
    select 1
    from public.guests g
    where g.hotel_id = target_hotel_id
      and g.id = requested_guest_id
  ) then
    raise exception 'Guest does not belong to the selected hotel.';
  end if;

  if requested_session_id is not null
     and not exists (
       select 1
       from public.guest_sessions gs
       where gs.hotel_id = target_hotel_id
         and gs.id = requested_session_id
         and gs.guest_id = requested_guest_id
     ) then
    raise exception 'Guest session does not belong to this guest and hotel.';
  end if;

  if requested_reservation_id is not null
     and not exists (
       select 1
       from public.reservation_guests rg
       join public.reservations r
         on r.hotel_id = rg.hotel_id
        and r.id = rg.reservation_id
       where rg.hotel_id = target_hotel_id
         and rg.reservation_id = requested_reservation_id
         and rg.guest_id = requested_guest_id
     ) then
    raise exception 'Reservation does not belong to this guest and hotel.';
  end if;

  expected_prefix :=
    target_hotel_id::text || '/' ||
    requested_guest_id::text || '/' ||
    requested_document_id::text || '/';

  if requested_storage_path not like expected_prefix || '%' then
    raise exception 'Storage path must be scoped to hotel/guest/document.';
  end if;

  if not exists (
    select 1
    from storage.objects object_record
    where object_record.bucket_id = requested_storage_bucket
      and object_record.name = requested_storage_path
  ) then
    raise exception 'Uploaded storage object was not found.';
  end if;

  begin
    insert into public.guest_documents (
      id,
      hotel_id,
      guest_id,
      guest_session_id,
      reservation_id,
      request_id,
      document_type,
      storage_bucket,
      storage_path,
      original_file_name,
      mime_type,
      file_size_bytes,
      document_number_masked,
      issue_country,
      issued_on,
      expires_on,
      verification_status,
      uploaded_by,
      metadata
    )
    values (
      requested_document_id,
      target_hotel_id,
      requested_guest_id,
      requested_session_id,
      requested_reservation_id,
      requested_request_id,
      requested_document_type,
      requested_storage_bucket,
      requested_storage_path,
      requested_original_name,
      requested_mime_type,
      requested_size,
      requested_masked_number,
      requested_issue_country,
      requested_issued_on,
      requested_expires_on,
      'pending',
      actor_id,
      requested_metadata
    )
    returning * into inserted_document;
  exception
    when unique_violation then
      select *
      into existing_document
      from public.guest_documents gd
      where gd.hotel_id = target_hotel_id
        and gd.request_id = requested_request_id
      limit 1;

      if found then
        return jsonb_build_object(
          'ok', true,
          'idempotent', true,
          'document', to_jsonb(existing_document)
        );
      end if;

      raise;
  end;

  update public.guests g
  set
    identity_verification_status = case
      when g.identity_verification_status = 'verified' then 'verified'
      else 'pending'
    end,
    updated_at = now()
  where g.hotel_id = target_hotel_id
    and g.id = requested_guest_id;

  activity_id := private.write_activity_log(
    target_hotel_id,
    'front_office.guest_document_uploaded',
    'guest_document',
    inserted_document.id,
    'Private guest document uploaded and registered for review.',
    null,
    jsonb_build_object(
      'guest_id', inserted_document.guest_id,
      'guest_session_id', inserted_document.guest_session_id,
      'document_type', inserted_document.document_type,
      'verification_status', inserted_document.verification_status
    ),
    jsonb_build_object(
      'request_id', inserted_document.request_id,
      'storage_bucket', inserted_document.storage_bucket,
      'storage_path', inserted_document.storage_path,
      'mime_type', inserted_document.mime_type,
      'file_size_bytes', inserted_document.file_size_bytes
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'activity_id', activity_id,
    'document', to_jsonb(inserted_document)
  );
end;
$$;


ALTER FUNCTION "public"."register_guest_document"("target_hotel_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."register_guest_document"("target_hotel_id" "uuid", "payload" "jsonb") IS 'Day 10 private KYC registration RPC. Validates tenant scope, storage object, MIME, size, path, guest/session linkage and request idempotency.';



CREATE OR REPLACE FUNCTION "public"."remove_reservation_room"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "target_reservation_room_id" "uuid", "expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reservation_row public.reservations%rowtype;
  room_row public.reservation_rooms%rowtype;
  before_json jsonb;
  after_json jsonb;
  remaining_count integer;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  select r.* into reservation_row
  from public.reservations r
  where r.hotel_id = target_hotel_id
    and r.id = target_reservation_id
  for update;

  if not found then raise exception 'Reservation not found.'; end if;

  if reservation_row.status not in ('draft', 'tentative', 'confirmed') then
    raise exception 'Checked-in reservation rooms cannot be removed.';
  end if;

  if expected_updated_at is not null
     and reservation_row.updated_at is distinct from expected_updated_at
  then
    raise exception 'Reservation changed after it was opened. Refresh and try again.';
  end if;

  select rr.* into room_row
  from public.reservation_rooms rr
  where rr.hotel_id = target_hotel_id
    and rr.reservation_id = target_reservation_id
    and rr.id = target_reservation_room_id
  for update;

  if not found then raise exception 'Reservation room not found.'; end if;

  if room_row.status in ('checked_in', 'checked_out') then
    raise exception 'A checked-in or checked-out room cannot be removed.';
  end if;

  select count(*) into remaining_count
  from public.reservation_rooms rr
  where rr.hotel_id = target_hotel_id
    and rr.reservation_id = target_reservation_id
    and rr.id <> target_reservation_room_id
    and rr.status not in ('cancelled', 'released');

  if remaining_count < 1 then
    raise exception 'A reservation must retain at least one room.';
  end if;

  before_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  update public.reservation_rooms
  set status = 'released'
  where hotel_id = target_hotel_id
    and id = target_reservation_room_id;

  update public.reservations r
  set
    adults = totals.total_adults,
    children = totals.total_children,
    room_subtotal = totals.room_subtotal,
    tax_amount = totals.tax_amount,
    discount_amount = totals.discount_amount,
    total_amount = greatest(
      totals.room_subtotal + totals.tax_amount - totals.discount_amount,
      0
    ),
    deposit_required = least(
      r.deposit_required,
      greatest(
        totals.room_subtotal + totals.tax_amount - totals.discount_amount,
        0
      )
    ),
    updated_by = auth.uid()
  from (
    select
      sum(rr.adults)::integer as total_adults,
      sum(rr.children)::integer as total_children,
      sum(rr.room_subtotal)::numeric(12,2) as room_subtotal,
      sum(rr.tax_amount)::numeric(12,2) as tax_amount,
      sum(rr.discount_amount)::numeric(12,2) as discount_amount
    from public.reservation_rooms rr
    where rr.hotel_id = target_hotel_id
      and rr.reservation_id = target_reservation_id
      and rr.status not in ('cancelled', 'released')
  ) totals
  where r.hotel_id = target_hotel_id
    and r.id = target_reservation_id;

  after_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'reservation.room_removed',
    'reservation',
    target_reservation_id,
    'A room was released from the reservation.',
    before_json,
    after_json,
    jsonb_build_object('reservation_room_id', target_reservation_room_id)
  );

  return after_json;
end;
$$;


ALTER FUNCTION "public"."remove_reservation_room"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "target_reservation_room_id" "uuid", "expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."renew_hotel_subscription"("target_hotel_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  caller_role text :=
    current_setting('request.jwt.claim.role', true);
  action_key text;
  existing_result jsonb;
  subscription_row public.hotel_subscriptions%rowtype;
  old_status_value text;
  period_start_value timestamptz;
  period_end_value timestamptz;
  result jsonb;
begin
  if not (
    (
      actor_user_id is not null
      and private.is_platform_admin()
    )
    or caller_role = 'service_role'
  ) then
    raise exception
      'Platform Admin or service-role access required.';
  end if;

  if target_hotel_id is null
     or payload is null
     or jsonb_typeof(payload) <> 'object'
  then
    raise exception 'Hotel and renewal payload are required.';
  end if;

  action_key :=
    nullif(trim(payload ->> 'idempotency_key'), '');
  existing_result :=
    private.subscription_action_result_20260728(action_key);

  if existing_result is not null then
    return existing_result
      || jsonb_build_object('idempotent', true);
  end if;

  period_start_value :=
    coalesce(
      nullif(
        trim(payload ->> 'current_period_start'),
        ''
      )::timestamptz,
      now()
    );
  period_end_value :=
    nullif(
      trim(payload ->> 'current_period_end'),
      ''
    )::timestamptz;

  if period_end_value is null
     or period_end_value <= period_start_value
  then
    raise exception 'A valid renewal period is required.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:renew-subscription:' || target_hotel_id::text
    )
  );

  select hs.*
  into subscription_row
  from public.hotel_subscriptions hs
  where hs.hotel_id = target_hotel_id
    and hs.status in (
      'active',
      'past_due',
      'suspended'
    )
  order by hs.updated_at desc, hs.id desc
  limit 1
  for update;

  if not found then
    raise exception
      'No renewable current subscription was found.';
  end if;

  old_status_value := subscription_row.status;

  perform set_config(
    'stayqr.subscription_event_source',
    'renew_hotel_subscription',
    true
  );

  update public.hotel_subscriptions hs
  set
    status = 'active',
    billing_mode = case
      when hs.billing_mode = 'complimentary'
        and nullif(
          trim(payload ->> 'amount_minor'),
          ''
        )::bigint > 0
        then 'paid'
      else hs.billing_mode
    end,
    billing_cycle = coalesce(
      nullif(trim(payload ->> 'billing_cycle'), ''),
      hs.billing_cycle
    ),
    amount_minor = coalesce(
      nullif(trim(payload ->> 'amount_minor'), '')::bigint,
      hs.amount_minor
    ),
    currency_code = upper(
      coalesce(
        nullif(trim(payload ->> 'currency_code'), ''),
        hs.currency_code
      )
    ),
    provider = coalesce(
      nullif(trim(payload ->> 'provider'), ''),
      hs.provider
    ),
    provider_status = coalesce(
      nullif(trim(payload ->> 'provider_status'), ''),
      'active'
    ),
    provider_customer_id = coalesce(
      nullif(trim(payload ->> 'provider_customer_id'), ''),
      hs.provider_customer_id
    ),
    provider_subscription_id = coalesce(
      nullif(
        trim(payload ->> 'provider_subscription_id'),
        ''
      ),
      hs.provider_subscription_id
    ),
    provider_payment_link_id = coalesce(
      nullif(
        trim(payload ->> 'provider_payment_link_id'),
        ''
      ),
      hs.provider_payment_link_id
    ),
    provider_metadata =
      coalesce(hs.provider_metadata, '{}'::jsonb)
      || coalesce(payload -> 'provider_metadata', '{}'::jsonb),
    start_date = period_start_value,
    end_date = period_end_value,
    current_period_start = period_start_value,
    current_period_end = period_end_value,
    grace_ends_at = null,
    suspended_at = null,
    reactivated_at = case
      when old_status_value = 'suspended'
        then now()
      else hs.reactivated_at
    end,
    last_payment_at = coalesce(
      nullif(
        trim(payload ->> 'last_payment_at'),
        ''
      )::timestamptz,
      now()
    ),
    cancellation_reason = null,
    cancelled_at = null,
    metadata = coalesce(hs.metadata, '{}'::jsonb)
      || coalesce(payload -> 'metadata', '{}'::jsonb)
      || jsonb_build_object(
        'last_renewal',
        jsonb_build_object(
          'renewed_at', now(),
          'renewed_by', actor_user_id,
          'source_role', caller_role
        )
      ),
    updated_at = now()
  where hs.id = subscription_row.id
  returning * into subscription_row;

  update public.hotels h
  set
    status = 'active',
    subscription_status = 'active',
    updated_at = now()
  where h.id = target_hotel_id;

  result := jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', subscription_row.id,
    'status', subscription_row.status,
    'current_period_start',
      subscription_row.current_period_start,
    'current_period_end',
      subscription_row.current_period_end,
    'amount_minor', subscription_row.amount_minor,
    'idempotent', false
  );

  return private.record_subscription_action_20260728(
    target_hotel_id,
    subscription_row.id,
    'subscription_renewed',
    'renew_hotel_subscription',
    actor_user_id,
    old_status_value,
    subscription_row.status,
    subscription_row.plan_id,
    subscription_row.plan_id,
    subscription_row.provider,
    nullif(trim(payload ->> 'provider_event_id'), ''),
    action_key,
    jsonb_build_object(
      'period_start', period_start_value,
      'period_end', period_end_value
    ),
    result
  );
end;
$$;


ALTER FUNCTION "public"."renew_hotel_subscription"("target_hotel_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_maintenance_task"("target_hotel_id" "uuid", "target_room_id" "uuid", "title_value" "text", "description_value" "text", "category_value" "text", "severity_value" "text", "inventory_impact_value" "text", "expected_return_date_value" "date", "due_at_value" timestamp with time zone, "requires_cleaning_value" boolean, "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  room_row public.rooms%rowtype;
  task_row public.maintenance_tasks%rowtype;
  block_row public.room_blocks%rowtype;
  commitments jsonb;
  block_type_value text;
begin
  actor_id_value :=
    private.day13_require_maintenance_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select task.*
  into task_row
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.request_id = request_key;

  if task_row.id is not null then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  if nullif(trim(title_value), '') is null then
    raise exception 'Maintenance title is required.';
  end if;

  if category_value not in (
    'electrical',
    'plumbing',
    'hvac',
    'appliance',
    'furniture',
    'structural',
    'safety',
    'pest_control',
    'internet',
    'other'
  ) then
    raise exception 'Invalid maintenance category.';
  end if;

  if severity_value not in (
    'low',
    'medium',
    'high',
    'critical'
  ) then
    raise exception 'Invalid maintenance severity.';
  end if;

  if inventory_impact_value not in (
    'none',
    'maintenance',
    'out_of_order'
  ) then
    raise exception 'Invalid inventory impact.';
  end if;

  select room.*
  into room_row
  from public.rooms room
  where room.hotel_id = target_hotel_id
    and room.id = target_room_id
  for update;

  if not found then
    raise exception 'Room was not found.';
  end if;

  if not room_row.is_active then
    raise exception
      'Archived room cannot receive a maintenance task.';
  end if;

  commitments :=
    private.day13_room_commitments(
      target_hotel_id,
      target_room_id
    );

  if inventory_impact_value <> 'none'
     and (
       commitments
       ->> 'active_stays'
     )::integer > 0
  then
    raise exception
      'Occupied room cannot be removed from inventory. Move or check out the active stay first.';
  end if;

  if inventory_impact_value <> 'none'
     and (
       expected_return_date_value is null
       or expected_return_date_value <= current_date
     )
  then
    raise exception
      'Offline maintenance requires a future expected return date.';
  end if;

  if inventory_impact_value <> 'none'
     and room_row.status not in (
       'available',
       'cleaning',
       'maintenance',
       'out_of_order'
     )
  then
    raise exception
      'Room status % cannot enter offline maintenance.',
      room_row.status;
  end if;

  if inventory_impact_value <> 'none'
     and exists (
       select 1
       from public.maintenance_tasks existing_task
       where existing_task.hotel_id = target_hotel_id
         and existing_task.room_id = target_room_id
         and existing_task.inventory_impact <> 'none'
         and existing_task.status in (
           'reported',
           'assigned',
           'in_progress',
           'on_hold',
           'resolved'
         )
     )
  then
    raise exception
      'Room already has an active offline maintenance task.';
  end if;

  if inventory_impact_value <> 'none' then
    block_type_value :=
      case
        when inventory_impact_value =
             'out_of_order'
          then 'out_of_order'
        else 'maintenance'
      end;

    insert into public.room_blocks (
      hotel_id,
      room_id,
      block_type,
      status,
      start_date,
      end_date,
      reason,
      notes,
      created_by,
      updated_by
    )
    values (
      target_hotel_id,
      target_room_id,
      block_type_value,
      'active',
      current_date,
      expected_return_date_value,
      trim(title_value),
      nullif(trim(description_value), ''),
      actor_id_value,
      actor_id_value
    )
    returning *
    into block_row;
  end if;

  insert into public.maintenance_tasks (
    hotel_id,
    room_id,
    task_number,
    title,
    description,
    category,
    severity,
    status,
    inventory_impact,
    previous_room_status,
    room_block_id,
    reported_by,
    request_id,
    due_at,
    expected_return_date,
    requires_cleaning,
    updated_by,
    metadata
  )
  values (
    target_hotel_id,
    target_room_id,
    private.day13_maintenance_task_number(
      target_hotel_id
    ),
    trim(title_value),
    nullif(trim(description_value), ''),
    category_value,
    severity_value,
    'reported',
    inventory_impact_value,
    room_row.status,
    block_row.id,
    actor_id_value,
    request_key,
    due_at_value,
    expected_return_date_value,
    coalesce(requires_cleaning_value, true),
    actor_id_value,
    jsonb_build_object(
      'room_number', room_row.room_number,
      'created_via', 'report_maintenance_task'
    )
  )
  returning *
  into task_row;

  perform private.day13_insert_maintenance_event(
    target_hotel_id,
    task_row.id,
    'reported',
    null,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'room_id', target_room_id,
      'room_number', room_row.room_number,
      'severity', severity_value,
      'inventory_impact',
        inventory_impact_value
    )
  );

  if block_row.id is not null then
    perform private.day13_insert_maintenance_event(
      target_hotel_id,
      task_row.id,
      'room_block_created',
      task_row.status,
      task_row.status,
      actor_id_value,
      request_key || ':block',
      jsonb_build_object(
        'room_block_id', block_row.id,
        'block_type', block_row.block_type,
        'start_date', block_row.start_date,
        'end_date', block_row.end_date
      )
    );

    perform public.transition_room_status(
      target_hotel_id,
      target_room_id,
      inventory_impact_value,
      trim(title_value),
      'maintenance',
      request_key || ':room'
    );
  end if;

  select task.*
  into task_row
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = task_row.id;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row),
    'room_block',
      case
        when block_row.id is null
          then null
        else to_jsonb(block_row)
      end
  );
end;
$$;


ALTER FUNCTION "public"."report_maintenance_task"("target_hotel_id" "uuid", "target_room_id" "uuid", "title_value" "text", "description_value" "text", "category_value" "text", "severity_value" "text", "inventory_impact_value" "text", "expected_return_date_value" "date", "due_at_value" timestamp with time zone, "requires_cleaning_value" boolean, "request_id_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."report_maintenance_task"("target_hotel_id" "uuid", "target_room_id" "uuid", "title_value" "text", "description_value" "text", "category_value" "text", "severity_value" "text", "inventory_impact_value" "text", "expected_return_date_value" "date", "due_at_value" timestamp with time zone, "requires_cleaning_value" boolean, "request_id_value" "text") IS 'Reports maintenance with explicit inventory impact and rejects a second active offline-maintenance lifecycle before room-block allocation.';



CREATE OR REPLACE FUNCTION "public"."report_operational_error"("p_hotel_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_is_service boolean := coalesce(auth.role(), '') = 'service_role';
  v_actor_user_id uuid := auth.uid();
  v_source text;
  v_environment text;
  v_severity text;
  v_event_name text;
  v_error_name text;
  v_error_code text;
  v_message text;
  v_route text;
  v_scope text;
  v_component text;
  v_request_id text;
  v_release text;
  v_context jsonb;
  v_incident_id text;
  v_fingerprint text;
  v_event_id uuid;
  v_occurrence_count integer;
  v_existing_id uuid;
  v_existing_incident text;
  v_deduplicated boolean := false;
begin
  if pg_column_size(v_payload) > 16384 then
    raise exception 'Operational payload exceeds 16 KiB.'
      using errcode = '22023';
  end if;

  if not v_is_service then
    if v_actor_user_id is null
       or p_hotel_id is null
       or not private.user_has_hotel_access(p_hotel_id)
    then
      raise exception 'Hotel access denied.'
        using errcode = '42501';
    end if;
  elsif p_hotel_id is not null
    and not exists (
      select 1
      from public.hotels h
      where h.id = p_hotel_id
    )
  then
    raise exception 'Unknown hotel context.'
      using errcode = '23503';
  end if;

  v_source := lower(coalesce(v_payload ->> 'source', 'client'));

  if not v_is_service then
    v_source := 'client';
  elsif v_source not in (
    'client',
    'edge_function',
    'webhook',
    'database',
    'deployment',
    'manual'
  ) then
    v_source := 'edge_function';
  end if;

  v_environment := lower(
    coalesce(v_payload ->> 'environment', 'production')
  );

  if v_environment not in (
    'development',
    'staging',
    'production',
    'test'
  ) then
    v_environment := 'production';
  end if;

  v_severity := lower(coalesce(v_payload ->> 'severity', 'error'));

  if v_severity not in ('info', 'warning', 'error', 'critical') then
    v_severity := 'error';
  end if;

  v_event_name := coalesce(
    nullif(
      private.day18_safe_log_text(
        v_payload ->> 'event_name',
        100
      ),
      ''
    ),
    'client.error'
  );

  v_error_name := nullif(
    private.day18_safe_log_text(
      v_payload ->> 'error_name',
      100
    ),
    ''
  );

  v_error_code := nullif(
    private.day18_safe_log_text(
      v_payload ->> 'error_code',
      100
    ),
    ''
  );

  v_message := coalesce(
    nullif(
      private.day18_safe_log_text(
        v_payload ->> 'message',
        1000
      ),
      ''
    ),
    'Unknown operational error'
  );

  v_route := nullif(
    private.day18_safe_log_text(
      v_payload ->> 'route',
      200
    ),
    ''
  );

  v_scope := nullif(
    private.day18_safe_log_text(
      v_payload ->> 'scope',
      100
    ),
    ''
  );

  v_component := nullif(
    private.day18_safe_log_text(
      v_payload ->> 'component',
      120
    ),
    ''
  );

  v_request_id := nullif(
    private.day18_safe_log_text(
      v_payload ->> 'request_id',
      96
    ),
    ''
  );

  v_release := nullif(
    private.day18_safe_log_text(
      v_payload ->> 'release',
      96
    ),
    ''
  );

  v_context := private.day18_safe_log_context(
    v_payload -> 'context'
  );

  v_incident_id := nullif(
    private.day18_safe_log_text(
      v_payload ->> 'incident_id',
      96
    ),
    ''
  );

  if v_incident_id is null
     or char_length(v_incident_id) < 8
  then
    v_incident_id :=
      'd18-' || replace(gen_random_uuid()::text, '-', '');
  end if;

  v_fingerprint := md5(
    concat_ws(
      '|',
      coalesce(p_hotel_id::text, 'platform'),
      v_environment,
      v_source,
      v_event_name,
      coalesce(v_error_name, ''),
      coalesce(v_error_code, ''),
      coalesce(v_route, ''),
      coalesce(v_scope, ''),
      coalesce(v_component, ''),
      left(v_message, 240)
    )
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext(
      coalesce(p_hotel_id::text, 'platform')
      || '|'
      || v_environment
      || '|'
      || v_fingerprint
    )
  );

  select
    event.id,
    event.incident_id
  into
    v_existing_id,
    v_existing_incident
  from public.operational_error_events event
  where event.hotel_id is not distinct from p_hotel_id
    and event.environment = v_environment
    and event.fingerprint = v_fingerprint
    and event.status in ('open', 'acknowledged')
    and event.last_seen_at >= now() - interval '30 minutes'
  order by event.last_seen_at desc, event.id desc
  limit 1
  for update;

  if v_existing_id is not null then
    update public.operational_error_events
    set
      severity = case
        when array_position(
          array['info', 'warning', 'error', 'critical'],
          v_severity
        ) > array_position(
          array['info', 'warning', 'error', 'critical'],
          severity
        )
        then v_severity
        else severity
      end,
      error_name = coalesce(v_error_name, error_name),
      error_code = coalesce(v_error_code, error_code),
      message = v_message,
      route = coalesce(v_route, route),
      scope = coalesce(v_scope, scope),
      component = coalesce(v_component, component),
      request_id = coalesce(v_request_id, request_id),
      release = coalesce(v_release, release),
      context = context || v_context,
      occurrence_count = occurrence_count + 1,
      last_seen_at = now(),
      updated_at = now()
    where id = v_existing_id
    returning
      id,
      incident_id,
      occurrence_count
    into
      v_event_id,
      v_incident_id,
      v_occurrence_count;

    v_deduplicated := true;
  else
    if exists (
      select 1
      from public.operational_error_events event
      where event.incident_id = v_incident_id
    ) then
      v_incident_id :=
        'd18-' || replace(gen_random_uuid()::text, '-', '');
    end if;

    insert into public.operational_error_events (
      hotel_id,
      actor_user_id,
      incident_id,
      fingerprint,
      source,
      environment,
      severity,
      status,
      event_name,
      error_name,
      error_code,
      message,
      route,
      scope,
      component,
      request_id,
      release,
      context
    )
    values (
      p_hotel_id,
      v_actor_user_id,
      v_incident_id,
      v_fingerprint,
      v_source,
      v_environment,
      v_severity,
      'open',
      v_event_name,
      v_error_name,
      v_error_code,
      v_message,
      v_route,
      v_scope,
      v_component,
      v_request_id,
      v_release,
      v_context
    )
    returning
      id,
      occurrence_count
    into
      v_event_id,
      v_occurrence_count;
  end if;

  return jsonb_build_object(
    'event_id', v_event_id,
    'incident_id', v_incident_id,
    'fingerprint', v_fingerprint,
    'occurrence_count', v_occurrence_count,
    'deduplicated', v_deduplicated,
    'recorded_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."report_operational_error"("p_hotel_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_folio_discount"("target_hotel_id" "uuid", "target_folio_id" "uuid", "discount_type_value" "text", "requested_value_value" numeric, "reason_value" "text", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  folio_row public.folios%rowtype;
  approval_row public.discount_approvals%rowtype;
  request_key text;
  amount_value numeric(14,2);
  normalized_type text;
begin
  if not private.user_has_any_permission(target_hotel_id,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Discount request access denied.';
  end if;
  actor_id_value := private.day11_require_current_actor();
  normalized_type := lower(trim(discount_type_value));
  if normalized_type not in ('fixed','percentage') then raise exception 'Discount type must be fixed or percentage.'; end if;
  if requested_value_value is null or requested_value_value <= 0 then raise exception 'Discount value must be positive.'; end if;
  if normalized_type = 'percentage' and requested_value_value > 100 then raise exception 'Percentage discount cannot exceed 100.'; end if;
  if nullif(trim(reason_value),'') is null then raise exception 'Discount reason is required.'; end if;
  request_key := coalesce(nullif(trim(request_id_value),''),gen_random_uuid()::text);

  select approval.* into approval_row
  from public.discount_approvals approval
  where approval.hotel_id = target_hotel_id and approval.idempotency_key = 'discount-request:' || request_key
  limit 1;
  if approval_row.id is not null then
    return jsonb_build_object('ok',true,'idempotent',true,'request_id',request_key,'approval',to_jsonb(approval_row));
  end if;

  select folio.* into folio_row
  from public.folios folio
  where folio.hotel_id = target_hotel_id and folio.id = target_folio_id
  for update;
  if not found then raise exception 'Folio was not found.'; end if;
  if folio_row.status = 'voided' or folio_row.balance_amount <= 0 then
    raise exception 'Discount requires a non-voided folio with positive balance.';
  end if;

  amount_value := case when normalized_type = 'fixed' then round(requested_value_value,2)
                       else round(folio_row.balance_amount * requested_value_value / 100,2) end;
  if amount_value <= 0 or amount_value > folio_row.balance_amount then
    raise exception 'Discount amount % exceeds open balance %.',amount_value,folio_row.balance_amount;
  end if;

  insert into public.discount_approvals(
    hotel_id,folio_id,discount_type,requested_value,requested_amount,reason,status,
    requested_by,idempotency_key,metadata
  ) values (
    target_hotel_id,target_folio_id,normalized_type,requested_value_value,amount_value,
    trim(reason_value),'pending',actor_id_value,'discount-request:' || request_key,
    jsonb_build_object('calculation_base',folio_row.balance_amount,'request_id',request_key,'day',11)
  ) returning * into approval_row;

  perform private.write_folio_event(target_hotel_id,target_folio_id,'folio.discount.requested','discount_approval',approval_row.id,to_jsonb(approval_row),jsonb_build_object('request_id',request_key,'day',11));
  return jsonb_build_object('ok',true,'idempotent',false,'request_id',request_key,'approval',to_jsonb(approval_row));
end;
$$;


ALTER FUNCTION "public"."request_folio_discount"("target_hotel_id" "uuid", "target_folio_id" "uuid", "discount_type_value" "text", "requested_value_value" numeric, "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_folio_refund"("target_hotel_id" "uuid", "target_folio_id" "uuid", "target_collection_id" "uuid", "amount_value" numeric, "reason_value" "text", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  collection_row public.folio_collections%rowtype;
  refund_row public.refunds%rowtype;
  request_key text;
  reserved_value numeric(14,2);
  available_value numeric(14,2);
begin
  if not private.user_has_any_permission(target_hotel_id,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Refund request access denied.';
  end if;
  actor_id_value := private.day11_require_current_actor();
  if amount_value is null or amount_value <= 0 then raise exception 'Refund amount must be positive.'; end if;
  if nullif(trim(reason_value),'') is null then raise exception 'Refund reason is required.'; end if;
  request_key := coalesce(nullif(trim(request_id_value),''),gen_random_uuid()::text);

  select refund.* into refund_row
  from public.refunds refund
  where refund.hotel_id = target_hotel_id and refund.idempotency_key = 'refund-request:' || request_key
  limit 1;
  if refund_row.id is not null then
    if refund_row.folio_id <> target_folio_id or refund_row.folio_collection_id <> target_collection_id or refund_row.amount <> amount_value then
      raise exception 'Refund idempotency key conflicts with a different request.';
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'request_id',request_key,'refund',to_jsonb(refund_row));
  end if;

  select collection.* into collection_row
  from public.folio_collections collection
  where collection.hotel_id = target_hotel_id and collection.folio_id = target_folio_id and collection.id = target_collection_id
  for update;
  if not found or collection_row.status <> 'posted' then raise exception 'Posted source collection was not found.'; end if;

  select coalesce(sum(refund.amount),0) into reserved_value
  from public.refunds refund
  where refund.hotel_id = target_hotel_id and refund.folio_collection_id = target_collection_id
    and refund.status in ('pending','processed');
  available_value := collection_row.amount - reserved_value;
  if amount_value > available_value then
    raise exception 'Refund amount % exceeds refundable collection balance %.',amount_value,available_value;
  end if;

  insert into public.refunds(
    hotel_id,folio_id,folio_collection_id,amount,payment_method,status,reason,
    provider,idempotency_key,requested_by,metadata
  ) values (
    target_hotel_id,target_folio_id,target_collection_id,amount_value,collection_row.payment_method,
    'pending',trim(reason_value),collection_row.provider,'refund-request:' || request_key,
    actor_id_value,jsonb_build_object('request_id',request_key,'source_collection_amount',collection_row.amount,'source_collection_reference',collection_row.transaction_reference,'day',11)
  ) returning * into refund_row;

  perform private.write_folio_event(target_hotel_id,target_folio_id,'folio.refund.requested','refund',refund_row.id,to_jsonb(refund_row),jsonb_build_object('request_id',request_key,'day',11));
  return jsonb_build_object('ok',true,'idempotent',false,'request_id',request_key,'refundable_before',available_value,'refund',to_jsonb(refund_row));
end;
$$;


ALTER FUNCTION "public"."request_folio_refund"("target_hotel_id" "uuid", "target_folio_id" "uuid", "target_collection_id" "uuid", "amount_value" numeric, "reason_value" "text", "request_id_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_folio_refund"("target_hotel_id" "uuid", "target_folio_id" "uuid", "target_collection_id" "uuid", "amount_value" numeric, "reason_value" "text", "request_id_value" "text") IS 'Collection-linked partial refund request with pending+processed reservation against over-refund.';



CREATE OR REPLACE FUNCTION "public"."resolve_guest_portal"("p_hotel_slug" "text", "p_access_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_token_id uuid;
  v_response jsonb;
begin
  v_token_id := private.resolve_guest_access_token(
    p_hotel_slug,
    p_access_token,
    true
  );

  if v_token_id is null then
    raise exception 'This guest access link is invalid or expired.';
  end if;

  select jsonb_build_object(
    'hotel', jsonb_build_object(
      'hotel_name', h.hotel_name,
      'slug', h.slug,
      'location', h.location,
      'timezone', h.timezone,
      'currency_code', h.currency_code
    ),
    'hotel_info',
      jsonb_strip_nulls(
        jsonb_build_object(
          'hotel_name', coalesce(hi.hotel_name, h.hotel_name),
          'address', coalesce(hi.address, h.address, h.location),
          'reception_phone', hi.reception_phone,
          'emergency_phone', hi.emergency_phone,
          'checkin_time', hi.checkin_time,
          'checkout_time', hi.checkout_time,
          'breakfast_time', hi.breakfast_time,
          'wifi_name', hi.wifi_name,
          'wifi_password', hi.wifi_password,
          'hotel_rules', hi.hotel_rules,
          'about', hi.about,
          'google_review_url', hi.google_review_url,
          'reward_title', hi.reward_title,
          'reward_description', hi.reward_description,
          'reward_enabled', coalesce(hi.reward_enabled, false)
        )
      )
      || coalesce(
        (
          select c.content
          from public.hotel_guest_content c
          where c.hotel_id = h.id
            and c.locale = 'en'
            and c.is_active
          limit 1
        ),
        '{}'::jsonb
      ),
    'guest_content', jsonb_build_object(
      'default_locale', 'en',
      'available_locales', coalesce(
        (
          select jsonb_agg(c.locale order by c.locale)
          from public.hotel_guest_content c
          where c.hotel_id = h.id
            and c.is_active
        ),
        '[]'::jsonb
      ),
      'translations', coalesce(
        (
          select jsonb_object_agg(c.locale, c.content)
          from public.hotel_guest_content c
          where c.hotel_id = h.id
            and c.is_active
        ),
        '{}'::jsonb
      ),
      'amenities', coalesce(
        (
          select jsonb_agg(
            jsonb_strip_nulls(
              jsonb_build_object(
                'id', a.id,
                'name', a.name,
                'description', a.description,
                'instructions', a.instructions,
                'icon', a.icon,
                'sort_order', a.sort_order
              )
            )
            order by a.sort_order, a.name
          )
          from public.amenities a
          where a.hotel_id = h.id
            and a.is_active
            and a.guest_visible
        ),
        '[]'::jsonb
      ),
      'feedback_enabled', true
    ),
    'session', jsonb_build_object(
      'id', gs.id,
      'checkin_time', gs.checkin_time,
      'checkout_time', gs.checkout_time,
      'extended_until', gs.extended_until,
      'guests', jsonb_build_object(
        'full_name', g.full_name
      ),
      'rooms', jsonb_build_object(
        'id', r.id,
        'room_number', r.room_number,
        'room_type', r.room_type
      )
    )
  )
  into v_response
  from public.guest_access_tokens t
  join public.hotels h
    on h.id = t.hotel_id
  join public.guest_sessions gs
    on gs.id = t.guest_session_id
  join public.guests g
    on g.id = gs.guest_id
   and g.hotel_id = t.hotel_id
  join public.rooms r
    on r.id = t.room_id
   and r.hotel_id = t.hotel_id
  left join public.hotel_info hi
    on hi.hotel_id = t.hotel_id
  where t.id = v_token_id;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."resolve_guest_portal"("p_hotel_slug" "text", "p_access_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "resolution_notes_value" "text", "requires_cleaning_value" boolean, "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.maintenance_tasks%rowtype;
  previous_status_value text;
  existing_event uuid;
begin
  actor_id_value :=
    private.day13_require_maintenance_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  if nullif(trim(resolution_notes_value), '') is null then
    raise exception 'Resolution notes are required.';
  end if;

  select event_record.id
  into existing_event
  from public.maintenance_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type = 'resolved';

  if existing_event is not null then
    select task.*
    into task_row
    from public.maintenance_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select task.*
  into task_row
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Maintenance task was not found.';
  end if;

  if task_row.status not in (
    'in_progress',
    'on_hold'
  ) then
    raise exception
      'Maintenance task can resolve only from in_progress or on_hold.';
  end if;

  previous_status_value := task_row.status;

  update public.maintenance_tasks
  set
    status = 'resolved',
    resolved_at = now(),
    resolved_by = actor_id_value,
    resolution_notes =
      trim(resolution_notes_value),
    requires_cleaning =
      coalesce(
        requires_cleaning_value,
        requires_cleaning
      ),
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'resolve_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_maintenance_event(
    target_hotel_id,
    target_task_id,
    'resolved',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'requires_cleaning',
      task_row.requires_cleaning
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row)
  );
end;
$$;


ALTER FUNCTION "public"."resolve_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "resolution_notes_value" "text", "requires_cleaning_value" boolean, "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_premium_guest_guide"("p_hotel_slug" "text", "p_access_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_token_id uuid;
  v_token public.guest_access_tokens%rowtype;
  v_snapshot jsonb;
  v_filtered_items jsonb;
  v_filtered_media jsonb;
  v_response jsonb;
  v_room_type_id uuid;
  v_hour integer;
  v_greeting_period text;
begin
  v_token_id := private.resolve_guest_access_token(
    p_hotel_slug,
    p_access_token,
    true
  );

  if v_token_id is null then
    raise exception 'This guest access link is invalid or expired.';
  end if;

  select t.*
  into v_token
  from public.guest_access_tokens t
  where t.id = v_token_id;

  select r.room_type_id
  into v_room_type_id
  from public.rooms r
  where r.hotel_id = v_token.hotel_id
    and r.id = v_token.room_id;

  select v.snapshot
  into v_snapshot
  from public.guest_guide_versions v
  join public.guest_guide_settings s
    on s.hotel_id = v.hotel_id
   and s.published_version = v.version_number
  where v.hotel_id = v_token.hotel_id
  order by v.version_number desc
  limit 1;

  if v_snapshot is null then
    v_snapshot :=
      private.day14_build_guide_snapshot(v_token.hotel_id);
  end if;

  select coalesce(
    jsonb_agg(x.item order by x.sort_order, x.item_key),
    '[]'::jsonb
  )
  into v_filtered_items
  from (
    select distinct on (
      item ->> 'section_id',
      item ->> 'item_key'
    )
      item,
      coalesce((item ->> 'sort_order')::integer, 0)
        as sort_order,
      item ->> 'item_key' as item_key,
      case item ->> 'scope_type'
        when 'room' then 3
        when 'room_type' then 2
        else 1
      end as scope_priority
    from jsonb_array_elements(
      coalesce(v_snapshot -> 'items', '[]'::jsonb)
    ) item
    where coalesce(
      (item ->> 'is_enabled')::boolean,
      true
    )
      and (
        item ->> 'scope_type' = 'hotel'
        or (
          item ->> 'scope_type' = 'room_type'
          and nullif(item ->> 'room_type_id', '')::uuid
            = v_room_type_id
        )
        or (
          item ->> 'scope_type' = 'room'
          and nullif(item ->> 'room_id', '')::uuid
            = v_token.room_id
        )
      )
    order by
      item ->> 'section_id',
      item ->> 'item_key',
      scope_priority desc
  ) x;

  select coalesce(
    jsonb_agg(
      item
      order by
        coalesce((item ->> 'sort_order')::integer, 0),
        item ->> 'media_key'
    ),
    '[]'::jsonb
  )
  into v_filtered_media
  from jsonb_array_elements(
    coalesce(v_snapshot -> 'media', '[]'::jsonb)
  ) item
  where coalesce(
    (item ->> 'is_active')::boolean,
    true
  )
    and (
      item ->> 'scope_type' = 'hotel'
      or (
        item ->> 'scope_type' = 'room_type'
        and nullif(item ->> 'room_type_id', '')::uuid
          = v_room_type_id
      )
      or (
        item ->> 'scope_type' = 'room'
        and nullif(item ->> 'room_id', '')::uuid
          = v_token.room_id
      )
    );

  select extract(
    hour from now() at time zone h.timezone
  )::integer
  into v_hour
  from public.hotels h
  where h.id = v_token.hotel_id;

  v_greeting_period :=
    case
      when v_hour between 5 and 11 then 'morning'
      when v_hour between 12 and 16 then 'afternoon'
      when v_hour between 17 and 21 then 'evening'
      else 'night'
    end;

  select jsonb_build_object(
    'hotel',
    jsonb_build_object(
      'hotel_name', h.hotel_name,
      'slug', h.slug,
      'location', h.location,
      'timezone', h.timezone,
      'currency_code', h.currency_code
    ),
    'hotel_info',
    jsonb_strip_nulls(
      jsonb_build_object(
        'hotel_name', coalesce(hi.hotel_name, h.hotel_name),
        'address', coalesce(hi.address, h.address, h.location),
        'reception_phone', hi.reception_phone,
        'emergency_phone', hi.emergency_phone,
        'checkin_time', hi.checkin_time,
        'checkout_time', hi.checkout_time,
        'breakfast_time', hi.breakfast_time,
        'wifi_name', hi.wifi_name,
        'wifi_password', hi.wifi_password,
        'hotel_rules', hi.hotel_rules,
        'about', hi.about,
        'google_review_url', hi.google_review_url,
        'reward_title', hi.reward_title,
        'reward_description', hi.reward_description,
        'reward_enabled', coalesce(hi.reward_enabled, false)
      )
    ),
    'guest_content',
    jsonb_build_object(
      'default_locale',
        v_snapshot #>> '{settings,default_locale}',
      'available_locales',
        coalesce(
          v_snapshot #> '{settings,enabled_locales}',
          '["en"]'::jsonb
        ),
      'translations',
        coalesce(
          v_snapshot -> 'legacy_content',
          '{}'::jsonb
        ),
      'amenities',
        coalesce(
          (
            select jsonb_agg(
              jsonb_strip_nulls(
                jsonb_build_object(
                  'id', a.id,
                  'name', a.name,
                  'description', a.description,
                  'instructions', a.instructions,
                  'icon', a.icon,
                  'sort_order', a.sort_order
                )
              )
              order by a.sort_order, a.name
            )
            from public.amenities a
            where a.hotel_id = h.id
              and a.is_active
              and a.guest_visible
          ),
          '[]'::jsonb
        ),
      'feedback_enabled', true
    ),
    'premium_guide',
    jsonb_build_object(
      'schema_version',
        coalesce(
          (v_snapshot ->> 'schema_version')::integer,
          1
        ),
      'settings',
        coalesce(v_snapshot -> 'settings', '{}'::jsonb),
      'sections',
        coalesce(v_snapshot -> 'sections', '[]'::jsonb),
      'items',
        v_filtered_items,
      'media',
        v_filtered_media,
      'payment_profile',
        coalesce(
          v_snapshot -> 'payment_profile',
          '{}'::jsonb
        ),
      'greetings',
        coalesce(v_snapshot -> 'greetings', '{}'::jsonb),
      'greeting_period',
        v_greeting_period,
      'storage_public_base',
        '/storage/v1/object/public/guest-guide-media/'
    ),
    'session',
    jsonb_build_object(
      'id', gs.id,
      'checkin_time', gs.checkin_time,
      'checkout_time', gs.checkout_time,
      'extended_until', gs.extended_until,
      'guest',
      jsonb_build_object(
        'id', g.id,
        'full_name', g.full_name
      ),
      'room',
      jsonb_build_object(
        'id', r.id,
        'room_number', r.room_number,
        'room_type', r.room_type,
        'room_type_id', r.room_type_id
      )
    ),
    'folio',
    coalesce(
      (
        select jsonb_build_object(
          'id', f.id,
          'currency_code', f.currency_code,
          'status', f.status,
          'charges_amount', f.charges_amount,
          'discount_amount', f.discount_amount,
          'tax_amount', f.tax_amount,
          'collection_amount', f.collection_amount,
          'refund_amount', f.refund_amount,
          'credit_amount', f.credit_amount,
          'balance_amount', f.balance_amount
        )
        from public.folios f
        where f.hotel_id = gs.hotel_id
          and f.guest_session_id = gs.id
        order by f.created_at desc
        limit 1
      ),
      '{}'::jsonb
    )
  )
  into v_response
  from public.guest_access_tokens t
  join public.hotels h
    on h.id = t.hotel_id
  join public.guest_sessions gs
    on gs.id = t.guest_session_id
   and gs.hotel_id = t.hotel_id
  join public.guests g
    on g.id = gs.guest_id
   and g.hotel_id = t.hotel_id
  join public.rooms r
    on r.id = t.room_id
   and r.hotel_id = t.hotel_id
  left join public.hotel_info hi
    on hi.hotel_id = t.hotel_id
  where t.id = v_token_id;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."resolve_premium_guest_guide"("p_hotel_slug" "text", "p_access_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_notification_delivery"("p_delivery_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.notification_deliveries%rowtype;
begin
  select *
  into v_row
  from public.notification_deliveries nd
  where nd.id = p_delivery_id
  for update;

  if not found then
    raise exception 'Notification delivery was not found.';
  end if;

  if not (
    private.is_platform_admin()
    or private.day17_can_manage_hotel(v_row.hotel_id)
  ) then
    raise exception 'Notification retry access denied.';
  end if;

  if v_row.status not in ('failed', 'retrying') then
    raise exception 'Only failed or retrying deliveries can be retried.';
  end if;

  update public.notification_deliveries nd
  set
    status = 'pending',
    next_attempt_at = now(),
    last_error_code = null,
    last_error_message = null,
    updated_at = now()
  where nd.id = p_delivery_id
  returning * into v_row;

  delete from public.notification_dead_letters ndl
  where ndl.delivery_id = p_delivery_id;

  return jsonb_build_object(
    'delivery_id', v_row.id,
    'status', v_row.status,
    'next_attempt_at', v_row.next_attempt_at
  );
end;
$$;


ALTER FUNCTION "public"."retry_notification_delivery"("p_delivery_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_folio_discount"("target_hotel_id" "uuid", "target_approval_id" "uuid", "approve_value" boolean, "review_notes_value" "text" DEFAULT NULL::"text", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  approval_row public.discount_approvals%rowtype;
  folio_row public.folios%rowtype;
  target_status text;
  request_key text;
begin
  if not private.user_has_any_permission(target_hotel_id,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Discount review access denied.';
  end if;
  actor_id_value := private.day11_require_current_actor();
  target_status := case when approve_value then 'approved' else 'rejected' end;
  request_key := coalesce(nullif(trim(request_id_value),''),gen_random_uuid()::text);

  select approval.* into approval_row
  from public.discount_approvals approval
  where approval.hotel_id = target_hotel_id and approval.id = target_approval_id
  for update;
  if not found then raise exception 'Discount approval was not found.'; end if;
  if approval_row.status <> 'pending' then
    if approval_row.status = target_status then
      return jsonb_build_object('ok',true,'idempotent',true,'request_id',request_key,'approval',to_jsonb(approval_row));
    end if;
    raise exception 'Discount request is already %.',approval_row.status;
  end if;

  if approve_value then
    select folio.* into folio_row
    from public.folios folio
    where folio.hotel_id = target_hotel_id and folio.id = approval_row.folio_id
    for update;
    if folio_row.status = 'voided' or approval_row.requested_amount > folio_row.balance_amount then
      raise exception 'Approved discount % exceeds current open balance %.',approval_row.requested_amount,folio_row.balance_amount;
    end if;
  end if;

  update public.discount_approvals
  set status = target_status, reviewed_by = actor_id_value, reviewed_at = now(),
      review_notes = nullif(trim(review_notes_value),''),
      metadata = metadata || jsonb_build_object('review_request_id',request_key,'review_decision',target_status)
  where hotel_id = target_hotel_id and id = target_approval_id
  returning * into approval_row;

  perform private.write_folio_event(target_hotel_id,approval_row.folio_id,'folio.discount.' || target_status,'discount_approval',approval_row.id,to_jsonb(approval_row),jsonb_build_object('request_id',request_key,'day',11));
  return jsonb_build_object('ok',true,'idempotent',false,'request_id',request_key,'approval',to_jsonb(approval_row));
end;
$$;


ALTER FUNCTION "public"."review_folio_discount"("target_hotel_id" "uuid", "target_approval_id" "uuid", "approve_value" boolean, "review_notes_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_guest_document"("target_hotel_id" "uuid", "target_document_id" "uuid", "target_action" "text", "target_rejection_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  normalized_action text := lower(trim(coalesce(target_action, '')));
  document_before public.guest_documents%rowtype;
  document_after public.guest_documents%rowtype;
  normalized_reason text := nullif(trim(target_rejection_reason), '');
  guest_next_status text;
  activity_id uuid;
begin
  if actor_id is null then
    raise exception 'Authentication is required.';
  end if;

  if not private.user_has_permission(target_hotel_id, 'guests.manage') then
    raise exception 'Only authorized guest managers can review KYC documents.';
  end if;

  if normalized_action not in (
    'verify',
    'reject',
    'expire',
    'reset_pending'
  ) then
    raise exception 'Unsupported review action.';
  end if;

  if normalized_action = 'reject' and normalized_reason is null then
    raise exception 'A rejection reason is required.';
  end if;

  select *
  into document_before
  from public.guest_documents gd
  where gd.hotel_id = target_hotel_id
    and gd.id = target_document_id
    and gd.deleted_at is null
  for update;

  if not found then
    raise exception 'Guest document was not found.';
  end if;

  update public.guest_documents gd
  set
    verification_status = case normalized_action
      when 'verify' then 'verified'
      when 'reject' then 'rejected'
      when 'expire' then 'expired'
      else 'pending'
    end,
    verified_by = case
      when normalized_action = 'reset_pending' then null
      else actor_id
    end,
    verified_at = case
      when normalized_action = 'reset_pending' then null
      else now()
    end,
    rejection_reason = case
      when normalized_action = 'reject' then normalized_reason
      else null
    end,
    reviewed_at = now(),
    review_action = case normalized_action
      when 'verify' then 'verified'
      when 'reject' then 'rejected'
      when 'expire' then 'expired'
      else 'reset_pending'
    end,
    updated_at = now()
  where gd.hotel_id = target_hotel_id
    and gd.id = target_document_id
  returning * into document_after;

  if normalized_action = 'verify' then
    guest_next_status := 'verified';
  elsif exists (
    select 1
    from public.guest_documents other_document
    where other_document.hotel_id = target_hotel_id
      and other_document.guest_id = document_after.guest_id
      and other_document.id <> document_after.id
      and other_document.deleted_at is null
      and other_document.verification_status = 'verified'
  ) then
    guest_next_status := 'verified';
  elsif normalized_action = 'reject' then
    guest_next_status := 'rejected';
  elsif normalized_action = 'reset_pending' then
    guest_next_status := 'pending';
  else
    guest_next_status := 'unverified';
  end if;

  update public.guests g
  set
    identity_verification_status = guest_next_status,
    updated_at = now()
  where g.hotel_id = target_hotel_id
    and g.id = document_after.guest_id;

  activity_id := private.write_activity_log(
    target_hotel_id,
    'front_office.guest_document_' || normalized_action,
    'guest_document',
    document_after.id,
    'Private guest document review state changed.',
    jsonb_build_object(
      'verification_status', document_before.verification_status,
      'rejection_reason', document_before.rejection_reason
    ),
    jsonb_build_object(
      'verification_status', document_after.verification_status,
      'rejection_reason', document_after.rejection_reason,
      'guest_identity_status', guest_next_status
    ),
    jsonb_build_object(
      'guest_id', document_after.guest_id,
      'review_action', normalized_action
    )
  );

  return jsonb_build_object(
    'ok', true,
    'activity_id', activity_id,
    'guest_identity_status', guest_next_status,
    'document', to_jsonb(document_after)
  );
end;
$$;


ALTER FUNCTION "public"."review_guest_document"("target_hotel_id" "uuid", "target_document_id" "uuid", "target_action" "text", "target_rejection_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_guest_document"("target_hotel_id" "uuid", "target_document_id" "uuid", "target_action" "text", "target_rejection_reason" "text") IS 'Day 10 authoritative guest-document verify/reject/expire/reset workflow with guest identity synchronization and immutable activity evidence.';



CREATE OR REPLACE FUNCTION "public"."revoke_guest_access_token"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "revocation_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  affected_count integer;
begin
  if not private.user_has_permission(target_hotel_id, 'hotel.manage') then
    raise exception 'You do not have permission to revoke guest access.';
  end if;

  if not exists (
    select 1
    from public.guest_sessions gs
    where gs.id = target_guest_session_id
      and gs.hotel_id = target_hotel_id
  ) then
    raise exception 'The selected stay does not belong to this hotel.';
  end if;

  update public.guest_access_tokens
  set status = 'revoked',
      revoked_at = coalesce(revoked_at, now()),
      revoked_by = auth.uid(),
      revocation_reason = coalesce(
        nullif(trim($3), ''),
        'Manual guest access revocation'
      ),
      updated_at = now()
  where hotel_id = target_hotel_id
    and guest_session_id = target_guest_session_id
    and status = 'active';

  get diagnostics affected_count = row_count;

  return jsonb_build_object(
    'result', 'GUEST ACCESS REVOKED',
    'revoked_tokens', affected_count
  );
end;
$_$;


ALTER FUNCTION "public"."revoke_guest_access_token"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "revocation_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."revoke_guest_access_token"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "revocation_reason" "text") IS 'Hotel-scoped manual guest-access revocation. Uses positional parameter reference to avoid column-name ambiguity.';



CREATE OR REPLACE FUNCTION "public"."rotate_guest_access_token"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "rotation_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  token_id uuid;
  rendered_token text;
  hotel_slug text;
begin
  if not private.user_has_permission(target_hotel_id, 'hotel.manage') then
    raise exception 'You do not have permission to rotate guest access.';
  end if;

  if not exists (
    select 1
    from public.guest_sessions gs
    where gs.id = target_guest_session_id
      and gs.hotel_id = target_hotel_id
      and gs.status = 'active'
  ) then
    raise exception 'The selected active stay does not belong to this hotel.';
  end if;

  token_id := private.issue_guest_access_token(
    target_guest_session_id,
    true,
    coalesce(nullif(trim(rotation_reason), ''), 'Manual guest access rotation')
  );

  rendered_token := private.render_guest_access_token(token_id);

  select slug into hotel_slug
  from public.hotels
  where id = target_hotel_id;

  return jsonb_build_object(
    'result', 'GUEST ACCESS ROTATED',
    'guest_path', '/guest/' || hotel_slug || '/' || rendered_token,
    'food_path', '/food/' || hotel_slug || '/' || rendered_token
  );
end;
$$;


ALTER FUNCTION "public"."rotate_guest_access_token"("target_hotel_id" "uuid", "target_guest_session_id" "uuid", "rotation_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_hotel_onboarding_step"("target_hotel_id" "uuid", "target_step" "text", "step_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  onboarding_row public.hotel_onboarding%rowtype;
  readiness jsonb;
  checklist_key text;
  step_ready boolean := false;
  complete_requested boolean := false;
  sanitized_payload jsonb;
  next_step text;
  updated_onboarding jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if target_hotel_id is null then
    raise exception 'Hotel is required.';
  end if;

  if target_step not in (
    'hotel_details',
    'policies',
    'room_types',
    'floors_rooms',
    'amenities',
    'request_categories',
    'menu',
    'invoice',
    'subscription',
    'review'
  ) then
    raise exception 'Unsupported onboarding step: %.', target_step;
  end if;

  if step_payload is null or jsonb_typeof(step_payload) <> 'object' then
    raise exception 'Step payload must be a JSON object.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_permission(target_hotel_id, 'hotel.manage')
    or exists (
      select 1
      from public.hotel_onboarding ho
      where ho.hotel_id = target_hotel_id
        and ho.owner_user_id = actor_user_id
    )
  ) then
    raise exception 'Onboarding update access denied.';
  end if;

  select ho.*
  into onboarding_row
  from public.hotel_onboarding ho
  where ho.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Hotel onboarding state is missing.';
  end if;

  begin
    complete_requested := coalesce(
      (step_payload ->> 'complete')::boolean,
      false
    );
  exception when invalid_text_representation then
    raise exception 'complete must be true or false.';
  end;

  sanitized_payload := step_payload - 'complete';
  readiness := private.compute_hotel_onboarding_readiness(target_hotel_id);

  checklist_key := case target_step
    when 'hotel_details' then 'hotel_details'
    when 'policies' then 'settings'
    when 'room_types' then 'room_types'
    when 'floors_rooms' then 'rooms'
    when 'amenities' then 'amenities'
    when 'request_categories' then 'request_categories'
    when 'menu' then 'menu'
    when 'invoice' then 'invoice'
    when 'subscription' then 'subscription'
    when 'review' then 'ready'
  end;

  if target_step = 'review' then
    step_ready := coalesce((readiness ->> 'ready')::boolean, false);
  else
    step_ready := coalesce(
      (readiness -> 'checklist' ->> checklist_key)::boolean,
      false
    );
  end if;

  if complete_requested and not step_ready then
    raise exception
      'Step % cannot be completed because its server readiness check is false.',
      target_step;
  end if;

  next_step := case
    when complete_requested
      then private.onboarding_next_step(target_step)
    else onboarding_row.current_step
  end;

  update public.hotel_onboarding ho
  set
    form_state = jsonb_set(
      coalesce(ho.form_state, '{}'::jsonb),
      array[target_step],
      sanitized_payload,
      true
    ),
    completed_steps = case
      when complete_requested then array(
        select distinct completed_step
        from unnest(
          coalesce(ho.completed_steps, '{}'::text[])
          || array[target_step]::text[]
        ) completed_step
        order by completed_step
      )
      else ho.completed_steps
    end,
    current_step = case
      when complete_requested then next_step
      else ho.current_step
    end,
    readiness_state = readiness,
    status = case
      when target_step = 'review'
       and complete_requested
       and step_ready
        then 'complete'
      else 'in_progress'
    end,
    completed_at = case
      when target_step = 'review'
       and complete_requested
       and step_ready
        then coalesce(ho.completed_at, now())
      else null
    end,
    last_error = null,
    last_saved_at = now(),
    updated_by = actor_user_id,
    version = ho.version + 1
  where ho.hotel_id = target_hotel_id
  returning to_jsonb(ho) into updated_onboarding;

  return jsonb_build_object(
    'hotel_id', target_hotel_id,
    'step', target_step,
    'step_ready', step_ready,
    'complete_requested', complete_requested,
    'next_step', next_step,
    'onboarding', updated_onboarding,
    'readiness', readiness
  );
end;
$$;


ALTER FUNCTION "public"."save_hotel_onboarding_step"("target_hotel_id" "uuid", "target_step" "text", "step_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_menu_locale_translations"("p_hotel_id" "uuid", "p_locale" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_locale text := lower(trim(coalesce(p_locale, '')));
  v_entry jsonb;
  v_updated_categories integer := 0;
  v_updated_items integer := 0;
  v_updated_groups integer := 0;
  v_updated_modifiers integer := 0;
begin
  if not private.user_has_permission(p_hotel_id, 'hotel.manage') then
    raise exception 'Menu translation update denied.';
  end if;

  if not (v_locale = any(array[
    'en','hi','mr','ta','te','bn','gu','kn','ml','pa','or','as'
  ]::text[])) then
    raise exception 'Unsupported dining locale.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Menu translation payload must be a JSON object.';
  end if;

  for v_entry in
    select value
    from jsonb_array_elements(coalesce(p_payload -> 'categories', '[]'::jsonb))
  loop
    update public.menu_categories mc
    set translations = jsonb_set(
      coalesce(mc.translations, '{}'::jsonb),
      array[v_locale],
      jsonb_strip_nulls(jsonb_build_object(
        'name', nullif(trim(v_entry ->> 'name'), '')
      )),
      true
    )
    where mc.hotel_id = p_hotel_id
      and mc.id = nullif(v_entry ->> 'id', '')::uuid;
    v_updated_categories := v_updated_categories + case when found then 1 else 0 end;
  end loop;

  for v_entry in
    select value
    from jsonb_array_elements(coalesce(p_payload -> 'items', '[]'::jsonb))
  loop
    update public.menu_items mi
    set translations = jsonb_set(
      coalesce(mi.translations, '{}'::jsonb),
      array[v_locale],
      jsonb_strip_nulls(jsonb_build_object(
        'item_name', nullif(trim(v_entry ->> 'item_name'), ''),
        'description', nullif(trim(v_entry ->> 'description'), '')
      )),
      true
    )
    where mi.hotel_id = p_hotel_id
      and mi.id = nullif(v_entry ->> 'id', '')::uuid;
    v_updated_items := v_updated_items + case when found then 1 else 0 end;
  end loop;

  for v_entry in
    select value
    from jsonb_array_elements(coalesce(p_payload -> 'groups', '[]'::jsonb))
  loop
    update public.menu_item_modifier_groups mg
    set translations = jsonb_set(
      coalesce(mg.translations, '{}'::jsonb),
      array[v_locale],
      jsonb_strip_nulls(jsonb_build_object(
        'name', nullif(trim(v_entry ->> 'name'), '')
      )),
      true
    )
    where mg.hotel_id = p_hotel_id
      and mg.id = nullif(v_entry ->> 'id', '')::uuid;
    v_updated_groups := v_updated_groups + case when found then 1 else 0 end;
  end loop;

  for v_entry in
    select value
    from jsonb_array_elements(coalesce(p_payload -> 'modifiers', '[]'::jsonb))
  loop
    update public.menu_item_modifiers mm
    set translations = jsonb_set(
      coalesce(mm.translations, '{}'::jsonb),
      array[v_locale],
      jsonb_strip_nulls(jsonb_build_object(
        'name', nullif(trim(v_entry ->> 'name'), '')
      )),
      true
    )
    where mm.hotel_id = p_hotel_id
      and mm.id = nullif(v_entry ->> 'id', '')::uuid;
    v_updated_modifiers := v_updated_modifiers + case when found then 1 else 0 end;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'locale', v_locale,
    'categories', v_updated_categories,
    'items', v_updated_items,
    'groups', v_updated_groups,
    'modifiers', v_updated_modifiers
  );
end;
$$;


ALTER FUNCTION "public"."save_menu_locale_translations"("p_hotel_id" "uuid", "p_locale" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_platform_announcement"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  target_id uuid;
  scope_value text;
  status_value text;
  target_hotel_id_value uuid;
  saved_row public.announcements%rowtype;
begin
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception
      'Announcement payload must be a JSON object.';
  end if;

  target_id :=
    nullif(trim(payload ->> 'id'), '')::uuid;
  scope_value :=
    coalesce(
      nullif(trim(payload ->> 'scope'), ''),
      'global'
    );
  status_value :=
    coalesce(
      nullif(trim(payload ->> 'status'), ''),
      'draft'
    );
  target_hotel_id_value :=
    nullif(
      trim(payload ->> 'target_hotel_id'),
      ''
    )::uuid;

  if nullif(trim(payload ->> 'title'), '') is null
     or nullif(trim(payload ->> 'body'), '') is null
  then
    raise exception
      'Announcement title and body are required.';
  end if;

  if scope_value = 'global' then
    target_hotel_id_value := null;
  elsif scope_value = 'hotel'
    and target_hotel_id_value is null
  then
    raise exception
      'Hotel-targeted announcements require target_hotel_id.';
  end if;

  if target_id is null then
    insert into public.announcements (
      scope,
      target_hotel_id,
      title,
      body,
      severity,
      status,
      starts_at,
      ends_at,
      created_by,
      published_by,
      published_at,
      metadata,
      created_at,
      updated_at
    ) values (
      scope_value,
      target_hotel_id_value,
      trim(payload ->> 'title'),
      trim(payload ->> 'body'),
      coalesce(
        nullif(trim(payload ->> 'severity'), ''),
        'info'
      ),
      status_value,
      nullif(
        trim(payload ->> 'starts_at'),
        ''
      )::timestamptz,
      nullif(
        trim(payload ->> 'ends_at'),
        ''
      )::timestamptz,
      actor_user_id,
      case when status_value = 'published'
        then actor_user_id end,
      case when status_value = 'published'
        then now() end,
      coalesce(payload -> 'metadata', '{}'::jsonb),
      now(),
      now()
    )
    returning * into saved_row;
  else
    update public.announcements a
    set
      scope = scope_value,
      target_hotel_id = target_hotel_id_value,
      title = trim(payload ->> 'title'),
      body = trim(payload ->> 'body'),
      severity = coalesce(
        nullif(trim(payload ->> 'severity'), ''),
        a.severity
      ),
      status = status_value,
      starts_at = case
        when payload ? 'starts_at'
          then nullif(
            trim(payload ->> 'starts_at'),
            ''
          )::timestamptz
        else a.starts_at
      end,
      ends_at = case
        when payload ? 'ends_at'
          then nullif(
            trim(payload ->> 'ends_at'),
            ''
          )::timestamptz
        else a.ends_at
      end,
      published_by = case
        when status_value = 'published'
          then coalesce(a.published_by, actor_user_id)
        else a.published_by
      end,
      published_at = case
        when status_value = 'published'
          then coalesce(a.published_at, now())
        else a.published_at
      end,
      metadata = case
        when payload ? 'metadata'
          then coalesce(
            payload -> 'metadata',
            '{}'::jsonb
          )
        else a.metadata
      end,
      updated_at = now()
    where a.id = target_id
    returning * into saved_row;

    if not found then
      raise exception
        'Announcement was not found.';
    end if;
  end if;

  return jsonb_build_object(
    'announcement', to_jsonb(saved_row)
  );
end;
$$;


ALTER FUNCTION "public"."save_platform_announcement"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_subscription_plan"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  target_plan_id uuid;
  saved_plan public.subscription_plans%rowtype;
  plan_name_value text;
  plan_code_value text;
  currency_value text;
  features_value jsonb;
  monthly_price numeric;
  annual_price numeric;
begin
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Plan payload must be a JSON object.';
  end if;

  target_plan_id :=
    nullif(trim(payload ->> 'id'), '')::uuid;
  plan_name_value :=
    nullif(trim(payload ->> 'plan_name'), '');
  plan_code_value := upper(
    coalesce(
      nullif(trim(payload ->> 'plan_code'), ''),
      private.normalize_hotel_slug(plan_name_value)
    )
  );
  currency_value := upper(
    coalesce(
      nullif(trim(payload ->> 'currency_code'), ''),
      'INR'
    )
  );
  features_value :=
    coalesce(payload -> 'features', '[]'::jsonb);
  monthly_price :=
    coalesce(
      nullif(trim(payload ->> 'price_monthly'), '')::numeric,
      0
    );
  annual_price :=
    nullif(trim(payload ->> 'price_annual'), '')::numeric;

  if plan_name_value is null
     or plan_code_value is null
  then
    raise exception 'Plan name and plan code are required.';
  end if;

  if jsonb_typeof(features_value) not in ('array', 'object') then
    raise exception
      'Plan features must be a JSON array or object.';
  end if;

  if target_plan_id is null then
    insert into public.subscription_plans (
      plan_name,
      plan_code,
      price_monthly,
      price_annual,
      max_rooms,
      max_staff,
      max_properties,
      max_storage_mb,
      trial_days,
      currency_code,
      features,
      is_public,
      status,
      created_at,
      updated_at
    ) values (
      plan_name_value,
      plan_code_value,
      monthly_price,
      annual_price,
      nullif(trim(payload ->> 'max_rooms'), '')::integer,
      nullif(trim(payload ->> 'max_staff'), '')::integer,
      coalesce(
        nullif(
          trim(payload ->> 'max_properties'),
          ''
        )::integer,
        1
      ),
      nullif(
        trim(payload ->> 'max_storage_mb'),
        ''
      )::bigint,
      coalesce(
        nullif(trim(payload ->> 'trial_days'), '')::integer,
        14
      ),
      currency_value,
      features_value,
      coalesce(
        nullif(trim(payload ->> 'is_public'), '')::boolean,
        true
      ),
      coalesce(
        nullif(trim(payload ->> 'status'), ''),
        'active'
      ),
      now(),
      now()
    )
    returning * into saved_plan;
  else
    update public.subscription_plans sp
    set
      plan_name = plan_name_value,
      plan_code = plan_code_value,
      price_monthly = monthly_price,
      price_annual = annual_price,
      max_rooms = case
        when payload ? 'max_rooms'
          then nullif(
            trim(payload ->> 'max_rooms'),
            ''
          )::integer
        else sp.max_rooms
      end,
      max_staff = case
        when payload ? 'max_staff'
          then nullif(
            trim(payload ->> 'max_staff'),
            ''
          )::integer
        else sp.max_staff
      end,
      max_properties = coalesce(
        nullif(
          trim(payload ->> 'max_properties'),
          ''
        )::integer,
        sp.max_properties
      ),
      max_storage_mb = case
        when payload ? 'max_storage_mb'
          then nullif(
            trim(payload ->> 'max_storage_mb'),
            ''
          )::bigint
        else sp.max_storage_mb
      end,
      trial_days = coalesce(
        nullif(trim(payload ->> 'trial_days'), '')::integer,
        sp.trial_days
      ),
      currency_code = currency_value,
      features = features_value,
      is_public = coalesce(
        nullif(trim(payload ->> 'is_public'), '')::boolean,
        sp.is_public
      ),
      status = coalesce(
        nullif(trim(payload ->> 'status'), ''),
        sp.status
      ),
      updated_at = now()
    where sp.id = target_plan_id
    returning * into saved_plan;

    if not found then
      raise exception 'Subscription plan was not found.';
    end if;
  end if;

  insert into public.subscription_plan_prices (
    plan_id,
    provider,
    billing_cycle,
    currency_code,
    amount_minor,
    status,
    metadata,
    created_by,
    updated_by,
    created_at,
    updated_at
  ) values (
    saved_plan.id,
    'manual',
    'monthly',
    saved_plan.currency_code,
    round(coalesce(saved_plan.price_monthly, 0) * 100)::bigint,
    case when saved_plan.status = 'active'
      then 'active' else 'inactive' end,
    jsonb_build_object(
      'source', 'save_subscription_plan'
    ),
    actor_user_id,
    actor_user_id,
    now(),
    now()
  )
  on conflict (
    plan_id,
    provider,
    billing_cycle,
    currency_code
  ) do update
  set
    amount_minor = excluded.amount_minor,
    status = excluded.status,
    metadata =
      public.subscription_plan_prices.metadata
      || excluded.metadata,
    updated_by = excluded.updated_by,
    updated_at = now();

  if saved_plan.price_annual is not null then
    insert into public.subscription_plan_prices (
      plan_id,
      provider,
      billing_cycle,
      currency_code,
      amount_minor,
      status,
      metadata,
      created_by,
      updated_by,
      created_at,
      updated_at
    ) values (
      saved_plan.id,
      'manual',
      'annual',
      saved_plan.currency_code,
      round(saved_plan.price_annual * 100)::bigint,
      case when saved_plan.status = 'active'
        then 'active' else 'inactive' end,
      jsonb_build_object(
        'source', 'save_subscription_plan'
      ),
      actor_user_id,
      actor_user_id,
      now(),
      now()
    )
    on conflict (
      plan_id,
      provider,
      billing_cycle,
      currency_code
    ) do update
    set
      amount_minor = excluded.amount_minor,
      status = excluded.status,
      metadata =
        public.subscription_plan_prices.metadata
        || excluded.metadata,
      updated_by = excluded.updated_by,
      updated_at = now();
  end if;

  return jsonb_build_object(
    'plan', to_jsonb(saved_plan),
    'prices', (
      select coalesce(
        jsonb_agg(to_jsonb(spp) order by spp.billing_cycle),
        '[]'::jsonb
      )
      from public.subscription_plan_prices spp
      where spp.plan_id = saved_plan.id
    )
  );
exception
  when unique_violation then
    raise exception
      'A plan with the same name, code or provider-price contract already exists.';
end;
$$;


ALTER FUNCTION "public"."save_subscription_plan"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_reservation_guests"("target_hotel_id" "uuid", "search_text" "text" DEFAULT NULL::"text", "result_limit" integer DEFAULT 20) RETURNS TABLE("guest_id" "uuid", "full_name" "text", "phone" "text", "email" "text", "id_type" "text", "id_number" "text", "preferred_language" "text", "created_at" timestamp with time zone, "reservation_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_search text;
  safe_limit integer;
begin
  if not private.user_has_hotel_access(target_hotel_id) then
    raise exception 'Hotel access denied.';
  end if;

  normalized_search := lower(trim(coalesce(search_text, '')));
  safe_limit := least(greatest(coalesce(result_limit, 20), 1), 50);

  return query
  select
    g.id,
    g.full_name,
    g.phone,
    g.email,
    g.id_type,
    g.id_number,
    g.preferred_language,
    g.created_at,
    (
      select count(*)
      from public.reservations r
      where r.hotel_id = g.hotel_id
        and r.primary_guest_id = g.id
    )::bigint
  from public.guests g
  where g.hotel_id = target_hotel_id
    and (
      normalized_search = ''
      or lower(g.full_name) like '%' || normalized_search || '%'
      or lower(coalesce(g.phone, '')) like
        '%' || normalized_search || '%'
      or lower(coalesce(g.email, '')) like
        '%' || normalized_search || '%'
      or lower(coalesce(g.id_number, '')) like
        '%' || normalized_search || '%'
    )
  order by
    case
      when lower(g.full_name) = normalized_search then 0
      when lower(coalesce(g.phone, '')) = normalized_search then 0
      else 1
    end,
    g.created_at desc
  limit safe_limit;
end;
$$;


ALTER FUNCTION "public"."search_reservation_guests"("target_hotel_id" "uuid", "search_text" "text", "result_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_hotel_configuration_defaults"("target_hotel_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  result jsonb;
  readiness jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if not (
    private.is_platform_admin()
    or private.user_has_permission(target_hotel_id, 'hotel.manage')
  ) then
    raise exception 'Hotel configuration access denied.';
  end if;

  result :=
    private.seed_hotel_configuration_defaults_internal(
      target_hotel_id,
      actor_user_id
    );

  readiness :=
    private.compute_hotel_onboarding_readiness(
      target_hotel_id
    );

  update public.hotel_onboarding ho
  set
    readiness_state = readiness,
    last_saved_at = now(),
    updated_by = actor_user_id,
    version = ho.version + 1
  where ho.hotel_id = target_hotel_id;

  return result || jsonb_build_object(
    'readiness',
    readiness
  );
end;
$$;


ALTER FUNCTION "public"."seed_hotel_configuration_defaults"("target_hotel_id" "uuid") OWNER TO "postgres";


