CREATE OR REPLACE FUNCTION "public"."set_operational_incident_status"("p_hotel_id" "uuid", "p_event_id" "uuid", "p_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text := lower(trim(coalesce(p_status, '')));
  v_actor uuid := auth.uid();
  v_result jsonb;
begin
  if p_hotel_id is null
     or not private.day17_can_manage_hotel(p_hotel_id)
  then
    raise exception 'Hotel management access required.'
      using errcode = '42501';
  end if;

  if v_status not in ('open', 'acknowledged', 'resolved', 'ignored') then
    raise exception 'Invalid operational incident status.'
      using errcode = '22023';
  end if;

  update public.operational_error_events event
  set
    status = v_status,
    acknowledged_at = case
      when v_status = 'acknowledged'
      then coalesce(event.acknowledged_at, now())
      when v_status = 'open'
      then null
      else event.acknowledged_at
    end,
    acknowledged_by = case
      when v_status = 'acknowledged'
      then v_actor
      when v_status = 'open'
      then null
      else event.acknowledged_by
    end,
    resolved_at = case
      when v_status in ('resolved', 'ignored')
      then now()
      when v_status = 'open'
      then null
      else event.resolved_at
    end,
    resolved_by = case
      when v_status in ('resolved', 'ignored')
      then v_actor
      when v_status = 'open'
      then null
      else event.resolved_by
    end,
    resolution_note = case
      when p_note is not null
      then nullif(private.day18_safe_log_text(p_note, 500), '')
      when v_status = 'open'
      then null
      else event.resolution_note
    end,
    updated_at = now()
  where event.id = p_event_id
    and event.hotel_id = p_hotel_id
  returning jsonb_build_object(
    'event_id', event.id,
    'incident_id', event.incident_id,
    'status', event.status,
    'acknowledged_at', event.acknowledged_at,
    'resolved_at', event.resolved_at,
    'resolution_note', event.resolution_note,
    'updated_at', event.updated_at
  )
  into v_result;

  if v_result is null then
    raise exception 'Operational incident was not found.'
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."set_operational_incident_status"("p_hotel_id" "uuid", "p_event_id" "uuid", "p_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_housekeeping_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.housekeeping_tasks%rowtype;
  room_row public.rooms%rowtype;
  previous_status_value text;
  existing_event_id uuid;
begin
  actor_id_value :=
    private.day13_require_housekeeping_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select event_record.id
  into existing_event_id
  from public.housekeeping_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type = 'started';

  if existing_event_id is not null then
    select task.*
    into task_row
    from public.housekeeping_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select task.*
  into task_row
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Housekeeping task was not found.';
  end if;

  if task_row.status not in (
    'pending',
    'assigned',
    'inspection_failed'
  ) then
    raise exception
      'Task cannot start from status %.',
      task_row.status;
  end if;

  if task_row.assigned_staff_id is null then
    raise exception
      'Task must be assigned before work starts.';
  end if;

  select room.*
  into room_row
  from public.rooms room
  where room.hotel_id = target_hotel_id
    and room.id = task_row.room_id
  for update;

  if room_row.status in (
    'maintenance',
    'out_of_order'
  ) then
    raise exception
      'Maintenance/out-of-order room cannot start housekeeping.';
  end if;

  if room_row.status = 'occupied'
     and task_row.task_type not in (
       'stayover_cleaning',
       'turndown'
     )
  then
    raise exception
      'Occupied room requires a stayover/turndown task.';
  end if;

  previous_status_value := task_row.status;

  update public.housekeeping_tasks
  set
    status = 'in_progress',
    started_at = coalesce(started_at, now()),
    started_by = actor_id_value,
    updated_by = actor_id_value,
    inspection_status =
      case
        when inspection_status = 'failed'
          then null
        else inspection_status
      end,
    metadata =
      metadata
      || jsonb_build_object(
        'start_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  if room_row.status = 'available'
     and task_row.task_type in (
       'room_cleaning',
       'deep_cleaning'
     )
  then
    perform set_config(
      'stayqr.day13_request_id',
      request_key || ':room',
      true
    );

    perform set_config(
      'stayqr.day13_event_source',
      'housekeeping',
      true
    );

    perform set_config(
      'stayqr.day13_status_reason',
      'Housekeeping task started',
      true
    );

    update public.rooms
    set
      status = 'cleaning',
      status_changed_at = now(),
      status_changed_by = actor_id_value,
      updated_by = actor_id_value,
      metadata =
        metadata
        || jsonb_build_object(
          'active_housekeeping_task_id',
          target_task_id
        )
    where hotel_id = target_hotel_id
      and id = task_row.room_id;
  end if;

  perform private.day13_insert_housekeeping_event(
    target_hotel_id,
    target_task_id,
    'started',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'room_id', task_row.room_id,
      'assigned_staff_id',
      task_row.assigned_staff_id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row)
  );
end;
$$;


ALTER FUNCTION "public"."start_housekeeping_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.maintenance_tasks%rowtype;
  previous_status_value text;
  existing_event uuid;
begin
  actor_id_value :=
    private.day13_require_maintenance_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select event_record.id
  into existing_event
  from public.maintenance_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type in (
      'started',
      'resumed'
    );

  if existing_event is not null then
    select task.*
    into task_row
    from public.maintenance_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row)
    );
  end if;

  select task.*
  into task_row
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Maintenance task was not found.';
  end if;

  if task_row.assigned_staff_id is null then
    raise exception
      'Maintenance task must be assigned before work starts.';
  end if;

  if task_row.status not in (
    'assigned',
    'on_hold'
  ) then
    raise exception
      'Maintenance task cannot start from status %.',
      task_row.status;
  end if;

  previous_status_value := task_row.status;

  update public.maintenance_tasks
  set
    status = 'in_progress',
    started_at = coalesce(started_at, now()),
    started_by = actor_id_value,
    held_at = null,
    hold_reason = null,
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'start_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  perform private.day13_insert_maintenance_event(
    target_hotel_id,
    target_task_id,
    case
      when previous_status_value = 'on_hold'
        then 'resumed'
      else 'started'
    end,
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    '{}'::jsonb
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row)
  );
end;
$$;


ALTER FUNCTION "public"."start_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_safe_support_access"("target_hotel_id" "uuid", "reason" "text", "duration_minutes" integer DEFAULT 60, "requested_permissions" "text"[] DEFAULT ARRAY['read_only'::"text"]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  session_row public.support_access_sessions%rowtype;
  normalized_permissions text[];
begin
  if target_hotel_id is null
     or nullif(trim(reason), '') is null
  then
    raise exception
      'Hotel and support-access reason are required.';
  end if;

  if duration_minutes is null
     or duration_minutes < 5
     or duration_minutes > 240
  then
    raise exception
      'Support access duration must be between 5 and 240 minutes.';
  end if;

  select array_agg(distinct permission_value order by permission_value)
  into normalized_permissions
  from unnest(
    coalesce(
      requested_permissions,
      array['read_only']::text[]
    )
  ) permission_value
  where permission_value in (
    'read_only',
    'hotel_configuration',
    'subscription_support',
    'ticket_support'
  );

  if coalesce(cardinality(normalized_permissions), 0) = 0 then
    raise exception
      'At least one approved support permission is required.';
  end if;

  update public.support_access_sessions sas
  set
    status = 'expired',
    ended_at = coalesce(sas.ended_at, now()),
    ended_by = actor_user_id,
    metadata = sas.metadata
      || jsonb_build_object(
        'expired_by_start_action', true
      ),
    updated_at = now()
  where sas.hotel_id = target_hotel_id
    and sas.platform_admin_user_id = actor_user_id
    and sas.status = 'active'
    and sas.expires_at <= now();

  insert into public.support_access_sessions (
    hotel_id,
    platform_admin_user_id,
    reason,
    status,
    permissions,
    started_at,
    expires_at,
    metadata,
    created_at,
    updated_at
  ) values (
    target_hotel_id,
    actor_user_id,
    trim(reason),
    'active',
    normalized_permissions,
    now(),
    now() + make_interval(mins => duration_minutes),
    '{}'::jsonb,
    now(),
    now()
  )
  returning * into session_row;

  insert into public.support_access_events (
    session_id,
    hotel_id,
    event_type,
    actor_user_id,
    message,
    details,
    created_at
  ) values (
    session_row.id,
    session_row.hotel_id,
    'support_access_started',
    actor_user_id,
    trim(reason),
    jsonb_build_object(
      'permissions', session_row.permissions,
      'expires_at', session_row.expires_at
    ),
    now()
  );

  return jsonb_build_object(
    'session', to_jsonb(session_row)
  );
exception
  when unique_violation then
    raise exception
      'An active support-access session already exists for this Platform Admin and hotel.';
end;
$$;


ALTER FUNCTION "public"."start_safe_support_access"("target_hotel_id" "uuid", "reason" "text", "duration_minutes" integer, "requested_permissions" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_guest_feedback"("p_hotel_slug" "text", "p_access_token" "text", "p_rating" integer, "p_message" "text", "p_consent_to_follow_up" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_token_id uuid;
  v_token public.guest_access_tokens%rowtype;
  v_feedback public.guest_feedback%rowtype;
  v_message text := nullif(trim(coalesce(p_message, '')), '');
begin
  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'Rating must be between 1 and 5.';
  end if;

  if v_message is not null and char_length(v_message) > 4000 then
    raise exception 'Feedback message exceeds 4000 characters.';
  end if;

  v_token_id := private.resolve_guest_access_token(
    p_hotel_slug,
    p_access_token,
    true
  );

  if v_token_id is null then
    raise exception 'This guest access link is invalid or expired.';
  end if;

  select t.*
  into v_token
  from public.guest_access_tokens t
  where t.id = v_token_id;

  insert into public.guest_feedback (
    hotel_id,
    guest_session_id,
    guest_access_token_id,
    rating,
    message,
    consent_to_follow_up,
    status,
    submitted_at
  )
  values (
    v_token.hotel_id,
    v_token.guest_session_id,
    v_token.id,
    p_rating,
    v_message,
    coalesce(p_consent_to_follow_up, false),
    'new',
    now()
  )
  on conflict (guest_session_id)
  do update set
    guest_access_token_id = excluded.guest_access_token_id,
    rating = excluded.rating,
    message = excluded.message,
    consent_to_follow_up = excluded.consent_to_follow_up,
    status = 'new',
    submitted_at = now(),
    reviewed_at = null,
    reviewed_by = null,
    updated_at = now()
  returning *
  into v_feedback;

  return jsonb_build_object(
    'result', 'FEEDBACK RECEIVED',
    'feedback_id', v_feedback.id,
    'rating', v_feedback.rating,
    'submitted_at', v_feedback.submitted_at
  );
end;
$$;


ALTER FUNCTION "public"."submit_guest_feedback"("p_hotel_slug" "text", "p_access_token" "text", "p_rating" integer, "p_message" "text", "p_consent_to_follow_up" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suspend_hotel_subscription"("target_hotel_id" "uuid", "reason" "text", "action_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  existing_result jsonb;
  subscription_row public.hotel_subscriptions%rowtype;
  old_status_value text;
  result jsonb;
begin
  if target_hotel_id is null
     or nullif(trim(reason), '') is null
  then
    raise exception 'Hotel and suspension reason are required.';
  end if;

  existing_result :=
    private.subscription_action_result_20260728(
      action_idempotency_key
    );

  if existing_result is not null then
    return existing_result
      || jsonb_build_object('idempotent', true);
  end if;

  perform pg_advisory_xact_lock(
    hashtext(
      'stayqr:suspend-subscription:' || target_hotel_id::text
    )
  );

  select hs.*
  into subscription_row
  from public.hotel_subscriptions hs
  where hs.hotel_id = target_hotel_id
    and hs.status in (
      'trial',
      'trialing',
      'active',
      'past_due'
    )
  order by
    coalesce(hs.updated_at, hs.created_at) desc,
    hs.id desc
  limit 1
  for update;

  if not found then
    if exists (
      select 1
      from public.hotel_subscriptions hs
      where hs.hotel_id = target_hotel_id
        and hs.status = 'suspended'
    ) then
      select hs.*
      into subscription_row
      from public.hotel_subscriptions hs
      where hs.hotel_id = target_hotel_id
        and hs.status = 'suspended'
      order by hs.updated_at desc, hs.id desc
      limit 1;

      return jsonb_build_object(
        'hotel_id', target_hotel_id,
        'subscription_id', subscription_row.id,
        'status', subscription_row.status,
        'idempotent', true
      );
    end if;

    raise exception
      'No current subscription can be suspended.';
  end if;

  old_status_value := subscription_row.status;

  perform set_config(
    'stayqr.subscription_event_source',
    'suspend_hotel_subscription',
    true
  );

  update public.hotel_subscriptions hs
  set
    status = 'suspended',
    provider_status = 'suspended',
    suspended_at = now(),
    cancellation_reason = trim(reason),
    metadata = coalesce(hs.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'last_suspension',
        jsonb_build_object(
          'reason', trim(reason),
          'suspended_by', actor_user_id,
          'suspended_at', now()
        )
      ),
    updated_at = now()
  where hs.id = subscription_row.id
  returning * into subscription_row;

  update public.hotels h
  set
    status = 'suspended',
    subscription_status = 'suspended',
    updated_at = now()
  where h.id = target_hotel_id;

  result := jsonb_build_object(
    'hotel_id', target_hotel_id,
    'subscription_id', subscription_row.id,
    'status', subscription_row.status,
    'hotel_status', 'suspended',
    'idempotent', false
  );

  return private.record_subscription_action_20260728(
    target_hotel_id,
    subscription_row.id,
    'hotel_suspended',
    'suspend_hotel_subscription',
    actor_user_id,
    old_status_value,
    subscription_row.status,
    subscription_row.plan_id,
    subscription_row.plan_id,
    subscription_row.provider,
    null,
    action_idempotency_key,
    jsonb_build_object('reason', trim(reason)),
    result
  );
end;
$$;


ALTER FUNCTION "public"."suspend_hotel_subscription"("target_hotel_id" "uuid", "reason" "text", "action_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_room_status"("h" "uuid", "room_id_value" "uuid", "new_status_value" "text", "reason_value" "text", "source_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; row_value public.rooms%rowtype; cm jsonb; req text; allowed boolean; ev public.room_status_events%rowtype;
begin
  actor:=private.day13_require_room_manager(h);
  req:=nullif(trim(request_id_value),'');
  if req is null or length(req)<8 then raise exception 'A request ID of at least eight characters is required.'; end if;
  if new_status_value not in ('available','occupied','cleaning','maintenance','out_of_order') then raise exception 'Invalid room status.'; end if;
  select * into ev from public.room_status_events where hotel_id=h and request_id=req;
  if ev.id is not null then
    select * into row_value from public.rooms where hotel_id=h and id=ev.room_id;
    return jsonb_build_object('ok',true,'idempotent',true,'room',to_jsonb(row_value),'event',to_jsonb(ev));
  end if;
  select * into row_value from public.rooms where hotel_id=h and id=room_id_value for update;
  if not found then raise exception 'Room was not found.'; end if;
  if not row_value.is_active then raise exception 'Archived room status cannot change.'; end if;
  if row_value.status=new_status_value then return jsonb_build_object('ok',true,'idempotent',true,'room',to_jsonb(row_value)); end if;
  allowed:=case row_value.status
    when 'available' then new_status_value in ('occupied','cleaning','maintenance','out_of_order')
    when 'occupied' then new_status_value in ('cleaning','maintenance','out_of_order')
    when 'cleaning' then new_status_value in ('available','maintenance','out_of_order')
    when 'maintenance' then new_status_value in ('available','cleaning','out_of_order')
    when 'out_of_order' then new_status_value in ('available','cleaning','maintenance')
    else false end;
  if not allowed then raise exception 'Room status transition % -> % is not allowed.',row_value.status,new_status_value; end if;
  cm:=private.day13_room_commitments(h,room_id_value);
  if new_status_value='occupied' and ((cm->>'active_stays')::int)=0 then raise exception 'Occupied status requires an active guest stay.'; end if;
  if new_status_value='available' then
    if ((cm->>'active_stays')::int)>0 then raise exception 'Active guest stay prevents available status.'; end if;
    if ((cm->>'active_blocks')::int)>0 then raise exception 'Active room block prevents available status.'; end if;
    if ((cm->>'pending_housekeeping')::int)>0 then raise exception 'Pending housekeeping prevents available status.'; end if;
  end if;
  if new_status_value in ('maintenance','out_of_order') and ((cm->>'active_stays')::int)>0
    then raise exception 'Occupied room cannot enter maintenance/out-of-order through this RPC.'; end if;
  if new_status_value in ('maintenance','out_of_order') and nullif(trim(reason_value),'') is null
    then raise exception 'Maintenance/out-of-order status requires a reason.'; end if;
  perform set_config('stayqr.day13_request_id',req,true);
  perform set_config('stayqr.day13_event_source',case when source_value in ('room_rpc','checkin','checkout','housekeeping','maintenance') then source_value else 'room_rpc' end,true);
  perform set_config('stayqr.day13_status_reason',coalesce(trim(reason_value),''),true);
  update public.rooms set status=new_status_value,status_changed_at=now(),status_changed_by=actor,updated_by=actor,
    metadata=metadata||jsonb_build_object('last_status_reason',nullif(trim(reason_value),''),'last_status_request_id',req)
  where hotel_id=h and id=room_id_value returning * into row_value;
  select * into ev from public.room_status_events where hotel_id=h and request_id=req;
  return jsonb_build_object('ok',true,'idempotent',false,'room',to_jsonb(row_value),'event',to_jsonb(ev));
end;
$$;


ALTER FUNCTION "public"."transition_room_status"("h" "uuid", "room_id_value" "uuid", "new_status_value" "text", "reason_value" "text", "source_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_calendar_room_block"("target_hotel_id" "uuid", "target_room_block_id" "uuid", "block_payload" "jsonb", "expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_block public.room_blocks%rowtype;
  target_room_id uuid;
  target_block_type text;
  target_start_date date;
  target_end_date date;
  target_reason text;
  before_json jsonb;
  after_json jsonb;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  if block_payload is null then
    raise exception 'Room-block payload is required.';
  end if;

  select block.*
  into current_block
  from public.room_blocks block
  where block.id = target_room_block_id
    and block.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Room block not found.';
  end if;

  if current_block.status <> 'active' then
    raise exception 'Only active room blocks may be edited.';
  end if;

  if expected_updated_at is not null
     and current_block.updated_at is distinct from
       expected_updated_at
  then
    raise exception
      'Room block changed after the calendar loaded. Refresh and try again.';
  end if;

  target_room_id := coalesce(
    nullif(block_payload->>'room_id', '')::uuid,
    current_block.room_id
  );
  target_block_type := lower(coalesce(
    nullif(trim(block_payload->>'block_type'), ''),
    current_block.block_type
  ));
  target_start_date := coalesce(
    nullif(block_payload->>'start_date', '')::date,
    current_block.start_date
  );
  target_end_date := coalesce(
    nullif(block_payload->>'end_date', '')::date,
    current_block.end_date
  );
  target_reason := coalesce(
    nullif(trim(block_payload->>'reason'), ''),
    current_block.reason
  );

  if target_end_date <= target_start_date
     or target_end_date - target_start_date > 365
  then
    raise exception
      'Room-block length must be between 1 and 365 days.';
  end if;

  if target_block_type not in (
    'operational',
    'maintenance',
    'out_of_order',
    'owner_use',
    'deep_cleaning',
    'other'
  ) then
    raise exception 'Room-block type is invalid.';
  end if;

  perform 1
  from public.rooms room
  where room.id = target_room_id
    and room.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Room does not belong to this hotel.';
  end if;

  if not private.calendar_room_is_available(
    target_hotel_id,
    target_room_id,
    target_start_date,
    target_end_date,
    null,
    current_block.id
  ) then
    raise exception
      'Room-block update overlaps active inventory.';
  end if;

  before_json := private.build_room_block_json(
    target_hotel_id,
    current_block.id
  );

  update public.room_blocks
  set
    room_id = target_room_id,
    block_type = target_block_type,
    start_date = target_start_date,
    end_date = target_end_date,
    reason = target_reason,
    notes = case
      when block_payload ? 'notes'
        then nullif(trim(block_payload->>'notes'), '')
      else notes
    end,
    updated_by = auth.uid(),
    updated_at = now()
  where id = current_block.id
    and hotel_id = target_hotel_id;

  after_json := private.build_room_block_json(
    target_hotel_id,
    current_block.id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'room_block.updated',
    'room_block',
    current_block.id,
    format(
      'Room block for room %s was updated.',
      after_json->>'room_number'
    ),
    before_json,
    after_json,
    '{}'::jsonb
  );

  return after_json;
end;
$$;


ALTER FUNCTION "public"."update_calendar_room_block"("target_hotel_id" "uuid", "target_room_block_id" "uuid", "block_payload" "jsonb", "expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_food_order_status"("p_hotel_id" "uuid", "p_order_id" "uuid", "p_status" "text", "p_estimated_minutes" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.food_orders%rowtype;
  v_status text := lower(trim(coalesce(p_status, '')));
  v_actor_staff_id uuid;
  v_sync jsonb;
  v_event_key text;
  v_title text;
  v_message text;
begin
  if not private.user_has_permission(p_hotel_id, 'foodorders.manage') then
    raise exception 'Food order management access denied.';
  end if;

  select fo.* into v_order
  from public.food_orders fo
  where fo.hotel_id = p_hotel_id
    and fo.id = p_order_id
  for update;

  if not found then
    raise exception 'Food order was not found in the selected hotel.';
  end if;

  if v_status = v_order.order_status
     and p_estimated_minutes is not distinct from v_order.estimated_minutes
  then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'order_id', v_order.id,
      'order_status', v_order.order_status
    );
  end if;

  if not (
    v_status = v_order.order_status
    or (v_order.order_status = 'pending' and v_status in ('accepted','cancelled'))
    or (v_order.order_status = 'accepted' and v_status in ('preparing','cancelled'))
    or (v_order.order_status = 'preparing' and v_status = 'ready')
    or (v_order.order_status = 'ready' and v_status = 'out_for_delivery')
    or (v_order.order_status = 'out_for_delivery' and v_status = 'delivered')
  ) then
    raise exception 'Invalid food order transition from % to %.',
      v_order.order_status,
      v_status;
  end if;

  if p_estimated_minutes is not null
     and (p_estimated_minutes < 1 or p_estimated_minutes > 1440)
  then
    raise exception 'Estimated minutes must be between 1 and 1440.';
  end if;

  v_actor_staff_id := private.day15_actor_staff_id(p_hotel_id);

  update public.food_orders
  set
    order_status = v_status,
    estimated_minutes = case
      when v_status in ('delivered','cancelled') then null
      else coalesce(p_estimated_minutes, estimated_minutes)
    end,
    estimated_delivery_time = case
      when v_status in ('delivered','cancelled') then null
      when p_estimated_minutes is not null
        then now() + make_interval(mins => p_estimated_minutes)
      else estimated_delivery_time
    end,
    accepted_at = case when v_status = 'accepted' then coalesce(accepted_at, now()) else accepted_at end,
    preparing_at = case when v_status = 'preparing' then coalesce(preparing_at, now()) else preparing_at end,
    ready_at = case when v_status = 'ready' then coalesce(ready_at, now()) else ready_at end,
    out_for_delivery_at = case when v_status = 'out_for_delivery' then coalesce(out_for_delivery_at, now()) else out_for_delivery_at end,
    delivered_at = case when v_status = 'delivered' then coalesce(delivered_at, now()) else delivered_at end,
    cancelled_at = case when v_status = 'cancelled' then coalesce(cancelled_at, now()) else cancelled_at end,
    cancelled_by = case when v_status = 'cancelled' then auth.uid() else cancelled_by end,
    cancellation_reason = case
      when v_status = 'cancelled' then coalesce(nullif(trim(p_note), ''), 'Cancelled by hotel')
      else cancellation_reason
    end
  where id = v_order.id
    and hotel_id = v_order.hotel_id;

  v_event_key := v_status || ':' || coalesce(p_estimated_minutes::text, 'none');

  insert into public.food_order_events (
    hotel_id,
    food_order_id,
    event_type,
    from_status,
    to_status,
    actor_user_id,
    actor_staff_id,
    estimated_minutes,
    message,
    idempotency_key,
    metadata
  ) values (
    v_order.hotel_id,
    v_order.id,
    'status_changed',
    v_order.order_status,
    v_status,
    auth.uid(),
    v_actor_staff_id,
    p_estimated_minutes,
    nullif(trim(p_note), ''),
    v_event_key,
    jsonb_build_object('source', 'day15_staff_rpc')
  )
  on conflict (hotel_id, food_order_id, idempotency_key) do nothing;

  select title, message into v_title, v_message
  from (values
    ('accepted', 'Order accepted', 'The kitchen has accepted your order.'),
    ('preparing', 'Meal being prepared', 'The kitchen has started preparing your order.'),
    ('ready', 'Order ready', 'Your order is ready and will leave the kitchen shortly.'),
    ('out_for_delivery', 'Order on the way', 'Your order is on the way to your room.'),
    ('delivered', 'Order delivered', 'Your order has been delivered. Enjoy your meal.'),
    ('cancelled', 'Order cancelled', 'The hotel cancelled this order. Please contact reception for assistance.')
  ) status_copy(status, title, message)
  where status = v_status;

  perform private.day15_notify_guest(
    v_order.hotel_id,
    v_order.guest_session_id,
    v_order.room_id,
    v_order.guest_id,
    'food_order',
    v_order.id,
    v_status,
    v_title,
    case
      when p_estimated_minutes is not null and v_status not in ('delivered','cancelled')
        then v_message || ' Estimated time: ' || p_estimated_minutes::text || ' minutes.'
      else v_message
    end,
    jsonb_build_object(
      'order_status', v_status,
      'estimated_minutes', p_estimated_minutes
    )
  );

  if v_status = 'delivered' then
    v_sync := private.day11_sync_food_order(v_order.id);

    if coalesce((v_sync ->> 'skipped')::boolean, false) then
      raise exception 'Delivered order could not post to the folio: %.',
        coalesce(v_sync ->> 'reason', 'unknown reason');
    end if;

    update public.food_orders
    set
      folio_item_id = nullif(v_sync ->> 'folio_item_id', '')::uuid,
      folio_posted_at = now()
    where hotel_id = v_order.hotel_id
      and id = v_order.id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'order_id', v_order.id,
    'order_status', v_status,
    'folio', v_sync
  );
end;
$$;


ALTER FUNCTION "public"."update_food_order_status"("p_hotel_id" "uuid", "p_order_id" "uuid", "p_status" "text", "p_estimated_minutes" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_hotel_system_settings"("p_hotel_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_user_id uuid := (select auth.uid());
begin
  if v_user_id is null
     or not private.day17_can_manage_hotel(p_hotel_id)
  then
    raise exception 'Hotel settings management denied.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Hotel settings payload must be a JSON object.';
  end if;

  if p_payload ? 'timezone' then
    perform now() at time zone trim(p_payload ->> 'timezone');

    update public.hotels h
    set
      timezone = trim(p_payload ->> 'timezone'),
      updated_at = now()
    where h.id = p_hotel_id;
  end if;

  if p_payload ? 'currency_code' then
    if upper(trim(p_payload ->> 'currency_code')) !~ '^[A-Z]{3}$' then
      raise exception 'currency_code must contain three letters.';
    end if;

    update public.hotels h
    set
      currency_code = upper(trim(p_payload ->> 'currency_code')),
      updated_at = now()
    where h.id = p_hotel_id;
  end if;

  update public.hotel_settings hs
  set
    legal_name = case
      when p_payload ? 'legal_name'
        then nullif(trim(p_payload ->> 'legal_name'), '')
      else hs.legal_name
    end,
    tax_registration_number = case
      when p_payload ? 'tax_registration_number'
        then nullif(trim(p_payload ->> 'tax_registration_number'), '')
      else hs.tax_registration_number
    end,
    default_tax_percent = case
      when p_payload ? 'default_tax_percent'
        then (p_payload ->> 'default_tax_percent')::numeric
      else hs.default_tax_percent
    end,
    prices_include_tax = case
      when p_payload ? 'prices_include_tax'
        then (p_payload ->> 'prices_include_tax')::boolean
      else hs.prices_include_tax
    end,
    checkin_time = case
      when p_payload ? 'checkin_time'
        then (p_payload ->> 'checkin_time')::time
      else hs.checkin_time
    end,
    checkout_time = case
      when p_payload ? 'checkout_time'
        then (p_payload ->> 'checkout_time')::time
      else hs.checkout_time
    end,
    checkout_grace_minutes = case
      when p_payload ? 'checkout_grace_minutes'
        then (p_payload ->> 'checkout_grace_minutes')::integer
      else hs.checkout_grace_minutes
    end,
    cancellation_policy = case
      when p_payload ? 'cancellation_policy'
        then nullif(trim(p_payload ->> 'cancellation_policy'), '')
      else hs.cancellation_policy
    end,
    house_rules = case
      when p_payload ? 'house_rules'
        then nullif(trim(p_payload ->> 'house_rules'), '')
      else hs.house_rules
    end,
    terms_and_conditions = case
      when p_payload ? 'terms_and_conditions'
        then nullif(trim(p_payload ->> 'terms_and_conditions'), '')
      else hs.terms_and_conditions
    end,
    locale = case
      when p_payload ? 'locale'
        then coalesce(nullif(trim(p_payload ->> 'locale'), ''), hs.locale)
      else hs.locale
    end,
    date_format = case
      when p_payload ? 'date_format'
        then trim(p_payload ->> 'date_format')
      else hs.date_format
    end,
    updated_by = v_user_id,
    updated_at = now()
  where hs.hotel_id = p_hotel_id;

  insert into public.business_day_settings (
    hotel_id,
    business_day_cutoff,
    week_starts_on,
    night_audit_time,
    locale,
    created_by,
    updated_by,
    created_at,
    updated_at
  ) values (
    p_hotel_id,
    coalesce(
      nullif(trim(p_payload ->> 'business_day_cutoff'), '')::time,
      '00:00'::time
    ),
    coalesce((p_payload ->> 'week_starts_on')::integer, 1),
    coalesce(
      nullif(trim(p_payload ->> 'night_audit_time'), '')::time,
      '02:00'::time
    ),
    coalesce(nullif(trim(p_payload ->> 'locale'), ''), 'en-IN'),
    v_user_id,
    v_user_id,
    now(),
    now()
  )
  on conflict (hotel_id) do update
  set
    business_day_cutoff = case
      when p_payload ? 'business_day_cutoff'
        then (p_payload ->> 'business_day_cutoff')::time
      else public.business_day_settings.business_day_cutoff
    end,
    week_starts_on = case
      when p_payload ? 'week_starts_on'
        then (p_payload ->> 'week_starts_on')::integer
      else public.business_day_settings.week_starts_on
    end,
    night_audit_time = case
      when p_payload ? 'night_audit_time'
        then (p_payload ->> 'night_audit_time')::time
      else public.business_day_settings.night_audit_time
    end,
    locale = case
      when p_payload ? 'locale'
        then coalesce(
          nullif(trim(p_payload ->> 'locale'), ''),
          public.business_day_settings.locale
        )
      else public.business_day_settings.locale
    end,
    updated_by = v_user_id,
    updated_at = now();

  insert into public.activity_logs (
    hotel_id,
    actor_user_id,
    actor_role,
    action,
    entity_type,
    entity_id,
    description,
    metadata,
    created_at
  ) values (
    p_hotel_id,
    v_user_id,
    'manager',
    'hotel_system_settings_updated',
    'hotel',
    p_hotel_id,
    'Hotel system settings were updated.',
    jsonb_build_object(
      'changed_keys', (
        select coalesce(
          jsonb_agg(changed_key.key_name order by changed_key.key_name),
          '[]'::jsonb
        )
        from jsonb_object_keys(p_payload)
          as changed_key(key_name)
      ),
      'business_date', private.resolve_hotel_business_date(
        p_hotel_id,
        now()
      )
    ),
    now()
  );

  return public.get_hotel_system_settings(p_hotel_id);
end;
$_$;


ALTER FUNCTION "public"."update_hotel_system_settings"("p_hotel_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_housekeeping_checklist_item"("target_hotel_id" "uuid", "target_task_id" "uuid", "target_item_id" "uuid", "item_status_value" "text", "notes_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.housekeeping_tasks%rowtype;
  item_row public.housekeeping_task_items%rowtype;
  existing_event_id uuid;
begin
  actor_id_value :=
    private.day13_require_housekeeping_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  if item_status_value not in (
    'pending',
    'completed',
    'failed',
    'not_applicable'
  ) then
    raise exception 'Invalid checklist item status.';
  end if;

  select event_record.id
  into existing_event_id
  from public.housekeeping_task_events event_record
  where event_record.hotel_id = target_hotel_id
    and event_record.request_id = request_key
    and event_record.event_type =
        'checklist_updated';

  if existing_event_id is not null then
    select item.*
    into item_row
    from public.housekeeping_task_items item
    where item.hotel_id = target_hotel_id
      and item.id = target_item_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'item', to_jsonb(item_row)
    );
  end if;

  select task.*
  into task_row
  from public.housekeeping_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Housekeeping task was not found.';
  end if;

  if task_row.status not in (
    'assigned',
    'in_progress',
    'inspection_failed'
  ) then
    raise exception
      'Checklist cannot change from task status %.',
      task_row.status;
  end if;

  update public.housekeeping_task_items
  set
    item_status = item_status_value,
    completed_at =
      case
        when item_status_value in (
          'completed',
          'not_applicable'
        ) then now()
        else null
      end,
    completed_by =
      case
        when item_status_value in (
          'completed',
          'not_applicable'
        ) then actor_id_value
        else null
      end,
    notes = nullif(trim(notes_value), ''),
    updated_at = now(),
    metadata =
      metadata
      || jsonb_build_object(
        'last_request_id',
        request_key
      )
  where hotel_id = target_hotel_id
    and task_id = target_task_id
    and id = target_item_id
  returning *
  into item_row;

  if item_row.id is null then
    raise exception
      'Checklist item was not found for this task.';
  end if;

  perform private.day13_insert_housekeeping_event(
    target_hotel_id,
    target_task_id,
    'checklist_updated',
    task_row.status,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'item_id', item_row.id,
      'item_code', item_row.item_code,
      'item_status', item_row.item_status
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'item', to_jsonb(item_row)
  );
end;
$$;


ALTER FUNCTION "public"."update_housekeeping_checklist_item"("target_hotel_id" "uuid", "target_task_id" "uuid", "target_item_id" "uuid", "item_status_value" "text", "notes_value" "text", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_reservation"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "reservation_payload" "jsonb", "expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := auth.uid();
  current_reservation public.reservations%rowtype;
  current_room public.reservation_rooms%rowtype;
  hotel_row public.hotels%rowtype;
  target_guest_id uuid;
  target_room_type_id uuid;
  target_rate_plan_id uuid;
  target_room_id uuid;
  target_arrival_date date;
  target_departure_date date;
  target_adults integer;
  target_children integer;
  target_deposit_required numeric(12,2);
  additional_deposit numeric(12,2);
  target_payment_method text;
  target_booking_source text;
  quote jsonb;
  target_subtotal numeric(12,2);
  target_total numeric(12,2);
  target_average_rate numeric(12,2);
  before_json jsonb;
  after_json jsonb;
  room_status_after_edit text;
begin
  perform private.assert_reservation_write_access(target_hotel_id);

  if reservation_payload is null then
    raise exception 'Reservation payload is required.';
  end if;

  select r.*
  into current_reservation
  from public.reservations r
  where r.id = target_reservation_id
    and r.hotel_id = target_hotel_id
  for update;

  if not found then
    raise exception 'Reservation not found.';
  end if;

  if current_reservation.status not in (
    'draft',
    'tentative',
    'confirmed'
  ) then
    raise exception
      'Only draft, tentative or confirmed reservations may be edited.';
  end if;

  if expected_updated_at is not null
     and current_reservation.updated_at is distinct from
       expected_updated_at
  then
    raise exception
      'Reservation changed after it was opened. Refresh and try again.';
  end if;

  select rr.*
  into current_room
  from public.reservation_rooms rr
  where rr.hotel_id = target_hotel_id
    and rr.reservation_id = target_reservation_id
  order by rr.created_at
  limit 1
  for update;

  if not found then
    raise exception 'Reservation room record not found.';
  end if;

  select h.*
  into hotel_row
  from public.hotels h
  where h.id = target_hotel_id
    and h.status = 'active';

  before_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  target_arrival_date := coalesce(
    nullif(reservation_payload->>'arrival_date', '')::date,
    current_reservation.arrival_date
  );
  target_departure_date := coalesce(
    nullif(reservation_payload->>'departure_date', '')::date,
    current_reservation.departure_date
  );

  if target_departure_date <= target_arrival_date
     or target_departure_date - target_arrival_date > 365
  then
    raise exception
      'Stay length must be between 1 and 365 nights.';
  end if;

  target_adults := coalesce(
    nullif(reservation_payload->>'adults', '')::integer,
    current_reservation.adults
  );
  target_children := coalesce(
    nullif(reservation_payload->>'children', '')::integer,
    current_reservation.children
  );

  target_room_type_id := coalesce(
    nullif(reservation_payload->>'room_type_id', '')::uuid,
    current_room.room_type_id
  );
  target_rate_plan_id := coalesce(
    nullif(reservation_payload->>'rate_plan_id', '')::uuid,
    current_room.rate_plan_id
  );

  if not exists (
    select 1
    from public.rate_plans rp
    where rp.id = target_rate_plan_id
      and rp.hotel_id = target_hotel_id
      and rp.room_type_id = target_room_type_id
      and rp.is_active
  ) then
    raise exception 'Rate plan does not belong to the selected room type.';
  end if;

  quote := public.get_reservation_rate_quote(
    target_hotel_id,
    target_rate_plan_id,
    target_arrival_date,
    target_departure_date,
    target_adults,
    target_children
  );

  target_subtotal := (quote->>'room_subtotal')::numeric(12,2);
  target_total := (quote->>'total_amount')::numeric(12,2);
  target_average_rate :=
    (quote->>'average_nightly_rate')::numeric(12,2);

  if reservation_payload ? 'room_id' then
    target_room_id :=
      nullif(reservation_payload->>'room_id', '')::uuid;
  else
    target_room_id := current_room.room_id;
  end if;

  if target_room_id is null
     and current_reservation.status in ('tentative', 'confirmed')
  then
    select available.room_id
    into target_room_id
    from public.get_reservation_available_rooms(
      target_hotel_id,
      target_arrival_date,
      target_departure_date,
      target_room_type_id,
      target_reservation_id
    ) available
    order by available.room_number
    limit 1;

    if target_room_id is null then
      raise exception
        'No room is available for the selected room type and dates.';
    end if;
  elsif target_room_id is not null then
    if not exists (
      select 1
      from public.get_reservation_available_rooms(
        target_hotel_id,
        target_arrival_date,
        target_departure_date,
        target_room_type_id,
        target_reservation_id
      ) available
      where available.room_id = target_room_id
    ) then
      raise exception
        'Selected room is not available for these dates.';
    end if;
  end if;

  if reservation_payload ? 'guest' then
    target_guest_id := private.resolve_reservation_guest(
      target_hotel_id,
      reservation_payload->'guest'
    );
  else
    target_guest_id := current_reservation.primary_guest_id;
  end if;

  target_booking_source := lower(coalesce(
    nullif(trim(reservation_payload->>'booking_source'), ''),
    current_reservation.booking_source
  ));

  if target_booking_source not in (
    'walk_in',
    'phone',
    'website',
    'ota_manual',
    'travel_agent',
    'corporate',
    'repeat_guest',
    'other'
  ) then
    raise exception 'Unsupported booking source.';
  end if;

  additional_deposit := coalesce(
    nullif(
      reservation_payload->>'additional_deposit_amount',
      ''
    )::numeric,
    0
  )::numeric(12,2);

  target_deposit_required := coalesce(
    nullif(
      reservation_payload->>'deposit_required',
      ''
    )::numeric,
    current_reservation.deposit_required
  )::numeric(12,2);

  target_deposit_required := greatest(
    target_deposit_required,
    current_reservation.deposit_collected + additional_deposit
  );

  if additional_deposit < 0
     or target_deposit_required < 0
     or target_deposit_required > target_total
     or current_reservation.deposit_collected +
       additional_deposit > target_total
  then
    raise exception
      'Deposit values must be between zero and the reservation total.';
  end if;

  target_payment_method := lower(coalesce(
    nullif(trim(reservation_payload->>'payment_method'), ''),
    'cash'
  ));

  -- Release the old allocation first to avoid a transient overlap while dates
  -- and physical room assignment are changed in the same transaction.
  update public.reservation_rooms
  set status = 'released'
  where id = current_room.id
    and hotel_id = target_hotel_id;

  update public.reservations
  set
    primary_guest_id = target_guest_id,
    booking_source = target_booking_source,
    source_reference = case
      when reservation_payload ? 'source_reference'
        then nullif(trim(reservation_payload->>'source_reference'), '')
      else source_reference
    end,
    arrival_date = target_arrival_date,
    departure_date = target_departure_date,
    expected_checkin_time = case
      when reservation_payload ? 'expected_checkin_time'
        then nullif(
          reservation_payload->>'expected_checkin_time',
          ''
        )::time
      else expected_checkin_time
    end,
    expected_checkout_time = case
      when reservation_payload ? 'expected_checkout_time'
        then nullif(
          reservation_payload->>'expected_checkout_time',
          ''
        )::time
      else expected_checkout_time
    end,
    adults = target_adults,
    children = target_children,
    currency_code = hotel_row.currency_code,
    room_subtotal = target_subtotal,
    tax_amount = 0,
    discount_amount = 0,
    total_amount = target_total,
    deposit_required = target_deposit_required,
    special_requests = case
      when reservation_payload ? 'special_requests'
        then nullif(trim(reservation_payload->>'special_requests'), '')
      else special_requests
    end,
    internal_notes = case
      when reservation_payload ? 'internal_notes'
        then nullif(trim(reservation_payload->>'internal_notes'), '')
      else internal_notes
    end,
    updated_by = actor_user_id,
    updated_at = now()
  where id = target_reservation_id
    and hotel_id = target_hotel_id;

  room_status_after_edit := case
    when current_reservation.status = 'confirmed' then 'confirmed'
    else 'held'
  end;

  update public.reservation_rooms
  set
    room_type_id = target_room_type_id,
    room_id = target_room_id,
    rate_plan_id = target_rate_plan_id,
    status = room_status_after_edit,
    adults = target_adults,
    children = target_children,
    nightly_rate = target_average_rate,
    room_subtotal = target_subtotal,
    tax_amount = 0,
    discount_amount = 0,
    total_amount = target_total,
    notes = case
      when reservation_payload ? 'room_notes'
        then nullif(trim(reservation_payload->>'room_notes'), '')
      else notes
    end,
    updated_at = now()
  where id = current_room.id
    and hotel_id = target_hotel_id;

  if target_guest_id is distinct from
     current_reservation.primary_guest_id
  then
    delete from public.reservation_guests
    where hotel_id = target_hotel_id
      and reservation_id = target_reservation_id
      and is_primary;

    insert into public.reservation_guests (
      hotel_id,
      reservation_id,
      guest_id,
      is_primary
    )
    values (
      target_hotel_id,
      target_reservation_id,
      target_guest_id,
      true
    )
    on conflict (reservation_id, guest_id)
    do update set is_primary = true;
  end if;

  if additional_deposit > 0 then
    insert into public.reservation_payments (
      hotel_id,
      reservation_id,
      amount,
      payment_method,
      payment_status,
      transaction_reference,
      notes,
      collected_by
    )
    values (
      target_hotel_id,
      target_reservation_id,
      additional_deposit,
      target_payment_method,
      'collected',
      nullif(
        trim(reservation_payload->>'payment_reference'),
        ''
      ),
      nullif(trim(reservation_payload->>'payment_notes'), ''),
      actor_user_id
    );
  end if;

  after_json := private.build_reservation_json(
    target_hotel_id,
    target_reservation_id
  );

  perform private.write_activity_log(
    target_hotel_id,
    'reservation.updated',
    'reservation',
    target_reservation_id,
    format(
      'Reservation %s was modified.',
      current_reservation.reservation_number
    ),
    before_json,
    after_json,
    jsonb_build_object(
      'additional_deposit', additional_deposit
    )
  );

  return after_json;
end;
$$;


ALTER FUNCTION "public"."update_reservation"("target_hotel_id" "uuid", "target_reservation_id" "uuid", "reservation_payload" "jsonb", "expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_service_request_priority"("p_hotel_id" "uuid", "p_request_id" "uuid", "p_priority" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.service_requests%rowtype;
  v_priority text := lower(trim(coalesce(p_priority, '')));
begin
  if not private.user_has_permission(p_hotel_id, 'services.manage') then
    raise exception 'Service request priority access denied.';
  end if;

  if v_priority not in ('low','normal','high','urgent') then
    raise exception 'Invalid service request priority.';
  end if;

  select sr.* into v_request
  from public.service_requests sr
  where sr.hotel_id = p_hotel_id
    and sr.id = p_request_id
  for update;

  if not found then
    raise exception 'Service request was not found in the selected hotel.';
  end if;

  if v_request.priority = v_priority then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'request_id', v_request.id,
      'priority', v_priority
    );
  end if;

  update public.service_requests
  set priority = v_priority
  where hotel_id = p_hotel_id
    and id = p_request_id;

  insert into public.service_request_events (
    hotel_id,
    service_request_id,
    event_type,
    actor_user_id,
    actor_staff_id,
    message,
    idempotency_key,
    metadata
  ) values (
    p_hotel_id,
    p_request_id,
    'priority_changed',
    auth.uid(),
    private.day15_actor_staff_id(p_hotel_id),
    'Priority changed from ' || v_request.priority || ' to ' || v_priority,
    'priority:' || v_priority,
    jsonb_build_object(
      'previous_priority', v_request.priority,
      'priority', v_priority
    )
  )
  on conflict (hotel_id, service_request_id, idempotency_key) do nothing;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'request_id', v_request.id,
    'priority', v_priority
  );
end;
$$;


ALTER FUNCTION "public"."update_service_request_priority"("p_hotel_id" "uuid", "p_request_id" "uuid", "p_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_service_request_status"("p_hotel_id" "uuid", "p_request_id" "uuid", "p_status" "text", "p_estimated_minutes" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.service_requests%rowtype;
  v_status text := lower(trim(coalesce(p_status, '')));
  v_actor_staff_id uuid;
  v_charge jsonb;
  v_event_key text;
  v_title text;
  v_message text;
begin
  if not private.user_has_permission(p_hotel_id, 'services.manage') then
    raise exception 'Service request management access denied.';
  end if;

  select sr.* into v_request
  from public.service_requests sr
  where sr.hotel_id = p_hotel_id
    and sr.id = p_request_id
  for update;

  if not found then
    raise exception 'Service request was not found in the selected hotel.';
  end if;

  if v_status = v_request.status
     and p_estimated_minutes is not distinct from v_request.estimated_minutes
  then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'request_id', v_request.id,
      'status', v_request.status
    );
  end if;

  if not (
    v_status = v_request.status
    or (v_request.status = 'pending' and v_status in ('accepted','cancelled','escalated'))
    or (v_request.status = 'accepted' and v_status in ('in_progress','cancelled','escalated'))
    or (v_request.status = 'in_progress' and v_status in ('completed','cancelled','escalated'))
    or (v_request.status = 'escalated' and v_status in ('accepted','in_progress','completed','cancelled'))
  ) then
    raise exception 'Invalid service request transition from % to %.',
      v_request.status,
      v_status;
  end if;

  if p_estimated_minutes is not null
     and (p_estimated_minutes < 1 or p_estimated_minutes > 1440)
  then
    raise exception 'Estimated minutes must be between 1 and 1440.';
  end if;

  v_actor_staff_id := private.day15_actor_staff_id(p_hotel_id);

  update public.service_requests
  set
    status = v_status,
    assigned_staff_id = case
      when v_status = 'accepted' and assigned_staff_id is null
        then v_actor_staff_id
      else assigned_staff_id
    end,
    estimated_minutes = coalesce(p_estimated_minutes, estimated_minutes),
    estimated_arrival_time = case
      when p_estimated_minutes is not null
        then now() + make_interval(mins => p_estimated_minutes)
      else estimated_arrival_time
    end,
    accepted_at = case when v_status = 'accepted' then coalesce(accepted_at, now()) else accepted_at end,
    started_at = case when v_status = 'in_progress' then coalesce(started_at, now()) else started_at end,
    completed_at = case when v_status = 'completed' then coalesce(completed_at, now()) else completed_at end,
    cancelled_at = case when v_status = 'cancelled' then coalesce(cancelled_at, now()) else cancelled_at end,
    cancellation_reason = case
      when v_status = 'cancelled' then coalesce(nullif(trim(p_note), ''), 'Cancelled by hotel')
      else cancellation_reason
    end,
    escalated_at = case when v_status = 'escalated' then coalesce(escalated_at, now()) else escalated_at end,
    escalation_level = case when v_status = 'escalated' then greatest(escalation_level, 1) else escalation_level end
  where hotel_id = v_request.hotel_id
    and id = v_request.id;

  v_event_key := v_status || ':' || coalesce(p_estimated_minutes::text, 'none');

  insert into public.service_request_events (
    hotel_id,
    service_request_id,
    event_type,
    from_status,
    to_status,
    actor_user_id,
    actor_staff_id,
    assigned_staff_id,
    message,
    idempotency_key,
    metadata
  ) values (
    v_request.hotel_id,
    v_request.id,
    'status_changed',
    v_request.status,
    v_status,
    auth.uid(),
    v_actor_staff_id,
    coalesce(v_request.assigned_staff_id, v_actor_staff_id),
    nullif(trim(p_note), ''),
    v_event_key,
    jsonb_build_object('estimated_minutes', p_estimated_minutes)
  )
  on conflict (hotel_id, service_request_id, idempotency_key) do nothing;

  select title, message into v_title, v_message
  from (values
    ('accepted', 'Request accepted', 'Hotel staff has accepted your request.'),
    ('in_progress', 'Staff on the way', 'Your request is now in progress.'),
    ('completed', 'Request completed', 'Your request has been completed.'),
    ('cancelled', 'Request cancelled', 'The hotel cancelled this request. Please contact reception if you need help.'),
    ('escalated', 'Request escalated', 'Your request has been escalated for faster attention.')
  ) status_copy(status, title, message)
  where status = v_status;

  perform private.day15_notify_guest(
    v_request.hotel_id,
    v_request.guest_session_id,
    v_request.room_id,
    v_request.guest_id,
    'service_request',
    v_request.id,
    v_status,
    v_title,
    case
      when p_estimated_minutes is not null and v_status in ('accepted','in_progress')
        then v_message || ' Estimated time: ' || p_estimated_minutes::text || ' minutes.'
      else v_message
    end,
    jsonb_build_object(
      'status', v_status,
      'estimated_minutes', p_estimated_minutes,
      'department', v_request.department
    )
  );

  if v_status = 'completed' then
    v_charge := private.day11_post_service_request_charge(
      v_request.id,
      false,
      'day15-completion:' || v_request.id::text
    );

    if coalesce((v_charge ->> 'ok')::boolean, false)
       and not coalesce((v_charge ->> 'skipped')::boolean, false)
    then
      update public.service_requests
      set
        folio_item_id = nullif(v_charge ->> 'folio_item_id', '')::uuid,
        folio_posted_at = now()
      where hotel_id = v_request.hotel_id
        and id = v_request.id;
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'request_id', v_request.id,
    'status', v_status,
    'folio', v_charge
  );
end;
$$;


ALTER FUNCTION "public"."update_service_request_status"("p_hotel_id" "uuid", "p_request_id" "uuid", "p_status" "text", "p_estimated_minutes" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_support_ticket_status"("target_ticket_id" "uuid", "new_status" "text", "message" "text" DEFAULT NULL::"text", "assign_to_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    private.require_platform_admin_20260728();
  ticket_row public.support_tickets%rowtype;
  old_status_value text;
begin
  if new_status not in (
    'open',
    'in_progress',
    'waiting_on_hotel',
    'resolved',
    'closed'
  ) then
    raise exception
      'Unsupported support ticket status.';
  end if;

  select st.*
  into ticket_row
  from public.support_tickets st
  where st.id = target_ticket_id
  for update;

  if not found then
    raise exception 'Support ticket was not found.';
  end if;

  old_status_value := ticket_row.status;

  update public.support_tickets st
  set
    status = new_status,
    assigned_to = coalesce(
      assign_to_user_id,
      st.assigned_to
    ),
    resolved_by = case
      when new_status in ('resolved', 'closed')
        then actor_user_id
      else st.resolved_by
    end,
    resolved_at = case
      when new_status in ('resolved', 'closed')
        then coalesce(st.resolved_at, now())
      else null
    end,
    closed_at = case
      when new_status = 'closed'
        then coalesce(st.closed_at, now())
      else null
    end,
    last_response_at = now(),
    updated_at = now()
  where st.id = target_ticket_id
  returning * into ticket_row;

  insert into public.support_ticket_events (
    ticket_id,
    hotel_id,
    event_type,
    actor_user_id,
    message,
    old_status,
    new_status,
    details,
    created_at
  ) values (
    ticket_row.id,
    ticket_row.hotel_id,
    'status_changed',
    actor_user_id,
    nullif(trim(message), ''),
    old_status_value,
    ticket_row.status,
    jsonb_build_object(
      'assigned_to', ticket_row.assigned_to
    ),
    now()
  );

  return jsonb_build_object(
    'ticket', to_jsonb(ticket_row)
  );
end;
$$;


ALTER FUNCTION "public"."update_support_ticket_status"("target_ticket_id" "uuid", "new_status" "text", "message" "text", "assign_to_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_email_adapter_config"("p_hotel_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_row public.email_adapter_configs%rowtype;
  v_adapter_key text;
  v_provider text;
  v_metadata jsonb;
begin
  if v_user_id is null
     or not private.day17_can_manage_hotel(p_hotel_id)
  then
    raise exception 'Email adapter management denied.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Email adapter payload must be a JSON object.';
  end if;

  v_adapter_key := nullif(trim(p_payload ->> 'adapter_key'), '');
  v_provider := coalesce(
    nullif(trim(p_payload ->> 'provider'), ''),
    'edge_function'
  );
  v_metadata := coalesce(p_payload -> 'metadata', '{}'::jsonb);

  if v_adapter_key is null
     or length(v_adapter_key) not between 2 and 100
  then
    raise exception 'adapter_key must contain 2 to 100 characters.';
  end if;

  if v_provider not in ('edge_function', 'external_worker', 'manual') then
    raise exception 'Unsupported email adapter provider.';
  end if;

  if jsonb_typeof(v_metadata) <> 'object' then
    raise exception 'Email adapter metadata must be a JSON object.';
  end if;

  insert into public.email_adapter_configs (
    hotel_id,
    adapter_key,
    provider,
    from_name,
    from_email,
    reply_to_email,
    secret_reference,
    endpoint_name,
    is_enabled,
    metadata,
    created_by,
    updated_by,
    created_at,
    updated_at
  ) values (
    p_hotel_id,
    v_adapter_key,
    v_provider,
    nullif(trim(p_payload ->> 'from_name'), ''),
    nullif(trim(p_payload ->> 'from_email'), ''),
    nullif(trim(p_payload ->> 'reply_to_email'), ''),
    null,
    nullif(trim(p_payload ->> 'endpoint_name'), ''),
    coalesce((p_payload ->> 'is_enabled')::boolean, false),
    v_metadata,
    v_user_id,
    v_user_id,
    now(),
    now()
  )
  on conflict (hotel_id, adapter_key)
  where hotel_id is not null
  do update
  set
    provider = excluded.provider,
    from_name = excluded.from_name,
    from_email = excluded.from_email,
    reply_to_email = excluded.reply_to_email,
    endpoint_name = excluded.endpoint_name,
    is_enabled = excluded.is_enabled,
    metadata = excluded.metadata,
    updated_by = v_user_id,
    updated_at = now()
  returning * into v_row;

  return jsonb_build_object(
    'saved', true,
    'adapter', to_jsonb(v_row) - 'secret_reference'
  );
end;
$$;


ALTER FUNCTION "public"."upsert_email_adapter_config"("p_hotel_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_floor"("h" "uuid", "floor_id_value" "uuid", "code_value" "text", "name_value" "text", "floor_number_value" integer, "description_value" "text", "sort_order_value" integer, "active_value" boolean, "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; row_value public.floors%rowtype; req text;
begin
  actor:=private.day13_require_room_manager(h);
  req:=nullif(trim(request_id_value),'');
  if req is null or length(req)<8 then raise exception 'A request ID of at least eight characters is required.'; end if;
  if coalesce(active_value,true)=false then raise exception 'Use archive_floor to deactivate a floor.'; end if;
  if nullif(trim(code_value),'') is null or nullif(trim(name_value),'') is null then raise exception 'Floor code and name are required.'; end if;
  if floor_id_value is null then
    insert into public.floors(hotel_id,name,code,floor_number,description,sort_order,is_active,created_by,updated_by,metadata)
    values(h,trim(name_value),upper(trim(code_value)),floor_number_value,nullif(trim(description_value),''),coalesce(sort_order_value,0),coalesce(active_value,true),actor,actor,jsonb_build_object('request_id',req))
    returning * into row_value;
  else
    update public.floors set
      name=trim(name_value),code=upper(trim(code_value)),floor_number=floor_number_value,
      description=nullif(trim(description_value),''),sort_order=coalesce(sort_order_value,sort_order),
      is_active=coalesce(active_value,is_active),
      archived_at=case when coalesce(active_value,is_active) then null else archived_at end,
      archived_by=case when coalesce(active_value,is_active) then null else archived_by end,
      archive_reason=case when coalesce(active_value,is_active) then null else archive_reason end,
      updated_by=actor,metadata=metadata||jsonb_build_object('request_id',req)
    where hotel_id=h and id=floor_id_value returning * into row_value;
    if row_value.id is null then raise exception 'Floor was not found.'; end if;
  end if;
  return jsonb_build_object('ok',true,'floor',to_jsonb(row_value));
end;
$$;


ALTER FUNCTION "public"."upsert_floor"("h" "uuid", "floor_id_value" "uuid", "code_value" "text", "name_value" "text", "floor_number_value" integer, "description_value" "text", "sort_order_value" integer, "active_value" boolean, "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_guest_guide_greeting"("p_hotel_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.guest_guide_greetings%rowtype;
begin
  if not private.user_has_permission(
    p_hotel_id,
    'hotel.manage'
  ) then
    raise exception 'Guest guide greeting update denied.';
  end if;

  insert into public.guest_guide_greetings (
    hotel_id,
    locale,
    language_name,
    native_name,
    neutral_greeting,
    morning_greeting,
    afternoon_greeting,
    evening_greeting,
    night_greeting,
    is_enabled,
    sort_order,
    updated_by
  )
  values (
    p_hotel_id,
    nullif(trim(p_payload ->> 'locale'), ''),
    nullif(trim(p_payload ->> 'language_name'), ''),
    nullif(trim(p_payload ->> 'native_name'), ''),
    nullif(trim(p_payload ->> 'neutral_greeting'), ''),
    nullif(trim(p_payload ->> 'morning_greeting'), ''),
    nullif(trim(p_payload ->> 'afternoon_greeting'), ''),
    nullif(trim(p_payload ->> 'evening_greeting'), ''),
    nullif(trim(p_payload ->> 'night_greeting'), ''),
    coalesce((p_payload ->> 'is_enabled')::boolean, false),
    coalesce((p_payload ->> 'sort_order')::integer, 0),
    auth.uid()
  )
  on conflict (hotel_id, locale)
  do update set
    language_name = excluded.language_name,
    native_name = excluded.native_name,
    neutral_greeting = excluded.neutral_greeting,
    morning_greeting = excluded.morning_greeting,
    afternoon_greeting = excluded.afternoon_greeting,
    evening_greeting = excluded.evening_greeting,
    night_greeting = excluded.night_greeting,
    is_enabled = excluded.is_enabled,
    sort_order = excluded.sort_order,
    updated_by = auth.uid(),
    updated_at = now()
  returning *
  into v_row;

  perform private.day14_mark_guide_draft(p_hotel_id);

  return jsonb_build_object(
    'result', 'GUEST GUIDE GREETING SAVED',
    'locale', v_row.locale,
    'is_enabled', v_row.is_enabled
  );
end;
$$;


ALTER FUNCTION "public"."upsert_guest_guide_greeting"("p_hotel_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_guest_guide_item"("p_hotel_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item public.guest_guide_items%rowtype;
  v_translation record;
  v_section_id uuid;
  v_scope_type text;
  v_room_type_id uuid;
  v_room_id uuid;
  v_item_key text;
begin
  if not private.user_has_permission(
    p_hotel_id,
    'hotel.manage'
  ) then
    raise exception 'Guest guide item update denied.';
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Item payload must be a JSON object.';
  end if;

  v_section_id := (p_payload ->> 'section_id')::uuid;
  v_scope_type :=
    coalesce(
      nullif(trim(p_payload ->> 'scope_type'), ''),
      'hotel'
    );
  v_room_type_id :=
    nullif(p_payload ->> 'room_type_id', '')::uuid;
  v_room_id :=
    nullif(p_payload ->> 'room_id', '')::uuid;
  v_item_key :=
    nullif(trim(p_payload ->> 'item_key'), '');

  if v_section_id is null or v_item_key is null then
    raise exception 'section_id and item_key are required.';
  end if;

  if not exists (
    select 1
    from public.guest_guide_sections s
    where s.hotel_id = p_hotel_id
      and s.id = v_section_id
  ) then
    raise exception 'Section does not belong to the hotel.';
  end if;

  insert into public.guest_guide_items (
    hotel_id,
    section_id,
    scope_type,
    room_type_id,
    room_id,
    item_key,
    item_type,
    icon,
    action_type,
    action_value,
    sort_order,
    is_enabled,
    metadata,
    created_by,
    updated_by
  )
  values (
    p_hotel_id,
    v_section_id,
    v_scope_type,
    v_room_type_id,
    v_room_id,
    v_item_key,
    coalesce(
      nullif(trim(p_payload ->> 'item_type'), ''),
      'custom'
    ),
    nullif(trim(p_payload ->> 'icon'), ''),
    coalesce(
      nullif(trim(p_payload ->> 'action_type'), ''),
      'none'
    ),
    nullif(trim(p_payload ->> 'action_value'), ''),
    coalesce((p_payload ->> 'sort_order')::integer, 0),
    coalesce((p_payload ->> 'is_enabled')::boolean, true),
    coalesce(p_payload -> 'metadata', '{}'::jsonb),
    auth.uid(),
    auth.uid()
  )
  on conflict (
    hotel_id,
    section_id,
    scope_type,
    (
      coalesce(
        room_type_id,
        '00000000-0000-0000-0000-000000000000'::uuid
      )
    ),
    (
      coalesce(
        room_id,
        '00000000-0000-0000-0000-000000000000'::uuid
      )
    ),
    item_key
  )
  do update set
    item_type = excluded.item_type,
    icon = excluded.icon,
    action_type = excluded.action_type,
    action_value = excluded.action_value,
    sort_order = excluded.sort_order,
    is_enabled = excluded.is_enabled,
    metadata = excluded.metadata,
    updated_by = auth.uid(),
    updated_at = now()
  returning *
  into v_item;

  for v_translation in
    select key as locale, value as payload
    from jsonb_each(
      coalesce(
        p_payload -> 'translations',
        '{}'::jsonb
      )
    )
  loop
    insert into public.guest_guide_item_translations (
      hotel_id,
      item_id,
      locale,
      title,
      subtitle,
      description,
      instructions,
      disclaimer,
      button_label,
      metadata
    )
    values (
      p_hotel_id,
      v_item.id,
      v_translation.locale,
      nullif(
        trim(v_translation.payload ->> 'title'),
        ''
      ),
      nullif(
        trim(v_translation.payload ->> 'subtitle'),
        ''
      ),
      nullif(
        trim(v_translation.payload ->> 'description'),
        ''
      ),
      coalesce(
        v_translation.payload -> 'instructions',
        '[]'::jsonb
      ),
      nullif(
        trim(v_translation.payload ->> 'disclaimer'),
        ''
      ),
      nullif(
        trim(v_translation.payload ->> 'button_label'),
        ''
      ),
      coalesce(
        v_translation.payload -> 'metadata',
        '{}'::jsonb
      )
    )
    on conflict (item_id, locale)
    do update set
      title = excluded.title,
      subtitle = excluded.subtitle,
      description = excluded.description,
      instructions = excluded.instructions,
      disclaimer = excluded.disclaimer,
      button_label = excluded.button_label,
      metadata = excluded.metadata,
      updated_at = now();
  end loop;

  perform private.day14_mark_guide_draft(p_hotel_id);

  return jsonb_build_object(
    'result', 'GUEST GUIDE ITEM SAVED',
    'item_id', v_item.id,
    'item_key', v_item.item_key
  );
end;
$$;


