    updated_at = now()
  returning *
  into v_section;

  for v_translation in
    select key as locale, value as payload
    from jsonb_each(
      coalesce(
        p_payload -> 'translations',
        '{}'::jsonb
      )
    )
  loop
    insert into public.guest_guide_section_translations (
      hotel_id,
      section_id,
