CREATE OR REPLACE FUNCTION "public"."upsert_guest_guide_settings"("p_hotel_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_default_locale text;
  v_enabled_locales text[];
  v_row public.guest_guide_settings%rowtype;
begin
  if not private.user_has_permission(
    p_hotel_id,
    'hotel.manage'
  ) then
    raise exception 'Guest guide settings update denied.';
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Settings payload must be a JSON object.';
  end if;

  v_default_locale :=
    coalesce(
      nullif(trim(p_payload ->> 'default_locale'), ''),
      'en'
    );

  select coalesce(
    array_agg(value order by ordinal),
    array['en']::text[]
  )
  into v_enabled_locales
  from jsonb_array_elements_text(
    coalesce(
      p_payload -> 'enabled_locales',
      '["en"]'::jsonb
    )
  ) with ordinality as x(value, ordinal);

  if not (
    v_enabled_locales <@ array[
      'en','hi','mr','ta','te','bn',
      'gu','kn','ml','pa','or','as'
    ]::text[]
  ) then
    raise exception 'Unsupported locale in enabled_locales.';
  end if;

  if not (v_default_locale = any(v_enabled_locales)) then
    raise exception 'Default locale must be enabled.';
  end if;

  insert into public.guest_guide_settings (
    hotel_id,
    template_key,
    default_locale,
    enabled_locales,
    publish_status,
    theme,
    branding,
    navigation,
    updated_by
  )
  values (
    p_hotel_id,
    coalesce(
      nullif(trim(p_payload ->> 'template_key'), ''),
      'stayqr_luxury'
    ),
    v_default_locale,
    v_enabled_locales,
    'draft',
    coalesce(p_payload -> 'theme', '{}'::jsonb),
    coalesce(p_payload -> 'branding', '{}'::jsonb),
    coalesce(p_payload -> 'navigation', '{}'::jsonb),
    auth.uid()
  )
  on conflict (hotel_id)
  do update set
    template_key = excluded.template_key,
    default_locale = excluded.default_locale,
    enabled_locales = excluded.enabled_locales,
    publish_status = 'draft',
    theme = excluded.theme,
    branding = excluded.branding,
    navigation = excluded.navigation,
    draft_revision =
      public.guest_guide_settings.draft_revision + 1,
    updated_by = auth.uid(),
    updated_at = now()
  returning *
  into v_row;

  update public.guest_guide_greetings g
  set
    is_enabled = g.locale = any(v_enabled_locales),
    updated_by = auth.uid(),
    updated_at = now()
  where g.hotel_id = p_hotel_id;

  return jsonb_build_object(
    'result', 'GUEST GUIDE SETTINGS SAVED',
    'hotel_id', v_row.hotel_id,
    'publish_status', v_row.publish_status,
    'draft_revision', v_row.draft_revision,
    'enabled_locales', to_jsonb(v_row.enabled_locales)
  );
end;
$$;


ALTER FUNCTION "public"."upsert_guest_guide_settings"("p_hotel_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_hotel_guest_content"("p_hotel_id" "uuid", "p_locale" "text", "p_content" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_locale text := coalesce(nullif(trim(p_locale), ''), 'en');
  v_row public.hotel_guest_content%rowtype;
begin
  if not private.user_has_permission(p_hotel_id, 'hotel.manage') then
    raise exception 'Guest content update denied.';
  end if;

  if not exists (
    select 1 from public.hotels h where h.id = p_hotel_id
  ) then
    raise exception 'Hotel was not found.';
  end if;

  if v_locale !~ '^[a-z]{2}(-[A-Z]{2})?$' then
    raise exception 'Invalid locale.';
  end if;

  if p_content is null or jsonb_typeof(p_content) <> 'object' then
    raise exception 'Guest content must be a JSON object.';
  end if;

  if pg_column_size(p_content) > 65536 then
    raise exception 'Guest content exceeds the 64 KB limit.';
  end if;

  insert into public.hotel_guest_content (
    hotel_id,
    locale,
    content,
    is_active,
    updated_by
  )
  values (
    p_hotel_id,
    v_locale,
    p_content,
    true,
    auth.uid()
  )
  on conflict (hotel_id, locale)
  do update set
    content = excluded.content,
    is_active = true,
    updated_by = auth.uid(),
    updated_at = now()
  returning *
  into v_row;

  return jsonb_build_object(
    'result', 'GUEST CONTENT SAVED',
    'hotel_id', v_row.hotel_id,
    'locale', v_row.locale,
    'content', v_row.content,
    'updated_at', v_row.updated_at
  );
end;
$_$;


ALTER FUNCTION "public"."upsert_hotel_guest_content"("p_hotel_id" "uuid", "p_locale" "text", "p_content" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_manual_whatsapp_template"("p_hotel_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_row public.whatsapp_templates%rowtype;
  v_event_key text;
  v_locale text;
  v_template_name text;
  v_body_template text;
  v_status text;
begin
  if v_user_id is null
     or not private.day17_can_manage_hotel(p_hotel_id)
  then
    raise exception 'Manual WhatsApp template management denied.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'WhatsApp template payload must be a JSON object.';
  end if;

  v_event_key := nullif(trim(p_payload ->> 'event_key'), '');
  v_locale := coalesce(
    nullif(trim(p_payload ->> 'locale'), ''),
    'en'
  );
  v_template_name := nullif(trim(p_payload ->> 'template_name'), '');
  v_body_template := nullif(trim(p_payload ->> 'body_template'), '');
  v_status := coalesce(
    nullif(trim(p_payload ->> 'status'), ''),
    'draft'
  );

  if not exists (
    select 1
    from public.notification_event_catalog nec
    where nec.event_key = v_event_key
      and nec.is_active
  ) then
    raise exception 'Unsupported notification event key.';
  end if;

  if length(v_locale) not between 2 and 20 then
    raise exception 'locale must contain 2 to 20 characters.';
  end if;

  if v_template_name is null then
    raise exception 'template_name is required.';
  end if;

  if v_body_template is null then
    raise exception 'body_template is required.';
  end if;

  if v_status not in ('draft', 'published', 'archived') then
    raise exception 'Unsupported WhatsApp template status.';
  end if;

  insert into public.whatsapp_templates (
    hotel_id,
    event_key,
    locale,
    template_name,
    body_template,
    status,
    created_by,
    updated_by,
    created_at,
    updated_at
  ) values (
    p_hotel_id,
    v_event_key,
    v_locale,
    v_template_name,
    v_body_template,
    v_status,
    v_user_id,
    v_user_id,
    now(),
    now()
  )
  on conflict (hotel_id, event_key, locale)
  where hotel_id is not null
  do update
  set
    template_name = excluded.template_name,
    body_template = excluded.body_template,
    status = excluded.status,
    updated_by = v_user_id,
    updated_at = now()
  returning * into v_row;

  return jsonb_build_object(
    'saved', true,
    'template', to_jsonb(v_row)
  );
end;
$$;


ALTER FUNCTION "public"."upsert_manual_whatsapp_template"("p_hotel_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_notification_preferences"("p_hotel_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_row public.notification_preferences%rowtype;
begin
  if v_user_id is null
     or not private.user_has_hotel_access(p_hotel_id)
  then
    raise exception 'Notification preference access denied.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Preference payload must be a JSON object.';
  end if;

  if p_payload ? 'event_overrides'
     and jsonb_typeof(p_payload -> 'event_overrides') <> 'object'
  then
    raise exception 'event_overrides must be a JSON object.';
  end if;

  insert into public.notification_preferences (
    hotel_id,
    user_id,
    in_app_enabled,
    email_enabled,
    manual_whatsapp_enabled,
    locale,
    quiet_hours_start,
    quiet_hours_end,
    event_overrides,
    created_at,
    updated_at
  ) values (
    p_hotel_id,
    v_user_id,
    coalesce((p_payload ->> 'in_app_enabled')::boolean, true),
    coalesce((p_payload ->> 'email_enabled')::boolean, false),
    coalesce((p_payload ->> 'manual_whatsapp_enabled')::boolean, false),
    coalesce(nullif(trim(p_payload ->> 'locale'), ''), 'en'),
    nullif(trim(p_payload ->> 'quiet_hours_start'), '')::time,
    nullif(trim(p_payload ->> 'quiet_hours_end'), '')::time,
    coalesce(p_payload -> 'event_overrides', '{}'::jsonb),
    now(),
    now()
  )
  on conflict (hotel_id, user_id) do update
  set
    in_app_enabled = excluded.in_app_enabled,
    email_enabled = excluded.email_enabled,
    manual_whatsapp_enabled = excluded.manual_whatsapp_enabled,
    locale = excluded.locale,
    quiet_hours_start = excluded.quiet_hours_start,
    quiet_hours_end = excluded.quiet_hours_end,
    event_overrides = excluded.event_overrides,
    updated_at = now()
  returning * into v_row;

  return to_jsonb(v_row);
end;
$$;


ALTER FUNCTION "public"."upsert_notification_preferences"("p_hotel_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_room"("h" "uuid", "room_id_value" "uuid", "room_number_value" "text", "floor_id_value" "uuid", "type_id_value" "uuid", "initial_status_value" "text", "metadata_value" "jsonb", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; row_value public.rooms%rowtype; cm jsonb; req text; nr text;
begin
  actor:=private.day13_require_room_manager(h);
  req:=nullif(trim(request_id_value),'');
  if req is null or length(req)<8 then raise exception 'A request ID of at least eight characters is required.'; end if;
  nr:=private.day13_normalize_room_number(room_number_value);
  if nr is null then raise exception 'Room number is required.'; end if;
  if initial_status_value is not null and initial_status_value not in ('available','cleaning','maintenance','out_of_order')
    then raise exception 'Room create/edit cannot directly set occupied status.'; end if;
  perform set_config('stayqr.day13_request_id',req,true);
  perform set_config('stayqr.day13_event_source','room_rpc',true);
  if room_id_value is null then
    insert into public.rooms(
      hotel_id,room_number,room_type_id,floor_id,status,is_active,updated_by,status_changed_by,metadata
    ) values(
      h,nr,type_id_value,floor_id_value,coalesce(initial_status_value,'available'),true,actor,actor,
      coalesce(metadata_value,'{}'::jsonb)||jsonb_build_object('create_request_id',req)
    ) returning * into row_value;
  else
    select * into row_value from public.rooms where hotel_id=h and id=room_id_value for update;
    if not found then raise exception 'Room was not found.'; end if;
    if not row_value.is_active then raise exception 'Archived room cannot be edited.'; end if;
    cm:=private.day13_room_commitments(h,room_id_value);
    if (floor_id_value is distinct from row_value.floor_id or type_id_value is distinct from row_value.room_type_id)
       and (((cm->>'active_stays')::int)>0 or ((cm->>'active_or_future_allocations')::int)>0)
    then raise exception 'Floor or room type cannot change while active/future commitments remain.'; end if;
    update public.rooms set room_number=nr,floor_id=floor_id_value,room_type_id=type_id_value,
      updated_by=actor,metadata=metadata||coalesce(metadata_value,'{}'::jsonb)||jsonb_build_object('update_request_id',req)
    where hotel_id=h and id=room_id_value returning * into row_value;
  end if;
  return jsonb_build_object('ok',true,'room',to_jsonb(row_value));
end;
$$;


ALTER FUNCTION "public"."upsert_room"("h" "uuid", "room_id_value" "uuid", "room_number_value" "text", "floor_id_value" "uuid", "type_id_value" "uuid", "initial_status_value" "text", "metadata_value" "jsonb", "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_room_type"("h" "uuid", "type_id_value" "uuid", "code_value" "text", "name_value" "text", "description_value" "text", "base_occupancy_value" integer, "max_adults_value" integer, "max_children_value" integer, "max_occupancy_value" integer, "base_rate_value" numeric, "extra_adult_rate_value" numeric, "extra_child_rate_value" numeric, "sort_order_value" integer, "active_value" boolean, "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; row_value public.room_types%rowtype; req text;
begin
  actor:=private.day13_require_room_manager(h);
  req:=nullif(trim(request_id_value),'');
  if req is null or length(req)<8 then raise exception 'A request ID of at least eight characters is required.'; end if;
  if coalesce(active_value,true)=false then raise exception 'Use archive_room_type to deactivate a room type.'; end if;
  if nullif(trim(code_value),'') is null or nullif(trim(name_value),'') is null then raise exception 'Room-type code and name are required.'; end if;
  if type_id_value is null then
    insert into public.room_types(
      hotel_id,name,code,description,base_occupancy,max_adults,max_children,max_occupancy,
      base_rate,extra_adult_rate,extra_child_rate,is_active,sort_order,created_by,updated_by,metadata
    ) values(
      h,trim(name_value),upper(trim(code_value)),nullif(trim(description_value),''),
      coalesce(base_occupancy_value,1),coalesce(max_adults_value,2),coalesce(max_children_value,1),
      coalesce(max_occupancy_value,3),coalesce(base_rate_value,0),coalesce(extra_adult_rate_value,0),
      coalesce(extra_child_rate_value,0),coalesce(active_value,true),coalesce(sort_order_value,0),
      actor,actor,jsonb_build_object('request_id',req)
    ) returning * into row_value;
  else
    update public.room_types set
      name=trim(name_value),code=upper(trim(code_value)),description=nullif(trim(description_value),''),
      base_occupancy=coalesce(base_occupancy_value,base_occupancy),
      max_adults=coalesce(max_adults_value,max_adults),max_children=coalesce(max_children_value,max_children),
      max_occupancy=coalesce(max_occupancy_value,max_occupancy),base_rate=coalesce(base_rate_value,base_rate),
      extra_adult_rate=coalesce(extra_adult_rate_value,extra_adult_rate),
      extra_child_rate=coalesce(extra_child_rate_value,extra_child_rate),
      sort_order=coalesce(sort_order_value,sort_order),is_active=coalesce(active_value,is_active),
      archived_at=case when coalesce(active_value,is_active) then null else archived_at end,
      archived_by=case when coalesce(active_value,is_active) then null else archived_by end,
      archive_reason=case when coalesce(active_value,is_active) then null else archive_reason end,
      updated_by=actor,metadata=metadata||jsonb_build_object('request_id',req)
    where hotel_id=h and id=type_id_value returning * into row_value;
    if row_value.id is null then raise exception 'Room type was not found.'; end if;
  end if;
  update public.rooms
  set room_type=row_value.name, updated_by=actor
  where hotel_id=h and room_type_id=row_value.id
    and room_type is distinct from row_value.name;

  return jsonb_build_object('ok',true,'room_type',to_jsonb(row_value));
end;
$$;


ALTER FUNCTION "public"."upsert_room_type"("h" "uuid", "type_id_value" "uuid", "code_value" "text", "name_value" "text", "description_value" "text", "base_occupancy_value" integer, "max_adults_value" integer, "max_children_value" integer, "max_occupancy_value" integer, "base_rate_value" numeric, "extra_adult_rate_value" numeric, "extra_child_rate_value" numeric, "sort_order_value" integer, "active_value" boolean, "request_id_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_tax_rate"("target_hotel_id" "uuid", "target_tax_rate_id" "uuid", "code_value" "text", "name_value" "text", "charge_category_value" "text", "hsn_sac_code_value" "text", "rate_percent_value" numeric, "cess_percent_value" numeric, "valid_from_value" "date", "valid_to_value" "date", "active_value" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  tax_rate_row public.tax_rates%rowtype;
  normalized_code text;
  normalized_name text;
begin
  if not private.user_has_any_permission(
    target_hotel_id,
    array[
      'invoices.manage',
      'checkout.manage'
    ]::text[]
  ) then
    raise exception 'Tax configuration access denied.';
  end if;

  normalized_code := upper(trim(coalesce(code_value, '')));
  normalized_name := trim(coalesce(name_value, ''));

  if normalized_code = ''
     or normalized_name = ''
  then
    raise exception 'Tax code and name are required.';
  end if;

  if charge_category_value not in (
    'room',
    'food',
    'service',
    'manual',
    'other'
  ) then
    raise exception 'Tax charge category is invalid.';
  end if;

  if rate_percent_value < 0
     or rate_percent_value > 100
     or coalesce(cess_percent_value, 0) < 0
     or coalesce(cess_percent_value, 0) > 100
  then
    raise exception 'Tax rates must be between 0 and 100.';
  end if;

  if valid_from_value is null
     or (
       valid_to_value is not null
       and valid_to_value < valid_from_value
     )
  then
    raise exception 'Tax validity period is invalid.';
  end if;

  if target_tax_rate_id is null then
    insert into public.tax_rates (
      hotel_id,
      code,
      name,
      charge_category,
      hsn_sac_code,
      rate_percent,
      cess_percent,
      valid_from,
      valid_to,
      is_active,
      created_by,
      updated_by
    )
    values (
      target_hotel_id,
      normalized_code,
      normalized_name,
      charge_category_value,
      nullif(trim(hsn_sac_code_value), ''),
      rate_percent_value,
      coalesce(cess_percent_value, 0),
      valid_from_value,
      valid_to_value,
      active_value,
      private.day11_valid_auth_actor(auth.uid()),
      private.day11_valid_auth_actor(auth.uid())
    )
    returning *
    into tax_rate_row;
  else
    update public.tax_rates
    set
      code = normalized_code,
      name = normalized_name,
      charge_category = charge_category_value,
      hsn_sac_code =
        nullif(trim(hsn_sac_code_value), ''),
      rate_percent = rate_percent_value,
      cess_percent =
        coalesce(cess_percent_value, 0),
      valid_from = valid_from_value,
      valid_to = valid_to_value,
      is_active = active_value,
      updated_by =
        private.day11_valid_auth_actor(auth.uid()),
      updated_at = now()
    where hotel_id = target_hotel_id
      and id = target_tax_rate_id
    returning *
    into tax_rate_row;

    if tax_rate_row.id is null then
      raise exception 'Tax rate was not found.';
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'tax_rate', to_jsonb(tax_rate_row)
  );
end;
$$;


ALTER FUNCTION "public"."upsert_tax_rate"("target_hotel_id" "uuid", "target_tax_rate_id" "uuid", "code_value" "text", "name_value" "text", "charge_category_value" "text", "hsn_sac_code_value" "text", "rate_percent_value" numeric, "cess_percent_value" numeric, "valid_from_value" "date", "valid_to_value" "date", "active_value" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_invoice"("verification_token_value" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  verification_row public.invoice_verifications%rowtype;
  invoice_row public.invoices%rowtype;
  hotel_name_value text;
  hash_valid boolean;
begin
  select verification.*
  into verification_row
  from public.invoice_verifications verification
  where verification.verification_token =
        verification_token_value
    and verification.status = 'active';

  if not found then
    return jsonb_build_object(
      'verified', false,
      'reason', 'verification_not_found'
    );
  end if;

  select invoice.*
  into invoice_row
  from public.invoices invoice
  where invoice.hotel_id =
        verification_row.hotel_id
    and invoice.id =
        verification_row.invoice_id;

  select hotel.hotel_name
  into hotel_name_value
  from public.hotels hotel
  where hotel.id =
        verification_row.hotel_id;

  hash_valid :=
    invoice_row.snapshot_hash =
      verification_row.snapshot_hash
    and invoice_row.snapshot_hash =
      private.day12_hash_snapshot(
        invoice_row.snapshot_json
      );

  update public.invoice_verifications
  set
    verified_count = verified_count + 1,
    last_verified_at = now()
  where id = verification_row.id;

  return jsonb_build_object(
    'verified', hash_valid,
    'invoice_number', invoice_row.invoice_number,
    'invoice_date', invoice_row.invoice_date,
    'financial_year',
      invoice_row.financial_year_label,
    'hotel_name', hotel_name_value,
    'invoice_status', invoice_row.invoice_status,
    'currency_code', invoice_row.currency_code,
    'seller_gstin', invoice_row.seller_gstin,
    'buyer_gstin', invoice_row.buyer_gstin,
    'place_of_supply',
      invoice_row.place_of_supply,
    'place_of_supply_code',
      invoice_row.place_of_supply_code,
    'tax_mode', invoice_row.tax_mode,
    'taxable_amount',
      invoice_row.taxable_amount,
    'tax_amount', invoice_row.tax_amount,
    'cgst_amount', invoice_row.cgst_amount,
    'sgst_amount', invoice_row.sgst_amount,
    'igst_amount', invoice_row.igst_amount,
    'cess_amount', invoice_row.cess_amount,
    'total_amount', invoice_row.total_amount,
    'snapshot_hash', invoice_row.snapshot_hash,
    'finalized_at', invoice_row.finalized_at
  );
end;
$$;


ALTER FUNCTION "public"."verify_invoice"("verification_token_value" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."verify_invoice"("verification_token_value" "uuid") IS 'Public limited-data invoice verification endpoint. It never exposes the private buyer or line snapshot.';



CREATE OR REPLACE FUNCTION "public"."verify_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "verification_notes_value" "text", "request_id_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  request_key text;
  task_row public.maintenance_tasks%rowtype;
  room_row public.rooms%rowtype;
  block_row public.room_blocks%rowtype;
  verification_row public.maintenance_verifications%rowtype;
  housekeeping_result jsonb;
  housekeeping_task_id_value uuid;
  snapshot_value jsonb;
  previous_status_value text;
  commitments jsonb;
begin
  actor_id_value :=
    private.day13_require_maintenance_manager(
      target_hotel_id
    );

  request_key :=
    nullif(trim(request_id_value), '');

  if request_key is null
     or length(request_key) < 8
  then
    raise exception
      'A request ID of at least eight characters is required.';
  end if;

  select verification.*
  into verification_row
  from public.maintenance_verifications verification
  where verification.hotel_id = target_hotel_id
    and verification.request_id = request_key;

  if verification_row.id is not null then
    select task.*
    into task_row
    from public.maintenance_tasks task
    where task.hotel_id = target_hotel_id
      and task.id = target_task_id;

    select room.*
    into room_row
    from public.rooms room
    where room.hotel_id = target_hotel_id
      and room.id = task_row.room_id;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'task', to_jsonb(task_row),
      'room', to_jsonb(room_row),
      'verification',
        to_jsonb(verification_row)
    );
  end if;

  select task.*
  into task_row
  from public.maintenance_tasks task
  where task.hotel_id = target_hotel_id
    and task.id = target_task_id
  for update;

  if not found then
    raise exception 'Maintenance task was not found.';
  end if;

  if task_row.status <> 'resolved' then
    raise exception
      'Maintenance verification requires resolved status.';
  end if;

  select room.*
  into room_row
  from public.rooms room
  where room.hotel_id = target_hotel_id
    and room.id = task_row.room_id
  for update;

  if not found then
    raise exception 'Maintenance room was not found.';
  end if;

  if task_row.room_block_id is not null then
    select block_record.*
    into block_row
    from public.room_blocks block_record
    where block_record.hotel_id =
          target_hotel_id
      and block_record.id =
          task_row.room_block_id
    for update;

    if block_row.id is null then
      raise exception
        'Linked maintenance room block was not found.';
    end if;

    if block_row.status = 'active' then
      update public.room_blocks
      set
        status = 'released',
        released_at = now(),
        released_by = actor_id_value,
        release_reason =
          coalesce(
            nullif(
              trim(verification_notes_value),
              ''
            ),
            'Maintenance verified'
          ),
        updated_by = actor_id_value
      where hotel_id = target_hotel_id
        and id = task_row.room_block_id
      returning *
      into block_row;

      perform private.day13_insert_maintenance_event(
        target_hotel_id,
        target_task_id,
        'room_block_released',
        task_row.status,
        task_row.status,
        actor_id_value,
        request_key || ':block',
        jsonb_build_object(
          'room_block_id', block_row.id,
          'release_reason',
            block_row.release_reason
        )
      );
    end if;
  end if;

  if task_row.inventory_impact <> 'none' then
    if task_row.requires_cleaning then
      perform public.transition_room_status(
        target_hotel_id,
        task_row.room_id,
        'cleaning',
        'Maintenance verified; housekeeping required',
        'maintenance',
        request_key || ':room-cleaning'
      );

      select task.id
      into housekeeping_task_id_value
      from public.housekeeping_tasks task
      where task.hotel_id = target_hotel_id
        and task.room_id = task_row.room_id
        and task.task_type = 'room_cleaning'
        and task.status in (
          'pending',
          'assigned',
          'in_progress',
          'cleaning_complete',
          'inspection_failed',
          'inspected'
        )
      order by task.created_at desc
      limit 1;

      if housekeeping_task_id_value is null then
        housekeeping_result :=
          public.create_housekeeping_task(
            target_hotel_id,
            task_row.room_id,
            'room_cleaning',
            case
              when task_row.severity in (
                'critical',
                'high'
              ) then 'high'
              else 'normal'
            end,
            now() + interval '2 hours',
            'Cleaning after maintenance: '
              || task_row.task_number,
            'maintenance',
            null,
            request_key || ':housekeeping'
          );

        housekeeping_task_id_value :=
          (
            housekeeping_result
            #>> '{task,id}'
          )::uuid;
      end if;

      perform private.day13_insert_maintenance_event(
        target_hotel_id,
        target_task_id,
        'housekeeping_handoff',
        task_row.status,
        task_row.status,
        actor_id_value,
        request_key || ':housekeeping-event',
        jsonb_build_object(
          'housekeeping_task_id',
          housekeeping_task_id_value
        )
      );
    else
      commitments :=
        private.day13_room_commitments(
          target_hotel_id,
          task_row.room_id
        );

      if (
        commitments
        ->> 'active_stays'
      )::integer > 0
      or (
        commitments
        ->> 'active_blocks'
      )::integer > 0
      or (
        commitments
        ->> 'pending_housekeeping'
      )::integer > 0
      then
        raise exception
          'Room cannot return to service while active stay, block or housekeeping work remains.';
      end if;

      perform public.transition_room_status(
        target_hotel_id,
        task_row.room_id,
        case
          when task_row.previous_room_status in (
            'available',
            'cleaning'
          ) then task_row.previous_room_status
          else 'available'
        end,
        'Maintenance verified',
        'maintenance',
        request_key || ':room-ready'
      );
    end if;
  end if;

  snapshot_value :=
    jsonb_build_object(
      'task_id', task_row.id,
      'task_number', task_row.task_number,
      'room_id', task_row.room_id,
      'room_number',
        room_row.room_number,
      'title', task_row.title,
      'category', task_row.category,
      'severity', task_row.severity,
      'inventory_impact',
        task_row.inventory_impact,
      'previous_room_status',
        task_row.previous_room_status,
      'room_block_id',
        task_row.room_block_id,
      'resolution_notes',
        task_row.resolution_notes,
      'requires_cleaning',
        task_row.requires_cleaning,
      'housekeeping_task_id',
        housekeeping_task_id_value,
      'verification_notes',
        nullif(
          trim(verification_notes_value),
          ''
        )
    );

  insert into public.maintenance_verifications (
    hotel_id,
    task_id,
    outcome,
    notes,
    verified_by,
    request_id,
    snapshot_json,
    snapshot_hash
  )
  values (
    target_hotel_id,
    target_task_id,
    'verified',
    nullif(
      trim(verification_notes_value),
      ''
    ),
    actor_id_value,
    request_key,
    snapshot_value,
    private.day13_hash_json(
      snapshot_value
    )
  )
  returning *
  into verification_row;

  previous_status_value := task_row.status;

  update public.maintenance_tasks
  set
    status = 'verified',
    verified_at = now(),
    verified_by = actor_id_value,
    verification_notes =
      nullif(
        trim(verification_notes_value),
        ''
      ),
    housekeeping_task_id =
      housekeeping_task_id_value,
    updated_by = actor_id_value,
    metadata =
      metadata
      || jsonb_build_object(
        'verification_request_id',
        request_key,
        'verification_id',
        verification_row.id
      )
  where hotel_id = target_hotel_id
    and id = target_task_id
  returning *
  into task_row;

  select room.*
  into room_row
  from public.rooms room
  where room.hotel_id = target_hotel_id
    and room.id = task_row.room_id;

  perform private.day13_insert_maintenance_event(
    target_hotel_id,
    target_task_id,
    'verified',
    previous_status_value,
    task_row.status,
    actor_id_value,
    request_key,
    jsonb_build_object(
      'verification_id',
        verification_row.id,
      'snapshot_hash',
        verification_row.snapshot_hash,
      'room_status',
        room_row.status,
      'housekeeping_task_id',
        housekeeping_task_id_value
    )
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'task', to_jsonb(task_row),
    'room', to_jsonb(room_row),
    'room_block',
      case
        when block_row.id is null
          then null
        else to_jsonb(block_row)
      end,
    'verification',
      to_jsonb(verification_row),
    'housekeeping_task_id',
      housekeeping_task_id_value
  );
end;
$$;


ALTER FUNCTION "public"."verify_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "verification_notes_value" "text", "request_id_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."verify_maintenance_task"("target_hotel_id" "uuid", "target_task_id" "uuid", "verification_notes_value" "text", "request_id_value" "text") IS 'Releases maintenance room block and either creates a housekeeping handoff or safely restores room service.';



CREATE OR REPLACE FUNCTION "public"."void_folio_credit_note"("target_hotel_id" "uuid", "target_credit_note_id" "uuid", "void_reason_value" "text", "request_id_value" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id_value uuid;
  credit_row public.credit_notes%rowtype;
  request_key text;
begin
  if not private.user_has_any_permission(target_hotel_id,array['payments.manage','checkout.manage','invoices.manage']::text[]) then
    raise exception 'Credit note void access denied.';
  end if;
  actor_id_value := private.day11_require_current_actor();
  if nullif(trim(void_reason_value),'') is null then raise exception 'Credit note void reason is required.'; end if;
  request_key := coalesce(nullif(trim(request_id_value),''),gen_random_uuid()::text);

  select credit.* into credit_row
  from public.credit_notes credit
  where credit.hotel_id = target_hotel_id and credit.id = target_credit_note_id
  for update;
  if not found then raise exception 'Credit note was not found.'; end if;
  if credit_row.status = 'voided' then return jsonb_build_object('ok',true,'idempotent',true,'request_id',request_key,'credit_note',to_jsonb(credit_row)); end if;
  if credit_row.status <> 'issued' then raise exception 'Only issued credit note can be voided.'; end if;

  update public.credit_notes
  set status = 'voided',voided_at = now(),voided_by = actor_id_value,
      void_reason = trim(void_reason_value),metadata = metadata || jsonb_build_object('void_request_id',request_key)
  where hotel_id = target_hotel_id and id = target_credit_note_id
  returning * into credit_row;

  perform private.write_folio_event(target_hotel_id,credit_row.folio_id,'folio.credit_note.voided','credit_note',credit_row.id,to_jsonb(credit_row),jsonb_build_object('request_id',request_key,'day',11));
  return jsonb_build_object('ok',true,'idempotent',false,'request_id',request_key,'credit_note',to_jsonb(credit_row));
end;
$$;


