    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reservations_amounts_nonnegative" CHECK ((("room_subtotal" >= (0)::numeric) AND ("tax_amount" >= (0)::numeric) AND ("discount_amount" >= (0)::numeric) AND ("total_amount" >= (0)::numeric) AND ("deposit_required" >= (0)::numeric) AND ("deposit_collected" >= (0)::numeric))),
    CONSTRAINT "reservations_booking_source_check" CHECK (("booking_source" = ANY (ARRAY['walk_in'::"text", 'phone'::"text", 'website'::"text", 'ota_manual'::"text", 'travel_agent'::"text", 'corporate'::"text", 'repeat_guest'::"text", 'other'::"text"]))),
    CONSTRAINT "reservations_cancelled_metadata_check" CHECK ((("status" <> 'cancelled'::"text") OR ("cancelled_at" IS NOT NULL))),
    CONSTRAINT "reservations_currency_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "reservations_dates_check" CHECK (("departure_date" > "arrival_date")),
    CONSTRAINT "reservations_guest_count_check" CHECK ((("adults" >= 1) AND ("children" >= 0))),
    CONSTRAINT "reservations_no_show_metadata_check" CHECK ((("status" <> 'no_show'::"text") OR ("no_show_at" IS NOT NULL))),
    CONSTRAINT "reservations_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'tentative'::"text", 'confirmed'::"text", 'checked_in'::"text", 'checked_out'::"text", 'cancelled'::"text", 'no_show'::"text"]))),
    CONSTRAINT "reservations_total_check" CHECK (("total_amount" = GREATEST((("room_subtotal" + "tax_amount") - "discount_amount"), (0)::numeric)))
);
