    CONSTRAINT "service_request_types_charge_enabled_check" CHECK (((NOT "charge_enabled") OR ("default_charge_amount" > (0)::numeric))),
    CONSTRAINT "service_request_types_charge_policy_check" CHECK (("charge_posting_policy" = ANY (ARRAY['manual'::"text", 'on_completion'::"text"]))),
