    CONSTRAINT "service_request_types_escalation_check" CHECK ((("escalation_minutes" >= 1) AND ("escalation_minutes" <= 1440))),
    CONSTRAINT "service_request_types_estimate_check" CHECK ((("default_estimated_minutes" IS NULL) OR (("default_estimated_minutes" >= 0) AND ("default_estimated_minutes" <= 1440)))),
    CONSTRAINT "service_request_types_name_not_blank" CHECK (("length"(TRIM(BOTH FROM "name")) > 0)),
    CONSTRAINT "service_request_types_notification_object_check" CHECK (("jsonb_typeof"("notification_template") = 'object'::"text")),
    CONSTRAINT "service_request_types_priority_check" CHECK (("default_priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "service_request_types_sla_check" CHECK ((("sla_minutes" >= 1) AND ("sla_minutes" <= 1440)))
);


ALTER TABLE "public"."service_request_types" OWNER TO "postgres";


COMMENT ON COLUMN "public"."service_request_types"."charge_enabled" IS 'Explicit hotel configuration gate. Existing service requests are never chargeable while false.';



COMMENT ON COLUMN "public"."service_request_types"."default_charge_amount" IS 'Configured service folio charge. No amount is inferred from request completion.';



COMMENT ON COLUMN "public"."service_request_types"."charge_posting_policy" IS 'manual requires an explicit RPC call; on_completion posts only after the type is deliberately enabled.';



