CREATE TABLE IF NOT EXISTS "public"."usage_counters" (
    "hotel_id" "uuid" NOT NULL,
    "metric_key" "text" NOT NULL,
    "current_value" numeric DEFAULT 0 NOT NULL,
    "limit_value" numeric,
    "source" "text" DEFAULT 'database'::"text" NOT NULL,
    "captured_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "usage_counters_limit_check" CHECK ((("limit_value" IS NULL) OR ("limit_value" >= (0)::numeric))),
    CONSTRAINT "usage_counters_metadata_object" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "usage_counters_metric_not_blank" CHECK (("length"(TRIM(BOTH FROM "metric_key")) > 0)),
    CONSTRAINT "usage_counters_source_not_blank" CHECK (("length"(TRIM(BOTH FROM "source")) > 0)),
    CONSTRAINT "usage_counters_value_check" CHECK (("current_value" >= (0)::numeric))
);


ALTER TABLE "public"."usage_counters" OWNER TO "postgres";


