    "request_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "result_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
