);


ALTER TABLE "public"."walkin_checkin_events" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."webhook_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider" "text" NOT NULL,
    "provider_event_id" "text" NOT NULL,
    "event_type" "text" NOT NULL,
    "processing_status" "text" DEFAULT 'received'::"text" NOT NULL,
    "signature_valid" boolean DEFAULT false NOT NULL,
    "payload_hash" "text",
    "payload" "jsonb" NOT NULL,
    "headers" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "processing_started_at" timestamp with time zone,
    "processed_at" timestamp with time zone,
    "next_retry_at" timestamp with time zone,
    "subscription_id" "uuid",
    "hotel_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "webhook_events_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "webhook_events_headers_object" CHECK (("jsonb_typeof"("headers") = 'object'::"text")),
    CONSTRAINT "webhook_events_metadata_object" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "webhook_events_payload_object" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "webhook_events_provider_event_not_blank" CHECK (("length"(TRIM(BOTH FROM "provider_event_id")) > 0)),
    CONSTRAINT "webhook_events_provider_not_blank" CHECK (("length"(TRIM(BOTH FROM "provider")) > 0)),
    CONSTRAINT "webhook_events_status_check" CHECK (("processing_status" = ANY (ARRAY['received'::"text", 'processing'::"text", 'processed'::"text", 'ignored'::"text", 'failed'::"text"]))),
    CONSTRAINT "webhook_events_type_not_blank" CHECK (("length"(TRIM(BOTH FROM "event_type")) > 0))
);


ALTER TABLE "public"."webhook_events" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."whatsapp_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "hotel_id" "uuid",
    "event_key" "text" NOT NULL,
    "locale" "text" DEFAULT 'en'::"text" NOT NULL,
    "template_name" "text" NOT NULL,
    "body_template" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "whatsapp_templates_body_not_blank" CHECK (("length"(TRIM(BOTH FROM "body_template")) > 0)),
    CONSTRAINT "whatsapp_templates_locale_not_blank" CHECK ((("length"(TRIM(BOTH FROM "locale")) >= 2) AND ("length"(TRIM(BOTH FROM "locale")) <= 20))),
    CONSTRAINT "whatsapp_templates_name_not_blank" CHECK (("length"(TRIM(BOTH FROM "template_name")) > 0)),
    CONSTRAINT "whatsapp_templates_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."whatsapp_templates" OWNER TO "postgres";


